/* Side-index payload names are resolved beside the index, never against cwd. */
static void llms_relative_asset(char *path, size_t capacity, const char *index) {
    if (!path[0] || path[0]=='/') return;
    const char *slash=strrchr(index,'/'); if (!slash) return;
    size_t n=(size_t)(slash-index)+1, m=strlen(path);
    if (n+m>=capacity) { fprintf(stderr,"ds4: side-index payload path too long\n"); abort(); }
    memmove(path+n,path,m+1); memcpy(path,index,n);
}
