static int g_llms_guards = -1;
static int llms_guards_on(void) { if (g_llms_guards < 0) { const char *e = getenv("LLMS_DS4_GUARDS"); g_llms_guards = e && *e && *e != '0'; } return g_llms_guards; }
void llms_guard_fail(const char *what) {
    if (!llms_guards_on()) return;
    const char *dn = getenv("DS4_METAL_DENSE_SOURCE"), *mi = getenv("DS4_METAL_DSV4_MISC_SOURCE"), *mo = getenv("DS4_METAL_MOE_SOURCE"), *hc = getenv("DS4_METAL_DSV4_HC_SOURCE");
    fprintf(stderr, "llms GUARDS FATAL: %s -- sources: dense %s | misc %s | moe %s | hc %s. A switch that is set cannot run as set; exiting 3 "
                    "(LLMS_DS4_GUARDS=0 runs on with it off)\n", what, dn ? dn : "(built-in)", mi ? mi : "(built-in)", mo ? mo : "(built-in)", hc ? hc : "(built-in)");
    fflush(stderr); exit(3);
}
int llms_strict_after(int printed, const char *what) { llms_guard_fail(what); return printed; }
static struct { const char *key; const char *kind; int hit; } g_llms_gsk[128]; static int g_llms_gsk_n; static volatile int g_llms_gsk_lk; static uint64_t g_llms_gsk_calls;
static const char *llms_gsk_kind(const char *src) {
    static const char *const nm[6] = {"DS4_METAL_DENSE_SOURCE", "DS4_METAL_DSV4_MISC_SOURCE", "DS4_METAL_MOE_SOURCE", "DS4_METAL_DSV4_HC_SOURCE", "DS4_METAL_NORM_SOURCE", "DS4_METAL_DSV41_SOURCE"};
    static const char *const sh[6] = {"dense", "misc", "moe", "hc", "norm", "dsv41"};
    if (!src) return "unset";
    for (int i = 0; i < 6; i++) { const char *v = getenv(nm[i]); if (v && !strcmp(v, src)) return sh[i]; }
    return "other";
}
static void llms_gsk_report(void) {
    fprintf(stderr, "llms source-name decisions (features keyed on a source FILE NAME):");
    for (int i = 0; i < g_llms_gsk_n; i++) fprintf(stderr, " %s@%s=%s", g_llms_gsk[i].key, g_llms_gsk[i].kind, g_llms_gsk[i].hit ? "yes" : "NO");
    fprintf(stderr, " (%llu calls)\n", (unsigned long long)g_llms_gsk_calls);
}
const char *llms_srckey(const char *src, const char *key) {
    const char *r = src ? strstr(src, key) : NULL;
    if (!llms_guards_on()) return r;
    __atomic_fetch_add(&g_llms_gsk_calls, 1, __ATOMIC_RELAXED); const char *kind = llms_gsk_kind(src);
    while (__atomic_exchange_n(&g_llms_gsk_lk, 1, __ATOMIC_ACQUIRE)) { }
    int i = 0; for (; i < g_llms_gsk_n; i++) if (!strcmp(g_llms_gsk[i].key, key) && g_llms_gsk[i].kind == kind) break;
    if (i == g_llms_gsk_n && g_llms_gsk_n < 128) { g_llms_gsk[i].key = key; g_llms_gsk[i].kind = kind; g_llms_gsk[i].hit = r != NULL; if (!g_llms_gsk_n++) atexit(llms_gsk_report); }
    __atomic_store_n(&g_llms_gsk_lk, 0, __ATOMIC_RELEASE);
    return r;
}
