static void llms_gpu_noop_report(void) { fprintf(stderr, "llms gpu noop: %llu dispatches skipped\n", (unsigned long long)g_llms_gpu_noop_n); }
static inline id<MTLComputeCommandEncoder> llms_bar(id<MTLComputeCommandEncoder> e) {
    if (g_llms_gpu_noop < 0) { const char *v = getenv("LLMS_DS4_GPU_NOOP"); g_llms_gpu_noop = v && *v && *v != '0';
                               if (g_llms_gpu_noop) { fprintf(stderr, "llms: GPU NOOP -- every llms_bar dispatch skipped (output is garbage)\n"); atexit(llms_gpu_noop_report); } }
    if (g_llms_gpu_noop) { g_llms_gpu_noop_n++; return nil; }
    if (g_llms_enc_auto && e == g_batch_enc) {
        if (g_llms_conc_skip == 1) { g_llms_conc_skip = 2; g_llms_conc_skips++; }   /* only the op's FIRST dispatch goes without */
        else { [e memoryBarrierWithScope:MTLBarrierScopeBuffers]; g_llms_conc_bars++; }
    }
    return e;
}
