/* ---- Encoder timeline diagnostic (DS4_METAL_ENCODER_TIMELINE=<file>) ----
 * Gives every batch dispatch group its own compute pass with stage-boundary
 * GPU timestamps, so one decode token can be read as a per-kernel GPU
 * timeline (durations and the gaps between them) without ending command
 * buffers. Pass boundaries add a little serialization, so absolute numbers
 * are an upper bound; the anatomy is what this exists for. Off by default. */
#define DS4_TIMELINE_NAME_MAX 80
#define DS4_TIMELINE_SAMPLES_PER_BUFFER 4096
typedef struct {
    uintptr_t caller;
    uint32_t n_dispatch;
    uint32_t tg[3];
    uint32_t tpt[3];
    char kernel[DS4_TIMELINE_NAME_MAX];
    uint32_t phase, pos, rows; uint64_t inv;   /* llms TL_PHASE (apply_tl_phase.py) */
    uintptr_t enc;   /* apply_tl_bind.py: the encoder this record samples, so the hooks label their own record */
    uint32_t tlp_sb, tlp_slot; uint64_t tlp_gen; int tlp;   /* llms TL_POOL: the pool buffer, sample index and ring position of this record */
} ds4_timeline_rec;
uint32_t g_llms_tl_phase, g_llms_tl_pos, g_llms_tl_rows; uint64_t g_llms_tl_inv;   /* llms TL_PHASE: the owner's phase / position / rows at encoder creation */
void ds4_gpu_llms_tl_phase(uint32_t phase, uint32_t pos, uint32_t rows) { if (phase != g_llms_tl_phase) g_llms_tl_inv++; g_llms_tl_phase = phase; g_llms_tl_pos = pos; g_llms_tl_rows = rows; }
uint32_t ds4_gpu_llms_tl_phase_get(uint32_t *pos, uint32_t *rows) { if (pos) *pos = g_llms_tl_pos; if (rows) *rows = g_llms_tl_rows; return g_llms_tl_phase; }

@interface DS4TimelineBatch : NSObject {
@public
    NSMutableArray<id<MTLCounterSampleBuffer>> *samples;
    ds4_timeline_rec *recs;
    uint32_t count;
    uint32_t cap;
    uint64_t seq;
    __unsafe_unretained id<MTLCommandBuffer> cb;
}
@end
@implementation DS4TimelineBatch
- (void)dealloc { free(recs); }
@end

static BOOL g_timeline_enabled;
static FILE *g_timeline_file;
static pthread_mutex_t g_timeline_mutex = PTHREAD_MUTEX_INITIALIZER;
static DS4TimelineBatch *g_timeline_batch;
static uint64_t g_timeline_seq;
static NSMutableDictionary<NSNumber *, NSString *> *g_timeline_pso_names;
static id<MTLCounterSet> g_timeline_counter_set;


#define LLMS_TLP_N 24u
#define LLMS_TLP_PER (DS4_TIMELINE_SAMPLES_PER_BUFFER / 2u)
#define LLMS_TLP_SLOTS (LLMS_TLP_N * LLMS_TLP_PER)
static id<MTLCounterSampleBuffer> g_llms_tlp_sb[LLMS_TLP_N]; static int g_llms_tlp_on = -1; static uint64_t g_llms_tlp_next, g_llms_tlp_stale;
static int llms_tlp(void) {
    if (g_llms_tlp_on < 0) {
        const char *e = getenv("LLMS_DS4_TL_POOL"); g_llms_tlp_on = e && *e && *e != '0';
        if (g_llms_tlp_on) {
            for (uint32_t i = 0; i < LLMS_TLP_N; i++) {
                MTLCounterSampleBufferDescriptor *d = [MTLCounterSampleBufferDescriptor new];
                d.counterSet = g_timeline_counter_set; d.storageMode = MTLStorageModeShared; d.sampleCount = DS4_TIMELINE_SAMPLES_PER_BUFFER;
                NSError *error = nil; g_llms_tlp_sb[i] = [g_device newCounterSampleBufferWithDescriptor:d error:&error];
                if (!g_llms_tlp_sb[i]) { fprintf(stderr, "llms tl pool: buffer %u failed: %s -- pool off\n", i, [[error localizedDescription] UTF8String]); g_llms_tlp_on = 0; break; }
            }
            if (g_llms_tlp_on) { fprintf(stderr, "llms: tl pool (%u counter sample buffers, %u encoder slots in a ring)\n", LLMS_TLP_N, LLMS_TLP_SLOTS);
                atexit_b(^{ fprintf(stderr, "llms tl pool: %llu slots taken, %llu records stale at resolve\n", (unsigned long long)g_llms_tlp_next, (unsigned long long)g_llms_tlp_stale); }); }
        }
    }
    return g_llms_tlp_on;
}
static BOOL g_timeline_encoder_hooked;

static void ds4_gpu_timeline_note_pso_name(id pso, NSString *name) {
    { static int llms_pi = -1; if (llms_pi < 0) { const char *e = getenv("LLMS_DS4_PIPE_INFO"); llms_pi = e && *e && *e != '0'; }   /* llms PIPE_INFO (apply_ds4_pipe_info.py) */
      if (llms_pi && pso && name) { id<MTLComputePipelineState> p_ = (id<MTLComputePipelineState>)pso;
          fprintf(stderr, "llms pipe: %s max_threads %lu width %lu static_tg_mem %lu\n", [name UTF8String], (unsigned long)[p_ maxTotalThreadsPerThreadgroup],
                  (unsigned long)[p_ threadExecutionWidth], (unsigned long)[p_ staticThreadgroupMemoryLength]); } }
    if (!g_timeline_enabled || !pso || !name) return;
    pthread_mutex_lock(&g_timeline_mutex);
    if (!g_timeline_pso_names) g_timeline_pso_names = [NSMutableDictionary dictionary];
    g_timeline_pso_names[@((uintptr_t)pso)] = name;
    pthread_mutex_unlock(&g_timeline_mutex);
}

@interface NSObject (DS4TimelineSwizzle)
- (id)ds4_tl_newComputePipelineStateWithFunction:(id<MTLFunction>)fn
                                            error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (id)ds4_tl_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)descriptor
                                            options:(MTLPipelineOption)options
                                         reflection:(MTLAutoreleasedComputePipelineReflection *)reflection
                                              error:(NSError * __autoreleasing *)error NS_RETURNS_RETAINED;
- (void)ds4_tl_setComputePipelineState:(id<MTLComputePipelineState>)pso;
- (void)ds4_tl_dispatchThreadgroups:(MTLSize)tg threadsPerThreadgroup:(MTLSize)tpt;
- (void)ds4_tl_dispatchThreads:(MTLSize)threads threadsPerThreadgroup:(MTLSize)tpt;
@end

static ds4_timeline_rec *ds4_gpu_timeline_current_rec(void) {
    DS4TimelineBatch *b = g_timeline_batch;
    if (!b || b->count == 0) return NULL;
    return &b->recs[b->count - 1];
}
/* apply_tl_bind.py: the record of THIS encoder (the newest whose enc matches, scanning back up to 64); NULL when none matches (21:0x: no fallback) */
static ds4_timeline_rec *ds4_gpu_timeline_rec_for(id self_enc) {
    DS4TimelineBatch *b = g_timeline_batch;
    if (!b || b->count == 0) return NULL;
    const uintptr_t key = (uintptr_t)self_enc; const uint32_t n = b->count;
    for (uint32_t i = 0; i < 64u && i < n; i++) { ds4_timeline_rec *r = &b->recs[n - 1u - i]; if (r->enc == key) return r; }
    return NULL;   /* an encoder without a record of its own (keepbusy's, or one made outside the timeline) labels nothing: its dispatches were never sampled */
}

@implementation NSObject (DS4TimelineSwizzle)
- (id)ds4_tl_newComputePipelineStateWithFunction:(id<MTLFunction>)fn
                                            error:(NSError * __autoreleasing *)error {
    id pso = [self ds4_tl_newComputePipelineStateWithFunction:fn error:error];
    ds4_gpu_timeline_note_pso_name(pso, [fn name]);
    return pso;
}
- (id)ds4_tl_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)descriptor
                                            options:(MTLPipelineOption)options
                                         reflection:(MTLAutoreleasedComputePipelineReflection *)reflection
                                              error:(NSError * __autoreleasing *)error {
    id pso = [self ds4_tl_newComputePipelineStateWithDescriptor:descriptor
                                                        options:options
                                                     reflection:reflection
                                                          error:error];
    ds4_gpu_timeline_note_pso_name(pso, [[descriptor computeFunction] name]);
    return pso;
}
- (void)ds4_tl_setComputePipelineState:(id<MTLComputePipelineState>)pso {
    [self ds4_tl_setComputePipelineState:pso];
    ds4_timeline_rec *rec = ds4_gpu_timeline_rec_for(self);   /* apply_tl_bind.py */
    if (!rec) return;
    NSString *name = nil;
    pthread_mutex_lock(&g_timeline_mutex);
    if (g_timeline_pso_names) name = g_timeline_pso_names[@((uintptr_t)pso)];
    pthread_mutex_unlock(&g_timeline_mutex);
    const char *cname = name ? [name UTF8String] : "?";
    if (rec->kernel[0] == '\0') {
        snprintf(rec->kernel, sizeof(rec->kernel), "%s", cname);
    } else if (strstr(rec->kernel, cname) == NULL) {
        size_t used = strlen(rec->kernel);
        if (used + 1 < sizeof(rec->kernel))
            snprintf(rec->kernel + used, sizeof(rec->kernel) - used, "+%s", cname);
    }
}
- (void)ds4_tl_dispatchThreadgroups:(MTLSize)tg threadsPerThreadgroup:(MTLSize)tpt {
    [self ds4_tl_dispatchThreadgroups:tg threadsPerThreadgroup:tpt];
    ds4_timeline_rec *rec = ds4_gpu_timeline_rec_for(self);   /* apply_tl_bind.py */
    if (!rec) return;
    if (rec->n_dispatch == 0) {
        rec->tg[0] = (uint32_t)tg.width; rec->tg[1] = (uint32_t)tg.height; rec->tg[2] = (uint32_t)tg.depth;
        rec->tpt[0] = (uint32_t)tpt.width; rec->tpt[1] = (uint32_t)tpt.height; rec->tpt[2] = (uint32_t)tpt.depth;
    }
    rec->n_dispatch++;
}
- (void)ds4_tl_dispatchThreads:(MTLSize)threads threadsPerThreadgroup:(MTLSize)tpt {
    [self ds4_tl_dispatchThreads:threads threadsPerThreadgroup:tpt];
    ds4_timeline_rec *rec = ds4_gpu_timeline_rec_for(self);   /* apply_tl_bind.py */
    if (!rec) return;
    if (rec->n_dispatch == 0) {
        rec->tg[0] = (uint32_t)((threads.width + tpt.width - 1) / (tpt.width ? tpt.width : 1));
        rec->tg[1] = (uint32_t)((threads.height + tpt.height - 1) / (tpt.height ? tpt.height : 1));
        rec->tg[2] = (uint32_t)((threads.depth + tpt.depth - 1) / (tpt.depth ? tpt.depth : 1));
        rec->tpt[0] = (uint32_t)tpt.width; rec->tpt[1] = (uint32_t)tpt.height; rec->tpt[2] = (uint32_t)tpt.depth;
    }
    rec->n_dispatch++;
}
@end


static uint64_t g_llms_su_t0;
__attribute__((constructor)) static void llms_su_ctor(void) { g_llms_su_t0 = clock_gettime_nsec_np(CLOCK_UPTIME_RAW); }
void ds4_gpu_llms_startup_mark(const char *label) {
    static int on = -1; if (on < 0) { const char *e = getenv("LLMS_DS4_STARTUP_LOG"); on = e && *e && *e != '0'; }
    if (!on || !label) return;
    static const char *seen[96]; static int nseen; static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mu); for (int i = 0; i < nseen; i++) if (seen[i] == label) { pthread_mutex_unlock(&mu); return; }
    if (nseen < 96) seen[nseen++] = label; pthread_mutex_unlock(&mu);
    fprintf(stderr, "llms startup: %8.1f ms %s (%s thread)\n", (double)(clock_gettime_nsec_np(CLOCK_UPTIME_RAW) - g_llms_su_t0) * 1e-6, label, pthread_main_np() ? "main" : "other");
}

static double g_llms_pc_ms, g_llms_pc_fms, g_llms_pc_phms[4]; static uint64_t g_llms_pc_n, g_llms_pc_fn, g_llms_pc_phn[4];
static pthread_mutex_t g_llms_pc_mu = PTHREAD_MUTEX_INITIALIZER;
static uint32_t llms_pc_phase(void);
double ds4_gpu_llms_pipe_ms(void) { pthread_mutex_lock(&g_llms_pc_mu); const double v = g_llms_pc_ms + g_llms_pc_fms; pthread_mutex_unlock(&g_llms_pc_mu); return v; }
static double llms_pc_now(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec * 1e3 + ts.tv_nsec / 1e6; }
static void llms_pc_note(int is_fn, double ms, NSString *name) {
    const uint32_t ph = llms_pc_phase() & 3u;
    pthread_mutex_lock(&g_llms_pc_mu);
    if (is_fn) { g_llms_pc_fms += ms; g_llms_pc_fn++; } else { g_llms_pc_ms += ms; g_llms_pc_n++; }
    g_llms_pc_phms[ph] += ms; g_llms_pc_phn[ph]++;
    pthread_mutex_unlock(&g_llms_pc_mu);
    if (ms > 5.0) fprintf(stderr, "llms pipe slow: %s %s %.1f ms phase %u\n", is_fn ? "function" : "pipeline", name ? [name UTF8String] : "?", ms, ph);
}
