@end
@implementation NSObject (LLMSPipeCensus)
- (id)llms_pc_newComputePipelineStateWithFunction:(id<MTLFunction>)fn error:(NSError * __autoreleasing *)error {
    const double t0 = llms_pc_now(); id p = [self llms_pc_newComputePipelineStateWithFunction:fn error:error]; llms_pc_note(0, llms_pc_now() - t0, [fn name]); return p; }
- (id)llms_pc_newComputePipelineStateWithDescriptor:(MTLComputePipelineDescriptor *)d options:(MTLPipelineOption)o reflection:(MTLAutoreleasedComputePipelineReflection *)r error:(NSError * __autoreleasing *)error {
    const double t0 = llms_pc_now(); id p = [self llms_pc_newComputePipelineStateWithDescriptor:d options:o reflection:r error:error]; llms_pc_note(0, llms_pc_now() - t0, [[d computeFunction] name]); return p; }
- (id)llms_pc_newFunctionWithName:(NSString *)name {
    const double t0 = llms_pc_now(); id f = [self llms_pc_newFunctionWithName:name]; llms_pc_note(1, llms_pc_now() - t0, name); return f; }
- (id)llms_pc_newFunctionWithName:(NSString *)name constantValues:(MTLFunctionConstantValues *)cv error:(NSError * __autoreleasing *)error {
    const double t0 = llms_pc_now(); id f = [self llms_pc_newFunctionWithName:name constantValues:cv error:error]; llms_pc_note(1, llms_pc_now() - t0, name); return f; }
@end
static void ds4_gpu_timeline_swizzle(Class cls, SEL orig, SEL repl) {
    Method m_orig = class_getInstanceMethod(cls, orig);
    Method m_repl = class_getInstanceMethod(cls, repl);
    if (!m_orig || !m_repl) {
        fprintf(stderr, "ds4: timeline hook missing for %s\n", sel_getName(orig));
        return;
    }
    if (class_addMethod(cls, orig, method_getImplementation(m_repl),
                        method_getTypeEncoding(m_orig))) {
        class_replaceMethod(cls, repl, method_getImplementation(m_orig),
                            method_getTypeEncoding(m_orig));
    } else {
        method_exchangeImplementations(m_orig, m_repl);
    }
}

/* Called once the device exists: opens the log and hooks pipeline creation so
 * every pipeline made afterwards has a kernel name. */
static void ds4_gpu_timeline_probe(id<MTLDevice> device) {
    static int probed;
    if (probed) return;
    probed = 1;
    const char *path = getenv("DS4_METAL_ENCODER_TIMELINE");
    if (!path || !path[0] || !device) return;
    g_timeline_file = fopen(path, "a");
    if (!g_timeline_file) {
        fprintf(stderr, "ds4: cannot open encoder timeline %s\n", path);
        return;
    }
    for (id<MTLCounterSet> cs in [device counterSets]) {
        if ([[cs name] isEqualToString:MTLCommonCounterSetTimestamp]) g_timeline_counter_set = cs;
    }
    if (!g_timeline_counter_set ||
        ![device supportsCounterSampling:MTLCounterSamplingPointAtStageBoundary]) {
        fprintf(stderr, "ds4: encoder timeline unsupported on this device\n");
        fclose(g_timeline_file);
        g_timeline_file = NULL;
        return;
    }
    g_timeline_enabled = YES;
    Class dev_cls = object_getClass(device);
    ds4_gpu_timeline_swizzle(dev_cls,
        @selector(newComputePipelineStateWithFunction:error:),
        @selector(ds4_tl_newComputePipelineStateWithFunction:error:));
    ds4_gpu_timeline_swizzle(dev_cls,
        @selector(newComputePipelineStateWithDescriptor:options:reflection:error:),
        @selector(ds4_tl_newComputePipelineStateWithDescriptor:options:reflection:error:));
    fprintf(g_timeline_file, "# ds4 encoder timeline; slide=0x%llx pid=%d\n",
            (unsigned long long)_dyld_get_image_vmaddr_slide(0), (int)getpid());
    fprintf(g_timeline_file, "# B <seq> <n_encoders> <gpu_start_ns> <gpu_end_ns>\n");
    fprintf(g_timeline_file, "# E <seq> <idx> <start_ns> <end_ns> <dur_us> <gap_us> <caller_unslid> <n_dispatch> <tg> <tpt> <kernel>\n");
    fflush(g_timeline_file);
    fprintf(stderr, "ds4: encoder timeline -> %s\n", path);
}



static __thread __unsafe_unretained id<MTLComputePipelineState> g_llms_tgc_pso;
static uint64_t g_llms_tgc_seen, g_llms_tgc_clamped;
static MTLSize llms_tgc_fit(MTLSize s) {
    __atomic_fetch_add(&g_llms_tgc_seen, 1, __ATOMIC_RELAXED);
    id<MTLComputePipelineState> p = g_llms_tgc_pso; if (!p) return s;
    const NSUInteger mx = p.maxTotalThreadsPerThreadgroup;
    if (s.width * s.height * s.depth <= mx) return s;
    __atomic_fetch_add(&g_llms_tgc_clamped, 1, __ATOMIC_RELAXED);
    { static char seen[32][64]; static int ns; static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER; NSString *nm = nil; if (g_timeline_pso_names) { pthread_mutex_lock(&g_timeline_mutex); nm = g_timeline_pso_names[@((uintptr_t)p)]; pthread_mutex_unlock(&g_timeline_mutex); }   /* names exist with DS4_METAL_ENCODER_TIMELINE set */
      char pb[40]; snprintf(pb, sizeof pb, "(pso %p)", (__bridge void *)p); const char *lb = nm ? nm.UTF8String : pb;   /* name every clamped pipeline once: its outputs are suspect, and so is any OOB report downstream of it */
      pthread_mutex_lock(&mu); int k = 0; for (; k < ns; k++) if (!strncmp(seen[k], lb, 63)) break;
      if (k == ns && ns < 32) { snprintf(seen[ns++], 64, "%s", lb); fprintf(stderr, "llms tg clamp: %s %lux%lux%lu -> max %lu\n", lb, (unsigned long)s.width, (unsigned long)s.height, (unsigned long)s.depth, (unsigned long)mx); }
      pthread_mutex_unlock(&mu); }
    while (s.width * s.height * s.depth > mx && s.width > 1) s.width = (s.width + 1) / 2;
    while (s.width * s.height * s.depth > mx && s.height > 1) s.height = (s.height + 1) / 2;
    while (s.width * s.height * s.depth > mx && s.depth > 1) s.depth = (s.depth + 1) / 2;
    return s;
}
@implementation NSObject (LLMSTGClamp)
- (void)llms_tgc_setComputePipelineState:(id<MTLComputePipelineState>)pso { g_llms_tgc_pso = pso; [self llms_tgc_setComputePipelineState:pso]; }
- (void)llms_tgc_dispatchThreadgroups:(MTLSize)tg threadsPerThreadgroup:(MTLSize)tpt { [self llms_tgc_dispatchThreadgroups:tg threadsPerThreadgroup:llms_tgc_fit(tpt)]; }
- (void)llms_tgc_dispatchThreads:(MTLSize)th threadsPerThreadgroup:(MTLSize)tpt { [self llms_tgc_dispatchThreads:th threadsPerThreadgroup:llms_tgc_fit(tpt)]; }
@end
/* llms VAL_CANARY (apply_tg_clamp.py): LLMS_DS4_VAL_CANARY=1 runs, once, a one-thread kernel that stores 4 floats past the end of a
   16-byte buffer -- the out-of-bounds access shader validation MUST report. Without it a clean validation run cannot be told from a
   validation layer that is not checking. Off unless set; touches nothing else. */
static void llms_val_canary(void) {
    static int done; if (done) return; done = 1;
    const char *e = getenv("LLMS_DS4_VAL_CANARY"); if (!(e && *e && *e != '0') || !g_device || !g_queue) return;
    NSError *err = nil;
    id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nkernel void llms_val_canary(device float *b [[buffer(0)]], uint i [[thread_position_in_grid]]) { b[i + 4u] = 1.0f; }\n" options:nil error:&err];
    id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_val_canary"] : nil;
    id<MTLComputePipelineState> ps = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
    id<MTLBuffer> b = [g_device newBufferWithLength:16 options:MTLResourceStorageModeShared];
    if (!ps || !b) { fprintf(stderr, "llms val canary: could not build (%s)\n", err ? err.localizedDescription.UTF8String : "?"); return; }
    id<MTLCommandBuffer> cb = [g_queue commandBuffer]; id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
    [enc setComputePipelineState:ps]; [enc setBuffer:b offset:0 atIndex:0]; [enc dispatchThreads:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)]; [enc endEncoding];
    [cb commit]; [cb waitUntilCompleted];
    fprintf(stderr, "llms val canary: an out-of-bounds store at byte 16 of a 16-byte buffer was dispatched; command buffer status %ld error %s\n", (long)cb.status, cb.error ? cb.error.localizedDescription.UTF8String : "(none)");
}
static id<MTLComputeCommandEncoder> llms_tgc_hook(id<MTLComputeCommandEncoder> enc) {
    static int on = -1; static Class hooked; static int nh, warned;   /* ONE class: the swizzle exchanges with NSObject's category method, so a second class would call the first class's original (the timeline hooks one class for the same reason) */
    if (on < 0) { const char *e = getenv("LLMS_DS4_TG_CLAMP"); on = e && *e && *e != '0';
                  if (on) { fprintf(stderr, "llms: TG_CLAMP -- every dispatch clamped to its pipeline's maxTotalThreadsPerThreadgroup (a validation aid: full-width kernels compute garbage)\n");
                            atexit_b(^{ fprintf(stderr, "llms tg clamp: %llu dispatches seen, %llu clamped, %d encoder classes hooked\n", (unsigned long long)g_llms_tgc_seen, (unsigned long long)g_llms_tgc_clamped, nh); }); } }
    llms_val_canary();
    if (!on || !enc) return enc;
    Class cls = object_getClass(enc);
    if (hooked == cls) return enc;
    if (hooked) { if (!warned) { warned = 1; fprintf(stderr, "llms tg clamp: SECOND encoder class %s NOT hooked (first %s): its dispatches are not clamped\n", class_getName(cls), class_getName(hooked)); } return enc; }
    hooked = cls; nh = 1; fprintf(stderr, "llms tg clamp: hooked encoder class %s\n", class_getName(cls));
    ds4_gpu_timeline_swizzle(cls, @selector(setComputePipelineState:), @selector(llms_tgc_setComputePipelineState:));
    ds4_gpu_timeline_swizzle(cls, @selector(dispatchThreadgroups:threadsPerThreadgroup:), @selector(llms_tgc_dispatchThreadgroups:threadsPerThreadgroup:));
    ds4_gpu_timeline_swizzle(cls, @selector(dispatchThreads:threadsPerThreadgroup:), @selector(llms_tgc_dispatchThreads:threadsPerThreadgroup:));
    return enc;
}
static void ds4_gpu_timeline_hook_encoder(id<MTLComputeCommandEncoder> enc) {
    if (g_timeline_encoder_hooked || !enc) return;
    g_timeline_encoder_hooked = YES;
    Class cls = object_getClass(enc);
    ds4_gpu_timeline_swizzle(cls, @selector(setComputePipelineState:),
                             @selector(ds4_tl_setComputePipelineState:));
    ds4_gpu_timeline_swizzle(cls, @selector(dispatchThreadgroups:threadsPerThreadgroup:),
                             @selector(ds4_tl_dispatchThreadgroups:threadsPerThreadgroup:));
    ds4_gpu_timeline_swizzle(cls, @selector(dispatchThreads:threadsPerThreadgroup:),
                             @selector(ds4_tl_dispatchThreads:threadsPerThreadgroup:));
}

static void ds4_gpu_timeline_resolve(DS4TimelineBatch *b, id<MTLCommandBuffer> cb) {
    if (!b || !g_timeline_file) return;
    pthread_mutex_lock(&g_timeline_mutex);
    fprintf(g_timeline_file, "B %llu %u %.0f %.0f\n", (unsigned long long)b->seq, b->count,
            cb.GPUStartTime * 1e9, cb.GPUEndTime * 1e9);
    uint64_t prev_end = 0;
    for (uint32_t i = 0; i < b->count; i++) {
        const uint32_t sb_index = i / (DS4_TIMELINE_SAMPLES_PER_BUFFER / 2);
        const uint32_t slot = (i % (DS4_TIMELINE_SAMPLES_PER_BUFFER / 2)) * 2u;
        uint64_t start = 0, end = 0;
        if (sb_index < [b->samples count]) {
            NSData *d = [b->samples[sb_index] resolveCounterRange:NSMakeRange(slot, 2)];
            if (d && [d length] >= 2 * sizeof(uint64_t)) {
                const uint64_t *ts = (const uint64_t *)[d bytes];
                start = ts[0];
                end = ts[1];
            }
        }
        if (b->recs[i].tlp) {   /* llms TL_POOL */
            const ds4_timeline_rec *q = &b->recs[i]; start = end = 0;
            if (__atomic_load_n(&g_llms_tlp_next, __ATOMIC_RELAXED) - q->tlp_gen < LLMS_TLP_SLOTS) {
                NSData *d = [g_llms_tlp_sb[q->tlp_sb] resolveCounterRange:NSMakeRange(q->tlp_slot, 2)];
                if (d && [d length] >= 2 * sizeof(uint64_t)) { const uint64_t *ts = (const uint64_t *)[d bytes]; start = ts[0]; end = ts[1]; }
                if (__atomic_load_n(&g_llms_tlp_next, __ATOMIC_RELAXED) - q->tlp_gen >= LLMS_TLP_SLOTS) { start = end = 0; g_llms_tlp_stale++; }
            } else g_llms_tlp_stale++;
        }
        const ds4_timeline_rec *r = &b->recs[i];
        const double dur_us = (end >= start) ? (double)(end - start) / 1000.0 : -1.0;
        const double gap_us = (prev_end && start >= prev_end) ? (double)(start - prev_end) / 1000.0 : 0.0;
        fprintf(g_timeline_file, "E %llu %u %llu %llu %.2f %.2f 0x%llx %u %ux%ux%u %ux%ux%u %s %u %u %u %llu\n",
                (unsigned long long)b->seq, i,
                (unsigned long long)start, (unsigned long long)end, dur_us, gap_us,
                (unsigned long long)(r->caller - (uintptr_t)_dyld_get_image_vmaddr_slide(0)),
                r->n_dispatch, r->tg[0], r->tg[1], r->tg[2], r->tpt[0], r->tpt[1], r->tpt[2],
                r->kernel[0] ? r->kernel : "?", r->phase, r->pos, r->rows, (unsigned long long)r->inv);   /* llms TL_PHASE: phase pos rows inv */
        if (end) prev_end = end;
    }
    fflush(g_timeline_file);
    pthread_mutex_unlock(&g_timeline_mutex);
}

/* Attach to a freshly created batch command buffer. */
static void ds4_gpu_timeline_attach(id<MTLCommandBuffer> cb) {
    if (!g_timeline_enabled || !cb) return;
    DS4TimelineBatch *b = [DS4TimelineBatch new];
    b->samples = [NSMutableArray array];
    b->cap = 1024;
    b->recs = calloc(b->cap, sizeof(ds4_timeline_rec));
    b->count = 0;
    b->seq = ++g_timeline_seq;
    b->cb = cb;
    g_timeline_batch = b;
    [cb addCompletedHandler:^(id<MTLCommandBuffer> done) {
        ds4_gpu_timeline_resolve(b, done);
    }];
}

static id<MTLComputeCommandEncoder> ds4_gpu_timeline_new_encoder(
        id<MTLCommandBuffer> cb, BOOL concurrent, uintptr_t caller) {
    DS4TimelineBatch *b = g_timeline_batch;
    if (!b) return nil;
    if (llms_tlp()) {   /* llms TL_POOL */
        if (b->count == b->cap) { b->cap *= 2; b->recs = realloc(b->recs, (size_t)b->cap * sizeof(ds4_timeline_rec)); }
        const uint64_t gen = __atomic_fetch_add(&g_llms_tlp_next, 1, __ATOMIC_RELAXED); const uint32_t ix = (uint32_t)(gen % LLMS_TLP_SLOTS);
        const uint32_t sbi = ix / LLMS_TLP_PER, slot = (ix % LLMS_TLP_PER) * 2u;
        MTLComputePassDescriptor *pd = [MTLComputePassDescriptor computePassDescriptor];
        pd.dispatchType = concurrent ? MTLDispatchTypeConcurrent : MTLDispatchTypeSerial;
        MTLComputePassSampleBufferAttachmentDescriptor *att = pd.sampleBufferAttachments[0];
        att.sampleBuffer = g_llms_tlp_sb[sbi]; att.startOfEncoderSampleIndex = slot; att.endOfEncoderSampleIndex = slot + 1u;
        id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoderWithDescriptor:pd];
        if (!enc) return nil;
        ds4_timeline_rec *rec = &b->recs[b->count++]; memset(rec, 0, sizeof(*rec));
        rec->phase = g_llms_tl_phase; rec->pos = g_llms_tl_pos; rec->rows = g_llms_tl_rows; rec->inv = g_llms_tl_inv;
        rec->caller = caller; rec->enc = (uintptr_t)enc; rec->tlp = 1; rec->tlp_sb = sbi; rec->tlp_slot = slot; rec->tlp_gen = gen;
        ds4_gpu_timeline_hook_encoder(enc);
        return enc;
    }
    const uint32_t per_buffer = DS4_TIMELINE_SAMPLES_PER_BUFFER / 2;
    const uint32_t sb_index = b->count / per_buffer;
    if (sb_index >= [b->samples count]) {
        MTLCounterSampleBufferDescriptor *d = [MTLCounterSampleBufferDescriptor new];
        d.counterSet = g_timeline_counter_set;
        d.storageMode = MTLStorageModeShared;
        d.sampleCount = DS4_TIMELINE_SAMPLES_PER_BUFFER;
        NSError *error = nil;
        id<MTLCounterSampleBuffer> sb = [g_device newCounterSampleBufferWithDescriptor:d error:&error];
        if (!sb) {
            fprintf(stderr, "ds4: timeline sample buffer failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return nil;
        }
        [b->samples addObject:sb];
    }
    if (b->count == b->cap) {
        b->cap *= 2;
        b->recs = realloc(b->recs, (size_t)b->cap * sizeof(ds4_timeline_rec));
    }
    const uint32_t slot = (b->count % per_buffer) * 2u;
    MTLComputePassDescriptor *pd = [MTLComputePassDescriptor computePassDescriptor];
    pd.dispatchType = concurrent ? MTLDispatchTypeConcurrent : MTLDispatchTypeSerial;
    MTLComputePassSampleBufferAttachmentDescriptor *att = pd.sampleBufferAttachments[0];
    att.sampleBuffer = b->samples[sb_index];
    att.startOfEncoderSampleIndex = slot;
    att.endOfEncoderSampleIndex = slot + 1u;
    id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoderWithDescriptor:pd];
    if (!enc) return nil;
    ds4_timeline_rec *rec = &b->recs[b->count++];
    memset(rec, 0, sizeof(*rec));
    rec->phase = g_llms_tl_phase; rec->pos = g_llms_tl_pos; rec->rows = g_llms_tl_rows; rec->inv = g_llms_tl_inv;   /* llms TL_PHASE */
    rec->caller = caller; rec->enc = (uintptr_t)enc;   /* apply_tl_bind.py */
    ds4_gpu_timeline_hook_encoder(enc);
    return enc;
}
/* Blit encoder with timeline sampling (blit passes are otherwise invisible
 * to the encoder timeline and show up as gaps). */
static id<MTLBlitCommandEncoder> ds4_gpu_blit_encoder(id<MTLCommandBuffer> cb, const char *label,
                                                     uint32_t n_ops) {
    if (g_timeline_enabled && cb == g_batch_cb && (!g_timeline_batch || g_timeline_batch->cb != cb)) ds4_gpu_timeline_attach(cb);
    DS4TimelineBatch *b = g_timeline_batch;
    if (!g_timeline_enabled || !b || cb != g_batch_cb) return [cb blitCommandEncoder];
    if (llms_tlp()) {   /* llms TL_POOL */
        if (b->count == b->cap) { b->cap *= 2; b->recs = realloc(b->recs, (size_t)b->cap * sizeof(ds4_timeline_rec)); }
        const uint64_t gen = __atomic_fetch_add(&g_llms_tlp_next, 1, __ATOMIC_RELAXED); const uint32_t ix = (uint32_t)(gen % LLMS_TLP_SLOTS);
        const uint32_t sbi = ix / LLMS_TLP_PER, slot = (ix % LLMS_TLP_PER) * 2u;
        MTLBlitPassDescriptor *pd = [MTLBlitPassDescriptor blitPassDescriptor];
        MTLBlitPassSampleBufferAttachmentDescriptor *att = pd.sampleBufferAttachments[0];
        att.sampleBuffer = g_llms_tlp_sb[sbi]; att.startOfEncoderSampleIndex = slot; att.endOfEncoderSampleIndex = slot + 1u;
        id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoderWithDescriptor:pd];
        if (!enc) return [cb blitCommandEncoder];
        ds4_timeline_rec *rec = &b->recs[b->count++]; memset(rec, 0, sizeof(*rec));
        rec->phase = g_llms_tl_phase; rec->pos = g_llms_tl_pos; rec->rows = g_llms_tl_rows; rec->inv = g_llms_tl_inv;
        rec->caller = (uintptr_t)__builtin_return_address(0); rec->n_dispatch = n_ops; rec->tlp = 1; rec->tlp_sb = sbi; rec->tlp_slot = slot; rec->tlp_gen = gen;
        snprintf(rec->kernel, sizeof(rec->kernel), "blit:%s", label ? label : "?");
        return enc;
    }
    const uint32_t per_buffer = DS4_TIMELINE_SAMPLES_PER_BUFFER / 2;
    const uint32_t sb_index = b->count / per_buffer;
    if (sb_index >= [b->samples count]) {
        MTLCounterSampleBufferDescriptor *d = [MTLCounterSampleBufferDescriptor new];
        d.counterSet = g_timeline_counter_set;
        d.storageMode = MTLStorageModeShared;
        d.sampleCount = DS4_TIMELINE_SAMPLES_PER_BUFFER;
        NSError *error = nil;
        id<MTLCounterSampleBuffer> sb = [g_device newCounterSampleBufferWithDescriptor:d error:&error];
        if (!sb) return [cb blitCommandEncoder];
        [b->samples addObject:sb];
    }
    if (b->count == b->cap) {
        b->cap *= 2;
        b->recs = realloc(b->recs, (size_t)b->cap * sizeof(ds4_timeline_rec));
    }
    const uint32_t slot = (b->count % per_buffer) * 2u;
    MTLBlitPassDescriptor *pd = [MTLBlitPassDescriptor blitPassDescriptor];
    MTLBlitPassSampleBufferAttachmentDescriptor *att = pd.sampleBufferAttachments[0];
    att.sampleBuffer = b->samples[sb_index];
    att.startOfEncoderSampleIndex = slot;
    att.endOfEncoderSampleIndex = slot + 1u;
    id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoderWithDescriptor:pd];
    if (!enc) return [cb blitCommandEncoder];
    ds4_timeline_rec *rec = &b->recs[b->count++];
    memset(rec, 0, sizeof(*rec));
    rec->phase = g_llms_tl_phase; rec->pos = g_llms_tl_pos; rec->rows = g_llms_tl_rows; rec->inv = g_llms_tl_inv;   /* llms TL_PHASE */
    rec->caller = (uintptr_t)__builtin_return_address(0);
    rec->n_dispatch = n_ops;
    snprintf(rec->kernel, sizeof(rec->kernel), "blit:%s", label ? label : "?");
    return enc;
}

