static void llms_kbt_report(void) {
    fprintf(stderr, "llms kb thermal: %llu touches gated, %llu open, last zone share %.2f, %llu samples\n", (unsigned long long)g_llms_kbt_gated,
            (unsigned long long)g_llms_kbt_open, (double)g_llms_kbt_zone, (unsigned long long)g_llms_kbt_samples);
