static void *llms_kbt_thread(void *arg) {
    (void)arg;
    void *h = dlopen("/usr/lib/libIOReport.dylib", RTLD_NOW);
    if (!h) { fprintf(stderr, "llms: kb thermal -- libIOReport not loadable; the gate stays open\n"); return NULL; }
    CFDictionaryRef (*copy_ch)(CFStringRef, CFStringRef, uint64_t, uint64_t, uint64_t) = dlsym(h, "IOReportCopyChannelsInGroup");
    void *(*create_sub)(void *, CFMutableDictionaryRef, CFMutableDictionaryRef *, uint64_t, CFTypeRef) = dlsym(h, "IOReportCreateSubscription");
    CFDictionaryRef (*samples)(void *, CFMutableDictionaryRef, CFTypeRef) = dlsym(h, "IOReportCreateSamples");
    CFDictionaryRef (*delta_of)(CFDictionaryRef, CFDictionaryRef, CFTypeRef) = dlsym(h, "IOReportCreateSamplesDelta");
    CFStringRef (*ch_sub)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetSubGroup");
    CFStringRef (*ch_name)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetChannelName");
    int (*ch_fmt)(CFDictionaryRef) = dlsym(h, "IOReportChannelGetFormat");
    int32_t (*st_count)(CFDictionaryRef) = dlsym(h, "IOReportStateGetCount");
    CFStringRef (*st_name)(CFDictionaryRef, int32_t) = dlsym(h, "IOReportStateGetNameForIndex");
    int64_t (*st_res)(CFDictionaryRef, int32_t) = dlsym(h, "IOReportStateGetResidency");
    if (!copy_ch || !create_sub || !samples || !delta_of || !ch_sub || !ch_name || !ch_fmt || !st_count || !st_name || !st_res) {
        fprintf(stderr, "llms: kb thermal -- an IOReport symbol is missing; the gate stays open\n"); return NULL; }
    CFDictionaryRef ch = copy_ch(CFSTR("GPU Stats"), NULL, 0, 0, 0);
    if (!ch) { fprintf(stderr, "llms: kb thermal -- no 'GPU Stats' channels; the gate stays open\n"); return NULL; }
    CFMutableDictionaryRef want = CFDictionaryCreateMutableCopy(NULL, 0, ch), subbed = NULL; CFRelease(ch);
    void *sub = create_sub(NULL, want, &subbed, 0, NULL);
    if (!sub) { fprintf(stderr, "llms: kb thermal -- IOReportCreateSubscription failed; the gate stays open\n"); return NULL; }
    CFDictionaryRef prev = samples(sub, subbed, NULL);
    for (;;) {
        sleep(1);
        CFDictionaryRef cur = samples(sub, subbed, NULL); if (!cur) continue;
        CFDictionaryRef d = prev ? delta_of(prev, cur, NULL) : NULL;
        CFArrayRef arr = d ? CFDictionaryGetValue(d, CFSTR("IOReportChannels")) : NULL;
        for (CFIndex i = 0, n = arr ? CFArrayGetCount(arr) : 0; i < n; i++) {
            CFDictionaryRef c = CFArrayGetValueAtIndex(arr, i);
            if (ch_fmt(c) != 2) continue;
            CFStringRef sg = ch_sub(c), nm = ch_name(c);
            if (!sg || !nm || CFStringCompare(nm, CFSTR("PZRSDNCY"), 0) != kCFCompareEqualTo) continue;
            int64_t tot = 0, slow = 0;
            for (int32_t s = 0, ns = st_count(c); s < ns; s++) {
                const int64_t r = st_res(c, s); tot += r;
                CFStringRef sn = st_name(c, s);
                if (sn && CFStringCompare(sn, CFSTR("SLOWCLTM"), 0) == kCFCompareEqualTo) slow += r;
            }
            if (tot > 0) { g_llms_kbt_zone = (float)((double)slow / (double)tot); __sync_fetch_and_add(&g_llms_kbt_samples, 1); }
        }
        if (d) CFRelease(d);
        if (prev) CFRelease(prev);
        prev = cur;
    }
    return NULL;
}


static int llms_kbt_on(void) {
