        if (g_llms_kbt) {
            pthread_t t; pthread_attr_t a; pthread_attr_init(&a); pthread_attr_setdetachstate(&a, PTHREAD_CREATE_DETACHED);
            if (pthread_create(&t, &a, llms_kbt_thread, NULL) != 0) { fprintf(stderr, "llms: kb thermal -- no thread; off\n"); g_llms_kbt = 0; }
            else { atexit(llms_kbt_report);
                   fprintf(stderr, g_llms_kbt == 2 ? "llms: kb thermal -- CANARY: the filler only INSIDE the GPU's thermal zone\n"
                                                   : "llms: kb thermal (the filler only outside the GPU's thermal zone; IOReport PZRSDNCY at 1 Hz)\n"); }
            pthread_attr_destroy(&a);
        }
    }
    return g_llms_kbt;
}
static void llms_kb_touch(void) {
