            NSError *err = nil;
            id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\nkernel void llms_kb(device float *b [[buffer(0)]], constant uint &n [[buffer(1)]], uint t [[thread_position_in_grid]]) { float x = b[t]; for (uint i = 0; i < n; i++) x = fma(x, 0.9999f, 0.0001f); b[t] = x; }\n" options:nil error:&err];
            id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_kb"] : nil;
            g_llms_kb_ps = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
            g_llms_kb_q = [g_device newCommandQueue];
            g_llms_kb_buf = [g_device newBufferWithLength:128 options:MTLResourceStorageModeShared];
            if (g_llms_kb_ps && g_llms_kb_q && g_llms_kb_buf) { g_llms_kb_n = atoi(e); atexit(llms_kb_report); fprintf(stderr, "llms: keepbusy on (%d multiply-adds per filler dispatch, second queue)\n", g_llms_kb_n); }
            else fprintf(stderr, "llms: keepbusy could not start (%s)\n", err ? err.localizedDescription.UTF8String : "no pipeline");
        }
    }
    if (g_llms_kb_n <= 0) return;
    {   const int kbt = llms_kbt_on();   /* llms KB_THERMAL */
        if (kbt) { const int clamped = g_llms_kbt_zone >= 0.5f; if (kbt == 2 ? !clamped : clamped) { g_llms_kbt_gated++; return; } g_llms_kbt_open++; } }
    g_llms_kb_last = llms_kb_now();
