static void llms_gl_wake(id<MTLCommandBuffer> cb, double wait0) {
    if (g_llms_gl_on <= 0) return;
    const double now = llms_up_s(), e = cb.GPUEndTime;
    if (e > 0.0) { g_llms_wake_ms += (now - (e > wait0 ? e : wait0)) * 1e3; g_llms_wake_n++; }
