static int llms_gl_cmp(const void *a, const void *b) { const double x = ((const llms_gl_ent *)a)->start, y = ((const llms_gl_ent *)b)->start; return x < y ? -1 : x > y; }
static void llms_gl_report(void) {
    if (!g_llms_gl) return;
    os_unfair_lock_lock(&g_llms_gl_lock);
    qsort(g_llms_gl, g_llms_gl_n, sizeof(llms_gl_ent), llms_gl_cmp);
    double busy = 0.0, sched = 0.0, starved = 0.0, overlap = 0.0, prev_end = 0.0, first = 0.0; uint32_t bad = 0, n = 0;
    double hs[5] = {0, 0, 0, 0, 0}; uint32_t hn[5] = {0, 0, 0, 0, 0};   /* starved gaps: < 0.5, 0.5-2, 2-5, 5-20, >= 20 ms */
    for (uint32_t i = 0; i < g_llms_gl_n; i++) {
        const llms_gl_ent *e = &g_llms_gl[i];
        if (!(e->start > 0.0 && e->end >= e->start) || e->start + 1e-3 < e->commit) { bad++; continue; }
        if (!n++) first = e->start;
