static int ds4_gpu_tp_world_is_two(void);

static ds4_gpu_mv_dispatch ds4_gpu_make_q8_0_mv_dispatch(void) {
    const uint64_t default_nsg = ds4_gpu_tp_world_is_two() ? 2u : 4u;
    const int16_t nsg =
        (int16_t)ds4_gpu_env_u64("DS4_METAL_Q8_MV_NSG", default_nsg, 1u, 8u);
    return (ds4_gpu_mv_dispatch) {
        .function_name = "kernel_mul_mv_q8_0_f32",
        .nsg = nsg,
        .nr0 = 2,
        .smem = 32u * 2u * sizeof(float),
    };
}

/* Single-token F16/F32 matvecs with few output rows (the Qwen hyper-connection
 * low-rank down projections and routers) launch one row per SIMD group on M5,
 * where two-row tiles leave most of the 40 cores idle.  The per-row K walk,
 * simdgroup count and reduction tree are unchanged.  DS4_METAL_PLAIN_MV_NR0
 * forces 1 or 2 rows on any device. */
static int llms_alt_off(const char *name);   /* llms PLAIN_NR1: ALT */
static bool ds4_gpu_plain_mv_single_row(uint64_t out_dim) {
    const uint64_t override = ds4_gpu_env_u64("DS4_METAL_PLAIN_MV_NR0", 0u, 0u, 2u);
    if (override) return override == 1u;
    {
        static int on = -1; if (on < 0) { const char *e = getenv("LLMS_DS4_PLAIN_NR1"); on = e && *e && *e != '0';
                                         if (on) fprintf(stderr, "llms: plain nr1 (one row per simdgroup for out_dim <= 1024; exact)\n"); }
        if (on && out_dim <= 1024u && !llms_alt_off("pn1")) return true;
    }
    return out_dim <= 1024u && ds4_gpu_device_is_m5_apple_silicon();
}

static ds4_gpu_mv_dispatch ds4_gpu_make_plain_mv_dispatch(
        uint64_t in_dim,
        int      f32_weights) {
    if (in_dim < 32) {
        return (ds4_gpu_mv_dispatch) {
            .function_name = f32_weights ? "kernel_mul_mv_f32_f32_short" : "kernel_mul_mv_f16_f32_short",
            .nsg = 1,
            .nr0 = 32,
            .smem = 0,
        };
    }

    const int16_t nsg = (int16_t)((in_dim + 127u) / 128u > 8u ? 8u : (in_dim + 127u) / 128u);
    const int use_4 = (in_dim % 4u) == 0;
    return (ds4_gpu_mv_dispatch) {
        .function_name = f32_weights
            ? (use_4 ? "kernel_mul_mv_f32_f32_4" : "kernel_mul_mv_f32_f32")
            : (use_4 ? "kernel_mul_mv_f16_f32_4" : "kernel_mul_mv_f16_f32"),
        .nsg = nsg,
        .nr0 = 2,
        .smem = 32u * 2u * sizeof(float),
    };
}

/* llms LLMS_DS4_PLAIN_MV_LEAN (apply_ds4_plain_mv_lean.py): the plain one-token F16 / F32 matvec with 4 rows per threadgroup (the
 * kernel's own nr0 = 4) and only the simdgroups that have work. Returns the simdgroups to dispatch. 1 on, 2 canary. */
static uint64_t g_llms_plain_mv_lean_calls;
static void llms_plain_mv_lean_report(void) { fprintf(stderr, "llms plain mv lean: %llu dispatches\n", (unsigned long long)g_llms_plain_mv_lean_calls); }
static int llms_plain_mv_lean(void) {
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("LLMS_DS4_PLAIN_MV_LEAN");
        on = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 2 : 1) : 0;
        if (on) { fprintf(stderr, on == 2 ? "llms: plain matvec lean dispatch -- CANARY: one simdgroup fewer than have work\n"
                                          : "llms: plain matvec lean dispatch (4 rows per threadgroup, working simdgroups only)\n");
                  atexit(llms_plain_mv_lean_report); }
    }
    return on;
}
static NSUInteger llms_plain_mv_lean_apply(ds4_gpu_mv_dispatch *d, uint64_t in_dim, uint64_t out_dim, uint64_t n_tok) {
    NSUInteger sg = (NSUInteger)d->nsg;
    if (!llms_plain_mv_lean() || n_tok != 1 || in_dim < 32u || (in_dim % 32u) != 0 || !strstr(d->function_name, "_f32_4")) return sg;
    if (d->nr0 == 2 && (out_dim % 4u) == 0) { d->nr0 = 4; d->smem = 32u * 4u * sizeof(float); }
    const NSUInteger active = (NSUInteger)((in_dim / 32u + 15u) / 16u);
    if (active < sg) sg = active;
    if (llms_plain_mv_lean() == 2 && sg > 1u) sg--;
    g_llms_plain_mv_lean_calls++;
    return sg;
}

