/* Simdgroups per threadgroup for the few-row (2..16 tokens) Q8/F16 matvecs
 * that carry the MTP verify rows.  Rows per threadgroup only: each row keeps
 * its lane walk and shuffle tree, so outputs are byte-identical at any
 * value (tests/test_qwen4_kernels.c pins 1/2/4/8). */
/* Row-exact geometry for the 3-row speculative verify: the few-row matvec
 * and routed-expert dispatches keep the lane maps and kernel choices of the
 * T <= 2 decode paths, so every committed row stays byte-identical. */
static bool g_qwen4_verify_rows_exact;
void ds4_gpu_qwen4_set_verify_rows_exact(bool on) {
    g_qwen4_verify_rows_exact = on;
}

static int16_t ds4_gpu_mv_ext_nsg(void) {
    return (int16_t)ds4_gpu_env_u64("DS4_METAL_MV_EXT_NSG", 2u, 1u, 8u);
}

static int16_t ds4_gpu_mv_ext_nxpsg(uint64_t in_dim, uint64_t n_tok) {
    if ((in_dim % 256u) == 0 && (n_tok < 3 || (n_tok == 3 && g_qwen4_verify_rows_exact))) return 16;
    if ((in_dim % 128u) == 0) return 8;
    return 4;
}

static int16_t ds4_gpu_mv_ext_r1ptg(uint64_t n_tok) {
    switch (n_tok) {
    case 2: return 2;
    case 3:
    case 6: return 3;
    case 4:
    case 7:
    case 8: return 4;
    case 5: return 5;
    default: return n_tok > 8 ? 4 : 0;
    }
}

/* llms LLMS_DS4_Q8_EXT_HALF (apply_ds4_q8_ext_half.py): the dense small-batch Q8_0 kernel with half-precision products;
 * the kernel exists only in a *_xh.metal dense source */
static int llms_q8_ext_half(void) {
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("LLMS_DS4_Q8_EXT_HALF"), *src = getenv("DS4_METAL_DENSE_SOURCE");
        on = e && *e && *e != '0';
        if (on && !(src && llms_srckey(src, "_xh.metal"))) {
            llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_Q8_EXT_HALF ignored: DS4_METAL_DENSE_SOURCE does not name a *_xh.metal source\n"), LLMS_G_NAME); on = 0;
        }
        if (on) fprintf(stderr, "llms: dense Q8_0 small-batch kernel with half-precision products (four tokens per pass)\n");
    }
    return on;
}
/* llms EXT_R8 (apply_ds4_ext_r8.py): 8 tokens per threadgroup in the batched Q8_0 ext matvec. 1 on, 2 canary */
static uint64_t g_llms_r8_calls;
static void llms_r8_report(void) { fprintf(stderr, "llms ext r8: %llu dispatches\n", (unsigned long long)g_llms_r8_calls); }
static int llms_ext_r8(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_EXT_R8"); on = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 2 : 1) : 0;
                  if (on) { fprintf(stderr, on == 2 ? "llms: ext r8 -- CANARY: wrong token stride\n" : "llms: ext r8 (8 tokens per threadgroup for Q8_0 multiples of 8)\n"); atexit(llms_r8_report); } }
    return on;
}

/* llms EXT_MT (apply_ds4_ext_mt.py): the batched dense Q8 matvec on the attn-out multi-token template. value = NR0*10 + NTOK; canary = 48 with the token stride halved */
static uint64_t g_llms_mt_calls;
static void llms_mt_report(void) { fprintf(stderr, "llms ext mt: %llu dispatches\n", (unsigned long long)g_llms_mt_calls); }
static int llms_ext_mt(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_EXT_MT"); on = e && *e ? (!strcmp(e, "canary") ? -48 : atoi(e)) : 0;
                  if (on != 44 && on != 48 && on != 84 && on != 88 && on != 28 && on != -48) on = 0;
                  if (on) { fprintf(stderr, on < 0 ? "llms: ext mt -- CANARY: 8 rows x 4 tokens with the wrong token stride\n" : "llms: ext mt %d (rows x tokens per threadgroup in the batched Q8 matvec, mt8 template; NOT bit-exact)\n", on); atexit(llms_mt_report); } }
    return on;
}

/* llms EXT_NXPSG (apply_ds4_ext_nxpsg.py): lanes per row in the batched Q8 ext matvec for matrices up to MAXROWS rows: 16 or 32; canary = 32 with the token stride halved */
static uint64_t g_llms_nx_calls;
static void llms_nx_report(void) { fprintf(stderr, "llms ext nxpsg: %llu dispatches\n", (unsigned long long)g_llms_nx_calls); }
static int llms_ext_nxpsg_env(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_EXT_NXPSG"); on = e && *e ? (!strcmp(e, "canary") ? -32 : atoi(e)) : 0;
                  if (on != 16 && on != 32 && on != -32) on = 0;
                  if (on) { fprintf(stderr, on < 0 ? "llms: ext nxpsg -- CANARY: 32 lanes per row with the wrong token stride\n" : "llms: ext nxpsg %d (lanes per row in the batched Q8 matvec, matrices up to %s rows; NOT bit-exact)\n", on, "8192"); atexit(llms_nx_report); } }
    return on;
}
static int16_t llms_ext_nxpsg(uint64_t in_dim, uint64_t out_dim, uint64_t n_tok, int16_t dflt) {
    const uint64_t maxrows = 8192u;
    const int v = llms_ext_nxpsg_env(); int nx = v < 0 ? 32 : v;
    if (!v || n_tok < 4 || out_dim > maxrows) return dflt;
    if (nx == 32 && (in_dim % 512u) != 0) nx = 16;
    if (nx == 16 && (in_dim % 256u) != 0) return dflt;
    g_llms_nx_calls++;
