/* Compile the single in-repo Metal source and create the pipelines that every
 * session uses. Shape-dependent kernels with function constants are built
 * lazily by the small ds4_gpu_get_* caches, so startup stays predictable
 * while long-context prefill and decode can still pick specialized variants. */

static void llms_routing_contract(void) {
    static int done; if (done) return; done = 1;
    static const char *knobs[4] = {"LLMS_DS4_DECODE_ROUTE", "LLMS_DS4_DECODE_ROUTE_LATE", "LLMS_DS4_PREFILL_ROUTE", "LLMS_DS4_PREFILL_ROUTE_SHORT"};
    const char *r = getenv("LLMS_DS4_ROUTING");
    const int bonus = r && !strcmp(r, "bonus");
    if (r && *r && !bonus && strcmp(r, "exact")) { fprintf(stderr, "llms: LLMS_DS4_ROUTING must be 'exact' or 'bonus' (got '%s')\n", r); exit(2); }
    if (bonus) { fprintf(stderr, "llms routing: bonus -- FIDELITY DIAL (cache-state-dependent expert selection; outputs are not the model's and not repeatable)\n"); return; }
    for (int i = 0; i < 4; i++) {
        const char *v = getenv(knobs[i]);
        if (v && *v && strcmp(v, "0") && strtod(v, NULL) != 0.0) {
            fprintf(stderr, "llms: ROUTING CONTRACT VIOLATED: LLMS_DS4_ROUTING=exact but %s=%s (set LLMS_DS4_ROUTING=bonus to use the fidelity dial)\n", knobs[i], v);
            exit(2);
        }
        setenv(knobs[i], "0", 1);
    }
    fprintf(stderr, "llms routing: exact (contract: ONE_RPOL / ONE_RPOL_LATE / RPOL / SP_RPOL forced 0)\n");
}
int ds4_gpu_init(void) {
    ds4_gpu_llms_startup_mark("gpu init: entry");   /* llms STARTUP_LOG */
    llms_routing_contract();
    if (g_initialized) return 1;

    @autoreleasepool {
        ds4_gpu_decode_pipeline_fast_cache_reset();
        g_device = MTLCreateSystemDefaultDevice();
        ds4_gpu_llms_startup_mark("gpu init: device created");   /* llms STARTUP_LOG */
        if (!g_device) {
            fprintf(stderr, "ds4: Metal device not available\n");
            return 0;
        }


        {
            static id llms_lc_activity; const char *e = getenv("LLMS_DS4_LATCRIT"); const int lc = e && *e && *e != '0' ? atoi(e) : 0;
            if (lc >= 1 && !llms_lc_activity) {
                llms_lc_activity = [[NSProcessInfo processInfo] beginActivityWithOptions:(NSActivityLatencyCritical | NSActivityUserInitiated | NSActivityIdleSystemSleepDisabled) reason:@"llms decode"];
                fprintf(stderr, "llms: latcrit %d (NSActivityLatencyCritical%s)\n", lc, lc >= 2 ? " + the time-constraint policy on the encode thread" : "");
            }
            if (lc >= 2) {
                mach_timebase_info_data_t tb; mach_timebase_info(&tb);
                const double per_ms = 1e6 * (double)tb.denom / (double)tb.numer;
                thread_time_constraint_policy_data_t pol = { .period = 0, .computation = (uint32_t)(5.0 * per_ms), .constraint = (uint32_t)(20.0 * per_ms), .preemptible = 1 };
                const kern_return_t kr = thread_policy_set(mach_thread_self(), THREAD_TIME_CONSTRAINT_POLICY, (thread_policy_t)&pol, THREAD_TIME_CONSTRAINT_POLICY_COUNT);
                fprintf(stderr, "llms: latcrit time-constraint policy on thread %p: kr %d\n", (void *)pthread_self(), (int)kr);
            }
        }
        ds4_gpu_timeline_probe(g_device);
        ds4_gpu_print_device_summary();
        ds4_gpu_detect_metal4_features();

        g_queue = [g_device newCommandQueueWithMaxCommandBufferCount:256];
        if (!g_queue) {
            fprintf(stderr, "ds4: failed to create Metal command queue\n");
            g_device = nil;
            return 0;
        }
        g_model_buffer_cache = [NSMutableDictionary dictionary];
        g_model_buffer_cache_bytes = 0;
        g_model_buffer_cache_evictions = 0;
        g_model_buffer_cache_over_limit = 0;
        g_q4_expert_table_cache = [NSMutableDictionary dictionary];
        g_q4_expert_layer_residency_cache = [NSMutableDictionary dictionary];
        g_pipeline_cache = [NSMutableDictionary dictionary];
        g_dsv4_completion_cache = [NSCache new];
        g_dsv4_completion_cache.countLimit = 256u;
        g_transient_buffers = [NSMutableArray array];
        g_pending_cbs = [NSMutableArray array];
        if (!g_model_buffer_cache || !g_q4_expert_table_cache ||
            !g_q4_expert_layer_residency_cache ||
            !g_pipeline_cache || !g_dsv4_completion_cache ||
            !g_transient_buffers || !g_pending_cbs) {
            fprintf(stderr, "ds4: Metal bookkeeping allocation failed\n");
            g_pending_cbs = nil;
            g_transient_buffers = nil;
            g_dsv4_completion_cache = nil;
            g_pipeline_cache = nil;
            g_q4_expert_layer_residency_cache = nil;
            g_q4_expert_table_cache = nil;
            g_model_buffer_cache = nil;
            g_queue = nil;
            g_device = nil;
            return 0;
        }

        NSError *error = nil;
        NSString *source = ds4_gpu_full_source();
        if (!source) {
            g_queue = nil;
            g_device = nil;
            return 0;
        }
        MTLCompileOptions *options = [MTLCompileOptions new];
        NSMutableDictionary *macros = [NSMutableDictionary new];
        if (g_metal4_tensor_api_enabled) {
            macros[@"DS4_METAL_HAS_TENSOR"] = @"1";
            fprintf(stderr, "ds4: Metal 4 tensor API enabled for Tensor kernels\n");
        }
        { const char *ce = getenv("LLMS_DS4_Q4L_CE"); if (ce && *ce && *ce != '0') { macros[@"LLMS_Q4L_CE"] = @"1"; fprintf(stderr, "llms: q4l ce (the compact BF16 epilogue of the two-row NR4 / NSG2 dense kernels; a compile macro from LLMS_DS4_Q4L_CE)\n"); } }   /* apply_ce.py */
        { const char *ce3 = getenv("LLMS_DS4_Q4L_CE3"); if (ce3 && *ce3 && *ce3 != '0') { macros[@"LLMS_Q4L_CE3"] = @"1"; fprintf(stderr, "llms: q4l ce3 (the compact epilogue on the three-row NR8 and four-row NR4 BF16 kernels too; a compile macro from LLMS_DS4_Q4L_CE3)\n"); } }   /* apply_ce3.py */


        { const char *rs = getenv("LLMS_DS4_ATT2_ROWSCALE"); if (rs && *rs && *rs != '0') { const int can = !strcmp(rs, "canary"); macros[@"LLMS_ATT2_RS"] = can ? @"2" : @"1";
            fprintf(stderr, "llms: att2 rowscale (the online-softmax rescale as an elementwise row scale, not a diagonal MMA; a compile-time switch%s)\n", can ? " -- CANARY: alpha^2" : ""); } }
        { const char *h2 = getenv("LLMS_DS4_Q4L_HALF2"); if (h2 && *h2 && *h2 != '0') { macros[@"LLMS_Q4L_HALF2"] = @"1"; fprintf(stderr, "llms: q4l half2 (the two-row dense loop's products in half2; a compile-time switch)\n"); } }   /* apply_half2.py */

        const int drift_hc_stable        = ds4_gpu_env_bool("DS4_METAL_HC_STABLE")          != 0; // default ON
        const int drift_norm_unify       = ds4_gpu_env_bool("DS4_METAL_NORM_RSQRT_DISABLE") != 0; // default ON
        const int drift_kv_raw_f32       = ds4_gpu_env_bool("DS4_METAL_KV_RAW_F32")         >  0; // default OFF
        const int drift_rope_exp2_log2   = ds4_gpu_env_bool("DS4_METAL_ROPE_EXP2_LOG2")     >  0; // default OFF
        const int drift_math_safe        = ds4_gpu_env_bool("DS4_METAL_MATH_SAFE")          >  0; // default OFF

        if (drift_math_safe) {
            // MTLCompileOptions.fastMathEnabled defaults to YES and Apple's
            // headers explicitly say this "may violate the IEEE 754 standard".
            // Different fast-math optimizations get applied across the
            // matmul2d cooperative-tensor path and the legacy
            // simdgroup_multiply_accumulate path on M5, amplifying the
            // mismatch. MTLMathModeSafe pins the entire library to strict
            // IEEE-754 semantics. Diagnostic-only: useful to localize drift
            // sources but not to ship as a default.
            if (@available(macOS 15.0, *)) {
                options.mathMode = MTLMathModeSafe;
                fprintf(stderr, "ds4: Metal shader library math mode = safe (strict IEEE-754) by DS4_METAL_MATH_SAFE\n");
            } else {
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
                options.fastMathEnabled = NO;
#pragma clang diagnostic pop
                fprintf(stderr, "ds4: Metal shader library fast-math disabled by DS4_METAL_MATH_SAFE (pre-macOS 15)\n");
            }
        }

        if (drift_hc_stable)      macros[@"DS4_METAL_HC_STABLE"]          = @"1";
        if (drift_norm_unify)     macros[@"DS4_METAL_NORM_RSQRT_DISABLE"] = @"1";
