int ds4_gpu_test_mxfp4_down_half_lut(uint16_t *legacy_bits,
                                     uint16_t *lut_bits) {
    if (!legacy_bits || !lut_bits) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;

    @autoreleasepool {
        const NSUInteger count = 4096u;
        const NSUInteger bytes = count * sizeof(uint16_t);
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline("kernel_test_mxfp4_down_half_lut");
        id<MTLBuffer> legacy = [g_device newBufferWithLength:bytes
                                                    options:MTLResourceStorageModeShared];
        id<MTLBuffer> lut = [g_device newBufferWithLength:bytes
                                                 options:MTLResourceStorageModeShared];
        id<MTLCommandBuffer> cb = ds4_gpu_new_command_buffer();
        if (!pipeline || !legacy || !lut || !cb) {
            fprintf(stderr, "ds4: Metal MXFP4 half-LUT test setup failed\n");
            return 0;
        }

        id<MTLComputeCommandEncoder> enc = [cb computeCommandEncoder];
        if (!enc) return 0;
        [enc setComputePipelineState:pipeline];
        [enc setBuffer:legacy offset:0 atIndex:0];
        [enc setBuffer:lut offset:0 atIndex:1];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((count + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256u, 1, 1)];
        [enc endEncoding];
        llms_gl_track(cb); [cb commit]; g_llms_all_commits++;
        if (!ds4_gpu_wait_command_buffer(cb, "MXFP4 half-LUT raw-bit test")) {
            return 0;
        }
        memcpy(legacy_bits, [legacy contents], bytes);
        memcpy(lut_bits, [lut contents], bytes);
    }
    return 1;
}

void ds4_gpu_test_set_flags(uint32_t flags) {
    g_test_flags = flags;
}

ds4_gpu_tensor *ds4_gpu_tensor_alloc(uint64_t bytes) {
    if (!g_initialized && !ds4_gpu_init()) return NULL;
    if (bytes == 0 || bytes > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *tensor = [DS4MetalTensor new];
        tensor.buffer = [g_device newBufferWithLength:(NSUInteger)bytes
                                              options:MTLResourceStorageModeShared];
        if (!tensor.buffer) {
            return NULL;
        }
        tensor.offset = 0;
        tensor.bytes = bytes;
        tensor.owner = 1;
        uint64_t live_snap = 0;
        uint64_t peak_snap = 0;
        pthread_mutex_lock(&g_tensor_mu);
        const int tracked = ds4_gpu_tensor_track_alloc_locked(
                (__bridge const void *)tensor,
                bytes,
                &live_snap,
                &peak_snap);
        pthread_mutex_unlock(&g_tensor_mu);
        if (!tracked) {
            fprintf(stderr, "ds4: failed to track Metal tensor allocation\n");
            tensor.buffer = nil;
            return NULL;
        }
        if (ds4_gpu_trace_allocs()) {
            fprintf(stderr,
                    "ds4: Metal tensor alloc %.3f MiB live %.3f MiB peak %.3f MiB\n",
                    (double)bytes / (1024.0 * 1024.0),
                    (double)live_snap / (1024.0 * 1024.0),
                    (double)peak_snap / (1024.0 * 1024.0));
        }
        return (__bridge_retained ds4_gpu_tensor *)tensor;
    }
}

ds4_gpu_tensor *ds4_gpu_tensor_alloc_managed(uint64_t bytes) {
    return ds4_gpu_tensor_alloc(bytes);
}

