    return 0;
}







static ds4_gpu_llms_owed g_llms_owed[2];
static uint64_t g_llms_owed_n[2][4], g_llms_owed_overwrites;   /* [kind 1, kind 2][owed, taken, forced, dropped at a free] */
static void llms_owed_report(void) {
    fprintf(stderr, "llms hc owed: split %llu owed / %llu taken by a dual / %llu forced / %llu dropped at a free; mixer+split %llu / %llu / %llu / %llu; %llu overwrites\n",
            (unsigned long long)g_llms_owed_n[0][0], (unsigned long long)g_llms_owed_n[0][1], (unsigned long long)g_llms_owed_n[0][2], (unsigned long long)g_llms_owed_n[0][3],
            (unsigned long long)g_llms_owed_n[1][0], (unsigned long long)g_llms_owed_n[1][1], (unsigned long long)g_llms_owed_n[1][2], (unsigned long long)g_llms_owed_n[1][3],
            (unsigned long long)g_llms_owed_overwrites);
}
static void llms_owed_drop_named(const ds4_gpu_tensor *t) {
    for (int w = 0; w < 2; w++) {
        ds4_gpu_llms_owed *r = &g_llms_owed[w];
        if (r->kind && (t == r->split || t == r->mix || t == r->xo || t == r->no || t == r->hin || t == r->pre)) { g_llms_owed_n[r->kind - 1][3]++; r->kind = 0; }
    }
}
int ds4_gpu_llms_owed_force(int side) {
    for (int w = side < 0 ? 0 : side; w <= (side < 0 ? 1 : side); w++) {
        const ds4_gpu_llms_owed r = g_llms_owed[w];
        if (!r.kind) continue;
        g_llms_owed[w].kind = 0; g_llms_owed_n[r.kind - 1][2]++;
        if (r.kind == 2 && !ds4_gpu_llms_hc_pre_fused_rows(r.split, r.xo, r.no, r.hin, r.pre, r.pre_stride, r.mix, r.map, r.size, r.fn_off, r.scale_off, r.base_off,
                                                          r.nw_off, r.n_embd, r.n_hc, r.iters, r.rms_eps, r.hc_eps, r.flags | DS4_GPU_LLMS_HCFR_MIX, r.rows)) return 0;
        if (!ds4_gpu_hc_split_sinkhorn_tensor(r.split, r.mix, r.map, r.size, r.scale_off, r.base_off, r.n_hc, r.iters, r.hc_eps)) return 0;
    }
    return 1;
}
void ds4_gpu_llms_owe(int side, const ds4_gpu_llms_owed *rec) {
    static int reg; if (!reg) { reg = 1; atexit(llms_owed_report); }
    if (g_llms_owed[side].kind) { g_llms_owed_overwrites++; (void)ds4_gpu_llms_owed_force(side); }   /* never overwrite an unsettled record */
    g_llms_owed[side] = *rec; g_llms_owed_n[rec->kind - 1][0]++;
}

ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base) return NULL;
    const DS4MetalTensor *base_obj = ds4_gpu_tensor_const_obj(base);
    if (offset > base_obj.bytes || bytes > base_obj.bytes - offset) return NULL;
    if (base_obj.offset > UINT64_MAX - offset) return NULL;
    const uint64_t absolute_offset = base_obj.offset + offset;
    if (absolute_offset > (uint64_t)NSUIntegerMax) return NULL;

    @autoreleasepool {
        DS4MetalTensor *view = [DS4MetalTensor new];
        view.buffer = base_obj.buffer;
        view.offset = absolute_offset;
        view.bytes = bytes;
        view.owner = 0;
        pthread_mutex_lock(&g_tensor_mu);
        const int tracked = ds4_gpu_tensor_track_view_locked((__bridge const void *)view);
        pthread_mutex_unlock(&g_tensor_mu);
        if (!tracked) {
            fprintf(stderr, "ds4: failed to track Metal tensor view\n");
            view.buffer = nil;
            return NULL;
        }
        return (__bridge_retained ds4_gpu_tensor *)view;
    }
}

void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    if (g_llms_owed[0].kind | g_llms_owed[1].kind) llms_owed_drop_named(tensor);   /* llms HC_OWED: no record outlives a tensor it names */
    @autoreleasepool {
        uint8_t owner = 0;
        uint64_t bytes = 0;
        uint64_t live_snap = 0;
        uint64_t peak_snap = 0;
        if (!ds4_gpu_tensor_prepare_free(tensor,
                                         &owner,
                                         &bytes,
                                         &live_snap,
                                         &peak_snap)) {
            return;
        }
        DS4MetalTensor *obj = (__bridge_transfer DS4MetalTensor *)tensor;
        if (owner) {
            if (ds4_gpu_trace_allocs()) {
                fprintf(stderr,
                        "ds4: Metal tensor free %.3f MiB live %.3f MiB peak %.3f MiB\n",
                        (double)bytes / (1024.0 * 1024.0),
                        (double)live_snap / (1024.0 * 1024.0),
                        (double)peak_snap / (1024.0 * 1024.0));
            }
        }
        obj.buffer = nil;
        obj.offset = 0;
        obj.bytes = 0;
        obj.owner = 0;
    }
}

uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    if (!tensor) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    return obj.bytes;
}

void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    return (uint8_t *)[obj.buffer contents] + obj.offset;
}

int ds4_gpu_tensor_fill_f32(ds4_gpu_tensor *tensor, float value, uint64_t count) {
    if (!tensor || count > ds4_gpu_tensor_bytes(tensor) / sizeof(float)) return 0;
    float *p = ds4_gpu_tensor_contents(tensor);
    if (!p && count != 0) return 0;
    for (uint64_t i = 0; i < count; i++) p[i] = value;
    return 1;
}

int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    DS4MetalTensor *obj = ds4_gpu_tensor_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        memcpy((uint8_t *)[obj.buffer contents] + obj.offset + offset, data, (size_t)bytes);
    }
    return 1;
}

int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || (!data && bytes != 0)) return 0;
    const DS4MetalTensor *obj = ds4_gpu_tensor_const_obj(tensor);
    if (offset > obj.bytes || bytes > obj.bytes - offset) return 0;
    if (bytes != 0) {
        memcpy(data, (const uint8_t *)[obj.buffer contents] + obj.offset + offset, (size_t)bytes);
    }
    return 1;
}

/* llms COPY_KERNEL (apply_ds4_copy_kernel.py): tensor copies as a compute dispatch on the open encoder instead of a blit encoder */




static int llms_k3x(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_K3X"); on = e && *e && *e != '0';
                  if (on && !ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4l_mv_kgxh3", 4)) {
                      fprintf(stderr, "llms: LLMS_DS4_K3X ignored: DS4_METAL_DENSE_SOURCE lacks the 3-row twins (kernel_llms_q4l_mv_kgxh3)\n"); on = 0; }
                  if (on) fprintf(stderr, "llms: k3x (3-row verify matvecs on half x / HXO / N1X / LEAN2 / F16 / BF16 / KGX; the routed down's colz2 at 2-4 tokens)\n"); }
    return on && !llms_alt_off("k3x");
}
static uint64_t g_llms_ck_calls;
static void llms_ck_report(void) { fprintf(stderr, "llms copy kernel: %llu copies on the compute encoder\n", (unsigned long long)g_llms_ck_calls); }
static int llms_copy_kernel(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_COPY_KERNEL"); on = e && *e && *e != '0' ? (!strcmp(e, "canary") ? 2 : 1) : 0;
                  if (on) { fprintf(stderr, on == 2 ? "llms: copy kernel -- CANARY: the last four words of every copy left out\n" : "llms: copy kernel (tensor copies on the compute encoder)\n"); atexit(llms_ck_report); } }
    return on;
}
int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                          const ds4_gpu_tensor *src, uint64_t src_offset,
                          uint64_t bytes) {
    if (!dst || !src) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    DS4MetalTensor *d = ds4_gpu_tensor_obj(dst);
    const DS4MetalTensor *s = ds4_gpu_tensor_const_obj(src);
    if (dst_offset > d.bytes || bytes > d.bytes - dst_offset) return 0;
    if (src_offset > s.bytes || bytes > s.bytes - src_offset) return 0;
    if (bytes == 0) return 1;
    if (!g_batch_cb) return 0;

    if (llms_copy_kernel() && !llms_alt_off("copyk") && g_cpy_contig_f16_f16_pipeline && (bytes % 2u) == 0 && bytes / 2u >= 4u && bytes / 2u <= UINT32_MAX &&
        ((s.offset + src_offset) % 2u) == 0 && ((d.offset + dst_offset) % 2u) == 0) {   /* llms COPY_KERNEL */
        const uint32_t n = (uint32_t)(bytes / 2u) - (llms_copy_kernel() == 2 ? 4u : 0u);
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
        if (enc) {
            g_batch_has_work = YES;
            [enc setComputePipelineState:g_cpy_contig_f16_f16_pipeline];
            [enc setBytes:&n length:sizeof(n) atIndex:0];
            [enc setBuffer:s.buffer offset:(NSUInteger)(s.offset + src_offset) atIndex:1];
            [enc setBuffer:d.buffer offset:(NSUInteger)(d.offset + dst_offset) atIndex:2];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n / 4u + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            ds4_gpu_end_compute_encoder(g_batch_cb, enc);
            g_llms_ck_calls++;
            return 1;
        }
    }
    /* C inference callers have no surrounding autorelease pool. In particular,
     * validation-layer blit bookkeeping otherwise accumulates across tokens. */
    @autoreleasepool {
        ds4_gpu_close_batch_encoder();
        g_batch_has_work = YES;
        id<MTLBlitCommandEncoder> blit = ds4_gpu_blit_encoder(g_batch_cb, "tensor_copy", 1u);
        if (!blit) return 0;
        [blit copyFromBuffer:s.buffer
                sourceOffset:(NSUInteger)(s.offset + src_offset)
                    toBuffer:d.buffer
           destinationOffset:(NSUInteger)(d.offset + dst_offset)
                        size:(NSUInteger)bytes];
        [blit endEncoding];
    }
    return 1;
}

int ds4_gpu_tensor_copy_f32_to_f16(ds4_gpu_tensor *dst, uint64_t dst_offset,
                                   const ds4_gpu_tensor *src, uint64_t src_offset,
                                   uint64_t count) {
    if (!dst || !src) return 0;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    DS4MetalTensor *d = ds4_gpu_tensor_obj(dst);
    const DS4MetalTensor *s = ds4_gpu_tensor_const_obj(src);
    if (count == 0) return 1;
    if (count > UINT64_MAX / sizeof(float) ||
        count > UINT64_MAX / sizeof(uint16_t)) {
        return 0;
    }
    const uint64_t src_bytes = count * sizeof(float);
    const uint64_t dst_bytes = count * sizeof(uint16_t);
    if (src_offset > s.bytes || src_bytes > s.bytes - src_offset ||
        dst_offset > d.bytes || dst_bytes > d.bytes - dst_offset) {
        return 0;
    }

    @autoreleasepool {
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        uint64_t done = 0;
        int ok = 1;
        while (done < count && ok) {
            uint64_t chunk64 = count - done;
            if (chunk64 > UINT32_MAX) chunk64 = UINT32_MAX;
            const uint32_t chunk = (uint32_t)chunk64;
            ok = ds4_gpu_encode_cpy_f32_f16_1d(
                    cb,
                    s.buffer,
                    (NSUInteger)(s.offset + src_offset + done * sizeof(float)),
                    d.buffer,
                    (NSUInteger)(d.offset + dst_offset + done * sizeof(uint16_t)),
                    chunk);
            done += chunk;
        }
        if (ok) ok = ds4_gpu_finish_command_buffer(cb, owned, "tensor f32 to f16 copy");
        return ok;
    }
}

int ds4_gpu_pack_slot_rows_f32_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *slots,
        uint32_t                n_rows,
        uint32_t                width,
        uint32_t                n_slots,
        uint32_t                slot_cap) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !slots || n_rows == 0 || width == 0 || n_slots == 0 ||
        slot_cap == 0 || n_rows > slot_cap) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> slotsbuf = ds4_gpu_tensor_buffer(slots);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        uint64_t row_bytes = 0;
        uint64_t slot_plane_bytes = 0;
        uint64_t slots_bytes = 0;
        uint64_t out_rows = 0;
        uint64_t out_bytes = 0;
        if ((uint64_t)width > UINT64_MAX / sizeof(float)) return 0;
        row_bytes = (uint64_t)width * sizeof(float);
        if ((uint64_t)slot_cap > UINT64_MAX / row_bytes) return 0;
        slot_plane_bytes = (uint64_t)slot_cap * row_bytes;
        if ((uint64_t)n_slots > UINT64_MAX / slot_plane_bytes) return 0;
        slots_bytes = (uint64_t)n_slots * slot_plane_bytes;
        if ((uint64_t)n_rows > UINT64_MAX / n_slots) return 0;
        out_rows = (uint64_t)n_rows * n_slots;
        if (out_rows > UINT64_MAX / row_bytes) return 0;
        out_bytes = out_rows * row_bytes;
        if (!slotsbuf || !outbuf ||
            ds4_gpu_tensor_bytes(slots) < slots_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal slot-row pack received undersized buffers\n");
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        if (!ds4_gpu_encode_cpy_f32_f32_3d_src_strided(cb,
                                                        slotsbuf,
                                                        ds4_gpu_tensor_offset(slots),
                                                        outbuf,
                                                        ds4_gpu_tensor_offset(out),
                                                        width,
                                                        n_slots,
                                                        n_rows,
                                                        sizeof(float),
                                                        slot_plane_bytes,
                                                        row_bytes,
                                                        row_bytes,
                                                        (uint64_t)n_slots * row_bytes)) {
            return 0;
        }
        if (!ds4_gpu_finish_command_buffer(cb, owned, "slot-row pack")) return 0;
    }

    return 1;
}

int ds4_gpu_begin_commands(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    /* A failed concurrent FFN must never affect the next command batch. */
    ds4_gpu_parallel_ffn_reset_state(YES);
    if (g_batch_cb) return 0;
    /* Refresh once per command batch so same-engine A/B runs can toggle the
     * static PSO without paying for environment lookups in every layer. */
    g_use_dsv4_head_rms_norm_rope_tail_pipeline =
        !g_ssd_streaming_mode &&
        ds4_gpu_device_is_pre_m5_apple_silicon() &&
        getenv("DS4_METAL_DISABLE_PRE_M5_HEAD_RMS_ROPE_PIPELINE_STATIC") == NULL;
    g_batch_cb_created_ms = ds4_gpu_now_ms();
    g_batch_cb = ds4_gpu_new_command_buffer();
    g_batch_has_work = NO;
    if (g_batch_cb) ds4_gpu_stream_expert_cache_note_batch_created();
    ds4_gpu_timeline_attach(g_batch_cb);
    return g_batch_cb != nil;
}

int ds4_gpu_flush_encoder(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    ds4_gpu_parallel_ffn_reset_state(YES);
    if (!g_batch_cb) return 0;
    ds4_gpu_close_batch_encoder();
    return 1;
}


