static uint64_t llms_pad16_rows(uint64_t n, uint64_t in_bytes_row, uint64_t out_bytes_row, id<MTLBuffer> xbuf, NSUInteger xoff, id<MTLBuffer> obuf, NSUInteger ooff) {   /* llms PAD16: 16, 8, or n */
