static uint64_t llms_pad8_rows(uint64_t n_tok, uint64_t in_dim, uint64_t out_dim, uint64_t in_esz, id<MTLBuffer> xbuf, NSUInteger xoff, id<MTLBuffer> obuf, NSUInteger ooff) {   /* llms PAD8: the padded count, or n_tok */
