                       if (g_llms_sr_set && g_queue && [g_queue respondsToSelector:@selector(addResidencySet:)]) [g_queue addResidencySet:g_llms_sr_set];
                       fprintf(stderr, "llms: slab residency (%s)\n", g_llms_sr_set ? "one residency set over the slab buffers, on the queue" : "set creation FAILED");
