static pthread_mutex_t g_llms_sbg_mu = PTHREAD_MUTEX_INITIALIZER; static pthread_cond_t g_llms_sbg_cv = PTHREAD_COND_INITIALIZER;
static __strong id<MTLBuffer> g_llms_sbg_buf[64]; static uint64_t g_llms_sbg_len[64]; static int g_llms_sbg_plan, g_llms_sbg_made, g_llms_sbg_taken, g_llms_sbg_stop, g_llms_sbg_last_taken;
static double g_llms_sbg_ms, g_llms_sbg_res_ms, g_llms_sbg_wait_ms;
static double llms_sbg_now_ms(void) { return (double)clock_gettime_nsec_np(CLOCK_UPTIME_RAW) * 1e-6; }
static id<MTLBuffer> llms_sbg_take(uint64_t len) {
    id<MTLBuffer> b = nil; g_llms_sbg_last_taken = 0; pthread_mutex_lock(&g_llms_sbg_mu);
    if (g_llms_sbg_plan > 0 && !g_llms_sbg_stop) {
