        if (k < g_llms_sbg_plan && g_llms_sbg_len[k] == len) {
            if (g_llms_sbg_made <= k) ds4_gpu_llms_startup_mark("slab take: first wait begins");   /* llms STARTUP_LOG */
            const double w0 = llms_sbg_now_ms(); while (g_llms_sbg_made <= k && !g_llms_sbg_stop) pthread_cond_wait(&g_llms_sbg_cv, &g_llms_sbg_mu); g_llms_sbg_wait_ms += llms_sbg_now_ms() - w0;
