#include <sys/mman.h>
#include <sys/file.h>
#include <sys/stat.h>
typedef struct { uint16_t layer, expert; uint32_t slot, gen, pad; uint64_t gate_abs, up_abs, down_abs, gate_bytes, down_bytes, gi, ui, di; } llms_shm_ent;
typedef struct { uint64_t magic; char key[256]; volatile uint64_t valid; uint32_t n, total_slots;
