static uint64_t g_llms_shm_restored, g_llms_shm_skip_used, g_llms_shm_skip_gen, g_llms_shm_skip_dup, g_llms_shm_skip_bad, g_llms_shm_saved_at_exit, g_llms_shm_resized;
static pthread_mutex_t g_llms_shm_mu = PTHREAD_MUTEX_INITIALIZER;
static __strong id<MTLBuffer> g_llms_shm_bufs[64];   /* the buffer made from segment k: a slab is shm-backed only if it IS that buffer */
static int llms_shm_slab_is_shm(uint32_t si) { return si < 64u && si < g_stream_expert_cache_slab_count && g_llms_shm_bufs[si] && g_stream_expert_cache_slabs[si] == g_llms_shm_bufs[si]; }
static int ds4_gpu_stream_expert_slab_slot_range(uint32_t slot, uint32_t *slab_index, uint64_t *slot_base);
static void llms_shm_drop_stale(void) {



    int n = 0; double gib = 0.0; char nm[32];
    for (int k = -1; k < 65; k++) {   /* llms DSP_BANK_SHM: k 64 = the drafter's bank segment */
        if (k < 0) snprintf(nm, sizeof nm, llms_shm_name(0)); else if (k == 64) snprintf(nm, sizeof nm, llms_shm_name(1)); else snprintf(nm, sizeof nm, llms_shm_name(2), k);
        const int fd = shm_open(nm, O_RDONLY, 0); if (fd < 0) continue;
        struct stat st; if (fstat(fd, &st) == 0) gib += (double)st.st_size / 1073741824.0;
        close(fd); if (shm_unlink(nm) == 0) n++;
    }
    if (n) fprintf(stderr, "llms shm cache: OFF in this process -- dropped %d segments (%.2f GiB) an earlier agent left (freed once unmapped)\n", n, gib);
}
static int llms_shm_on(void) {



    if (g_llms_shm < 0) { const char *e = getenv("LLMS_DS4_SHM_CACHE"); g_llms_shm = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 2 : 1;
                          if (!g_llms_shm) llms_shm_drop_stale();
                          if (g_llms_shm) fprintf(stderr, "llms: shm cache (the expert slabs in POSIX shm that outlive the process; the next process restores the cache)%s\n",
                                                  g_llms_shm == 2 ? " -- CANARY: two restored experts of one layer swapped" : ""); }
    return g_llms_shm;
}
static void llms_shm_stat_key(char *out, size_t n, const char *tag, int fd, const char *path) {
    struct stat st; int ok = fd >= 0 ? fstat(fd, &st) == 0 : (path && *path ? stat(path, &st) == 0 : 0);
    snprintf(out, n, "%s%llx.%llx.%llx;", tag, ok ? (unsigned long long)st.st_size : 0ull, ok ? (unsigned long long)st.st_mtimespec.tv_sec : 0ull, ok ? (unsigned long long)st.st_ino : 0ull);
}
static void llms_shm_save(void) {   /* atexit: the cache as it stands, the valid flag last */
    if (g_llms_shm_ok != 1 || !g_llms_shm_hdr) return;
    if (g_llms_shm == 2) { fprintf(stderr, "llms shm cache: CANARY run -- nothing saved (the header stays invalid: the next run is cold)\n"); return; }
    llms_shm_hdr *h = g_llms_shm_hdr; uint32_t n = 0;
    for (uint32_t L = 0; L < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; L++) for (uint32_t x = 0; x < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; x++) {
        const ds4_gpu_stream_expert_cache_entry *e = &g_stream_expert_cache[L][x]; uint32_t si = 0; uint64_t base = 0;
        if (!e->valid || !e->slab_backed || e->slab_slot >= g_stream_expert_cache_slab_total_slots || !ds4_gpu_stream_expert_slab_slot_range(e->slab_slot, &si, &base) || !llms_shm_slab_is_shm(si)) continue;
        if ((uint64_t)e->gate_inner < base || (uint64_t)e->up_inner < base || (uint64_t)e->down_inner < base) continue;
        h->e[n] = (llms_shm_ent){ .layer = (uint16_t)L, .expert = (uint16_t)x, .slot = e->slab_slot, .gen = h->gen[e->slab_slot], .gate_abs = e->gate_abs_offset,
            .up_abs = e->up_abs_offset, .down_abs = e->down_abs_offset, .gate_bytes = e->gate_expert_bytes, .down_bytes = e->down_expert_bytes,
            .gi = (uint64_t)e->gate_inner - base, .ui = (uint64_t)e->up_inner - base, .di = (uint64_t)e->down_inner - base };
