    __atomic_thread_fence(__ATOMIC_SEQ_CST); h->valid = 1; g_llms_shm_saved_at_exit = n;
    fprintf(stderr, "llms shm cache: %llu restored at start (skipped: %llu slot in use, %llu generation moved, %llu already cached, %llu malformed; %llu slabs resized); %llu entries saved at exit\n",
            (unsigned long long)g_llms_shm_restored, (unsigned long long)g_llms_shm_skip_used, (unsigned long long)g_llms_shm_skip_gen, (unsigned long long)g_llms_shm_skip_dup,
            (unsigned long long)g_llms_shm_skip_bad, (unsigned long long)g_llms_shm_resized, (unsigned long long)n);
    { char snm[32]; int sd = 0; for (uint32_t k = g_stream_expert_cache_slab_count; k < 64u; k++) { snprintf(snm, sizeof snm, llms_shm_name(3), k); if (shm_unlink(snm) == 0) sd++; }   /* llms CACHE BUDGET (apply_cache_budget.py): a smaller plan leaves no stale segment */
      if (sd) fprintf(stderr, "llms shm cache: dropped %d stale slab segments beyond this plan's %u\n", sd, g_stream_expert_cache_slab_count); }
    llms_mg_spawn_guardian();   /* llms MEMGUARD (4): the cache outlives this process -- a guardian drops it if memory turns scarce */
}
static void llms_shm_attach(uint64_t slot_bytes, uint32_t budget) {   /* once, from the first shm slab; under g_llms_shm_mu */
    g_llms_shm_ok = 0;
