    const int lfd = open(lp, O_CREAT | O_RDWR | O_CLOEXEC, 0600);
    if (lfd < 0 || flock(lfd, LOCK_EX | LOCK_NB) != 0) { fprintf(stderr, "llms memguard: REFUSING TO RUN -- another engine holds %s (a private second expert cache would exceed memory) (exit 75)\n", lp); _exit(75); }   /* llms MEMGUARD (1): was a private-slab fallback */   /* the lock lives as long as the process */
    char k1[64], k2[64], k3[64]; llms_shm_stat_key(k1, sizeof k1, "m", g_model_fd, NULL); llms_shm_stat_key(k2, sizeof k2, "b", -1, getenv("LLMS_DS4_GATEUP_BS64"));
    llms_shm_stat_key(k3, sizeof k3, "d", g_llms_g32d_fd, NULL);
    snprintf(g_llms_shm_key, sizeof g_llms_shm_key, "%s%s%ss%llx;n%u;p%d.%llx;%s %s", k1, k2, k3, (unsigned long long)slot_bytes, budget, g_llms_sbg_plan,
