static id<MTLBuffer> llms_shm_slab(int k, uint64_t len, uint64_t slot_bytes, uint32_t budget) {   /* slab k of the plan from /ds4x.slab.<k>, or nil */
    if (!llms_shm_on() || k < 0 || k >= 64) return nil;
    pthread_mutex_lock(&g_llms_shm_mu); if (g_llms_shm_ok < 0) llms_shm_attach(slot_bytes, budget); const int ok = g_llms_shm_ok; pthread_mutex_unlock(&g_llms_shm_mu);
    if (ok != 1) return nil;
    char nm[32]; snprintf(nm, sizeof nm, llms_shm_name(2), k);
    int fd = shm_open(nm, O_CREAT | O_RDWR, 0600); if (fd < 0) { perror("llms shm cache: shm_open slab"); return nil; }
    struct stat st; if (fstat(fd, &st) != 0) { close(fd); return nil; }
    if (st.st_size != (off_t)len) {   /* a slab of another size: its bytes mean nothing now; macOS takes one ftruncate per object */
        if (st.st_size != 0) { close(fd); shm_unlink(nm); fd = shm_open(nm, O_CREAT | O_EXCL | O_RDWR, 0600); if (fd < 0) { perror("llms shm cache: recreate slab"); return nil; } }
        if (ftruncate(fd, (off_t)len) != 0) { perror("llms shm cache: ftruncate slab"); close(fd); return nil; }
        pthread_mutex_lock(&g_llms_shm_mu); g_llms_shm_resized++; if (g_llms_shm_saved) { free(g_llms_shm_saved); g_llms_shm_saved = NULL; g_llms_shm_nsaved = 0; } pthread_mutex_unlock(&g_llms_shm_mu);
    }
    void *p = mmap(NULL, (size_t)len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0); close(fd);
    if (p == MAP_FAILED) { perror("llms shm cache: mmap slab"); return nil; }
    id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:p length:(NSUInteger)len options:MTLResourceStorageModeShared deallocator:nil];
    if (!b) { munmap(p, (size_t)len); fprintf(stderr, "llms shm cache: newBufferWithBytesNoCopy failed for slab %d\n", k); }
    else g_llms_shm_bufs[k] = b;
    return b;
}


typedef struct { uint64_t magic; char key[256]; volatile uint64_t valid; uint64_t bytes; } llms_bshm_hdr;
#define LLMS_BSHM_MAGIC 0x314B4E4142505344ull   /* "DSPBANK1" */
static llms_bshm_hdr *g_llms_bshm_hdr;
int ds4_gpu_llms_shm_holder(void) { return g_llms_shm_ok == 1; }
ds4_gpu_tensor *ds4_gpu_llms_shm_tensor(uint64_t bytes, const char *key, int *valid_out) {
    *valid_out = 0;
    if (g_llms_shm_ok != 1 || bytes == 0 || !key || !g_device) return NULL;
    const uint64_t pg = 16384u, hlen = pg, dlen = (bytes + pg - 1u) / pg * pg, len = hlen + dlen;
    int fd = shm_open(llms_shm_name(1), O_CREAT | O_RDWR, 0600); if (fd < 0) { perror("llms dsp bank shm: shm_open"); return NULL; }
    struct stat st; if (fstat(fd, &st) != 0) { close(fd); return NULL; }
    if (st.st_size != (off_t)len) {   /* another size: recreate (macOS takes one ftruncate per object) */
        if (st.st_size != 0) { close(fd); shm_unlink(llms_shm_name(1)); fd = shm_open(llms_shm_name(1), O_CREAT | O_EXCL | O_RDWR, 0600); if (fd < 0) { perror("llms dsp bank shm: recreate"); return NULL; } }
        if (ftruncate(fd, (off_t)len) != 0) { perror("llms dsp bank shm: ftruncate"); close(fd); return NULL; }
    }
    void *p = mmap(NULL, (size_t)len, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0); close(fd);
    if (p == MAP_FAILED) { perror("llms dsp bank shm: mmap"); return NULL; }
    llms_bshm_hdr *h = (llms_bshm_hdr *)p;
    const int match = h->magic == LLMS_BSHM_MAGIC && h->valid == 1 && h->bytes == bytes && !strncmp(h->key, key, sizeof h->key);
    if (!match) { h->valid = 0; __atomic_thread_fence(__ATOMIC_SEQ_CST); h->magic = LLMS_BSHM_MAGIC; h->bytes = bytes; snprintf(h->key, sizeof h->key, "%s", key); }
    @autoreleasepool {
        DS4MetalTensor *tensor = [DS4MetalTensor new];
        tensor.buffer = [g_device newBufferWithBytesNoCopy:(uint8_t *)p + hlen length:(NSUInteger)dlen options:MTLResourceStorageModeShared deallocator:nil];
        if (!tensor.buffer) { munmap(p, (size_t)len); fprintf(stderr, "llms dsp bank shm: newBufferWithBytesNoCopy failed\n"); return NULL; }
        tensor.offset = 0; tensor.bytes = dlen; tensor.owner = 1;
        uint64_t live_snap = 0, peak_snap = 0;
        pthread_mutex_lock(&g_tensor_mu);
        const int tracked = ds4_gpu_tensor_track_alloc_locked((__bridge const void *)tensor, dlen, &live_snap, &peak_snap);
        pthread_mutex_unlock(&g_tensor_mu);
        if (!tracked) { tensor.buffer = nil; munmap(p, (size_t)len); return NULL; }
        g_llms_bshm_hdr = h; *valid_out = match;
        return (__bridge_retained ds4_gpu_tensor *)tensor;
    }
}
void ds4_gpu_llms_shm_tensor_valid(void) { if (g_llms_bshm_hdr) { __atomic_thread_fence(__ATOMIC_SEQ_CST); g_llms_bshm_hdr->valid = 1; } }
static void llms_shm_early(void);   /* llms SHM_CACHE: defined after llms_ed_prealloc; called at the first touch of the cache */
static void llms_shm_gen_bump(uint32_t slot) { if (g_llms_shm_ok == 1 && g_llms_shm_hdr && slot < DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) __atomic_fetch_add(&g_llms_shm_hdr->gen[slot], 1u, __ATOMIC_SEQ_CST); }
static void llms_sbg_start(uint32_t budget, uint64_t slot) {   /* called by the slot seed once the stride is fixed */
    const char *e = getenv("LLMS_DS4_SLAB_BG");
    if (!(e && *e && *e != '0') || slot == 0 || budget == 0 || !g_device || g_llms_sbg_plan) return;
    ds4_gpu_llms_startup_mark("sbg: admission begins");   /* llms STARTUP_LOG */
    llms_mg_admit_slabs(budget, slot);   /* llms MEMGUARD (2): the whole plan, before any slab or shm segment exists */
    ds4_gpu_llms_startup_mark("sbg: admission done");
    uint64_t per64 = ds4_gpu_stream_expert_slab_target_bytes() / slot; if (per64 == 0) per64 = 1;
    uint32_t total = 0; int n = 0;
    while (total < budget && n < 64) { const uint32_t sl = per64 > budget - total ? budget - total : (uint32_t)per64; g_llms_sbg_len[n++] = (uint64_t)sl * slot; total += sl; }
    g_llms_sbg_plan = n; const double t0 = llms_sbg_now_ms();
    if (llms_shm_on()) { pthread_mutex_lock(&g_llms_shm_mu); if (g_llms_shm_ok < 0) llms_shm_attach(slot, budget); pthread_mutex_unlock(&g_llms_shm_mu); }   /* llms SHM_CACHE: attach before any slab or install */
    ds4_gpu_llms_startup_mark("sbg: shm attached");   /* llms STARTUP_LOG */
    fprintf(stderr, "llms: slab bg v2 (%d slab buffers for %u slots made AND made resident on a background queue from startup)\n", n, budget);
    atexit_b(^{ fprintf(stderr, "llms slab bg: %d planned, %d made in %.1f ms (background; residency %.1f ms of it), %d taken, %.1f ms waited by the cache\n", g_llms_sbg_plan, g_llms_sbg_made, g_llms_sbg_ms, g_llms_sbg_res_ms, g_llms_sbg_taken, g_llms_sbg_wait_ms); });
    ds4_gpu_llms_startup_mark("slab bg: dispatched");   /* llms STARTUP_LOG */
    static int sbgpar = -1; if (sbgpar < 0) { const char *ev = getenv("LLMS_DS4_SBG_PAR"); sbgpar = ev && *ev && *ev != '0';
        if (sbgpar) fprintf(stderr, "llms: sbg par (the planned slabs built concurrently, one residency set each)\n"); }
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ds4_gpu_llms_startup_mark("slab bg: thread running");


        if (sbgpar) {
            static __strong id own_sets[64]; static uint64_t done_mask; static pthread_mutex_t qmu = PTHREAD_MUTEX_INITIALIZER;
            dispatch_apply((size_t)g_llms_sbg_plan, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^(size_t kk) {
                const int k = (int)kk;
                id<MTLBuffer> b = llms_shm_slab(k, g_llms_sbg_len[k], slot, budget);
                if (!b) b = [g_device newBufferWithLength:(NSUInteger)g_llms_sbg_len[k] options:MTLResourceStorageModeShared];
                double rms = 0.0;
                if (b) { b.label = @"ds4_stream_expert_slab"; const double r0 = llms_sbg_now_ms();
                    if (g_llms_sr < 0) { const char *e2 = getenv("LLMS_DS4_SLAB_RESIDENCY"); g_llms_sr = e2 && *e2 && *e2 != '0'; }
#if TARGET_OS_OSX
                    if (g_llms_sr) { if (@available(macOS 15.0, *)) {
                        MTLResidencySetDescriptor *d = [[MTLResidencySetDescriptor alloc] init]; d.label = @"llms_slab_own"; d.initialCapacity = 1; NSError *er = nil;
                        id<MTLResidencySet> rs = [g_device newResidencySetWithDescriptor:d error:&er];
                        if (rs) { [rs addAllocation:b]; [rs commit]; [rs requestResidency];
                                  pthread_mutex_lock(&qmu); own_sets[k] = rs; if (g_queue && [g_queue respondsToSelector:@selector(addResidencySet:)]) [g_queue addResidencySet:rs]; g_llms_sr_n++; pthread_mutex_unlock(&qmu); }
                    } }
#endif
                    rms = llms_sbg_now_ms() - r0; }
                pthread_mutex_lock(&g_llms_sbg_mu);
                g_llms_sbg_res_ms += rms;
                if (!g_llms_sbg_stop) g_llms_sbg_buf[k] = b;
                if (b) done_mask |= 1ull << k; else g_llms_sbg_stop = 1;
                while (g_llms_sbg_made < g_llms_sbg_plan && ((done_mask >> g_llms_sbg_made) & 1ull)) g_llms_sbg_made++;
                g_llms_sbg_ms = llms_sbg_now_ms() - t0; pthread_cond_broadcast(&g_llms_sbg_cv); pthread_mutex_unlock(&g_llms_sbg_mu);
            });
            ds4_gpu_llms_startup_mark("slab bg: all made");
            return;
        }
        for (int k = 0; k < g_llms_sbg_plan; k++) {
            pthread_mutex_lock(&g_llms_sbg_mu); const int stop = g_llms_sbg_stop; pthread_mutex_unlock(&g_llms_sbg_mu); if (stop) break;
            id<MTLBuffer> b = llms_shm_slab(k, g_llms_sbg_len[k], slot, budget);   /* llms SHM_CACHE: slab k from its shm segment, else as before */
            if (!b) b = [g_device newBufferWithLength:(NSUInteger)g_llms_sbg_len[k] options:MTLResourceStorageModeShared];
            if (b) { b.label = @"ds4_stream_expert_slab"; const double r0 = llms_sbg_now_ms(); llms_sr_add(b, g_llms_sbg_len[k]); g_llms_sbg_res_ms += llms_sbg_now_ms() - r0; }
            pthread_mutex_lock(&g_llms_sbg_mu); if (!g_llms_sbg_stop) g_llms_sbg_buf[k] = b; g_llms_sbg_made = k + 1; g_llms_sbg_ms = llms_sbg_now_ms() - t0; pthread_cond_broadcast(&g_llms_sbg_cv); pthread_mutex_unlock(&g_llms_sbg_mu);
            if (!b) { pthread_mutex_lock(&g_llms_sbg_mu); g_llms_sbg_stop = 1; pthread_cond_broadcast(&g_llms_sbg_cv); pthread_mutex_unlock(&g_llms_sbg_mu); break; }
        }
        ds4_gpu_llms_startup_mark("slab bg: all made");   /* llms STARTUP_LOG */
    });
}
static int llms_ld_mode(void); static uint64_t llms_ld_region(uint64_t bytes);   /* llms SLOT_SEED: defined below */
static void llms_slot_seed(uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {


    static int ss = -1; if (ss < 0) { const char *e = getenv("LLMS_DS4_SLOT_SEED"); ss = e && *e && *e != '0'; if (ss) fprintf(stderr, "llms: slot seed (the slab stride set at startup, not by the first install; the ED preallocation latch cleared with the slabs)\n"); }
    if (!ss || g_stream_expert_cache_slab_slot_bytes != 0 || gate_expert_bytes == 0 || down_expert_bytes == 0 || gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) return;
    uint64_t sb = gate_expert_bytes * 2ull + down_expert_bytes;
    if (llms_ld_mode()) sb = 2ull * llms_ld_region(gate_expert_bytes) + llms_ld_region(down_expert_bytes);
    const uint64_t page = (uint64_t)getpagesize(); if (page != 0) sb = round_up_u64(sb, page);
    if (sb != 0 && sb <= (uint64_t)NSUIntegerMax) { g_stream_expert_cache_slab_slot_bytes = sb; fprintf(stderr, "llms slot seed: stride %llu bytes\n", (unsigned long long)sb); }
    llms_sbg_start(ds4_gpu_stream_expert_cache_configured_budget(), g_stream_expert_cache_slab_slot_bytes);   /* llms SLAB_BG v2 */
}
void ds4_gpu_llms_slot_seed(uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {   /* llms SLOT_SEED at STARTUP (ds4.c, after the class is pinned; the probe 11:58 showed note_expert_size is first reached at the first install) */
    ds4_gpu_llms_startup_mark("seed: entry");   /* llms STARTUP_LOG */
    if (llms_gubs() && gate_expert_bytes == LLMS_BS6C_IQ2_GATE) gate_expert_bytes = g_llms_gubs_matb;   /* as budget_for_expert_size adjusts before note_expert_size, and as the cache task carries it */
    if (llms_g32d() && down_expert_bytes == LLMS_BS6C_DOWN) down_expert_bytes = g_llms_g32d_matb;   /* llms G32D: the slab stride with the side file's down */
    ds4_gpu_llms_startup_mark("seed: side files ready");   /* llms STARTUP_LOG */
    llms_slot_seed(gate_expert_bytes, down_expert_bytes);
}
static int ds4_gpu_stream_expert_cache_note_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (llms_g32d() && down_expert_bytes == LLMS_BS6C_DOWN) down_expert_bytes = g_llms_g32d_matb;   /* llms G32D: one size class with the side file's down */
    if (gate_expert_bytes == 0 || down_expert_bytes == 0) return 0;
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        fprintf(stderr, "ds4: Metal streaming expert cache byte size overflow\n");
        return 0;
    }
    /*
     * The cache is a single-size-class slab allocator: the expert byte size is
     * frozen on first sight (or pre-seeded at startup from the model's slab
     * class) and off-size layers are REJECTED rather than adopted. A rejected
     * layer (mixed-precision boost: Q4_K experts among IQ2 layers) falls back
     * to the mapped-model per-expert path; last-writer-wins here would instead
     * poison the slab size class and deadlock slab reuse.
     */
    const uint64_t bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (g_stream_expert_cache_expert_bytes == 0) {
        g_stream_expert_cache_expert_bytes = bytes;
        llms_slot_seed(gate_expert_bytes, down_expert_bytes);   /* llms SLOT_SEED: an accepted first-sight caller */
        return 1;
    }
    if (bytes != g_stream_expert_cache_expert_bytes && g_llms_gubs > 0 && gate_expert_bytes == LLMS_BS6C_IQ2_GATE) g_llms_gubs_rejects++;   /* llms BS6C */
    if (bytes == g_stream_expert_cache_expert_bytes) llms_slot_seed(gate_expert_bytes, down_expert_bytes);   /* llms SLOT_SEED: an accepted caller of the frozen class */
    if (bytes != g_stream_expert_cache_expert_bytes && llms_guards_on()) {
        static uint64_t rej, rej_x, first_b, first_c; static int rep;
        const int xl = llms_gubs() && gate_expert_bytes == g_llms_gubs_matb;   /* a translated install: never legitimately off-class */
        __sync_fetch_and_add(&rej, 1); if (xl && __sync_fetch_and_add(&rej_x, 1) == 0) { first_b = bytes; first_c = g_stream_expert_cache_expert_bytes;
            fprintf(stderr, "llms CLASS GUARD: a TRANSLATED expert install (%llu bytes) was rejected by the cache's size class (%llu bytes) -- the cache is BYPASSED for it (every use re-reads)\n",
                    (unsigned long long)first_b, (unsigned long long)first_c); }
        if (!__sync_lock_test_and_set(&rep, 1)) atexit_b(^{ fprintf(stderr, "llms class guard: %llu installs rejected by the size class, %llu of them translated (first %llu vs class %llu)\n",
            (unsigned long long)rej, (unsigned long long)rej_x, (unsigned long long)first_b, (unsigned long long)first_c); });
    }
    return bytes == g_stream_expert_cache_expert_bytes;
}

static uint32_t ds4_gpu_stream_expert_cache_requested_budget(void) {
    if (!g_ssd_streaming_mode) return 0;
    if (g_stream_expert_cache_budget_override != 0) {
        return g_stream_expert_cache_budget_override;
    }
    return 0;
}

static uint32_t ds4_gpu_stream_expert_cache_configured_budget(void) {
    uint32_t budget = ds4_gpu_stream_expert_cache_requested_budget();
    if (budget != 0 &&
        g_stream_expert_cache_mlock_budget_cap != 0 &&
        budget > g_stream_expert_cache_mlock_budget_cap) {
        budget = g_stream_expert_cache_mlock_budget_cap;
    }
    return budget;
}

static uint32_t ds4_gpu_stream_expert_cache_effective_cap(
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t n_selected) {
    (void)layer;
    if (ds4_gpu_stream_expert_cache_configured_budget() == 0) return 0;

    /*
     * The residency policy is global: every layer can use any expert slot it
     * routes to, and global pruning decides which existing entry is least
     * valuable.  A per-layer cap made cache size depend on model depth rather
     * than the actual byte budget.
     */
    uint32_t cap = n_total_expert;
    if (cap < n_selected) cap = n_selected;
    if (cap > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        cap = DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    }
    return cap;
}

static int ds4_gpu_stream_expert_timing_summary_enabled(void) {
    static int checked = 0;
    static int enabled = 0;
    if (!checked) {
        enabled =
            (getenv("DS4_METAL_STREAMING_EXPERT_TIMING_SUMMARY") != NULL ||
             getenv("DS4_METAL_STREAMING_EXPERT_PROFILE_SUMMARY") != NULL) &&
            getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_TIMING_SUMMARY") == NULL;
        checked = 1;
    }
    return enabled;
}

static uint32_t ds4_gpu_stream_expert_popcount(uint32_t mask) {
    return (uint32_t)__builtin_popcount(mask);
}

static int ds4_gpu_stream_expert_split_worthwhile(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (resident_mask == 0 || missing_mask == 0) return 0;
    /*
     * The split path pays an extra command stage and a second routed-expert
     * bind.  It is worthwhile when several experts are missing and their SSD
     * reads can be hidden by resident expert work.  With one or two misses,
     * especially in large caches, a single unsplit routed pass is faster.
     */
    return ds4_gpu_stream_expert_popcount(missing_mask) >= 3u;
}

static void ds4_gpu_stream_expert_timing_note_selected(
        double sync_ms,
        double copy_ms,
        double bind_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_selected_calls++;
    g_stream_expert_timing_selected_sync_ms += sync_ms;
    g_stream_expert_timing_selected_copy_ms += copy_ms;
    g_stream_expert_timing_selected_read_ms += sync_ms + copy_ms;
    g_stream_expert_timing_selected_bind_ms += bind_ms;
}

static void ds4_gpu_stream_expert_timing_note_split(
        uint32_t resident_mask,
        uint32_t missing_mask,
        double   resident_ms,
        double   missing_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_layers++;
    g_stream_expert_timing_split_resident_experts +=
        ds4_gpu_stream_expert_popcount(resident_mask);
    g_stream_expert_timing_split_missing_experts +=
        ds4_gpu_stream_expert_popcount(missing_mask);
    g_stream_expert_timing_split_resident_ms += resident_ms;
    g_stream_expert_timing_split_missing_ms += missing_ms;
}

static void ds4_gpu_stream_expert_timing_note_split_missing_detail(
        double load_ms,
        double slot_ms,
        double prune_ms,
        double addr_ms,
        double wait_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_split_missing_load_ms += load_ms;
    g_stream_expert_timing_split_missing_slot_ms += slot_ms;
    g_stream_expert_timing_split_missing_prune_ms += prune_ms;
    g_stream_expert_timing_split_missing_addr_ms += addr_ms;
    g_stream_expert_timing_split_missing_wait_ms += wait_ms;
}

static void ds4_gpu_stream_expert_timing_note_load_detail(
        double prepare_ms,
        double pread_ms,
        double install_ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_load_calls++;
    g_stream_expert_timing_load_prepare_ms += prepare_ms;
    g_stream_expert_timing_load_pread_ms += pread_ms;
    g_stream_expert_timing_load_install_ms += install_ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_batch_reuse(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_batch_reuse_calls++;
    g_stream_expert_timing_prepare_batch_reuse_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_buffer(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_buffer_calls++;
    g_stream_expert_timing_prepare_buffer_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_prepare_task(
        uint32_t experts,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_prepare_task_experts += experts;
    g_stream_expert_timing_prepare_task_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_reuse_scan(
        uint64_t entries,
        double   ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_reuse_scan_calls++;
    g_stream_expert_timing_reuse_scan_entries += entries;
    g_stream_expert_timing_reuse_scan_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_reuse_clear(double ms) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    g_stream_expert_timing_reuse_clear_ms += ms;
}

static void ds4_gpu_stream_expert_timing_note_cache_class(
        uint32_t resident_mask,
        uint32_t missing_mask) {
    if (!ds4_gpu_stream_expert_timing_summary_enabled()) return;
    const uint32_t resident = ds4_gpu_stream_expert_popcount(resident_mask);
    const uint32_t missing = ds4_gpu_stream_expert_popcount(missing_mask);
    if (missing == 0) {
        g_stream_expert_timing_cache_all_resident_layers++;
    } else if (resident == 0) {
        g_stream_expert_timing_cache_all_missing_layers++;
    } else {
        g_stream_expert_timing_cache_mixed_layers++;
    }
    g_stream_expert_timing_cache_resident_experts += resident;
    g_stream_expert_timing_cache_missing_experts += missing;
}

static int ds4_gpu_stream_expert_readahead_enabled(void) {
    return g_ssd_streaming_mode && g_model_fd_nocache < 0 &&   /* llms: no page-cache hint for uncached preads */
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_READAHEAD") == NULL;
}

static void ds4_gpu_stream_expert_readahead_range(uint64_t offset, uint64_t len) {
    if (!ds4_gpu_stream_expert_readahead_enabled() || g_model_fd < 0 || len == 0) {
        return;
    }

#if defined(F_RDADVISE)
    const int timing = ds4_gpu_stream_expert_timing_summary_enabled();
    const double t0 = timing ? ds4_gpu_now_ms() : 0.0;
    uint64_t pos = offset;
    uint64_t rem = len;
    while (rem > 0) {
        const uint64_t chunk64 =
            rem > (uint64_t)INT_MAX ? (uint64_t)INT_MAX : rem;
        if (pos > (uint64_t)LLONG_MAX) break;

        struct radvisory ra;
        ra.ra_offset = (off_t)pos;
        ra.ra_count = (int)chunk64;
        (void)fcntl(g_model_fd, F_RDADVISE, &ra);

        pos += chunk64;
        rem -= chunk64;
    }
    if (timing) {
        g_stream_expert_timing_readahead_calls++;
        g_stream_expert_timing_readahead_bytes += len;
        g_stream_expert_timing_readahead_ms += ds4_gpu_now_ms() - t0;
    }
#else
    (void)offset;
    (void)len;
#endif
}

typedef struct {
    uint64_t offset;
    uint64_t len;
    uint8_t *dst;
    uint64_t read_bytes;
    double ms;
    int ok;
} ds4_gpu_stream_expert_read_task;
static void llms_psb_report(void) { fprintf(stderr, "llms static state: prepare_selected_batch %llu calls, %llu heap ids, %llu heap tasks (concurrent / oversize)\n",
    (unsigned long long)g_llms_psb_calls, (unsigned long long)g_llms_psb_heap_ids, (unsigned long long)g_llms_psb_heap_tasks); }
static int32_t *llms_psb_take_ids(uint64_t n) {
    static int reg; if (!reg) { reg = 1; atexit(llms_psb_report); }
    g_llms_psb_calls++;
    int z = 0; if (n <= LLMS_PSB_MAX_IDS && atomic_compare_exchange_strong(&g_llms_psb_ids_busy, &z, 1)) return g_llms_psb_ids;
    g_llms_psb_heap_ids++; return malloc((size_t)n * sizeof(int32_t));
}
static void llms_psb_give_ids(int32_t *p) { if (p == g_llms_psb_ids) atomic_store(&g_llms_psb_ids_busy, 0); else free(p); }
static ds4_gpu_stream_expert_read_task *llms_psb_take_tasks(uint64_t n) {
    int z = 0; if (n <= LLMS_PSB_MAX_TASKS && atomic_compare_exchange_strong(&g_llms_psb_tasks_busy, &z, 1)) {
        memset(g_llms_psb_tasks, 0, (size_t)n * sizeof(ds4_gpu_stream_expert_read_task)); return (ds4_gpu_stream_expert_read_task *)g_llms_psb_tasks; }
    g_llms_psb_heap_tasks++; return calloc((size_t)n, sizeof(ds4_gpu_stream_expert_read_task));
}
static void llms_psb_give_tasks(ds4_gpu_stream_expert_read_task *p) { if ((unsigned char *)p == g_llms_psb_tasks) atomic_store(&g_llms_psb_tasks_busy, 0); else free(p); }
_Static_assert(sizeof(ds4_gpu_stream_expert_read_task) <= LLMS_PSB_TASK_BYTES, "llms STATIC_STATE: task storage too small");   /* llms STATIC_STATE */

typedef struct {
    int active;
    const void *model_map;
    uint64_t model_size;
    uint32_t layer;
    uint32_t n_total_expert;
    uint32_t n_selected;
    uint32_t missing_mask;
    uint32_t load_slots[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint32_t source_slots[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint32_t n_loads;
    uint32_t n_tasks;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    int32_t selected_ids[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint64_t gate_abs_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint64_t up_abs_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    uint64_t down_abs_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    __strong id<MTLBuffer> gate_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    __strong id<MTLBuffer> up_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    __strong id<MTLBuffer> down_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    NSUInteger gate_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    NSUInteger up_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    NSUInteger down_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
    ds4_gpu_stream_expert_read_task tasks[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED * 3u];
    double start_ms;
    double prepare_ms;
} ds4_gpu_stream_expert_pending_load;

static ds4_gpu_stream_expert_pending_load g_stream_expert_pending_load;

typedef struct {
    int active;
    const void *model_map;
    uint64_t model_size;
    uint32_t layer;
    uint32_t n_total_expert;
    uint32_t n_selected;
    uint64_t gate_offset;
    uint64_t up_offset;
    uint64_t down_offset;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    int32_t selected_ids[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED];
} ds4_gpu_glm_stream_selected_prefetch;

static ds4_gpu_glm_stream_selected_prefetch g_glm_stream_selected_prefetch;

