    ds4_gpu_stream_expert_read_task *tasks;
    uint32_t n_tasks;
    uint32_t worker_index;
    uint32_t n_workers;
} ds4_gpu_stream_expert_pread_worker_args;

static void ds4_gpu_stream_expert_cache_note_read(
        uint32_t layer,
        uint64_t bytes,
        double   ms) {
    if (g_stream_expert_cache_read_bytes > UINT64_MAX - bytes) {
        g_stream_expert_cache_read_bytes = UINT64_MAX;
    } else {
        g_stream_expert_cache_read_bytes += bytes;
    }
    g_stream_expert_cache_pread_ms += ms;
    if (layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        if (g_stream_expert_cache_layer_read_bytes[layer] > UINT64_MAX - bytes) {
            g_stream_expert_cache_layer_read_bytes[layer] = UINT64_MAX;
        } else {
            g_stream_expert_cache_layer_read_bytes[layer] += bytes;
        }
        g_stream_expert_cache_layer_read_ms[layer] += ms;
    }
}

static uint32_t ds4_gpu_stream_expert_pread_thread_limit(void) {
    uint32_t threads = 9;
    const char *env = getenv("DS4_METAL_STREAMING_EXPERT_PREAD_THREADS");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long v = strtoul(env, &end, 10);
        if (end != env && *end == '\0') {
            threads = v > UINT32_MAX ? UINT32_MAX : (uint32_t)v;
        }
    }
    if (threads == 0) threads = 1;
    if (threads > 32) threads = 32;   /* llms: was 18 */
    return threads;
}

static uint32_t ds4_gpu_stream_expert_pread_thread_count(uint32_t n_tasks) {
    if (n_tasks <= 1) return n_tasks;
    uint32_t threads = ds4_gpu_stream_expert_pread_thread_limit();
    if (threads > n_tasks) threads = n_tasks;
    return threads;
}

/* llms LOAD_DIRECT (apply_ds4_load_direct.py): expert loads read straight into the cache slot, no scratch copy */
#define LLMS_LD_P 16384ull
static int g_llms_ld = -1;   /* 0 off, 1 on, 2 canary, 3 verify */
static uint8_t *g_llms_ld_lo[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SLABS], *g_llms_ld_hi[DS4_METAL_STREAM_EXPERT_CACHE_MAX_SLABS];
static volatile uint32_t g_llms_ld_slabs;
static uint64_t g_llms_ld_reads, g_llms_ld_bytes, g_llms_ld_phased, g_llms_ld_cmp, g_llms_ld_differ;
static uint64_t g_llms_aligned_reads, g_llms_aligned_bytes;
static void llms_ld_report(void) {
    fprintf(stderr, "llms load direct (mode %d): %llu reads in place, %.3f GB; %llu reads through the scratch copy, %.3f GB; %llu slot offsets given the file phase; verify: %llu ranges compared, %llu differ\n",
            g_llms_ld, (unsigned long long)g_llms_ld_reads, (double)g_llms_ld_bytes / 1e9, (unsigned long long)g_llms_aligned_reads, (double)g_llms_aligned_bytes / 1e9,
            (unsigned long long)g_llms_ld_phased, (unsigned long long)g_llms_ld_cmp, (unsigned long long)g_llms_ld_differ);
}
static int llms_ld_mode(void) {
    if (g_llms_ld < 0) {
        const char *e = getenv("LLMS_DS4_LOAD_DIRECT"), *ch = getenv("LLMS_DS4_PREAD_CHUNK");
        int v = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 2 : !strcmp(e, "verify") ? 3 : 1;
        if (v && ((ch && *ch && *ch != '0' && (strtoull(ch, NULL, 10) % LLMS_LD_P) != 0) || (uint64_t)getpagesize() != LLMS_LD_P)) {   /* llms LOAD_DIRECT pieces: a piece size in whole pages is cut at page boundaries of the file */
            fprintf(stderr, "llms load direct: off (LLMS_DS4_PREAD_CHUNK is not a multiple of 16384, or the page size is not 16384)\n"); v = 0;
        }
        if (__sync_bool_compare_and_swap(&g_llms_ld, -1, v) && v) atexit(llms_ld_report);
    }
    return g_llms_ld;
}
static uint64_t llms_ld_region(uint64_t bytes) { return ((bytes + LLMS_LD_P - 1ull) & ~(LLMS_LD_P - 1ull)) + LLMS_LD_P; }
static int llms_ld_in_slab(const uint8_t *p, uint64_t n) {   /* reader threads: plain ranges only */
    if (((uintptr_t)p & (uintptr_t)(LLMS_LD_P - 1ull)) != 0) return 0;
    const uint32_t k = g_llms_ld_slabs;
    for (uint32_t i = 0; i < k; i++) if (p >= g_llms_ld_lo[i] && p + n <= g_llms_ld_hi[i]) return 1;
    return 0;
}
static NSUInteger llms_ld_inner(id<MTLBuffer> buf, NSUInteger inner, uint64_t file_offset) {   /* main thread, at the load sites */
    if (!buf || !llms_ld_mode()) return inner;
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        if (g_stream_expert_cache_slabs[i] != buf) continue;
        g_llms_ld_phased++;
        return (NSUInteger)(((uint64_t)inner & ~(LLMS_LD_P - 1ull)) + (file_offset & (LLMS_LD_P - 1ull)));
    }
    return inner;
}
static void llms_aligned_report(void) { fprintf(stderr, "llms aligned pread: %llu reads, %.3f GB\n", (unsigned long long)g_llms_aligned_reads, (double)g_llms_aligned_bytes / 1e9); }



static __thread int g_llms_is_reader, g_llms_rq_cur = -1; static uint32_t g_llms_rq_switch;
static int llms_alt_off(const char *name);
static void llms_rq_alt_report(void) { fprintf(stderr, "llms reader qos alt: %u class switches in reader threads\n", g_llms_rq_switch); }
static void llms_reader_qos_alt(void) {
    static int on = -1; if (on < 0) { const char *e = getenv("LLMS_DS4_READER_QOS_ALT"); on = e && *e && *e != '0'; if (on) { fprintf(stderr, "llms: reader qos follows ALT 'rqbg' (background while on)\n"); atexit(llms_rq_alt_report); } }
    if (!on || !g_llms_is_reader) return;
    const int want = !llms_alt_off("rqbg");
    if (want != g_llms_rq_cur) { pthread_set_qos_class_self_np(want ? QOS_CLASS_BACKGROUND : QOS_CLASS_DEFAULT, 0); g_llms_rq_cur = want; __sync_fetch_and_add(&g_llms_rq_switch, 1); }
}





static uint64_t g_llms_g32_blocks, g_llms_g32_bytes;
static int llms_g32sim_on(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_DOWN_G32SIM"); on = e && *e && *e != '0';
                  if (on) { fprintf(stderr, "llms: down g32sim -- FIDELITY PROBE: every routed q2_K down re-quantized with one scale / min per 32 inputs\n");
                            atexit_b(^{ fprintf(stderr, "llms down g32sim: %llu blocks, %llu bytes transformed\n", (unsigned long long)g_llms_g32_blocks, (unsigned long long)g_llms_g32_bytes); }); } }
    return on;
}
static void llms_g32sim(uint8_t *dst, uint64_t len) {
    if (len % 84u) return;
    const uint64_t nb = len / 84u;
    for (uint64_t b = 0; b < nb; b++) {
        uint8_t *blk = dst + b * 84u; uint8_t *sc = blk, *qs = blk + 16;
        __fp16 dh, mh; memcpy(&dh, blk + 80, 2); memcpy(&mh, blk + 82, 2);
        const float d = (float)dh, dmin = (float)mh;
        for (int p = 0; p < 8; p++) {   /* sub-blocks 2p, 2p+1 = 32 consecutive inputs: half n = p / 4, shift 2 (p % 4); q[l] / q[l + 16] */
            const int n = p >> 2, sh = 2 * (p & 3); uint8_t *q = qs + 32 * n;
            float v[32]; const int is0 = 2 * p, is1 = 2 * p + 1;
            for (int l = 0; l < 16; l++) { v[l] = d * (float)(sc[is0] & 15) * (float)((q[l] >> sh) & 3) - dmin * (float)(sc[is0] >> 4);
                                           v[16 + l] = d * (float)(sc[is1] & 15) * (float)((q[l + 16] >> sh) & 3) - dmin * (float)(sc[is1] >> 4); }
            float lo = v[0], hi = v[0]; for (int i = 1; i < 32; i++) { if (v[i] < lo) lo = v[i]; if (v[i] > hi) hi = v[i]; }
            int cs[3], cm[3];
            cs[0] = sc[is0] & 15; cm[0] = sc[is0] >> 4; cs[1] = sc[is1] & 15; cm[1] = sc[is1] >> 4;
            { int mm = dmin > 0.0f ? (int)lrintf((lo < 0.0f ? -lo : 0.0f) / dmin) : 0; if (mm > 15) mm = 15; if (mm < 0) mm = 0;
              int ss = d > 0.0f ? (int)lrintf((hi + dmin * (float)mm) / (3.0f * d)) : 0; if (ss > 15) ss = 15; if (ss < 0) ss = 0; cs[2] = ss; cm[2] = mm; }
            int best = 0; float be = 3.4e38f; uint8_t bq[32];
            for (int c = 0; c < 3; c++) {
                const float dl = d * (float)cs[c], ml = dmin * (float)cm[c]; float err = 0.0f; uint8_t qq[32];
                for (int i = 0; i < 32; i++) { int k = dl > 0.0f ? (int)lrintf((v[i] + ml) / dl) : 0; if (k < 0) k = 0; if (k > 3) k = 3; qq[i] = (uint8_t)k;
                                               const float r = dl * (float)k - ml - v[i]; err += r * r; }
                if (err < be) { be = err; best = c; memcpy(bq, qq, 32); }
            }
            sc[is0] = sc[is1] = (uint8_t)(cs[best] | (cm[best] << 4));
            const uint8_t mk = (uint8_t)~(3u << sh);
            for (int l = 0; l < 16; l++) { q[l] = (uint8_t)((q[l] & mk) | (bq[l] << sh)); q[l + 16] = (uint8_t)((q[l + 16] & mk) | (bq[16 + l] << sh)); }
        }
    }
    __atomic_fetch_add(&g_llms_g32_blocks, nb, __ATOMIC_RELAXED); __atomic_fetch_add(&g_llms_g32_bytes, len, __ATOMIC_RELAXED);
}




static uint64_t g_llms_landed_n[3], g_llms_landed_b[3]; static int g_llms_landed_rep;
static void llms_expert_read_landed(int path, int fd, uint8_t *dst, uint64_t len) {
    if (!__atomic_exchange_n(&g_llms_landed_rep, 1, __ATOMIC_RELAXED))
        atexit_b(^{ fprintf(stderr, "llms expert reads landed: pread %llu (%.2f GB), aio sync %llu (%.2f GB), aio ticket %llu (%.2f GB) -- every expert byte lands in llms_expert_read_landed\n",
                            (unsigned long long)g_llms_landed_n[0], (double)g_llms_landed_b[0] / 1e9, (unsigned long long)g_llms_landed_n[1], (double)g_llms_landed_b[1] / 1e9,
                            (unsigned long long)g_llms_landed_n[2], (double)g_llms_landed_b[2] / 1e9); });
    __atomic_fetch_add(&g_llms_landed_n[path], 1, __ATOMIC_RELAXED); __atomic_fetch_add(&g_llms_landed_b[path], len, __ATOMIC_RELAXED);
    const int from_model = !(g_llms_gubs_fd >= 0 && fd == g_llms_gubs_fd);   /* the routed down (and every non-BS64 part) comes from the model file */
    if (from_model && llms_g32sim_on()) llms_g32sim(dst, len);
    {
        static int ms = -1; static uint64_t ms_gu, ms_dn, ms_skip;
        if (ms < 0) { const char *e = getenv("LLMS_DS4_MISSTIER_SIM"); ms = e && *e && *e != '0';
            if (ms) { fprintf(stderr, "llms: MISSTIER_SIM (synchronous decode expert loads degraded in place to one bit: x := y in every plane pair)\n");
                      atexit_b(^{ fprintf(stderr, "llms misstier sim: %llu gate/up matrices and %llu downs degraded; %llu sync reads of other sizes left\n",
                                          (unsigned long long)ms_gu, (unsigned long long)ms_dn, (unsigned long long)ms_skip); }); } }
        if (ms && path == 1) {
            const uint32_t ph = __atomic_load_n(&g_llms_tl_phase, __ATOMIC_RELAXED);
            if (!(ph == 2u || ph == 3u)) {
                if (len == 3225600ull) { for (uint32_t r = 0; r < 2304u; r++) { uint32_t *w = (uint32_t *)(dst + (uint64_t)r * 1400u); for (uint32_t i = 0; i < 160u; i++) w[2u * i] = w[2u * i + 1u]; }
                                         __atomic_fetch_add(&ms_gu, 1, __ATOMIC_RELAXED); }
                else if (len == 3502080ull) { uint32_t *w = (uint32_t *)dst; for (uint32_t i = 0; i < 72u * 5120u; i++) w[2u * i] = w[2u * i + 1u]; __atomic_fetch_add(&ms_dn, 1, __ATOMIC_RELAXED); }
                else __atomic_fetch_add(&ms_skip, 1, __ATOMIC_RELAXED);
            }
        }
    }
}
static int llms_expert_read_pread(
        uint64_t  offset,
        uint64_t  len,
        uint8_t  *dst,
        uint64_t *read_bytes,
        double   *ms_out) {
    llms_reader_qos_alt();   /* llms READER_QOS_ALT */
    const int llms_bfd = llms_gubs_src(&offset, g_model_fd_nocache);   /* llms BS6C: a flagged offset reads the side file */
    if (read_bytes) *read_bytes = 0;
    if (ms_out) *ms_out = 0.0;
    if (g_model_fd < 0 ||
        !dst ||
        len == 0 ||
        offset > (uint64_t)LLONG_MAX ||
        len > (uint64_t)LLONG_MAX - offset) {
        return 0;
    }

    {   /* llms LLMS_DS4_PREAD_ALIGNED: aligned superset into aligned scratch (direct I/O), then copy */
        static int llms_al = -1;
        if (llms_al < 0) { const char *e = getenv("LLMS_DS4_PREAD_ALIGNED"); llms_al = e && *e && *e != '0'; if (llms_al) atexit(llms_aligned_report); }
        if (llms_al && llms_bfd >= 0) {
            static __thread uint8_t *scratch; static __thread uint64_t scratch_cap;
            const uint64_t A = 16384u, a0 = offset & ~(A - 1u), a1 = (offset + len + A - 1u) & ~(A - 1u), alen = a1 - a0;
            int llms_ld_check = 0;   /* llms LOAD_DIRECT verify: the range is already in place, compare instead of copying */
            if (llms_ld_mode() && llms_ld_in_slab(dst - (offset - a0), alen)) {   /* llms LOAD_DIRECT: the slot region is page-aligned at the file's phase */
                uint8_t *d0 = dst - (offset - a0);
                const double ta = ds4_gpu_now_ms();
                uint64_t got = 0; int aok = 1;
                while (got < alen) {
                    ssize_t nr;
                    do { nr = pread(llms_bfd, d0 + got, (size_t)(alen - got), (off_t)(a0 + got)); } while (nr < 0 && errno == EINTR);
                    if (nr < 0) { aok = 0; break; }
                    if (nr == 0) break;   /* end of file: the aligned tail may reach past it */
                    got += (uint64_t)nr;
                }
                if (aok && got >= (offset - a0) + len) {
                    __sync_fetch_and_add(&g_llms_ld_reads, 1); __sync_fetch_and_add(&g_llms_ld_bytes, len);
                    if (g_llms_ld == 2) memset(dst, 0, (size_t)(len < 4096u ? len : 4096u));   /* canary: the kernels must see it */
                    if (g_llms_ld != 3) {
                        if (read_bytes) *read_bytes = len;
                        if (ms_out) *ms_out = ds4_gpu_now_ms() - ta;
                        llms_expert_read_landed(0, llms_bfd, dst, len);
                        return 1;
                    }
                    llms_ld_check = 1;
                }
            }
            if (scratch_cap < alen) {
                free(scratch); scratch = NULL; scratch_cap = 0;
                if (posix_memalign((void **)&scratch, A, (size_t)(alen + A)) == 0) scratch_cap = alen + A;
            }
            if (scratch) {
                const double ta = ds4_gpu_now_ms();
                uint64_t got = 0; int aok = 1;
                while (got < alen) {
                    ssize_t nr;
                    do { nr = pread(llms_bfd, scratch + got, (size_t)(alen - got), (off_t)(a0 + got)); } while (nr < 0 && errno == EINTR);
                    if (nr < 0) { aok = 0; break; }
                    if (nr == 0) break;   /* end of file: the aligned tail may reach past it */
                    got += (uint64_t)nr;
                }
                if (aok && got >= (offset - a0) + len) {
                    if (llms_ld_check) {   /* llms LOAD_DIRECT verify */
                        __sync_fetch_and_add(&g_llms_ld_cmp, 1);
                        if (memcmp(dst, scratch + (offset - a0), (size_t)len) != 0) __sync_fetch_and_add(&g_llms_ld_differ, 1);
                    }
                    memcpy(dst, scratch + (offset - a0), (size_t)len);
                    __sync_fetch_and_add(&g_llms_aligned_reads, 1); __sync_fetch_and_add(&g_llms_aligned_bytes, len);
                    if (read_bytes) *read_bytes = len;
                    if (ms_out) *ms_out = ds4_gpu_now_ms() - ta;
                    llms_expert_read_landed(0, llms_bfd, dst, len);
                    return 1;
                }
            }
        }
    }
    const double t0 = ds4_gpu_now_ms();
    uint64_t pos = 0;
    int ok = 1;
    while (pos < len) {
        const uint64_t rem = len - pos;
        const size_t want = rem > (uint64_t)SSIZE_MAX ? (size_t)SSIZE_MAX : (size_t)rem;
        ssize_t nread;
        do {
            nread = pread(llms_bfd >= 0 ? llms_bfd : g_model_fd, dst + pos, want, (off_t)(offset + pos));
        } while (nread < 0 && errno == EINTR);
        if (nread <= 0) {
            ok = 0;
            break;
        }
        pos += (uint64_t)nread;
    }
    const double dt = ds4_gpu_now_ms() - t0;
    if (read_bytes) *read_bytes = pos;
    if (ms_out) *ms_out = dt;
    if (!ok || pos != len) {
        fprintf(stderr,
                "ds4: Metal streaming expert explicit pread failed offset=%.2f GiB len=%.2f MiB read=%.2f MiB\n",
                ds4_gpu_gib(offset),
                ds4_gpu_mib(len),
                ds4_gpu_mib(pos));
        return 0;
    }
    llms_expert_read_landed(0, llms_bfd >= 0 ? llms_bfd : g_model_fd, dst, len);
    return 1;
}

/* llms READER_QOS (apply_ds4_reader_qos.py): scheduling class of the reader threads, the load queue and the calling thread */
static int llms_qos_parse(const char *name, qos_class_t *out) {
    const char *e = getenv(name);
    if (!e || !*e) return 0;
    if (!strcmp(e, "ui")) *out = QOS_CLASS_USER_INTERACTIVE; else if (!strcmp(e, "in")) *out = QOS_CLASS_USER_INITIATED;
    else if (!strcmp(e, "ut")) *out = QOS_CLASS_UTILITY; else if (!strcmp(e, "bg")) *out = QOS_CLASS_BACKGROUND;
    else { fprintf(stderr, "llms reader qos: %s=%s is not one of ui|in|ut|bg; ignored\n", name, e); return 0; }
    return 1;
}
static uint32_t g_llms_rq_set, g_llms_rq_fail; static unsigned g_llms_rq_seen, g_llms_mq_seen; static int g_llms_rq_once;
static void llms_reader_qos_report(void) {
    fprintf(stderr, "llms reader qos: %u reader threads set their class (%u failed), a reader reads back 0x%x, the calling thread 0x%x (ui 0x21, in 0x19, default 0x15, ut 0x11, bg 0x09, unspecified 0x00)\n",
            g_llms_rq_set, g_llms_rq_fail, g_llms_rq_seen, g_llms_mq_seen);
}
static void llms_reader_qos_self(void) {   /* first thing a reader thread does */
    g_llms_is_reader = 1;   /* llms READER_QOS_ALT */
    qos_class_t q;
    if (!llms_qos_parse("LLMS_DS4_READER_QOS", &q)) return;
    if (pthread_set_qos_class_self_np(q, 0) == 0) __sync_fetch_and_add(&g_llms_rq_set, 1); else __sync_fetch_and_add(&g_llms_rq_fail, 1);
    g_llms_rq_seen = (unsigned)qos_class_self();
    if (__sync_bool_compare_and_swap(&g_llms_rq_once, 0, 1)) atexit(llms_reader_qos_report);
}
static void llms_main_qos_self(void) {   /* the thread that issues the first load ticket */
    qos_class_t q;
    if (!llms_qos_parse("LLMS_DS4_MAIN_QOS", &q)) return;
    if (pthread_set_qos_class_self_np(q, 0) != 0) fprintf(stderr, "llms reader qos: the calling thread could not set its class\n");
    g_llms_mq_seen = (unsigned)qos_class_self();
    if (__sync_bool_compare_and_swap(&g_llms_rq_once, 0, 1)) atexit(llms_reader_qos_report);
}

static void *ds4_gpu_stream_expert_pread_worker(void *arg) {
    ds4_gpu_stream_expert_pread_worker_args *wa =
        (ds4_gpu_stream_expert_pread_worker_args *)arg;
    llms_reader_qos_self();   /* llms READER_QOS */
    for (uint32_t i = wa->worker_index; i < wa->n_tasks; i += wa->n_workers) {
        ds4_gpu_stream_expert_read_task *task = &wa->tasks[i];
        task->ok = llms_expert_read_pread(task->offset,
                                                    task->len,
                                                    task->dst,
                                                    &task->read_bytes,
                                                    &task->ms);
    }
    return NULL;
}

static pthread_mutex_t g_stream_expert_pread_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_stream_expert_pread_pool_start_cond = PTHREAD_COND_INITIALIZER;
static pthread_cond_t g_stream_expert_pread_pool_done_cond = PTHREAD_COND_INITIALIZER;
static pthread_t g_stream_expert_pread_pool_threads[32];   /* llms: was 18 */
static uint32_t g_stream_expert_pread_pool_thread_count;
static uint32_t g_stream_expert_pread_pool_active_workers;
static uint32_t g_stream_expert_pread_pool_remaining_workers;
static uint32_t g_stream_expert_pread_pool_n_tasks;
static uint32_t g_stream_expert_pread_pool_next_task;
static uint64_t g_stream_expert_pread_pool_generation;
static ds4_gpu_stream_expert_read_task *g_stream_expert_pread_pool_tasks;
static int g_stream_expert_pread_pool_initialized;
static int g_stream_expert_pread_pool_stopping;

static int ds4_gpu_stream_expert_pread_pool_enabled(void) {
    const char *env = getenv("DS4_METAL_STREAMING_EXPERT_PREAD_POOL");
    return !(env && strcmp(env, "0") == 0);
}

static void *ds4_gpu_stream_expert_pread_pool_worker(void *arg) {
    const uint32_t worker_index = (uint32_t)(uintptr_t)arg;
    uint64_t seen_generation = 0;
    llms_reader_qos_self();   /* llms READER_QOS */

    for (;;) {
        pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
        while (!g_stream_expert_pread_pool_stopping &&
               g_stream_expert_pread_pool_generation == seen_generation) {
            pthread_cond_wait(&g_stream_expert_pread_pool_start_cond,
                              &g_stream_expert_pread_pool_mutex);
        }
        if (g_stream_expert_pread_pool_stopping) {
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            break;
        }

        seen_generation = g_stream_expert_pread_pool_generation;
        if (worker_index >= g_stream_expert_pread_pool_active_workers) {
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            continue;
        }

        for (;;) {
            const uint32_t task_index =
                g_stream_expert_pread_pool_next_task++;
            if (task_index >= g_stream_expert_pread_pool_n_tasks) break;

            ds4_gpu_stream_expert_read_task *task =
                &g_stream_expert_pread_pool_tasks[task_index];
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

            task->ok = llms_expert_read_pread(task->offset,
                                                        task->len,
                                                        task->dst,
                                                        &task->read_bytes,
                                                        &task->ms);

            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
        }

        if (g_stream_expert_pread_pool_remaining_workers > 0 &&
            --g_stream_expert_pread_pool_remaining_workers == 0) {
            g_stream_expert_pread_pool_tasks = NULL;
            g_stream_expert_pread_pool_n_tasks = 0;
            g_stream_expert_pread_pool_active_workers = 0;
            pthread_cond_signal(&g_stream_expert_pread_pool_done_cond);
        }
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    }

    return NULL;
}

static int ds4_gpu_stream_expert_pread_pool_init(uint32_t n_threads) {
    if (g_stream_expert_pread_pool_initialized) return 1;
    if (!ds4_gpu_stream_expert_pread_pool_enabled() || n_threads <= 1) return 0;
    if (n_threads > 32) n_threads = 32;   /* llms: was 18 */

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_thread_count = n_threads;
    g_stream_expert_pread_pool_stopping = 0;
    g_stream_expert_pread_pool_generation = 0;
    g_stream_expert_pread_pool_tasks = NULL;
    g_stream_expert_pread_pool_n_tasks = 0;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_active_workers = 0;
    g_stream_expert_pread_pool_remaining_workers = 0;
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

    uint32_t started = 0;
    for (uint32_t i = 0; i < n_threads; i++) {
        const int rc = pthread_create(&g_stream_expert_pread_pool_threads[i],
                                      NULL,
                                      ds4_gpu_stream_expert_pread_pool_worker,
                                      (void *)(uintptr_t)i);
        if (rc != 0) {
            fprintf(stderr,
                    "ds4: Metal streaming expert pread pool thread creation failed: %s\n",
                    strerror(rc));
            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
            g_stream_expert_pread_pool_stopping = 1;
            g_stream_expert_pread_pool_generation++;
            pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            for (uint32_t j = 0; j < started; j++) {
                (void)pthread_join(g_stream_expert_pread_pool_threads[j], NULL);
            }
            pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
            g_stream_expert_pread_pool_thread_count = 0;
            g_stream_expert_pread_pool_stopping = 0;
            pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
            return 0;
        }
        started++;
    }

    g_stream_expert_pread_pool_initialized = 1;
    return 1;
}

static uint32_t g_llms_aio_inflight;   /* llms LOAD_AIO_SYNC: forward (a tentative definition; LOAD_AIO's block defines it below) */
static uint64_t g_llms_pool_begins[2], g_llms_aio_sync_reads, g_llms_aio_sync_batches, g_llms_aio_sync_inline;   /* llms LOAD_AIO_SYNC: [0] the sync path, [1] the early-load path */
static int g_llms_ep_on = -1; static uint32_t g_llms_ep_layer = UINT32_MAX, g_llms_ep_n; static int32_t g_llms_ep_ids[64]; static uint64_t g_llms_ep_hits, g_llms_ep_sets;   /* llms ELA_PROTECT */
static int g_llms_ela_m, g_llms_ela_inbegin, g_llms_ela_aio;   /* llms ED_LA2 (apply_ed_la2.py): ED_LA's prefetch as fire-and-forget aio */
static uint32_t g_llms_ela_ncb; static uint64_t g_llms_ela_aio_fail, g_llms_ela_aio_refused, g_llms_ela_busy, g_llms_ela_late, g_llms_ela_waited;
static uint64_t g_llms_ela_full, g_llms_ela_dup;   /* llms ED_LA9 */
static dispatch_queue_t g_llms_ela_q; static dispatch_group_t g_llms_ela_grp; static uint32_t g_llms_ela_left; static int g_llms_ela_tier = -1;   /* llms ED_LA3 */
static double g_llms_ela_t_issue, g_llms_ela_t_done, g_llms_ela_lead_ms, g_llms_ela_read_ms, g_llms_ela_wait_ms; static uint64_t g_llms_ela_nlead, g_llms_ela_nread;   /* llms ED_LA4 */
/* Pending counts include one publication token. Zero means payload AND metadata published.
 * The last reader owns the remaining token; no callback accesses this slot after publishing zero. */
static inline void llms_ela_complete(uint32_t *pending, double *done) {
    if (__atomic_sub_fetch(pending, 1u, __ATOMIC_ACQ_REL) == 1u) {
        *done = ds4_gpu_now_ms();
        __atomic_store_n(pending, 0u, __ATOMIC_RELEASE);
    }
}
static int llms_ela_aio_issue(ds4_gpu_stream_expert_read_task *tasks, uint32_t n) {   /* llms ED_LA3: one utility-QoS block per read, low I/O tier */
    if (n == 0 || n > 3u * DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED) { g_llms_ela_aio_refused++; return 0; }
    if (g_llms_ela_tier < 0) {
        g_llms_ela_tier = IOPOL_UTILITY;
        g_llms_ela_q = dispatch_queue_create("llms.ela", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_CONCURRENT, QOS_CLASS_UTILITY, 0));
        g_llms_ela_grp = dispatch_group_create();
        fprintf(stderr, "llms: ed la reads as libdispatch blocks (utility QoS, I/O tier %d) straight into the victim slots\n", g_llms_ela_tier);
    }
    if (!g_llms_ela_q || !g_llms_ela_grp) { g_llms_ela_aio_refused++; return 0; }
    g_llms_ela_t_issue = ds4_gpu_now_ms(); g_llms_ela_t_done = 0.0;   /* llms ED_LA4 */
    g_llms_ela_ncb = n; __atomic_store_n(&g_llms_ela_left, n + 1u, __ATOMIC_RELEASE);
    const int tier = g_llms_ela_tier;
    for (uint32_t i = 0; i < n; i++) {
        ds4_gpu_stream_expert_read_task *t = &tasks[i]; t->ok = 0; t->read_bytes = 0;
        dispatch_group_async(g_llms_ela_grp, g_llms_ela_q, ^{
            const int old = getiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD);
            (void)setiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD, tier);
            t->ok = llms_expert_read_pread(t->offset, t->len, t->dst, &t->read_bytes, &t->ms);
            (void)setiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD, old >= 0 ? old : IOPOL_DEFAULT);
            llms_ela_complete(&g_llms_ela_left, &g_llms_ela_t_done);
        });
    }
    return 1;
}
static int llms_ela_aio_done(void) {   /* every read of the prefetch completed (polls, never blocks) */
    return __atomic_load_n(&g_llms_ela_left, __ATOMIC_ACQUIRE) == 0u;
}
static int llms_ela_aio_reap(ds4_gpu_stream_expert_read_task *tasks) {   /* blocks only for reads still in flight */
    if (!llms_ela_aio_done()) { g_llms_ela_waited++; const double w0 = ds4_gpu_now_ms(); dispatch_group_wait(g_llms_ela_grp, DISPATCH_TIME_FOREVER);
                                g_llms_ela_wait_ms += ds4_gpu_now_ms() - w0; }   /* llms ED_LA4 */
    int ok = 1;
    for (uint32_t i = 0; i < g_llms_ela_ncb; i++) if (!tasks[i].ok) ok = 0;
    g_llms_ela_ncb = 0;
    if (!ok) g_llms_ela_aio_fail++;
    return ok;
}
static void llms_pool_report(void) { fprintf(stderr, "llms pread pool: %llu begins from the sync path, %llu from the early-load path; load aio sync: %llu reads in %llu batches, %llu read inline\n",
    (unsigned long long)g_llms_pool_begins[0], (unsigned long long)g_llms_pool_begins[1], (unsigned long long)g_llms_aio_sync_reads, (unsigned long long)g_llms_aio_sync_batches, (unsigned long long)g_llms_aio_sync_inline); }
static int llms_load_aio_sync(void) {   /* 0 off, 1 on, -1 canary */
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_LOAD_AIO_SYNC"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on) fprintf(stderr, on < 0 ? "llms: load aio sync -- CANARY: every aio span read 16 KB off\n" : "llms: load aio sync (the synchronous expert loads as aio_read into the slab, reaped on the calling thread; no pread pool)\n");
                   atexit(llms_pool_report); }
    return on;
}
static int ds4_gpu_stream_expert_pread_pool_begin(
        ds4_gpu_stream_expert_read_task *tasks,
        uint32_t n_tasks,
        uint32_t n_workers) {
    if (n_workers <= 1) return 0;
    const uint32_t limit = ds4_gpu_stream_expert_pread_thread_limit();
    if (!ds4_gpu_stream_expert_pread_pool_init(limit)) return 0;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    if (!g_stream_expert_pread_pool_initialized ||
        g_stream_expert_pread_pool_stopping ||
        g_stream_expert_pread_pool_thread_count == 0) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }
    if (n_workers > g_stream_expert_pread_pool_thread_count) {
        n_workers = g_stream_expert_pread_pool_thread_count;
    }
    if (n_workers == 0) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }

    if (g_stream_expert_pread_pool_remaining_workers != 0 ||
        g_stream_expert_pread_pool_tasks != NULL) {
        pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
        return 0;
    }

    g_stream_expert_pread_pool_tasks = tasks;
    g_stream_expert_pread_pool_n_tasks = n_tasks;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_active_workers = n_workers;
    g_stream_expert_pread_pool_remaining_workers = n_workers;
    g_stream_expert_pread_pool_generation++;
    pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    return 1;
}

static int ds4_gpu_stream_expert_pread_pool_wait(void) {
    if (!g_stream_expert_pread_pool_initialized) return 0;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    while (g_stream_expert_pread_pool_remaining_workers != 0) {
        pthread_cond_wait(&g_stream_expert_pread_pool_done_cond,
                          &g_stream_expert_pread_pool_mutex);
    }
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
    return 1;
}

static int ds4_gpu_stream_expert_pread_pool_dispatch(
        ds4_gpu_stream_expert_read_task *tasks,
        uint32_t n_tasks,
        uint32_t n_workers) {
    (void)llms_load_aio_sync(); g_llms_pool_begins[0]++;   /* llms LOAD_AIO_SYNC: count */
    if (!ds4_gpu_stream_expert_pread_pool_begin(tasks, n_tasks, n_workers)) {
        return 0;
    }
    return ds4_gpu_stream_expert_pread_pool_wait();
}

static void ds4_gpu_stream_expert_pread_pool_shutdown(void) {
    if (!g_stream_expert_pread_pool_initialized) return;

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_stopping = 1;
    g_stream_expert_pread_pool_generation++;
    pthread_cond_broadcast(&g_stream_expert_pread_pool_start_cond);
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);

    const uint32_t n_threads = g_stream_expert_pread_pool_thread_count;
    for (uint32_t i = 0; i < n_threads; i++) {
        (void)pthread_join(g_stream_expert_pread_pool_threads[i], NULL);
    }

    pthread_mutex_lock(&g_stream_expert_pread_pool_mutex);
    g_stream_expert_pread_pool_thread_count = 0;
    g_stream_expert_pread_pool_active_workers = 0;
    g_stream_expert_pread_pool_remaining_workers = 0;
    g_stream_expert_pread_pool_n_tasks = 0;
    g_stream_expert_pread_pool_next_task = 0;
    g_stream_expert_pread_pool_tasks = NULL;
    g_stream_expert_pread_pool_initialized = 0;
    g_stream_expert_pread_pool_stopping = 0;
    pthread_mutex_unlock(&g_stream_expert_pread_pool_mutex);
}

static int ds4_gpu_stream_expert_read_tasks(
        ds4_gpu_stream_expert_read_task *tasks,
        uint32_t n_tasks,
        uint64_t *total_bytes,
        double *wall_ms);
static uint64_t g_llms_chunk_calls, g_llms_chunk_tasks;
static void llms_chunk_report(void) { fprintf(stderr, "llms pread chunk: %llu calls, %llu chunk tasks\n", (unsigned long long)g_llms_chunk_calls, (unsigned long long)g_llms_chunk_tasks); }
/* llms LLMS_DS4_PREAD_CHUNK: run the same reads as more, smaller concurrent I/Os */
static int llms_pread_tasks_chunked(ds4_gpu_stream_expert_read_task *tasks, uint32_t n_tasks, uint64_t chunk,
                                    uint64_t *total_bytes, double *wall_ms) {
    static int nested;
    uint32_t n = 0;
    /* llms LOAD_DIRECT pieces: ph = the tensor's offset inside its page when loads are read in place, else 0 (pieces as before).
     * Piece j of a task covers [max(0, j * chunk - ph), min(len, (j + 1) * chunk - ph)) of the tensor. */
    const int llms_al = llms_ld_mode() != 0;
#define LLMS_PH(t) (llms_al ? ((t).offset & (LLMS_LD_P - 1ull)) : 0ull)
#define LLMS_NP(t) ((uint32_t)((LLMS_PH(t) + (t).len + chunk - 1) / chunk))
    for (uint32_t i = 0; i < n_tasks; i++) n += LLMS_NP(tasks[i]);
    ds4_gpu_stream_expert_read_task *c = calloc(n ? n : 1, sizeof(*c));
    if (!c) return 0;
    uint32_t k = 0;
    for (uint32_t i = 0; i < n_tasks; i++) {
        const uint64_t ph = LLMS_PH(tasks[i]); const uint32_t np = LLMS_NP(tasks[i]);
        for (uint32_t j = 0; j < np; j++) {
            const uint64_t o0 = j == 0 ? 0 : (uint64_t)j * chunk - ph, o1 = ((uint64_t)j + 1) * chunk - ph < tasks[i].len ? ((uint64_t)j + 1) * chunk - ph : tasks[i].len;
            c[k++] = (ds4_gpu_stream_expert_read_task){ .offset = tasks[i].offset + o0, .len = o1 - o0, .dst = tasks[i].dst + o0 };
        }
    }
    if (!g_llms_chunk_calls++) atexit(llms_chunk_report);
    g_llms_chunk_tasks += n;
    nested = 1; (void)nested;
    const int ok = ds4_gpu_stream_expert_read_tasks(c, n, total_bytes, wall_ms);
    k = 0;
    for (uint32_t i = 0; i < n_tasks; i++) {
        tasks[i].ok = 1; tasks[i].read_bytes = 0; tasks[i].ms = 0;
        const uint32_t np = LLMS_NP(tasks[i]);
        for (uint32_t j = 0; j < np; j++, k++) {
            if (!c[k].ok) tasks[i].ok = 0;
            tasks[i].read_bytes += c[k].read_bytes; tasks[i].ms += c[k].ms;
        }
    }
#undef LLMS_PH
#undef LLMS_NP
    free(c);
    return ok;
}
static int ds4_gpu_stream_expert_read_tasks(
        ds4_gpu_stream_expert_read_task *tasks,
        uint32_t n_tasks,
        uint64_t *total_bytes,
        double *wall_ms) {
    if (total_bytes) *total_bytes = 0;
    if (wall_ms) *wall_ms = 0.0;
    if (!tasks || n_tasks == 0) return 1;
    {   /* llms LLMS_DS4_PREAD_CHUNK */
        static long long llms_chunk = -1; static int llms_in_chunked;
        if (llms_chunk < 0) { const char *e = getenv("LLMS_DS4_PREAD_CHUNK"); llms_chunk = (e && *e) ? atoll(e) : 0; }
        if (llms_chunk >= 65536 && !llms_in_chunked) {
            llms_in_chunked = 1;
            const int r = llms_pread_tasks_chunked(tasks, n_tasks, (uint64_t)llms_chunk, total_bytes, wall_ms);
            llms_in_chunked = 0;
            return r;
        }
    }

    if (llms_load_aio_sync() && g_model_fd_nocache >= 0 && llms_ld_mode() == 1 && n_tasks > 1) {   /* llms LOAD_AIO_SYNC */
        const double ts0 = ds4_gpu_now_ms(); uint64_t tb = 0; int aok = 1;
        struct aiocb cb[64]; uint32_t idx[64]; uint32_t i = 0;
        while (i < n_tasks && aok) {
            const uint32_t used = g_llms_aio_inflight, room = used + 64u <= 240u ? 64u : (used < 239u ? 240u - used : 1u);
            uint32_t nb = 0;
            for (; i < n_tasks && nb < room; i++) {
                ds4_gpu_stream_expert_read_task *t = &tasks[i];
                const uint64_t A = 16384u, a0 = t->offset & ~(A - 1u), a1 = (t->offset + t->len + A - 1u) & ~(A - 1u);
                t->ok = 0; t->read_bytes = 0; t->ms = 0.0;
                int inl = !llms_ld_in_slab(t->dst - (t->offset - a0), a1 - a0);
                if (!inl) {
                    memset(&cb[nb], 0, sizeof cb[nb]);
                    uint64_t llms_bo = a0; const int llms_bfd = llms_gubs_src(&llms_bo, g_model_fd_nocache);   /* llms BS6C */
                    cb[nb].aio_fildes = llms_bfd; cb[nb].aio_buf = t->dst - (t->offset - a0); cb[nb].aio_nbytes = (size_t)(a1 - a0);
                    cb[nb].aio_offset = (off_t)(llms_bo + (llms_load_aio_sync() < 0 ? 16384u : 0u)); cb[nb].aio_sigevent.sigev_notify = SIGEV_NONE;
                    if (aio_read(&cb[nb]) == 0) { idx[nb++] = i; continue; }
                    inl = 1;   /* refused: read it here */
                }
                t->ok = llms_expert_read_pread(t->offset, t->len, t->dst, &t->read_bytes, &t->ms); g_llms_aio_sync_inline++;
                if (!t->ok) aok = 0; else tb += t->read_bytes;
            }
            for (uint32_t b = 0; b < nb; b++) {   /* every request reaped, failed or not */
                const struct aiocb *one[1] = { &cb[b] };
                while (aio_error(&cb[b]) == EINPROGRESS) (void)aio_suspend(one, 1, NULL);
                const ssize_t got = aio_return(&cb[b]);
                ds4_gpu_stream_expert_read_task *t = &tasks[idx[b]];
                const uint64_t need = (t->offset & 16383u) + t->len;
                if (got >= 0 && (uint64_t)got >= need) { t->ok = 1; t->read_bytes = t->len; tb += t->len; __sync_fetch_and_add(&g_llms_ld_reads, 1); __sync_fetch_and_add(&g_llms_ld_bytes, t->len);
                    llms_expert_read_landed(1, cb[b].aio_fildes, t->dst, t->len); }
                else aok = 0;
            }
            g_llms_aio_sync_reads += nb; g_llms_aio_sync_batches++;
        }
        if (total_bytes) *total_bytes = tb;
        if (wall_ms) *wall_ms = ds4_gpu_now_ms() - ts0;
        return aok;
    }
    const uint32_t n_workers =
        ds4_gpu_stream_expert_pread_thread_count(n_tasks);
    const double t0 = ds4_gpu_now_ms();
    int ok = 1;
    if (n_workers <= 1) {
        ds4_gpu_stream_expert_pread_worker_args wa = {
            .tasks = tasks,
            .n_tasks = n_tasks,
            .worker_index = 0,
            .n_workers = 1,
        };
        (void)ds4_gpu_stream_expert_pread_worker(&wa);
    } else if (!ds4_gpu_stream_expert_pread_pool_dispatch(tasks,
                                                          n_tasks,
                                                          n_workers)) {
        pthread_t threads[32];
        ds4_gpu_stream_expert_pread_worker_args args[32];
        uint32_t started = 0;
        for (uint32_t i = 0; i < n_workers; i++) {
            args[i].tasks = tasks;
            args[i].n_tasks = n_tasks;
            args[i].worker_index = i;
            args[i].n_workers = n_workers;
            const int rc = pthread_create(&threads[i],
                                          NULL,
                                          ds4_gpu_stream_expert_pread_worker,
                                          &args[i]);
            if (rc != 0) {
                fprintf(stderr,
                        "ds4: Metal streaming expert pread thread creation failed: %s\n",
                        strerror(rc));
                ok = 0;
                break;
            }
            started++;
        }
        for (uint32_t i = 0; i < started; i++) {
            if (pthread_join(threads[i], NULL) != 0) ok = 0;
        }
    }
    const double dt = ds4_gpu_now_ms() - t0;

    uint64_t bytes = 0;
    for (uint32_t i = 0; i < n_tasks; i++) {
        if (!tasks[i].ok) ok = 0;
        if (bytes > UINT64_MAX - tasks[i].read_bytes) {
            bytes = UINT64_MAX;
        } else {
            bytes += tasks[i].read_bytes;
        }
    }
    if (total_bytes) *total_bytes = bytes;
    if (wall_ms) *wall_ms = dt;
    return ok;
}

static void ds4_gpu_stream_expert_cache_warn_mlock_failure(
        uint64_t failed_len,
        int      err) {
    if (g_stream_expert_cache_mlock_warned) return;
    g_stream_expert_cache_mlock_warned = 1;

    const uint64_t gib = 1024ull * 1024ull * 1024ull;
    const uint32_t budget = ds4_gpu_stream_expert_cache_requested_budget();
    uint64_t requested = 0;
    if (budget != 0 && g_stream_expert_cache_expert_bytes != 0) {
        requested =
            budget > UINT64_MAX / g_stream_expert_cache_expert_bytes ?
                UINT64_MAX :
                (uint64_t)budget * g_stream_expert_cache_expert_bytes;
    }

    uint64_t suggested_gib = g_stream_expert_cache_mlock_bytes / gib;
    if (suggested_gib > 1) suggested_gib--;

    fprintf(stderr,
            "ds4: warning: streaming expert cache could not mlock all buffers\n");
    if (requested != 0) {
        fprintf(stderr,
                "ds4:   requested cache: %u experts / %.2f GiB\n",
                budget,
                ds4_gpu_gib(requested));
    } else {
        fprintf(stderr,
                "ds4:   requested cache: %u experts\n",
                budget);
    }
    fprintf(stderr,
            "ds4:   locked so far:   %.2f GiB\n",
            ds4_gpu_gib(g_stream_expert_cache_mlock_bytes));
    fprintf(stderr,
            "ds4:   failed buffer:   %.2f MiB (%s)\n",
            ds4_gpu_mib(failed_len),
            err != 0 ? strerror(err) : "mlock unavailable");
    fprintf(stderr,
            "ds4:   macOS may page unlocked expert buffers, causing poor or unstable speed\n");
    if (g_stream_expert_cache_mlock_budget_cap != 0 &&
        g_stream_expert_cache_expert_bytes != 0) {
        const uint64_t capped_bytes =
            g_stream_expert_cache_mlock_budget_cap >
                UINT64_MAX / g_stream_expert_cache_expert_bytes ?
                    UINT64_MAX :
                    (uint64_t)g_stream_expert_cache_mlock_budget_cap *
                        g_stream_expert_cache_expert_bytes;
        fprintf(stderr,
                "ds4:   using locked cache cap: %u experts / %.2f GiB\n",
                g_stream_expert_cache_mlock_budget_cap,
                ds4_gpu_gib(capped_bytes));
    }
    if (suggested_gib != 0) {
        fprintf(stderr,
                "ds4:   try: --ssd-streaming-cache-experts %" PRIu64 "GB\n",
                suggested_gib);
    } else {
        fprintf(stderr,
                "ds4:   try a smaller --ssd-streaming-cache-experts NGB budget\n");
    }
}

static uint32_t ds4_gpu_stream_expert_slab_locked_slot_count(void) {
    uint32_t count = 0;
    uint32_t total = g_stream_expert_cache_slab_total_slots;
    if (total > DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        total = DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES;
    }
    for (uint32_t slot = 0; slot < total; slot++) {
        if (g_stream_expert_cache_slab_slot_locked[slot]) count++;
    }
    return count;
}

static void ds4_gpu_stream_expert_cache_cap_budget_to_locked(void) {
    { static int uo = -1; if (uo < 0) { const char *e = getenv("LLMS_DS4_UNLOCKED_OK"); uo = e && *e && *e != '0';
                                        if (uo) fprintf(stderr, "llms: unlocked-ok -- an mlock failure does not cap the expert cache: slots past the wire limit stay in use, pageable\n"); }
      if (uo) return; }   /* llms UNLOCKED_OK (apply_unlocked_ok.py) */
    uint32_t cap = g_stream_expert_cache_entry_count;
    const uint32_t locked_slots = ds4_gpu_stream_expert_slab_locked_slot_count();
    if (locked_slots != 0 && locked_slots < cap) cap = locked_slots;
    const uint64_t gib = 1024ull * 1024ull * 1024ull;
    uint64_t safe_gib = g_stream_expert_cache_mlock_bytes / gib;
    if (safe_gib > 1) safe_gib--;
    static long llms_headroom_mb = -1;   /* llms LOCK_HEADROOM (apply_ds4_lock_headroom.py): keep locked - headroom instead of floor(GiB) - 1 */
    if (llms_headroom_mb < 0) { const char *e = getenv("LLMS_DS4_LOCK_HEADROOM_MB"); llms_headroom_mb = e && *e ? atol(e) : 0; if (e && *e && llms_headroom_mb <= 0) llms_headroom_mb = 256; }
    if (safe_gib != 0 && g_stream_expert_cache_expert_bytes != 0) {
        uint64_t safe_bytes =
            safe_gib > UINT64_MAX / gib ? UINT64_MAX : safe_gib * gib;
        if (llms_headroom_mb > 0 && g_stream_expert_cache_mlock_bytes > (uint64_t)llms_headroom_mb << 20) safe_bytes = g_stream_expert_cache_mlock_bytes - ((uint64_t)llms_headroom_mb << 20);   /* llms LOCK_HEADROOM */
        uint64_t safe_cap64 = safe_bytes / g_stream_expert_cache_expert_bytes;
        if (safe_cap64 > UINT32_MAX) safe_cap64 = UINT32_MAX;
        if (safe_cap64 != 0 && safe_cap64 < cap) {
            cap = (uint32_t)safe_cap64;
        }
    }
    if (cap == 0) return;
    if (g_stream_expert_cache_mlock_budget_cap == 0 ||
        cap < g_stream_expert_cache_mlock_budget_cap) {
        g_stream_expert_cache_mlock_budget_cap = cap;
    }
}

static id<MTLBuffer> ds4_gpu_stream_expert_alloc_buffer(
        uint64_t  len,
        NSString *label) {
    if (!g_device ||
        len == 0 ||
        len > (uint64_t)NSUIntegerMax) {
        return nil;
    }

    id<MTLBuffer> buffer = [g_device newBufferWithLength:(NSUInteger)len
                                                 options:MTLResourceStorageModeShared];
    if (!buffer) {
        fprintf(stderr,
                "ds4: Metal streaming expert explicit buffer allocation failed (%.2f MiB)\n",
                ds4_gpu_mib(len));
        return nil;
    }
    buffer.label = label;
    g_stream_expert_cache_buffer_allocs++;
    if (g_ssd_streaming_mode) {
        void *ptr = [buffer contents];
        const NSUInteger n = [buffer length];
        const double t0 = ds4_gpu_now_ms();
        if (ptr && n != 0 && mlock(ptr, (size_t)n) == 0) {
            const double dt = ds4_gpu_now_ms() - t0;
            g_stream_expert_cache_mlock_ms += dt;
            if (g_stream_expert_cache_mlock_bytes > UINT64_MAX - (uint64_t)n) {
                g_stream_expert_cache_mlock_bytes = UINT64_MAX;
            } else {
                g_stream_expert_cache_mlock_bytes += (uint64_t)n;
            }
        } else {
            const double dt = ds4_gpu_now_ms() - t0;
            g_stream_expert_cache_mlock_ms += dt;
            g_stream_expert_cache_mlock_failures++;
            if (g_stream_expert_cache_mlock_fail_bytes > UINT64_MAX - (uint64_t)n) {
                g_stream_expert_cache_mlock_fail_bytes = UINT64_MAX;
            } else {
                g_stream_expert_cache_mlock_fail_bytes += (uint64_t)n;
            }
            const int err = ptr && n != 0 ? errno : 0;
            ds4_gpu_stream_expert_cache_cap_budget_to_locked();
            ds4_gpu_stream_expert_cache_warn_mlock_failure((uint64_t)n, err);
            if (getenv("DS4_METAL_STREAMING_EXPERT_BUFFER_MLOCK_PROFILE") != NULL) {
                fprintf(stderr,
                        "ds4: Metal streaming expert buffer mlock failed len=%.2f MiB: %s\n",
                        ds4_gpu_mib((uint64_t)n),
                        err != 0 ? strerror(err) : "mlock unavailable");
            }
            return nil;
        }
    }
    return buffer;
}

static void ds4_gpu_stream_expert_unlock_explicit_buffer(id<MTLBuffer> buffer) {
    if (!g_ssd_streaming_mode || !buffer) return;
    void *ptr = [buffer contents];
    const NSUInteger n = [buffer length];
    if (!ptr || n == 0 || munlock(ptr, (size_t)n) != 0) return;
    if (g_stream_expert_cache_mlock_bytes >= (uint64_t)n) {
        g_stream_expert_cache_mlock_bytes -= (uint64_t)n;
    } else {
        g_stream_expert_cache_mlock_bytes = 0;
    }
}

static int ds4_gpu_stream_expert_combined_buffer_enabled(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_COMBINED_BUFFER") == NULL;
}

static int ds4_gpu_stream_expert_slab_enabled(void) {
    return ds4_gpu_stream_expert_combined_buffer_enabled() &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_SLABS") == NULL;
}

/*
 * Large PRO caches otherwise create thousands of small shared Metal buffers.
 * Slabs keep the buffer object set small while locking pages only for slots
 * that actually hold a streamed expert.
 */
static uint64_t ds4_gpu_stream_expert_slab_target_bytes(void) {
    const uint64_t mib = 1024ull * 1024ull;
    uint64_t target = 4096ull * mib;
    const char *env = getenv("DS4_METAL_STREAMING_EXPERT_SLAB_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && *end == '\0' && v != 0) {
            target = v > UINT64_MAX / mib ? UINT64_MAX : (uint64_t)v * mib;
        }
    }
    return target;
}

static id<MTLBuffer> ds4_gpu_stream_expert_alloc_slab_buffer(
        uint64_t  len,
        NSString *label) {
    if (!g_device ||
        len == 0 ||
        len > (uint64_t)NSUIntegerMax) {
        return nil;
    }

    id<MTLBuffer> buffer = llms_sbg_take(len);   /* llms SLAB_BG v2 */
    const int llms_planned = buffer != nil;
    if (!buffer) { llms_mg_admit_alloc(len, "expert slab");   /* llms MEMGUARD (2): an on-demand slab must leave the reserve */
                   buffer = [g_device newBufferWithLength:(NSUInteger)len
                                                 options:MTLResourceStorageModeShared]; }
    if (!buffer) {
        fprintf(stderr,
                "ds4: Metal streaming expert slab allocation failed (%.2f MiB)\n",
                ds4_gpu_mib(len));
        return nil;
    }
    buffer.label = label;
    g_stream_expert_cache_buffer_allocs++;
    if (!llms_planned) llms_sr_add(buffer, len);   /* llms SLAB_RESIDENCY through the shared helper (SLAB_BG v2); a planned buffer is already in the set */
    return buffer;
}

static int ds4_gpu_stream_expert_slab_slot_range(
        uint32_t slot,
        uint32_t *slab_index,
        uint64_t *slot_base) {
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        const uint32_t start = g_stream_expert_cache_slab_start_slot[i];
        const uint32_t count = g_stream_expert_cache_slab_slot_count[i];
        if (slot < start || slot >= start + count) continue;
        if (slab_index) *slab_index = i;
        if (slot_base) {
            *slot_base =
                (uint64_t)(slot - start) * g_stream_expert_cache_slab_slot_bytes;
        }
        return 1;
    }
    return 0;
}

static int ds4_gpu_stream_expert_slab_slot_for_buffer(
        id<MTLBuffer> buffer,
        NSUInteger    gate_inner,
        uint32_t     *slot_out) {
    if (!buffer || g_stream_expert_cache_slab_slot_bytes == 0 || !slot_out) {
        return 0;
    }
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        if (g_stream_expert_cache_slabs[i] != buffer) continue;
        const uint64_t inner = (uint64_t)gate_inner;
        const uint64_t slot_bytes = g_stream_expert_cache_slab_slot_bytes;
        if (slot_bytes == 0 || inner % slot_bytes >= (llms_ld_mode() ? LLMS_LD_P : 1ull)) return 0;   /* llms LOAD_DIRECT: the gate offset carries a phase below one page */
        const uint64_t local_slot = inner / slot_bytes;
        if (local_slot >= g_stream_expert_cache_slab_slot_count[i]) return 0;
        const uint64_t slot =
            (uint64_t)g_stream_expert_cache_slab_start_slot[i] + local_slot;
        if (slot > UINT32_MAX) return 0;
        *slot_out = (uint32_t)slot;
        return 1;
    }
    return 0;
}

static void ds4_gpu_stream_expert_slab_push_free_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        g_stream_expert_cache_free_slot_count >=
            DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES) {
        return;
    }
    g_stream_expert_cache_free_slots[g_stream_expert_cache_free_slot_count++] =
        slot;
}

static int ds4_gpu_stream_expert_slab_lock_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        g_stream_expert_cache_slab_slot_locked[slot] || g_llms_slot_pageable[slot]) {   /* llms UNLOCKED_OK: a pageable slot is usable */
        return 1;
    }
    {
        static int nl = -1; static uint64_t nl_n;
        if (nl < 0) { const char *e = getenv("LLMS_DS4_SLOT_NOLOCK"); nl = e && *e && *e != '0';
                      if (nl) { fprintf(stderr, "llms: slot nolock (a fresh expert slot is not mlocked; the slabs are resident through the residency set)\n");
                                atexit_b(^{ fprintf(stderr, "llms slot nolock: %llu slots marked without mlock\n", (unsigned long long)nl_n); }); } }
        if (nl && !llms_alt_off("nolock")) { g_stream_expert_cache_slab_slot_locked[slot] = 1; nl_n++; return 1; }
    }
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab] ||
        g_stream_expert_cache_slab_slot_bytes == 0 ||
        base > (uint64_t)NSUIntegerMax) {
        return 0;
    }

    void *contents = [g_stream_expert_cache_slabs[slab] contents];
    if (!contents) return 0;
    const double t0 = ds4_gpu_now_ms();
    void *ptr = (uint8_t *)contents + (NSUInteger)base;
    const size_t n = (size_t)g_stream_expert_cache_slab_slot_bytes;
    if (mlock(ptr, n) == 0) {
        const double dt = ds4_gpu_now_ms() - t0;
        g_stream_expert_cache_mlock_ms += dt;
        if (g_stream_expert_cache_mlock_bytes >
            UINT64_MAX - g_stream_expert_cache_slab_slot_bytes) {
            g_stream_expert_cache_mlock_bytes = UINT64_MAX;
        } else {
            g_stream_expert_cache_mlock_bytes +=
                g_stream_expert_cache_slab_slot_bytes;
        }
        g_stream_expert_cache_slab_slot_locked[slot] = 1;
        return 1;
    }

    const double dt = ds4_gpu_now_ms() - t0;
    g_stream_expert_cache_mlock_ms += dt;
    g_stream_expert_cache_mlock_failures++;
    if (g_stream_expert_cache_mlock_fail_bytes >
        UINT64_MAX - g_stream_expert_cache_slab_slot_bytes) {
        g_stream_expert_cache_mlock_fail_bytes = UINT64_MAX;
    } else {
        g_stream_expert_cache_mlock_fail_bytes +=
            g_stream_expert_cache_slab_slot_bytes;
    }
    if (llms_unlocked_ok()) {   /* llms UNLOCKED_OK part 2: keep the slot, pageable; report once per 256 */
        const int llms_err = errno; g_llms_slot_pageable[slot] = 1;
        if ((g_llms_pageable_slots++ & 255u) == 0) fprintf(stderr, "llms: unlocked-ok: %u slots in use without a lock (mlock: %s)\n", g_llms_pageable_slots, strerror(llms_err));
        return 1;
    }
    ds4_gpu_stream_expert_cache_cap_budget_to_locked();
    ds4_gpu_stream_expert_cache_warn_mlock_failure(
            g_stream_expert_cache_slab_slot_bytes,
            errno);
    return 0;
}

static int ds4_gpu_stream_expert_slab_unlock_slot(uint32_t slot) {
    if (slot >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_ENTRIES ||
        !g_stream_expert_cache_slab_slot_locked[slot]) {
        return 1;
    }
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab] ||
        g_stream_expert_cache_slab_slot_bytes == 0 ||
        base > (uint64_t)NSUIntegerMax) {
        return 0;
    }

    void *contents = [g_stream_expert_cache_slabs[slab] contents];
    if (!contents) return 0;
    void *ptr = (uint8_t *)contents + (NSUInteger)base;
    const size_t n = (size_t)g_stream_expert_cache_slab_slot_bytes;
    if (munlock(ptr, n) != 0) return 0;

    g_stream_expert_cache_slab_slot_locked[slot] = 0;
    if (g_stream_expert_cache_mlock_bytes >= g_stream_expert_cache_slab_slot_bytes) {
        g_stream_expert_cache_mlock_bytes -= g_stream_expert_cache_slab_slot_bytes;
    } else {
        g_stream_expert_cache_mlock_bytes = 0;
    }
    return 1;
}

static int ds4_gpu_stream_expert_slab_slot_buffers_impl(uint32_t slot, uint64_t gate_expert_bytes, uint64_t down_expert_bytes, __strong id<MTLBuffer> *gate_buf, __strong id<MTLBuffer> *up_buf, __strong id<MTLBuffer> *down_buf, NSUInteger *gate_inner, NSUInteger *up_inner, NSUInteger *down_inner);
static int ds4_gpu_stream_expert_slab_slot_buffers(uint32_t slot, uint64_t gate_expert_bytes, uint64_t down_expert_bytes, __strong id<MTLBuffer> *gate_buf, __strong id<MTLBuffer> *up_buf, __strong id<MTLBuffer> *down_buf, NSUInteger *gate_inner, NSUInteger *up_inner, NSUInteger *down_inner) {   /* llms SHM_CACHE: a slot handed out for a new load moves its generation */
    llms_shm_gen_bump(slot);
    return ds4_gpu_stream_expert_slab_slot_buffers_impl(slot, gate_expert_bytes, down_expert_bytes, gate_buf, up_buf, down_buf, gate_inner, up_inner, down_inner);
}
static int ds4_gpu_stream_expert_slab_slot_buffers_impl(
        uint32_t slot,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        __strong id<MTLBuffer> *gate_buf,
        __strong id<MTLBuffer> *up_buf,
        __strong id<MTLBuffer> *down_buf,
        NSUInteger *gate_inner,
        NSUInteger *up_inner,
        NSUInteger *down_inner) {
    uint32_t slab = UINT32_MAX;
    uint64_t base = 0;
    if (!ds4_gpu_stream_expert_slab_slot_range(slot, &slab, &base) ||
        slab >= g_stream_expert_cache_slab_count ||
        !g_stream_expert_cache_slabs[slab]) {
        return 0;
    }
    if (gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull ||
        base > UINT64_MAX - (gate_expert_bytes * 2ull + down_expert_bytes) ||
        base + gate_expert_bytes * 2ull + down_expert_bytes >
            (uint64_t)NSUIntegerMax) {
        return 0;
    }
    id<MTLBuffer> b = g_stream_expert_cache_slabs[slab];
    if (!ds4_gpu_stream_expert_slab_lock_slot(slot)) return 0;
    *gate_buf = b;
    *up_buf = b;
    *down_buf = b;
    *gate_inner = (NSUInteger)base;
    *up_inner = (NSUInteger)(base + gate_expert_bytes);
    *down_inner = (NSUInteger)(base + gate_expert_bytes * 2ull);
    if (llms_ld_mode()) {   /* llms LOAD_DIRECT: each tensor in its own page-aligned region with one spare page */
        *up_inner = (NSUInteger)(base + llms_ld_region(gate_expert_bytes));
        *down_inner = (NSUInteger)(base + 2ull * llms_ld_region(gate_expert_bytes));
    }
    return 1;
}

static int ds4_gpu_stream_expert_alloc_slab_slot(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        __strong id<MTLBuffer> *gate_buf,
        __strong id<MTLBuffer> *up_buf,
        __strong id<MTLBuffer> *down_buf,
        NSUInteger *gate_inner,
        NSUInteger *up_inner,
        NSUInteger *down_inner) {
    llms_shm_early();   /* llms SHM_CACHE: restore before the first touch */
    if (!ds4_gpu_stream_expert_slab_enabled() ||
        !gate_buf || !up_buf || !down_buf ||
        !gate_inner || !up_inner || !down_inner ||
        gate_expert_bytes == 0 || down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }

    uint64_t slot_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
    if (slot_bytes == 0 || slot_bytes > (uint64_t)NSUIntegerMax) return 0;
    if (llms_ld_mode()) slot_bytes = 2ull * llms_ld_region(gate_expert_bytes) + llms_ld_region(down_expert_bytes);   /* llms LOAD_DIRECT */
    const uint64_t page = (uint64_t)getpagesize();
    if (page != 0) {
        slot_bytes = round_up_u64(slot_bytes, page);
        if (slot_bytes == 0 || slot_bytes > (uint64_t)NSUIntegerMax) return 0;
    }
    if (g_stream_expert_cache_slab_slot_bytes != 0 &&
        g_stream_expert_cache_slab_slot_bytes != slot_bytes) {
        return 0;
    }
    g_stream_expert_cache_slab_slot_bytes = slot_bytes;

    if (g_stream_expert_cache_free_slot_count != 0) {
        const uint32_t slot =
            g_stream_expert_cache_free_slots[--g_stream_expert_cache_free_slot_count];
        return ds4_gpu_stream_expert_slab_slot_buffers(slot,
                                                       gate_expert_bytes,
                                                       down_expert_bytes,
                                                       gate_buf,
                                                       up_buf,
                                                       down_buf,
                                                       gate_inner,
                                                       up_inner,
                                                       down_inner);
    }

    uint32_t slab = g_stream_expert_cache_slab_count;
    if (slab != 0 &&
        g_stream_expert_cache_slab_slots_used[slab - 1] <
            g_stream_expert_cache_slab_slot_count[slab - 1]) {
        slab--;
    } else {
        if (g_stream_expert_cache_slab_count >=
            DS4_METAL_STREAM_EXPERT_CACHE_MAX_SLABS) {
            return 0;
        }
        const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
        if (budget != 0 && g_stream_expert_cache_slab_total_slots >= budget) {
            return 0;
        }
        uint64_t target = ds4_gpu_stream_expert_slab_target_bytes();
        uint64_t slots64 = target / slot_bytes;
        if (slots64 == 0) slots64 = 1;
        if (slots64 > UINT32_MAX) slots64 = UINT32_MAX;
        uint32_t slots = (uint32_t)slots64;
        if (budget != 0) {
            const uint32_t remaining =
                budget - g_stream_expert_cache_slab_total_slots;
            if (slots > remaining) slots = remaining;
        }
        if (slots == 0) return 0;
        id<MTLBuffer> slab_buffer = nil;
        while (slots != 0) {
            if ((uint64_t)slots <= UINT64_MAX / slot_bytes &&
                (uint64_t)slots * slot_bytes <= (uint64_t)NSUIntegerMax) {
                slab_buffer =
                    ds4_gpu_stream_expert_alloc_slab_buffer(
                            (uint64_t)slots * slot_bytes,
                            @"ds4_stream_expert_slab");
                if (slab_buffer) break;
            }
            slots /= 2u;
        }
        if (!slab_buffer || slots == 0) return 0;

        slab = g_stream_expert_cache_slab_count++;
        g_stream_expert_cache_slabs[slab] = slab_buffer;
        g_llms_ld_lo[slab] = (uint8_t *)[slab_buffer contents];   /* llms LOAD_DIRECT */
        g_llms_ld_hi[slab] = g_llms_ld_lo[slab] ? g_llms_ld_lo[slab] + (uint64_t)slots * slot_bytes : NULL;
        g_llms_ld_slabs = slab + 1u;
        g_stream_expert_cache_slab_start_slot[slab] =
            g_stream_expert_cache_slab_total_slots;
        g_stream_expert_cache_slab_slot_count[slab] = slots;
        g_stream_expert_cache_slab_slots_used[slab] = 0;
        g_stream_expert_cache_slab_total_slots += slots;
    }

    const uint32_t local_slot = g_stream_expert_cache_slab_slots_used[slab]++;
    const uint32_t slot =
        g_stream_expert_cache_slab_start_slot[slab] + local_slot;
    return ds4_gpu_stream_expert_slab_slot_buffers(slot,
                                                   gate_expert_bytes,
                                                   down_expert_bytes,
                                                   gate_buf,
                                                   up_buf,
                                                   down_buf,
                                                   gate_inner,
                                                   up_inner,
                                                   down_inner);
}
static ds4_gpu_stream_expert_cache_entry *ds4_gpu_stream_expert_cache_install_loaded(const void *, uint64_t, uint32_t, uint32_t, uint64_t, uint64_t, uint64_t,
    uint64_t, uint64_t, id<MTLBuffer>, id<MTLBuffer>, id<MTLBuffer>, NSUInteger, NSUInteger, NSUInteger);
static int g_llms_shm_in_restore;   /* llms R0PF: set around the restore loop (its installs are not round 0's) */
static void llms_shm_restore(void) {   /* llms SHM_CACHE: once per process, right after the ED preallocation, before any install */
    if (g_llms_shm_restore_done || g_llms_shm_ok != 1 || !g_llms_shm_hdr) return;
    g_llms_shm_restore_done = 1;
    pthread_mutex_lock(&g_llms_shm_mu); llms_shm_ent *v = g_llms_shm_saved; const uint32_t n = g_llms_shm_nsaved; g_llms_shm_saved = NULL; g_llms_shm_nsaved = 0; pthread_mutex_unlock(&g_llms_shm_mu);
    if (!v || !n) { free(v); return; }
    if (g_llms_shm == 2) {   /* CANARY (10-20 05:0x, second form): the first swapped EXPERT IDS, and every lookup's offset check rejected the swapped entries
                             (the reload then served the right bytes: C == L, the canary could not fire). Now the SLOTS (bytes, inner offsets,
                             generation) of every pair of entries of the first layer with two or more are swapped, each entry keeping its own key
                             and file offsets: the lookups accept them and read another expert's weights. */
        uint32_t L = UINT32_MAX, sw = 0; for (uint32_t a = 0; a + 1 < n && L == UINT32_MAX; a++) if (v[a].layer == v[a + 1].layer) L = v[a].layer;
        for (uint32_t a = 0, prev = UINT32_MAX; L != UINT32_MAX && a < n; a++) { if (v[a].layer != L) continue; if (prev == UINT32_MAX) { prev = a; continue; }
            llms_shm_ent *x = &v[prev], *y = &v[a]; const uint32_t ts = x->slot; x->slot = y->slot; y->slot = ts;
            const uint32_t tg = x->gen; x->gen = y->gen; y->gen = tg; const uint64_t t1 = x->gi, t2 = x->ui, t3 = x->di; x->gi = y->gi; x->ui = y->ui; x->di = y->di; y->gi = t1; y->ui = t2; y->di = t3;
            prev = UINT32_MAX; sw++; }
        fprintf(stderr, "llms shm cache: CANARY swapped the slots of %u entry pairs of layer %u\n", sw, L); }
    const uint64_t m0 = g_stream_expert_cache_misses, w0 = g_stream_expert_cache_wraps; const double t0 = llms_sbg_now_ms();
    g_llms_shm_in_restore = 1;   /* llms R0PF */
    for (uint32_t q = 0; q < n; q++) {
        const llms_shm_ent *x = &v[q]; uint32_t si = 0; uint64_t base = 0;
        if (x->layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || x->expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || x->slot >= g_stream_expert_cache_slab_total_slots ||
            !ds4_gpu_stream_expert_slab_slot_range(x->slot, &si, &base) || !llms_shm_slab_is_shm(si)) { g_llms_shm_skip_bad++; continue; }
        if (g_stream_expert_cache[x->layer][x->expert].valid) { g_llms_shm_skip_dup++; continue; }
        if (g_llms_shm_hdr->gen[x->slot] != x->gen) { g_llms_shm_skip_gen++; continue; }
        uint32_t f = 0; while (f < g_stream_expert_cache_free_slot_count && g_stream_expert_cache_free_slots[f] != x->slot) f++;
        if (f == g_stream_expert_cache_free_slot_count) { g_llms_shm_skip_used++; continue; }
        g_stream_expert_cache_free_slots[f] = g_stream_expert_cache_free_slots[--g_stream_expert_cache_free_slot_count];
        id<MTLBuffer> b = g_stream_expert_cache_slabs[si];
        if (!ds4_gpu_stream_expert_cache_install_loaded(g_model_map_ptr, g_model_map_size, x->layer, x->expert, x->gate_abs, x->up_abs, x->down_abs, x->gate_bytes, x->down_bytes,
                b, b, b, (NSUInteger)(base + x->gi), (NSUInteger)(base + x->ui), (NSUInteger)(base + x->di))) {
            ds4_gpu_stream_expert_slab_push_free_slot(x->slot); g_llms_shm_skip_bad++; continue; }
        g_stream_expert_cache_layer_misses[x->layer]--; g_llms_shm_restored++;
    }
    g_llms_shm_in_restore = 0;   /* llms R0PF */
    g_stream_expert_cache_misses = m0; g_stream_expert_cache_wraps = w0;   /* the install counted misses that were not */
    fprintf(stderr, "llms shm cache: %llu of %u entries restored in %.1f ms\n", (unsigned long long)g_llms_shm_restored, n, llms_sbg_now_ms() - t0);
    free(v);
}
static int g_llms_ed_pre;   /* llms ED v4 (apply_ed_prealloc.py): every slab at once */
static void llms_ed_prealloc(void);
static pthread_once_t g_llms_shm_once = PTHREAD_ONCE_INIT;
static void llms_shm_early_body(void) {   /* the ED preallocation (it restores at its end) before the first install, in every path */
    if (!g_llms_ed_pre && g_stream_expert_cache_slab_slot_bytes != 0) { g_llms_ed_pre = 1; llms_ed_prealloc(); }
    else llms_shm_restore();
}
static void llms_shm_early(void) { if (g_llms_shm >= 1 && g_llms_shm_ok == 1 && !g_llms_shm_restore_done) pthread_once(&g_llms_shm_once, llms_shm_early_body); }   /* the canary too */
static void llms_ed_prealloc(void) {
    ds4_gpu_llms_startup_mark("ed prealloc: entry");   /* llms STARTUP_LOG */
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    const uint64_t slot_bytes = g_stream_expert_cache_slab_slot_bytes;
    if (!budget || !slot_bytes) return;
    uint32_t pushed = 0, made = 0;
    if (g_stream_expert_cache_slab_count != 0) {   /* the lazily created last slab: its unused tail onto the free list */
        const uint32_t last = g_stream_expert_cache_slab_count - 1u;
        while (g_stream_expert_cache_slab_slots_used[last] < g_stream_expert_cache_slab_slot_count[last]) {
            ds4_gpu_stream_expert_slab_push_free_slot(g_stream_expert_cache_slab_start_slot[last] + g_stream_expert_cache_slab_slots_used[last]);
            g_stream_expert_cache_slab_slots_used[last]++; pushed++;
        }
    }
    while (g_stream_expert_cache_slab_total_slots < budget && g_stream_expert_cache_slab_count < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SLABS) {
        uint64_t slots64 = ds4_gpu_stream_expert_slab_target_bytes() / slot_bytes;
        if (slots64 == 0) slots64 = 1;
        uint32_t slots = slots64 > UINT32_MAX ? UINT32_MAX : (uint32_t)slots64;
        if (slots > budget - g_stream_expert_cache_slab_total_slots) slots = budget - g_stream_expert_cache_slab_total_slots;
        id<MTLBuffer> b = nil;
        while (slots != 0) {
            if ((uint64_t)slots * slot_bytes <= (uint64_t)NSUIntegerMax) { b = ds4_gpu_stream_expert_alloc_slab_buffer((uint64_t)slots * slot_bytes, @"ds4_stream_expert_slab"); if (b) break; }
            slots /= 2u;
        }
        if (!b || slots == 0) break;
        const uint32_t slab = g_stream_expert_cache_slab_count++;
        g_stream_expert_cache_slabs[slab] = b;
        g_llms_ld_lo[slab] = (uint8_t *)[b contents]; g_llms_ld_hi[slab] = g_llms_ld_lo[slab] ? g_llms_ld_lo[slab] + (uint64_t)slots * slot_bytes : NULL; g_llms_ld_slabs = slab + 1u;
        g_stream_expert_cache_slab_start_slot[slab] = g_stream_expert_cache_slab_total_slots;
        g_stream_expert_cache_slab_slot_count[slab] = slots; g_stream_expert_cache_slab_slots_used[slab] = slots;
        for (uint32_t k = slots; k-- > 0; ) { ds4_gpu_stream_expert_slab_push_free_slot(g_stream_expert_cache_slab_total_slots + k); pushed++; }
        g_stream_expert_cache_slab_total_slots += slots; made++;
    }
    fprintf(stderr, "llms ed: slabs preallocated (%u new, %u slots onto the free list; %u of %u slots)\n", made, pushed, g_stream_expert_cache_slab_total_slots, budget);
    llms_shm_restore();   /* llms SHM_CACHE */
    ds4_gpu_llms_startup_mark("shm restore: done");   /* llms STARTUP_LOG */
}

static uint64_t ds4_gpu_stream_expert_buffer_object_count(
        id<MTLBuffer> gate,
        id<MTLBuffer> up,
        id<MTLBuffer> down) {
    if (!gate || !up || !down) return 0;
    if (gate == up && gate == down) return 1;
    if (gate == up || gate == down || up == down) return 2;
    return 3;
}

static int ds4_gpu_stream_expert_evict_dontneed_enabled(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_EVICT_DONTNEED") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_EVICT_DONTNEED") == NULL;
}

static void ds4_gpu_stream_expert_evict_dontneed_range(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    offset,
        uint64_t    len) {
    if (!ds4_gpu_stream_expert_evict_dontneed_enabled() ||
        !model_map ||
        model_size == 0 ||
        offset > model_size ||
        len == 0 ||
        len > model_size - offset) {
        return;
    }

#if defined(POSIX_MADV_DONTNEED)
    const uint64_t page = (uint64_t)getpagesize();
    const uint64_t page_offset = offset & ~(page - 1);
    const uint64_t leading = offset - page_offset;
    if (len > UINT64_MAX - leading ||
        leading + len > UINT64_MAX - (page - 1)) {
        return;
    }
    uint64_t advise_bytes = round_up_u64(leading + len, page);
    if (advise_bytes > model_size - page_offset) {
        advise_bytes = model_size - page_offset;
    }
    if (advise_bytes == 0 || advise_bytes > (uint64_t)SIZE_MAX) return;

    const uintptr_t base = (uintptr_t)model_map;
    if (page_offset > (uint64_t)(UINTPTR_MAX - base)) return;
    void *addr = (void *)(base + (uintptr_t)page_offset);
    const int rc = posix_madvise(addr, (size_t)advise_bytes, POSIX_MADV_DONTNEED);
    if (rc == 0) {
        if (g_stream_expert_cache_evict_advise_bytes > UINT64_MAX - advise_bytes) {
            g_stream_expert_cache_evict_advise_bytes = UINT64_MAX;
        } else {
            g_stream_expert_cache_evict_advise_bytes += advise_bytes;
        }
    } else if (getenv("DS4_METAL_STREAMING_EXPERT_EVICT_DONTNEED_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal streaming expert evict DONTNEED failed offset=%.2f GiB len=%.2f MiB: %s\n",
                ds4_gpu_gib(offset),
                ds4_gpu_mib(len),
                strerror(rc));
    }
#else
    (void)model_map;
    (void)model_size;
    (void)offset;
    (void)len;
#endif
}

static int ds4_gpu_stream_expert_split_requested(void) {
    return g_ssd_streaming_mode;
}

static uint32_t ds4_gpu_stream_expert_split_min_decode_tokens(void) {
    return 4;
}

static uint32_t ds4_gpu_stream_expert_split_min_cached(void) {
    uint32_t min_cached = 1024;
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (budget != 0 && budget < min_cached * 2u) {
        min_cached = budget / 2u;
    }
    return min_cached;
}

static int ds4_gpu_stream_expert_split_ready(void) {
    if (!ds4_gpu_stream_expert_split_requested()) return 0;
    if (g_stream_expert_cache_decode_tokens <
        ds4_gpu_stream_expert_split_min_decode_tokens()) {
        return 0;
    }
    return g_stream_expert_cache_entry_count >=
           ds4_gpu_stream_expert_split_min_cached();
}

static void ds4_gpu_stream_expert_cache_decay_route_hotness(void) {
    for (uint32_t layer = 0;
         layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER;
         layer++) {
        for (uint32_t expert = 0;
             expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
             expert++) {
            g_stream_expert_cache_route_hotness[layer][expert] >>= 1;
        }
    }
}

void ds4_gpu_stream_expert_cache_reset_route_hotness(void) {
    memset(g_stream_expert_cache_route_hotness,
           0,
           sizeof(g_stream_expert_cache_route_hotness));
    g_stream_expert_cache_hotness_decay_token =
        g_stream_expert_cache_decode_tokens;
}

/* llms LLMS_DS4_HOTNESS_DECAY=N: decay interval in decode tokens (default: the built-in constant) */
static uint64_t ds4_gpu_stream_expert_hotness_decay_tokens(void) {
    static uint64_t v = 0;
    if (v == 0) {
        const char *e = getenv("LLMS_DS4_HOTNESS_DECAY");
        long n = e ? strtol(e, NULL, 10) : 0;
        v = n > 0 ? (uint64_t)n : (uint64_t)DS4_METAL_STREAM_EXPERT_HOTNESS_DECAY_TOKENS;
        if (e) fprintf(stderr, "llms: expert hotness decays every %llu decode tokens\n", (unsigned long long)v);
    }
    return v;
}

static void ds4_gpu_stream_expert_cache_maybe_decay_route_hotness(void) {
    if (g_stream_expert_cache_decode_tokens == 0) return;
    if (g_stream_expert_cache_hotness_decay_token == 0) {
        g_stream_expert_cache_hotness_decay_token =
            g_stream_expert_cache_decode_tokens;
        return;
    }
    while (g_stream_expert_cache_decode_tokens -
           g_stream_expert_cache_hotness_decay_token >=
           ds4_gpu_stream_expert_hotness_decay_tokens()) {
        ds4_gpu_stream_expert_cache_decay_route_hotness();
        g_stream_expert_cache_hotness_decay_token +=
            ds4_gpu_stream_expert_hotness_decay_tokens();
    }
}

static void ds4_gpu_stream_expert_cache_note_route_hotness(
        uint32_t layer,
        uint32_t expert,
        uint32_t amount) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        amount == 0) {
        return;
    }
    uint32_t *hotness = &g_stream_expert_cache_route_hotness[layer][expert];
    if (*hotness > UINT32_MAX - amount) {
        *hotness = UINT32_MAX;
    } else {
        *hotness += amount;
    }
}

static void ds4_gpu_stream_expert_cache_note_selected_hotness(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected) {
    if (!selected_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0) {
        return;
    }
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 ||
            selected_ids[i] >=
                (int32_t)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
            continue;
        }
        ds4_gpu_stream_expert_cache_note_route_hotness(
                layer,
                (uint32_t)selected_ids[i],
                1);
    }
}

static void ds4_gpu_stream_expert_cache_note_frequency_hotness(
        uint32_t        layer,
        const uint32_t *frequency,
        uint32_t        n_total_expert) {
    if (!frequency || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        return;
    }
    if (n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        n_total_expert = DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
    }
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    for (uint32_t expert = 0; expert < n_total_expert; expert++) {
        ds4_gpu_stream_expert_cache_note_route_hotness(layer,
                                                       expert,
                                                       frequency[expert]);
    }
}

static void ds4_gpu_stream_expert_cache_note_token(uint32_t layer_index) {
    if (!g_ssd_streaming_mode ||
        g_stream_expert_cache_decode_tokens == UINT64_MAX) {
        return;
    }
    /* GLM starts with dense layers; a pipeline slice may start even later.
     * Typed and generic routed kernels must advance the same aging clock. */
    if (layer_index < g_stream_expert_cache_first_decode_layer)
        g_stream_expert_cache_first_decode_layer = layer_index;
    if (layer_index != g_stream_expert_cache_first_decode_layer) return;
    g_stream_expert_cache_decode_tokens++;
    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
}


static int g_llms_decode_aging_clock = -1; static uint64_t g_llms_decode_aging_clock_ticks, g_llms_decode_aging_clock_halvings;
static void llms_decode_aging_clock_report(void) {
    fprintf(stderr, "llms one clock: %llu ticks, %llu decode tokens counted, %llu hotness halvings (every %llu tokens)\n", (unsigned long long)g_llms_decode_aging_clock_ticks,
            (unsigned long long)g_stream_expert_cache_decode_tokens, (unsigned long long)g_llms_decode_aging_clock_halvings, (unsigned long long)ds4_gpu_stream_expert_hotness_decay_tokens());
}
static inline int llms_decode_aging_clock(void) {
    if (g_llms_decode_aging_clock < 0) { const char *e = getenv("LLMS_DS4_DECODE_AGING_CLOCK"); g_llms_decode_aging_clock = (e && *e && strcmp(e, "0") != 0) ? 1 : 0;
                                if (g_llms_decode_aging_clock) { fprintf(stderr, "llms: one-token decode ticks the expert aging clock (DECODE_AGING_CLOCK)\n"); atexit(llms_decode_aging_clock_report); } }
    return g_llms_decode_aging_clock;
}
static void llms_decode_aging_clock_tick(uint32_t layer_index) {
    const uint64_t mark = g_stream_expert_cache_hotness_decay_token;
    ds4_gpu_stream_expert_cache_note_token(layer_index); g_llms_decode_aging_clock_ticks++;
    if (g_stream_expert_cache_hotness_decay_token != mark && mark != 0) g_llms_decode_aging_clock_halvings += (g_stream_expert_cache_hotness_decay_token - mark) / ds4_gpu_stream_expert_hotness_decay_tokens();
}

/* llms STEP_CLOCK (apply_ds4_step_clock.py): one tick per batched decode step; every LLMS_DS4_HOTNESS_DECAY ticks the route hotness
 * halves (ds4's own aging, which its token clock never runs in the batched step). Own counter: the shared clock gates the split paths. */
static uint64_t g_llms_sclk_steps, g_llms_sclk_halvings;
static void llms_sclk_report(void) { fprintf(stderr, "llms step clock: %llu steps, %llu hotness halvings\n", (unsigned long long)g_llms_sclk_steps, (unsigned long long)g_llms_sclk_halvings); }
void ds4_gpu_llms_step_clock(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_STEP_CLOCK"); on = e && *e && *e != '0';
                  if (on) { fprintf(stderr, "llms: step clock (expert hotness halves every %llu batched steps)\n", (unsigned long long)ds4_gpu_stream_expert_hotness_decay_tokens()); atexit(llms_sclk_report); } }
    if (!on || !g_ssd_streaming_mode) return;
    g_llms_sclk_steps++;
    if (g_llms_sclk_steps % ds4_gpu_stream_expert_hotness_decay_tokens() == 0 && !ds4_gpu_llms_alt_off("sclk")) {
        ds4_gpu_stream_expert_cache_decay_route_hotness(); g_llms_sclk_halvings++;
    }
}

static int ds4_gpu_stream_compact_addr_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_COMPACT_ADDR") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_COMPACT_ADDR") == NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_addr_table_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            g_stream_prefill_batch_selected_addr_building ||
            g_glm_stream_expert_addr_table_building ||
            (getenv("DS4_METAL_ENABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL &&
             getenv("DS4_METAL_DISABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") == NULL) ||
            ds4_gpu_stream_expert_split_requested()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_addr_table_kernel_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL ||
            getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            ds4_gpu_stream_expert_split_ready()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") == NULL;
}

static int ds4_gpu_stream_expert_masked_addr_requested(void) {
    return g_ssd_streaming_mode &&
           (getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_MASKED_ADDR") != NULL ||
            ds4_gpu_stream_expert_split_ready()) &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_MASKED_ADDR") == NULL;
}

static int ds4_gpu_stream_expert_hit_validator_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_EXPERT_HIT_VALIDATOR") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_HIT_VALIDATOR") == NULL;
}

static uint32_t ds4_gpu_stream_prefill_batch_selected_addr_auto_max(
        uint32_t n_total_expert) {
    const char *env = llms_genv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_MAX");
    if (env && env[0]) {
        char *end = NULL;
        const long v = strtol(env, &end, 10);
        if (end != env) {
            if (v <= 0) return 0;
            if ((unsigned long)v > (unsigned long)UINT32_MAX) return UINT32_MAX;
            return (uint32_t)v;
        }
    }
    if (n_total_expert == 384) return 800u;
    if (n_total_expert == 256) return 760u;
    return 0;
}

static uint32_t ds4_gpu_stream_prefill_batch_selected_addr_auto_min(
        uint32_t n_total_expert) {
    const char *env = getenv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_MIN");
    if (env && env[0]) {
        char *end = NULL;
        const long v = strtol(env, &end, 10);
        if (end != env) {
            if (v <= 0) return 0;
            if ((unsigned long)v > (unsigned long)UINT32_MAX) return UINT32_MAX;
            return (uint32_t)v;
        }
    }
    if (n_total_expert == 384 || n_total_expert == 256) return 2u;
    return 0;
}

static int ds4_gpu_stream_prefill_batch_selected_addr_enabled(
        uint32_t n_tokens,
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint32_t gate_type,
        uint32_t down_type) {
    const int llms_one1 = g_llms_decode_experts_bs64 > 0 && g_llms_gubs_active && n_tokens == 1;   /* llms ONE_BS6C v2 */
    if (!g_ssd_streaming_mode ||
        (n_tokens <= 1 && !llms_one1) ||
        n_total_expert == 0 ||
        n_expert != 6 ||
        gate_type != DS4_METAL_TENSOR_IQ2_XXS ||
        down_type != DS4_METAL_TENSOR_Q2_K ||
        g_quality_mode ||
        getenv("DS4_METAL_DISABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL ||
        getenv("DS4_METAL_DISABLE_STREAMING_EXPERT_ADDR_TABLE") != NULL ||
        llms_genv("DS4_METAL_MOE_WRITE_CLAMPED_ACT") != NULL ||
        getenv("DS4_METAL_DISABLE_ROUTED_PAIR_SWIGLU_FUSION") != NULL) {
        return 0;
    }
    /* All unique experts for one layer must fit simultaneously because the
     * address-table kernels consume them in one dispatch. Once the global
     * cache fills, preparation reuses entries owned by other layers. */
    if (ds4_gpu_stream_expert_cache_configured_count() < n_total_expert) {
        return 0;
    }
    if (getenv("DS4_METAL_ENABLE_STREAMING_PREFILL_BATCH_SELECTED_ADDR") != NULL) {
        return 1;
    }
    const uint32_t max_tokens =
        ds4_gpu_stream_prefill_batch_selected_addr_auto_max(n_total_expert);
    const uint32_t min_tokens =
        ds4_gpu_stream_prefill_batch_selected_addr_auto_min(n_total_expert);
    return max_tokens != 0 && (n_tokens >= min_tokens || llms_one1) && n_tokens <= max_tokens;   /* llms ONE_BS6C v2 */
}

static int ds4_gpu_glm_streaming_prefill_full_layer_active(void) {
    return g_glm_streaming_prefill_full_layer_runtime ||
           getenv("DS4_METAL_GLM_STREAMING_PREFILL_FULL_LAYER") != NULL;
}

static int ds4_gpu_stream_full_expert_addr_table_requested(void) {
    return g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_STREAMING_FULL_EXPERT_ADDR_TABLE") != NULL &&
           getenv("DS4_METAL_DISABLE_STREAMING_FULL_EXPERT_ADDR_TABLE") == NULL;
}

static uint64_t ds4_gpu_buffer_address(id<MTLBuffer> buffer, NSUInteger inner) {
    if (!buffer) return 0;
#if TARGET_OS_OSX
    if (@available(macOS 13.0, *)) {
        return (uint64_t)[buffer gpuAddress] + (uint64_t)inner;
    }
#endif
    return 0;
}

static int ds4_gpu_stream_compact_addr_ensure_buffers(uint32_t layer) {
    if (!g_device || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 0;

    const NSUInteger addr_bytes = 6u * sizeof(uint64_t);
    const NSUInteger ids_bytes = 6u * sizeof(int32_t);
    for (uint32_t i = 0; i < 4; i++) {
        id<MTLBuffer> current = nil;
        NSUInteger bytes = addr_bytes;
        NSString *label = @"ds4_stream_compact_gate_addresses";
        switch (i) {
        case 0:
            current = g_stream_compact_gate_addr_buffers[layer];
            label = @"ds4_stream_compact_gate_addresses";
            break;
        case 1:
            current = g_stream_compact_up_addr_buffers[layer];
            label = @"ds4_stream_compact_up_addresses";
            break;
        case 2:
            current = g_stream_compact_down_addr_buffers[layer];
            label = @"ds4_stream_compact_down_addresses";
            break;
        default:
            current = g_stream_compact_selected_buffers[layer];
            bytes = ids_bytes;
            label = @"ds4_stream_compact_selected_ids";
            break;
        }
        if (current) continue;
        id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                                options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming compact address buffer allocation failed\n");
            return 0;
        }
        b.label = label;
        memset([b contents], 0, bytes);
        switch (i) {
        case 0:
            g_stream_compact_gate_addr_buffers[layer] = b;
            break;
        case 1:
            g_stream_compact_up_addr_buffers[layer] = b;
            break;
        case 2:
            g_stream_compact_down_addr_buffers[layer] = b;
            break;
        default:
            g_stream_compact_selected_buffers[layer] = b;
            break;
        }
    }
    return 1;
}

static int ds4_gpu_stream_compact_addr_prepare(
        uint32_t layer,
        ds4_gpu_stream_expert_cache_entry * const entries[6],
        uint32_t n_entries,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        id<MTLBuffer> *selected_ids) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        !entries || !gate_addrs || !up_addrs || !down_addrs || !selected_ids ||
        n_entries == 0 || n_entries > 6) {
        return 0;
    }
    if (!ds4_gpu_stream_compact_addr_ensure_buffers(layer)) return 0;

    uint64_t gate_values[6] = {0, 0, 0, 0, 0, 0};
    uint64_t up_values[6] = {0, 0, 0, 0, 0, 0};
    uint64_t down_values[6] = {0, 0, 0, 0, 0, 0};
    int32_t slot_ids[6] = {0, 1, 2, 3, 4, 5};

    for (uint32_t i = 0; i < n_entries; i++) {
        ds4_gpu_stream_expert_cache_entry *e = entries[i];
        if (!e || !e->gate_buffer || !e->up_buffer || !e->down_buffer) {
            return 0;
        }
        gate_values[i] = ds4_gpu_buffer_address(e->gate_buffer, e->gate_inner);
        up_values[i] = ds4_gpu_buffer_address(e->up_buffer, e->up_inner);
        down_values[i] = ds4_gpu_buffer_address(e->down_buffer, e->down_inner);
        if (gate_values[i] == 0 || up_values[i] == 0 || down_values[i] == 0) {
            fprintf(stderr, "ds4: Metal streaming compact address path requires GPU addresses\n");
            return 0;
        }
    }

    const NSUInteger addr_bytes = 6u * sizeof(uint64_t);
    const NSUInteger ids_bytes = 6u * sizeof(int32_t);
    id<MTLBuffer> gb = g_stream_compact_gate_addr_buffers[layer];
    id<MTLBuffer> ub = g_stream_compact_up_addr_buffers[layer];
    id<MTLBuffer> db = g_stream_compact_down_addr_buffers[layer];
    id<MTLBuffer> ib = g_stream_compact_selected_buffers[layer];
    memcpy([gb contents], gate_values, addr_bytes);
    memcpy([ub contents], up_values, addr_bytes);
    memcpy([db contents], down_values, addr_bytes);
    memcpy([ib contents], slot_ids, ids_bytes);

    *gate_addrs = gb;
    *up_addrs = ub;
    *down_addrs = db;
    *selected_ids = ib;
    return 1;
}

static int ds4_gpu_stream_selected_ids_prepare(
        uint32_t       layer,
        const int32_t *selected_ids,
        uint32_t       n_selected,
        id<MTLBuffer> *selected_buf,
        NSUInteger    *selected_off) {
    if (!g_device ||
        !selected_ids ||
        !selected_buf ||
        !selected_off ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > DS4_METAL_MAX_ROUTED_EXPERT_USED) {
        return 0;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_MAX_ROUTED_EXPERT_USED * sizeof(int32_t);
    id<MTLBuffer> b = g_stream_selected_id_buffers[layer];
    if (!b) {
        b = [g_device newBufferWithLength:bytes
                                  options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming selected-id buffer allocation failed\n");
            return 0;
        }
        b.label = @"ds4_stream_selected_ids";
        g_stream_selected_id_buffers[layer] = b;
    }

    int32_t ids[DS4_METAL_MAX_ROUTED_EXPERT_USED] = {0};
    memcpy(ids, selected_ids, (size_t)n_selected * sizeof(ids[0]));
    memcpy([b contents], ids, bytes);

    *selected_buf = b;
    *selected_off = 0;
    return 1;
}

static int ds4_gpu_stream_expert_cache_ensure_addr_buffers(uint32_t layer) {
    if (!g_device ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) {
        return 0;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT * sizeof(uint64_t);
    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    for (uint32_t i = 0; i < 3; i++) {
        if (buffers[i]) continue;
        id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                                options:MTLResourceStorageModeShared];
        if (!b) {
            fprintf(stderr, "ds4: Metal streaming expert address table allocation failed\n");
            return 0;
        }
        b.label =
            i == 0 ? @"ds4_stream_expert_gate_addresses" :
            (i == 1 ? @"ds4_stream_expert_up_addresses" :
                      @"ds4_stream_expert_down_addresses");
        memset([b contents], 0, bytes);
        if (i == 0) {
            g_stream_expert_cache_gate_addr_buffers[layer] = b;
        } else if (i == 1) {
            g_stream_expert_cache_up_addr_buffers[layer] = b;
        } else {
            g_stream_expert_cache_down_addr_buffers[layer] = b;
        }
    }
    return 1;
}

static void ds4_gpu_stream_expert_cache_zero_addr_slot(uint32_t layer, uint32_t expert) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        return;
    }

    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    const NSUInteger off = (NSUInteger)expert * sizeof(uint64_t);
    for (uint32_t i = 0; i < 3; i++) {
        if (!buffers[i]) continue;
        uint64_t *addr = (uint64_t *)((uint8_t *)[buffers[i] contents] + off);
        *addr = 0;
    }
}

static int ds4_gpu_stream_expert_cache_set_addr_slot_raw(
        uint32_t      layer,
        uint32_t      expert,
        id<MTLBuffer> gate_buffer,
        NSUInteger    gate_inner,
        id<MTLBuffer> up_buffer,
        NSUInteger    up_inner,
        id<MTLBuffer> down_buffer,
        NSUInteger    down_inner) {
    if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) return 0;

    const uint64_t values[3] = {
        ds4_gpu_buffer_address(gate_buffer, gate_inner),
        ds4_gpu_buffer_address(up_buffer, up_inner),
        ds4_gpu_buffer_address(down_buffer, down_inner),
    };
    if (values[0] == 0 || values[1] == 0 || values[2] == 0) {
        fprintf(stderr, "ds4: Metal streaming expert address table requires GPU addresses\n");
        return 0;
    }

    id<MTLBuffer> buffers[3] = {
        g_stream_expert_cache_gate_addr_buffers[layer],
        g_stream_expert_cache_up_addr_buffers[layer],
        g_stream_expert_cache_down_addr_buffers[layer],
    };
    const NSUInteger off = (NSUInteger)expert * sizeof(uint64_t);
    for (uint32_t i = 0; i < 3; i++) {
        uint64_t *addr = (uint64_t *)((uint8_t *)[buffers[i] contents] + off);
        *addr = values[i];
    }
    return 1;
}

static int ds4_gpu_stream_expert_cache_set_addr_slot(
        uint32_t      layer,
        uint32_t      expert,
        id<MTLBuffer> gate_buffer,
        NSUInteger    gate_inner,
        id<MTLBuffer> up_buffer,
        NSUInteger    up_inner,
        id<MTLBuffer> down_buffer,
        NSUInteger    down_inner) {
    if (!ds4_gpu_stream_expert_addr_table_requested()) return 1;
    return ds4_gpu_stream_expert_cache_set_addr_slot_raw(layer,
                                                         expert,
                                                         gate_buffer,
                                                         gate_inner,
                                                         up_buffer,
                                                         up_inner,
                                                         down_buffer,
                                                         down_inner);
}

static int ds4_gpu_stream_expert_cache_addr_buffers(
        uint32_t       layer,
        id<MTLBuffer> *gate,
        id<MTLBuffer> *up,
        id<MTLBuffer> *down) {
    if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) return 0;
    if (gate) *gate = g_stream_expert_cache_gate_addr_buffers[layer];
    if (up) *up = g_stream_expert_cache_up_addr_buffers[layer];
    if (down) *down = g_stream_expert_cache_down_addr_buffers[layer];
    return g_stream_expert_cache_gate_addr_buffers[layer] &&
           g_stream_expert_cache_up_addr_buffers[layer] &&
           g_stream_expert_cache_down_addr_buffers[layer];
}

static void ds4_gpu_stream_full_expert_addr_clear_layer(uint32_t layer) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return;
    ds4_gpu_stream_expert_cache_entry *e = &g_stream_full_expert_addr_entry[layer];
    e->gate_buffer = nil;
    e->up_buffer = nil;
    e->down_buffer = nil;
    e->model_map = NULL;
    e->model_size = 0;
    e->gate_abs_offset = 0;
    e->up_abs_offset = 0;
    e->down_abs_offset = 0;
    e->gate_expert_bytes = 0;
    e->down_expert_bytes = 0;
    e->logical_bytes = 0;
    e->last_used = 0;
    e->use_count = 0;
    e->gate_inner = 0;
    e->up_inner = 0;
    e->down_inner = 0;
    e->slab_slot = 0;
    e->valid = 0;
    e->slab_backed = 0;
}

static int ds4_gpu_stream_full_expert_addr_table_prepare(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        uint32_t       n_total_expert,
        uint64_t       gate_abs_offset,
        uint64_t       up_abs_offset,
        uint64_t       down_abs_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        ds4_gpu_stream_expert_cache_entry **entry_out) {
    if (!ds4_gpu_stream_full_expert_addr_table_requested()) return 0;
    if (!model_map || model_size == 0 ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        n_total_expert > UINT64_MAX / gate_expert_bytes ||
        n_total_expert > UINT64_MAX / down_expert_bytes) {
        return 0;
    }

    const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_abs_offset > model_size ||
        up_abs_offset > model_size ||
        down_abs_offset > model_size ||
        gate_tensor_bytes > model_size - gate_abs_offset ||
        gate_tensor_bytes > model_size - up_abs_offset ||
        down_tensor_bytes > model_size - down_abs_offset) {
        return 0;
    }

    ds4_gpu_stream_expert_cache_entry *entry =
        &g_stream_full_expert_addr_entry[layer];
    if (!entry->valid ||
        entry->model_map != model_map ||
        entry->model_size != model_size ||
        entry->gate_abs_offset != gate_abs_offset ||
        entry->up_abs_offset != up_abs_offset ||
        entry->down_abs_offset != down_abs_offset ||
        entry->gate_expert_bytes != gate_expert_bytes ||
        entry->down_expert_bytes != down_expert_bytes ||
        !entry->gate_buffer ||
        !entry->up_buffer ||
        !entry->down_buffer) {
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);

        uint64_t gate_inner = 0;
        uint64_t up_inner = 0;
        uint64_t down_inner = 0;
        id<MTLBuffer> gate_buf =
            ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                 model_size,
                                                 gate_abs_offset,
                                                 gate_tensor_bytes,
                                                 &gate_inner);
        id<MTLBuffer> up_buf =
            ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                 model_size,
                                                 up_abs_offset,
                                                 gate_tensor_bytes,
                                                 &up_inner);
        id<MTLBuffer> down_buf =
            ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                 model_size,
                                                 down_abs_offset,
                                                 down_tensor_bytes,
                                                 &down_inner);
        if (!gate_buf || !up_buf || !down_buf) return 0;

        entry->gate_buffer = gate_buf;
        entry->up_buffer = up_buf;
        entry->down_buffer = down_buf;
        entry->model_map = model_map;
        entry->model_size = model_size;
        entry->gate_abs_offset = gate_abs_offset;
        entry->up_abs_offset = up_abs_offset;
        entry->down_abs_offset = down_abs_offset;
        entry->gate_expert_bytes = gate_expert_bytes;
        entry->down_expert_bytes = down_expert_bytes;
        entry->logical_bytes = gate_tensor_bytes * 2ull + down_tensor_bytes;
        entry->gate_inner = (NSUInteger)gate_inner;
        entry->up_inner = (NSUInteger)up_inner;
        entry->down_inner = (NSUInteger)down_inner;
        entry->valid = 1;

        if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) {
            ds4_gpu_stream_full_expert_addr_clear_layer(layer);
            return 0;
        }

        const uint64_t gate_base = ds4_gpu_buffer_address(entry->gate_buffer,
                                                          entry->gate_inner);
        const uint64_t up_base = ds4_gpu_buffer_address(entry->up_buffer,
                                                        entry->up_inner);
        const uint64_t down_base = ds4_gpu_buffer_address(entry->down_buffer,
                                                          entry->down_inner);
        if (gate_base == 0 || up_base == 0 || down_base == 0) {
            fprintf(stderr, "ds4: Metal full streaming expert address table requires GPU addresses\n");
            ds4_gpu_stream_full_expert_addr_clear_layer(layer);
            return 0;
        }

        id<MTLBuffer> buffers[3] = {
            g_stream_expert_cache_gate_addr_buffers[layer],
            g_stream_expert_cache_up_addr_buffers[layer],
            g_stream_expert_cache_down_addr_buffers[layer],
        };
        uint64_t *gate_addr = (uint64_t *)[buffers[0] contents];
        uint64_t *up_addr = (uint64_t *)[buffers[1] contents];
        uint64_t *down_addr = (uint64_t *)[buffers[2] contents];
        for (uint32_t expert = 0; expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; expert++) {
            if (expert < n_total_expert) {
                gate_addr[expert] = gate_base + (uint64_t)expert * gate_expert_bytes;
                up_addr[expert] = up_base + (uint64_t)expert * gate_expert_bytes;
                down_addr[expert] = down_base + (uint64_t)expert * down_expert_bytes;
            } else {
                gate_addr[expert] = 0;
                up_addr[expert] = 0;
                down_addr[expert] = 0;
            }
        }
    }

    if (gate_addrs) *gate_addrs = g_stream_expert_cache_gate_addr_buffers[layer];
    if (up_addrs) *up_addrs = g_stream_expert_cache_up_addr_buffers[layer];
    if (down_addrs) *down_addrs = g_stream_expert_cache_down_addr_buffers[layer];
    if (entry_out) *entry_out = entry;
    return entry->valid &&
           g_stream_expert_cache_gate_addr_buffers[layer] &&
           g_stream_expert_cache_up_addr_buffers[layer] &&
           g_stream_expert_cache_down_addr_buffers[layer];
}

static id<MTLBuffer> ds4_gpu_stream_expert_validate_status_buffer(void) {
    if (!g_device) return nil;
    if (g_stream_expert_validate_status_buffer) {
        return g_stream_expert_validate_status_buffer;
    }

    const NSUInteger bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_VALIDATE_WORDS * sizeof(uint32_t);
    id<MTLBuffer> b = [g_device newBufferWithLength:bytes
                                            options:MTLResourceStorageModeShared];
    if (!b) {
        fprintf(stderr, "ds4: Metal streaming expert validator allocation failed\n");
        return nil;
    }
    b.label = @"ds4_stream_expert_validate_status";
    memset([b contents], 0, bytes);
    g_stream_expert_validate_status_buffer = b;
    return b;
}

static int ds4_gpu_encode_stream_expert_cache_validate(
        id<MTLCommandBuffer> cb,
        const ds4_gpu_stream_expert_validate_args *args,
        id<MTLBuffer> selected,
        NSUInteger selected_off,
        id<MTLBuffer> gate_addrs,
        id<MTLBuffer> up_addrs,
        id<MTLBuffer> down_addrs,
        id<MTLBuffer> status) {
    if (!cb || !args || !selected || !gate_addrs || !up_addrs || !down_addrs ||
        !status || !g_moe_stream_expert_cache_validate_pipeline ||
        args->n_total_expert == 0 || args->n_total_expert > 384 ||
        args->n_expert == 0 || args->n_expert > 6) {
        return 0;
    }

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_moe_stream_expert_cache_validate_pipeline];
    [enc setBytes:args length:sizeof(*args) atIndex:0];
    [enc setBuffer:selected offset:selected_off atIndex:1];
    [enc setBuffer:gate_addrs offset:0 atIndex:2];
    [enc setBuffer:up_addrs offset:0 atIndex:3];
    [enc setBuffer:down_addrs offset:0 atIndex:4];
    [enc setBuffer:status offset:0 atIndex:5];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_stream_expert_cache_validate_selected(
        const ds4_gpu_tensor *selected,
        id<MTLBuffer> gate_addrs,
        id<MTLBuffer> up_addrs,
        id<MTLBuffer> down_addrs,
        uint32_t n_total_expert,
        uint32_t n_expert,
        int32_t selected_ids[6],
        uint32_t *all_cached,
        uint32_t *miss_mask,
        uint32_t *invalid_mask) {
    if (!selected || !selected_ids || !all_cached || !miss_mask || !invalid_mask) {
        return 0;
    }
    id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
    id<MTLBuffer> status = ds4_gpu_stream_expert_validate_status_buffer();
    if (!selectedbuf || !status) return 0;

    const NSUInteger status_bytes =
        (NSUInteger)DS4_METAL_STREAM_EXPERT_VALIDATE_WORDS * sizeof(uint32_t);
    memset([status contents], 0, status_bytes);

    ds4_gpu_stream_expert_validate_args args = {
        .n_total_expert = n_total_expert,
        .n_expert = n_expert,
    };

    const int had_batch = g_batch_cb != nil;
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    if (!ds4_gpu_encode_stream_expert_cache_validate(cb,
                                                     &args,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     gate_addrs,
                                                     up_addrs,
                                                     down_addrs,
                                                     status)) {
        return 0;
    }

    if (had_batch) {
        if (ds4_gpu_end_commands() == 0) return 0;
    } else if (!ds4_gpu_finish_command_buffer(cb, owned,
                                              "streaming expert cache validator")) {
        return 0;
    }

    const uint32_t *words = (const uint32_t *)[status contents];
    *all_cached = words[0];
    *miss_mask = words[1];
    *invalid_mask = words[2];
    for (uint32_t i = 0; i < 6; i++) {
        selected_ids[i] = (int32_t)words[4 + i];
    }

    if (had_batch && ds4_gpu_begin_commands() == 0) return 0;
    return 1;
}


static int g_llms_seam = -1; static uint32_t g_llms_seam_pfseq, g_llms_seam_lastph = 0xffffffffu;
static uint32_t g_llms_seam_ev[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER][DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];   /* bit 30: evicted once; bit 31: in prefill; low: the prefill seq */
static uint64_t g_llms_seam_n[8], g_llms_seam_e[4], g_llms_seam_tok0;   /* e: the decode-install classes in the first 40 decode tokens after a prefill */   /* 0..3 decode installs (latest prefill / earlier prefill / decode / first time); 4 prefill installs; 5 / 6 prefill / decode evictions; 7 prefill phases */
static void llms_seam_report(void) {
    const uint64_t *n = g_llms_seam_n;
    fprintf(stderr, "llms seam census: decode installs %llu = %llu evicted by the latest prefill + %llu by an earlier prefill + %llu evicted in decode + %llu never evicted; "
            "prefill installs %llu; evictions in prefill %llu, in decode %llu; prefill phases %llu\n", (unsigned long long)(n[0] + n[1] + n[2] + n[3]), (unsigned long long)n[0],
            (unsigned long long)n[1], (unsigned long long)n[2], (unsigned long long)n[3], (unsigned long long)n[4], (unsigned long long)n[5], (unsigned long long)n[6], (unsigned long long)n[7]);
    fprintf(stderr, "llms seam census, the first 40 decode tokens after each prefill: %llu = %llu latest prefill + %llu earlier prefill + %llu decode + %llu never evicted\n",
            (unsigned long long)(g_llms_seam_e[0] + g_llms_seam_e[1] + g_llms_seam_e[2] + g_llms_seam_e[3]), (unsigned long long)g_llms_seam_e[0], (unsigned long long)g_llms_seam_e[1],
            (unsigned long long)g_llms_seam_e[2], (unsigned long long)g_llms_seam_e[3]);
}
static int llms_seam_on(void) {
    if (g_llms_seam < 0) { const char *e = getenv("LLMS_DS4_SEAM_CENSUS"); g_llms_seam = e && *e && *e != '0';
        if (g_llms_seam) { atexit(llms_seam_report); fprintf(stderr, "llms: seam census (every eviction tagged with its phase; every decode install classified)\n"); } }
    return g_llms_seam;
}
static int llms_seam_pf(void) {   /* the phase now (TL 2/3 = prefill); counts each decode -> prefill switch */
    const uint32_t ph = __atomic_load_n(&g_llms_tl_phase, __ATOMIC_RELAXED); const int pf = ph == 2u || ph == 3u;
    if (pf && g_llms_seam_lastph != 1u) { g_llms_seam_pfseq++; __atomic_fetch_add(&g_llms_seam_n[7], 1, __ATOMIC_RELAXED); }
    if (!pf && g_llms_seam_lastph == 1u) g_llms_seam_tok0 = g_stream_expert_cache_decode_tokens;   /* the seam: decode starts */
    g_llms_seam_lastph = pf ? 1u : 0u; return pf;
}
static void llms_seam_evict(uint32_t L, uint32_t x) {
    const int pf = llms_seam_pf(); g_llms_seam_ev[L][x] = 0x40000000u | (pf ? 0x80000000u : 0u) | (g_llms_seam_pfseq & 0x3fffffffu);
    __atomic_fetch_add(&g_llms_seam_n[pf ? 5 : 6], 1, __ATOMIC_RELAXED);
}
static void llms_seam_install(uint32_t L, uint32_t x) {
    if (llms_seam_pf()) { __atomic_fetch_add(&g_llms_seam_n[4], 1, __ATOMIC_RELAXED); return; }
    const uint32_t v = g_llms_seam_ev[L][x];
    const int k = !(v & 0x40000000u) ? 3 : !(v & 0x80000000u) ? 2 : (v & 0x3fffffffu) == (g_llms_seam_pfseq & 0x3fffffffu) ? 0 : 1;
    __atomic_fetch_add(&g_llms_seam_n[k], 1, __ATOMIC_RELAXED);
    if (g_stream_expert_cache_decode_tokens - g_llms_seam_tok0 < 40u) __atomic_fetch_add(&g_llms_seam_e[k], 1, __ATOMIC_RELAXED);
}
static void ds4_gpu_stream_expert_cache_clear_entry_internal(
        uint32_t                                  layer,
        uint32_t                                  expert,
        int                                       count_eviction,
        int                                       recycle_slab_slot,
        ds4_gpu_stream_expert_reusable_buffers   *reuse) {
    if (layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        expert >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) {
        return;
    }
    if (reuse) {
        reuse->gate_buffer = nil;
        reuse->up_buffer = nil;
        reuse->down_buffer = nil;
        reuse->gate_inner = 0;
        reuse->up_inner = 0;
        reuse->down_inner = 0;
    }
    ds4_gpu_stream_expert_cache_entry *e =
        &g_stream_expert_cache[layer][expert];
    if (!e->valid) return;
    if (ds4_gpu_stream_expert_cache_entry_inflight(e)) {
        return;
    }

    const uint64_t bytes = e->logical_bytes;
    ds4_gpu_stream_expert_evict_dontneed_range(e->model_map,
                                               e->model_size,
                                               e->gate_abs_offset,
                                               e->gate_expert_bytes);
    ds4_gpu_stream_expert_evict_dontneed_range(e->model_map,
                                               e->model_size,
                                               e->up_abs_offset,
                                               e->gate_expert_bytes);
    ds4_gpu_stream_expert_evict_dontneed_range(e->model_map,
                                               e->model_size,
                                               e->down_abs_offset,
                                               e->down_expert_bytes);
    {
        static int nz = -1; static uint64_t nz_n;
        if (nz < 0) { const char *ev = getenv("LLMS_DS4_ELA_NOZERO"); nz = ev && *ev && *ev != '0';
                      if (nz) atexit_b(^{ fprintf(stderr, "llms ela nozero: %llu look-ahead evictions left the address in place\n", (unsigned long long)nz_n); }); }
        if (nz && g_llms_ela_inbegin) nz_n++;
        else ds4_gpu_stream_expert_cache_zero_addr_slot(layer, expert);
    }
    if (reuse) {
        reuse->gate_buffer = e->gate_buffer;
        reuse->up_buffer = e->up_buffer;
        reuse->down_buffer = e->down_buffer;
        reuse->gate_inner = e->gate_inner;
        reuse->up_inner = e->up_inner;
        reuse->down_inner = e->down_inner;
    } else if (e->slab_backed && recycle_slab_slot) {
        ds4_gpu_stream_expert_slab_push_free_slot(e->slab_slot);
    } else if (!e->slab_backed) {
        ds4_gpu_stream_expert_unlock_explicit_buffer(e->gate_buffer);
        if (e->up_buffer != e->gate_buffer) {
            ds4_gpu_stream_expert_unlock_explicit_buffer(e->up_buffer);
        }
        if (e->down_buffer != e->gate_buffer &&
            e->down_buffer != e->up_buffer) {
            ds4_gpu_stream_expert_unlock_explicit_buffer(e->down_buffer);
        }
    }
    e->gate_buffer = nil;
    e->up_buffer = nil;
    e->down_buffer = nil;
    e->model_map = NULL;
    e->model_size = 0;
    e->gate_abs_offset = 0;
    e->up_abs_offset = 0;
    e->down_abs_offset = 0;
    e->gate_expert_bytes = 0;
    e->down_expert_bytes = 0;
    e->logical_bytes = 0;
    e->last_used = 0;
    e->use_count = 0;
    e->gate_inner = 0;
    e->up_inner = 0;
    e->down_inner = 0;
    e->inflight_seq = 0;
    e->slab_slot = 0;
    e->valid = 0;
    e->slab_backed = 0;
    g_llms_vbits[layer][expert >> 6] &= ~(1ull << (expert & 63u));   /* llms FAST_VICTIM */

    if (g_stream_expert_cache_layer_count[layer] > 0) {
        g_stream_expert_cache_layer_count[layer]--;
    }
    if (g_stream_expert_cache_entry_count > 0) {
        g_stream_expert_cache_entry_count--;
    }
    if (g_stream_expert_cache_bytes >= bytes) {
        g_stream_expert_cache_bytes -= bytes;
    } else {
        g_stream_expert_cache_bytes = 0;
    }
    if (count_eviction) {
        if (llms_seam_on()) llms_seam_evict(layer, expert);   /* llms SEAM_CENSUS */
        g_stream_expert_cache_evictions++;
        g_stream_expert_cache_layer_evictions[layer]++;
    }
}

static void ds4_gpu_stream_expert_cache_clear_entry(
        uint32_t layer,
        uint32_t expert,
        int      count_eviction) {
    ds4_gpu_stream_expert_cache_clear_entry_internal(layer,
                                                     expert,
                                                     count_eviction,
                                                     1,
                                                     NULL);
}




static int g_llms_r0pf = -1, g_llms_r0_rec;
static uint64_t g_llms_r0_bits[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER][6], g_llms_r0_touch, g_llms_r0_inst;
static ds4_gpu_stream_expert_table g_llms_r0_tab[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER]; static uint8_t g_llms_r0_tabok[DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER];
static int llms_r0pf_on(void) {
    if (g_llms_r0pf < 0) { const char *e = getenv("LLMS_DS4_R0PF"); g_llms_r0pf = e && *e && *e != '0';
                           if (g_llms_r0pf) fprintf(stderr, "llms: r0pf (round 0's experts recorded; at exit the missing ones are loaded before the shm cache is saved)\n"); }
    return g_llms_r0pf;
}
static inline void llms_r0_note(uint32_t layer, uint32_t expert, const void *map, uint64_t size, uint64_t gate_abs, uint64_t up_abs, uint64_t down_abs,
                                uint64_t gb, uint64_t db, int installed) {
    if (!g_llms_r0_rec || g_llms_shm_in_restore || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || expert >= 384u || gb == 0 || db == 0) return;
    uint64_t *w = &g_llms_r0_bits[layer][expert >> 6]; const uint64_t bit = 1ull << (expert & 63u);
    if (!(*w & bit)) { *w |= bit; g_llms_r0_touch++; }
    if (installed) g_llms_r0_inst++;
    if (!g_llms_r0_tabok[layer]) {
        ds4_gpu_stream_expert_table *t = &g_llms_r0_tab[layer];
        t->model_map = map; t->model_size = size; t->layer = layer; t->n_total_expert = 384u;
        t->gate_offset = gate_abs - (uint64_t)expert * gb; t->up_offset = up_abs - (uint64_t)expert * gb; t->down_offset = down_abs - (uint64_t)expert * db;
        t->gate_expert_bytes = gb; t->down_expert_bytes = db; g_llms_r0_tabok[layer] = 1;
    }
}
static void llms_r0pf_exit(void) {   /* llms R0PF: from the teardown's clear_all, right before its llms_shm_save (the cache and the device alive) */
    if (!g_llms_r0_touch) return;
    const double t0 = llms_sbg_now_ms(); const uint64_t m0 = g_stream_expert_cache_misses; uint64_t want = 0, have = 0, asked = 0;
    for (uint32_t L = 0; L < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; L++) {
        if (!g_llms_r0_tabok[L]) continue;
        int32_t ids[384]; uint32_t n = 0;
        for (uint32_t x = 0; x < 384u; x++) {
            if (!((g_llms_r0_bits[L][x >> 6] >> (x & 63u)) & 1ull)) continue;
            want++;
            if (g_stream_expert_cache[L][x].valid) have++; else ids[n++] = (int32_t)x;
        }
        asked += n;
        if (n && !ds4_gpu_stream_expert_cache_seed_experts(&g_llms_r0_tab[L], ids, NULL, n)) { fprintf(stderr, "llms r0pf at exit: the seed failed at layer %u\n", L); break; }
    }
    fprintf(stderr, "llms r0pf at exit: round 0's %llu experts, %llu resident, %llu asked, %llu loaded in %.1f ms\n", (unsigned long long)want, (unsigned long long)have,
            (unsigned long long)asked, (unsigned long long)(g_stream_expert_cache_misses - m0), llms_sbg_now_ms() - t0);
}
void ds4_gpu_llms_r0_record(int on) {   /* llms R0PF: ds4.c calls 1 at the first sync, 0 at the first block-1 decode cycle */
    if (!llms_r0pf_on()) return;
    if (on) { g_llms_r0_rec = 1; return; }
    if (!g_llms_r0_rec) return;
    g_llms_r0_rec = 0;
    fprintf(stderr, "llms r0pf: round 0 touched %llu experts, installed %llu\n", (unsigned long long)g_llms_r0_touch, (unsigned long long)g_llms_r0_inst);
}
static void ds4_gpu_stream_expert_cache_clear_all(int reset_stats) {
    { static int r0x; if (!r0x && g_llms_shm_ok == 1 && g_llms_r0_touch && !g_llms_r0_rec) { r0x = 1; llms_r0pf_exit(); } }   /* llms R0PF: the round-0 set loaded before the save */
    if (g_llms_shm_ok == 1) llms_shm_save();   /* llms SHM_CACHE: the teardown (ds4_gpu_cleanup) clears the cache before atexit runs -- save it first */
    ds4_gpu_stream_expert_pending_load_clear();
    g_stream_expert_cache_done_seq = g_stream_expert_cache_cb_seq;
    g_stream_expert_cache_batch_seq = 0;
    g_stream_expert_cache_owned_seq = 0;
    g_stream_expert_cache_pending_max_seq = 0;
    for (uint32_t layer = 0; layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER; layer++) {
        for (uint32_t expert = 0; expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; expert++) {
            g_stream_expert_cache[layer][expert].inflight_seq = 0;
            ds4_gpu_stream_expert_cache_clear_entry(layer, expert, 0);
        }
        ds4_gpu_stream_full_expert_addr_clear_layer(layer);
        g_stream_expert_cache_layer_count[layer] = 0;
        id<MTLBuffer> buffers[3] = {
            g_stream_expert_cache_gate_addr_buffers[layer],
            g_stream_expert_cache_up_addr_buffers[layer],
            g_stream_expert_cache_down_addr_buffers[layer],
        };
        for (uint32_t i = 0; i < 3; i++) {
            if (!buffers[i]) continue;
            const NSUInteger bytes =
                (NSUInteger)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT * sizeof(uint64_t);
            memset([buffers[i] contents], 0, bytes);
        }
    }
    g_stream_expert_cache_bytes = 0;
    g_stream_expert_cache_entry_count = 0;
    for (uint32_t i = 0; i < g_stream_expert_cache_slab_count; i++) {
        g_stream_expert_cache_slabs[i] = nil;
        g_stream_expert_cache_slab_start_slot[i] = 0;
        g_stream_expert_cache_slab_slot_count[i] = 0;
        g_stream_expert_cache_slab_slots_used[i] = 0;
    }
    g_stream_expert_cache_slab_count = 0;
    g_llms_ld_slabs = 0;   /* llms LOAD_DIRECT */
    g_stream_expert_cache_slab_total_slots = 0;
    g_stream_expert_cache_free_slot_count = 0;
    g_stream_expert_cache_slab_slot_bytes = 0;
    { static int ss2 = -1; if (ss2 < 0) { const char *e = getenv("LLMS_DS4_SLOT_SEED"); ss2 = e && *e && *e != '0'; } if (ss2) g_llms_ed_pre = 0; }
    memset(g_stream_expert_cache_slab_slot_locked,
           0,
           sizeof(g_stream_expert_cache_slab_slot_locked));
    if (reset_stats) {
        g_stream_expert_cache_hits = 0;
        g_stream_expert_cache_misses = 0;
        g_stream_expert_cache_evictions = 0;
        g_stream_expert_cache_wraps = 0;
        g_stream_expert_cache_clock = 0;
        g_stream_expert_cache_evict_advise_bytes = 0;
        g_stream_expert_cache_willneed_advise_bytes = 0;
        g_stream_expert_cache_read_bytes = 0;
        g_stream_expert_cache_pread_ms = 0.0;
        g_stream_expert_cache_mlock_bytes = 0;
        g_stream_expert_cache_mlock_fail_bytes = 0;
        g_stream_expert_cache_mlock_failures = 0;
        g_stream_expert_cache_mlock_ms = 0.0;
        g_stream_expert_cache_mlock_warned = 0;
        g_stream_expert_cache_mlock_budget_cap = 0;
        g_stream_expert_cache_mlock_relief_applied = 0;
        g_stream_expert_cache_buffer_allocs = 0;
        g_stream_expert_cache_buffer_reuses = 0;
        g_stream_expert_cache_decode_tokens = 0;
        g_stream_expert_cache_first_decode_layer = UINT32_MAX;
        g_stream_expert_cache_hotness_decay_token = 0;
        memset(g_stream_expert_cache_route_hotness,
               0,
               sizeof(g_stream_expert_cache_route_hotness));
        g_stream_expert_timing_selected_calls = 0;
        g_stream_expert_timing_selected_read_ms = 0.0;
        g_stream_expert_timing_selected_sync_ms = 0.0;
        g_stream_expert_timing_selected_copy_ms = 0.0;
        g_stream_expert_timing_selected_bind_ms = 0.0;
        g_stream_expert_timing_split_layers = 0;
        g_stream_expert_timing_split_resident_experts = 0;
        g_stream_expert_timing_split_missing_experts = 0;
        g_stream_expert_timing_split_resident_ms = 0.0;
