static uint64_t llms_ticket_issue(ds4_gpu_stream_expert_read_task *tasks, uint32_t n_tasks, uint32_t layer) {
    if (!g_llms_load_q) {
        dispatch_queue_attr_t llms_qa = g_llms_load_concurrent ? DISPATCH_QUEUE_CONCURRENT : DISPATCH_QUEUE_SERIAL; qos_class_t llms_qc;
        if (llms_qos_parse("LLMS_DS4_READER_QOS", &llms_qc)) llms_qa = dispatch_queue_attr_make_with_qos_class(llms_qa, llms_qc, 0);   /* llms READER_QOS */
        llms_main_qos_self();
        g_llms_load_q = dispatch_queue_create("llms.expert.load", llms_qa); atexit(llms_async_report);
    }
    const uint64_t id = g_llms_tk_issued + 1; const int sl = (int)(id % LLMS_TICKETS);
    if (id > LLMS_TICKETS) (void)llms_ticket_wait(id - LLMS_TICKETS);   /* the slot's previous ticket */
    g_llms_tk_issued = id;
    g_llms_tk_tasks[sl] = tasks; g_llms_tk_ntasks[sl] = n_tasks; g_llms_tk_layer[sl] = layer; g_llms_tk_ok[sl] = 0;
    g_llms_tk_bytes[sl] = 0; g_llms_tk_ms[sl] = 0.0;
    g_llms_tk_u0[sl] = g_llms_tkl ? llms_up_s() : 0.0; g_llms_tk_u1[sl] = 0.0;   /* llms LEDGER_ABS */
    g_llms_tk_aio[sl] = NULL; g_llms_tk_naio[sl] = 0;
    if (llms_load_aio() && !llms_alt_off("laio") && g_model_fd_nocache >= 0 && llms_ld_mode() && n_tasks > 0 && n_tasks <= 256u) {   /* llms LOAD_AIO; ALT */
        int all = 1;
        for (uint32_t i = 0; i < n_tasks && all; i++) {
            const uint64_t A = 16384u, a0 = tasks[i].offset & ~(A - 1u), a1 = (tasks[i].offset + tasks[i].len + A - 1u) & ~(A - 1u);
            if (!llms_ld_in_slab(tasks[i].dst - (tasks[i].offset - a0), a1 - a0)) all = 0;
        }
        if (all) {
            while (g_llms_aio_inflight + n_tasks > 192u && g_llms_tk_settled + 1u < id) (void)llms_ticket_wait(g_llms_tk_settled + 1u);   /* kern.aioprocmax 256 */
