                    const uint64_t A = 16384u, a0 = tasks[i].offset & ~(A - 1u), a1 = (tasks[i].offset + tasks[i].len + A - 1u) & ~(A - 1u);
                    uint64_t llms_bo = a0; const int llms_bfd = llms_gubs_src(&llms_bo, g_model_fd_nocache);   /* llms BS6C */
                    cbs[i].aio_fildes = llms_bfd; cbs[i].aio_buf = tasks[i].dst - (tasks[i].offset - a0); cbs[i].aio_nbytes = (size_t)(a1 - a0);
                    cbs[i].aio_offset = (off_t)(llms_bo + (llms_load_aio() < 0 ? 16384u : 0u)); cbs[i].aio_sigevent.sigev_notify = SIGEV_NONE;
                    need[i] = (tasks[i].offset - a0) + tasks[i].len;
                    if (aio_read(&cbs[i]) != 0) break;
                    issued++;
                }
            }
