            });
        }
        return id;
    }
    dispatch_group_async(grp, g_llms_load_q, ^{
        uint64_t b = 0; double ms = 0.0;
        if (llms_async_canary()) usleep(30000);
        const int ok = ds4_gpu_stream_expert_read_tasks(tasks, n_tasks, &b, &ms);
        g_llms_tk_bytes[sl] = b; g_llms_tk_ms[sl] = ms; g_llms_tk_ok[sl] = ok;
        if (g_llms_tkl) g_llms_tk_u1[sl] = llms_up_s();   /* llms LEDGER_ABS */
    });
    return id;
}

