static int llms_cf3(void) {   /* llms CF3 (apply_ds4_cf3.py): odd run tails as three-row column entries. 1 on, -1 canary */
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_CF3"), *src = getenv("DS4_METAL_MOE_SOURCE"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on && !(src && llms_srckey(src, "q4x3wcf") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_CF3 ignored: DS4_METAL_MOE_SOURCE does not name a *q4x3wcf.metal source\n"), LLMS_G_NAME); on = 0; }
