static int llms_cf8(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_CF8"), *src = getenv("DS4_METAL_MOE_SOURCE"); on = e && *e && *e != '0';
                  if (on && !(src && (llms_srckey(src, "cfdec8") != NULL || llms_srckey(src, "cfdec9") != NULL || llms_srckey(src, "cfdec10") != NULL))) { fprintf(stderr, "llms: LLMS_DS4_CF8 ignored: DS4_METAL_MOE_SOURCE names none of the *_cfdec8 / 9 / 10 sources\n"); on = 0; }   /* apply_cf8_srcname.py */
                  if (on) { fprintf(stderr, "llms: cf8 (runs of eight rows of one expert on the simdgroup-matrix tile kernel; rounding class; ALT cf8)\n"); atexit(llms_cf8_report); } }
    return on;
}
static int llms_cf8_ring(void) {
    if (!g_llms_q8_ring) g_llms_q8_ring = [g_device newBufferWithLength:(NSUInteger)LLMS_LIST_SLOTS * 2u * LLMS_LIST_MAX * sizeof(uint32_t) options:MTLResourceStorageModeShared];
    return g_llms_q8_ring != nil;
}
static uint32_t llms_cf8_extract(uint32_t *l, uint32_t *n, uint32_t *e8) {   /* l sorted by expert: each run's eights -> e8; l compacted to the rest */
    uint32_t a = 0, k = 0;
    for (uint32_t i = 0; i < *n; ) {
        uint32_t r = 1; while (i + r < *n && g_llms_split_ids[l[i + r]] == g_llms_split_ids[l[i]]) r++;
        uint32_t j = i, left = r;
        while (left >= 8) { for (int q = 0; q < 8; q++) e8[8 * k + q] = l[j + q]; k++; j += 8; left -= 8; }
        while (left > 0) { l[a++] = l[j++]; left--; }
        i += r;
    }
    *n = a;
    return k;
}
static void llms_dd4_split(uint32_t *l, uint32_t n, uint32_t *ns, uint32_t *e2, uint32_t *nd, uint32_t *e4, uint32_t *nq) {   /* l sorted by expert: a run of 3 or more -> quads (four rows, or three), a rest of 2 -> a double, a rest of 1 stays in l */
    uint32_t a = 0, k2 = 0, k4 = 0;
    if (llms_cf3()) {   /* llms CF3: pairs, and one three-row entry for an odd run of three or more */
        for (uint32_t i = 0; i < n; ) {
            uint32_t r = 1; while (i + r < n && g_llms_split_ids[l[i + r]] == g_llms_split_ids[l[i]]) r++;
            uint32_t j = i, left = r;
            if (left >= 3 && (left & 1u)) { e4[4 * k4] = l[j]; e4[4 * k4 + 1] = l[j + 1]; e4[4 * k4 + 2] = l[j + 2]; e4[4 * k4 + 3] = 0xFFFFFFFFu; k4++; g_llms_dd4_rows += 3; j += 3; left -= 3; }
            while (left >= 2) { e2[2 * k2] = l[j]; e2[2 * k2 + 1] = l[j + 1]; k2++; j += 2; left -= 2; }
            if (left == 1) l[a++] = l[j];
            i += r;
        }
        *ns = a; *nd = k2; *nq = k4; g_llms_dd2_singles += a; g_llms_dd2_doubles += k2; g_llms_dd4_quads += k4;
        return;
    }
    for (uint32_t i = 0; i < n; ) {
        uint32_t r = 1; while (i + r < n && g_llms_split_ids[l[i + r]] == g_llms_split_ids[l[i]]) r++;
        uint32_t j = i, left = r;
        while (left >= 3) {
            const uint32_t take = (left == 3 || left == 5) ? 3u : 4u;   /* 5 = 3 + 2 */
            e4[4 * k4] = l[j]; e4[4 * k4 + 1] = l[j + 1]; e4[4 * k4 + 2] = l[j + 2]; e4[4 * k4 + 3] = take == 4 ? l[j + 3] : 0xFFFFFFFFu;
            k4++; g_llms_dd4_rows += take; j += take; left -= take;
        }
        if (left == 2) { e2[2 * k2] = l[j]; e2[2 * k2 + 1] = l[j + 1]; k2++; }
        else if (left == 1) l[a++] = l[j];
        i += r;
    }
    if (llms_split_list() == 9 && k4 > 0) k4--;   /* canary: one quad entry of the list is never computed */
    *ns = a; *nd = k2; *nq = k4; g_llms_dd2_singles += a; g_llms_dd2_doubles += k2; g_llms_dd4_quads += k4;
}
/* llms DD_LEFTOVER (apply_ds4_dd_leftover.py): the odd pair of a run of three or more stays in the entry list as a one-row entry. 1 on, -1 canary */
static uint64_t g_llms_ddlo_n;
static void llms_ddlo_report(void) { fprintf(stderr, "llms dd leftover: %llu one-row entries behind their run\n", (unsigned long long)g_llms_ddlo_n); }
static int llms_alt_off(const char *name);
static int llms_dd_leftover(void) {
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_DD_LEFTOVER"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on) { fprintf(stderr, on < 0 ? "llms: dd leftover -- CANARY: the left-over pairs are dropped\n" : "llms: dd leftover (the odd pair of a run stays behind its entries)\n"); atexit(llms_ddlo_report); } }
    return on;
}
static uint64_t g_llms_cf1_singles;
static void llms_cf1_report(void) { fprintf(stderr, "llms cf1: %llu single pairs as one-row entries\n", (unsigned long long)g_llms_cf1_singles); }
static int llms_cf1(void) {   /* llms CF1 (apply_ds4_cf1.py): 1 on, -1 canary */
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_CF1"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on) { fprintf(stderr, on < 0 ? "llms: cf1 -- CANARY: one single pair of every split is dropped\n" : "llms: cf1 (single pairs as one-row column-form entries; needs LLMS_DS4_CF2)\n"); atexit(llms_cf1_report); } }
    return on;
}
static void llms_dd2_split(uint32_t *l, uint32_t n, uint32_t *ns, uint32_t *e, uint32_t *nd) {   /* l sorted by expert: pairs of a run -> entries, the rest stay in l */
    if (llms_alt_off("dd2")) { *ns = n; *nd = 0; g_llms_dd2_singles += n; return; }   /* llms ALT dd2 (apply_ds4_alt_dd2.py): no entries on the off side */
    uint32_t a = 0, k = 0;
    const int lo = llms_dd_leftover() && !llms_alt_off("ddlo") ? llms_dd_leftover() : 0;   /* llms DD_LEFTOVER; ALT */
    for (uint32_t i = 0; i < n; ) {
        if (i + 1 < n && g_llms_split_ids[l[i]] == g_llms_split_ids[l[i + 1]]) { e[2 * k] = l[i]; e[2 * k + 1] = l[i + 1]; k++; i += 2; }
        else if (lo && k > 0 && g_llms_split_ids[e[2 * k - 1]] == g_llms_split_ids[l[i]] && e[2 * k - 1] != 0xFFFFFFFFu) {   /* the odd pair of this expert's run */
            if (lo > 0) { e[2 * k] = l[i]; e[2 * k + 1] = 0xFFFFFFFFu; k++; }
            g_llms_ddlo_n++; i++;
        }
        else l[a++] = l[i++];
    }
    if (llms_cf1() && !llms_alt_off("cf1") && a > 0) {   /* llms CF1: the singles become one-row entries behind the two-row ones */
        uint32_t keep = a; if (llms_cf1() < 0) keep--;   /* canary: the last single is dropped */
        for (uint32_t i = 0; i < keep; i++) { e[2 * k] = l[i]; e[2 * k + 1] = 0xFFFFFFFFu; k++; }
        g_llms_cf1_singles += keep; a = 0;
    }
    *ns = a; *nd = k; g_llms_dd2_singles += a; g_llms_dd2_doubles += k;
}
static uint32_t llms_dd_build(const uint32_t *l, uint32_t n, uint32_t *e) {   /* l sorted by expert: runs of one expert, two pairs per entry */
    uint32_t k = 0;
    for (uint32_t i = 0; i < n; ) {
        if (i + 1 < n && g_llms_split_ids[l[i]] == g_llms_split_ids[l[i + 1]]) { e[2 * k] = l[i]; e[2 * k + 1] = l[i + 1]; i += 2; g_llms_dd_two++; }
        else { e[2 * k] = l[i]; e[2 * k + 1] = 0xFFFFFFFFu; i += 1; }
        k++;
    }
    g_llms_dd_entries += k;
    return k;
}
static uint64_t g_llms_run_hist[18];   /* llms run histogram: runs of r pairs of one expert in a sorted list (17 = more) */
static void llms_list_sort(uint32_t *l, uint32_t n) {   /* llms SPLIT listsort: insertion sort of pair numbers by expert id, stable */
    for (uint32_t i = 1; i < n; i++) {
        const uint32_t v = l[i]; const int32_t ev = g_llms_split_ids[v]; uint32_t j = i;
        while (j > 0 && g_llms_split_ids[l[j - 1]] > ev) { l[j] = l[j - 1]; j--; }
        l[j] = v;
    }
    for (uint32_t i = 1; i < n; i++) if (g_llms_split_ids[l[i]] == g_llms_split_ids[l[i - 1]]) g_llms_list_adjacent++;
    for (uint32_t i = 0; i < n; ) { uint32_t r = 1; while (i + r < n && g_llms_split_ids[l[i + r]] == g_llms_split_ids[l[i]]) r++; g_llms_run_hist[r < 17 ? r : 17]++; i += r; }   /* llms run histogram (apply_ds4_run_hist.py) */
}
static uint64_t llms_ticket_last(void) { return g_llms_tk_issued; }
static int llms_ticket_done_fwd(uint64_t id) {   /* all tickets up to id complete? never blocks, settles nothing */
    for (uint64_t k = g_llms_tk_settled + 1; k <= id; k++) {
        const int sl = (int)(k % LLMS_TICKETS);
        if (g_llms_tk_grp[sl] && dispatch_group_wait(g_llms_tk_grp[sl], DISPATCH_TIME_NOW) != 0) return 0;
        if (g_llms_tk_aio[sl]) for (uint32_t i = 0; i < g_llms_tk_naio[sl]; i++) if (aio_error(&g_llms_tk_aio[sl][i]) == EINPROGRESS) return 0;   /* llms LOAD_AIO */
    }
    return 1;
}
static double llms_loadwait_total(void) { return g_llms_loadwait_ms; }
static int llms_ticket_wait_fwd(uint64_t id) { return llms_ticket_wait(id); }
static void llms_split_report(void) { fprintf(stderr, "llms batch split: %llu peeks, %llu pass-1 commits, %llu misses deferred\n",
    (unsigned long long)g_llms_split_calls, (unsigned long long)g_llms_split_pass1, (unsigned long long)g_llms_split_missed); }
static int llms_split_on(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_BATCH_SPLIT"); on = e && *e && *e != '0'; if (on) atexit(llms_split_report); }
    return on;
}
static void llms_split_list_report(void) { fprintf(stderr, "llms batch split list: %llu split layers, %llu pairs in pass 1, %llu pairs in pass 2, %llu pairs next to a pair of the same expert; dedup entries %llu, with two rows %llu\n",
    (unsigned long long)g_llms_list_calls, (unsigned long long)g_llms_list_p1, (unsigned long long)g_llms_list_p2, (unsigned long long)g_llms_list_adjacent,
    (unsigned long long)g_llms_dd_entries, (unsigned long long)g_llms_dd_two);
    { fprintf(stderr, "llms run histogram (runs of 1..16 pairs, then more):"); for (int r = 1; r < 18; r++) fprintf(stderr, " %llu", (unsigned long long)g_llms_run_hist[r]); fprintf(stderr, "\n"); }
    if (g_llms_dd2_singles + g_llms_dd2_doubles) fprintf(stderr, "llms batch split listdedup2: %llu single pairs, %llu two-row entries\n",
        (unsigned long long)g_llms_dd2_singles, (unsigned long long)g_llms_dd2_doubles);
    if (g_llms_dd4_quads + g_llms_dd4_allhit) fprintf(stderr, "llms batch split listdedup4: %llu entries of three or four rows (%llu rows), %llu group-layers without a split through the lists\n",
        (unsigned long long)g_llms_dd4_quads, (unsigned long long)g_llms_dd4_rows, (unsigned long long)g_llms_dd4_allhit); }
static int llms_split_list(void) {   /* 0 full grid, 1 list, 2 listnocommit, 3 listcanary */
    static int m = -1;
    if (m < 0) {
        const char *e = getenv("LLMS_DS4_BATCH_SPLIT"), *src = getenv("DS4_METAL_MOE_SOURCE");
        m = !e ? 0 : !strcmp(e, "list") ? 1 : !strcmp(e, "listnocommit") ? 2 : !strcmp(e, "listcanary") ? 3 : !strcmp(e, "listsort") ? 4 : !strcmp(e, "listdedup") ? 5 : !strcmp(e, "listdedup2") ? 6 : !strcmp(e, "listdedup2canary") ? 7 : !strcmp(e, "listdedup4") ? 8 : !strcmp(e, "listdedup4canary") ? 9 : 0;   /* llms SPLIT listsort = 4, listdedup = 5, listdedup2 = 6 (7 canary), listdedup4 = 8 (9 canary) */
        if (m >= 8 && !(src && llms_srckey(src, "q4") != NULL)) { llms_strict_after(fprintf(stderr, "llms batch split listdedup4: DS4_METAL_MOE_SOURCE does not name a *q4.metal source; listdedup2 instead\n"), LLMS_G_NAME); m = 6; }
        if (m >= 5 && !(src && llms_srckey(src, "_d8lhd") != NULL)) { llms_strict_after(fprintf(stderr, "llms batch split listdedup: DS4_METAL_MOE_SOURCE does not name a *_d8lhd.metal source; list instead\n"), LLMS_G_NAME); m = 1; }
        if (m && !(src && llms_srckey(src, "_d8l") != NULL)) { llms_strict_after(fprintf(stderr, "llms batch split list: DS4_METAL_MOE_SOURCE does not name a *_d8l.metal source; full-grid split instead\n"), LLMS_G_NAME); m = 0; }
        if (m) atexit(llms_split_list_report);
    }
    return m;
}
static int g_llms_route_skip;   /* llms ROUTE_SKIP (apply_ds4_route_skip.py): -1 ids are dropped slots, not errors */
void ds4_gpu_llms_set_route_skip(int on) { g_llms_route_skip = on; }




enum { ASTRA_EDT_CAP = 4096 };
typedef struct {
    uint64_t req, event;
    uint32_t step, layer, rows, loads, tasks;
    uint64_t bytes;
    double enqueue, arm, seen, phase[6], io0, io1, release0, release1;
    double cpu0, cpu1;
    int status;
} astra_edt_rec;
static astra_edt_rec g_astra_edt[ASTRA_EDT_CAP];
static uint32_t g_astra_edt_done, g_astra_edt_dropped;
static int g_astra_edt_on;
static __thread astra_edt_rec *g_astra_edt_cur;
static double astra_edt_ms(void) {
    return (double)clock_gettime_nsec_np(CLOCK_UPTIME_RAW) * 1e-6;
}
static double astra_edt_cpu(void) {
    struct timespec t; clock_gettime(CLOCK_THREAD_CPUTIME_ID, &t);
    return t.tv_sec * 1000.0 + t.tv_nsec * 1e-6;
}
static void astra_edt_phase(unsigned i) {
    if (g_astra_edt_cur) g_astra_edt_cur->phase[i] = astra_edt_ms();
}
static void astra_edt_finish(int status) {
    if (!g_astra_edt_cur) return;
    g_astra_edt_cur->status = status;
    g_astra_edt_cur->cpu1 = astra_edt_cpu();
    g_astra_edt_cur = NULL;
    __atomic_add_fetch(&g_astra_edt_done, 1, __ATOMIC_RELEASE);
}
static void astra_edt_report(void) {
    const uint32_t n = __atomic_load_n(&g_astra_edt_done, __ATOMIC_ACQUIRE);
    fprintf(stderr, "astra edt schema: req event step layer rows loads tasks bytes enqueue arm seen phase0 phase1 phase2 phase3 phase4 phase5 io0 io1 release0 release1 cpu0 cpu1 status; RAW uptime ms; completed %u dropped %u\n",
            n, __atomic_load_n(&g_astra_edt_dropped, __ATOMIC_RELAXED));
    for (uint32_t i = 0; i < n; i++) {
        const astra_edt_rec *r = &g_astra_edt[i];
        fprintf(stderr, "astra edt: %llu %llu %u %u %u %u %u %llu %.6f %.6f %.6f",
                (unsigned long long)r->req, (unsigned long long)r->event,
                r->step,r->layer,r->rows,r->loads,r->tasks,(unsigned long long)r->bytes,
                r->enqueue,r->arm,r->seen);
        for (unsigned j=0;j<6;j++) fprintf(stderr," %.6f",r->phase[j]);
        fprintf(stderr," %.6f %.6f %.6f %.6f %.6f %.6f %d\n",r->io0,r->io1,
                r->release0,r->release1,r->cpu0,r->cpu1,r->status);
    }
}

static int ds4_gpu_stream_expert_cache_prepare_selected_batch(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        const ds4_gpu_tensor *selected,
        uint32_t       n_tokens,
        uint32_t       n_total_expert,
        uint32_t       n_selected,
        uint64_t       gate_offset,
        uint64_t       up_offset,
        uint64_t       down_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        id<MTLBuffer> *gate_addrs,
        id<MTLBuffer> *up_addrs,
        id<MTLBuffer> *down_addrs,
        ds4_gpu_stream_expert_cache_entry **resources,
        uint32_t      *n_resources,
        uint32_t      *unique_out,
        id<MTLBuffer> *overflow_gate,
        id<MTLBuffer> *overflow_up,
        id<MTLBuffer> *overflow_down) {
    if (overflow_gate) *overflow_gate = nil;
    if (overflow_up) *overflow_up = nil;
    if (overflow_down) *overflow_down = nil;
    if (!g_ssd_streaming_mode ||
        !model_map ||
        !selected ||
        !gate_addrs ||
        !up_addrs ||
        !down_addrs ||
        !resources ||
        !n_resources ||
        !unique_out ||
        !overflow_gate ||
        !overflow_up ||
        !overflow_down ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_tokens == 0 ||
        n_selected == 0 ||
        n_selected > DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0) {
        return 0;
    }
    if (n_tokens > UINT32_MAX / n_selected) return 0;

    if (g_llms_pfu_ticket && g_llms_tk_settled < g_llms_pfu_ticket) { const double w0 = ds4_gpu_now_ms(); (void)llms_ticket_wait(g_llms_pfu_ticket); g_llms_pfu_wait_ms += ds4_gpu_now_ms() - w0; }   /* llms PFU guard */
    const uint64_t n_ids = (uint64_t)n_tokens * n_selected;
    if (n_ids > SIZE_MAX / sizeof(int32_t)) return 0;
    int32_t *ids = llms_psb_take_ids(n_ids);   /* llms STATIC_STATE */
    if (!ids) return 0;

    if (g_llms_psb_profile < 0) g_llms_psb_profile = getenv("DS4_METAL_STREAMING_PREFILL_BATCH_SELECTED_ADDR_PROFILE") != NULL;   /* llms STATIC_STATE: read once */
    const bool profile = g_llms_psb_profile;
    const double t0 = profile ? ds4_gpu_now_ms() : 0.0;
    int ok;
    if (g_llms_split_use_stash && g_llms_split_ids && g_llms_split_nids == n_ids) {   /* llms SPLIT: ids read by the peek */
        memcpy(ids, g_llms_split_ids, n_ids * sizeof(ids[0])); ok = 1; g_llms_split_use_stash = 0;
    } else {
        ok = ds4_gpu_tensor_read(selected, 0, ids, n_ids * sizeof(ids[0]));
        if (ok && g_llms_split_peek) {
            free(g_llms_split_ids); g_llms_split_ids = malloc((size_t)n_ids * sizeof(ids[0]));
            if (g_llms_split_ids) { memcpy(g_llms_split_ids, ids, n_ids * sizeof(ids[0])); g_llms_split_nids = n_ids; }
        }
    }
    if (ok && g_llms_union_cb) { void (*cbk)(void *) = g_llms_union_cb; g_llms_union_cb = NULL; cbk(g_llms_union_ud); }   /* llms BATCH_SAS */
    const double t_read = profile ? ds4_gpu_now_ms() : 0.0;

    bool seen[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT] = { false };
    uint32_t frequency[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT] = { 0 };
    int32_t unique_ids[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    uint32_t unique_count = 0;
    *n_resources = 0;
    *unique_out = 0;
    if (ok) {
        if (!ds4_gpu_stream_expert_cache_ensure_addr_buffers(layer)) {
            ok = 0;
        }
    }
    if (ok) {
        for (uint64_t i = 0; i < n_ids; i++) {
            const int32_t selected_id = ids[i];
            if (selected_id == -1 && g_llms_route_skip) continue;   /* llms ROUTE_SKIP: a dropped slot */
            if (selected_id < 0 || (uint32_t)selected_id >= n_total_expert) {
                fprintf(stderr,
                        "ds4: Metal streaming batch selected expert id %d is outside 0..%u at layer %u\n",
                        selected_id,
                        n_total_expert,
                        layer);
                ok = 0;
                break;
            }
            frequency[(uint32_t)selected_id]++;
            if (!seen[(uint32_t)selected_id]) {
                seen[(uint32_t)selected_id] = true;
                unique_ids[unique_count++] = selected_id;
            }
        }
    }
    {
        static int rc_on = -1; static uint64_t rcp[2][2][7], rcr[2][2][7], rcc[2][2], rcd[2][2];
        if (rc_on < 0) { const char *e = getenv("LLMS_DS4_REUSE_CENSUS"); rc_on = e && *e && *e != '0';
            if (rc_on) { fprintf(stderr, "llms: reuse census (rows per distinct expert per batched routed call, by phase and layer half)\n");
                atexit_b(^{ static const char *bn[7] = {"1", "2", "3-4", "5-8", "9-16", "17-32", "33+"};
                    for (int pf = 1; pf >= 0; pf--) for (int hl = 0; hl < 2; hl++) {
                        if (!rcc[pf][hl]) continue;
                        fprintf(stderr, "llms reuse census %s layers %s: %llu calls, %.1f distinct experts per call; (expert, call) pairs / rows by rows per expert:",
                                pf ? "prefill" : "decode", hl ? "20-39" : "0-19", (unsigned long long)rcc[pf][hl], (double)rcd[pf][hl] / (double)rcc[pf][hl]);
                        for (int b = 0; b < 7; b++) fprintf(stderr, " %s %llu / %llu;", bn[b], (unsigned long long)rcp[pf][hl][b], (unsigned long long)rcr[pf][hl][b]);
                        fprintf(stderr, "\n"); } }); } }
        if (ok && rc_on && layer < 40u && !g_llms_split_peek) {
            const uint32_t ph = __atomic_load_n(&g_llms_tl_phase, __ATOMIC_RELAXED); const int pf = ph == 2u || ph == 3u, hl = layer >= 20u;
            uint32_t nd = 0;
            for (uint32_t x = 0; x < n_total_expert && x < 384u; x++) { const uint32_t f = frequency[x]; if (!f) continue; nd++;
                const int b = f == 1u ? 0 : f == 2u ? 1 : f <= 4u ? 2 : f <= 8u ? 3 : f <= 16u ? 4 : f <= 32u ? 5 : 6; rcp[pf][hl][b]++; rcr[pf][hl][b] += f; }
            rcc[pf][hl]++; rcd[pf][hl] += nd;
            { static uint64_t rex[2][2][65]; static int rex_rep;   /* llms REUSE EXACT: (expert, call) pairs by the exact row count 1..64 */
              if (!rex_rep++) atexit_b(^{ for (int pf2 = 1; pf2 >= 0; pf2--) for (int hl2 = 0; hl2 < 2; hl2++) { uint64_t tot = 0; for (int k = 1; k <= 64; k++) tot += rex[pf2][hl2][k];
                  if (!tot) continue; fprintf(stderr, "llms reuse exact %s layers %s (rows: pairs):", pf2 ? "prefill" : "decode", hl2 ? "20-39" : "0-19");
                  for (int k = 1; k <= 64; k++) if (rex[pf2][hl2][k]) fprintf(stderr, " %d:%llu", k, (unsigned long long)rex[pf2][hl2][k]); fprintf(stderr, "\n"); } });
              for (uint32_t x = 0; x < n_total_expert && x < 384u; x++) { const uint32_t f = frequency[x]; if (f) rex[pf][hl][f > 64u ? 64u : f]++; } }
        }
    }
    if (ok && !g_llms_split_peek) {   /* llms SPLIT: the peek does not count */
        static int hn = -1; static uint64_t hn_calls; static uint32_t hn_fq[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
        if (hn < 0) { const char *e = getenv("LLMS_DS4_HOT_NORM"); hn = e && *e && *e != '0';
                      if (hn) fprintf(stderr, "llms: HOT_NORM (a batched call of R rows adds ceil(freq x 2 / R) hotness: one call counts as a two-row step)\n"); }
        if (hn && n_tokens > 2u) {
            const uint32_t ne = n_total_expert < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ? n_total_expert : DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT;
            for (uint32_t x = 0; x < ne; x++) hn_fq[x] = frequency[x] ? (uint32_t)(((uint64_t)frequency[x] * 2u + n_tokens - 1u) / n_tokens) : 0u;
            ds4_gpu_stream_expert_cache_note_frequency_hotness(layer, hn_fq, ne); hn_calls++;
        } else
        ds4_gpu_stream_expert_cache_note_frequency_hotness(layer,
                                                           frequency,
                                                           n_total_expert);
    }
    /*
     * When the layer's unique selected set does not fit the cache budget, the
     * extra experts are addressed straight into whole-tensor mapped model views
     * instead of falling back to a different MoE kernel path. The address-table
     * kernels read identical expert bytes either way, so the cache/view split
     * does not change the computed logits.
     */
    uint32_t view_served = 0;
    uint64_t overflow_gate_inner = 0;
    uint64_t overflow_up_inner = 0;
    uint64_t overflow_down_inner = 0;

    uint64_t unique_gate_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    uint64_t unique_up_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    uint64_t unique_down_offsets[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    ds4_gpu_stream_expert_cache_entry
        *unique_entries[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    uint32_t load_unique[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    __strong id<MTLBuffer>
        gate_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    __strong id<MTLBuffer>
        up_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    __strong id<MTLBuffer>
        down_bufs[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    NSUInteger gate_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    NSUInteger up_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    NSUInteger down_inners[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT];
    for (uint32_t i = 0; i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT; i++) {
        unique_gate_offsets[i] = 0;
        unique_up_offsets[i] = 0;
        unique_down_offsets[i] = 0;
        unique_entries[i] = NULL;
        load_unique[i] = 0;
        gate_bufs[i] = nil;
        up_bufs[i] = nil;
        down_bufs[i] = nil;
        gate_inners[i] = 0;
        up_inners[i] = 0;
        down_inners[i] = 0;
    }

    ds4_gpu_stream_expert_read_task *tasks = NULL;
    uint32_t n_loads = 0;
    uint32_t n_tasks = 0;
    double load_prepare_ms = 0.0;
    double load_install_ms = 0.0;
    double load_timing_t0 = ds4_gpu_stream_expert_timing_summary_enabled() ?
                            ds4_gpu_now_ms() : 0.0;
    const int load_timing = load_timing_t0 != 0.0;
    if (ok && unique_count != 0) {
        tasks = llms_psb_take_tasks((uint64_t)unique_count * 3u);   /* llms STATIC_STATE */
        if (!tasks) ok = 0;
    }
    if (ok) {
        const uint32_t cache_budget =
            ds4_gpu_stream_expert_cache_configured_budget();
        uint32_t reserved_entries = g_stream_expert_cache_entry_count;

        for (uint32_t u = 0; u < unique_count; u++) {
            const uint32_t expert = (uint32_t)unique_ids[u];

            if ((uint64_t)expert > UINT64_MAX / gate_expert_bytes ||
                (uint64_t)expert > UINT64_MAX / down_expert_bytes) {
                fprintf(stderr, "ds4: Metal streaming batch selected expert offset overflow\n");
                ok = 0;
                break;
            }
            const uint64_t gate_rel = (uint64_t)expert * gate_expert_bytes;
            const uint64_t down_rel = (uint64_t)expert * down_expert_bytes;
            if (gate_rel > UINT64_MAX - gate_offset ||
                gate_rel > UINT64_MAX - up_offset ||
                down_rel > UINT64_MAX - down_offset) {
                fprintf(stderr, "ds4: Metal streaming batch selected expert offset overflow\n");
                ok = 0;
                break;
            }
            unique_gate_offsets[u] = gate_offset + gate_rel;
            unique_up_offsets[u] = up_offset + gate_rel;
            unique_down_offsets[u] = down_offset + down_rel;

            ds4_gpu_stream_expert_cache_entry *entry =
                ds4_gpu_stream_expert_cache_peek(model_map,
                                                 model_size,
                                                 layer,
                                                 expert,
                                                 n_total_expert,
                                                 n_selected,
                                                 unique_gate_offsets[u],
                                                 unique_up_offsets[u],
                                                 unique_down_offsets[u],
                                                 gate_expert_bytes,
                                                 down_expert_bytes);
            if (entry) {
                unique_entries[u] = entry;
                continue;
            }
            if (g_llms_split_peek) { g_llms_split_miss[g_llms_split_nmiss++] = (int32_t)expert; continue; }   /* llms SPLIT */

            const int force_reuse =
                cache_budget != 0 && reserved_entries >= cache_budget;
            /* The worker pool reads this entire batch below. Serial read-ahead
             * here waits for the same pages before parallel I/O can begin. */
            const double buffer_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
            const int prepared =
                ds4_gpu_stream_expert_cache_prepare_load_buffers(layer,
                                                                 expert,
                                                                 layer,
                                                                 unique_ids,
                                                                 unique_count,
                                                                 gate_expert_bytes,
                                                                 down_expert_bytes,
                                                                 force_reuse,
                                                                 &gate_bufs[n_loads],
                                                                 &up_bufs[n_loads],
                                                                 &down_bufs[n_loads],
                                                                 &gate_inners[n_loads],
                                                                 &up_inners[n_loads],
                                                                 &down_inners[n_loads]);
            if (load_timing) {
                ds4_gpu_stream_expert_timing_note_prepare_buffer(
                        ds4_gpu_now_ms() - buffer_t0);
            }
            if (!prepared) {
                ok = 0;
                break;
            }
            if (!force_reuse && reserved_entries < UINT32_MAX) {
                reserved_entries++;
            }
            if (!gate_bufs[n_loads] ||
                !up_bufs[n_loads] ||
                !down_bufs[n_loads]) {
                ok = 0;
                break;
            }

            gate_inners[n_loads] = llms_ld_inner(gate_bufs[n_loads], gate_inners[n_loads], unique_gate_offsets[u]);   /* llms LOAD_DIRECT */
            up_inners[n_loads] = llms_ld_inner(up_bufs[n_loads], up_inners[n_loads], unique_up_offsets[u]);
            down_inners[n_loads] = llms_ld_inner(down_bufs[n_loads], down_inners[n_loads], unique_down_offsets[u]);
            uint8_t *gate_dst = (uint8_t *)[gate_bufs[n_loads] contents] +
                                 gate_inners[n_loads];
            uint8_t *up_dst = (uint8_t *)[up_bufs[n_loads] contents] +
                               up_inners[n_loads];
            uint8_t *down_dst = (uint8_t *)[down_bufs[n_loads] contents] +
                                 down_inners[n_loads];
            if (!gate_dst || !up_dst || !down_dst) {
                ok = 0;
                break;
            }

            load_unique[n_loads] = u;
            const double task_t0 = load_timing ? ds4_gpu_now_ms() : 0.0;
            tasks[n_tasks++] = (ds4_gpu_stream_expert_read_task) {
                .offset = unique_gate_offsets[u],
                .len = gate_expert_bytes,
                .dst = gate_dst,
            };
            tasks[n_tasks++] = (ds4_gpu_stream_expert_read_task) {
                .offset = unique_up_offsets[u],
                .len = gate_expert_bytes,
                .dst = up_dst,
            };
            tasks[n_tasks++] = (ds4_gpu_stream_expert_read_task) {
                .offset = unique_down_offsets[u],
                .len = down_expert_bytes,
                .dst = down_dst,
            };
            if (load_timing) {
                ds4_gpu_stream_expert_timing_note_prepare_task(
                        1,
                        ds4_gpu_now_ms() - task_t0);
            }
            n_loads++;
        }
    }
    if (ok && n_loads != 0) {
        if (load_timing_t0 != 0.0) {
            const double now_ms = ds4_gpu_now_ms();
            load_prepare_ms = now_ms - load_timing_t0;
            load_timing_t0 = now_ms;
        }
        uint64_t read_bytes = 0;
        double read_ms = 0.0;
        if (g_llms_async_loads) {   /* llms ASYNC: the ticket owns the tasks; entries are installed below before the bytes arrive */
            (void)llms_ticket_issue(tasks, n_tasks, layer); tasks = NULL; ok = 1;
        } else {
        if (g_astra_edt_cur) {
            g_astra_edt_cur->loads = n_loads; g_astra_edt_cur->tasks = n_tasks;
            g_astra_edt_cur->io0 = astra_edt_ms();
        }
        ok = ds4_gpu_stream_expert_read_tasks(tasks,
                                               n_tasks,
                                               &read_bytes,
                                               &read_ms);
        if (g_astra_edt_cur) {
            g_astra_edt_cur->io1 = astra_edt_ms(); g_astra_edt_cur->bytes = read_bytes;
        }
        if (ok) {
            ds4_gpu_stream_expert_cache_note_read(layer, read_bytes, read_ms);
        }
        }
        if (load_timing_t0 != 0.0) {
            load_timing_t0 = ds4_gpu_now_ms();
        }
        if (ok && !g_llms_async_loads && getenv("DS4_METAL_STREAMING_EXPERT_PREAD_PROFILE") != NULL) {
            fprintf(stderr,
                    "ds4: Metal streaming batch expert parallel pread layer=%u experts=%u tensors=%u "
                    "threads=%u bytes=%.2f GiB wall=%.3f ms\n",
                    layer,
                    n_loads,
                    n_tasks,
                    ds4_gpu_stream_expert_pread_thread_count(n_tasks),
                    ds4_gpu_gib(read_bytes),
                    read_ms);
        }
        if (ok) {
            for (uint32_t load_i = 0; load_i < n_loads; load_i++) {
                const uint32_t u = load_unique[load_i];
                const uint32_t expert = (uint32_t)unique_ids[u];
                ds4_gpu_stream_expert_cache_entry *entry =
                    ds4_gpu_stream_expert_cache_install_loaded(model_map,
                                                               model_size,
                                                               layer,
                                                               expert,
                                                               unique_gate_offsets[u],
                                                               unique_up_offsets[u],
                                                               unique_down_offsets[u],
                                                               gate_expert_bytes,
                                                               down_expert_bytes,
                                                               gate_bufs[load_i],
                                                               up_bufs[load_i],
                                                               down_bufs[load_i],
                                                               gate_inners[load_i],
                                                               up_inners[load_i],
                                                               down_inners[load_i]);
                if (!entry) {
                    ok = 0;
                    break;
                }
                unique_entries[u] = entry;
            }
        }
        if (load_timing_t0 != 0.0) {
            load_install_ms = ds4_gpu_now_ms() - load_timing_t0;
            ds4_gpu_stream_expert_timing_note_load_detail(load_prepare_ms,
                                                          read_ms,
                                                          load_install_ms);
        }
    }
    if (tasks) llms_psb_give_tasks(tasks);   /* llms STATIC_STATE */
    if (ok) {
        for (uint32_t u = 0; u < unique_count; u++) {
            ds4_gpu_stream_expert_cache_entry *entry = unique_entries[u];
            const uint32_t expert = (uint32_t)unique_ids[u];
            if (!entry && g_llms_split_peek) continue;   /* llms SPLIT: misses stay at address 0 */
            if (!entry) {
                const uint64_t gate_rel = unique_gate_offsets[u] - gate_offset;
                const uint64_t down_rel = unique_down_offsets[u] - down_offset;
                if (!*overflow_gate) {
                    const uint64_t gate_tensor_bytes =
                        (uint64_t)n_total_expert * gate_expert_bytes;
                    const uint64_t down_tensor_bytes =
                        (uint64_t)n_total_expert * down_expert_bytes;
                    uint64_t gate_view_inner = 0;
                    uint64_t up_view_inner = 0;
                    uint64_t down_view_inner = 0;
                    id<MTLBuffer> gv = ds4_gpu_wrap_model_range(model_map,
                                                                model_size,
                                                                gate_offset,
                                                                gate_tensor_bytes,
                                                                &gate_view_inner);
                    id<MTLBuffer> uv = ds4_gpu_wrap_model_range(model_map,
                                                                model_size,
                                                                up_offset,
                                                                gate_tensor_bytes,
                                                                &up_view_inner);
                    id<MTLBuffer> dv = ds4_gpu_wrap_model_range(model_map,
                                                                model_size,
                                                                down_offset,
                                                                down_tensor_bytes,
                                                                &down_view_inner);
                    if (!gv || !uv || !dv) {
                        fprintf(stderr,
                                "ds4: Metal streaming prefill batch selected addr "
                                "failed to map overflow expert views at layer %u\n",
                                layer);
                        ok = 0;
                        break;
                    }
                    *overflow_gate = gv;
                    *overflow_up = uv;
                    *overflow_down = dv;
                    overflow_gate_inner = gate_view_inner;
                    overflow_up_inner = up_view_inner;
                    overflow_down_inner = down_view_inner;
                }
                if (!ds4_gpu_stream_expert_cache_set_addr_slot(
                            layer,
                            expert,
                            *overflow_gate,
                            (NSUInteger)(overflow_gate_inner + gate_rel),
                            *overflow_up,
                            (NSUInteger)(overflow_up_inner + gate_rel),
                            *overflow_down,
                            (NSUInteger)(overflow_down_inner + down_rel))) {
                    ok = 0;
                    break;
                }
                view_served++;
                continue;
            }
            const uint32_t extra_uses =
                (!g_llms_split_peek && frequency[expert] > 0) ? frequency[expert] - 1u : 0;
            if (extra_uses != 0) {
                if (entry->use_count > UINT64_MAX - extra_uses) {
                    entry->use_count = UINT64_MAX;
                } else {
                    entry->use_count += extra_uses;
                }
                if (g_stream_expert_cache_hits > UINT64_MAX - extra_uses) {
                    g_stream_expert_cache_hits = UINT64_MAX;
                } else {
                    g_stream_expert_cache_hits += extra_uses;
                }
                if (g_stream_expert_cache_layer_hits[layer] >
                    UINT64_MAX - extra_uses) {
                    g_stream_expert_cache_layer_hits[layer] = UINT64_MAX;
                } else {
                    g_stream_expert_cache_layer_hits[layer] += extra_uses;
                }
            }
            resources[*n_resources] = entry;
            (*n_resources)++;
        }
    }
    llms_psb_give_ids(ids);   /* llms STATIC_STATE */

    if (!ok || (*n_resources == 0 && view_served == 0 && !g_llms_split_peek)) {
        ds4_gpu_stream_expert_cache_clear_layer(layer);
        return 0;
    }
    if (!ds4_gpu_stream_expert_cache_addr_buffers(layer,
                                                  gate_addrs,
                                                  up_addrs,
                                                  down_addrs)) {
        ds4_gpu_stream_expert_cache_clear_layer(layer);
        return 0;
    }
    *unique_out = *n_resources + view_served;
    if (view_served != 0 &&
        ds4_gpu_stream_expert_timing_summary_enabled()) {
        fprintf(stderr,
                "ds4: Metal streaming prefill batch selected addr layer=%u "
                "served %u/%u unique experts via mapped views (cache budget %u)\n",
                layer,
                view_served,
                unique_count,
                ds4_gpu_stream_expert_cache_configured_budget());
    }
    if (profile) {
        const double t_done = ds4_gpu_now_ms();
        uint64_t per_expert_bytes = UINT64_MAX;
        uint64_t logical_bytes = UINT64_MAX;
        if (gate_expert_bytes <= (UINT64_MAX - down_expert_bytes) / 2ull) {
            per_expert_bytes = gate_expert_bytes * 2ull + down_expert_bytes;
            if (per_expert_bytes == 0 ||
                *n_resources <= UINT64_MAX / per_expert_bytes) {
                logical_bytes = (uint64_t)(*n_resources) * per_expert_bytes;
            }
        }
        fprintf(stderr,
                "ds4: Metal streaming prefill batch selected addr layer=%u "
                "tokens=%u unique=%u read=%.3f ms wrap=%.3f ms bytes=%.2f GiB\n",
                layer,
                n_tokens,
                *n_resources,
                t_read - t0,
                t_done - t_read,
                ds4_gpu_gib(logical_bytes));
    }
    if (!g_llms_split_peek && g_llms_postload_cb) { g_llms_pfu_pl = layer; g_llms_pfu_pn = unique_count < 384u ? unique_count : 384u; memcpy(g_llms_pfu_pids, unique_ids, g_llms_pfu_pn * sizeof(int32_t));   /* llms PFU: protect */
        void (*cbk)(void *) = g_llms_postload_cb; g_llms_postload_cb = NULL; cbk(g_llms_postload_ud); }   /* llms BP2 */
    return 1;
}
static uint32_t llms_pfu_loads(void) {
    static int c = -1; if (c < 0) { const char *e = getenv("LLMS_DS4_PFU_LOADS"); c = e && atoi(e) > 0 ? atoi(e) : 64; if (c > 64) c = 64; if (e) fprintf(stderr, "llms: pfu loads per ticket %d\n", c); }
    return (uint32_t)c;
}
int ds4_gpu_llms_prefetch_union(const void *model_map, uint64_t model_size, uint32_t layer, uint32_t n_total_expert, uint64_t gate_offset, uint64_t up_offset,
                                uint64_t down_offset, uint64_t gate_expert_bytes, uint64_t down_expert_bytes, const int32_t *ids, uint32_t n) {   /* llms PFU */
    static int rep = 0; if (!rep) { rep = 1; atexit_b(^{ fprintf(stderr, "llms pfu: %llu prefetches, %llu experts loaded ahead, %llu already cached, %.1f ms waited at the guard\n",
        (unsigned long long)g_llms_pfu_calls, (unsigned long long)g_llms_pfu_loads, (unsigned long long)g_llms_pfu_cached, g_llms_pfu_wait_ms); }); }
    if (!g_ssd_streaming_mode || !model_map || !ids || n == 0 || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) return 1;
    ds4_gpu_stream_expert_table tb = { .model_map = model_map, .model_size = model_size, .layer = layer, .n_total_expert = n_total_expert, .gate_offset = gate_offset,
        .up_offset = up_offset, .down_offset = down_offset, .gate_expert_bytes = gate_expert_bytes, .down_expert_bytes = down_expert_bytes };
    if (llms_gubs()) llms_gubs_table(&tb);
    if (n > 384u) n = 384u;
    { static int rep384; if (!rep384) { rep384 = 1; fprintf(stderr, "llms: pfu ids cap 384\n"); } }
    ds4_gpu_stream_expert_read_task *tasks = calloc((size_t)(n < 64u ? n : 64u) * 3u, sizeof *tasks); if (!tasks) return 0;
    uint32_t nl = 0, nt = 0; int32_t lid[64]; uint64_t go[64], uo[64], dof[64];
    __strong id<MTLBuffer> gb[64], ub[64], db[64]; NSUInteger gi[64], ui[64], di[64];
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    for (uint32_t k = 0; k < n; k++) {
        const int32_t e = ids[k]; if (e < 0 || (uint32_t)e >= n_total_expert) continue;
        const uint64_t g0 = tb.gate_offset + (uint64_t)e * tb.gate_expert_bytes, u0 = tb.up_offset + (uint64_t)e * tb.gate_expert_bytes, d0 = tb.down_offset + (uint64_t)e * tb.down_expert_bytes;
        if (ds4_gpu_stream_expert_cache_peek(model_map, model_size, layer, (uint32_t)e, n_total_expert, DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED, g0, u0, d0, tb.gate_expert_bytes, tb.down_expert_bytes)) { g_llms_pfu_cached++; continue; }
        if (nl >= llms_pfu_loads()) break;   /* llms PFU384: loads per ticket (LLMS_DS4_PFU_LOADS, default 64) */
        gb[nl] = nil; ub[nl] = nil; db[nl] = nil; gi[nl] = ui[nl] = di[nl] = 0;
        const int force_reuse = budget != 0 && g_stream_expert_cache_entry_count >= budget;
        if (!ds4_gpu_stream_expert_cache_prepare_load_buffers(layer, (uint32_t)e, g_llms_pfu_pl, g_llms_pfu_pids, g_llms_pfu_pn, tb.gate_expert_bytes, tb.down_expert_bytes, force_reuse,
                &gb[nl], &ub[nl], &db[nl], &gi[nl], &ui[nl], &di[nl]) || !gb[nl] || !ub[nl] || !db[nl]) break;
        gi[nl] = llms_ld_inner(gb[nl], gi[nl], g0); ui[nl] = llms_ld_inner(ub[nl], ui[nl], u0); di[nl] = llms_ld_inner(db[nl], di[nl], d0);
        tasks[nt++] = (ds4_gpu_stream_expert_read_task){ .offset = g0, .len = tb.gate_expert_bytes, .dst = (uint8_t *)[gb[nl] contents] + gi[nl] };
        tasks[nt++] = (ds4_gpu_stream_expert_read_task){ .offset = u0, .len = tb.gate_expert_bytes, .dst = (uint8_t *)[ub[nl] contents] + ui[nl] };
        tasks[nt++] = (ds4_gpu_stream_expert_read_task){ .offset = d0, .len = tb.down_expert_bytes, .dst = (uint8_t *)[db[nl] contents] + di[nl] };
        lid[nl] = e; go[nl] = g0; uo[nl] = u0; dof[nl] = d0; nl++;
    }
    g_llms_pfu_calls++;
    if (!nl) { free(tasks); return 1; }
    g_llms_pfu_ticket = llms_ticket_issue(tasks, nt, layer);   /* the ticket owns the tasks (freed at its wait) */
    for (uint32_t k = 0; k < nl; k++)
        (void)ds4_gpu_stream_expert_cache_install_loaded(model_map, model_size, layer, (uint32_t)lid[k], go[k], uo[k], dof[k], tb.gate_expert_bytes, tb.down_expert_bytes,
                                                         gb[k], ub[k], db[k], gi[k], ui[k], di[k]);
    g_llms_pfu_loads += nl;
    return 1;
}

int ds4_gpu_stream_expert_cache_seed_selected(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    ds4_gpu_stream_expert_table llms_gubs_t; if (table && llms_gubs()) { llms_gubs_t = *table; llms_gubs_table(&llms_gubs_t); table = &llms_gubs_t; }   /* llms BS6C */
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !selected_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_selected == 0 ||
        n_selected > 6 ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  n_selected) == 0) {
        return 1;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    ds4_gpu_stream_expert_cache_note_selected_hotness(layer,
                                                      selected_ids,
                                                      n_selected);
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 || (uint32_t)selected_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: Metal prefill expert-cache seed selected expert id %d is outside 0..%u\n",
                    selected_ids[i],
                    n_total_expert);
            return 0;
        }
        const uint64_t expert_id = (uint64_t)(uint32_t)selected_ids[i];
        if (expert_id > UINT64_MAX / gate_expert_bytes ||
            expert_id > UINT64_MAX / down_expert_bytes) {
            fprintf(stderr, "ds4: Metal prefill expert-cache seed offset overflow\n");
            return 0;
        }
        const uint64_t gate_rel = expert_id * gate_expert_bytes;
        const uint64_t down_rel = expert_id * down_expert_bytes;
        if (gate_rel > UINT64_MAX - gate_offset ||
            gate_rel > UINT64_MAX - up_offset ||
            down_rel > UINT64_MAX - down_offset) {
            fprintf(stderr, "ds4: Metal prefill expert-cache seed offset overflow\n");
            return 0;
        }

        if (!ds4_gpu_stream_expert_cache_get(model_map,
                                             model_size,
                                             layer,
                                             (uint32_t)selected_ids[i],
                                             n_total_expert,
                                             n_selected,
                                             gate_offset + gate_rel,
                                             up_offset + gate_rel,
                                             down_offset + down_rel,
                                             gate_expert_bytes,
                                             down_expert_bytes)) {
            return 0;
        }
    }
    ds4_gpu_stream_expert_cache_prune_layer(layer,
                                            n_total_expert,
                                            n_selected,
                                            selected_ids,
                                            n_selected);
    ds4_gpu_stream_expert_cache_prune_global(layer,
                                             selected_ids,
                                             n_selected);
    return 1;
}

static int ds4_gpu_stream_expert_cache_seed_experts_impl(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        const uint32_t                    *expert_priorities,
        uint32_t                           n_experts,
        int                                gpu_copy_source) {
    ds4_gpu_stream_expert_table llms_gubs_t; if (table && llms_gubs()) { llms_gubs_t = *table; llms_gubs_table(&llms_gubs_t); table = &llms_gubs_t; }   /* llms BS6C */
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !expert_ids ||
        layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_experts == 0 ||
        n_total_expert == 0 ||
        n_total_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT ||
        !ds4_gpu_stream_expert_cache_note_expert_size(gate_expert_bytes,
                                                      down_expert_bytes) ||
        ds4_gpu_stream_expert_cache_effective_cap(layer,
                                                  n_total_expert,
                                                  1) == 0) {
        return 1;
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;

    ds4_gpu_stream_expert_cache_maybe_decay_route_hotness();
    uint32_t remaining = n_experts;
    while (remaining != 0) {
        const uint32_t batch =
            remaining > 6u ? 6u : remaining;
        remaining -= batch;

        int32_t selected_ids[6] = { -1, -1, -1, -1, -1, -1 };
        uint64_t gate_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        uint64_t up_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        uint64_t down_abs_offsets[6] = { 0, 0, 0, 0, 0, 0 };
        ds4_gpu_stream_expert_cache_entry *entries[6] = {
            NULL, NULL, NULL, NULL, NULL, NULL
        };
        uint32_t missing_mask = 0;

        for (uint32_t i = 0; i < batch; i++) {
            const int32_t expert = expert_ids[remaining + i];
            const uint32_t priority =
                expert_priorities ? expert_priorities[remaining + i] : 0;
            if (expert < 0 || (uint32_t)expert >= n_total_expert) {
                fprintf(stderr,
                        "ds4: Metal streaming hotlist seed expert id %d is outside 0..%u\n",
                        expert,
                        n_total_expert);
                return 0;
            }
            const uint64_t expert_id = (uint64_t)(uint32_t)expert;
            if (expert_id > UINT64_MAX / gate_expert_bytes ||
                expert_id > UINT64_MAX / down_expert_bytes) {
                fprintf(stderr, "ds4: Metal streaming hotlist seed offset overflow\n");
                return 0;
            }
            const uint64_t gate_rel = expert_id * gate_expert_bytes;
            const uint64_t down_rel = expert_id * down_expert_bytes;
            if (gate_rel > UINT64_MAX - gate_offset ||
                gate_rel > UINT64_MAX - up_offset ||
                down_rel > UINT64_MAX - down_offset) {
                fprintf(stderr, "ds4: Metal streaming hotlist seed offset overflow\n");
                return 0;
            }

            ds4_gpu_stream_expert_cache_note_route_hotness(
                    layer,
                    (uint32_t)expert,
                    priority != 0 ? priority : 1u);
            selected_ids[i] = expert;
            gate_abs_offsets[i] = gate_offset + gate_rel;
            up_abs_offsets[i] = up_offset + gate_rel;
            down_abs_offsets[i] = down_offset + down_rel;
            entries[i] = ds4_gpu_stream_expert_cache_peek(model_map,
                                                          model_size,
                                                          layer,
                                                          (uint32_t)expert,
                                                          n_total_expert,
                                                          batch,
                                                          gate_abs_offsets[i],
                                                          up_abs_offsets[i],
                                                          down_abs_offsets[i],
                                                          gate_expert_bytes,
                                                          down_expert_bytes);
            if (!entries[i]) missing_mask |= 1u << i;
            if (entries[i] && priority != 0 &&
                entries[i]->use_count < (uint64_t)priority) {
                entries[i]->use_count = (uint64_t)priority;
            }
        }

        if (missing_mask != 0 &&
            !ds4_gpu_stream_expert_cache_load_selected_missing_with_source(
                    model_map,
                    model_size,
                    layer,
                    selected_ids,
                    n_total_expert,
                    batch,
                    gate_abs_offsets,
                    up_abs_offsets,
                    down_abs_offsets,
                    gate_expert_bytes,
                    down_expert_bytes,
                    missing_mask,
                    gpu_copy_source,
                    entries)) {
            return 0;
        }
        if (expert_priorities) {
            for (uint32_t i = 0; i < batch; i++) {
                const uint32_t priority = expert_priorities[remaining + i];
                if (entries[i] && priority != 0 &&
                    entries[i]->use_count < (uint64_t)priority) {
                    entries[i]->use_count = (uint64_t)priority;
                }
            }
        }
    }

    const uint32_t protect_n = n_experts < 6u ? n_experts : 6u;
    ds4_gpu_stream_expert_cache_prune_layer(layer,
                                            n_total_expert,
                                            1,
                                            expert_ids,
                                            protect_n);
    ds4_gpu_stream_expert_cache_prune_global(layer,
                                             expert_ids,
                                             protect_n);
    return 1;
}

int ds4_gpu_stream_expert_cache_seed_experts(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        const uint32_t                    *expert_priorities,
        uint32_t                           n_experts) {
    ds4_gpu_stream_expert_table llms_gubs_t; if (table && llms_gubs()) { llms_gubs_t = *table; llms_gubs_table(&llms_gubs_t); table = &llms_gubs_t; }   /* llms BS6C */
    @autoreleasepool {
        return ds4_gpu_stream_expert_cache_seed_experts_impl(table,
                                                             expert_ids,
                                                             expert_priorities,
                                                             n_experts,
                                                             0);
    }
}

int ds4_gpu_stream_expert_cache_seed_experts_gpu_copy(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        const uint32_t                    *expert_priorities,
        uint32_t                           n_experts) {
    ds4_gpu_stream_expert_table llms_gubs_t; if (table && llms_gubs()) { llms_gubs_t = *table; llms_gubs_table(&llms_gubs_t); table = &llms_gubs_t; }   /* llms BS6C */
    /* The C prefill caller has no pool. In particular, blit encoders retain
     * destination slabs even after the cache drops its last references. */
    @autoreleasepool {
        return ds4_gpu_stream_expert_cache_seed_experts_impl(table,
                                                             expert_ids,
                                                             expert_priorities,
                                                             n_experts,
                                                             (llms_gubs() && llms_bs64_nolist()) ? 0 : 1);   /* llms BS64_NOLIST part 2: the bs64 side file is not in the model mapping -- seed it by pread, not GPU copy */
    }
}
static uint32_t ds4_gpu_q4_expert_table_group_size(uint32_t n_total_expert) {
    const char *env = getenv("DS4_METAL_Q4_EXPERT_TABLE_GROUP_SIZE");
    if (!env || !env[0]) return 1;
    char *end = NULL;
    unsigned long v = strtoul(env, &end, 10);
    if (end == env || *end != '\0' || v < 2 || v > n_total_expert) {
        return 1;
    }
    return (uint32_t)v;
}

static bool ds4_gpu_q4_table_queue_residency_requested(void) {
    return getenv("DS4_METAL_Q4_TABLE_QUEUE_RESIDENCY_SET") != NULL;
}

static bool ds4_gpu_q4_table_queue_residency_available(void) {
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        return g_queue && [g_queue respondsToSelector:@selector(addResidencySet:)];
    }
#endif
    return false;
}

static bool ds4_gpu_q4_non_streaming_opt_in_enabled(void) {
    return getenv("DS4_METAL_ENABLE_Q4_SELECTED_EXPERT_VIEWS") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_SELECTED_EXPERT_VIEWS") != NULL ||
           llms_genv("DS4_METAL_ENABLE_Q4_EXPERT_TABLE") != NULL ||
           getenv("DS4_METAL_ENABLE_Q4_EXPERT_ADDRESS_TABLE") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_TABLE_AUTO") != NULL ||
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") != NULL;
}

static bool ds4_gpu_q4_selected_paths_allowed(void) {
    if (g_ssd_streaming_mode) return true;
    if (g_glm_model_mode) return false;
    return ds4_gpu_q4_non_streaming_opt_in_enabled();
}

int ds4_gpu_pro_q4_expert_table_auto_available(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    /* Indirect tables retain every expert and its residency set. They cannot
     * coexist with a bounded SSD cache, even when only six experts are read. */
    return !g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_TABLE_AUTO") != NULL &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_TABLE_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_Q4_EXPERT_TABLE") == NULL &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_queue_residency_enabled(bool auto_queue_residency) {
    return (auto_queue_residency || ds4_gpu_q4_table_queue_residency_requested()) &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_model_residency_enabled(void) {
    return getenv("DS4_METAL_Q4_TABLE_MODEL_RESIDENCY_SET") != NULL;
}

static bool ds4_gpu_pro_q4_expert_indirect_shape_supported(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    const uint64_t q4_selected_min_tensor_bytes = 2ull * 1024ull * 1024ull * 1024ull;
    return n_total_expert == 384 &&
           n_expert == 6 &&
           gate_tensor_bytes >= q4_selected_min_tensor_bytes &&
           down_tensor_bytes >= q4_selected_min_tensor_bytes;
}

static bool ds4_gpu_pro_q4_expert_table_auto_enabled(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    /*
     * This path lets the shader choose among exact per-expert resources.
     * It is only automatic when a Metal queue residency set can make every
     * indirect expert resource visible up front; otherwise the selected
     * exact-slice path remains the fallback.
     */
    return ds4_gpu_pro_q4_expert_indirect_shape_supported(n_total_expert,
                                                          n_expert,
                                                          gate_tensor_bytes,
                                                          down_tensor_bytes) &&
           ds4_gpu_pro_q4_expert_table_auto_available();
}

static bool ds4_gpu_pro_q4_expert_address_auto_enabled(
        uint32_t n_total_expert,
        uint32_t n_expert,
        uint64_t gate_tensor_bytes,
        uint64_t down_tensor_bytes) {
    /*
     * GPU-address expert tables are useful for experiments, but they are not
     * safe as an automatic path unless every indirect expert resource is made
     * visible to Metal. Keep this behind an explicit opt-in while the selected
     * active-slice path remains the correctness/performance baseline.
     */
    return !g_ssd_streaming_mode &&
           getenv("DS4_METAL_ENABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") != NULL &&
           ds4_gpu_q4_selected_paths_allowed() &&
           ds4_gpu_pro_q4_expert_indirect_shape_supported(n_total_expert,
                                                          n_expert,
                                                          gate_tensor_bytes,
                                                          down_tensor_bytes) &&
           g_moe_mul_mv_addr_q4_k_pair_swiglu_pipeline != nil &&
           g_moe_mul_mv_addr_q4_k_sum6_pipeline != nil &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_TABLE_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_PRO_Q4_EXPERT_ADDRESS_AUTO") == NULL &&
           getenv("DS4_METAL_DISABLE_Q4_EXPERT_ADDRESS_TABLE") == NULL &&
           ds4_gpu_q4_table_queue_residency_available();
}

static bool ds4_gpu_q4_table_bind_anchors_enabled(void) {
    return getenv("DS4_METAL_Q4_TABLE_BIND_ANCHORS") != NULL;
}

static int ds4_gpu_use_model_residency_set(id<MTLCommandBuffer> cb) {
    if (!ds4_gpu_q4_table_model_residency_enabled()) return 1;
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        if (cb && g_model_residency_set && [cb respondsToSelector:@selector(useResidencySet:)]) {
            [cb useResidencySet:g_model_residency_set];
            return 1;
        }
    }
#endif
    fprintf(stderr, "ds4: Metal Q4 table model residency set is not available\n");
    return 0;
}

static int ds4_gpu_bind_q4_expert_table_anchors(
        id<MTLComputeCommandEncoder> enc,
        DS4MetalQ4ExpertTable       *table,
        NSUInteger                   first_index,
        NSUInteger                   max_count) {
    if (!ds4_gpu_q4_table_bind_anchors_enabled()) return 1;
    if (!enc || !table || !table.expertBuffers) return 0;

    const NSUInteger count = [table.expertBuffers count];
    if (count > max_count) {
        fprintf(stderr,
                "ds4: Metal Q4 table anchor count %lu exceeds available slots %lu\n",
                (unsigned long)count,
                (unsigned long)max_count);
        return 0;
    }
    for (NSUInteger i = 0; i < count; i++) {
        [enc setBuffer:[table.expertBuffers objectAtIndex:i]
                offset:0
               atIndex:first_index + i];
    }
    return 1;
}

static id ds4_gpu_q4_expert_table_residency_set(NSMutableArray<id<MTLBuffer>> *buffers) {
    if (!buffers || [buffers count] == 0 ||
        getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") == NULL ||
        getenv("DS4_METAL_Q4_TABLE_PER_TENSOR_RESIDENCY_SET") == NULL) {
        return nil;
    }
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        MTLResidencySetDescriptor *desc = [[MTLResidencySetDescriptor alloc] init];
        desc.label = @"ds4_q4_expert_table";
        desc.initialCapacity = [buffers count];
        NSError *error = nil;
        id residency_set = [g_device newResidencySetWithDescriptor:desc error:&error];
        if (!residency_set) {
            fprintf(stderr, "ds4: Metal Q4 expert table residency set creation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return nil;
        }
        for (id<MTLBuffer> buffer in buffers) {
            [residency_set addAllocation:buffer];
        }
        [residency_set commit];
        [residency_set requestResidency];
        return residency_set;
    }
#endif
    return nil;
}

static void ds4_gpu_q4_residency_add_table(id residency_set,
                                           DS4MetalQ4ExpertTable *table) {
#if TARGET_OS_OSX
    if (!residency_set || !table) return;
    if (@available(macOS 15.0, *)) {
        if (table.argumentBuffer) {
            [residency_set addAllocation:table.argumentBuffer];
        }
        if (table.addressBuffer) {
            [residency_set addAllocation:table.addressBuffer];
        }
        for (id<MTLBuffer> buffer in table.expertBuffers) {
            [residency_set addAllocation:buffer];
        }
    }
#else
    (void)residency_set;
    (void)table;
#endif
}

static id ds4_gpu_q4_expert_layer_residency_set(DS4MetalQ4ExpertTable *gate_table,
                                                DS4MetalQ4ExpertTable *up_table,
                                                DS4MetalQ4ExpertTable *down_table,
                                                bool auto_queue_residency) {
    const bool queue_residency =
        ds4_gpu_q4_table_queue_residency_enabled(auto_queue_residency);
    if (!gate_table || !up_table || !down_table ||
        !g_device || !g_q4_expert_layer_residency_cache ||
        (getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") == NULL &&
         !queue_residency)) {
        return nil;
    }
#if TARGET_OS_OSX
    if (@available(macOS 15.0, *)) {
        NSString *key = [NSString stringWithFormat:@"%p:%p:%p",
                         gate_table, up_table, down_table];
        DS4MetalQ4LayerResidency *cached =
            [g_q4_expert_layer_residency_cache objectForKey:key];
        if (cached) return cached.residencySet;

        const NSUInteger capacity =
            [gate_table.expertBuffers count] +
            [up_table.expertBuffers count] +
            [down_table.expertBuffers count] + 3u;
        MTLResidencySetDescriptor *desc = [[MTLResidencySetDescriptor alloc] init];
        desc.label = @"ds4_q4_expert_layer";
        desc.initialCapacity = capacity;
        NSError *error = nil;
        id residency_set = [g_device newResidencySetWithDescriptor:desc error:&error];
        if (!residency_set) {
            fprintf(stderr,
                    "ds4: Metal Q4 expert layer residency set creation failed: %s\n",
                    [[error localizedDescription] UTF8String]);
            return nil;
        }

        ds4_gpu_q4_residency_add_table(residency_set, gate_table);
        ds4_gpu_q4_residency_add_table(residency_set, up_table);
        ds4_gpu_q4_residency_add_table(residency_set, down_table);
        [residency_set commit];
        [residency_set requestResidency];

        DS4MetalQ4LayerResidency *entry = [DS4MetalQ4LayerResidency new];
        entry.residencySet = residency_set;
        if (queue_residency) {
            [g_queue addResidencySet:residency_set];
            entry.addedToQueue = YES;
        }
        [g_q4_expert_layer_residency_cache setObject:entry forKey:key];
        return residency_set;
    }
#endif
    return nil;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_table(
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                tensor_offset,
        uint64_t                expert_bytes,
        uint32_t                n_total_expert,
        id<MTLArgumentEncoder>  encoder);

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_address_table(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    tensor_offset,
        uint64_t    expert_bytes,
        uint32_t    n_total_expert);

int ds4_gpu_preload_q4_expert_tables(const void *model_map, uint64_t model_size,
                                     uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
                                     uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
                                     uint32_t n_total_expert) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!model_map || model_size == 0 || gate_expert_bytes == 0 ||
        down_expert_bytes == 0 || n_total_expert == 0) {
        return 0;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert table preload byte size overflow\n");
        return 0;
    }

    const uint64_t gate_tensor_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_tensor_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    const bool address_auto =
        ds4_gpu_pro_q4_expert_address_auto_enabled(n_total_expert,
                                                   6,
                                                   gate_tensor_bytes,
                                                   down_tensor_bytes);
    const bool table_auto =
        ds4_gpu_pro_q4_expert_table_auto_enabled(n_total_expert,
                                                 6,
                                                 gate_tensor_bytes,
                                                 down_tensor_bytes);
    if (!address_auto && !table_auto) {
        return 1;
    }

    if (address_auto) {
        @autoreleasepool {
            DS4MetalQ4ExpertTable *gate_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                gate_offset,
                                                gate_expert_bytes,
                                                n_total_expert);
            DS4MetalQ4ExpertTable *up_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                up_offset,
                                                gate_expert_bytes,
                                                n_total_expert);
            DS4MetalQ4ExpertTable *down_table =
                ds4_gpu_q4_expert_address_table(model_map,
                                                model_size,
                                                down_offset,
                                                down_expert_bytes,
                                                n_total_expert);
            if (!gate_table || !up_table || !down_table) {
                return 0;
            }
            id residency = ds4_gpu_q4_expert_layer_residency_set(gate_table,
                                                                 up_table,
                                                                 down_table,
                                                                 true);
            if (!residency) {
                fprintf(stderr, "ds4: Metal Q4 expert address table preload failed to create queue residency set\n");
                return 0;
            }
        }
        return 1;
    }

    if (!g_moe_table_q4_pair_gate_encoder || !g_moe_table_q4_pair_up_encoder ||
        !g_moe_table_q4_sum_down_encoder) {
        fprintf(stderr, "ds4: Metal Q4 expert table preload missing argument encoders\n");
        return 0;
    }

    @autoreleasepool {
        DS4MetalQ4ExpertTable *gate_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    gate_offset,
                                    gate_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_pair_gate_encoder);
        DS4MetalQ4ExpertTable *up_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    up_offset,
                                    gate_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_pair_up_encoder);
        DS4MetalQ4ExpertTable *down_table =
            ds4_gpu_q4_expert_table(model_map,
                                    model_size,
                                    down_offset,
                                    down_expert_bytes,
                                    n_total_expert,
                                    g_moe_table_q4_sum_down_encoder);
        if (!gate_table || !up_table || !down_table) {
            return 0;
        }
        id residency = ds4_gpu_q4_expert_layer_residency_set(gate_table,
                                                             up_table,
                                                             down_table,
                                                             true);
        if (!residency) {
            fprintf(stderr, "ds4: Metal Q4 expert table preload failed to create queue residency set\n");
            return 0;
        }
    }
    return 1;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_table(
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                tensor_offset,
        uint64_t                expert_bytes,
        uint32_t                n_total_expert,
        id<MTLArgumentEncoder>  encoder) {
    if (g_ssd_streaming_mode || !model_map || !g_device || !g_q4_expert_table_cache || !encoder ||
        model_size == 0 || expert_bytes == 0 ||
        n_total_expert == 0 || n_total_expert > 384) {
        return nil;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert table byte size overflow\n");
        return nil;
    }
    const uint64_t tensor_bytes = (uint64_t)n_total_expert * expert_bytes;
    if (tensor_offset > model_size || tensor_bytes > model_size - tensor_offset) {
        fprintf(stderr, "ds4: Metal Q4 expert table is outside the mapped model\n");
        return nil;
    }

    const uint32_t table_group_size =
        ds4_gpu_q4_expert_table_group_size(n_total_expert);
    NSString *key = [NSString stringWithFormat:@"%p:%llu:%llu:%llu:%u:%llu:%u",
                     model_map,
                     (unsigned long long)model_size,
                     (unsigned long long)tensor_offset,
                     (unsigned long long)expert_bytes,
                     n_total_expert,
                     (unsigned long long)[encoder encodedLength],
                     table_group_size];
    DS4MetalQ4ExpertTable *cached = [g_q4_expert_table_cache objectForKey:key];
    if (cached) return cached;

    id<MTLBuffer> arg_buffer =
        [g_device newBufferWithLength:[encoder encodedLength]
                               options:MTLResourceStorageModeShared];
    if (!arg_buffer) {
        fprintf(stderr, "ds4: Metal Q4 expert table argument buffer allocation failed\n");
        return nil;
    }
    arg_buffer.label = @"ds4_q4_expert_table";
    [encoder setArgumentBuffer:arg_buffer offset:0];

    NSMutableArray<id<MTLBuffer>> *expert_buffers =
        [NSMutableArray arrayWithCapacity:table_group_size > 1 ?
            (n_total_expert + table_group_size - 1u) / table_group_size :
            n_total_expert];
    if (!expert_buffers) return nil;

    if (table_group_size > 1) {
        for (uint32_t first = 0; first < n_total_expert; first += table_group_size) {
            const uint32_t remaining = n_total_expert - first;
            const uint32_t group_n =
                remaining < table_group_size ? remaining : table_group_size;
            if ((uint64_t)first > UINT64_MAX / expert_bytes ||
                (uint64_t)group_n > UINT64_MAX / expert_bytes) {
                fprintf(stderr, "ds4: Metal Q4 expert table group byte overflow\n");
                return nil;
            }
            const uint64_t rel = (uint64_t)first * expert_bytes;
            const uint64_t group_bytes = (uint64_t)group_n * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert table group offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> group_buf =
                ds4_gpu_wrap_model_range(model_map,
                                         model_size,
                                         tensor_offset + rel,
                                         group_bytes,
                                         &inner);
            if (!group_buf) return nil;
            for (uint32_t j = 0; j < group_n; j++) {
                const uint64_t expert_inner = inner + (uint64_t)j * expert_bytes;
                [encoder setBuffer:group_buf offset:(NSUInteger)expert_inner atIndex:first + j];
            }
            [expert_buffers addObject:group_buf];
        }
    } else {
        for (uint32_t i = 0; i < n_total_expert; i++) {
            const uint64_t rel = (uint64_t)i * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert table offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> expert_buf =
                ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                     model_size,
                                                     tensor_offset + rel,
                                                     expert_bytes,
                                                     &inner);
            if (!expert_buf) return nil;
            [encoder setBuffer:expert_buf offset:(NSUInteger)inner atIndex:i];
            [expert_buffers addObject:expert_buf];
        }
    }

    if (getenv("DS4_METAL_Q4_EXPERT_TABLE_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal Q4 expert table: experts=%u group=%u buffers=%lu expert_bytes=%.2f MiB\n",
                n_total_expert,
                table_group_size,
                (unsigned long)[expert_buffers count],
                ds4_gpu_mib(expert_bytes));
    }

    DS4MetalQ4ExpertTable *table = [DS4MetalQ4ExpertTable new];
    table.argumentBuffer = arg_buffer;
    table.expertBuffers = expert_buffers;
    table.residencySet = ds4_gpu_q4_expert_table_residency_set(expert_buffers);
    table.nExpert = n_total_expert;
    table.expertBytes = expert_bytes;
    [g_q4_expert_table_cache setObject:table forKey:key];
    return table;
}

static DS4MetalQ4ExpertTable *ds4_gpu_q4_expert_address_table(
        const void *model_map,
        uint64_t    model_size,
        uint64_t    tensor_offset,
        uint64_t    expert_bytes,
        uint32_t    n_total_expert) {
    if (g_ssd_streaming_mode || !model_map || !g_device || !g_q4_expert_table_cache ||
        model_size == 0 || expert_bytes == 0 ||
        n_total_expert == 0 || n_total_expert > 384) {
        return nil;
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / expert_bytes) {
        fprintf(stderr, "ds4: Metal Q4 expert address table byte size overflow\n");
        return nil;
    }
    const uint64_t tensor_bytes = (uint64_t)n_total_expert * expert_bytes;
    if (tensor_offset > model_size || tensor_bytes > model_size - tensor_offset) {
        fprintf(stderr, "ds4: Metal Q4 expert address table is outside the mapped model\n");
        return nil;
    }

    const uint32_t table_group_size =
        ds4_gpu_q4_expert_table_group_size(n_total_expert);
    NSString *key = [NSString stringWithFormat:@"addr:%p:%llu:%llu:%llu:%u:%u",
                     model_map,
                     (unsigned long long)model_size,
                     (unsigned long long)tensor_offset,
                     (unsigned long long)expert_bytes,
                     n_total_expert,
                     table_group_size];
    DS4MetalQ4ExpertTable *cached = [g_q4_expert_table_cache objectForKey:key];
    if (cached) return cached;

    id<MTLBuffer> address_buffer =
        [g_device newBufferWithLength:(NSUInteger)n_total_expert * sizeof(uint64_t)
                               options:MTLResourceStorageModeShared];
    if (!address_buffer) {
        fprintf(stderr, "ds4: Metal Q4 expert address table allocation failed\n");
        return nil;
    }
    address_buffer.label = @"ds4_q4_expert_address_table";
    uint64_t *addresses = (uint64_t *)[address_buffer contents];
    if (!addresses) return nil;

    NSMutableArray<id<MTLBuffer>> *expert_buffers =
        [NSMutableArray arrayWithCapacity:table_group_size > 1 ?
            (n_total_expert + table_group_size - 1u) / table_group_size :
            n_total_expert];
    if (!expert_buffers) return nil;

#if TARGET_OS_OSX
    if (@available(macOS 13.0, *)) {
        for (uint32_t first = 0; first < n_total_expert; first += table_group_size) {
            const uint32_t remaining = n_total_expert - first;
            const uint32_t group_n =
                remaining < table_group_size ? remaining : table_group_size;
            if ((uint64_t)first > UINT64_MAX / expert_bytes ||
                (uint64_t)group_n > UINT64_MAX / expert_bytes) {
                fprintf(stderr, "ds4: Metal Q4 expert address table group byte overflow\n");
                return nil;
            }
            const uint64_t rel = (uint64_t)first * expert_bytes;
            const uint64_t group_bytes = (uint64_t)group_n * expert_bytes;
            if (rel > UINT64_MAX - tensor_offset) {
                fprintf(stderr, "ds4: Metal Q4 expert address table group offset overflow\n");
                return nil;
            }
            uint64_t inner = 0;
            id<MTLBuffer> group_buf = nil;
            if (table_group_size > 1) {
                group_buf = ds4_gpu_wrap_model_range(model_map,
                                                     model_size,
                                                     tensor_offset + rel,
                                                     group_bytes,
                                                     &inner);
            } else {
                group_buf = ds4_gpu_wrap_model_exact_range_owned(model_map,
                                                                 model_size,
                                                                 tensor_offset + rel,
                                                                 expert_bytes,
                                                                 &inner);
            }
            if (!group_buf) return nil;
            const uint64_t base_address = (uint64_t)[group_buf gpuAddress] + inner;
            for (uint32_t j = 0; j < group_n; j++) {
                addresses[first + j] = base_address + (uint64_t)j * expert_bytes;
            }
            [expert_buffers addObject:group_buf];
        }
    } else
#endif
    {
        fprintf(stderr, "ds4: Metal GPU addresses require macOS 13 or newer\n");
        return nil;
    }

    if (getenv("DS4_METAL_Q4_EXPERT_TABLE_PROFILE") != NULL) {
        fprintf(stderr,
                "ds4: Metal Q4 expert address table: experts=%u group=%u buffers=%lu expert_bytes=%.2f MiB\n",
                n_total_expert,
                table_group_size,
                (unsigned long)[expert_buffers count],
                ds4_gpu_mib(expert_bytes));
    }

    DS4MetalQ4ExpertTable *table = [DS4MetalQ4ExpertTable new];
    table.addressBuffer = address_buffer;
    table.expertBuffers = expert_buffers;
    table.nExpert = n_total_expert;
    table.expertBytes = expert_bytes;
    [g_q4_expert_table_cache setObject:table forKey:key];
    return table;
}

static void ds4_gpu_use_q4_expert_table_resources(
        id<MTLCommandBuffer>        cb,
        id<MTLComputeCommandEncoder> enc,
        DS4MetalQ4ExpertTable       *table,
        bool                         queue_residency) {
    if (!enc || !table) return;
    if (table.argumentBuffer) {
        [enc useResource:table.argumentBuffer usage:MTLResourceUsageRead];
    }
    if (table.addressBuffer) {
        [enc useResource:table.addressBuffer usage:MTLResourceUsageRead];
    }
    if (!queue_residency &&
        getenv("DS4_METAL_Q4_TABLE_RESIDENCY_SET") != NULL &&
        table.residencySet &&
        cb &&
        [cb respondsToSelector:@selector(useResidencySet:)]) {
        [cb useResidencySet:table.residencySet];
    }
    if (getenv("DS4_METAL_Q4_TABLE_USE_RESOURCES") == NULL &&
        getenv("DS4_METAL_Q4_ADDR_USE_RESOURCES") == NULL) {
        return;
    }
    const NSUInteger count = [table.expertBuffers count];
    for (NSUInteger base = 0; base < count; base += 64u) {
        const NSUInteger n = count - base < 64u ? count - base : 64u;
        __unsafe_unretained id<MTLResource> resources[64];
        for (NSUInteger i = 0; i < n; i++) {
            resources[i] = [table.expertBuffers objectAtIndex:base + i];
        }
        [enc useResources:resources count:n usage:MTLResourceUsageRead];
    }
}

int ds4_gpu_indexer_score_one_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_head,
        uint32_t                head_dim,
        float                   scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !index_comp ||
        n_comp == 0 || n_head == 0 || head_dim == 0) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q_bytes = (uint64_t)n_head * head_dim * sizeof(float);
        const uint64_t weight_bytes = (uint64_t)n_head * sizeof(float);
        const uint64_t comp_bytes = (uint64_t)n_comp * head_dim * sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_comp * sizeof(float);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> compbuf = ds4_gpu_tensor_buffer(index_comp);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        if (!qbuf || !wbuf || !compbuf || !scorebuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weight_bytes ||
            ds4_gpu_tensor_bytes(index_comp) < comp_bytes ||
            ds4_gpu_tensor_bytes(scores) < score_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer score received undersized buffers\n");
            return 0;
        }

        if (n_head == 64 && head_dim == 128) {
            id<MTLComputePipelineState> direct_pipeline =
                ds4_gpu_hot_pipeline(g_dsv4_indexer_score_one_direct_pipeline,
                                        "kernel_dsv4_indexer_score_one_direct");
            if (!direct_pipeline) return 0;

            ds4_gpu_dsv4_indexer_scores_fused_args args = {
                .n_comp = n_comp,
                .n_tokens = 1,
                .n_head = n_head,
                .head_dim = head_dim,
                .pos0 = 0,
                .ratio = 4,
                .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
                .q_head_stride = (uint64_t)head_dim * sizeof(float),
                .weights_token_stride = (uint64_t)n_head * sizeof(float),
                .index_row_stride = (uint64_t)head_dim * sizeof(float),
                .score_token_stride = (uint64_t)n_comp * sizeof(float),
                .scale = scale,
            };

            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:direct_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:3];
            [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [enc setThreadgroupMemoryLength:(128u + 4u) * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_comp, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer direct score")) return 0;
            return 1;
        }

        const uint64_t head_score_bytes = (uint64_t)n_comp * n_head * sizeof(float);
        if (!ds4_gpu_ensure_scratch_buffer(&g_indexer_head_scores_buffer,
                                             &g_indexer_head_scores_bytes,
                                             (NSUInteger)head_score_bytes,
                                             "ds4_indexer_head_scores")) {
            return 0;
        }

        ds4_gpu_q8_0_matvec_args dot_args =
            ds4_gpu_make_f32_mv_args(head_dim, n_comp, n_head);
        ds4_gpu_mv_dispatch dot_dispatch =
            ds4_gpu_make_plain_mv_dispatch(head_dim, 1);
        dot_args.nr0 = dot_dispatch.nr0;
        id<MTLComputePipelineState> dot_pipeline =
            ds4_gpu_get_mul_mv_pipeline(dot_dispatch.function_name, dot_dispatch.nsg);
        if (!dot_pipeline) return 0;
        ds4_gpu_dsv4_indexer_weighted_sum_args sum_args = {
            .ne00 = (int64_t)n_comp,
            .ne01 = 1,
            .ne02 = (int64_t)n_head,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)n_comp * sizeof(float),
            .nb02 = (uint64_t)n_comp * sizeof(float),
            .ne10 = (int64_t)n_head,
            .ne11 = 1,
            .nb10 = sizeof(float),
            .nb11 = (uint64_t)n_head * sizeof(float),
            .ne0 = (int64_t)n_comp,
            .ne1 = 1,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_comp * sizeof(float),
            .scale = scale,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:dot_pipeline];
        [enc setBytes:&dot_args length:sizeof(dot_args) atIndex:0];
        [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:1];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:2];
        [enc setBuffer:g_indexer_head_scores_buffer offset:0 atIndex:3];
        if (dot_dispatch.smem) {
            [enc setThreadgroupMemoryLength:dot_dispatch.smem atIndex:0];
        }
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + (NSUInteger)dot_dispatch.nr0 - 1u) / (NSUInteger)dot_dispatch.nr0,
                                              n_head,
                                              1)
             threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)dot_dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_indexer_weighted_sum_pipeline];
        [enc setBytes:&sum_args length:sizeof(sum_args) atIndex:0];
        [enc setBuffer:g_indexer_head_scores_buffer offset:0 atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer score")) return 0;
    }

    return 1;
}

static int ds4_gpu_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                pos0,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !index_comp ||
        n_comp == 0 || n_tokens == 0 || n_head == 0 || head_dim == 0 || ratio == 0) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        const uint64_t weight_bytes = (uint64_t)n_tokens * n_head * sizeof(float);
        const uint64_t comp_bytes = (uint64_t)n_comp * head_dim * sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> compbuf = ds4_gpu_tensor_buffer(index_comp);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        if (!qbuf || !wbuf || !compbuf || !scorebuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weight_bytes ||
            ds4_gpu_tensor_bytes(index_comp) < comp_bytes ||
            ds4_gpu_tensor_bytes(scores) < score_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer prefill scores received undersized buffers\n");
            return 0;
        }
        if (head_dim != 128) {
            fprintf(stderr, "ds4: Metal fused DS4 indexer scores expect 128-wide rows\n");
            return 0;
        }
        /*
         * The NAX/TensorOps score builder is a prefill-only win.  At small
         * batches and in one-token decode the setup cost is not amortized, so
         * those paths keep the older direct/tiled score kernels.
         */
        const bool use_nax = ds4_gpu_mpp_available() && n_tokens >= 16u;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(
            use_nax ? "kernel_dsv4_indexer_scores_nax" :
            (g_quality_mode ? "kernel_dsv4_indexer_scores_tiled_f32"
                            : "kernel_dsv4_indexer_scores_tiled"));
        if (!pipeline) return 0;

        ds4_gpu_dsv4_indexer_scores_fused_args args = {
            .n_comp = n_comp,
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .pos0 = pos0,
            .ratio = ratio,
            .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
            .q_head_stride = (uint64_t)head_dim * sizeof(float),
            .weights_token_stride = (uint64_t)n_head * sizeof(float),
            .index_row_stride = (uint64_t)head_dim * sizeof(float),
            .score_token_stride = (uint64_t)n_comp * sizeof(float),
            .scale = scale,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(index_comp) atIndex:3];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        if (use_nax) {
            const NSUInteger q_shared = 2u * 32u * 32u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 32u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                            dot_shared * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 15u) / 16u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        } else if (g_quality_mode) {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared + dot_shared) * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        } else {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                            dot_shared * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_comp + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer prefill scores")) return 0;
    }

    return 1;
}

int ds4_gpu_indexer_scores_prefill_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    return ds4_gpu_indexer_scores_batch_tensor(scores,
                                                 q,
                                                 weights,
                                                 index_comp,
                                                 n_comp,
                                                 n_tokens,
                                                 0,
                                                 n_head,
                                                 head_dim,
                                                 ratio,
                                                 scale);
}

int ds4_gpu_indexer_scores_decode_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *index_comp,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                pos0,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                ratio,
        float                   scale) {
    return ds4_gpu_indexer_scores_batch_tensor(scores,
                                                 q,
                                                 weights,
                                                 index_comp,
                                                 n_comp,
                                                 n_tokens,
                                                 pos0,
                                                 n_head,
                                                 head_dim,
                                                 ratio,
                                                 scale);
}

static int llms_tkio(void) {
    static int on = -1; static uint64_t calls;
    if (on < 0) { const char *e = getenv("LLMS_DS4_TK_IDXORD"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); on = e && *e && *e != '0';
                  if (on) { int has = 0; FILE *f = src ? fopen(src, "r") : NULL; if (f) { char buf[65536]; size_t nr;
                                while (!has && (nr = fread(buf, 1, sizeof buf - 1, f)) > 0) { buf[nr] = 0; has = strstr(buf, "llms TK_IDXORD") != NULL; if (!has && nr > 64) fseek(f, -64, SEEK_CUR); } fclose(f); }
                            if (!has) { fprintf(stderr, "llms: LLMS_DS4_TK_IDXORD ignored: DS4_METAL_DSV4_MISC_SOURCE does not carry the TK_IDXORD kernel code\n"); on = 0; }
                            else { fprintf(stderr, "llms: tk idxord (the indexer top-k set in index order, no sort; rounding class; ALT tkio)\n");
                                   atexit_b(^{ fprintf(stderr, "llms tk idxord: %llu dispatches in index order\n", (unsigned long long)calls); }); } } }
    if (on && !llms_alt_off("tkio")) { calls++; return 1; }
    return 0;
}
static int ds4_gpu_indexer_topk_tensor_impl(
        ds4_gpu_tensor       *selected,
        const ds4_gpu_tensor *scores,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k,
        uint32_t                causal_start,
        uint32_t                causal_ratio) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !scores || n_comp == 0 || n_tokens == 0 || top_k == 0 || top_k > n_comp) return 0;
    {   /* llms TOPK_RADIX (apply_ds4_topk_radix.py): radix select, one threadgroup per row; non-causal, 64 <= k <= 1024 */
        static int rx = -2; static id<MTLComputePipelineState> rx_pl; static uint64_t rx_calls;
        if (rx < -1) { const char *e = getenv("LLMS_DS4_TOPK_RADIX"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); rx = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                       if (rx && !(src && llms_srckey(src, "llms16") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_TOPK_RADIX ignored: DS4_METAL_DSV4_MISC_SOURCE does not name an *llms16* source\n"), LLMS_G_NAME); rx = 0; }
                       if (rx) { rx_pl = ds4_gpu_get_pipeline("kernel_llms_topk_radix"); if (!rx_pl) { fprintf(stderr, "llms topk radix: kernel missing\n"); rx = 0; }
                                 else fprintf(stderr, rx < 0 ? "llms: topk radix -- CANARY: each row's first index has its low bit flipped\n" : "llms: topk radix (radix select per row, O(N) in the context)\n"); } }
        if (rx && !causal_ratio && top_k >= 64u && top_k <= 1024u && !llms_alt_off("tkrx")) {
            @autoreleasepool {
                id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores), selbuf = ds4_gpu_tensor_buffer(selected);
                if (!scorebuf || !selbuf || ds4_gpu_tensor_bytes(scores) < (uint64_t)n_comp * n_tokens * sizeof(float) ||
                    ds4_gpu_tensor_bytes(selected) < (uint64_t)top_k * n_tokens * sizeof(uint32_t)) { fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n"); return 0; }
                struct { uint32_t n, k, rows, canary; uint64_t score_stride, sel_stride; uint32_t mode; } ra = { n_comp, top_k, n_tokens, rx < 0 ? 1u : 0u, n_comp, top_k, (uint32_t)llms_tkio() };   /* llms TK_IDXORD: mode */
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                id<MTLComputeCommandEncoder> enc = cb ? ds4_gpu_compute_encoder(cb) : nil;
                if (!enc) return 0;
                [enc setComputePipelineState:rx_pl];
                [enc setBytes:&ra length:sizeof(ra) atIndex:0];
                [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
                [enc setBuffer:selbuf offset:ds4_gpu_tensor_offset(selected) atIndex:2];
                [enc setThreadgroupMemoryLength:(2048u + 16u + 1024u + 1024u) * 4u atIndex:0];
                [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tokens, 1, 1) threadsPerThreadgroup:MTLSizeMake(1024, 1, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                if (!rx_calls++) fprintf(stderr, "llms topk radix: first call (n %u, k %u, rows %u)\n", n_comp, top_k, n_tokens);
                {   /* llms TOPK_KN (instrument): calls with k < n (the radix passes run) vs k >= n (every element selected) */
                    static uint64_t lt, ge, nmax; if (!lt && !ge) atexit_b(^{ fprintf(stderr, "llms topk radix: %llu calls with k < n (max n %llu), %llu with k >= n\n", (unsigned long long)lt, (unsigned long long)nmax, (unsigned long long)ge); });
                    if (top_k < n_comp) lt++; else ge++; if (n_comp > nmax) nmax = n_comp;
                }
                return ds4_gpu_finish_command_buffer(cb, owned, "llms topk radix");
            }
        }
    }

    @autoreleasepool {
        id<MTLComputePipelineState> sort_pipeline = causal_ratio ?
            ds4_gpu_get_pipeline(getenv("DS4_METAL_DISABLE_V41_TOPK_SHUFFLE") ?
                "kernel_argsort_f32_i32_desc_causal" : "kernel_argsort_f32_i32_desc_causal_shuffle") :
            g_argsort_f32_i32_desc_pipeline;
        id<MTLComputePipelineState> merge_pipeline = causal_ratio ?
            ds4_gpu_get_pipeline(top_k == 512u && !getenv("DS4_METAL_DISABLE_V41_TOPK_PREFIX") ?
                "kernel_argsort_merge_f32_i32_desc_causal_prefix" :
                "kernel_argsort_merge_f32_i32_desc_causal") : g_argsort_merge_f32_i32_desc_pipeline;
        if (!sort_pipeline || !merge_pipeline) return 0;
        const uint64_t score_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        const uint64_t selected_bytes = (uint64_t)top_k * n_tokens * sizeof(uint32_t);
        id<MTLBuffer> scorebuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> selbuf = ds4_gpu_tensor_buffer(selected);
        if (!scorebuf || !selbuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(selected) < selected_bytes) {
            fprintf(stderr, "ds4: Metal graph indexer top-k received undersized buffers\n");
            return 0;
        }
        NSUInteger max_threads = g_argsort_f32_i32_desc_pipeline.maxTotalThreadsPerThreadgroup;
        if (max_threads == 0) max_threads = 256;
        int32_t nth = 1;
        while ((uint32_t)nth < n_comp && (uint64_t)2u * (uint64_t)nth <= (uint64_t)max_threads) {
            nth *= 2;
        }
        if (causal_ratio && (sort_pipeline.maxTotalThreadsPerThreadgroup < (NSUInteger)nth ||
            (causal_start + 1u) / causal_ratio <= (uint32_t)nth / 2u)) return 0;
        const int32_t npr = (int32_t)((n_comp + (uint32_t)nth - 1u) / (uint32_t)nth);
        const int32_t block_top_k = (int32_t)(top_k < (uint32_t)nth ? top_k : (uint32_t)nth);
        int32_t work_width = (int32_t)top_k;
        if (npr > 1) {
            const int32_t last_block = (int32_t)n_comp - (npr - 1) * nth;
            work_width = (npr - 1) * block_top_k + (last_block < block_top_k ? last_block : block_top_k);
        }
        const uint64_t scratch_row_bytes = (uint64_t)work_width * sizeof(uint32_t);
        const bool one_pass = npr <= 1;
        const uint64_t scratch_bytes = one_pass ? scratch_row_bytes * n_tokens :
            2u * scratch_row_bytes * n_tokens;
        if (!ds4_gpu_ensure_scratch_buffer(&g_indexer_topk_buffer,
                                             &g_indexer_topk_bytes,
                                             (NSUInteger)scratch_bytes,
                                             "ds4_indexer_topk")) {
            return 0;
        }

        ds4_gpu_kargs_argsort args = {
            .ne00 = (int32_t)n_comp,
            .ne01 = (int32_t)n_tokens,
            .ne02 = 1,
            .ne03 = 1,
            .nb00 = sizeof(float),
            .nb01 = (uint64_t)n_comp * sizeof(float),
            .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
            .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
            .ne0 = work_width,
            .ne1 = (int32_t)n_tokens,
            .ne2 = 1,
            .ne3 = 1,
            .top_k = block_top_k,
            .causal_start = causal_start,
            .causal_ratio = causal_ratio,
        };
        // kernel_argsort_f32_i32_desc stages the block's scores behind the
        // index array: nth int32 indices + nth float scores.
        const NSUInteger smem = (((NSUInteger)nth * (sizeof(int32_t) + sizeof(float))) + 15u) & ~(NSUInteger)15u;

        NSUInteger cur_off = 0;
        NSUInteger next_off = (NSUInteger)scratch_row_bytes * n_tokens;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:sort_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
        [enc setBuffer:one_pass ? selbuf : g_indexer_topk_buffer
              offset:one_pass ? ds4_gpu_tensor_offset(selected) : cur_off
             atIndex:2];
        [enc setThreadgroupMemoryLength:smem atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)npr * n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake((NSUInteger)nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        int32_t len = block_top_k;
        while (len < work_width) {
            const int32_t nm = (work_width + 2 * len - 1) / (2 * len);
            const bool final_merge = nm == 1;
            NSUInteger merge_threads = merge_pipeline.maxTotalThreadsPerThreadgroup;
            if (merge_threads == 0 || merge_threads > 512u) merge_threads = 512u;
            if (merge_threads > (NSUInteger)len) merge_threads = (NSUInteger)len;
            if (merge_threads == 0) merge_threads = 1;

            ds4_gpu_kargs_argsort_merge merge_args = {
                .ne00 = (int64_t)n_comp,
                .ne01 = (int64_t)n_tokens,
                .ne02 = 1,
                .ne03 = 1,
                .nb00 = sizeof(float),
                .nb01 = (uint64_t)n_comp * sizeof(float),
                .nb02 = (uint64_t)n_comp * n_tokens * sizeof(float),
                .nb03 = (uint64_t)n_comp * n_tokens * sizeof(float),
                .ne0 = work_width,
                .ne1 = (int32_t)n_tokens,
                .ne2 = 1,
                .ne3 = 1,
                .top_k = nm == 1 ? (int32_t)top_k : work_width,
                .len = len,
                .causal_start = causal_start,
                .causal_ratio = causal_ratio,
                .block_width = (uint32_t)nth,
                .block_top_k = (uint32_t)block_top_k,
            };

            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:merge_pipeline];
            [enc setBytes:&merge_args length:sizeof(merge_args) atIndex:0];
            [enc setBuffer:scorebuf offset:ds4_gpu_tensor_offset(scores) atIndex:1];
            [enc setBuffer:g_indexer_topk_buffer offset:cur_off atIndex:2];
            [enc setBuffer:final_merge ? selbuf : g_indexer_topk_buffer
                  offset:final_merge ? ds4_gpu_tensor_offset(selected) : next_off
                 atIndex:3];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)nm * n_tokens, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(merge_threads, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            const NSUInteger tmp = cur_off;
            cur_off = next_off;
            next_off = tmp;
            len <<= 1;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "indexer top-k")) return 0;
    }

    return 1;
}

int ds4_gpu_indexer_topk_tensor(ds4_gpu_tensor *selected, const ds4_gpu_tensor *scores,
                               uint32_t n_comp, uint32_t n_tokens, uint32_t top_k) {
    return ds4_gpu_indexer_topk_tensor_impl(selected, scores, n_comp, n_tokens, top_k, 0, 0);
}

int ds4_gpu_dsv41_indexer_topk_batch(ds4_gpu_tensor *selected, const ds4_gpu_tensor *scores,
                                    uint32_t width, uint32_t rows, uint32_t start, uint32_t ratio) {
    if ((ratio != 1u && ratio != 2u) || !rows || rows > UINT32_MAX - start ||
        width > INT32_MAX || rows > INT32_MAX || (start + rows) / ratio > width ||
        (start + 1u) / ratio < 1024u) return 0;
    return ds4_gpu_indexer_topk_tensor_impl(selected, scores, width, rows, 512u, start, ratio);
}

int ds4_gpu_argmax_tensor(
        ds4_gpu_tensor       *out_idx,
        const ds4_gpu_tensor *logits,
        uint32_t                n_vocab) {
    if (!out_idx || !logits || n_vocab == 0) return 0;
    if (ds4_gpu_tensor_bytes(out_idx) < sizeof(int32_t) ||
        ds4_gpu_tensor_bytes(logits) < (uint64_t)n_vocab * sizeof(float)) {
        fprintf(stderr, "ds4: Metal graph argmax received undersized buffers\n");
        return 0;
    }

    return ds4_gpu_indexer_topk_tensor(out_idx, logits, n_vocab, 1, 1);
}

int ds4_gpu_dsv4_topk_mask_tensor(
        ds4_gpu_tensor       *mask,
        const ds4_gpu_tensor *topk,
        uint32_t                n_comp,
        uint32_t                n_tokens,
        uint32_t                top_k) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!mask || !topk || n_comp == 0 || n_tokens == 0 || top_k == 0) return 0;

    @autoreleasepool {
        const uint64_t topk_bytes = (uint64_t)top_k * n_tokens * sizeof(int32_t);
        const uint64_t mask_bytes = (uint64_t)n_comp * n_tokens * sizeof(float);
        id<MTLBuffer> topkbuf = ds4_gpu_tensor_buffer(topk);
        id<MTLBuffer> maskbuf = ds4_gpu_tensor_buffer(mask);
        if (!topkbuf || !maskbuf ||
            ds4_gpu_tensor_bytes(topk) < topk_bytes ||
            ds4_gpu_tensor_bytes(mask) < mask_bytes) {
            fprintf(stderr, "ds4: Metal dsv4 top-k mask received undersized buffers\n");
            return 0;
        }

        ds4_gpu_dsv4_topk_mask_args args = {
            .ne00 = (int64_t)top_k,
            .ne01 = (int64_t)n_tokens,
            .nb00 = sizeof(int32_t),
            .nb01 = (uint64_t)top_k * sizeof(int32_t),
            .ne0 = (int64_t)n_comp,
            .ne1 = (int64_t)n_tokens,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_comp * sizeof(float),
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_topk_mask_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
        [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((((NSUInteger)n_comp * n_tokens) + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_topk_mask_scatter_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
        [enc setBuffer:maskbuf offset:ds4_gpu_tensor_offset(mask) atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((((NSUInteger)top_k * n_tokens) + 255u) / 256u, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "dsv4 top-k mask")) return 0;
    }

    return 1;
}


typedef struct { uint64_t abs, off; uint32_t k, n; __unsafe_unretained id<MTLBuffer> buf; uint64_t inner; char alt[8]; } llms_q4l_ent;   /* buf, inner: llms Q4L_WRAP; alt: llms Q4L_TAG */
static NSMutableArray *g_llms_q4l_bufs;   /* llms Q4L_WRAP: keeps the per-tensor buffers alive */
static llms_q4l_ent *g_llms_q4l; static int g_llms_q4l_n = -1; static id<MTLBuffer> g_llms_q4l_buf;
static uint64_t g_llms_q4l_calls, g_llms_q4l_b_calls, g_llms_q4l_unaligned, g_llms_q4la_calls;   /* q4la: llms Q4L_A */
static int llms_q4l_cmp(const void *a, const void *b) {
    const uint64_t x = ((const llms_q4l_ent *)a)->abs, y = ((const llms_q4l_ent *)b)->abs; return x < y ? -1 : x > y;
}
static void llms_q4l_init(void) {
    g_llms_q4l_n = 0;
    const char *idx = getenv("LLMS_DS4_Q4L");
    if (!idx || !*idx || !strcmp(idx, "0")) return;
    FILE *f = fopen(idx, "r");
    if (!f) { fprintf(stderr, "llms: q4l index %s cannot be opened\n", idx); abort(); }
    char path[4096]; unsigned long long gb = 0;
    if (!fgets(path, sizeof path, f) || fscanf(f, "gguf_bytes %llu\n", &gb) != 1) { fprintf(stderr, "llms: q4l index %s malformed\n", idx); abort(); }
    path[strcspn(path, "\r\n")] = 0;
    llms_relative_asset(path,sizeof path,idx);
    int cap = 256; g_llms_q4l = calloc((size_t)cap, sizeof *g_llms_q4l);
    unsigned long long ab, of; unsigned k, n; char name[512], alt[8], line[1024];   /* llms Q4L_TAG: an optional sixth token, the entry's ALT name */
    while (fgets(line, sizeof line, f)) {
        alt[0] = 0;
        if (sscanf(line, "%llu %llu %u %u %511s %7s", &ab, &of, &k, &n, name, alt) < 5) continue;
        if (g_llms_q4l_n == cap) { cap *= 2; g_llms_q4l = realloc(g_llms_q4l, (size_t)cap * sizeof *g_llms_q4l); }
        llms_q4l_ent e = { ab, of, k, n }; strncpy(e.alt, alt[0] ? alt : "q4l", sizeof e.alt - 1); e.alt[sizeof e.alt - 1] = 0;
        g_llms_q4l[g_llms_q4l_n++] = e;
    }
    fclose(f);
    qsort(g_llms_q4l, (size_t)g_llms_q4l_n, sizeof *g_llms_q4l, llms_q4l_cmp);
    const int fd = open(path, O_RDONLY); const off_t fsz = fd < 0 ? -1 : lseek(fd, 0, SEEK_END);   /* no sys/stat.h in this file */
    if (fd < 0 || fsz <= 0) { fprintf(stderr, "llms: q4l file %s cannot be opened\n", path); abort(); }
    const uint64_t len = ((uint64_t)fsz + 16383u) & ~(uint64_t)16383u;
    void *mp = mmap(NULL, (size_t)len, PROT_READ, MAP_SHARED, fd, 0); close(fd);
    if (mp == MAP_FAILED) { fprintf(stderr, "llms: q4l mmap failed\n"); abort(); }
    for (int i = 0; i < g_llms_q4l_n; i++)
        if ((g_llms_q4l[i].k % 256u) || (g_llms_q4l[i].off % 16u) || g_llms_q4l[i].off + (uint64_t)g_llms_q4l[i].n * (g_llms_q4l[i].k / 16u * 9u) > (uint64_t)fsz) {
            fprintf(stderr, "llms: q4l entry %d (offset %llu) is malformed or past the file end\n", i, (unsigned long long)g_llms_q4l[i].abs); abort();
        }
    {   /* llms Q4L_WRAP: one no-copy buffer per listed tensor; Metal makes only those ranges resident */
        g_llms_q4l_bufs = [NSMutableArray arrayWithCapacity:(NSUInteger)g_llms_q4l_n]; uint64_t wrapped = 0;
        for (int i = 0; i < g_llms_q4l_n; i++) {
            llms_q4l_ent *e = &g_llms_q4l[i];
            const uint64_t a0 = e->off & ~(uint64_t)16383u, end = e->off + (uint64_t)e->n * (e->k / 16u * 9u);
            const uint64_t blen = ((end - a0) + 16383u) & ~(uint64_t)16383u;
            if (a0 + blen > len) { fprintf(stderr, "llms: q4l entry %d range past the mapping\n", i); abort(); }
            id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:(uint8_t *)mp + a0 length:(NSUInteger)blen options:MTLResourceStorageModeShared deallocator:nil];
            if (!b) { fprintf(stderr, "llms: q4l buffer %d failed\n", i); abort(); }
            [g_llms_q4l_bufs addObject:b]; e->buf = b; e->inner = e->off - a0; wrapped += blen;
        }
        g_llms_q4l_buf = g_llms_q4l_bufs.count ? g_llms_q4l_bufs[0] : nil;
        fprintf(stderr, "llms: q4l wraps %d tensors, %.2f GB of the side file\n", g_llms_q4l_n, (double)wrapped / 1e9);
    }
    fprintf(stderr, "llms: q4l on (%d one-token dense matvecs on 4-bit copies, %.2f GB, %s)\n", g_llms_q4l_n, (double)fsz / 1e9, path);
    atexit_b(^{ fprintf(stderr, "llms q4l: %llu one-token calls on the 4-bit copies (%llu with the bf16 store, %llu grouped attn_output_a, %llu left on Q8_0: unaligned activations)\n",
                        (unsigned long long)g_llms_q4l_calls, (unsigned long long)g_llms_q4l_b_calls, (unsigned long long)g_llms_q4la_calls, (unsigned long long)g_llms_q4l_unaligned); });
}
static int g_llms_q4l_bypass;   /* llms DSP41: while set, no tensor takes a Q4L copy (the drafter's support-model tensors; the index is keyed by offset) */
void ds4_gpu_llms_q4l_bypass(int on) { g_llms_q4l_bypass = on; }

static llms_q4l_ent *g_llms_q4ld; static int g_llms_q4ld_n = -1; static uint64_t g_llms_q4ld_hits;
static void llms_q4ld_init(void) {
    g_llms_q4ld_n = 0;
    const char *idx = getenv("LLMS_DS4_Q4L_DSP");
    if (!idx || !*idx || !strcmp(idx, "0")) return;
    FILE *f = fopen(idx, "r"); if (!f) { fprintf(stderr, "llms: q4l dsp index %s cannot be opened\n", idx); abort(); }
    char path[4096]; unsigned long long gb = 0;
    if (!fgets(path, sizeof path, f) || fscanf(f, "gguf_bytes %llu\n", &gb) != 1) { fprintf(stderr, "llms: q4l dsp index %s malformed\n", idx); abort(); }
    path[strcspn(path, "\r\n")] = 0;
    llms_relative_asset(path,sizeof path,idx);
    int cap = 64; g_llms_q4ld = calloc((size_t)cap, sizeof *g_llms_q4ld);
    unsigned long long ab, of; unsigned k, n; char name[512], line[1024];
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%llu %llu %u %u %511s", &ab, &of, &k, &n, name) < 5) continue;
        if (g_llms_q4ld_n == cap) { cap *= 2; g_llms_q4ld = realloc(g_llms_q4ld, (size_t)cap * sizeof *g_llms_q4ld); }
        llms_q4l_ent e = { ab, of, k, n }; strncpy(e.alt, "q4ld", sizeof e.alt - 1); g_llms_q4ld[g_llms_q4ld_n++] = e;
    }
    fclose(f);
    qsort(g_llms_q4ld, (size_t)g_llms_q4ld_n, sizeof *g_llms_q4ld, llms_q4l_cmp);
    const int fd = open(path, O_RDONLY); const off_t fsz = fd < 0 ? -1 : lseek(fd, 0, SEEK_END);
    if (fd < 0 || fsz <= 0) { fprintf(stderr, "llms: q4l dsp file %s cannot be opened\n", path); abort(); }
    const uint64_t len = ((uint64_t)fsz + 16383u) & ~(uint64_t)16383u;
    void *mp = mmap(NULL, (size_t)len, PROT_READ, MAP_SHARED, fd, 0); close(fd);
    if (mp == MAP_FAILED) { fprintf(stderr, "llms: q4l dsp mmap failed\n"); abort(); }
    static NSMutableArray *bufs; bufs = [NSMutableArray arrayWithCapacity:(NSUInteger)g_llms_q4ld_n]; uint64_t wrapped = 0;
    for (int i = 0; i < g_llms_q4ld_n; i++) {
        llms_q4l_ent *e = &g_llms_q4ld[i];
        const uint64_t a0 = e->off & ~(uint64_t)16383u, end = e->off + (uint64_t)e->n * (e->k / 16u * 9u);
        if ((e->k % 256u) || (e->off % 16u) || end > (uint64_t)fsz) { fprintf(stderr, "llms: q4l dsp entry %d malformed\n", i); abort(); }
        const uint64_t blen = ((end - a0) + 16383u) & ~(uint64_t)16383u;
        id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:(uint8_t *)mp + a0 length:(NSUInteger)blen options:MTLResourceStorageModeShared deallocator:nil];
        if (!b) { fprintf(stderr, "llms: q4l dsp buffer %d failed\n", i); abort(); }
        [bufs addObject:b]; e->buf = b; e->inner = e->off - a0; wrapped += blen;
    }
    ds4_gpu_llms_startup_mark("q4l dsp: loaded");   /* llms STARTUP_LOG */
    fprintf(stderr, "llms: q4l dsp on (%d drafter tensors on 4-bit copies, %.2f GB, %s)\n", g_llms_q4ld_n, (double)wrapped / 1e9, path);
    atexit_b(^{ fprintf(stderr, "llms q4l dsp: %llu drafter lookups served from the 4-bit table\n", (unsigned long long)g_llms_q4ld_hits); });
}
static const llms_q4l_ent *llms_q4l_find(uint64_t abs) {
    if (g_llms_q4l_bypass) {   /* llms DSP41; llms Q4L_DSP: the drafter's own table when loaded */
        if (g_llms_q4ld_n < 0) llms_q4ld_init();
        int lo = 0, hi = g_llms_q4ld_n - 1;
        while (lo <= hi) { const int mid = (lo + hi) / 2;
            if (g_llms_q4ld[mid].abs == abs) { g_llms_q4ld_hits++; return &g_llms_q4ld[mid]; }
            if (g_llms_q4ld[mid].abs < abs) lo = mid + 1; else hi = mid - 1; }
        return NULL;
    }
    int lo = 0, hi = g_llms_q4l_n - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (g_llms_q4l[mid].abs == abs) return &g_llms_q4l[mid];
        if (g_llms_q4l[mid].abs < abs) lo = mid + 1; else hi = mid - 1;
    }
    return NULL;
}

typedef struct { uint64_t abs; uint32_t k, n, S, gr; __unsafe_unretained id<MTLBuffer> buf; uint64_t soff; } llms_q4i_ent;
static llms_q4i_ent *g_llms_q4i; static int g_llms_q4i_n = -1, g_llms_q4i_canary, g_llms_q4i_hooks = 3; static NSMutableArray *g_llms_q4i_bufs;
static uint64_t g_llms_q4i_c1, g_llms_q4i_c2; static id<MTLComputePipelineState> g_llms_q4i_ps, g_llms_q4i_cvt;
static int g_llms_ddup = -1; static uint64_t g_llms_ddup_n;   /* llms DENSE_DUP (apply_q4i_dup.py) */
static int llms_ddup(void) { if (g_llms_ddup < 0) { const char *e = getenv("LLMS_DS4_DENSE_DUP"); g_llms_ddup = e && *e == '1';
    if (g_llms_ddup) { fprintf(stderr, "llms: DENSE_DUP -- attn_q_b / output_a matvecs issued twice (the DUP method)\n"); atexit_b(^{ fprintf(stderr, "llms dense dup: %llu second issues\n", (unsigned long long)g_llms_ddup_n); }); } }
    return g_llms_ddup; }
static int llms_q4i_on(void) {
    if (g_llms_q4i_n >= 0) return g_llms_q4i_n > 0;
    g_llms_q4i_n = 0; const char *idx = getenv("LLMS_DS4_Q4I");
    if (!idx || !*idx || !strcmp(idx, "0")) return 0;
    if (!llms_has_kernel("kernel_llms_q4i_mv2")) { fprintf(stderr, "llms: LLMS_DS4_Q4I ignored: the dense source lacks kernel_llms_q4i_mv2\n"); return 0; }
    FILE *f = fopen(idx, "r"); if (!f) { fprintf(stderr, "llms: q4i index %s cannot be opened\n", idx); return 0; }
    char path[4096], line[1024], name[512]; if (!fgets(path, sizeof path, f)) { fclose(f); return 0; } path[strcspn(path, "\r\n")] = 0;
    int cap = 128; g_llms_q4i = calloc((size_t)cap, sizeof *g_llms_q4i); unsigned long long ab, of; unsigned k, n, S, gr;
    uint64_t *offv = calloc((size_t)cap, sizeof(uint64_t));
    while (fgets(line, sizeof line, f)) {
        if (sscanf(line, "%llu %llu %u %u %u %u %511s", &ab, &of, &k, &n, &S, &gr, name) < 7) continue;
        if (g_llms_q4i_n == cap) { cap *= 2; g_llms_q4i = realloc(g_llms_q4i, (size_t)cap * sizeof *g_llms_q4i); offv = realloc(offv, (size_t)cap * sizeof(uint64_t)); }
        offv[g_llms_q4i_n] = of; g_llms_q4i[g_llms_q4i_n++] = (llms_q4i_ent){ ab, k, n, S, gr, nil, 0 };
    }
    fclose(f);
    const int fd = open(path, O_RDONLY); const off_t fsz = fd < 0 ? -1 : lseek(fd, 0, SEEK_END);
    if (fd < 0 || fsz <= 0) { fprintf(stderr, "llms: q4i file %s cannot be opened\n", path); g_llms_q4i_n = 0; free(offv); return 0; }
    const uint64_t len = ((uint64_t)fsz + 16383u) & ~(uint64_t)16383u;
    void *mp = mmap(NULL, (size_t)len, PROT_READ, MAP_SHARED, fd, 0); close(fd);
    if (mp == MAP_FAILED) { fprintf(stderr, "llms: q4i mmap failed\n"); g_llms_q4i_n = 0; free(offv); return 0; }
    g_llms_q4i_bufs = [NSMutableArray arrayWithCapacity:(NSUInteger)g_llms_q4i_n]; uint64_t wrapped = 0;
    for (int e = 0; e < g_llms_q4i_n; e++) {
        llms_q4i_ent *q = &g_llms_q4i[e]; const uint64_t cb = (uint64_t)q->n * q->k / 2u, sb = (uint64_t)q->n * (q->k / 32u) * 2u;
        if ((offv[e] & 16383u) || q->k % 32u || q->n % 32u || q->S < 1u || q->S > 16u || offv[e] + cb + sb > (uint64_t)fsz) { fprintf(stderr, "llms: q4i entry %d malformed\n", e); g_llms_q4i_n = 0; free(offv); return 0; }
        const uint64_t blen = (cb + sb + 16383u) & ~(uint64_t)16383u;
        id<MTLBuffer> b = [g_device newBufferWithBytesNoCopy:(uint8_t *)mp + offv[e] length:(NSUInteger)blen options:MTLResourceStorageModeShared deallocator:nil];
        if (!b) { fprintf(stderr, "llms: q4i buffer %d failed\n", e); g_llms_q4i_n = 0; free(offv); return 0; }
        [g_llms_q4i_bufs addObject:b]; q->buf = b; q->soff = cb; wrapped += blen;
    }
    free(offv);
    g_llms_q4i_ps = ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4i_mv2", 1); g_llms_q4i_cvt = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
    if (!g_llms_q4i_ps || !g_llms_q4i_cvt) { fprintf(stderr, "llms: q4i pipelines missing\n"); g_llms_q4i_n = 0; return 0; }
    { const char *c = getenv("LLMS_DS4_Q4I_CANARY"); g_llms_q4i_canary = c && *c == '1'; }
    { const char *hk = getenv("LLMS_DS4_Q4I_HOOKS"); g_llms_q4i_hooks = hk && *hk ? atoi(hk) & 3 : 3; if (g_llms_q4i_hooks != 3) fprintf(stderr, "llms: q4i hooks mask %d (1 = attn_q_b, 2 = output_a)\n", g_llms_q4i_hooks); }
    fprintf(stderr, "llms: q4i %s: %d tensors, %.2f GB wrapped (two-row attn_q_b / grouped output_a on the interleaved layout)%s\n", path, g_llms_q4i_n, (double)wrapped / 1e9,
            g_llms_q4i_canary ? " -- CANARY: the last block of every row skipped" : "");
    atexit_b(^{ fprintf(stderr, "llms q4i: %llu two-row matvecs + %llu grouped output_a on the interleaved layout\n", (unsigned long long)g_llms_q4i_c1, (unsigned long long)g_llms_q4i_c2); });
    return 1;
}
static const llms_q4i_ent *llms_q4i_find(uint64_t abs) {
    if (g_llms_q4l_bypass) return NULL;   /* the drafter's table: its offsets index another file */
    for (int e = 0; e < g_llms_q4i_n; e++) if (g_llms_q4i[e].abs == abs) return &g_llms_q4i[e];
    return NULL;
}
/* one two-vector Q4I matvec: x_half holds the two rows (token stride xs halves); y = 2 x N floats */
static void llms_q4i_dispatch(id<MTLComputeCommandEncoder> enc, const llms_q4i_ent *ie, id<MTLBuffer> xh, NSUInteger xoff, uint32_t xs, id<MTLBuffer> yb, NSUInteger yoff, uint32_t rb) {
    struct { uint32_t K, N, gr, xs, rb, canary; } ia = { ie->k, ie->n, ie->gr, xs, rb, (uint32_t)g_llms_q4i_canary };
    [enc setComputePipelineState:g_llms_q4i_ps];
    [enc setBytes:&ia length:sizeof ia atIndex:0];
    [enc setBuffer:ie->buf offset:0 atIndex:1];
    [enc setBuffer:ie->buf offset:(NSUInteger)ie->soff atIndex:2];
    [enc setBuffer:xh offset:xoff atIndex:3];
    [enc setBuffer:yb offset:yoff atIndex:4];
    [enc setThreadgroupMemoryLength:(NSUInteger)(ie->S > 1u ? ie->S * 32u * 2u * sizeof(float) : 16u) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)(ie->n / 32u), 1, 1) threadsPerThreadgroup:MTLSizeMake((NSUInteger)(32u * ie->S), 1, 1)];
    if (llms_ddup()) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)(ie->n / 32u), 1, 1) threadsPerThreadgroup:MTLSizeMake((NSUInteger)(32u * ie->S), 1, 1)]; g_llms_ddup_n++; }
}



static uint64_t g_llms_short_calls;
int ds4_gpu_llms_q4l_short(ds4_gpu_tensor *out, uint64_t weight_abs, uint32_t k, uint32_t n_out, const ds4_gpu_tensor *x, const int32_t *ids, uint32_t n_ids) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (llms_alt_off("short") || n_ids == 0 || n_ids > n_out) return 0;
    if (g_llms_q4l_n < 0) llms_q4l_init();
