static uint64_t g_llms_dual_calls, g_llms_dual_splits;
int ds4_gpu_llms_q4l_dual(ds4_gpu_tensor *out_a, uint64_t wa_abs, uint32_t n_a, ds4_gpu_tensor *out_b, uint64_t wb_abs, uint32_t n_b,
