        ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(k, n_a), qb = ds4_gpu_make_q8_0_mv_args(k, n_b);
        qa.nb00 = 1; qa.nb01 = k / 16u * 9u; qa.nb02 = qa.nb01 * n_a; qa.nb03 = qa.nb02; qa.nr0 = 4;
