typedef struct { uint64_t abs; uint32_t k; uint32_t calls; __unsafe_unretained id<MTLBuffer> acc; } llms_act_ent;
static llms_act_ent g_llms_act[512]; static int g_llms_act_n = 0, g_llms_act_on = -1; static NSMutableArray *g_llms_act_keep; static const char *g_llms_act_path;
static void llms_act_dump(void) {
    FILE *f = fopen(g_llms_act_path, "wb"); if (!f) { fprintf(stderr, "llms: act stats: cannot write %s\n", g_llms_act_path); return; }
    const uint32_t n = (uint32_t)g_llms_act_n; fwrite("ACTS", 1, 4, f); fwrite(&n, 4, 1, f);
    for (int i = 0; i < g_llms_act_n; i++) {
        const llms_act_ent *e = &g_llms_act[i];
        fwrite(&e->abs, 8, 1, f); fwrite(&e->k, 4, 1, f); fwrite(&e->calls, 4, 1, f); fwrite([e->acc contents], 4, e->k, f);
    }
    fclose(f); fprintf(stderr, "llms act stats: %d weights written to %s\n", g_llms_act_n, g_llms_act_path);
}
static void llms_act_note(uint64_t abs, id<MTLCommandBuffer> cb, id<MTLBuffer> xbuf, NSUInteger xoff, uint32_t k) {
    if (g_llms_act_on < 0) {
        g_llms_act_path = getenv("LLMS_DS4_ACT_STATS"); g_llms_act_on = g_llms_act_path && *g_llms_act_path ? 1 : 0;
        if (g_llms_act_on) { g_llms_act_keep = [NSMutableArray array]; atexit(llms_act_dump);
                             fprintf(stderr, "llms: act stats on (per-column x^2 of the one-token dense matvecs -> %s)\n", g_llms_act_path); }
    }
    if (!g_llms_act_on || !cb || !xbuf || k == 0) return;
    int i = 0; while (i < g_llms_act_n && g_llms_act[i].abs != abs) i++;
    if (i == g_llms_act_n) {
        if (g_llms_act_n == 512) return;
        id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)k * 4u options:MTLResourceStorageModeShared];
        if (!b) return;
        memset([b contents], 0, (size_t)k * 4u); [g_llms_act_keep addObject:b];
        g_llms_act[i] = (llms_act_ent){ abs, k, 0, b }; g_llms_act_n++;
    }
    if (g_llms_act[i].k != k) return;
    id<MTLComputePipelineState> p = ds4_gpu_get_mul_mv_pipeline("kernel_llms_act_sq_acc", 1);
    if (!p) { fprintf(stderr, "llms: act stats kernel missing from DS4_METAL_DENSE_SOURCE\n"); g_llms_act_on = 0; return; }
    ds4_gpu_q8_0_matvec_args a = ds4_gpu_make_q8_0_mv_args(k, 1);
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:p];
    [enc setBytes:&a length:sizeof(a) atIndex:0];
    [enc setBuffer:xbuf offset:xoff atIndex:1];
    [enc setBuffer:xbuf offset:xoff atIndex:2];
    [enc setBuffer:g_llms_act[i].acc offset:0 atIndex:3];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)k + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    g_llms_act[i].calls++;
}

