            const uint64_t r0ptg = (uint64_t)nypsg * (uint64_t)nsg * (uint64_t)(llms_rpt && (r1ptg == 4 || r1ptg == 8) ? (llms_rpt < 0 ? 4 : llms_rpt) : 1);   /* llms EXT_RPT: rows per threadgroup; the canary uses the RPT-4 grid with the RPT-2 kernel (half the rows unwritten) */
            ds4_gpu_mul_mv_ext_args args =
                ds4_gpu_make_mv_ext_args(in_dim, out_dim, n_tok, 34, row_bytes);
            if (r1ptg == 8) { g_llms_r8_calls++; if (llms_ext_r8() == 2) args.nb11 /= 2; }   /* llms EXT_R8 canary */
            uint32_t llms_slices = 1; id<MTLBuffer> llms_dst_buf = outbuf; NSUInteger llms_dst_off = ds4_gpu_tensor_offset(out);   /* llms EXT_KSLICE */
            if (llms_ext_kslice() && !llms_alt_off("kslice")) {   /* ALT */
                const uint64_t kmax = (uint64_t)(llms_ext_kslice() < 0 ? 1280 : llms_ext_kslice());
                const uint64_t ns = (in_dim + kmax - 1u) / kmax, slice = ns ? in_dim / ns : in_dim;
                const uint64_t need = ns * n_tok * out_dim * sizeof(float);
                if (ns > 1 && ns <= 16 && slice * ns == in_dim && (slice % 128u) == 0) {
                    if (!g_llms_ks_part || g_llms_ks_part_bytes < need) {
                        if (g_llms_ks_part) ds4_gpu_tensor_free(g_llms_ks_part);
                        g_llms_ks_part_bytes = need > (16u << 20) ? need : (16u << 20);
                        g_llms_ks_part = ds4_gpu_tensor_alloc(g_llms_ks_part_bytes);
