                        llms_slices = (uint32_t)ns;
                        args.ne00 = (int32_t)slice; args.ne10 = (int32_t)slice;
                        args.ne02 = (int32_t)ns; args.nb02 = slice * 34u / 32u;            /* the slice's bytes within a weight row */
                        args.ne12 = (int32_t)ns; args.nb12 = slice * sizeof(float);        /* the slice's floats within a token's activations */
                        llms_dst_buf = ds4_gpu_tensor_buffer(g_llms_ks_part); llms_dst_off = ds4_gpu_tensor_offset(g_llms_ks_part);
                        g_llms_ks_calls++;
