                if (!sum_pl) return 0;
                const uint32_t n_out = (uint32_t)(out_dim * n_tok); const uint32_t n_sum = llms_ext_kslice() < 0 ? llms_slices - 1u : llms_slices;   /* canary */
                id<MTLComputeCommandEncoder> enc2 = ds4_gpu_compute_encoder(cb);
                [enc2 setComputePipelineState:sum_pl];
                [enc2 setBuffer:llms_dst_buf offset:llms_dst_off atIndex:0];
                [enc2 setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:1];
                [enc2 setBytes:&n_out length:sizeof(n_out) atIndex:2];
                [enc2 setBytes:&n_sum length:sizeof(n_sum) atIndex:3];
                [llms_bar(enc2) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_out + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
