            !g_quality_mode && n_tok >= 192u && (n_tok % 32u) != 0u;
        const uint64_t nax_rows =
            (n_tok % 32u) == 0u ? n_tok :
            (split_nax_prefix ? n_tok - (n_tok % 32u) : 0u);
        uint64_t generic_row0 = 0u;
        uint64_t generic_rows = n_tok;
        if (ds4_gpu_mpp_available() &&
            nax_rows >= 32u &&
            (in_dim % 64u) == 0 &&
            (out_dim % 64u) == 0) {
