            id<MTLComputeCommandEncoder> unpack_enc = ds4_gpu_compute_encoder(cb);
            [unpack_enc setComputePipelineState:unpack];
            [unpack_enc setBytes:&n_blocks length:sizeof(n_blocks) atIndex:0];
