        if (llms_hxdup()) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; g_llms_hxdup_n++; }
    }
    [enc setComputePipelineState:lq != qnsg && (k2m ? dmhL : split ? dshL : dpL) ? (k2m ? dmhL : split ? dshL : dpL) : (k2m ? dmh : (split ? dsh : dp))];   /* llms Q4L_LEAN2 */
    [enc setBytes:&aa length:sizeof aa atIndex:0]; [enc setBuffer:qa_e->buf offset:(NSUInteger)qa_e->inner atIndex:1];
    [enc setBuffer:hb offset:0 atIndex:2];
    [enc setBuffer:oa offset:ds4_gpu_tensor_offset(out_a) atIndex:3];
    [enc setBytes:&ab length:sizeof ab atIndex:4]; [enc setBuffer:qb_e->buf offset:(NSUInteger)qb_e->inner atIndex:5];
    [enc setBuffer:ob offset:ds4_gpu_tensor_offset(out_b) atIndex:6];
    struct { uint32_t ga, gb, sk, rows; int32_t iters; float eps; } sp = { gp[0], gp[1], split ? 1u : 0u, 2u, (int32_t)iters, eps };   /* llms Q4L_K2SPLIT */
    if (split) {
        [enc setBytes:&sp length:sizeof sp atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(mix) offset:ds4_gpu_tensor_offset(mix) atIndex:8];
        [enc setBuffer:ssb offset:(NSUInteger)ssi atIndex:9]; [enc setBuffer:sbb offset:(NSUInteger)sbi atIndex:10];
        [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:11];
    } else if (k2m) {   /* llms HC_MIXDUAL */
        static int mcan = -1; if (mcan < 0) { const char *e = getenv("LLMS_DS4_HC_MIXDUAL"); mcan = e && *e == '2'; }
        struct { uint32_t ga, gb, nm, rows; int32_t iters; float eps; int32_t n; float rms_eps; int32_t ntg; } mp = { gp[0], gp[1], 192u, 2u,
            (int32_t)(mcan ? ow->take_iters / 2u : ow->take_iters), ow->hc_eps, (int32_t)(4u * 5120u), ow->rms_eps, 32 * (int32_t)qnsg };
        [enc setBytes:&mp length:sizeof mp atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(ow->hin) offset:ds4_gpu_tensor_offset(ow->hin) atIndex:8];
        [enc setBuffer:mfb offset:(NSUInteger)mfi atIndex:9];
        [enc setBuffer:ds4_gpu_tensor_buffer(ow->mix) offset:ds4_gpu_tensor_offset(ow->mix) atIndex:10];
        [enc setBuffer:k2m_scr offset:0 atIndex:11];
        [enc setBuffer:msb offset:(NSUInteger)msi atIndex:12]; [enc setBuffer:mbb offset:(NSUInteger)mbi atIndex:13];
        [enc setBuffer:ds4_gpu_tensor_buffer(ow->split) offset:ds4_gpu_tensor_offset(ow->split) atIndex:14];
    } else [enc setBytes:gp length:sizeof gp atIndex:7];
    [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)gp[0] + gp[1] + (split ? 1u : 0u) + (k2m ? 192u : 0u) - (on == 2 ? 1u : 0u), 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    g_llms_t32_rounded = 1; g_llms_k2d_calls++;
    const int ok = ds4_gpu_finish_command_buffer(cb, owned, "llms q4l k2dual");
    if (ok && ow) { g_llms_owed_n[ow->kind - 1][1]++; ow->kind = 0; }   /* llms HC_OWED: taken */
    return ok;
}

