        ds4_gpu_device_name_contains("M3 Ultra"));
}

int ds4_gpu_matmul_q8_0_decode_rows_exact_tensor(
        ds4_gpu_tensor       *out,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              in_dim,
        uint64_t              out_dim,
        const ds4_gpu_tensor *x,
        uint32_t              n_rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !x || !model_map || n_rows == 0 ||
        n_rows > INT32_MAX || in_dim == 0 || out_dim == 0 ||
        (in_dim & 31u) != 0 || in_dim > UINT32_MAX ||
        out_dim > UINT32_MAX ||
        in_dim > UINT64_MAX / n_rows / sizeof(float) ||
        out_dim > UINT64_MAX / n_rows / sizeof(float) ||
        ds4_gpu_tensor_bytes(x) <
            (uint64_t)n_rows * in_dim * sizeof(float) ||
        ds4_gpu_tensor_bytes(out) <
            (uint64_t)n_rows * out_dim * sizeof(float)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t blocks = in_dim / 32u;
        const uint64_t row_bytes = blocks * 34u;
        if (!xbuf || !outbuf ||
            out_dim > UINT64_MAX / row_bytes) {
            return 0;
        }
        const uint64_t weight_bytes = out_dim * row_bytes;
        if (weight_offset > model_size ||
            weight_bytes > model_size - weight_offset) {
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(
                model_map, model_size, weight_offset, weight_bytes,
                &inner_offset);
        if (!wbuf) return 0;

        {
            static int qk = -1; static uint64_t qk_calls;
            if (qk < 0) { const char *e = getenv("LLMS_DS4_Q4L_K"); qk = e && *e && *e != '0';
                          if (qk) { fprintf(stderr, "llms: q4l k (the batched path's 2-4-row dense matvecs in one pass over the 4-bit copies)\n");
                                    atexit_b(^{ fprintf(stderr, "llms q4l k: %llu multi-row dense matvecs\n", (unsigned long long)qk_calls); }); } }
            if (qk && n_rows >= 2u && n_rows <= 4u && !llms_alt_off("q4lk")) {
                if (g_llms_q4l_n < 0) llms_q4l_init();
                const llms_q4l_ent *qe = g_llms_q4l_n > 0 ? llms_q4l_find(weight_offset) : NULL;
                if (qe && llms_alt_off(qe->alt)) qe = NULL;
                if (qe && (ds4_gpu_tensor_offset(x) & 15u) == 0 && (uint64_t)qe->k == in_dim && (uint64_t)qe->n == out_dim) {
                    const bool rb = g_llms_t32_round && llms_mvb16(0) && !llms_alt_off("mvb");
                    const int nr = n_rows <= 3u ? 8 : 4;
                    char name[64]; snprintf(name, sizeof name, "kernel_llms_q4l_mv_k%u_r%d_%s", n_rows, nr, rb ? "b" : "f");
                    int16_t qnsg = in_dim <= 1536u ? 1 : 2;
                    if (llms_n1w(n_rows, out_dim)) { qnsg = 1; strlcat(name, "_n1", sizeof name); }
                    if (llms_f2(qnsg, rb)) strlcat(name, "_f2", sizeof name);
                    bool llms_hx_use = false;
                    {   static int hx = -1; static uint64_t hx_n;
                        if (hx < 0) { const char *e = getenv("LLMS_DS4_Q4L_HX"); hx = e && *e && *e != '0';
                                      if (hx) { fprintf(stderr, "llms: q4l hx (the two-row dense matvecs read x as HALF: one f32->f16 copy per matvec, then the _bxh kernel; kx_bench 02:56)\n");
                                                atexit_b(^{ fprintf(stderr, "llms q4l hx: %llu two-row dense matvecs on half x\n", (unsigned long long)hx_n); }); } }
                        const size_t ln = strlen(name);
                        if (hx && !llms_alt_off("hx") && ln >= 2 && !strcmp(name + ln - 2, "_b") && (strstr(name, "_k2_") || (strstr(name, "_k3_") && llms_k3x()))) { strlcat(name, "xh", sizeof name); llms_hx_use = true; hx_n++; }
                        {   static int hxo = -1; static uint64_t hxo_n;
                            if (hxo < 0) { const char *e = getenv("LLMS_DS4_Q4L_HXO"); hxo = e && *e && *e != '0';
                                           if (hxo) { fprintf(stderr, "llms: q4l hxo (the unrounded two-row kernels on half x)\n");
                                                      atexit_b(^{ fprintf(stderr, "llms q4l hxo: %llu unrounded two-row matvecs on half x\n", (unsigned long long)hxo_n); }); } }
                            if (hxo && hx && !llms_hx_use && !llms_alt_off("hxo") && (!strcmp(name, "kernel_llms_q4l_mv_k2_r8_f") || (!strcmp(name, "kernel_llms_q4l_mv_k3_r8_f") && llms_k3x()))) { strlcat(name, "xh", sizeof name); llms_hx_use = true; hxo_n++; } }
                        {   static int n1x = -1; static uint64_t n1x_n;
                            if (n1x < 0) { const char *e = getenv("LLMS_DS4_Q4L_N1X"); n1x = e && *e && *e != '0';
                                           if (n1x) { fprintf(stderr, "llms: q4l n1x (one-simdgroup two-row matvecs on half x with the direct epilogue)\n");
                                                      atexit_b(^{ fprintf(stderr, "llms q4l n1x: %llu one-simdgroup half-x matvecs on the direct epilogue\n", (unsigned long long)n1x_n); }); } }
                            const size_t l2 = strlen(name);
                            if (n1x && qnsg == 1 && llms_hx_use && l2 >= 4 && !strcmp(name + l2 - 4, "_bxh") && !llms_alt_off("n1x")) { strlcat(name, "_n1x", sizeof name); n1x_n++; } }
                    }
                    id<MTLComputePipelineState> qp = ds4_gpu_get_mul_mv_pipeline(name, llms_hx_use ? llms_lean2_nsg(qnsg) : qnsg);   /* llms Q4L_LEAN2 */
                    if (qp) {
                        ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
                        qa.nb00 = 1; qa.nb01 = in_dim / 16u * 9u; qa.nb02 = qa.nb01 * out_dim; qa.nb03 = qa.nb02; qa.nr0 = nr;
                        int owned = 0;
                        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                        if (!cb) return 0;
                        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                        [enc setComputePipelineState:qp];
                        [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                        [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                        if (llms_hx_use) {   /* apply_hx.py: the f32 -> f16 copy of x into the next ring slot; the matvec reads the slot (llms_bar's barrier orders them) */
                            static id<MTLBuffer> hx_ring[8]; static unsigned hx_slot; static id<MTLComputePipelineState> hx_cp;
                            if (!hx_cp) hx_cp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
                            if (!hx_cp) { static int w; if (!w++) fprintf(stderr, "llms: kernel_llms_f32_to_f16_rows missing from DS4_METAL_DENSE_SOURCE -- hx off\n"); abort(); }
                            {

                                const unsigned hs = hx_slot & 7u; const NSUInteger hneed = (NSUInteger)n_rows * (NSUInteger)in_dim * 2u;
                                if (!hx_ring[hs] || hx_ring[hs].length < hneed) hx_ring[hs] = [g_device newBufferWithLength:(hneed > 65536u ? hneed : 65536u) options:MTLResourceStorageModePrivate];
                            }
                            id<MTLBuffer> hb = hx_ring[hx_slot++ & 7u];
                            uint32_t cv[3] = { (uint32_t)(in_dim / 4u), (uint32_t)(qa.nb11 / 16u), (uint32_t)n_rows };
                            [enc setComputePipelineState:hx_cp];
                            [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:0];
                            [enc setBuffer:hb offset:0 atIndex:1];
                            [enc setBytes:cv length:sizeof cv atIndex:2];
                            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                            if (llms_hxdup()) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; g_llms_hxdup_n++; }
                            [enc setComputePipelineState:qp];
                            [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                            [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];
                            [enc setBuffer:hb offset:0 atIndex:2];
                        } else [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
                        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                        [enc setThreadgroupMemoryLength:(NSUInteger)nr * 32u * sizeof(float) atIndex:0];
                        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + (NSUInteger)nr - 1u) / (NSUInteger)nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)qnsg, 1)];
                        ds4_gpu_end_compute_encoder(cb, enc);
                        if (rb) g_llms_t32_rounded = 1;
                        qk_calls++;
                        return ds4_gpu_finish_command_buffer(cb, owned, "llms q4l k-row matvec");
                    }
                }
            }
        }
        ds4_gpu_mv_dispatch dispatch = ds4_gpu_make_q8_0_mv_dispatch();
        if (out_dim > 65536u) dispatch.nsg = 8;
        ds4_gpu_q8_0_matvec_args args =
            ds4_gpu_make_q8_0_mv_args(in_dim, out_dim);
        args.ne11 = (int32_t)n_rows;
        args.nb12 = (uint64_t)n_rows * in_dim * sizeof(float);
        args.nb13 = args.nb12;
        args.ne1 = (int32_t)n_rows;
        args.nr0 = dispatch.nr0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mv_pipeline(dispatch.function_name, dispatch.nsg);
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:dispatch.smem atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:
                MTLSizeMake(((NSUInteger)out_dim +
                             (NSUInteger)dispatch.nr0 - 1u) /
                                (NSUInteger)dispatch.nr0,
                            (NSUInteger)n_rows,
                            1)
             threadsPerThreadgroup:
                MTLSizeMake(32, (NSUInteger)dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        return ds4_gpu_finish_command_buffer(
                cb, owned, "Q8_0 exact decode-row matvec");
    }
}

