}

/* llms F32_ROWS (apply_ds4_f32_rows.py): the single-row F32 matvec of ds4_gpu_matmul_f32_tensor for `rows` rows in one dispatch
 * (grid y = rows, ne11 = rows); each row keeps its single-row K walk and reduction tree, so its bits are the single-row ones. */
static id<MTLBuffer> llms_router_bf16_buf(const void *model_map, uint64_t model_size, uint64_t off, uint64_t in_dim, uint64_t out_dim, const char *fn);   /* llms ROWS_RBF */
int ds4_gpu_llms_matmul_f32_rows(ds4_gpu_tensor *out, const void *model_map, uint64_t model_size, uint64_t weight_offset,
                                 uint64_t in_dim, uint64_t out_dim, const ds4_gpu_tensor *x, uint64_t rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (in_dim > UINT32_MAX || out_dim > UINT32_MAX || rows == 0 || rows > llms_rows_max()) return 0;   /* llms ROWS128 */
    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf || ds4_gpu_tensor_bytes(x) < rows * in_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < rows * out_dim * sizeof(float)) {
            fprintf(stderr, "llms F32 rows matvec: undersized activation buffers\n");
            return 0;
        }
        const uint64_t weight_bytes = in_dim * sizeof(float) * out_dim;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) return 0;
        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size, weight_offset, weight_bytes, &inner_offset);
        if (!wbuf) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_f32_mv_args(in_dim, out_dim, rows);
        ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_plain_mv_dispatch(in_dim, 1);
        if (ds4_gpu_plain_mv_single_row(out_dim)) { mv_dispatch.nr0 = 1; mv_dispatch.smem = 32u * sizeof(float); }
        const NSUInteger llms_sg = llms_plain_mv_lean_apply(&mv_dispatch, in_dim, out_dim, 1);   /* the single-row dispatch's shape */
        mv_args.nr0 = mv_dispatch.nr0;
        const uint64_t llms_np8 = llms_pad8_rows(rows, in_dim, out_dim, sizeof(float), xbuf, ds4_gpu_tensor_offset(x), outbuf, ds4_gpu_tensor_offset(out));   /* llms PAD8 */
        {
            static int rr = -1, rr4; static uint64_t rr_n;
            if (rr < 0) { const char *e = getenv("LLMS_DS4_ROWS_RBF"); rr = e && *e && *e != '0';
                          const char *e4 = getenv("LLMS_DS4_ROWS_RBF4"); rr4 = e4 && *e4 && *e4 != '0';
                          if (rr) atexit_b(^{ fprintf(stderr, "llms rows rbf: %llu multi-row router matvecs on the BF16 copy\n", (unsigned long long)rr_n); }); }
            if (rr && rows >= 2u && (rows <= 3u || (rows == 4u && rr4)) && !llms_alt_off("rrbf")) {
                id<MTLBuffer> rb = llms_router_bf16_buf(model_map, model_size, weight_offset, in_dim, out_dim, mv_dispatch.function_name);
                if (rb) { mv_dispatch.function_name = "kernel_mul_mv_bf16_f32_4"; mv_args.nb00 = 2; mv_args.nb01 = in_dim * 2u;
                          mv_args.nb02 = mv_args.nb01 * out_dim; mv_args.nb03 = mv_args.nb02; wbuf = rb; inner_offset = 0; rr_n++; }
            }
        }
        if (mv_args.nb00 == sizeof(float) && llms_t4_wants(llms_np8, out_dim)) {   /* BF16 uses the existing row kernel; F32 keeps T4. */
            ds4_gpu_q8_0_matvec_args t4a = mv_args;
            if (llms_rows_t4() == 3) t4a.nb11 = 0;   /* canary */
            id<MTLComputeCommandEncoder> enc4 = ds4_gpu_compute_encoder(cb);
            if (llms_t4_encode(enc4, 1, &t4a, sizeof(t4a), mv_dispatch, llms_sg, wbuf, (NSUInteger)inner_offset, xbuf,
                               ds4_gpu_tensor_offset(x) + ((llms_np8 != rows && llms_pad8() < 0) ? (NSUInteger)(in_dim * sizeof(float)) : 0u),   /* llms PAD8 canary */
                               outbuf, ds4_gpu_tensor_offset(out), out_dim, llms_np8)) {
                ds4_gpu_end_compute_encoder(cb, enc4);
                if (!ds4_gpu_finish_command_buffer(cb, owned, "llms F32 rows t4 matvec")) return 0;
                return 1;
            }
