        }
        int llms_f16k2 = 0;
        {   static int k2 = -1; static uint64_t k2_n;
            if (k2 < 0) { const char *e = getenv("LLMS_DS4_F16_K2"); k2 = e && *e && *e != '0';
                          if (k2) { fprintf(stderr, "llms: f16 k2 (the two-row generic F16 / BF16 matvecs on the k-family kernel: the weights read once for both rows; kf16_bench 03:50)\n");
                                    atexit_b(^{ fprintf(stderr, "llms f16 k2: %llu two-row F16 / BF16 matvecs on the k-family kernel\n", (unsigned long long)k2_n); }); } }
            const int isf16 = !strcmp(mv_dispatch.function_name, "kernel_mul_mv_f16_f32_4"), isbf16 = !strcmp(mv_dispatch.function_name, "kernel_mul_mv_bf16_f32_4");
            if (k2 && (rows == 2u || (rows == 3u && llms_k3x())) && out_dim >= 128u && (in_dim % 32u) == 0 && (isf16 || isbf16) && !llms_alt_off("f16k2")) {   /* llms K3X */
                mv_dispatch.function_name = rows == 3u ? (isbf16 ? "kernel_llms_bf16_mv_k3_r2" : "kernel_llms_f16_mv_k3_r2") : isbf16 ? "kernel_llms_bf16_mv_k2_r2" : "kernel_llms_f16_mv_k2_r2"; mv_dispatch.nr0 = 2; mv_dispatch.nsg = in_dim >= 4096u ? 4 : 2; mv_dispatch.smem = 2u * 32u * sizeof(float);
                mv_args.nr0 = 2; llms_f16k2 = 1; k2_n++;
