int ds4_gpu_rms_norm_plain_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        uint32_t                n,
        float                   eps) {
    return ds4_gpu_rms_norm_plain_rows_tensor(out, x, n, 1, eps);
}

int ds4_gpu_rms_norm_plain_rows_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        uint32_t                n,
        uint32_t                rows,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n == 0 || rows == 0 || (n & 3u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t bytes = (uint64_t)n * rows * sizeof(float);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal plain RMS norm received undersized activation buffers\n");
            return 0;
        }

        ds4_gpu_rms_norm_args args = ds4_gpu_make_rms_norm_args(n, rows, eps);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_rms_norm_plain_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:3];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_threads(n), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "plain RMS norm")) return 0;
    }

    return 1;
}

static int ds4_gpu_hc_rms_scale_project_mode(
        uint32_t in_dim,
        uint32_t out_dim,
        uint32_t n_rows) {
    const bool hard_shape = n_rows > 8u &&
        (in_dim == 16384u || in_dim == 20480u || in_dim == 28672u) && out_dim == 24u;
    if (!hard_shape) return 0;
    if (in_dim == 20480u && n_rows < 512u) return 0;

    if ((in_dim != 20480u && !ds4_gpu_device_name_contains("M3") &&
         (g_test_flags & DS4_GPU_TEST_HC_RMS_SCALE_PROJ) == 0u) ||
        getenv("DS4_METAL_DISABLE_HC_RMS_SCALE_PROJ") != NULL) {
        return 0;
    }
    if (g_rms_norm_scale_pipeline == nil) {
        return 0;
    }
    return 1;
}

int ds4_gpu_hc_rms_scale_project_f16_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *scale_scratch,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                in_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *x,
        uint32_t                n_rows,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !scale_scratch || !model_map || !x ||
        in_dim == 0u || out_dim == 0u || n_rows == 0u ||
        n_rows > INT32_MAX) {
        return 0;
    }

    const int mode =
        ds4_gpu_hc_rms_scale_project_mode(in_dim, out_dim, n_rows);
    if (mode < 0) return 0;
    if (mode == 0) {
        return ds4_gpu_rms_norm_plain_rows_tensor(
                   scale_scratch, x, in_dim, n_rows, eps) != 0 &&
               ds4_gpu_matmul_f16_tensor(
                   out, model_map, model_size, weight_offset,
                   in_dim, out_dim, scale_scratch, n_rows) != 0;
    }

    @autoreleasepool {
        const uint64_t x_elems = (uint64_t)in_dim * n_rows;
        const uint64_t out_elems = (uint64_t)out_dim * n_rows;
        if (x_elems > UINT64_MAX / sizeof(float) ||
            out_elems > UINT64_MAX / sizeof(float)) {
            return 0;
        }
        const uint64_t x_bytes = x_elems * sizeof(float);
        const uint64_t out_bytes = out_elems * sizeof(float);
        const uint64_t scale_bytes = (uint64_t)n_rows * sizeof(float);

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> scalebuf = ds4_gpu_tensor_buffer(scale_scratch);
        if (!xbuf || !outbuf || !scalebuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(scale_scratch) < scale_bytes) {
            fprintf(stderr, "ds4: Metal HC RMS scale projection received undersized activation buffers\n");
            return 0;
        }

        const uint64_t weight_row_bytes = (uint64_t)in_dim * sizeof(uint16_t);
        if ((uint64_t)out_dim > UINT64_MAX / weight_row_bytes) return 0;
        const uint64_t weight_bytes = (uint64_t)out_dim * weight_row_bytes;
        if (weight_offset > model_size ||
            weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal HC RMS scale projection weight range is outside the mapped model\n");
            return 0;
        }

        const bool bc_inp = (in_dim % 32u) != 0u;
        const bool bc_out = (out_dim % 64u) != 0u ||
                            (n_rows % 32u) != 0u;
        id<MTLComputePipelineState> mm_pipeline =
            ds4_gpu_get_mul_mm_pipeline(
                "kernel_mul_mm_f16_f32_scaled", bc_inp, bc_out);
        if (!mm_pipeline) {
            return ds4_gpu_rms_norm_plain_rows_tensor(
                       scale_scratch, x, in_dim, n_rows, eps) != 0 &&
                   ds4_gpu_matmul_f16_tensor(
                       out, model_map, model_size, weight_offset,
                       in_dim, out_dim, scale_scratch, n_rows) != 0;
        }

        id<MTLComputePipelineState> scale_pipeline = ds4_gpu_hot_pipeline(
            g_rms_norm_scale_pipeline, "kernel_rms_norm_scale_f32_4");
        if (!scale_pipeline) return 0;

        uint64_t weight_inner = 0;
        id<MTLBuffer> weightbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, weight_offset, weight_bytes, &weight_inner);
        if (!weightbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_rms_norm_args norm_args =
            ds4_gpu_make_rms_norm_args(in_dim, n_rows, eps);
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:scale_pipeline];
        [enc setBytes:&norm_args length:sizeof(norm_args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:scalebuf
                offset:ds4_gpu_tensor_offset(scale_scratch)
               atIndex:2];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(
                 ds4_gpu_rms_norm_threads(in_dim), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        ds4_gpu_mul_mm_args mm_args = ds4_gpu_make_mm_args(
            in_dim, out_dim, n_rows, weight_row_bytes);
        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:mm_pipeline];
        [enc setBytes:&mm_args length:sizeof(mm_args) atIndex:0];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setBuffer:scalebuf
                offset:ds4_gpu_tensor_offset(scale_scratch)
               atIndex:4];
        [enc setThreadgroupMemoryLength:(bc_out ? 8192u : 6144u) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(
                                          ((NSUInteger)n_rows + 31u) / 32u,
                                          ((NSUInteger)out_dim + 63u) / 64u,
                                          1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "HC RMS scale F16 projection")) {
            return 0;
        }
    }

    return 1;
}

int ds4_gpu_rms_norm_weight_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                n,
        float                   eps) {
    return ds4_gpu_rms_norm_weight_rows_tensor(out, x, model_map, model_size, weight_offset, n, 1, eps);
}

int ds4_gpu_rms_norm_weight_rows_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                n,
        uint32_t                rows,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n == 0 || rows == 0 || (n & 3u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t row_bytes = (uint64_t)n * sizeof(float);
        const uint64_t bytes = row_bytes * rows;
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal weighted RMS norm received undersized activation buffers\n");
            return 0;
        }
        if (weight_offset > model_size || row_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal weighted RMS norm range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map,
                                                       model_size,
                                                       weight_offset,
                                                       row_bytes,
                                                       &inner_offset);
        if (!wbuf) return 0;

        ds4_gpu_rms_norm_args args = ds4_gpu_make_rms_norm_args(n, rows, eps);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        static id<MTLComputePipelineState> llms_nb;   /* llms MVB16: the norm with the BF16 rounding in its store */
        const bool llms_nbo = g_llms_t32_round && llms_mvb16(1) && !llms_alt_off("mvbn");
        if (llms_nbo && !llms_nb) llms_nb = ds4_gpu_get_pipeline("kernel_rms_norm_mul_f32_4_b");
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:(llms_nbo && llms_nb) ? llms_nb : g_rms_norm_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:2];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:3];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_threads(n), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (llms_nbo && llms_nb) { g_llms_t32_rounded = 1; g_llms_mvb_norm_calls++; }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "weighted RMS norm")) return 0;
    }

    return 1;
}

int ds4_gpu_add_rms_norm_weight_tensor(
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *sum_out,
        const ds4_gpu_tensor *a,
        const ds4_gpu_tensor *b,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                n,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!norm_out || !sum_out || !a || !b || n == 0 || (n & 3u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> abuf = ds4_gpu_tensor_buffer(a);
        id<MTLBuffer> bbuf = ds4_gpu_tensor_buffer(b);
        id<MTLBuffer> sumbuf = ds4_gpu_tensor_buffer(sum_out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        const uint64_t row_bytes = (uint64_t)n * sizeof(float);
        if (!abuf || !bbuf || !sumbuf || !normbuf ||
            ds4_gpu_tensor_bytes(a) < row_bytes ||
            ds4_gpu_tensor_bytes(b) < row_bytes ||
            ds4_gpu_tensor_bytes(sum_out) < row_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < row_bytes) {
            fprintf(stderr, "ds4: Metal add+RMS norm received undersized activation buffers\n");
            return 0;
        }
        if (weight_offset > model_size || row_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal add+RMS norm range is outside the mapped model\n");
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map,
                                                       model_size,
                                                       weight_offset,
                                                       row_bytes,
                                                       &inner_offset);
        if (!wbuf) return 0;

        ds4_gpu_rms_norm_args args = ds4_gpu_make_rms_norm_args(n, 1, eps);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_add_rms_norm_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:abuf offset:ds4_gpu_tensor_offset(a) atIndex:1];
        [enc setBuffer:bbuf offset:ds4_gpu_tensor_offset(b) atIndex:2];
        [enc setBuffer:wbuf offset:(NSUInteger)inner_offset atIndex:3];
        [enc setBuffer:sumbuf offset:ds4_gpu_tensor_offset(sum_out) atIndex:4];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:5];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_threads(n), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "add+RMS norm")) return 0;
    }

    return 1;
}

int ds4_gpu_dsv4_qkv_rms_norm_rows_tensor(
        ds4_gpu_tensor       *q_out,
        const ds4_gpu_tensor *q,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                q_weight_offset,
        uint32_t                q_n,
        ds4_gpu_tensor       *kv_out,
        const ds4_gpu_tensor *kv,
        uint64_t                kv_weight_offset,
        uint32_t                kv_n,
        uint32_t                rows,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!q_out || !q || !kv_out || !kv || q_n == 0 || kv_n == 0 || rows == 0 ||
        (q_n & 3u) != 0 || (kv_n & 3u) != 0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> qoutbuf = ds4_gpu_tensor_buffer(q_out);
        id<MTLBuffer> kvbuf = ds4_gpu_tensor_buffer(kv);
        id<MTLBuffer> kvoutbuf = ds4_gpu_tensor_buffer(kv_out);

        const uint64_t q_row_bytes = (uint64_t)q_n * sizeof(float);
        const uint64_t kv_row_bytes = (uint64_t)kv_n * sizeof(float);
        if (!qbuf || !qoutbuf || !kvbuf || !kvoutbuf ||
            ds4_gpu_tensor_bytes(q) < q_row_bytes * rows ||
            ds4_gpu_tensor_bytes(q_out) < q_row_bytes * rows ||
            ds4_gpu_tensor_bytes(kv) < kv_row_bytes * rows ||
            ds4_gpu_tensor_bytes(kv_out) < kv_row_bytes * rows) {
            fprintf(stderr, "ds4: Metal fused q/kv RMS norm received undersized activation buffers\n");
            return 0;
        }
        if (q_weight_offset > model_size || q_row_bytes > model_size - q_weight_offset ||
            kv_weight_offset > model_size || kv_row_bytes > model_size - kv_weight_offset) {
            fprintf(stderr, "ds4: Metal fused q/kv RMS norm weight range is outside the mapped model\n");
            return 0;
        }

        uint64_t q_inner_offset = 0;
        uint64_t kv_inner_offset = 0;
        id<MTLBuffer> q_wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                          q_weight_offset, q_row_bytes,
                                                          &q_inner_offset);
        if (!q_wbuf) return 0;
        id<MTLBuffer> kv_wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                           kv_weight_offset, kv_row_bytes,
                                                           &kv_inner_offset);
        if (!kv_wbuf) return 0;

        ds4_gpu_qkv_rms_norm_args args = {
            .q_n = (int32_t)q_n,
            .q_n4 = (int32_t)(q_n / 4u),
            .kv_n = (int32_t)kv_n,
            .kv_n4 = (int32_t)(kv_n / 4u),
            .q_row_stride = q_row_bytes,
            .kv_row_stride = kv_row_bytes,
            .eps = eps,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_qkv_rms_norm_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:q_wbuf offset:(NSUInteger)q_inner_offset atIndex:2];
        [enc setBuffer:qoutbuf offset:ds4_gpu_tensor_offset(q_out) atIndex:3];
        [enc setBuffer:kvbuf offset:ds4_gpu_tensor_offset(kv) atIndex:4];
        [enc setBuffer:kv_wbuf offset:(NSUInteger)kv_inner_offset atIndex:5];
        [enc setBuffer:kvoutbuf offset:ds4_gpu_tensor_offset(kv_out) atIndex:6];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(rows, 2, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_threads(q_n), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "fused q/kv RMS norm")) return 0;
    }

    return 1;
}

/* Decode-only triple fusion: q/kv RMS norm + KV RoPE tail + FP8/raw store.
 * Same arithmetic, order and rounding as the three separate dispatches (see
 * metal/norm.metal); gated and verified against full-vocabulary logits.
 * Returns 1 on success, 0 on unsupported shape (caller falls back). */
/* Deferred kv norm/RoPE/FP8 task: the q/kv norm dispatch runs its q task
 * only and the kv task is folded into the KV staging kernel of the same
 * layer (ds4_gpu_kv_norm_task_flush runs it standalone if no staging
 * consumed it). */
static struct {
    int pending;
    id<MTLBuffer> kv, kv_out, kv_w, q, q_out, q_w, raw;
    NSUInteger kv_off, kv_out_off, kv_w_off, q_off, q_out_off, q_w_off, raw_off;
    ds4_gpu_qkv_rms_norm_args nargs;
    ds4_gpu_rope_affine_pair_args rope;
    ds4_gpu_dsv4_kv_fp8_store_args store;
    NSUInteger norm_threads;
} g_kv_task;

static int g_qkv_norm_defer_kv;

void ds4_gpu_dsv4_qkv_norm_defer_kv_next(void) {
    g_qkv_norm_defer_kv = 1;
}

int ds4_gpu_kv_norm_task_pending(void) {
    return g_kv_task.pending;
}

/* Run a deferred kv task standalone (the full q/kv norm kernel; the q task
 * recomputes identical values).  Used when no KV staging consumed it. */
int ds4_gpu_kv_norm_task_flush(void) {
    if (!g_kv_task.pending) return 1;
    g_kv_task.pending = 0;
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    id<MTLComputePipelineState> pipeline =
        ds4_gpu_get_pipeline("kernel_dsv4_qkv_rms_norm_kv_rope_fp8_store_f32");
    if (!pipeline) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:&g_kv_task.nargs length:sizeof(g_kv_task.nargs) atIndex:0];
    [enc setBytes:&g_kv_task.rope length:sizeof(g_kv_task.rope) atIndex:1];
    [enc setBytes:&g_kv_task.store length:sizeof(g_kv_task.store) atIndex:2];
    [enc setBuffer:g_kv_task.q offset:g_kv_task.q_off atIndex:3];
    [enc setBuffer:g_kv_task.q_w offset:g_kv_task.q_w_off atIndex:4];
    [enc setBuffer:g_kv_task.q_out offset:g_kv_task.q_out_off atIndex:5];
    [enc setBuffer:g_kv_task.kv offset:g_kv_task.kv_off atIndex:6];
    [enc setBuffer:g_kv_task.kv_w offset:g_kv_task.kv_w_off atIndex:7];
    [enc setBuffer:g_kv_task.kv_out offset:g_kv_task.kv_out_off atIndex:8];
    [enc setBuffer:g_kv_task.raw offset:g_kv_task.raw_off atIndex:9];
    [enc setThreadgroupMemoryLength:(32u + 64u) * sizeof(float) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 2, 1)
         threadsPerThreadgroup:MTLSizeMake(g_kv_task.norm_threads, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return ds4_gpu_finish_command_buffer(cb, owned, "deferred kv norm task");
}

/* Run the deferred kv task in a concurrent encoder left open for the
 * caller's next dispatch (the q_b projection), so its ~9 us of serial work
 * hides under that stream.  End closes the section. */
int ds4_gpu_kv_norm_task_begin_concurrent(void) {
    if (!g_kv_task.pending || !g_batch_cb || g_batch_encoder_concurrent) return 0;
    id<MTLComputePipelineState> pipeline =
        ds4_gpu_get_pipeline("kernel_dsv4_qkv_rms_norm_kv_rope_fp8_store_f32");
    if (!pipeline) return 0;
    g_kv_task.pending = 0;
    ds4_gpu_close_batch_encoder();
    g_batch_encoder_concurrent = YES;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    if (!enc || enc.dispatchType != MTLDispatchTypeConcurrent) {
        ds4_gpu_close_batch_encoder();
        g_batch_encoder_concurrent = NO;
        g_kv_task.pending = 1;
        return 0;
    }
    [enc setComputePipelineState:pipeline];
    [enc setBytes:&g_kv_task.nargs length:sizeof(g_kv_task.nargs) atIndex:0];
    [enc setBytes:&g_kv_task.rope length:sizeof(g_kv_task.rope) atIndex:1];
    [enc setBytes:&g_kv_task.store length:sizeof(g_kv_task.store) atIndex:2];
    [enc setBuffer:g_kv_task.q offset:g_kv_task.q_off atIndex:3];
    [enc setBuffer:g_kv_task.q_w offset:g_kv_task.q_w_off atIndex:4];
    [enc setBuffer:g_kv_task.q_out offset:g_kv_task.q_out_off atIndex:5];
    [enc setBuffer:g_kv_task.kv offset:g_kv_task.kv_off atIndex:6];
    [enc setBuffer:g_kv_task.kv_w offset:g_kv_task.kv_w_off atIndex:7];
    [enc setBuffer:g_kv_task.kv_out offset:g_kv_task.kv_out_off atIndex:8];
    [enc setBuffer:g_kv_task.raw offset:g_kv_task.raw_off atIndex:9];
    [enc setThreadgroupMemoryLength:(32u + 64u) * sizeof(float) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 2, 1)
         threadsPerThreadgroup:MTLSizeMake(g_kv_task.norm_threads, 1, 1)];
    ds4_gpu_end_compute_encoder(g_batch_cb, enc);
    return 1;
}

void ds4_gpu_kv_norm_task_end_concurrent(void) {
    if (!g_batch_encoder_concurrent) return;
    ds4_gpu_close_batch_encoder();
    g_batch_encoder_concurrent = NO;
}

int ds4_gpu_dsv4_qkv_rms_norm_kv_rope_fp8_store_tensor(
        ds4_gpu_tensor       *q_out,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              q_weight_offset,
        uint32_t              q_n,
        ds4_gpu_tensor       *kv_out,
        const ds4_gpu_tensor *kv,
        uint64_t              kv_weight_offset,
        uint32_t              kv_n,
        ds4_gpu_tensor       *raw_cache,
        uint64_t              raw_cap,
        uint32_t              raw_row,
        uint32_t              n_rot,
        uint32_t              pos0,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        float                 eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!q_out || !q || !kv_out || !kv || !raw_cache ||
        q_n == 0 || kv_n == 0 || (q_n & 3u) != 0 || (kv_n & 3u) != 0 ||
        n_rot > kv_n || (n_rot & 1u) != 0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> qoutbuf = ds4_gpu_tensor_buffer(q_out);
        id<MTLBuffer> kvbuf = ds4_gpu_tensor_buffer(kv);
        id<MTLBuffer> kvoutbuf = ds4_gpu_tensor_buffer(kv_out);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_cache);

        const uint64_t q_row_bytes = (uint64_t)q_n * sizeof(float);
        const uint64_t kv_row_bytes = (uint64_t)kv_n * sizeof(float);
        const uint64_t raw_bytes = raw_cap * kv_row_bytes;
        if (!qbuf || !qoutbuf || !kvbuf || !kvoutbuf || !rawbuf ||
            ds4_gpu_tensor_bytes(q) < q_row_bytes ||
            ds4_gpu_tensor_bytes(q_out) < q_row_bytes ||
            ds4_gpu_tensor_bytes(kv) < kv_row_bytes ||
            ds4_gpu_tensor_bytes(kv_out) < kv_row_bytes ||
            ds4_gpu_tensor_bytes(raw_cache) < raw_bytes ||
            (uint64_t)raw_row >= raw_cap) {
            fprintf(stderr, "ds4: Metal fused q/kv norm RoPE store received undersized buffers\n");
            return 0;
        }
        if (q_weight_offset > model_size || q_row_bytes > model_size - q_weight_offset ||
            kv_weight_offset > model_size || kv_row_bytes > model_size - kv_weight_offset) {
            fprintf(stderr, "ds4: Metal fused q/kv norm RoPE store weight range is outside the mapped model\n");
            return 0;
        }

        uint64_t q_inner_offset = 0;
        uint64_t kv_inner_offset = 0;
        id<MTLBuffer> q_wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                          q_weight_offset, q_row_bytes,
                                                          &q_inner_offset);
        if (!q_wbuf) return 0;
        id<MTLBuffer> kv_wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                           kv_weight_offset, kv_row_bytes,
                                                           &kv_inner_offset);
        if (!kv_wbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_pipeline("kernel_dsv4_qkv_rms_norm_kv_rope_fp8_store_f32");
        if (!pipeline) return 0;

        ds4_gpu_qkv_rms_norm_args args = {
            .q_n = (int32_t)q_n,
            .q_n4 = (int32_t)(q_n / 4u),
            .kv_n = (int32_t)kv_n,
            .kv_n4 = (int32_t)(kv_n / 4u),
            .q_row_stride = q_row_bytes,
            .kv_row_stride = kv_row_bytes,
            .eps = eps,
        };
        ds4_gpu_rope_affine_pair_args rope = {
            .row_bytes = kv_row_bytes,
            .token_bytes = kv_row_bytes,
            .head_dim = (int32_t)kv_n,
            .n_dims = (int32_t)n_rot,
            .n_ctx_orig = (int32_t)n_ctx_orig,
            .inverse = 0,
            .pos0 = pos0,
            .pos_step = 1,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };
        ds4_gpu_dsv4_kv_fp8_store_args store = {
            .head_dim = (int32_t)kv_n,
            .n_rot = (int32_t)n_rot,
            .raw_row = (int32_t)raw_row,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBytes:&rope length:sizeof(rope) atIndex:1];
        [enc setBytes:&store length:sizeof(store) atIndex:2];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:3];
        [enc setBuffer:q_wbuf offset:(NSUInteger)q_inner_offset atIndex:4];
        [enc setBuffer:qoutbuf offset:ds4_gpu_tensor_offset(q_out) atIndex:5];
        [enc setBuffer:kvbuf offset:ds4_gpu_tensor_offset(kv) atIndex:6];
        [enc setBuffer:kv_wbuf offset:(NSUInteger)kv_inner_offset atIndex:7];
        [enc setBuffer:kvoutbuf offset:ds4_gpu_tensor_offset(kv_out) atIndex:8];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_cache) atIndex:9];
        [enc setThreadgroupMemoryLength:(32u + 64u) * sizeof(float) atIndex:0];
        const NSUInteger norm_threads = ds4_gpu_rms_norm_threads(q_n);
        const bool defer_kv = g_qkv_norm_defer_kv && !g_kv_task.pending;
        g_qkv_norm_defer_kv = 0;
        if (defer_kv) {
            args.tasks = 1u;   /* q task now; kv task later, concurrently with q_b */
            [enc setBytes:&args length:sizeof(args) atIndex:0];
        }
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, defer_kv ? 1 : 2, 1)
             threadsPerThreadgroup:MTLSizeMake(norm_threads, 1, 1)];
        if (defer_kv) {
            g_kv_task.pending = 1;
            g_kv_task.kv = kvbuf; g_kv_task.kv_off = ds4_gpu_tensor_offset(kv);
            g_kv_task.kv_out = kvoutbuf; g_kv_task.kv_out_off = ds4_gpu_tensor_offset(kv_out);
            g_kv_task.kv_w = kv_wbuf; g_kv_task.kv_w_off = (NSUInteger)kv_inner_offset;
            g_kv_task.q = qbuf; g_kv_task.q_off = ds4_gpu_tensor_offset(q);
            g_kv_task.q_out = qoutbuf; g_kv_task.q_out_off = ds4_gpu_tensor_offset(q_out);
            g_kv_task.q_w = q_wbuf; g_kv_task.q_w_off = (NSUInteger)q_inner_offset;
            g_kv_task.raw = rawbuf; g_kv_task.raw_off = ds4_gpu_tensor_offset(raw_cache);
            g_kv_task.nargs = args;
            g_kv_task.nargs.tasks = 2u;   /* kv task only */
            g_kv_task.rope = rope;
            g_kv_task.store = store;
            g_kv_task.norm_threads = norm_threads;
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "fused q/kv norm RoPE store")) return 0;
    }

    return 1;
}

int ds4_gpu_head_rms_norm_tensor(
        ds4_gpu_tensor *x,
        uint32_t          n_tok,
        uint32_t          n_head,
        uint32_t          head_dim,
        float             eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || n_tok == 0 || n_head == 0 || head_dim == 0 || (head_dim & 3u) != 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        const uint64_t bytes = (uint64_t)n_tok * n_head * head_dim * sizeof(float);
        if (!xbuf || ds4_gpu_tensor_bytes(x) < bytes) {
            fprintf(stderr, "ds4: Metal head RMS norm received undersized activation buffer\n");
            return 0;
        }

        ds4_gpu_rms_norm_args args = ds4_gpu_make_rms_norm_3d_args(head_dim, n_head, n_tok, eps);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_rms_norm_plain_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:2];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:4];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_head, n_tok, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_pipeline_threads(head_dim, g_rms_norm_plain_pipeline), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "head RMS norm")) return 0;
    }

    return 1;
}

int ds4_gpu_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t          n_tok,
        uint32_t          n_head,
        uint32_t          head_dim,
        uint32_t          n_rot,
        uint32_t          pos0,
        uint32_t          n_ctx_orig,
        bool              inverse,
        float             freq_base,
        float             freq_scale,
        float             ext_factor,
        float             attn_factor,
        float             beta_fast,
        float             beta_slow) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || n_tok == 0 || n_head == 0 || head_dim == 0 || n_rot > head_dim || (n_rot & 1u) != 0) {
        return 0;
    }
    if (n_rot == 0) return 1;

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        const uint64_t bytes = (uint64_t)n_tok * n_head * head_dim * sizeof(float);
        if (!xbuf || ds4_gpu_tensor_bytes(x) < bytes) {
            fprintf(stderr, "ds4: Metal RoPE received undersized activation buffer\n");
            return 0;
        }

        ds4_gpu_rope_tail_batch_args args = ds4_gpu_make_rope_tail_args(
            n_tok, n_head, head_dim, n_rot, n_ctx_orig, inverse,
            freq_base, freq_scale, ext_factor, attn_factor, beta_fast, beta_slow);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_rope_tail_inplace(cb,
                                                xbuf,
                                                ds4_gpu_tensor_offset(x),
                                                &args,
                                                n_tok,
                                                n_head,
                                                head_dim,
                                                pos0,
                                                1)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "RoPE tail")) return 0;
    }

    return 1;
}

int ds4_gpu_head_rms_norm_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t          n_tok,
        uint32_t          n_head,
        uint32_t          head_dim,
        uint32_t          n_rot,
        uint32_t          pos0,
        uint32_t          n_ctx_orig,
        bool              inverse,
        float             freq_base,
        float             freq_scale,
        float             ext_factor,
        float             attn_factor,
        float             beta_fast,
        float             beta_slow,
        float             eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || n_tok == 0u || n_head == 0u || head_dim == 0u ||
        (head_dim & 3u) != 0u || n_rot > head_dim ||
        pos0 > (uint32_t)INT32_MAX - n_tok) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        const uint64_t bytes =
            (uint64_t)n_tok * n_head * head_dim * sizeof(float);
        if (!xbuf || ds4_gpu_tensor_bytes(x) < bytes) {
            fprintf(stderr,
                    "ds4: Metal fused head norm/RoPE received undersized activation buffer\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            g_use_dsv4_head_rms_norm_rope_tail_pipeline
            ? g_dsv4_head_rms_norm_rope_tail_pipeline
            : ds4_gpu_get_pipeline(
                  "kernel_dsv4_head_rms_norm_rope_tail_f32");
        if (!pipeline) return 0;

        struct {
            int32_t n_head;
            int32_t head_dim;
            int32_t head_dim4;
            int32_t n_dims;
            int32_t n_ctx_orig;
            int32_t pos0;
            int32_t inverse;
            float eps;
            float freq_base;
            float freq_scale;
            float ext_factor;
            float attn_factor;
            float beta_fast;
            float beta_slow;
        } args = {
            .n_head = (int32_t)n_head,
            .head_dim = (int32_t)head_dim,
            .head_dim4 = (int32_t)(head_dim / 4u),
            .n_dims = (int32_t)n_rot,
            .n_ctx_orig = (int32_t)n_ctx_orig,
            .pos0 = (int32_t)pos0,
            .inverse = inverse ? 1 : 0,
            .eps = eps,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_head, n_tok, 1)
             threadsPerThreadgroup:MTLSizeMake(
                 ds4_gpu_rms_norm_pipeline_threads(head_dim, pipeline),
                 1,
                 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "fused head norm/RoPE")) {
            return 0;
        }
    }

    return 1;
}

