                    ds4_gpu_end_compute_encoder(cb, enc);
                    g_llms_t8_calls++;
                } else if (llms_mt) {
                    const NSUInteger llms_mt_rows = llms_mt8 ? 8u : (NSUInteger)args.nr0;
                    const NSUInteger llms_mt_grid_rows = llms_mt8 && getenv("LLMS_DS4_ATTN_OUT_MT8_CANARY") ? 16u : llms_mt_rows;
                    const NSUInteger row_groups = ((NSUInteger)args.ne01 + llms_mt_grid_rows - 1u) / llms_mt_grid_rows;
                    for (uint32_t llms_q = 0; llms_q < n_tokens / 4u; llms_q++) {   /* llms ATTN_OUT_MT quads: four tokens per pass */
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:llms_mt];
                    [enc setBytes:&args length:sizeof(args) atIndex:0];
                    [enc setBuffer:out_a_buf offset:(NSUInteger)out_a_inner atIndex:1];
                    [enc setBuffer:ds4_gpu_tensor_buffer(heads) offset:ds4_gpu_tensor_offset(heads) + (NSUInteger)((uint64_t)llms_q * 4u * args.nb12) atIndex:2];
                    [enc setBuffer:ds4_gpu_tensor_buffer(low) offset:ds4_gpu_tensor_offset(low) + (NSUInteger)((uint64_t)llms_q * 4u * (uint64_t)args.ne1 * (uint64_t)args.ne0 * sizeof(float)) atIndex:3];
                    [enc setThreadgroupMemoryLength:32u * llms_mt_rows * sizeof(float) atIndex:0];
                    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(row_groups, 1, n_groups) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    g_llms_attn_out_mt_calls++;
                    }
                } else
                ok = ds4_gpu_encode_attn_out_low_q8_direct(cb,
                                                             pipeline,
                                                             &args,
                                                             out_a_buf,
                                                             (NSUInteger)out_a_inner,
                                                             ds4_gpu_tensor_buffer(heads),
                                                             ds4_gpu_tensor_offset(heads),
                                                             ds4_gpu_tensor_buffer(low),
                                                             ds4_gpu_tensor_offset(low),
                                                             32u * 2u * sizeof(float),
                                                             4,
                                                             true) != 0;
            } else {
                ds4_gpu_mul_mv_id_args args = {
                    .nei0 = (int32_t)n_groups,
                    .nei1 = (int32_t)n_tokens,
                    .nbi1 = (uint64_t)n_groups * sizeof(int32_t),
                    .ne00 = (int32_t)group_dim,
                    .ne01 = (int32_t)rank,
                    .ne02 = (int32_t)n_groups,
                    .nb00 = 34,
                    .nb01 = row_a_bytes,
                    .nb02 = (uint64_t)rank * row_a_bytes,
                    .ne10 = (int32_t)group_dim,
                    .ne11 = (int32_t)n_groups,
                    .ne12 = (int32_t)n_tokens,
                    .ne13 = 1,
                    .nb10 = sizeof(float),
                    .nb11 = (uint64_t)group_dim * sizeof(float),
                    .nb12 = (uint64_t)n_groups * group_dim * sizeof(float),
                    .ne0 = (int32_t)rank,
                    .ne1 = (int32_t)n_groups,
                    .nb1 = (uint64_t)rank * sizeof(float),
                    .nr0 = 2,
                };
                id<MTLComputePipelineState> pipeline =
                    ds4_gpu_get_mul_mv_pipeline("kernel_mul_mv_id_q8_0_f32", 4);
                ok = ds4_gpu_encode_mul_mv_id(cb,
                                                pipeline,
                                                &args,
                                                out_a_buf,
                                                (NSUInteger)out_a_inner,
                                                ds4_gpu_tensor_buffer(heads),
                                                ds4_gpu_tensor_offset(heads),
                                                ds4_gpu_tensor_buffer(low),
                                                ds4_gpu_tensor_offset(low),
                                                group_ids_buffer,
                                                0,
                                                32u * 2u * sizeof(float),
                                                4,
                                                true) != 0;
            }
        }
        DS4_METAL_PROFILE_ATTN_OUT_STAGE("low_proj");

        if (ok && round_low_bf16)
            ok = ds4_gpu_dsv41_quantize(low, (uint32_t)low_dim, n_tokens, DS4_V41_BF16);
        if (ok && full_low_dim != low_dim) {
            const uint32_t matrix_rows = ds4_gpu_mpp_available() ? n_tokens / 32u * 32u : 0;
            if (matrix_rows) {
                ok = ds4_gpu_matmul_q8_0_kslice_rows_impl(out, model_map, model_size,
                    out_b_offset, full_low_dim, out_dim, low_offset, low_dim,
                    low, matrix_rows, low_dim, 0) != 0;
            }
            for (uint32_t t = matrix_rows; ok && t < n_tokens; t++) {
                ds4_gpu_tensor *row = ds4_gpu_tensor_view(out,
                    (uint64_t)t * out_dim * sizeof(float), out_dim * sizeof(float));
                ok = row && ds4_gpu_matmul_q8_0_kslice_tensor(row, model_map, model_size,
                    out_b_offset, full_low_dim, low_offset, low_dim, out_dim,
                    low, (uint64_t)t * low_dim);
                ds4_gpu_tensor_free(row);
            }
        } else if (ok && round_low_bf16 && n_tokens <= 8u) {
            ok = ds4_gpu_matmul_q8_0_decode_rows_exact_tensor(out, model_map, model_size,
                out_b_offset, low_dim, out_dim, low, n_tokens) != 0;
        } else if (ok) {
            ok = ds4_gpu_matmul_q8_0_tensor(out, model_map, model_size,
                                              out_b_offset,
                                              low_dim, out_dim, low, n_tokens) != 0;
        }
        DS4_METAL_PROFILE_ATTN_OUT_STAGE("out_proj");

        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
#undef DS4_METAL_PROFILE_ATTN_OUT_STAGE
        return ok ? 1 : 0;
    }
}

int ds4_gpu_attention_output_q8_batch_tensor(
        ds4_gpu_tensor *out, ds4_gpu_tensor *low,
        ds4_gpu_tensor *group_tmp, ds4_gpu_tensor *low_tmp,
        const void *model_map, uint64_t model_size,
        uint64_t out_a_offset, uint64_t out_b_offset,
        uint64_t group_dim, uint64_t rank, uint32_t n_groups, uint64_t out_dim,
        const ds4_gpu_tensor *heads, uint32_t n_tokens) {
    return ds4_gpu_attention_output_q8_batch_impl(out, low, group_tmp, low_tmp,
        model_map, model_size, out_a_offset, out_b_offset, group_dim, rank,
        n_groups, out_dim, heads, n_tokens, false, 0, 0);
}


int ds4_gpu_llms_attn_out_k(ds4_gpu_tensor *out, ds4_gpu_tensor *low, uint64_t out_a_offset, uint64_t out_b_offset, const ds4_gpu_tensor *heads, uint32_t rows) {
    static uint64_t calls; static int once;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (rows < 2u || rows > 4u || llms_alt_off("q4lkg")) return 0;
    if (g_llms_q4l_n < 0) llms_q4l_init();
    const llms_q4l_ent *ea = g_llms_q4l_n > 0 ? llms_q4l_find(out_a_offset) : NULL, *eb = g_llms_q4l_n > 0 ? llms_q4l_find(out_b_offset) : NULL;
    if (!ea || !eb || llms_alt_off(ea->alt) || llms_alt_off(eb->alt)) return 0;
    if (ea->k != 4096u || ea->n != 8u * 1024u || eb->k != 8192u || eb->n != 5120u) return 0;
    if ((ds4_gpu_tensor_offset(heads) & 15u) || (ds4_gpu_tensor_offset(low) & 15u)) return 0;
    int nrb = rows <= 3u ? 8 : 4;
    char nb[64]; snprintf(nb, sizeof nb, "kernel_llms_q4l_mv_k%u_r%d_f", rows, nrb);
    char na[64]; snprintf(na, sizeof na, "kernel_llms_q4l_mv_kg%u", rows);
    if (llms_f2(2, true)) { strlcat(nb, "_f2", sizeof nb); strlcat(na, "_f2", sizeof na); }   /* llms F2_AO (apply_q4l_f2_ao.py) */
    /* Offset representation is exact for this owner's fixed 8192x5120 packed
     * projection: the referenced span is 23,592,960 bytes, below 2^32.
     * Experimental OFF32 switch: remove after adoption/refutation. */
    static int off32_mode = -1;
    static uint64_t off32_calls;
    if (off32_mode < 0) {
        const char *e = getenv("LLMS_DS4_Q4L_OFF32");
        off32_mode = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? 2 : 1;
        if (off32_mode) atexit_b(^{ fprintf(stderr, "llms q4l off32: %llu attention projections\n", (unsigned long long)off32_calls); });
    }
    const int use_off32 = rows == 4u && off32_mode &&
        !strcmp(nb, "kernel_llms_q4l_mv_k4_r4_f") && !llms_alt_off("off32") ? off32_mode : 0;
    if (use_off32) { nrb = 8; strlcpy(nb, "kernel_astra_q4l_off32_f", sizeof nb); }
    static int hxo = -1; static uint64_t hxo_ao; if (hxo < 0) { const char *e = getenv("LLMS_DS4_Q4L_HXO"); hxo = e && *e && *e != '0';   /* llms Q4L_HXO (apply_hxo2.py): output_b on half low */
                                                             if (hxo) atexit_b(^{ fprintf(stderr, "llms q4l hxo: %llu attention output_b on half x\n", (unsigned long long)hxo_ao); }); }
    const int use_hxo = hxo && (rows == 2u || (rows == 3u && llms_k3x())) && !use_off32 && (!strcmp(nb, "kernel_llms_q4l_mv_k2_r8_f") || !strcmp(nb, "kernel_llms_q4l_mv_k3_r8_f")) && !llms_alt_off("hxo");   /* llms K3X */
    if (use_hxo) strlcat(nb, "xh", sizeof nb);
    static id<MTLComputePipelineState> hcp; static id<MTLBuffer> hring[8]; static unsigned hslot;
    if (use_hxo && !hcp) hcp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
    if (use_hxo && !hring[0]) for (int i = 0; i < 8; ++i) hring[i] = [g_device newBufferWithLength:4u * 8192u * 2u options:MTLResourceStorageModePrivate];   /* llms K3X: 4 rows */
    static int kgx = -1; static uint64_t kgx_n; if (kgx < 0) { const char *e = getenv("LLMS_DS4_Q4L_KGX"); kgx = e && *e && *e != '0' ? (*e == '2' ? 2 : 1) : 0;   /* llms Q4L_KGX (apply_kgx.py) */
                                                              if (kgx) { fprintf(stderr, "llms: q4l kgx (the grouped output_a on half heads)%s\n", kgx == 2 ? " -- CANARY: the f16 copy skipped" : "");
                                                                         atexit_b(^{ fprintf(stderr, "llms q4l kgx: %llu grouped output_a on half heads\n", (unsigned long long)kgx_n); }); } }
    const int use_kgx = kgx && (rows == 2u || (rows == 3u && llms_k3x())) && !llms_alt_off("kgx") && (!strcmp(na, "kernel_llms_q4l_mv_kg2") || !strcmp(na, "kernel_llms_q4l_mv_kg3"));   /* llms K3X */
    if (use_kgx) snprintf(na, sizeof na, "kernel_llms_q4l_mv_kgxh%u", rows);
    static id<MTLComputePipelineState> kgx_cp; static id<MTLBuffer> kgx_ring[8]; static unsigned kgx_slot;
    if (use_kgx && !kgx_cp) kgx_cp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_f32_to_f16_rows", 1);
    if (use_kgx && !kgx_ring[0]) for (int i = 0; i < 8; ++i) kgx_ring[i] = [g_device newBufferWithLength:4u * 8u * 4096u * 2u options:MTLResourceStorageModePrivate];   /* llms K3X: 4 rows */
    if (use_kgx && !kgx_cp) return 0;
    id<MTLComputePipelineState> pa = ds4_gpu_get_mul_mv_pipeline(na, strstr(na, "kgxh") ? llms_lean2_nsg(2) : 2), pb = ds4_gpu_get_mul_mv_pipeline(nb, strstr(nb, "xh") ? llms_lean2_nsg(2) : 2);   /* llms Q4L_LEAN2 */
    if (!pa || !pb || (use_hxo && !hcp)) return 0;
    if (!once++) atexit_b(^{ fprintf(stderr, "llms q4l kg: %llu batched attention outputs on the 4-bit copies\n", (unsigned long long)calls); });
    ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(4096, 1024);
    qa.nb00 = 1; qa.nb01 = 4096u / 16u * 9u; qa.nb02 = qa.nb01 * 1024u; qa.nb03 = qa.nb02; qa.nr0 = 4;
    qa.nb11 = 4096u * sizeof(float); qa.nb12 = 8u * 4096u * sizeof(float); qa.nb13 = 8u * 1024u * sizeof(float);   /* group stride; row strides in and out */
    ds4_gpu_q8_0_matvec_args qb = ds4_gpu_make_q8_0_mv_args(8192, 5120);
    qb.nb00 = 1; qb.nb01 = 8192u / 16u * 9u; qb.nb02 = qb.nb01 * 5120u; qb.nb03 = qb.nb02; qb.nr0 = nrb;
    if (use_off32 == 2) qb.nb11 = 0; /* diagnostic wrong-token-stride canary */
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    id<MTLBuffer> kgx_h = nil;
    if (use_kgx) {   /* llms Q4L_KGX: heads (2 x 8 x 4096 floats) -> half */
        kgx_h = kgx_ring[kgx_slot++ & 7u];
        if (kgx != 2) {
            uint32_t cv[3] = { rows * 8u * 4096u / 4u, rows * 8u * 4096u / 4u, 1u };   /* llms K3X: every row's heads (10-19: the 2-row wiring gave ppl 414 at 3 rows) */
            [enc setComputePipelineState:kgx_cp];
            [enc setBuffer:ds4_gpu_tensor_buffer(heads) offset:ds4_gpu_tensor_offset(heads) atIndex:0];
            [enc setBuffer:kgx_h offset:0 atIndex:1];
            [enc setBytes:cv length:sizeof cv atIndex:2];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            if (llms_hxdup()) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; g_llms_hxdup_n++; }
            if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        }
        qa.nb11 = 4096u * 2u; qa.nb12 = 8u * 4096u * 2u; kgx_n++;
    }
    const llms_q4i_ent *q4i_oa = (rows == 2u && use_kgx && kgx != 2 && llms_q4i_on() && (g_llms_q4i_hooks & 2) && !llms_alt_off("q4i")) ? llms_q4i_find(out_a_offset) : NULL;   /* llms Q4I */
    if (q4i_oa && q4i_oa->gr == 1024u && q4i_oa->k == 4096u && q4i_oa->n == 8192u) {
        llms_q4i_dispatch(enc, q4i_oa, kgx_h, 0, 8u * 4096u, ds4_gpu_tensor_buffer(low), ds4_gpu_tensor_offset(low), 1u);   /* kgxh2 rounds (RB true) */
        g_llms_q4i_c2++;
    } else {
        [enc setComputePipelineState:pa];
        [enc setBytes:&qa length:sizeof(qa) atIndex:0];
        [enc setBuffer:ea->buf offset:(NSUInteger)ea->inner atIndex:1];
        if (use_kgx) [enc setBuffer:kgx_h offset:0 atIndex:2]; else [enc setBuffer:ds4_gpu_tensor_buffer(heads) offset:ds4_gpu_tensor_offset(heads) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(low) offset:ds4_gpu_tensor_offset(low) atIndex:3];
        [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1024u / 4u, 1, 8) threadsPerThreadgroup:MTLSizeMake(32, 2, 1)];
        if (llms_ddup() && rows == 2u) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1024u / 4u, 1, 8) threadsPerThreadgroup:MTLSizeMake(32, 2, 1)]; g_llms_ddup_n++; }   /* llms DENSE_DUP */
    }
    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
    id<MTLBuffer> hlow = nil;
    if (use_hxo) {   /* llms Q4L_HXO: low (2 x 8192 floats) -> half, as the HX copy does */
        hlow = hring[hslot++ & 7u];
        uint32_t cv[3] = { 8192u / 4u, 8192u / 4u, rows };   /* llms K3X: every row's low */
        [enc setComputePipelineState:hcp];
        [enc setBuffer:ds4_gpu_tensor_buffer(low) offset:ds4_gpu_tensor_offset(low) atIndex:0];
        [enc setBuffer:hlow offset:0 atIndex:1];
        [enc setBytes:cv length:sizeof cv atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        if (llms_hxdup()) { [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)cv[0] * cv[2] + 255u) / 256u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; g_llms_hxdup_n++; }
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        hxo_ao++;
    }
    [enc setComputePipelineState:pb];
    [enc setBytes:&qb length:sizeof(qb) atIndex:0];
    [enc setBuffer:eb->buf offset:(NSUInteger)eb->inner atIndex:1];
    if (use_hxo) [enc setBuffer:hlow offset:0 atIndex:2]; else [enc setBuffer:ds4_gpu_tensor_buffer(low) offset:ds4_gpu_tensor_offset(low) atIndex:2];
    [enc setBuffer:ds4_gpu_tensor_buffer(out) offset:ds4_gpu_tensor_offset(out) atIndex:3];
    [enc setThreadgroupMemoryLength:(NSUInteger)nrb * 32u * sizeof(float) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((5120u + (NSUInteger)nrb - 1u) / (NSUInteger)nrb, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 2, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    calls++;
    if (use_off32) off32_calls++;
    return ds4_gpu_finish_command_buffer(cb, owned, "llms q4l kg attention output");
}
/* llms AO_G64 (apply_ao_g64.py): the attention output of 8-64-row prefill steps as 64-token MMA passes on the 4-bit copies */
int ds4_gpu_llms_attn_out_g64(ds4_gpu_tensor *out, ds4_gpu_tensor *low, uint64_t out_a_offset, uint64_t out_b_offset, const ds4_gpu_tensor *heads, uint32_t rows) {
    static id<MTLComputePipelineState> p; static int tried; static uint64_t calls, passes;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (rows < 8u || llms_alt_off("aog64")) return 0;
    if (!tried) { tried = 1; p = ds4_gpu_get_pipeline("kernel_llms_q4g64s"); { const char *pe = getenv("LLMS_DS4_Q4G_PF"); if (pe && *pe && *pe != '0') g_llms_q4spf_p = ds4_gpu_get_pipeline(llms_q4hpf() ? "kernel_llms_q4g64shpf" : "kernel_llms_q4g64spf"); }
                  fprintf(stderr, "llms: ao g64 %s (prefill attention output as 64-token MMA passes; rounding class)\n", p ? "on" : "MISSING -- off");
                  if (p) atexit_b(^{ fprintf(stderr, "llms ao g64: %llu attention outputs in %llu 64-token passes\n", (unsigned long long)calls, (unsigned long long)passes); }); }
    if (!p) return 0;
    static int aogk = -1; static id<MTLComputePipelineState> aogk_p[8]; static id<MTLBuffer> aogk_part, aogk_cnt; static unsigned aogk_r; static uint64_t aogk_n;
    if (aogk < 0) { const char *e = getenv("LLMS_DS4_AOG_KSA"); aogk = e && *e && *e != '0';
                    if (aogk) { int ok = 1; for (int i = 0; i < 8; i++) { char nm[64]; snprintf(nm, sizeof nm, llms_q4pf3() ? ((llms_q4hpf() && llms_q4pf3() != 2) ? "kernel_llms_q4g64s_ksahpf_nt%d" : "kernel_llms_q4g64s_ksapf_nt%d") : "kernel_llms_q4g64s_ksa_nt%d", i + 1); aogk_p[i] = ds4_gpu_get_pipeline(nm); if (!aogk_p[i]) ok = 0; }
                                if (ok) { aogk_part = [g_device newBufferWithLength:8u * 2u * 64u * 1024u * sizeof(float) options:MTLResourceStorageModePrivate];
                                          aogk_cnt = [g_device newBufferWithLength:64u * 4096u options:MTLResourceStorageModeShared]; if (aogk_cnt) memset(aogk_cnt.contents, 0, 64u * 4096u); }
                                aogk = ok && aogk_part && aogk_cnt;
                                fprintf(stderr, "llms: aog ksa %s (attention output chunks of < 64 tokens: a ceil(C / 8)-token tile, the atomic K-split at S 2; ALT aogk off -> the original)\n", aogk ? "on" : "MISSING -- off"); if (!aogk) llms_guard_fail(LLMS_G_MISS);
                                if (aogk) atexit_b(^{ fprintf(stderr, "llms aog ksa: %llu bounded chunks\n", (unsigned long long)aogk_n); }); } }
    if (g_llms_q4l_n < 0) llms_q4l_init();
    const llms_q4l_ent *ea = g_llms_q4l_n > 0 ? llms_q4l_find(out_a_offset) : NULL, *eb = g_llms_q4l_n > 0 ? llms_q4l_find(out_b_offset) : NULL;
    if (!ea || !eb || llms_alt_off(ea->alt) || llms_alt_off(eb->alt)) return 0;
    if (ea->k != 4096u || ea->n != 8u * 1024u || eb->k != 8192u || eb->n != 5120u) return 0;
    id<MTLBuffer> hb = ds4_gpu_tensor_buffer(heads), lb = ds4_gpu_tensor_buffer(low), ob = ds4_gpu_tensor_buffer(out);
    if (!hb || !lb || !ob) return 0;
    int owned = 0;
    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
    if (!cb) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:llms_q4spf_pick(p)];
    [enc setThreadgroupMemoryLength:64u * 64u * sizeof(float) atIndex:0];
    for (uint32_t c0 = 0; c0 < rows; c0 += 64u) {
        const int C = (int)(rows - c0 < 64u ? rows - c0 : 64u);
        if (aogk && C < 64 && !llms_alt_off("aogk")) {   /* llms AOG_KSA: the bounded tile + the atomic split, both projections */
            const int NT = (C + 7) / 8, S = 2;
            struct { int K, R, C, rb, S, xs, xg, ds; uint64_t wg; } A2 = { 4096, 1024, C, 1, S, 32768, 4096, 8192, (uint64_t)1024u * 2304u }; if (llms_ksa_canary()) A2.rb |= 2;
            [enc setComputePipelineState:aogk_p[NT - 1]]; [enc setThreadgroupMemoryLength:64u * 64u * sizeof(float) + 16u atIndex:0];
            [enc setBytes:&A2 length:sizeof A2 atIndex:0];
            [enc setBuffer:ea->buf offset:(NSUInteger)ea->inner atIndex:1];
            [enc setBuffer:hb offset:ds4_gpu_tensor_offset(heads) + (NSUInteger)c0 * 32768u * sizeof(float) atIndex:2];
            [enc setBuffer:lb offset:ds4_gpu_tensor_offset(low) + (NSUInteger)c0 * 8192u * sizeof(float) atIndex:3];
            [enc setBuffer:aogk_part offset:0 atIndex:4]; [enc setBuffer:aogk_cnt offset:(NSUInteger)((aogk_r++ & 63u) * 4096u) atIndex:5];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1024u / 64u, (NSUInteger)S, 8) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
            struct { int K, R, C, rb, S, xs, xg, ds; uint64_t wg; } B2 = { 8192, 5120, C, 0, S, 8192, 0, 5120, 0 }; if (llms_ksa_canary()) B2.rb |= 2;
            [enc setBytes:&B2 length:sizeof B2 atIndex:0];
            [enc setBuffer:eb->buf offset:(NSUInteger)eb->inner atIndex:1];
            [enc setBuffer:lb offset:ds4_gpu_tensor_offset(low) + (NSUInteger)c0 * 8192u * sizeof(float) atIndex:2];
            [enc setBuffer:ob offset:ds4_gpu_tensor_offset(out) + (NSUInteger)c0 * 5120u * sizeof(float) atIndex:3];
            [enc setBuffer:aogk_cnt offset:(NSUInteger)((aogk_r++ & 63u) * 4096u) atIndex:5];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(5120u / 64u, (NSUInteger)S, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
            if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
            [enc setComputePipelineState:llms_q4spf_pick(p)]; [enc setThreadgroupMemoryLength:64u * 64u * sizeof(float) atIndex:0];
            passes++; aogk_n++; continue;
        }
        struct { int K, R, C, rb, xs, xg, ds, pad; uint64_t wg; } A = { 4096, 1024, C, 1, 32768, 4096, 8192, 0, (uint64_t)1024u * 2304u };
        [enc setBytes:&A length:sizeof A atIndex:0];
        [enc setBuffer:ea->buf offset:(NSUInteger)ea->inner atIndex:1];
        [enc setBuffer:hb offset:ds4_gpu_tensor_offset(heads) + (NSUInteger)c0 * 32768u * sizeof(float) atIndex:2];
        [enc setBuffer:lb offset:ds4_gpu_tensor_offset(low) + (NSUInteger)c0 * 8192u * sizeof(float) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1024u / 64u, 1, 8) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        struct { int K, R, C, rb, xs, xg, ds, pad; uint64_t wg; } B = { 8192, 5120, C, 0, 8192, 0, 5120, 0, 0 };
        [enc setBytes:&B length:sizeof B atIndex:0];
        [enc setBuffer:eb->buf offset:(NSUInteger)eb->inner atIndex:1];
        [enc setBuffer:lb offset:ds4_gpu_tensor_offset(low) + (NSUInteger)c0 * 8192u * sizeof(float) atIndex:2];
        [enc setBuffer:ob offset:ds4_gpu_tensor_offset(out) + (NSUInteger)c0 * 5120u * sizeof(float) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(5120u / 64u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        passes++;
    }
    ds4_gpu_end_compute_encoder(cb, enc);
    calls++;
    return ds4_gpu_finish_command_buffer(cb, owned, "llms ao g64") ? 1 : 0;
}
int ds4_gpu_dsv41_attention_output_batch(
        ds4_gpu_tensor *out, ds4_gpu_tensor *low,
        const void *model_map, uint64_t model_size,
        uint64_t out_a_offset, uint64_t out_b_offset,
        const ds4_gpu_tensor *heads, uint32_t n_tokens) {
    /* One-row verify uses the same low-projection codec owner as ordinary
     * decode. Diagnostic switch: remove it after the product/quality gate. */
    static int ao_one = -1;
    static uint64_t ao_one_calls;
    if (ao_one < 0) {
        const char *e = getenv("LLMS_DS4_AO_ONE");
        ao_one = e && *e && *e != '0';
    }
    if (n_tokens == 1u && ao_one) {
        if (!ao_one_calls++) atexit_b(^{
            fprintf(stderr, "astra ao one: %llu calls through the ordinary one-token projection\n",
                    (unsigned long long)ao_one_calls);
        });
        return ds4_gpu_attention_output_low_q8_tensor(low, model_map, model_size,
                   out_a_offset, 4096, 1024, 8, heads) &&
               ds4_gpu_dsv41_quantize(low, 8192, 1, DS4_V41_BF16) &&
               ds4_gpu_matmul_q8_0_tensor(out, model_map, model_size,
                   out_b_offset, 8192, 5120, low, 1);
    }
    return ds4_gpu_attention_output_q8_batch_impl(out, low, low, low,
        model_map, model_size, out_a_offset, out_b_offset, 4096, 1024,
        8, 5120, heads, n_tokens, true, 0, 0);
}

int ds4_gpu_dsv41_attention_output_tp_batch(
        ds4_gpu_tensor *out, ds4_gpu_tensor *low,
        const void *model_map, uint64_t model_size,
        uint64_t out_a_offset, uint64_t out_b_offset,
        const ds4_gpu_tensor *heads, uint32_t n_tokens, uint32_t tp_rank) {
    const uint64_t shard_bytes = UINT64_C(4) * 1024 * (4096 / 32 * 34);
    if (tp_rank > 1 || out_a_offset > model_size ||
        shard_bytes * 2u > model_size - out_a_offset) return 0;
    return ds4_gpu_attention_output_q8_batch_impl(out, low, low, low,
        model_map, model_size, out_a_offset + tp_rank * shard_bytes, out_b_offset,
        4096, 1024, 4, 5120, heads, n_tokens, true, 8192, tp_rank * 4096u);
}

int ds4_gpu_attention_output_q4_K_batch_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *low,
        ds4_gpu_tensor       *group_tmp,
        ds4_gpu_tensor       *low_tmp,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                out_a_offset,
        uint64_t                out_b_offset,
        uint32_t                out_b_type,
        uint64_t                group_dim,
        uint64_t                rank,
        uint32_t                n_groups,
        uint64_t                out_dim,
        const ds4_gpu_tensor *heads,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !low || !heads || !model_map ||
        group_dim == 0 || rank == 0 || n_groups == 0 || out_dim == 0 || n_tokens == 0 ||
        group_dim > UINT32_MAX || rank > UINT32_MAX || out_dim > UINT32_MAX) {
        return 0;
    }
    if (n_tokens < 32u) return 0;

    @autoreleasepool {
        const uint64_t low_dim = (uint64_t)n_groups * rank;
        if ((group_dim % 256u) != 0 || (low_dim % 256u) != 0 || low_dim > UINT32_MAX) {
            return 0;
        }

        uint64_t row_a_bytes = 0;
        uint64_t row_b_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(DS4_METAL_TENSOR_Q4_K, (uint32_t)group_dim, &row_a_bytes) ||
            !ds4_gpu_quant_row_bytes(out_b_type, (uint32_t)low_dim, &row_b_bytes)) {
            return 0;
        }

        const uint64_t out_a_bytes = (uint64_t)n_groups * rank * row_a_bytes;
        const uint64_t out_b_bytes = out_dim * row_b_bytes;
        if (out_a_offset > model_size || out_a_bytes > model_size - out_a_offset ||
            out_b_offset > model_size || out_b_bytes > model_size - out_b_offset) {
            fprintf(stderr, "ds4: Metal Q4 attention output batch weights are outside the mapped model\n");
            return 0;
        }

        const uint64_t heads_bytes = (uint64_t)n_tokens * n_groups * group_dim * sizeof(float);
        const uint64_t low_bytes = (uint64_t)n_tokens * low_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * out_dim * sizeof(float);
        if (ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(low) < low_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal Q4 attention output batch received undersized buffers\n");
            return 0;
        }
        (void)group_tmp;
        (void)low_tmp;

        const uint64_t padded_n_tokens_u64 =
            ((uint64_t)n_tokens + DS4_METAL_ATTN_OUT_MPP_TILE_N - 1u) /
            DS4_METAL_ATTN_OUT_MPP_TILE_N * DS4_METAL_ATTN_OUT_MPP_TILE_N;
        const uint32_t padded_n_tokens =
            padded_n_tokens_u64 <= UINT32_MAX ? (uint32_t)padded_n_tokens_u64 : n_tokens;
        /*
         * TensorOps requires complete 64-row tiles.  For a substantial final
         * prefill chunk, compute harmless extra rows when the caller's
         * workspace already covers them; the following projection consumes
         * only the real rows.  Small tails stay on the legacy kernel because
         * padding overhead outweighs the faster arithmetic there.
         */
        const bool use_mpp_padding =
            n_tokens >= 256u &&
            padded_n_tokens > n_tokens &&
            ds4_gpu_tensor_bytes(heads) >=
                (uint64_t)padded_n_tokens * n_groups * group_dim * sizeof(float) &&
            ds4_gpu_tensor_bytes(low) >=
                (uint64_t)padded_n_tokens * low_dim * sizeof(float);
        bool use_mpp_low =
            ((n_tokens % DS4_METAL_ATTN_OUT_MPP_TILE_N) == 0 ||
             use_mpp_padding) &&
            ds4_gpu_use_mpp_attn_out_low_matmul();
        id<MTLComputePipelineState> mpp_low_pipeline = nil;
        if (use_mpp_low) {
            mpp_low_pipeline = ds4_gpu_get_mul_mm_id_pipeline(
                "kernel_attn_out_low_q4_K_mpp_direct_rhs_n64", false);
            if (!mpp_low_pipeline) {
                ds4_gpu_warn_mpp_fallback();
                use_mpp_low = false;
            }
        }
        const NSUInteger ids_bytes = (NSUInteger)n_tokens * (NSUInteger)n_groups * sizeof(int32_t);
        id<MTLBuffer> group_ids_buffer = nil;
        if (!use_mpp_low) {
            if (getenv("DS4_METAL_DISABLE_ATTN_OUT_IDS_CACHE") != NULL) {
                group_ids_buffer =
                    ds4_gpu_new_transient_buffer(ids_bytes, "attention output Q4 group ids");
            } else if (ds4_gpu_ensure_scratch_buffer(&g_attn_out_group_ids_buffer,
                                                     &g_attn_out_group_ids_bytes,
                                                     ids_bytes,
                                                     "ds4_attention_output_group_ids")) {
                group_ids_buffer = g_attn_out_group_ids_buffer;
            }
            if (!group_ids_buffer) return 0;

            int32_t *ids = (int32_t *)[group_ids_buffer contents];
            for (uint32_t t = 0; t < n_tokens; t++) {
                for (uint32_t group = 0; group < n_groups; group++) {
                    ids[(uint64_t)t * n_groups + group] = (int32_t)group;
                }
            }
        }

        uint64_t out_a_inner = 0;
        id<MTLBuffer> out_a_buf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                     out_a_offset, out_a_bytes,
                                     &out_a_inner);
        if (!out_a_buf) return 0;

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;

        bool ok = true;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb || owned) ok = false;

        if (ok) {
            ds4_gpu_mul_mm_id_args mm_args =
                ds4_gpu_make_mul_mm_id_args((uint32_t)group_dim,
                                            (uint32_t)rank,
                                            n_groups,
                                            row_a_bytes,
                                            (uint64_t)rank * row_a_bytes,
                                            n_groups,
                                            n_groups,
                                            use_mpp_low && use_mpp_padding
                                                ? padded_n_tokens
                                                : n_tokens);
            if (use_mpp_low) {
                ok = ds4_gpu_encode_attn_out_low_mpp(
                        cb,
                        mpp_low_pipeline,
                        &mm_args,
                        out_a_buf,
                        (NSUInteger)out_a_inner,
                        ds4_gpu_tensor_buffer(heads),
                        ds4_gpu_tensor_offset(heads),
                        ds4_gpu_tensor_buffer(low),
                        ds4_gpu_tensor_offset(low)) != 0;
            } else {
                ds4_gpu_mul_mm_id_map_args map_args =
                    ds4_gpu_make_mul_mm_id_map_args((uint32_t)group_dim,
                                                    n_groups,
                                                    n_groups,
                                                    n_groups,
                                                    n_tokens);
                id<MTLComputePipelineState> map_pipeline =
                    ds4_gpu_get_pipeline(ds4_gpu_mul_mm_id_map0_name(n_groups));
                id<MTLComputePipelineState> mm_pipeline =
                    ds4_gpu_get_mul_mm_id_pipeline("kernel_mul_mm_id_q4_K_f32", false);
                ok = ds4_gpu_encode_mul_mm_id(cb,
                                              map_pipeline,
                                              mm_pipeline,
                                              &map_args,
                                              &mm_args,
                                              out_a_buf,
                                              (NSUInteger)out_a_inner,
                                              ds4_gpu_tensor_buffer(heads),
                                              ds4_gpu_tensor_offset(heads),
                                              ds4_gpu_tensor_buffer(low),
                                              ds4_gpu_tensor_offset(low),
                                              group_ids_buffer,
                                              0) != 0;
            }
        }

        if (ok) {
            ok = ds4_gpu_matmul_quant_tensor(out,
                                             model_map,
                                             model_size,
                                             out_b_offset,
                                             out_b_type,
                                             low_dim,
                                             out_dim,
                                             low,
                                             n_tokens) != 0;
        }

        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        return ok ? 1 : 0;
    }
}

int ds4_gpu_attention_output_q8_batch_f16_tensor(
        ds4_gpu_tensor       *out_h,
        ds4_gpu_tensor       *low,
