int ds4_gpu_matmul_q8_0_kslice_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                full_in_dim,
        uint64_t                k_off,
        uint64_t                k_cnt,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                x_elem_off) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if ((full_in_dim & 31u) != 0 || (k_off & 31u) != 0 || (k_cnt & 31u) != 0 ||
        k_cnt == 0 || k_off + k_cnt > full_in_dim ||
        full_in_dim > UINT32_MAX || out_dim > UINT32_MAX) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < (x_elem_off + k_cnt) * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < out_dim * sizeof(float)) {
            fprintf(stderr, "ds4: Metal Q8_0 kslice matmul received undersized buffers\n");
            return 0;
        }
        const uint64_t row_bytes = (full_in_dim / 32u) * 34u;
        const uint64_t weight_bytes = out_dim * row_bytes;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal Q8_0 kslice weights are outside the mapped model\n");
            return 0;
        }
        uint64_t inner = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                        weight_offset, weight_bytes, &inner);
        if (!wbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        /* Same matvec kernel as the full projection: ne00 bounds the k loop
         * while nb01/nb02 keep the full-row stride, so each row reads only
         * the owned k window. */
        ds4_gpu_q8_0_matvec_args mv_args = ds4_gpu_make_q8_0_mv_args(full_in_dim, out_dim);
        mv_args.ne00 = (int32_t)k_cnt;
        mv_args.ne10 = (int32_t)k_cnt;
        ds4_gpu_mv_dispatch mv_dispatch = ds4_gpu_make_q8_0_mv_dispatch();
        if (out_dim > 65536u) mv_dispatch.nsg = 8;
        mv_args.nr0 = mv_dispatch.nr0;
        /* TP partial producer: publish the gate's checked flag from the
         * same kernel (last-arriving threadgroup) when requested. */
        uint32_t fold_slot = 0, fold_value = 0;
        const int fold = !owned &&
            ds4_gpu_tp_flag_fold_take(out, out_dim * sizeof(float), &fold_slot, &fold_value);
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mv_pipeline(
                fold ? "kernel_dsv4_mul_mv_q8_0_f32_tp_flag_checked"
                     : mv_dispatch.function_name,
                mv_dispatch.nsg);
        if (!pipeline) return 0;
        const NSUInteger ntg =
            ((NSUInteger)out_dim + (NSUInteger)mv_dispatch.nr0 - 1u) / (NSUInteger)mv_dispatch.nr0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&mv_args length:sizeof(mv_args) atIndex:0];
        [enc setBuffer:wbuf offset:(NSUInteger)(inner + (k_off / 32u) * 34u) atIndex:1];
        [enc setBuffer:xbuf
                offset:(NSUInteger)(ds4_gpu_tensor_offset(x) + x_elem_off * sizeof(float))
               atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        if (fold) {
            const uint32_t ntg32 = (uint32_t)ntg;
            [enc setBuffer:g_tp_slab_buffer
                    offset:(NSUInteger)(g_tp_slab_buffer_off + g_tp_gpu_flags_off + (uint64_t)fold_slot * 4u)
                   atIndex:4];
            [enc setBuffer:g_tp_check_buffer offset:(NSUInteger)fold_slot * 4u atIndex:5];
            [enc setBytes:&fold_value length:sizeof(fold_value) atIndex:6];
            [enc setBuffer:g_tp_fold_ctl offset:(NSUInteger)fold_slot * 8u atIndex:7];
            [enc setBytes:&ntg32 length:sizeof(ntg32) atIndex:8];
            [enc setThreadgroupMemoryLength:16 atIndex:1];
        }
        [enc setThreadgroupMemoryLength:mv_dispatch.smem atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(ntg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)mv_dispatch.nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (fold) g_tp_flag_prepublished_seq = g_tp_seq + 1u;

        if (!ds4_gpu_finish_command_buffer(cb, owned, "Q8_0 kslice matvec")) {
            return 0;
        }
        return 1;
    }
}

static int ds4_gpu_matmul_q8_0_kslice_rows_impl(
        ds4_gpu_tensor       *out,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              full_in_dim,
        uint64_t              out_dim,
        uint64_t              k_off,
        uint64_t              k_cnt,
        const ds4_gpu_tensor *x,
        uint64_t              n_rows,
        uint64_t              x_stride,
        uint64_t              x_off) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!ds4_gpu_mpp_available() ||
        !out || !x || !model_map ||
        (full_in_dim % 64u) != 0 || (out_dim % 64u) != 0 ||
        (k_off % 32u) != 0 || (k_cnt % 64u) != 0 ||
        k_cnt == 0 || k_off > full_in_dim || k_cnt > full_in_dim - k_off ||
        x_stride > UINT32_MAX || x_off > x_stride || k_cnt > x_stride - x_off ||
        (n_rows % 32u) != 0 || n_rows == 0 ||
        full_in_dim > UINT32_MAX || out_dim > UINT32_MAX ||
        n_rows > UINT32_MAX) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t row_bytes = (full_in_dim / 32u) * 34u;
        const uint64_t weight_bytes = out_dim * row_bytes;
        const uint64_t x_bytes = n_rows * x_stride * sizeof(float);
        const uint64_t out_bytes = n_rows * out_dim * sizeof(float);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < x_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            weight_offset > model_size ||
            weight_bytes > model_size - weight_offset) {
            return 0;
        }

        uint64_t inner_offset = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map,
                                                      model_size,
                                                      weight_offset,
                                                      weight_bytes,
                                                      &inner_offset);
        if (!wbuf) return 0;

        uint64_t tile_rows = 32u;
        if ((n_rows % 128u) == 0) tile_rows = 128u;
        else if ((n_rows % 64u) == 0) tile_rows = 64u;
        const char *fn = tile_rows == 128u
            ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n128"
            : (tile_rows == 64u
                ? "kernel_mul_mm_q8_0_f32_nax_direct_rhs_n64"
                : "kernel_mul_mm_q8_0_f32_nax_direct_rhs");
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mm_pipeline(fn, false, false);
        if (!pipeline) return 0;

        ds4_gpu_mul_mm_args args =
            ds4_gpu_make_mm_args(k_cnt, out_dim, n_rows, row_bytes);
        args.nb01 = row_bytes;
        args.nb02 = row_bytes * out_dim;
        args.nb03 = row_bytes * out_dim;
        args.nb11 = x_stride * sizeof(float);
        args.nb12 = n_rows * x_stride * sizeof(float);
        args.nb13 = args.nb12;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:wbuf
                offset:(NSUInteger)(inner_offset + (k_off / 32u) * 34u)
               atIndex:1];
        [enc setBuffer:xbuf
                offset:(NSUInteger)(ds4_gpu_tensor_offset(x) +
                                    x_off * sizeof(float))
               atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:2u * 64u * 32u * sizeof(uint16_t)
                                atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)(n_rows / tile_rows),
                                              (NSUInteger)(out_dim / 64u),
                                              1)
             threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return ds4_gpu_finish_command_buffer(cb,
                                             owned,
                                             "Q8_0 NAX kslice rows matmul");
    }
}

int ds4_gpu_matmul_q8_0_kslice_rows_tensor(
        ds4_gpu_tensor *out, const void *model_map, uint64_t model_size,
        uint64_t weight_offset, uint64_t full_in_dim, uint64_t out_dim,
        uint64_t k_off, uint64_t k_cnt, const ds4_gpu_tensor *x,
        uint64_t n_rows) {
    return ds4_gpu_matmul_q8_0_kslice_rows_impl(out, model_map, model_size,
        weight_offset, full_in_dim, out_dim, k_off, k_cnt, x, n_rows,
        full_in_dim, k_off);
}

int ds4_gpu_matmul_quant_kslice_tensor(
        ds4_gpu_tensor       *out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint32_t                weight_type,
        uint64_t                full_in_dim,
        uint64_t                k_off,
        uint64_t                k_cnt,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        uint64_t                x_elem_off) {
    if (weight_type == DS4_METAL_TENSOR_Q8_0) {
        return ds4_gpu_matmul_q8_0_kslice_tensor(out,
                                                 model_map,
                                                 model_size,
                                                 weight_offset,
                                                 full_in_dim,
                                                 k_off,
                                                 k_cnt,
                                                 out_dim,
                                                 x,
                                                 x_elem_off);
    }
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !x || !model_map ||
        full_in_dim == 0 || k_cnt == 0 || out_dim == 0 ||
        k_off + k_cnt > full_in_dim ||
        full_in_dim > UINT32_MAX || k_cnt > UINT32_MAX ||
        out_dim > UINT32_MAX) {
        return 0;
    }

    uint64_t block_elems = 0;
    uint64_t block_bytes = 0;
    if (weight_type == DS4_METAL_TENSOR_Q4_K) {
        block_elems = 256u;
        block_bytes = 144u;
    } else if (weight_type == DS4_METAL_TENSOR_Q4_0) {
        block_elems = 32u;
        block_bytes = 18u;
    } else {
        fprintf(stderr, "ds4: Metal quant kslice received unsupported type %u\n", weight_type);
        return 0;
    }
    if ((full_in_dim % block_elems) != 0 ||
        (k_off % block_elems) != 0 ||
        (k_cnt % block_elems) != 0) {
        fprintf(stderr, "ds4: Metal quant kslice dimensions are not block aligned\n");
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < (x_elem_off + k_cnt) * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < out_dim * sizeof(float)) {
            fprintf(stderr, "ds4: Metal quant kslice matmul received undersized buffers\n");
            return 0;
        }

        const uint64_t row_bytes = (full_in_dim / block_elems) * block_bytes;
        const uint64_t weight_bytes = out_dim * row_bytes;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal quant kslice weights are outside the mapped model\n");
            return 0;
        }
        uint64_t inner = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                        weight_offset, weight_bytes, &inner);
        if (!wbuf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (weight_type == DS4_METAL_TENSOR_Q4_K &&
            (k_cnt % 256u) == 0 &&
            getenv("DS4_METAL_DISABLE_Q4_MV_CLASSIC") == NULL) {
            const int16_t nsg = 2;
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_ext_pipeline("kernel_mul_mv_q4_K_dense_f32", nsg, 8);
            if (pipeline) {
                ds4_gpu_q8_0_matvec_args args = {
                    .ne00 = (int32_t)k_cnt,
                    .ne01 = (int32_t)out_dim,
                    .ne02 = 1,
                    .nb00 = 1,
                    .nb01 = row_bytes,
                    .nb02 = row_bytes * out_dim,
                    .nb03 = row_bytes * out_dim,
                    .ne10 = (int32_t)k_cnt,
                    .ne11 = 1,
                    .ne12 = 1,
                    .nb10 = sizeof(float),
                    .nb11 = k_cnt * sizeof(float),
                    .nb12 = k_cnt * sizeof(float),
                    .nb13 = k_cnt * sizeof(float),
                    .ne0 = (int32_t)out_dim,
                    .ne1 = 1,
                    .nr0 = 2,
                    .r2 = 1,
                    .r3 = 1,
                };
                const uint64_t rows_ptg = (uint64_t)nsg * 2u;
                const uint64_t w_skip = (k_off / block_elems) * block_bytes;

                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:pipeline];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:wbuf offset:(NSUInteger)(inner + w_skip) atIndex:1];
                [enc setBuffer:xbuf
                        offset:(NSUInteger)(ds4_gpu_tensor_offset(x) + x_elem_off * sizeof(float))
                       atIndex:2];
                [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
                [enc setThreadgroupMemoryLength:32 atIndex:0];
                [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)out_dim + rows_ptg - 1u) / rows_ptg,
                                                      1,
                                                      1)
                     threadsPerThreadgroup:MTLSizeMake(32, (NSUInteger)nsg, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);

                if (!ds4_gpu_finish_command_buffer(cb, owned, "Q4_K kslice matvec")) return 0;
                return 1;
            }
        }

        fprintf(stderr, "ds4: Metal quant kslice has no kernel for type %u\n",
                weight_type);
        return 0;
    }
}

int ds4_gpu_attention_output_q8_tp_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *low,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                out_a_offset,
        uint64_t                out_b_offset,
        uint64_t                group_dim,
        uint64_t                rank,
        uint32_t                n_groups_total,
        uint32_t                group0,
        uint32_t                group_cnt,
        uint64_t                out_dim,
        const ds4_gpu_tensor *heads) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !low || !heads || !model_map ||
        group_dim == 0 || rank == 0 || group_cnt == 0 ||
        group0 + group_cnt > n_groups_total ||
        (group_dim % 32u) != 0 || ((rank * group_cnt) % 32u) != 0 ||
        group_dim > UINT32_MAX || rank > UINT32_MAX || out_dim > UINT32_MAX) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t low_dim_total = (uint64_t)n_groups_total * rank;
        const uint64_t row_a_bytes = (group_dim / 32u) * 34u;
        const uint64_t a_group_bytes = rank * row_a_bytes;
        const uint64_t out_a_bytes = (uint64_t)n_groups_total * a_group_bytes;
        if (out_a_offset > model_size || out_a_bytes > model_size - out_a_offset) {
            fprintf(stderr, "ds4: Metal TP attention output weights are outside the mapped model\n");
            return 0;
        }
        /* The heads buffer holds only the owned groups, compact at its
         * base (the head slice keeps q/attention output halves packed). */
        if (ds4_gpu_tensor_bytes(heads) < (uint64_t)group_cnt * group_dim * sizeof(float) ||
            ds4_gpu_tensor_bytes(low) < (uint64_t)group_cnt * rank * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < out_dim * sizeof(float)) {
            fprintf(stderr, "ds4: Metal TP attention output received undersized buffers\n");
            return 0;
        }

        uint64_t out_a_inner = 0;
        id<MTLBuffer> out_a_buf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                       out_a_offset, out_a_bytes, &out_a_inner);
        if (!out_a_buf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb || owned) return 0;

        /* Low projection for the owned groups only: identical dispatch to
         * the single-node direct path with the weight base, heads input and
         * group count shifted to the slice.  The owned low half lands
         * compactly at low[0 .. group_cnt*rank). */
        ds4_gpu_mul_mv_id_args args = {
            .nei0 = (int32_t)group_cnt,
            .nei1 = 1,
            .nbi1 = 0,
            .ne00 = (int32_t)group_dim,
            .ne01 = (int32_t)rank,
            .ne02 = (int32_t)group_cnt,
            .nb00 = 34,
            .nb01 = row_a_bytes,
            .nb02 = a_group_bytes,
            .ne10 = (int32_t)group_dim,
            .ne11 = (int32_t)group_cnt,
            .ne12 = 1,
            .ne13 = 1,
            .nb10 = sizeof(float),
            .nb11 = (uint64_t)group_dim * sizeof(float),
            .nb12 = (uint64_t)group_cnt * group_dim * sizeof(float),
            .ne0 = (int32_t)rank,
            .ne1 = (int32_t)group_cnt,
            .nb1 = (uint64_t)rank * sizeof(float),
            .nr0 = 2,
        };
        id<MTLComputePipelineState> pipeline =
            ds4_gpu_get_mul_mv_pipeline("kernel_dsv4_attn_out_low_q8_0_f32", 4);
        int ok = ds4_gpu_encode_attn_out_low_q8_direct(cb,
                pipeline,
                &args,
                out_a_buf,
                (NSUInteger)(out_a_inner + (uint64_t)group0 * a_group_bytes),
                ds4_gpu_tensor_buffer(heads),
                ds4_gpu_tensor_offset(heads),
                ds4_gpu_tensor_buffer(low),
                ds4_gpu_tensor_offset(low),
                32u * 2u * sizeof(float),
                4,
                true);
        if (!ok) return 0;

        /* Expand projection over the owned k window only; the result is this
         * rank's partial attention block output. */
        return ds4_gpu_matmul_q8_0_kslice_tensor(out, model_map, model_size,
                                                   out_b_offset,
                                                   low_dim_total,
                                                   (uint64_t)group0 * rank,
                                                   (uint64_t)group_cnt * rank,
                                                   out_dim, low, 0);
    }
}

int ds4_gpu_attention_output_low_q8_tensor(
        ds4_gpu_tensor       *low,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                out_a_offset,
        uint64_t                group_dim,
        uint64_t                rank,
        uint32_t                n_groups,
        const ds4_gpu_tensor *heads) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!low || !heads || !model_map || group_dim == 0 || rank == 0 ||
        n_groups == 0 || group_dim > UINT32_MAX || rank > UINT32_MAX) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t low_dim = (uint64_t)n_groups * rank;
        if ((group_dim % 32u) != 0 || low_dim > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal attention output low received invalid q8 dimensions\n");
            return 0;
        }

        const uint64_t row_a_bytes = (group_dim / 32u) * 34u;
        const uint64_t out_a_bytes = (uint64_t)n_groups * rank * row_a_bytes;
        if (out_a_offset > model_size || out_a_bytes > model_size - out_a_offset) {
            fprintf(stderr, "ds4: Metal attention output low weights are outside the mapped model\n");
            return 0;
        }

        const uint64_t heads_bytes = (uint64_t)n_groups * group_dim * sizeof(float);
        const uint64_t low_bytes = low_dim * sizeof(float);
        if (ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(low) < low_bytes) {
            fprintf(stderr, "ds4: Metal attention output low received undersized buffers\n");
            return 0;
        }

        uint64_t out_a_inner = 0;
        id<MTLBuffer> out_a_buf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                       out_a_offset, out_a_bytes,
                                       &out_a_inner);
        if (!out_a_buf) return 0;

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;

        bool ok = true;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb || owned) {
            ok = false;
        }

        bool llms_q4la_done = false;   /* llms Q4L_A (apply_q4l_a.py): the grouped low projection on the 4-bit copy */
        if (ok) llms_act_note(out_a_offset, cb, ds4_gpu_tensor_buffer(heads), ds4_gpu_tensor_offset(heads), (uint32_t)(n_groups * group_dim));   /* llms ACT_STATS */
        if (ok) {
            if (g_llms_q4l_n < 0) llms_q4l_init();
            const llms_q4l_ent *qe = g_llms_q4l_n > 0 && !llms_alt_off("q4la") ? llms_q4l_find(out_a_offset) : NULL;
            if (qe && (ds4_gpu_tensor_offset(heads) & 15u) != 0) { g_llms_q4l_unaligned++; qe = NULL; }
            if (qe) {
                if ((uint64_t)qe->k != group_dim || (uint64_t)qe->n != (uint64_t)n_groups * rank) {
                    fprintf(stderr, "llms: q4l entry at %llu is %ux%u, the grouped call %llux%llu\n", (unsigned long long)out_a_offset, qe->k, qe->n,
                            (unsigned long long)group_dim, (unsigned long long)n_groups * rank);
                    abort();
                }
                id<MTLComputePipelineState> qp = ds4_gpu_get_mul_mv_pipeline("kernel_llms_q4l_mv_grp", 2);
                if (!qp) { fprintf(stderr, "llms: kernel_llms_q4l_mv_grp missing from DS4_METAL_DENSE_SOURCE\n"); abort(); }
                ds4_gpu_q8_0_matvec_args qa = ds4_gpu_make_q8_0_mv_args(group_dim, rank);
                qa.nb00 = 1; qa.nb01 = group_dim / 16u * 9u; qa.nb02 = qa.nb01 * rank; qa.nb03 = qa.nb02; qa.nr0 = 4;
                qa.nb11 = group_dim * sizeof(float);
                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:qp];
                [enc setBytes:&qa length:sizeof(qa) atIndex:0];
                [enc setBuffer:qe->buf offset:(NSUInteger)qe->inner atIndex:1];   /* llms Q4L_WRAP */
                [enc setBuffer:ds4_gpu_tensor_buffer(heads) offset:ds4_gpu_tensor_offset(heads) atIndex:2];
                [enc setBuffer:ds4_gpu_tensor_buffer(low) offset:ds4_gpu_tensor_offset(low) atIndex:3];
                [enc setThreadgroupMemoryLength:4u * 32u * sizeof(float) atIndex:0];
                [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)rank + 3u) / 4u, 1, (NSUInteger)n_groups) threadsPerThreadgroup:MTLSizeMake(32, 2, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                g_llms_q4l_calls++; g_llms_q4la_calls++; llms_q4la_done = true;
            }
        }
        if (ok && !llms_q4la_done) {
            ds4_gpu_mul_mv_id_args args = {
                .nei0 = (int32_t)n_groups,
                .nei1 = 1,
                .nbi1 = 0,
                .ne00 = (int32_t)group_dim,
                .ne01 = (int32_t)rank,
                .ne02 = (int32_t)n_groups,
                .nb00 = 34,
                .nb01 = row_a_bytes,
                .nb02 = (uint64_t)rank * row_a_bytes,
                .ne10 = (int32_t)group_dim,
                .ne11 = (int32_t)n_groups,
                .ne12 = 1,
                .ne13 = 1,
                .nb10 = sizeof(float),
                .nb11 = (uint64_t)group_dim * sizeof(float),
                .nb12 = (uint64_t)n_groups * group_dim * sizeof(float),
                .ne0 = (int32_t)rank,
                .ne1 = (int32_t)n_groups,
                .nb1 = (uint64_t)rank * sizeof(float),
                .nr0 = 2,
            };
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_pipeline("kernel_dsv4_attn_out_low_q8_0_f32", 4);
            ok = ds4_gpu_encode_attn_out_low_q8_direct(cb,
                                                         pipeline,
                                                         &args,
                                                         out_a_buf,
                                                         (NSUInteger)out_a_inner,
                                                         ds4_gpu_tensor_buffer(heads),
                                                         ds4_gpu_tensor_offset(heads),
                                                         ds4_gpu_tensor_buffer(low),
                                                         ds4_gpu_tensor_offset(low),
                                                         32u * 2u * sizeof(float),
                                                         4,
                                                         true) != 0;
        }

        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        return ok ? 1 : 0;
    }
}

int ds4_gpu_attention_output_low_q4_K_slice_tensor(
        ds4_gpu_tensor       *low,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                out_a_offset,
        uint64_t                group_dim,
        uint64_t                rank,
        uint32_t                group0,
        uint32_t                group_cnt,
        const ds4_gpu_tensor *heads) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!low || !heads || !model_map || group_dim == 0 || rank == 0 ||
        group_cnt == 0 || group_dim > UINT32_MAX || rank > UINT32_MAX) {
        return 0;
    }

    @autoreleasepool {
        if ((group_dim % 256u) != 0) {
            fprintf(stderr, "ds4: Metal attention output low received invalid Q4_K dimensions\n");
            return 0;
        }

        uint64_t row_a_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(DS4_METAL_TENSOR_Q4_K,
                                     (uint32_t)group_dim,
                                     &row_a_bytes)) {
            return 0;
        }
        if (rank > UINT64_MAX / row_a_bytes) return 0;
        const uint64_t group_weight_bytes = rank * row_a_bytes;
        if (group0 > UINT64_MAX / group_weight_bytes ||
            group_cnt > UINT64_MAX / group_weight_bytes) {
            return 0;
        }
        const uint64_t group_skip = (uint64_t)group0 * group_weight_bytes;
        const uint64_t out_a_bytes = (uint64_t)group_cnt * group_weight_bytes;
        if (out_a_offset > UINT64_MAX - group_skip ||
            out_a_offset + group_skip > model_size ||
            out_a_bytes > model_size - (out_a_offset + group_skip)) {
            fprintf(stderr, "ds4: Metal Q4 attention output low weights are outside the mapped model\n");
            return 0;
        }

        const uint64_t heads_bytes = (uint64_t)group_cnt * group_dim * sizeof(float);
        const uint64_t low_bytes = (uint64_t)group_cnt * rank * sizeof(float);
        if (ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(low) < low_bytes) {
            fprintf(stderr, "ds4: Metal Q4 attention output low received undersized buffers\n");
            return 0;
        }

        uint64_t out_a_inner = 0;
        id<MTLBuffer> out_a_buf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                      out_a_offset + group_skip,
                                      out_a_bytes,
                                      &out_a_inner);
        if (!out_a_buf) return 0;

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;

        bool ok = true;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb || owned) {
            ok = false;
        }

        if (ok) {
            ds4_gpu_mul_mv_id_args args = {
                .nei0 = (int32_t)group_cnt,
                .nei1 = 1,
                .nbi1 = 0,
                .ne00 = (int32_t)group_dim,
                .ne01 = (int32_t)rank,
                .ne02 = (int32_t)group_cnt,
                .nb00 = 1,
                .nb01 = row_a_bytes,
                .nb02 = group_weight_bytes,
                .ne10 = (int32_t)group_dim,
                .ne11 = (int32_t)group_cnt,
                .ne12 = 1,
                .ne13 = 1,
                .nb10 = sizeof(float),
                .nb11 = (uint64_t)group_dim * sizeof(float),
                .nb12 = (uint64_t)group_cnt * group_dim * sizeof(float),
                .ne0 = (int32_t)rank,
                .ne1 = (int32_t)group_cnt,
                .nb1 = (uint64_t)rank * sizeof(float),
                .nr0 = 2,
            };
            const NSUInteger nsg = 2;
            id<MTLComputePipelineState> pipeline =
                ds4_gpu_get_mul_mv_pipeline("kernel_dsv4_attn_out_low_q4_K_f32", (int16_t)nsg);
            ok = ds4_gpu_encode_attn_out_low_q8_direct(cb,
                                                         pipeline,
                                                         &args,
                                                         out_a_buf,
                                                         (NSUInteger)out_a_inner,
                                                         ds4_gpu_tensor_buffer(heads),
                                                         ds4_gpu_tensor_offset(heads),
                                                         ds4_gpu_tensor_buffer(low),
                                                         ds4_gpu_tensor_offset(low),
                                                         32u,
                                                         nsg,
                                                         false) != 0;
        }

        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        return ok ? 1 : 0;
    }
}

static NSUInteger ds4_gpu_align_up_ns(NSUInteger value, NSUInteger align) {
    return (value + align - 1u) & ~(align - 1u);
}

static int ds4_gpu_encode_cpy_f32_f32_3d(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        NSUInteger           dst_off,
        uint32_t             cols,
        uint32_t             rows,
        uint32_t             planes,
        uint64_t             src_row_stride,
        uint64_t             src_plane_stride,
        uint64_t             dst_row_stride,
        uint64_t             dst_plane_stride) {
    if (!cb || !src || !dst || cols == 0 || rows == 0 || planes == 0) return 0;

    ds4_gpu_cpy_args args = {
        .nk0 = (int64_t)cols,
        .ne00 = (int64_t)cols,
        .ne01 = (int64_t)rows,
        .ne02 = (int64_t)planes,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = src_row_stride,
        .nb02 = src_plane_stride,
        .nb03 = (uint64_t)planes * src_plane_stride,
        .ne0 = (int64_t)cols,
        .ne1 = (int64_t)rows,
        .ne2 = (int64_t)planes,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = dst_row_stride,
        .nb2 = dst_plane_stride,
        .nb3 = (uint64_t)planes * dst_plane_stride,
    };
    const NSUInteger nth = ds4_gpu_cpy_threads(cols, g_cpy_f32_f32_pipeline);
    const NSUInteger col_groups = ((NSUInteger)cols + nth - 1u) / nth;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_cpy_f32_f32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
