static const ds4_gpu_tensor *g_llms_ring_new; static uint32_t g_llms_ring_prev;
int ds4_gpu_llms_att2_ring_set(const ds4_gpu_tensor *newkv, uint32_t prev) { g_llms_ring_new = newkv; g_llms_ring_prev = newkv ? prev : 0u; return 1; }
int ds4_gpu_attention_indexed_mixed_batch_heads_tensor_ex(
        ds4_gpu_tensor       *heads,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                sinks_offset,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *raw_kv,
        const ds4_gpu_tensor *comp_kv,
        uint32_t                comp_kv_f16,
        const ds4_gpu_tensor *topk,
        uint32_t                n_tokens,
        uint32_t                pos0,
        uint32_t                n_raw,
        uint32_t                raw_cap,
        uint32_t                raw_start,
        uint32_t                n_comp,
        uint32_t                top_k,
        uint32_t                window,
        uint32_t                ratio,
        uint32_t                n_head,
        uint32_t                head_dim,
        uint32_t                force_decode_order) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (force_decode_order && (g_quality_mode || n_tokens > 16u)) {
        fprintf(stderr, "astra split rows require fast mode and at most16 rows\n");
        return 0;
    }
    if (!heads || !model_map || !q || !raw_kv || !comp_kv || !topk ||
        n_tokens == 0 || n_raw == 0 || raw_cap < (g_llms_ring_prev ? g_llms_ring_prev : n_raw) || raw_start >= raw_cap ||   /* llms ATT2_RING: the ring holds only the previous rows */
        n_comp == 0 || top_k == 0 || top_k > n_comp || (top_k & (top_k - 1u)) != 0 ||
        ratio == 0 || n_head == 0 || head_dim != 512) {
        return 0;
    }

    @autoreleasepool {
        if (sinks_offset > model_size || (uint64_t)n_head * sizeof(float) > model_size - sinks_offset) {
            fprintf(stderr, "ds4: Metal indexed attention sinks range is outside the mapped model\n");
            return 0;
        }

        const uint64_t row_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t row_bytes_f16 = (uint64_t)head_dim * sizeof(uint16_t);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * row_bytes;
        const uint64_t raw_bytes = (uint64_t)raw_cap * row_bytes;
        const uint64_t comp_bytes = (uint64_t)n_comp * (comp_kv_f16 ? row_bytes_f16 : row_bytes);
        const uint64_t topk_bytes = (uint64_t)top_k * n_tokens * sizeof(int32_t);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_kv);
        id<MTLBuffer> compbuf = ds4_gpu_tensor_buffer(comp_kv);
        id<MTLBuffer> topkbuf = ds4_gpu_tensor_buffer(topk);
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        if (!qbuf || !rawbuf || !compbuf || !topkbuf || !headsbuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(raw_kv) < raw_bytes ||
            ds4_gpu_tensor_bytes(comp_kv) < comp_bytes ||
            ds4_gpu_tensor_bytes(topk) < topk_bytes ||
            ds4_gpu_tensor_bytes(heads) < q_bytes) {
            fprintf(stderr, "ds4: Metal indexed mixed attention received undersized buffers\n");
            return 0;
        }

        uint64_t sinks_inner = 0;
        id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                             sinks_offset,
                                                             (uint64_t)n_head * sizeof(float),
                                                             &sinks_inner);
        if (!sinks_buf) return 0;

        id<MTLComputePipelineState> sort_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_sort_i32_rows_asc_pipeline,
                                    "kernel_dsv4_sort_i32_rows_asc");
        const bool decode_one_token = n_tokens == 1u || force_decode_order != 0u;
        const bool prefill_dual_heads =
            !decode_one_token && !g_quality_mode && ds4_gpu_mpp_available() &&
            (n_head == 64u || n_head == 32u) &&
            top_k == 512u && window == 128u && head_dim == 512u;
        static int llms_att2 = -1;
        static id<MTLComputePipelineState> llms_att2_pipeline;
        if (llms_att2 < 0) { const char *e = getenv("LLMS_DS4_ATT2"); llms_att2 = (e && *e) ? atoi(e) : 0; if (llms_att2 < 2 || llms_att2 > 31) llms_att2 = 0;
                             if (llms_att2) fprintf(stderr, "llms att2: on, %d splits\n", llms_att2); }
        const bool llms_att2_now = llms_att2 && decode_one_token && !g_quality_mode && head_dim == 512u && n_head % 8u == 0u && !llms_alt_off("att2");   /* llms ALTW: ATT2's ALT name */
        if (llms_att2_now && !llms_att2_pipeline) llms_att2_pipeline = ds4_gpu_get_pipeline("kernel_llms_att2_r16qj");
        static int llms_a2h = -1; static id<MTLComputePipelineState> llms_a2h_pipeline;
        if (llms_a2h < 0) { const char *e = getenv("LLMS_DS4_ATT2_HFIRST"); llms_a2h = e && *e && *e != '0'; if (llms_a2h) fprintf(stderr, "llms: att2 hfirst (the split attention launched heads-fastest: one token's head groups share their K / V rows in cache)\n"); }
        const bool llms_a2h_now = llms_att2_now && llms_a2h && !llms_alt_off("a2h");
        if (llms_a2h_now && !llms_a2h_pipeline) llms_a2h_pipeline = ds4_gpu_get_pipeline("kernel_llms_att2_r16qjh");
        const uint32_t decode_splits =
            decode_one_token && !g_quality_mode ? (llms_att2_now ? (uint32_t)llms_att2 : 12u) : 1u;
        const bool split_decode = decode_splits > 1u;
        id<MTLComputePipelineState> attn_pipeline =
            split_decode ? (llms_att2_now ? ((llms_a2h_now && llms_a2h_pipeline) ? llms_a2h_pipeline : llms_att2_pipeline) :
            ds4_gpu_hot_pipeline(
                g_dsv4_indexed_attention_heads8_split_pipeline,
                "kernel_dsv4_indexed_mixed_attention_heads8_split")) :
            decode_one_token ?
            ds4_gpu_hot_pipeline(g_dsv4_indexed_attention_heads8_rb16_pipeline,
                                   "kernel_dsv4_indexed_mixed_attention_heads8_rb16") :
            prefill_dual_heads ?
            ds4_gpu_hot_pipeline(g_dsv4_indexed_attention_heads16_dual_pipeline,
                                   "kernel_dsv4_indexed_mixed_attention_heads16_dual") :
            ds4_gpu_hot_pipeline(g_dsv4_indexed_attention_heads8_pipeline,
                                   "kernel_dsv4_indexed_mixed_attention_heads8");

        static int astra_indexed_reduce_group = -1;
        static id<MTLComputePipelineState> astra_indexed_reduce_pipeline;
        if (astra_indexed_reduce_group < 0) {
            const char *e = getenv("LLMS_DS4_INDEXED_REDUCE_GROUP");
            astra_indexed_reduce_group = e && *e && *e != '0';
        }
        const bool astra_indexed_reduce_now = split_decode &&
            astra_indexed_reduce_group && !llms_alt_off("irdg");
        if (astra_indexed_reduce_now && !astra_indexed_reduce_pipeline)
            astra_indexed_reduce_pipeline = ds4_gpu_get_pipeline("kernel_astra_indexed_reduce_t32");
        static id<MTLComputePipelineState> llms_att2_r2_pipeline;   /* llms ATT2 r2 (apply_att2_r2.py): the one-thread-per-float4 reduce under ATT2 */
        if (llms_att2_now && !llms_att2_r2_pipeline) llms_att2_r2_pipeline = ds4_gpu_get_pipeline("kernel_llms_att_reduce_v3");
        const bool llms_att2_r2_now = llms_att2_now && llms_att2_r2_pipeline != nil;
        id<MTLComputePipelineState> split_reduce_pipeline = llms_att2_r2_now ? llms_att2_r2_pipeline : astra_indexed_reduce_now ?
            astra_indexed_reduce_pipeline : split_decode ?
            ds4_gpu_hot_pipeline(
                g_dsv4_indexed_attention_heads8_split_reduce_pipeline,
                "kernel_dsv4_indexed_mixed_attention_heads8_split_reduce") :
            nil;
        if (!sort_pipeline || !attn_pipeline ||
            (split_decode && !split_reduce_pipeline)) {
            return 0;
        }
        if ((NSUInteger)top_k > sort_pipeline.maxTotalThreadsPerThreadgroup) {
            fprintf(stderr, "ds4: Metal indexed attention top-k exceeds sort threadgroup limit\n");
            return 0;
        }
        /*
         * Fast decode attends to the same full top-k compressed rows but keeps
         * them in score order, avoiding a chronological sort dispatch.
         * --quality restores the sorted order for stricter reproducibility.
         */
        const bool skip_decode_sort = !g_quality_mode && decode_one_token;
        if (!skip_decode_sort &&
            !ds4_gpu_ensure_scratch_buffer(&g_indexed_topk_buffer,
                                             &g_indexed_topk_bytes,
                                             (NSUInteger)topk_bytes,
                                             "ds4_indexed_topk_sorted")) {
            return 0;
        }

        ds4_gpu_dsv4_topk_mask_args sort_args = {
            .ne00 = (int64_t)top_k,
            .ne01 = (int64_t)n_tokens,
            .nb00 = sizeof(int32_t),
            .nb01 = (uint64_t)top_k * sizeof(int32_t),
            .ne0 = (int64_t)top_k,
            .ne1 = (int64_t)n_tokens,
            .nb0 = sizeof(int32_t),
            .nb1 = (uint64_t)top_k * sizeof(int32_t),
        };
        ds4_gpu_dsv4_indexed_attention_args attn_args = {
            .n_tokens = n_tokens,
            .n_head = n_head,
            .n_raw = n_raw,
            .raw_cap = raw_cap,
            .raw_start = raw_start,
            .n_comp = n_comp,
            .top_k = top_k,
            .pos0 = pos0,
            .window = window,
            .ratio = ratio,
            .comp_kv_f16 = comp_kv_f16 ? 1u : 0u,
            .n_splits = decode_splits,
            .q_token_stride = (uint64_t)n_head * row_bytes,
            .q_head_stride = row_bytes,
            .raw_row_stride = row_bytes,
            .comp_row_stride = comp_kv_f16 ? row_bytes_f16 : row_bytes,
            .topk_token_stride = (uint64_t)top_k * sizeof(int32_t),
            .dst_token_stride = (uint64_t)n_head * row_bytes,
            .dst_head_stride = row_bytes,
            .scale = 1.0f / sqrtf((float)head_dim),
        };
        if (g_llms_ring_prev && !(split_decode && llms_att2_now && llms_a2h_now && llms_a2h_pipeline)) return 0;   /* llms ATT2_RING: only the heads-fastest att2 reads two sources; the caller falls back to the copies */
        attn_args.ring_prev = g_llms_ring_prev;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = nil;
        if (!skip_decode_sort) {
            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:sort_pipeline];
            [enc setBytes:&sort_args length:sizeof(sort_args) atIndex:0];
            [enc setBuffer:topkbuf offset:ds4_gpu_tensor_offset(topk) atIndex:1];
            [enc setBuffer:g_indexed_topk_buffer offset:0 atIndex:2];
            [enc setThreadgroupMemoryLength:(NSUInteger)top_k * sizeof(int32_t) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tokens, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(top_k, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        }

        if (split_decode) {
            const uint64_t nrows = (uint64_t)n_tokens * n_head;
            const uint64_t partial_bytes =
                nrows * head_dim * decode_splits * sizeof(float);
            const uint64_t stats_bytes =
                nrows * decode_splits * 2u * sizeof(float);
            if (partial_bytes > NSUIntegerMax - stats_bytes ||
                !ds4_gpu_ensure_scratch_buffer(
                    &g_flash_attn_tmp_buffer,
                    &g_flash_attn_tmp_bytes,
                    (NSUInteger)(partial_bytes + stats_bytes),
                    "ds4_dsv4_indexed_attention_split_tmp")) {
                return 0;
            }

            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:attn_pipeline];
            [enc setBytes:&attn_args length:sizeof(attn_args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_kv) atIndex:2];
            [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(comp_kv) atIndex:3];
            [enc setBuffer:skip_decode_sort ? topkbuf : g_indexed_topk_buffer
                  offset:skip_decode_sort ? ds4_gpu_tensor_offset(topk) : 0
                 atIndex:4];
            [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:5];
            [enc setBuffer:g_llms_ring_prev ? ds4_gpu_tensor_buffer(g_llms_ring_new) : rawbuf offset:g_llms_ring_prev ? ds4_gpu_tensor_offset(g_llms_ring_new) : ds4_gpu_tensor_offset(raw_kv) atIndex:6];   /* llms ATT2_RING: the new rows (a dummy when off) */
            [enc setThreadgroupMemoryLength:llms_att2_now ? 22528u : 16u * 128u * sizeof(uint16_t) * 4u
                                    atIndex:0];
            { static uint64_t a2h_n; if (llms_a2h_now && llms_a2h_pipeline && !a2h_n++) atexit_b(^{ fprintf(stderr, "llms att2 hfirst: %llu heads-fastest dispatches\n", (unsigned long long)a2h_n); }); }   /* llms ATT2_HFIRST: the execution counter */
            { static uint64_t att2_n; static int att2_s; att2_s = (int)decode_splits; if (llms_att2_now && !att2_n++) atexit_b(^{ fprintf(stderr, "llms att2: %llu split attentions (splits %d)\n", (unsigned long long)att2_n, att2_s); }); }
            [llms_bar(enc) dispatchThreadgroups:
                    MTLSizeMake((llms_a2h_now && llms_a2h_pipeline) ? ((NSUInteger)n_head + 7u) / 8u : (NSUInteger)n_tokens,
                                (llms_a2h_now && llms_a2h_pipeline) ? (NSUInteger)n_tokens : ((NSUInteger)n_head + 7u) / 8u,
                                decode_splits)
                 threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:split_reduce_pipeline];
            [enc setBytes:&attn_args length:sizeof(attn_args) atIndex:0];
            [enc setBuffer:g_flash_attn_tmp_buffer offset:0 atIndex:1];
            [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:2];
            [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:3];
            { static uint64_t irdg_n; if (astra_indexed_reduce_now && !irdg_n++) atexit_b(^{ fprintf(stderr, "astra irdg: %llu grouped reduces\n", (unsigned long long)irdg_n); }); }
            if (llms_att2_r2_now) [llms_bar(enc) dispatchThreads:MTLSizeMake(128u, (NSUInteger)nrows, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
            else [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)nrows * (astra_indexed_reduce_now ? 4u : 1u), 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        } else {
            enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:attn_pipeline];
            [enc setBytes:&attn_args length:sizeof(attn_args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_kv) atIndex:2];
            [enc setBuffer:compbuf offset:ds4_gpu_tensor_offset(comp_kv) atIndex:3];
            [enc setBuffer:skip_decode_sort ? topkbuf : g_indexed_topk_buffer
                  offset:skip_decode_sort ? ds4_gpu_tensor_offset(topk) : 0
                 atIndex:4];
            [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:5];
            [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:6];
            [enc setThreadgroupMemoryLength:(decode_one_token ? 16u : 1u) *
                                            128u * 4u * sizeof(uint16_t)
                                    atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:
                    MTLSizeMake((NSUInteger)n_tokens,
                                ((NSUInteger)n_head + (prefill_dual_heads ? 15u : 7u)) /
                                    (prefill_dual_heads ? 16u : 8u),
                                1)
                 threadsPerThreadgroup:MTLSizeMake(32, 8, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph indexed mixed attention heads")) return 0;
    }

    return 1;
}

int ds4_gpu_attention_prefill_static_mixed_heads_range_tensor(
        ds4_gpu_tensor       *heads,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                sinks_offset,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *raw_kv,
        const ds4_gpu_tensor *comp_kv,
        uint32_t                comp_kv_f16,
        uint32_t                q_row0,
        uint32_t                n_q,
        uint32_t                n_tokens,
        uint32_t                n_comp,
        uint32_t                window,
        uint32_t                ratio,
        uint32_t                n_head,
        uint32_t                head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !raw_kv || !model_map || n_q == 0 || n_tokens == 0 ||
        ratio == 0 || (n_comp != 0 && !comp_kv)) {
        return 0;
    }

    @autoreleasepool {
        if (sinks_offset > model_size || (uint64_t)n_head * sizeof(float) > model_size - sinks_offset) {
            fprintf(stderr, "ds4: Metal attention sinks range is outside the mapped model\n");
            return 0;
        }

        uint64_t sinks_inner = 0;
        id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                             sinks_offset,
                                                             (uint64_t)n_head * sizeof(float),
                                                             &sinks_inner);
        if (!sinks_buf) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_flash_attention_prefill_static_mixed_heads_nonvec(&cb,
                                                                                heads,
                                                                                sinks_buf,
                                                                                (NSUInteger)sinks_inner,
                                                                                q,
                                                                                raw_kv,
                                                                                comp_kv,
                                                                                comp_kv_f16,
                                                                                NULL,
                                                                                0,
                                                                                q_row0,
                                                                                n_q,
                                                                                n_tokens,
                                                                                n_comp,
                                                                                window,
                                                                                ratio,
                                                                                n_head,
                                                                                head_dim)) {
            return 0;
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph prefill static mixed attention heads")) return 0;
    }

    return 1;
}

