static int g_llms_mqa_verify_pending; static id<MTLBuffer> g_llms_mqa_vhead; static double *g_llms_mqa_vmax, *g_llms_mqa_vrel;   /* llms MQA_ATTN verify */
static uint64_t g_llms_mqa_vbad;   /* llms MQA_ATTN verify: calls whose max |d| exceeded 1e-3 */
static int llms_mqa_verify_finish(const ds4_gpu_tensor *heads) {   /* wait, compare the original heads with the mqa scratch (same call) */
    if (!g_llms_mqa_verify_pending) return 1;
    g_llms_mqa_verify_pending = 0;
    if (!ds4_gpu_synchronize()) return 0;
    static float hv[64 * 512];
    if (ds4_gpu_tensor_read(heads, 0, hv, sizeof hv)) {
        const float *mv = (const float *)[g_llms_mqa_vhead contents]; double mx = 0, mr = 0;
        for (int i = 0; i < 64 * 512; i++) { const double d = fabs((double)hv[i] - mv[i]); if (d > mx) mx = d; const double r = d / (fabs((double)hv[i]) + 1e-3); if (r > mr) mr = r; }
        if (mx > *g_llms_mqa_vmax) *g_llms_mqa_vmax = mx;
        if (mr > *g_llms_mqa_vrel) *g_llms_mqa_vrel = mr;
        if (mx > 1e-3 && g_llms_mqa_vbad++ < 5) fprintf(stderr, "llms mqa verify: call with max |d| %.3g\n", mx);
    }
    return ds4_gpu_begin_commands();
}
int ds4_gpu_attention_decode_heads_tensor(
        ds4_gpu_tensor       *heads,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                sinks_offset,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *raw_kv,
        uint32_t                n_raw,
        uint32_t                raw_cap,
        uint32_t                raw_start,
        const ds4_gpu_tensor *comp_kv,
        uint32_t                comp_kv_f16,
        uint32_t                n_comp,
        const ds4_gpu_tensor *comp_mask,
        uint32_t                use_mask,
        uint32_t                n_head,
        uint32_t                head_dim) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !model_map || !q || !raw_kv ||
        n_raw == 0 || n_head == 0 || head_dim == 0 ||
        raw_cap < n_raw || raw_start >= raw_cap ||
        n_raw > UINT32_MAX - n_comp || n_raw + n_comp > 8192u ||
        (n_comp != 0 && !comp_kv) ||
        (use_mask != 0 && !comp_mask)) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t q_bytes = (uint64_t)n_head * head_dim * sizeof(float);
        const uint64_t raw_bytes = (uint64_t)raw_cap * head_dim * sizeof(float);
        const uint64_t comp_bytes = (uint64_t)n_comp * head_dim *
                                    (comp_kv_f16 ? sizeof(uint16_t) : sizeof(float));
        const uint64_t sink_bytes = (uint64_t)n_head * sizeof(float);
        if (sinks_offset > model_size || sink_bytes > model_size - sinks_offset) {
            fprintf(stderr, "ds4: Metal graph attention heads sink range is outside the mapped model\n");
            return 0;
        }

        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_kv);
        id<MTLBuffer> compbuf = n_comp ? ds4_gpu_tensor_buffer(comp_kv) : rawbuf;
        id<MTLBuffer> maskbuf = use_mask ? ds4_gpu_tensor_buffer(comp_mask) : rawbuf;
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        const uint64_t comp_mask_bytes = use_mask ? (uint64_t)n_comp * sizeof(float) : 0u;
        if (!qbuf || !rawbuf || !compbuf || !maskbuf || !headsbuf ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(raw_kv) < raw_bytes ||
            (n_comp && ds4_gpu_tensor_bytes(comp_kv) < comp_bytes) ||
            (use_mask && ds4_gpu_tensor_bytes(comp_mask) < comp_mask_bytes) ||
            ds4_gpu_tensor_bytes(heads) < q_bytes) {
            fprintf(stderr, "ds4: Metal graph attention heads received undersized buffers\n");
            return 0;
        }

        uint64_t sinks_inner = 0;
        id<MTLBuffer> sinks_buf = ds4_gpu_wrap_model_range(model_map, model_size, sinks_offset, sink_bytes, &sinks_inner);
        if (!sinks_buf) return 0;
        {
            static int mq = -1; static id<MTLComputePipelineState> pp, pr; static id<MTLBuffer> part, vhead; static uint64_t calls, vcalls; static double vmax, vrel;
            if (mq < 0) { const char *e = getenv("LLMS_DS4_MQA_ATTN"); mq = !e || !*e || *e == '0' ? 0 : !strcmp(e, "verify") ? 2 : 1;
                          if (mq) { pp = ds4_gpu_get_pipeline("llms_mqa_partial"); pr = ds4_gpu_get_pipeline("llms_mqa_reduce");
                                    if (!pp || !pr) { fprintf(stderr, "llms: mqa kernels missing (DS4_METAL_DSV4_MISC_SOURCE must name the *_mqa superset) -- MQA_ATTN off\n"); mq = 0; }
                                    else { fprintf(stderr, mq == 2 ? "llms: mqa attn VERIFY (both paths; the original's output is used)\n" : "llms: mqa attn (decode attention: each KV row read once for 16 heads)\n");
                                           atexit_b(^{ fprintf(stderr, "llms mqa attn: %llu calls; verify %llu calls, max |d| %.3g, max rel %.3g\n", (unsigned long long)calls,
                                                       (unsigned long long)vcalls, vmax, vrel); }); } } }
            const uint32_t N = n_raw + n_comp;
            if (mq && n_head == 64u && head_dim == 512u && use_mask == 0u && N >= 1u && N <= 2048u && raw_cap >= n_raw && !ds4_gpu_llms_alt_off("mqa")) {
                const uint32_t nch = (N + 15u) / 16u;
                const NSUInteger pbytes = (NSUInteger)nch * 64u * 516u * sizeof(float);
                if (!part || part.length < pbytes) part = [g_device newBufferWithLength:(NSUInteger)128u * 64u * 516u * sizeof(float) options:MTLResourceStorageModePrivate];
                if (mq == 2 && !vhead) vhead = [g_device newBufferWithLength:64u * 512u * sizeof(float) options:MTLResourceStorageModeShared];
                static uint64_t seen; seen++;
                const bool verify = mq == 2 && seen % 8u == 1u && vcalls < 4000u;   /* every 8th call, so long runs are sampled throughout */
                if (part && (mq == 1 || verify)) {   /* mq 2 and not sampled: the original path alone */
                    if (verify && g_kv_task.pending && !ds4_gpu_kv_norm_task_flush()) return 0;
                    struct { uint32_t n_raw, raw_cap, raw_start, n_comp, n_head, comp_f16, n_chunk, pad0; float scale; } ma =
                        { n_raw, raw_cap, raw_start, n_comp, n_head, comp_kv_f16 ? 1u : 0u, nch, 0u, 1.0f / sqrtf((float)head_dim) };
                    if (mq == 1 && g_kv_task.pending && !ds4_gpu_kv_norm_task_flush()) return 0;
                    int owned = 0;
                    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) return 0;
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:pp];
                    [enc setBytes:&ma length:sizeof ma atIndex:0];
                    [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
                    [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_kv) atIndex:2];
                    [enc setBuffer:compbuf offset:(n_comp ? ds4_gpu_tensor_offset(comp_kv) : 0) atIndex:3];
                    [enc setBuffer:part offset:0 atIndex:4];
                    [enc setThreadgroupMemoryLength:16u * 128u * 8u atIndex:0];
                    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(nch, 4, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
                    if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
                    [enc setComputePipelineState:pr];
                    [enc setBytes:&ma length:sizeof ma atIndex:0];
                    [enc setBuffer:part offset:0 atIndex:1];
                    [enc setBuffer:sinks_buf offset:(NSUInteger)sinks_inner atIndex:2];
                    if (verify) [enc setBuffer:vhead offset:0 atIndex:3];
                    else [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:3];
                    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(64, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "llms mqa attention")) return 0;
                    calls++;
                    if (!verify) return 1;
                    vcalls++;   /* verify: fall through to the original into heads, then compare */
                    g_llms_mqa_verify_pending = 1; g_llms_mqa_vhead = vhead; g_llms_mqa_vmax = &vmax; g_llms_mqa_vrel = &vrel;
                }
            }
        }

        if (n_comp == 0) {
            /* The raw-only path stages through the same kernel when it
             * stages at all; a pending deferred kv task that nothing
             * consumes must run before the attention reads the cache. */
            if (g_kv_task.pending && !ds4_gpu_kv_norm_task_flush()) return 0;
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;

            if (!ds4_gpu_encode_flash_attention_raw_heads(cb,
                                                            heads,
                                                            sinks_buf,
                                                            (NSUInteger)sinks_inner,
                                                            q,
                                                            raw_kv,
                                                            n_raw,
                                                            raw_cap,
                                                            raw_start,
                                                            n_head,
                                                            head_dim)) {
                return 0;
            }

            if (!ds4_gpu_finish_command_buffer(cb, owned, "graph raw attention heads")) return 0;
            if (!llms_mqa_verify_finish(heads)) return 0;   /* llms MQA_ATTN verify */
            return 1;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!ds4_gpu_encode_flash_attention_gathered_heads(cb,
                                                             heads,
                                                             sinks_buf,
                                                             (NSUInteger)sinks_inner,
                                                             q,
                                                             raw_kv,
                                                             n_raw,
                                                             raw_cap,
                                                             raw_start,
                                                             comp_kv,
                                                             comp_kv_f16,
                                                             n_comp,
                                                             comp_mask,
                                                             use_mask,
                                                             n_head,
                                                             head_dim)) {
            return 0;
        }

        if (g_kv_task.pending) {
            static int warned;
            if (!warned) {
                warned = 1;
                fprintf(stderr, "ds4: deferred kv norm task was not consumed by the attention path\n");
            }
            if (!ds4_gpu_kv_norm_task_flush()) return 0;
        }
        if (!ds4_gpu_finish_command_buffer(cb, owned, "graph attention heads")) return 0;
    }
    if (!llms_mqa_verify_finish(heads)) return 0;   /* llms MQA_ATTN verify */

    return 1;
}

int ds4_gpu_swiglu_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *gate,
        const ds4_gpu_tensor *up,
        uint32_t                n,
        float                   clamp,
        float                   weight) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || n == 0) return 0;
    if (!isfinite(clamp) || clamp < 0.0f || !isfinite(weight)) return 0;

    @autoreleasepool {
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        id<MTLBuffer> upbuf = ds4_gpu_tensor_buffer(up);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t bytes = (uint64_t)n * sizeof(float);
        if (!gatebuf || !upbuf || !outbuf ||
            ds4_gpu_tensor_bytes(gate) < bytes ||
            ds4_gpu_tensor_bytes(up) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal SwiGLU received undersized buffers\n");
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glu_args args = {
            .ne00 = (int32_t)n,
            .nb01 = (uint64_t)n * sizeof(float),
            .ne10 = (int32_t)n,
            .nb11 = (uint64_t)n * sizeof(float),
            .ne0 = (int32_t)n,
            .nb1 = (uint64_t)n * sizeof(float),
            .i00 = 0,
            .i10 = 0,
            .alpha = weight,
            .limit = clamp,
        };
        NSUInteger nth = g_swiglu_flat_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > (NSUInteger)n) nth = (NSUInteger)n;
        if (nth == 0u) nth = 1u;
        const NSUInteger groups = ((NSUInteger)n + nth - 1u) / nth;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:(g_llms_swiglu_round && g_llms_swiglu_bf16_pipeline) ? g_llms_swiglu_bf16_pipeline : g_swiglu_flat_pipeline];   /* llms SWIGLU_BF16 */
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:gatebuf offset:ds4_gpu_tensor_offset(gate) atIndex:1];
        [enc setBuffer:upbuf offset:ds4_gpu_tensor_offset(up) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "SwiGLU")) return 0;
    }

    return 1;
}

int ds4_gpu_add_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *a,
        const ds4_gpu_tensor *b,
        uint32_t                n) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !a || !b || n == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> abuf = ds4_gpu_tensor_buffer(a);
        id<MTLBuffer> bbuf = ds4_gpu_tensor_buffer(b);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t bytes = (uint64_t)n * sizeof(float);
        if (!abuf || !bbuf || !outbuf ||
            ds4_gpu_tensor_bytes(a) < bytes ||
            ds4_gpu_tensor_bytes(b) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal tensor add received undersized buffers\n");
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_add_flat_args args = { .n = n };
        NSUInteger nth = g_add2_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > (NSUInteger)n) nth = (NSUInteger)n;
        if (nth == 0u) nth = 1u;
        const NSUInteger groups = ((NSUInteger)n + nth - 1u) / nth;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_add2_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:abuf offset:ds4_gpu_tensor_offset(a) atIndex:1];
        [enc setBuffer:bbuf offset:ds4_gpu_tensor_offset(b) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "tensor add")) return 0;
    }

    return 1;
}

int ds4_gpu_add3_tensor(
