/* llms IQ2_NSG (apply_ds4_iq2_nsg.py): simdgroups per threadgroup of the PREHALF pair pipelines, 4 or 8; canary = 4 with the row grid of 2 */
static int llms_iq2_nsg(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("LLMS_DS4_IQ2_NSG"); on = e && *e ? (!strcmp(e, "canary") ? -4 : atoi(e)) : 0; if (on != 4 && on != 8 && on != -4) on = 0;
                  if (on) fprintf(stderr, on < 0 ? "llms: iq2 nsg -- CANARY: 4 simdgroups, the last threadgroup of rows not dispatched\n" : "llms: iq2 nsg %d (simdgroups per threadgroup of the routed pair kernel)\n", on); }
    return on;
}
/* llms IQ2_W16 (apply_ds4_iq2_w16.py): the pair kernels' decode tables as two 16-byte loads per 8 weights. 1 on, -1 canary */
static uint64_t g_llms_w16_calls;
static void llms_iq2_w16_report(void) { fprintf(stderr, "llms iq2 w16: %llu gate/up calls with 16-byte table loads\n", (unsigned long long)g_llms_w16_calls); }
static int llms_iq2_w16(void) {
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_IQ2_W16"), *src = getenv("DS4_METAL_MOE_SOURCE"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : atoi(e) == 3 ? 3 : 1;   /* llms LIST_H2: 3 = W16 + packed half2 FMA chains */
                   if (on == 3 && !(src && llms_srckey(src, "cfdec2") != NULL)) { fprintf(stderr, "llms: LLMS_DS4_IQ2_W16=3 needs the *_cfdec2.metal source; 1 instead\n"); on = 1; }
                   if (on == 3) fprintf(stderr, "llms: iq2 w16 3 (the pair kernels' products as packed half2 FMA chains; rounding class; ALT w16f)\n");
