        NSUInteger                  ids_off,
        NSUInteger                  threadgroup_bytes,
        NSUInteger                  nsg,
        bool                        rows_per_group_is_nr0,
        uint32_t                    resource_kind,
        id<MTLBuffer>               overflow_resource) {
    if (!cb || !pipeline || !args || !entries ||
        (n_entries == 0 && !overflow_resource) ||
        n_entries > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || resource_kind > 2 ||
        !addrs || !src1 || !dst || !ids ||
        args->ne00 <= 0 || args->ne01 <= 0 ||
        args->nei0 <= 0 || args->nei0 > DS4_METAL_MAX_ROUTED_EXPERT_USED ||
        args->nei1 <= 0 ||
        args->ne02 <= 0 || args->ne02 > 384) {
        return 0;
    }
    for (uint32_t i = 0; i < n_entries; i++) {
        if (!entries[i] || !entries[i]->gate_buffer ||
            !entries[i]->up_buffer || !entries[i]->down_buffer) return 0;
    }
    if (n_entries && !ds4_gpu_stream_expert_cache_mark_entries_inflight(entries,
                                                           n_entries,
                                                           0)) {
        return 0;
    }

    const NSUInteger nr0 = (NSUInteger)args->nr0;
    const NSUInteger rows_per_group = rows_per_group_is_nr0 ? nr0 : nr0 * nsg;
    const NSUInteger row_groups = ((NSUInteger)args->ne01 + rows_per_group - 1u) / rows_per_group;
    const NSUInteger pairs = (NSUInteger)args->nei0 * (NSUInteger)args->nei1;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:pipeline];
    [enc setBytes:args length:sizeof(*args) atIndex:0];
    [enc setBuffer:addrs offset:0 atIndex:1];
    [enc setBuffer:src1  offset:src1_off atIndex:2];
    [enc setBuffer:dst   offset:dst_off  atIndex:3];
    [enc setBuffer:ids   offset:ids_off  atIndex:4];
    for (uint32_t i = 0; i < n_entries; i++) {
        id<MTLBuffer> b = resource_kind == 0 ? entries[i]->gate_buffer :
                          resource_kind == 1 ? entries[i]->up_buffer :
                                               entries[i]->down_buffer;
        [enc useResource:b usage:MTLResourceUsageRead];
    }
    if (overflow_resource) [enc useResource:overflow_resource usage:MTLResourceUsageRead];
    if (threadgroup_bytes != 0) {
        [enc setThreadgroupMemoryLength:threadgroup_bytes atIndex:0];
    }
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(row_groups, 1, pairs)
         threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* llms LLMS_DS4_Q2K_DOWN_NR8 (apply_ds4_q2k_down_nr8.py): 8 rows per simdgroup in the routed down kernel; the kernel exists
 * only in the replacement sources named *_d8.metal. 1 on, 2 canary (grid for 16 rows). */
static int llms_q2k_down_nr8(void) {
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("LLMS_DS4_Q2K_DOWN_NR8"), *src = getenv("DS4_METAL_MOE_SOURCE");
        const int want = e && *e && *e != '0';
        on = want && src && llms_srckey(src, "_d8") != NULL ? (!strcmp(e, "canary") ? 2 : 1) : 0;
        if (want) fprintf(stderr, on == 2 ? "llms: routed down kernel with 8 rows per simdgroup -- CANARY: grid sized for 16 rows\n" :
                                  on ? "llms: routed down kernel with 8 rows per simdgroup\n" :
                                       "llms: LLMS_DS4_Q2K_DOWN_NR8 ignored: DS4_METAL_MOE_SOURCE does not name a *_d8.metal source\n");
        if (want && !on) llms_guard_fail(LLMS_G_NAME);
    }
    return on;
}
