                   if (on && !(src && llms_srckey(src, "q4x2") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_DOWN_TOKX ignored: DS4_METAL_MOE_SOURCE does not name a *q4x2.metal source\n"), LLMS_G_NAME); on = 0; }
                   if (on) { fprintf(stderr, on < 0 ? "llms: down tokx -- CANARY: the stock kernel on the swapped grid\n" : "llms: down tokx (the routed down grid with x = token)\n"); atexit(llms_tokx_report); } }
