                   if (on && !(src && llms_srckey(src, "ctx") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_DOWN_COLTOKX ignored: DS4_METAL_MOE_SOURCE does not name a *ctx* source\n"), LLMS_G_NAME); on = 0; }
                   if (on) { fprintf(stderr, on < 0 ? "llms: down coltokx -- CANARY: the last token of each call is not dispatched\n" : "llms: down coltokx (the column down kernel on a token-fastest grid; bit-exact against DOWN_COL)\n"); atexit(llms_down_coltokx_report); } }
