static ds4_gpu_bin_args ds4_gpu_make_moe_add_args(
        uint32_t out_dim,
        uint32_t n_tokens,
        uint64_t src0_token_stride,
        uint64_t src1_token_stride,
        uint64_t dst_token_stride) {
    return (ds4_gpu_bin_args) {
        .ne00 = (int32_t)out_dim,
        .ne01 = (int32_t)n_tokens,
        .ne02 = 1,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = src0_token_stride,
        .nb02 = (uint64_t)n_tokens * src0_token_stride,
        .nb03 = (uint64_t)n_tokens * src0_token_stride,
        .ne10 = (int32_t)out_dim,
        .ne11 = (int32_t)n_tokens,
        .ne12 = 1,
        .ne13 = 1,
        .nb10 = sizeof(float),
        .nb11 = src1_token_stride,
        .nb12 = (uint64_t)n_tokens * src1_token_stride,
        .nb13 = (uint64_t)n_tokens * src1_token_stride,
        .ne0 = (int32_t)out_dim,
        .ne1 = (int32_t)n_tokens,
        .ne2 = 1,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = dst_token_stride,
        .nb2 = (uint64_t)n_tokens * dst_token_stride,
        .nb3 = (uint64_t)n_tokens * dst_token_stride,
        .offs = 0,
        .o1 = { 0 },
    };
}

static int ds4_gpu_encode_moe_sum_experts(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        experts,
        NSUInteger           experts_off,
        id<MTLBuffer>        out,
        NSUInteger           out_off,
        uint32_t             out_dim,
        uint32_t             n_expert,
        uint32_t             n_tokens) {
    if (!cb || !experts || !out || out_dim == 0 || n_expert < 2 || n_tokens == 0) return 0;

    const uint64_t out_row_bytes = (uint64_t)out_dim * sizeof(float);
    const uint64_t expert_token_stride = (uint64_t)n_expert * out_row_bytes;

    if (n_expert == 6 &&
        ds4_gpu_encode_moe_sum6(cb,
                                  experts,
                                  experts_off,
                                  out,
                                  out_off,
                                  out_dim,
                                  n_tokens)) {
        return 1;
    }

    if (n_expert == 8 &&
        ds4_gpu_encode_moe_sum8(cb,
                                  experts,
                                  experts_off,
                                  out,
                                  out_off,
                                  out_dim,
                                  n_tokens)) {
        return 1;
    }

    ds4_gpu_bin_args first =
        ds4_gpu_make_moe_add_args(out_dim, n_tokens, expert_token_stride, expert_token_stride, out_row_bytes);
    if (!ds4_gpu_encode_bin_f32_rows(cb,
                                       g_add_pipeline,
                                       &first,
                                       experts,
                                       experts_off,
                                       experts,
                                       experts_off + (NSUInteger)out_row_bytes,
                                       out,
                                       out_off)) {
        return 0;
    }

    ds4_gpu_bin_args accum =
        ds4_gpu_make_moe_add_args(out_dim, n_tokens, out_row_bytes, expert_token_stride, out_row_bytes);
    for (uint32_t slot = 2; slot < n_expert; slot++) {
        if (!ds4_gpu_encode_bin_f32_rows(cb,
                                           g_add_pipeline,
                                           &accum,
                                           out,
                                           out_off,
                                           experts,
                                           experts_off + (NSUInteger)((uint64_t)slot * out_row_bytes),
                                           out,
                                           out_off)) {
            return 0;
        }
    }
    return 1;
}

static int ds4_gpu_encode_get_rows_i32_token_rows(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        table,
        NSUInteger           table_off,
        id<MTLBuffer>        tokens,
        NSUInteger           tokens_off,
        const int32_t       *token_inline,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        uint32_t             hash_rows,
        uint32_t             n_cols,
        uint32_t             n_tokens) {
    if (!cb || !table || !selected || hash_rows == 0 || n_cols == 0 || n_tokens == 0) return 0;
    if (!tokens && !token_inline) return 0;

    const uint64_t table_row_bytes = (uint64_t)n_cols * sizeof(int32_t);
    const uint64_t token_bytes = (uint64_t)n_tokens * sizeof(int32_t);
    ds4_gpu_get_rows_args args = {
        .ne00t = (int64_t)n_cols,
        .ne00 = (int64_t)n_cols,
        .nb01 = table_row_bytes,
        .nb02 = (uint64_t)hash_rows * table_row_bytes,
        .nb03 = (uint64_t)hash_rows * table_row_bytes,
        .ne10 = (int32_t)n_tokens,
        .nb10 = sizeof(int32_t),
        .nb11 = token_bytes,
        .nb12 = token_bytes,
        .nb1 = table_row_bytes,
        .nb2 = (uint64_t)n_tokens * table_row_bytes,
        .nb3 = (uint64_t)n_tokens * table_row_bytes,
    };

    NSUInteger nth = (NSUInteger)n_cols;
    const NSUInteger max_threads = g_get_rows_i32_pipeline.maxTotalThreadsPerThreadgroup;
    if (nth > max_threads) nth = max_threads;
    if (nth == 0) nth = 1u;
    const NSUInteger nw0 = ((NSUInteger)n_cols + nth - 1u) / nth;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_get_rows_i32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:table offset:table_off atIndex:1];
    if (tokens) {
        [enc setBuffer:tokens offset:tokens_off atIndex:2];
    } else {
        [enc setBytes:token_inline length:sizeof(*token_inline) atIndex:2];
    }
    [enc setBuffer:selected offset:selected_off atIndex:3];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(nw0 * n_tokens, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_get_rows_f32_router_weights(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        probs,
        NSUInteger           probs_off,
        id<MTLBuffer>        selected,
        NSUInteger           selected_off,
        id<MTLBuffer>        weights,
        NSUInteger           weights_off,
        uint32_t             n_expert,
        uint32_t             n_expert_used,
        uint32_t             n_tokens) {
    if (!cb || !probs || !selected || !weights || n_expert == 0 || n_expert_used == 0 || n_tokens == 0) return 0;

    const uint64_t probs_token_bytes = (uint64_t)n_expert * sizeof(float);
    const uint64_t selected_row_bytes = (uint64_t)n_expert_used * sizeof(int32_t);
    const uint64_t weights_row_bytes = (uint64_t)n_expert_used * sizeof(float);
    ds4_gpu_get_rows_args args = {
        .ne00t = 1,
        .ne00 = 1,
        .nb01 = sizeof(float),
        .nb02 = probs_token_bytes,
        .nb03 = (uint64_t)n_tokens * probs_token_bytes,
        .ne10 = (int64_t)n_expert_used,
        .nb10 = sizeof(int32_t),
        .nb11 = selected_row_bytes,
        .nb12 = (uint64_t)n_tokens * selected_row_bytes,
        .nb1 = sizeof(float),
        .nb2 = weights_row_bytes,
        .nb3 = (uint64_t)n_tokens * weights_row_bytes,
    };

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_get_rows_f32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:probs offset:probs_off atIndex:1];
    [enc setBuffer:selected offset:selected_off atIndex:2];
    [enc setBuffer:weights offset:weights_off atIndex:3];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_expert_used, n_tokens, 1)
         threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

static int ds4_gpu_encode_sum_rows_f32(
        id<MTLCommandBuffer> cb,
        id<MTLBuffer>        src,
        NSUInteger           src_off,
        id<MTLBuffer>        dst,
        NSUInteger           dst_off,
        uint32_t             width,
        uint32_t             rows) {
    if (!cb || !src || !dst || width == 0 || rows == 0) return 0;

    const uint64_t src_row_bytes = (uint64_t)width * sizeof(float);
    ds4_gpu_kargs_sum_rows args = {
        .ne00 = (int64_t)width,
        .ne01 = (int64_t)rows,
        .ne02 = 1,
        .ne03 = 1,
        .nb00 = sizeof(float),
        .nb01 = src_row_bytes,
        .nb02 = (uint64_t)rows * src_row_bytes,
        .nb03 = (uint64_t)rows * src_row_bytes,
        .ne0 = 1,
        .ne1 = (int64_t)rows,
        .ne2 = 1,
        .ne3 = 1,
        .nb0 = sizeof(float),
        .nb1 = sizeof(float),
        .nb2 = (uint64_t)rows * sizeof(float),
        .nb3 = (uint64_t)rows * sizeof(float),
    };

    NSUInteger nth = 32u;
    const NSUInteger max_threads = g_sum_rows_f32_f32_pipeline.maxTotalThreadsPerThreadgroup;
    while (nth < (NSUInteger)args.ne00 && nth < max_threads) nth *= 2u;
    if (nth > max_threads) nth = max_threads;
    if (nth > (NSUInteger)args.ne00) nth = (NSUInteger)args.ne00;
    if (nth == 0) nth = 1u;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_sum_rows_f32_f32_pipeline];
    [enc setBytes:&args length:sizeof(args) atIndex:0];
    [enc setBuffer:src offset:src_off atIndex:1];
    [enc setBuffer:dst offset:dst_off atIndex:2];
    [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(rows, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);
    return 1;
}

/* llms ROUTER41 (apply_router41.py): the DS4.1 one-token router selection in one dispatch (ALT 'r41') */
static id<MTLComputePipelineState> g_llms_r41_ps; static int g_llms_r41 = -1; static uint64_t g_llms_r41_calls;
static int llms_alt_off(const char *name);
static int llms_router41_encode(id<MTLCommandBuffer> cb, id<MTLBuffer> logitsbuf, NSUInteger logits_off, id<MTLBuffer> biasbuf, NSUInteger bias_off,
                                id<MTLBuffer> probsbuf, NSUInteger probs_off, id<MTLBuffer> selectedbuf, NSUInteger selected_off,
                                id<MTLBuffer> weightsbuf, NSUInteger weights_off, float scale, uint32_t n_rows) {   /* llms ROUTER41_ROWS: n_rows */
    if (g_llms_r41 < 0) {
        g_llms_r41 = 0; const char *e = getenv("LLMS_DS4_ROUTER41");
        if (e && *e && *e != '0' && g_device) {
            NSError *err = nil;
            NSString *llms_r41_source = @"#include <metal_stdlib>\nusing namespace metal;\nkernel void llms_router41(constant float &scale [[buffer(0)]], constant uint &canary [[buffer(1)]],\n                          device const float *logits [[buffer(2)]], device const float *bias [[buffer(3)]],\n                          device float *probs [[buffer(4)]], device int *selected [[buffer(5)]], device float *weights [[buffer(6)]],\n                          uint tid [[thread_position_in_threadgroup]], ushort tiisg [[thread_index_in_simdgroup]], ushort sgitg [[simdgroup_index_in_threadgroup]],\n                          uint row [[threadgroup_position_in_grid]]) {\n    logits += row * 384u; probs += row * 384u; selected += row * 6u; weights += row * 6u;   /* llms ROUTER41_ROWS: row 0 is the one-row kernel */\n    threadgroup float sv[384]; threadgroup float pv[384]; threadgroup int sel[8];\n    if (tid < 96u) {   /* the float4 unary kernels' expressions (kernel_unary_f32_f32_4: softplus, then sqrt) */\n        const float4 x = ((device const float4 *)logits)[tid];\n        const float4 ex = exp(x);\n        const float4 em = min(ex, (float4)0.03125f);\n        const float4 poly = em*(1.0f - em*(0.5f - em*(1.0f/3.0f - 0.25f*em)));\n        const float4 sp = (float4) select(select(log(1 + ex), poly, ex < (float4)0.03125f), x, x > 20);\n        const float4 p = (float4) sqrt(sp);\n        ((device float4 *)probs)[tid] = p;\n        for (uint k = 0; k < 4u; k++) { pv[4u * tid + k] = p[k]; sv[4u * tid + k] = p[k] + bias[4u * tid + k]; }\n    }\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n#ifdef LLMS_ROUTER_SELECT6\n    threadgroup float group_max[12];\n    threadgroup uint group_id[12];\n    float s = sv[tid];\n    for (uint k = 0; k < 6; ++k) {\n        const float m = simd_max(s);\n        const uint i = simd_min(s == m ? tid : 0xffffffffu);\n        if (tiisg == 0) { group_max[sgitg] = m; group_id[sgitg] = i; }\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n        if (sgitg == 0) {\n            const float gm = tiisg < 12 ? group_max[tiisg] : -INFINITY;\n            const float best = simd_max(gm);\n            const uint gi = tiisg < 12 && gm == best ? group_id[tiisg] : 0xffffffffu;\n            const uint winner = simd_min(gi);\n            if (tiisg == 0) sel[k] = (int)winner;\n        }\n        threadgroup_barrier(mem_flags::mem_threadgroup);\n        if (tid == (uint)sel[k]) s = -INFINITY;\n    }\n#else\n    const float s = sv[tid];\n    uint r = 0;\n    for (uint j = 0; j < 384u; j++) { const float v = sv[j]; r += (v > s || (v == s && j < tid)) ? 1u : 0u; }\n    if (r < 6u) sel[r] = (int)tid;\n#endif\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    /* 10:1x v2 (the first version moved the text): each later step materialized as its own kernel did -- the row sum as a simd_sum\n       over 6 ACTIVE lanes (sum_rows ran 6 threads), then clamp, divide and scale each through threadgroup memory (no fusion) */\n    threadgroup float wq[8]; threadgroup float ssh[1];\n    if (sgitg == 0 && tiisg < 6) {\n        float w = pv[sel[tiisg]];\n        if (canary && tiisg == 5) w = 0.0f;\n        wq[tiisg] = w;\n        const float S = simd_sum(w);\n        if (tiisg == 0) ssh[0] = S;\n    }\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    if (tid == 0) ssh[0] = clamp(ssh[0], 6.103515625e-5f, INFINITY);\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    if (tid < 6u) wq[tid] = wq[tid] / ssh[0];\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n    if (tid < 6u) { selected[tid] = sel[tid]; weights[tid] = wq[tid] * scale; }\n}\n";
            const char *llms_sel6 = getenv("LLMS_DS4_ROUTER_SELECT6");
            if (llms_sel6 && *llms_sel6 && *llms_sel6 != '0') {
                llms_r41_source = [@"#define LLMS_ROUTER_SELECT6 1\n" stringByAppendingString:llms_r41_source];
                fprintf(stderr, "llms: router select6 (six winner reductions)\n");
            }
            id<MTLLibrary> lib = [g_device newLibraryWithSource:llms_r41_source options:[MTLCompileOptions new] error:&err];
            id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_router41"] : nil;
            g_llms_r41_ps = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
            if (g_llms_r41_ps && g_llms_r41_ps.maxTotalThreadsPerThreadgroup >= 384u) {
                g_llms_r41 = !strcmp(e, "canary") ? 2 : 1;
                fprintf(stderr, g_llms_r41 == 2 ? "llms: router41 -- CANARY: the 6th pick's weight dropped\n" : "llms: router41 (the DS4.1 router selection in one dispatch)\n");
                atexit_b(^{ fprintf(stderr, "llms router41: %llu calls\n", (unsigned long long)g_llms_r41_calls); });
            } else fprintf(stderr, "llms: router41 could not start (%s)\n", err ? err.localizedDescription.UTF8String : "pipeline");
        }
    }
    if (g_llms_r41 <= 0 || llms_alt_off("r41")) return 0;
    const uint32_t canary = g_llms_r41 == 2 ? 1u : 0u;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_llms_r41_ps];
    [enc setBytes:&scale length:sizeof(scale) atIndex:0];
    [enc setBytes:&canary length:sizeof(canary) atIndex:1];
    [enc setBuffer:logitsbuf offset:logits_off atIndex:2];
    [enc setBuffer:biasbuf offset:bias_off atIndex:3];
    [enc setBuffer:probsbuf offset:probs_off atIndex:4];
    [enc setBuffer:selectedbuf offset:selected_off atIndex:5];
    [enc setBuffer:weightsbuf offset:weights_off atIndex:6];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_rows ? n_rows : 1u, 1, 1) threadsPerThreadgroup:MTLSizeMake(384, 1, 1)];   /* llms ROUTER41_ROWS */
    ds4_gpu_end_compute_encoder(cb, enc);
    g_llms_r41_calls++;
    return 1;
}
static int ds4_gpu_encode_router_select(
        id<MTLCommandBuffer>  cb,
        ds4_gpu_tensor     *selected,
        ds4_gpu_tensor     *weights,
        ds4_gpu_tensor     *probs,
        id<MTLBuffer>         logitsbuf,
        NSUInteger            logits_off,
        id<MTLBuffer>         biasbuf,
        NSUInteger            bias_off,
        id<MTLBuffer>         hashbuf,
        NSUInteger            hash_off,
        id<MTLBuffer>         tokensbuf,
        NSUInteger            tokens_off,
        id<MTLBuffer>         visual_biasbuf,
        NSUInteger            visual_bias_off,
        const int32_t        *single_token,
        uint32_t              hash_rows,
        uint32_t              vocab_size,
        uint32_t              n_tokens,
        uint32_t              n_expert,
        uint32_t              n_expert_used,
        float                 expert_weight_scale,
        bool                  has_bias,
        bool                  hash_mode,
        bool                  mixed_visual) {
    id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
    id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
    id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
    const NSUInteger selected_off = ds4_gpu_tensor_offset(selected);
    const NSUInteger weights_off = ds4_gpu_tensor_offset(weights);
    const NSUInteger probs_off = ds4_gpu_tensor_offset(probs);

    if (!cb || !selectedbuf || !weightsbuf || !probsbuf || !logitsbuf ||
        (mixed_visual && (!visual_biasbuf || !tokensbuf || single_token)) ||
        n_tokens == 0 || n_expert == 0 || n_expert_used == 0) return 0;

    const NSUInteger probs_bytes = (NSUInteger)n_tokens * (NSUInteger)n_expert * sizeof(float);
    const bool flash_router_fast_path =
        n_expert == 256u &&
        n_expert_used == 6u &&
        fabsf(expert_weight_scale - 1.5f) <= 1.0e-6f;

    static int llms_r41r = -1; static uint64_t llms_r41r_n;   /* llms ROUTER41_ROWS */
    if (llms_r41r < 0) { const char *e = getenv("LLMS_DS4_ROUTER41_ROWS"); llms_r41r = e && *e && *e != '0';
                         if (llms_r41r) atexit_b(^{ fprintf(stderr, "llms router41 rows: %llu multi-row selections\n", (unsigned long long)llms_r41r_n); }); }
    if (n_expert == 384u && n_expert_used == 6u && (n_tokens == 1 || (llms_r41r && n_tokens <= 16u && !llms_alt_off("r41r"))) && !mixed_visual && !hash_mode && has_bias && biasbuf && !g_quality_mode &&
        llms_router41_encode(cb, logitsbuf, logits_off, biasbuf, bias_off, probsbuf, probs_off, selectedbuf, selected_off, weightsbuf, weights_off,
                             expert_weight_scale, n_tokens)) { if (n_tokens > 1) llms_r41r_n++; return 1; }   /* llms ROUTER41; llms ROUTER41_ROWS */
    int ok = 0;
    if (flash_router_fast_path && !mixed_visual &&
        !g_quality_mode && n_tokens == 1 &&
        getenv("DS4_METAL_DISABLE_ROUTER_SELECT_FUSION") == NULL) {
        const bool pre_m5_device =
            ds4_gpu_device_is_pre_m5_apple_silicon();
        const bool use_simd_finalize =
            !hash_mode &&
            g_dsv4_router_finalize_one_simd_pipeline != nil &&
            g_dsv4_router_finalize_one_simd_pipeline.threadExecutionWidth == 32u &&
            g_dsv4_router_finalize_one_simd_pipeline.maxTotalThreadsPerThreadgroup >= 256u &&
            (pre_m5_device ||
             ds4_gpu_device_name_contains("M5")) &&
            (!pre_m5_device ||
             getenv("DS4_METAL_DISABLE_PRE_M5_ROUTER_SIMD_FINALIZE") == NULL);
        const bool use_simd_weights_fusion =
            use_simd_finalize &&
            g_dsv4_router_finalize_weights_one_simd_pipeline != nil &&
            g_dsv4_router_finalize_weights_one_simd_pipeline.threadExecutionWidth == 32u &&
            g_dsv4_router_finalize_weights_one_simd_pipeline.maxTotalThreadsPerThreadgroup >= 256u &&
            (pre_m5_device ||
             ds4_gpu_device_name_contains("M5")) &&
            (!pre_m5_device ||
             getenv("DS4_METAL_DISABLE_PRE_M5_ROUTER_SIMD_WEIGHTS_FUSION") == NULL);
        const bool use_pre_m5_transform_finalize_fusion_default =
            !g_ssd_streaming_mode &&
            (pre_m5_device || ds4_gpu_device_name_contains("M5")) &&
            getenv("DS4_METAL_DISABLE_PRE_M5_ROUTER_TRANSFORM_FINALIZE_FUSION") == NULL;
        const bool use_transform_finalize_fusion =
            use_simd_weights_fusion &&
            !hash_mode &&
            use_pre_m5_transform_finalize_fusion_default &&
            (pre_m5_device ||
             ds4_gpu_device_name_contains("M5")) &&
            g_dsv4_router_transform_finalize_weights_one_simd_pipeline != nil &&
            g_dsv4_router_transform_finalize_weights_one_simd_pipeline.threadExecutionWidth == 32u &&
            g_dsv4_router_transform_finalize_weights_one_simd_pipeline.maxTotalThreadsPerThreadgroup >= 256u;
        id<MTLComputePipelineState> softplus_sqrt_pipeline =
            use_transform_finalize_fusion
                ? nil
                : ds4_gpu_hot_pipeline(g_dsv4_softplus_sqrt_pipeline,
                                          "kernel_dsv4_softplus_sqrt_f32_4");
        id<MTLComputePipelineState> router_finalize_pipeline =
            ds4_gpu_hot_pipeline(
                use_transform_finalize_fusion
                    ? g_dsv4_router_transform_finalize_weights_one_simd_pipeline
                    : use_simd_weights_fusion
                    ? g_dsv4_router_finalize_weights_one_simd_pipeline
                    : use_simd_finalize
                    ? g_dsv4_router_finalize_one_simd_pipeline
                    : g_dsv4_router_finalize_one_pipeline,
                use_transform_finalize_fusion
                    ? "kernel_dsv4_router_transform_finalize_weights_one_simd"
                    : use_simd_weights_fusion
                    ? "kernel_dsv4_router_finalize_weights_one_simd"
                    : use_simd_finalize
                    ? "kernel_dsv4_router_finalize_one_simd"
                    : "kernel_dsv4_router_finalize_one");
        id<MTLComputePipelineState> router_weights_pipeline = use_simd_weights_fusion
            ? nil
            : ds4_gpu_hot_pipeline(g_dsv4_router_weights_one_pipeline,
                                      "kernel_dsv4_router_weights_one");
        if ((!use_transform_finalize_fusion && !softplus_sqrt_pipeline) ||
            !router_finalize_pipeline ||
            (!use_simd_weights_fusion && !router_weights_pipeline)) return 0;

        if (!use_transform_finalize_fusion) {
            ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 softplus_sqrt_pipeline,
                                                 logitsbuf,
                                                 logits_off,
                                                 probsbuf,
                                                 probs_off,
                                                 n_expert,
                                                 1,
                                                 1,
                                                 0.0f,
                                                 0.0f);
            if (!ok) return 0;
        }

        const bool use_token_buffer = single_token == NULL;
        ds4_gpu_dsv4_router_select_one_args args = {
            .has_bias = has_bias ? 1u : 0u,
            .hash_mode = hash_mode ? 1u : 0u,
            .use_token_buffer = use_token_buffer ? 1u : 0u,
            .token = single_token ? (uint32_t)*single_token : 0u,
            .hash_rows = hash_rows,
        };

        const float zero_f32 = 0.0f;
        const int32_t zero_i32 = 0;
        if ((has_bias && !biasbuf) ||
            (hash_mode && !hashbuf) ||
            (use_token_buffer && !tokensbuf)) {
            return 0;
        }

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_finalize_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        if (use_transform_finalize_fusion) {
            [enc setBuffer:logitsbuf offset:logits_off atIndex:1];
            [enc setBuffer:probsbuf offset:probs_off atIndex:2];
            if (has_bias) {
                [enc setBuffer:biasbuf offset:bias_off atIndex:3];
            } else {
                [enc setBytes:&zero_f32 length:sizeof(zero_f32) atIndex:3];
            }
            [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:4];
            if (use_token_buffer) {
                [enc setBuffer:tokensbuf offset:tokens_off atIndex:5];
            } else {
                [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:5];
            }
            [enc setBuffer:selectedbuf offset:selected_off atIndex:6];
            [enc setBuffer:weightsbuf offset:weights_off atIndex:7];
        } else {
            [enc setBuffer:probsbuf offset:probs_off atIndex:1];
            if (has_bias) {
                [enc setBuffer:biasbuf offset:bias_off atIndex:2];
            } else {
                [enc setBytes:&zero_f32 length:sizeof(zero_f32) atIndex:2];
            }
            if (hash_mode) {
                [enc setBuffer:hashbuf offset:hash_off atIndex:3];
            } else {
                [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:3];
            }
            if (use_token_buffer) {
                [enc setBuffer:tokensbuf offset:tokens_off atIndex:4];
            } else {
                [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:4];
            }
            [enc setBuffer:selectedbuf offset:selected_off atIndex:5];
            if (use_simd_weights_fusion) {
                [enc setBuffer:weightsbuf offset:weights_off atIndex:6];
            }
        }
        const NSUInteger router_finalize_scratch_bytes = use_simd_finalize
            ? 2u * (256u * sizeof(float) + 256u * sizeof(int32_t))
            : 256u * sizeof(float) + 256u * sizeof(int32_t);
        [enc setThreadgroupMemoryLength:router_finalize_scratch_bytes atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (use_simd_weights_fusion) return 1;

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_weights_pipeline];
        [enc setBuffer:probsbuf offset:probs_off atIndex:0];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:1];
        [enc setBuffer:weightsbuf offset:weights_off atIndex:2];
        [llms_bar(enc) dispatchThreads:MTLSizeMake(6, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(6, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }

    if (flash_router_fast_path && !mixed_visual && !g_quality_mode && n_tokens == 1) {
        id<MTLComputePipelineState> softplus_sqrt_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_softplus_sqrt_pipeline,
                                    "kernel_dsv4_softplus_sqrt_f32_4");
        ok = softplus_sqrt_pipeline &&
             ds4_gpu_encode_unary_f32_rows(cb,
                                             softplus_sqrt_pipeline,
                                             logitsbuf,
                                             logits_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             1,
                                             1,
                                             0.0f,
                                             0.0f);
    } else {
        ok = ds4_gpu_encode_unary_f32_rows(cb,
                                             g_unary_softplus_pipeline,
                                             logitsbuf,
                                             logits_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             n_tokens,
                                             1,
                                             0.0f,
                                             0.0f) &&
             ds4_gpu_encode_unary_f32_rows(cb,
                                             g_unary_sqrt_pipeline,
                                             probsbuf,
                                             probs_off,
                                             probsbuf,
                                             probs_off,
                                             n_expert,
                                             n_tokens,
                                             1,
                                             0.0f,
                                             0.0f);
    }
    if (!ok) return 0;

    if (mixed_visual) {
        if (!g_dsv4_router_select_visual_batch_pipeline ||
            n_expert != 256u || n_expert_used != 6u) return 0;
        ds4_gpu_dsv4_router_select_visual_args args = {
            .hash_rows = hash_rows,
            .vocab_size = vocab_size,
            .n_tokens = n_tokens,
            .has_bias = has_bias ? 1u : 0u,
            .hash_mode = hash_mode ? 1u : 0u,
        };
        const float zero_f32 = 0.0f;
        const int32_t zero_i32 = 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_router_select_visual_batch_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:probsbuf offset:probs_off atIndex:1];
        if (has_bias) [enc setBuffer:biasbuf offset:bias_off atIndex:2];
        else [enc setBytes:&zero_f32 length:sizeof(zero_f32) atIndex:2];
        [enc setBuffer:visual_biasbuf offset:visual_bias_off atIndex:3];
        if (hash_mode) [enc setBuffer:hashbuf offset:hash_off atIndex:4];
        else [enc setBytes:&zero_i32 length:sizeof(zero_i32) atIndex:4];
        [enc setBuffer:tokensbuf offset:tokens_off atIndex:5];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:6];
        [enc setThreadgroupMemoryLength:
                256u * (sizeof(float) + sizeof(int32_t)) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        ok = 1;
    } else if (hash_mode) {
        ok = ds4_gpu_encode_get_rows_i32_token_rows(cb,
                                                      hashbuf,
                                                      hash_off,
                                                      tokensbuf,
                                                      tokens_off,
                                                      single_token,
                                                      selectedbuf,
                                                      selected_off,
                                                      hash_rows,
                                                      n_expert_used,
                                                      n_tokens);
    } else {
        ds4_gpu_tensor *score_tensor = probs;
        DS4MetalTensor *selection_view = nil;

        if (has_bias) {
            if (!biasbuf ||
                !ds4_gpu_ensure_scratch_buffer(&g_router_selection_buffer,
                                                 &g_router_selection_bytes,
                                                 probs_bytes,
                                                 "ds4_router_selection")) {
                return 0;
            }

            ds4_gpu_bin_args add_args = ds4_gpu_make_bin_rows_args(n_expert, n_tokens, n_expert);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_add_pipeline,
                                               &add_args,
                                               probsbuf,
                                               probs_off,
                                               biasbuf,
                                               bias_off,
                                               g_router_selection_buffer,
                                               0);
            if (!ok) return 0;

            selection_view = [DS4MetalTensor new];
            selection_view.buffer = g_router_selection_buffer;
            selection_view.offset = 0;
            selection_view.bytes = probs_bytes;
            selection_view.owner = 0;
            score_tensor = (__bridge ds4_gpu_tensor *)selection_view;
        }

        ok = ds4_gpu_indexer_topk_tensor(selected, score_tensor, n_expert, n_tokens, n_expert_used) != 0;
    }
    if (!ok) return 0;

    const bool use_batch_weights_fusion =
        flash_router_fast_path && !g_quality_mode && n_tokens > 1u &&
        g_dsv4_router_weights_batch_pipeline != nil &&
        ds4_gpu_device_name_contains("M3") &&
        getenv("DS4_METAL_DISABLE_ROUTER_WEIGHTS_BATCH_FUSION") == NULL &&
        getenv("DS4_METAL_DISABLE_ROUTER_SELECT_FUSION") == NULL;
    if (use_batch_weights_fusion) {
        const float scale = expert_weight_scale;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_dsv4_router_weights_batch_pipeline];
        [enc setBytes:&scale length:sizeof(scale) atIndex:0];
        [enc setBuffer:probsbuf offset:probs_off atIndex:1];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:2];
        [enc setBuffer:weightsbuf offset:weights_off atIndex:3];
        [enc setThreadgroupMemoryLength:40u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(6, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }

    if (flash_router_fast_path && !g_quality_mode && n_tokens == 1) {
        id<MTLComputePipelineState> router_weights_pipeline =
            ds4_gpu_hot_pipeline(g_dsv4_router_weights_one_pipeline,
                                    "kernel_dsv4_router_weights_one");
        if (!router_weights_pipeline) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:router_weights_pipeline];
        [enc setBuffer:probsbuf offset:probs_off atIndex:0];
        [enc setBuffer:selectedbuf offset:selected_off atIndex:1];
        [enc setBuffer:weightsbuf offset:weights_off atIndex:2];
        [llms_bar(enc) dispatchThreads:MTLSizeMake(6, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(6, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        return 1;
    }

    const NSUInteger sum_bytes = (NSUInteger)n_tokens * sizeof(float);
    if (!ds4_gpu_ensure_scratch_buffer(&g_router_weight_sum_buffer,
                                         &g_router_weight_sum_bytes,
                                         sum_bytes,
                                         "ds4_router_weight_sum")) {
        return 0;
    }

    ok = ds4_gpu_encode_get_rows_f32_router_weights(cb,
                                                      probsbuf,
                                                      probs_off,
                                                      selectedbuf,
                                                      selected_off,
                                                      weightsbuf,
                                                      weights_off,
                                                      n_expert,
                                                      n_expert_used,
                                                      n_tokens) &&
         ds4_gpu_encode_sum_rows_f32(cb,
                                       weightsbuf,
                                       weights_off,
                                       g_router_weight_sum_buffer,
                                       0,
                                       n_expert_used,
                                       n_tokens) &&
         ds4_gpu_encode_unary_f32_rows(cb,
                                         g_unary_clamp_pipeline,
                                         g_router_weight_sum_buffer,
                                         0,
                                         g_router_weight_sum_buffer,
                                         0,
                                         1,
                                         n_tokens,
                                         0,
                                         6.103515625e-5f,
                                         ds4_gpu_positive_infinity());
    if (!ok) return 0;

    ds4_gpu_bin_args div_args = ds4_gpu_make_bin_rowwise_scalar_args(n_expert_used, n_tokens);
    const float scale = expert_weight_scale;
    ds4_gpu_bin_args scale_args = ds4_gpu_make_bin_rows_args(n_expert_used, n_tokens, 1);

    ok = ds4_gpu_encode_bin_f32_rows(cb,
                                       g_bin_div_row_pipeline,
                                       &div_args,
                                       weightsbuf,
                                       weights_off,
                                       g_router_weight_sum_buffer,
                                       0,
                                       weightsbuf,
                                       weights_off);
    if (!ok) return 0;

    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
    [enc setComputePipelineState:g_bin_mul_scalar_pipeline];
    [enc setBytes:&scale_args length:sizeof(scale_args) atIndex:0];
    [enc setBuffer:weightsbuf offset:weights_off atIndex:1];
    [enc setBytes:&scale length:sizeof(scale) atIndex:2];
    [enc setBuffer:weightsbuf offset:weights_off atIndex:3];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)scale_args.ne1,
                                          (NSUInteger)scale_args.ne2,
                                          (NSUInteger)scale_args.ne3)
         threadsPerThreadgroup:MTLSizeMake(ds4_gpu_bin_threads(n_expert_used, g_bin_mul_scalar_pipeline), 1, 1)];
    ds4_gpu_end_compute_encoder(cb, enc);

    return 1;
}

int ds4_gpu_glm_kv_lora_rms_norm_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *kv_raw,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              n_tokens,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        float                 eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !kv_raw || !model_map ||
        n_tokens == 0 || kv_raw_dim == 0 || kv_lora_dim == 0 ||
        kv_lora_dim > kv_raw_dim || (kv_lora_dim & 3u) != 0 ||
        !isfinite(eps) || eps < 0.0f) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(kv_raw);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t raw_bytes = (uint64_t)n_tokens * kv_raw_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * kv_lora_dim * sizeof(float);
        const uint64_t weight_bytes = (uint64_t)kv_lora_dim * sizeof(float);
        if (!rawbuf || !outbuf ||
            ds4_gpu_tensor_bytes(kv_raw) < raw_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal GLM KV RMS norm received undersized buffers\n");
            return 0;
        }
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal GLM KV RMS norm weight range is outside the mapped model\n");
            return 0;
        }

        const bool exact_decode_weight_view =
            n_tokens == 1u &&
            weight_bytes <= (1ull << 20) &&
            getenv("DS4_METAL_DISABLE_DECODE_NORM_EXACT_VIEWS") == NULL;
        uint64_t weight_inner = 0;
        id<MTLBuffer> weightbuf = exact_decode_weight_view ?
            ds4_gpu_wrap_model_exact_range(model_map,
                                           model_size,
                                           weight_offset,
                                           weight_bytes,
                                           &weight_inner) :
            ds4_gpu_wrap_model_range(model_map,
                                     model_size,
                                     weight_offset,
                                     weight_bytes,
                                     &weight_inner);
        if (!weightbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_kv_lora_rms_norm_pipeline,
                                 "kernel_glm_kv_lora_rms_norm");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_kv_lora_rms_norm_args args = {
            .n_tokens = n_tokens,
            .kv_raw_dim = kv_raw_dim,
            .kv_lora_dim = kv_lora_dim,
            .eps = eps,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(kv_lora_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(kv_raw) atIndex:1];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM KV RMS norm")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_k_b_project_typed_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *kv_norm,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              weight_type,
        uint32_t              n_tokens,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              n_head) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !kv_norm || !model_map ||
        n_tokens == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || n_head == 0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> kvbuf = ds4_gpu_tensor_buffer(kv_norm);
        uint64_t row_bytes = 0;
        if (!ds4_gpu_quant_row_bytes(weight_type, qk_nope, &row_bytes)) {
            fprintf(stderr, "ds4: Metal GLM k_b projection received unsupported weight type\n");
            return 0;
        }
        const uint64_t weight_rows = (uint64_t)n_head * kv_lora_dim;
        const uint64_t weight_bytes = weight_rows * row_bytes;
        const uint64_t kv_bytes = (uint64_t)n_tokens * kv_lora_dim * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_tokens * n_head * qk_nope * sizeof(float);
        if (!outbuf || !kvbuf ||
            ds4_gpu_tensor_bytes(kv_norm) < kv_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes) {
            fprintf(stderr, "ds4: Metal GLM k_b projection received undersized buffers\n");
            return 0;
        }
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal GLM k_b projection range is outside the mapped model\n");
            return 0;
        }
        const NSUInteger q_blocks = ((NSUInteger)qk_nope + 31u) / 32u;
        if (q_blocks > 8u) {
            fprintf(stderr, "ds4: Metal GLM k_b projection q width is too large for the tiled kernel\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        id<MTLBuffer> weightbuf =
            ds4_gpu_wrap_model_range(model_map,
                                      model_size,
                                      weight_offset,
                                      weight_bytes,
                                      &weight_inner);
        if (!weightbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_k_b_project_pipeline,
                                 "kernel_glm_k_b_project_q8_0");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_k_b_project_args args = {
            .n_tokens = n_tokens,
            .kv_lora_dim = kv_lora_dim,
            .qk_nope = qk_nope,
            .n_head = n_head,
            .row_bytes = (uint32_t)row_bytes,
            .weight_type = weight_type,
            .pad1 = 0,
            .pad2 = 0,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:1];
        [enc setBuffer:kvbuf offset:ds4_gpu_tensor_offset(kv_norm) atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:(NSUInteger)kv_lora_dim * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, (NSUInteger)n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(32, q_blocks, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM k_b projection")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_k_b_project_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *kv_norm,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              n_tokens,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              n_head) {
    return ds4_gpu_glm_k_b_project_typed_tensor(out,
                                                kv_norm,
                                                model_map,
                                                model_size,
                                                weight_offset,
                                                DS4_METAL_TENSOR_Q8_0,
                                                n_tokens,
                                                kv_lora_dim,
                                                qk_nope,
                                                n_head);
}

int ds4_gpu_glm_store_compact_kv_tensor(
        ds4_gpu_tensor       *kv_lora_cache,
        ds4_gpu_tensor       *k_rope_cache,
        const ds4_gpu_tensor *kv_norm,
        const ds4_gpu_tensor *kv_raw,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_rope,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!kv_lora_cache || !k_rope_cache || !kv_norm || !kv_raw ||
        n_tokens == 0 || cache_cap == 0 ||
        kv_raw_dim == 0 || kv_lora_dim == 0 ||
        kv_lora_dim > kv_raw_dim ||
        qk_rope > kv_raw_dim - kv_lora_dim ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> kvcachebuf = ds4_gpu_tensor_buffer(kv_lora_cache);
        id<MTLBuffer> ropecachebuf = ds4_gpu_tensor_buffer(k_rope_cache);
        id<MTLBuffer> kvnormbuf = ds4_gpu_tensor_buffer(kv_norm);
        id<MTLBuffer> kvrawbuf = ds4_gpu_tensor_buffer(kv_raw);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t kv_cache_bytes =
            (uint64_t)cache_cap * kv_lora_dim * cache_elem_bytes;
        const uint64_t rope_cache_bytes =
            (uint64_t)cache_cap * qk_rope * cache_elem_bytes;
        const uint64_t kv_norm_bytes =
            (uint64_t)n_tokens * kv_lora_dim * sizeof(float);
        const uint64_t kv_raw_bytes =
            (uint64_t)n_tokens * kv_raw_dim * sizeof(float);
        if (!kvcachebuf || !ropecachebuf || !kvnormbuf || !kvrawbuf ||
            ds4_gpu_tensor_bytes(kv_lora_cache) < kv_cache_bytes ||
            ds4_gpu_tensor_bytes(k_rope_cache) < rope_cache_bytes ||
            ds4_gpu_tensor_bytes(kv_norm) < kv_norm_bytes ||
            ds4_gpu_tensor_bytes(kv_raw) < kv_raw_bytes) {
            fprintf(stderr, "ds4: Metal GLM compact KV store received undersized buffers\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_store_compact_kv_pipeline,
                                 "kernel_glm_store_compact_kv");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_store_compact_kv_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_cap = cache_cap,
            .kv_raw_dim = kv_raw_dim,
            .kv_lora_dim = kv_lora_dim,
            .qk_rope = qk_rope,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad1 = 0,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:kvnormbuf offset:ds4_gpu_tensor_offset(kv_norm) atIndex:1];
        [enc setBuffer:kvrawbuf offset:ds4_gpu_tensor_offset(kv_raw) atIndex:2];
        [enc setBuffer:kvcachebuf offset:ds4_gpu_tensor_offset(kv_lora_cache) atIndex:3];
        [enc setBuffer:ropecachebuf offset:ds4_gpu_tensor_offset(k_rope_cache) atIndex:4];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, 2, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM compact KV store")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_qkv_norm_store_compact_kv_tensor(
        ds4_gpu_tensor       *q_out,
        const ds4_gpu_tensor *q,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              q_weight_offset,
        uint32_t              q_n,
        ds4_gpu_tensor       *kv_lora_cache,
        ds4_gpu_tensor       *k_rope_cache,
        const ds4_gpu_tensor *kv_raw,
        uint64_t              kv_weight_offset,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_rope,
        bool                  cache_f16,
        float                 eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!q_out || !q || !kv_lora_cache || !k_rope_cache || !kv_raw ||
        !model_map || n_tokens == 0 || cache_cap == 0 ||
        q_n == 0 || kv_raw_dim == 0 || kv_lora_dim == 0 ||
        (q_n & 3u) != 0 || (kv_lora_dim & 3u) != 0 ||
        kv_lora_dim > kv_raw_dim ||
        qk_rope > kv_raw_dim - kv_lora_dim ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> qoutbuf = ds4_gpu_tensor_buffer(q_out);
        id<MTLBuffer> kvcachebuf = ds4_gpu_tensor_buffer(kv_lora_cache);
        id<MTLBuffer> ropecachebuf = ds4_gpu_tensor_buffer(k_rope_cache);
        id<MTLBuffer> kvrawbuf = ds4_gpu_tensor_buffer(kv_raw);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t q_row_bytes = (uint64_t)q_n * sizeof(float);
        const uint64_t kv_weight_bytes = (uint64_t)kv_lora_dim * sizeof(float);
        const uint64_t kv_cache_bytes =
            (uint64_t)cache_cap * kv_lora_dim * cache_elem_bytes;
        const uint64_t rope_cache_bytes =
            (uint64_t)cache_cap * qk_rope * cache_elem_bytes;
        const uint64_t kv_raw_bytes =
            (uint64_t)n_tokens * kv_raw_dim * sizeof(float);
        if (!qbuf || !qoutbuf || !kvcachebuf || !ropecachebuf || !kvrawbuf ||
            ds4_gpu_tensor_bytes(q) < q_row_bytes * n_tokens ||
            ds4_gpu_tensor_bytes(q_out) < q_row_bytes * n_tokens ||
            ds4_gpu_tensor_bytes(kv_lora_cache) < kv_cache_bytes ||
            ds4_gpu_tensor_bytes(k_rope_cache) < rope_cache_bytes ||
            ds4_gpu_tensor_bytes(kv_raw) < kv_raw_bytes) {
            fprintf(stderr, "ds4: Metal GLM fused q/kv norm compact store received undersized buffers\n");
            return 0;
        }
        if (q_weight_offset > model_size || q_row_bytes > model_size - q_weight_offset ||
            kv_weight_offset > model_size || kv_weight_bytes > model_size - kv_weight_offset) {
            fprintf(stderr, "ds4: Metal GLM fused q/kv norm compact store weight range is outside the mapped model\n");
            return 0;
        }

        uint64_t q_weight_inner = 0;
        id<MTLBuffer> q_weightbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                              q_weight_offset, q_row_bytes,
                                                              &q_weight_inner);
        if (!q_weightbuf) return 0;
        uint64_t kv_weight_inner = 0;
        id<MTLBuffer> kv_weightbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                               kv_weight_offset, kv_weight_bytes,
                                                               &kv_weight_inner);
        if (!kv_weightbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_qkv_norm_store_compact_kv_pipeline,
                                 "kernel_glm_qkv_norm_store_compact_kv");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_qkv_norm_store_compact_kv_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_cap = cache_cap,
            .q_n = q_n,
            .q_n4 = q_n / 4u,
            .kv_raw_dim = kv_raw_dim,
            .kv_lora_dim = kv_lora_dim,
            .kv_lora_n4 = kv_lora_dim / 4u,
            .qk_rope = qk_rope,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .eps = eps,
            .pad0 = 0,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:q_weightbuf offset:(NSUInteger)q_weight_inner atIndex:2];
        [enc setBuffer:qoutbuf offset:ds4_gpu_tensor_offset(q_out) atIndex:3];
        [enc setBuffer:kvrawbuf offset:ds4_gpu_tensor_offset(kv_raw) atIndex:4];
        [enc setBuffer:kv_weightbuf offset:(NSUInteger)kv_weight_inner atIndex:5];
        [enc setBuffer:kvcachebuf offset:ds4_gpu_tensor_offset(kv_lora_cache) atIndex:6];
        [enc setBuffer:ropecachebuf offset:ds4_gpu_tensor_offset(k_rope_cache) atIndex:7];
        [enc setThreadgroupMemoryLength:32u * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, 3, 1)
             threadsPerThreadgroup:MTLSizeMake(ds4_gpu_rms_norm_threads(q_n), 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM fused q/kv norm compact store")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_store_indexer_k_tensor(
        ds4_gpu_tensor       *indexer_key_cache,
        const ds4_gpu_tensor *raw_k,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint64_t              bias_offset,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              head_dim,
        uint32_t              rot_dim,
        uint32_t              n_ctx_orig,
        float                 eps,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!indexer_key_cache || !raw_k || !model_map ||
        n_tokens == 0 || cache_cap == 0 ||
        head_dim == 0 || rot_dim == 0 ||
        rot_dim > head_dim || (rot_dim & 1u) != 0 ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> cachebuf = ds4_gpu_tensor_buffer(indexer_key_cache);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_k);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t cache_bytes =
            (uint64_t)cache_cap * head_dim * cache_elem_bytes;
        const uint64_t raw_bytes =
            (uint64_t)n_tokens * head_dim * sizeof(float);
        const uint64_t norm_bytes = (uint64_t)head_dim * sizeof(float);
        if (!cachebuf || !rawbuf ||
            ds4_gpu_tensor_bytes(indexer_key_cache) < cache_bytes ||
            ds4_gpu_tensor_bytes(raw_k) < raw_bytes) {
            fprintf(stderr, "ds4: Metal GLM indexer K store received undersized buffers\n");
            return 0;
        }
        if (weight_offset > model_size || norm_bytes > model_size - weight_offset ||
            bias_offset > model_size || norm_bytes > model_size - bias_offset) {
            fprintf(stderr, "ds4: Metal GLM indexer K norm range is outside the mapped model\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        uint64_t bias_inner = 0;
        id<MTLBuffer> weightbuf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                     weight_offset, norm_bytes,
                                     &weight_inner);
        id<MTLBuffer> biasbuf =
            ds4_gpu_wrap_model_range(model_map, model_size,
                                     bias_offset, norm_bytes,
                                     &bias_inner);
        if (!weightbuf || !biasbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_store_indexer_k_pipeline,
                                 "kernel_glm_store_indexer_k");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_store_indexer_k_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_cap = cache_cap,
            .head_dim = head_dim,
            .rot_dim = rot_dim,
            .n_ctx_orig = n_ctx_orig,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad0 = 0,
            .eps = eps,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
            .pad1 = 0.0f,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(head_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_k) atIndex:1];
        [enc setBuffer:weightbuf offset:(NSUInteger)weight_inner atIndex:2];
        [enc setBuffer:biasbuf offset:(NSUInteger)bias_inner atIndex:3];
        [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:4];
        [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer K store")) return 0;
    }

    return 1;
}

int ds4_gpu_glm53_indexer_pool_update_tensor(
        ds4_gpu_tensor       *pool_cache,
        ds4_gpu_tensor       *tail_k,
        ds4_gpu_tensor       *tail_gate,
        const ds4_gpu_tensor *raw_k,
        const ds4_gpu_tensor *gate,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              norm_weight_offset,
        uint64_t              norm_bias_offset,
        uint64_t              ape_offset,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              head_dim,
        uint32_t              pool_size,
        float                 eps,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!pool_cache || !tail_k || !tail_gate || !raw_k || !gate || !model_map ||
        n_tokens == 0 || cache_cap == 0 || head_dim == 0 || pool_size != 4u ||
        head_dim > 1024u || !isfinite(eps) || eps <= 0.0f ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> poolbuf = ds4_gpu_tensor_buffer(pool_cache);
        id<MTLBuffer> tailkbuf = ds4_gpu_tensor_buffer(tail_k);
        id<MTLBuffer> tailgatebuf = ds4_gpu_tensor_buffer(tail_gate);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_k);
        id<MTLBuffer> gatebuf = ds4_gpu_tensor_buffer(gate);
        const uint64_t pool_cap =
            ((uint64_t)cache_cap + pool_size - 1u) / pool_size;
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t pool_bytes = pool_cap * head_dim * cache_elem_bytes;
        const uint64_t tail_bytes = (uint64_t)pool_size * head_dim * sizeof(float);
        const uint64_t input_bytes = (uint64_t)n_tokens * head_dim * sizeof(float);
        const uint64_t norm_bytes = (uint64_t)head_dim * sizeof(float);
        const uint64_t ape_bytes =
            (uint64_t)pool_size * head_dim * sizeof(uint16_t);
        if (!poolbuf || !tailkbuf || !tailgatebuf || !rawbuf || !gatebuf ||
            ds4_gpu_tensor_bytes(pool_cache) < pool_bytes ||
            ds4_gpu_tensor_bytes(tail_k) < tail_bytes ||
            ds4_gpu_tensor_bytes(tail_gate) < tail_bytes ||
            ds4_gpu_tensor_bytes(raw_k) < input_bytes ||
            ds4_gpu_tensor_bytes(gate) < input_bytes) {
            fprintf(stderr, "ds4: Metal GLM-5.3 indexer pool received undersized buffers\n");
            return 0;
        }
        if (norm_weight_offset > model_size ||
            norm_bytes > model_size - norm_weight_offset ||
            norm_bias_offset > model_size ||
            norm_bytes > model_size - norm_bias_offset ||
            ape_offset > model_size || ape_bytes > model_size - ape_offset) {
            fprintf(stderr, "ds4: Metal GLM-5.3 indexer pool model range is invalid\n");
            return 0;
        }

        uint64_t norm_weight_inner = 0;
        uint64_t norm_bias_inner = 0;
        uint64_t ape_inner = 0;
        id<MTLBuffer> norm_weightbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, norm_weight_offset, norm_bytes, &norm_weight_inner);
        id<MTLBuffer> norm_biasbuf = ds4_gpu_wrap_model_range(
            model_map, model_size, norm_bias_offset, norm_bytes, &norm_bias_inner);
        id<MTLBuffer> apebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, ape_offset, ape_bytes, &ape_inner);
        if (!norm_weightbuf || !norm_biasbuf || !apebuf) return 0;

        id<MTLComputePipelineState> pipeline = ds4_gpu_hot_pipeline(
            g_glm53_indexer_pool_update_pipeline,
            "kernel_glm53_indexer_pool_update");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBuffer:norm_weightbuf offset:(NSUInteger)norm_weight_inner atIndex:3];
        [enc setBuffer:norm_biasbuf offset:(NSUInteger)norm_bias_inner atIndex:4];
        [enc setBuffer:apebuf offset:(NSUInteger)ape_inner atIndex:5];
        [enc setBuffer:poolbuf offset:ds4_gpu_tensor_offset(pool_cache) atIndex:6];
        [enc setBuffer:tailkbuf offset:ds4_gpu_tensor_offset(tail_k) atIndex:7];
        [enc setBuffer:tailgatebuf offset:ds4_gpu_tensor_offset(tail_gate) atIndex:8];
        [enc setThreadgroupMemoryLength:
            ((NSUInteger)pool_size * head_dim + 2u * pool_size) * sizeof(float)
                                  atIndex:0];

        uint32_t done = 0;
        const uint32_t leading = pos0 % pool_size;
        if (leading != 0u) {
            uint32_t chunk = pool_size - leading;
            if (chunk > n_tokens) chunk = n_tokens;
            ds4_gpu_glm53_indexer_pool_update_args args = {
                .pos0 = pos0,
                .n_tokens = chunk,
                .cache_cap = cache_cap,
                .head_dim = head_dim,
                .pool_size = pool_size,
                .cache_f16 = cache_f16 ? 1u : 0u,
                .eps = eps,
                .pad0 = 0,
            };
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_k) atIndex:1];
            [enc setBuffer:gatebuf offset:ds4_gpu_tensor_offset(gate) atIndex:2];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(head_dim, 1, 1)];
            done = chunk;
        }
        if (done < n_tokens) {
            const uint32_t chunk = n_tokens - done;
            ds4_gpu_glm53_indexer_pool_update_args args = {
                .pos0 = pos0 + done,
                .n_tokens = chunk,
                .cache_cap = cache_cap,
                .head_dim = head_dim,
                .pool_size = pool_size,
                .cache_f16 = cache_f16 ? 1u : 0u,
                .eps = eps,
                .pad0 = 0,
            };
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:rawbuf
                    offset:ds4_gpu_tensor_offset(raw_k) +
                           (NSUInteger)((uint64_t)done * head_dim * sizeof(float))
                  atIndex:1];
            [enc setBuffer:gatebuf
                    offset:ds4_gpu_tensor_offset(gate) +
                           (NSUInteger)((uint64_t)done * head_dim * sizeof(float))
                  atIndex:2];
            const uint32_t groups = (chunk + pool_size - 1u) / pool_size;
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(groups, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(head_dim, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM-5.3 indexer pool update")) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_glm53_expand_pool_selection_tensor(
        ds4_gpu_tensor       *raw_selected,
        const ds4_gpu_tensor *pool_selected,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              selected_pools,
        uint32_t              index_topk,
        uint32_t              pool_size,
        uint32_t              output_width) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!raw_selected || !pool_selected || n_tokens == 0 ||
        selected_pools == 0 || index_topk == 0 || pool_size == 0 ||
        selected_pools > index_topk / pool_size ||
        output_width < index_topk || output_width < index_topk + pool_size - 1u) {
        return 0;
    }
    @autoreleasepool {
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(raw_selected);
        id<MTLBuffer> poolbuf = ds4_gpu_tensor_buffer(pool_selected);
        const uint64_t raw_bytes =
            (uint64_t)n_tokens * output_width * sizeof(uint32_t);
        const uint64_t pool_bytes =
            (uint64_t)n_tokens * selected_pools * sizeof(uint32_t);
        if (!rawbuf || !poolbuf ||
            ds4_gpu_tensor_bytes(raw_selected) < raw_bytes ||
            ds4_gpu_tensor_bytes(pool_selected) < pool_bytes) {
            fprintf(stderr, "ds4: Metal GLM-5.3 pool expansion received undersized buffers\n");
            return 0;
        }
        id<MTLComputePipelineState> pipeline = ds4_gpu_hot_pipeline(
            g_glm53_expand_pool_selection_pipeline,
            "kernel_glm53_expand_pool_selection");
        if (!pipeline) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        ds4_gpu_glm53_expand_pool_selection_args args = {
            .n_tokens = n_tokens,
            .pos0 = pos0,
            .selected_pools = selected_pools,
            .index_topk = index_topk,
            .pool_size = pool_size,
            .output_width = output_width,
        };
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:poolbuf offset:ds4_gpu_tensor_offset(pool_selected) atIndex:1];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(raw_selected) atIndex:2];
        const NSUInteger total = (NSUInteger)n_tokens * output_width;
        const NSUInteger nth = MIN((NSUInteger)256, pipeline.maxTotalThreadsPerThreadgroup);
        [llms_bar(enc) dispatchThreads:MTLSizeMake(total, 1, 1)
           threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM-5.3 pool selection expansion")) {
            return 0;
        }
    }
    return 1;
}

int ds4_gpu_glm_build_kv_cache_tensor(
        ds4_gpu_tensor       *key_cache,
        ds4_gpu_tensor       *value_cache,
        const ds4_gpu_tensor *kv_raw,
        const ds4_gpu_tensor *k_nope,
        const ds4_gpu_tensor *value,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const uint32_t qk_dim = qk_nope + qk_rope;
    if (!key_cache || !value_cache || !kv_raw || !k_nope || !value ||
        n_tokens == 0 || cache_cap == 0 || n_head == 0 ||
        kv_raw_dim == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || value_dim == 0 ||
        kv_lora_dim + qk_rope > kv_raw_dim ||
        qk_dim < qk_nope || (qk_rope & 1u) != 0 ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0 ||
        (qk_rope != 0 && (!isfinite(freq_base) || freq_base <= 0.0f)) ||
        (qk_rope != 0 && (!isfinite(freq_scale) || freq_scale <= 0.0f)) ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
        !isfinite(beta_fast) || !isfinite(beta_slow)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(kv_raw);
        id<MTLBuffer> knbuf = ds4_gpu_tensor_buffer(k_nope);
        id<MTLBuffer> vbuf = ds4_gpu_tensor_buffer(value);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t cache_value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        const uint64_t raw_bytes = (uint64_t)n_tokens * kv_raw_dim * sizeof(float);
        const uint64_t kn_bytes = (uint64_t)n_tokens * n_head * qk_nope * sizeof(float);
        const uint64_t value_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        if (!keybuf || !valbuf || !rawbuf || !knbuf || !vbuf ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_value_bytes ||
            ds4_gpu_tensor_bytes(kv_raw) < raw_bytes ||
            ds4_gpu_tensor_bytes(k_nope) < kn_bytes ||
            ds4_gpu_tensor_bytes(value) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM KV cache builder received undersized buffers\n");
            return 0;
        }

        const bool decode_group4 =
            n_tokens == 1u &&
            n_head >= 4u &&
            ds4_gpu_env_bool("DS4_METAL_DISABLE_GLM_DECODE_KV_GROUP4") <= 0;
        id<MTLComputePipelineState> pipeline =
            decode_group4 ?
            ds4_gpu_hot_pipeline(g_glm_build_kv_cache_decode_group4_pipeline,
                                 "kernel_glm_build_kv_cache_decode_group4") :
            ds4_gpu_hot_pipeline(g_glm_build_kv_cache_pipeline,
                                 "kernel_glm_build_kv_cache");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_build_kv_cache_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_cap = cache_cap,
            .n_head = n_head,
            .kv_raw_dim = kv_raw_dim,
            .kv_lora_dim = kv_lora_dim,
            .qk_nope = qk_nope,
            .qk_rope = qk_rope,
            .value_dim = value_dim,
            .n_ctx_orig = n_ctx_orig,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad0 = 0u,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(kv_raw) atIndex:1];
        [enc setBuffer:knbuf offset:ds4_gpu_tensor_offset(k_nope) atIndex:2];
        [enc setBuffer:vbuf offset:ds4_gpu_tensor_offset(value) atIndex:3];
        [enc setBuffer:keybuf offset:ds4_gpu_tensor_offset(key_cache) atIndex:4];
        [enc setBuffer:valbuf offset:ds4_gpu_tensor_offset(value_cache) atIndex:5];
        const NSUInteger group_y = decode_group4 ?
            ((NSUInteger)n_head + 3u) / 4u :
            (NSUInteger)n_head;
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, group_y, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM KV cache build")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_build_kv_cache_flash_tensor(
        ds4_gpu_tensor       *key_cache,
        ds4_gpu_tensor       *value_cache,
        const ds4_gpu_tensor *kv_raw,
        const ds4_gpu_tensor *k_nope,
        const ds4_gpu_tensor *value,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    const uint32_t qk_dim = qk_nope + qk_rope;
    if (!key_cache || !value_cache || !kv_raw || !k_nope || !value ||
        pos0 != 0 || n_tokens == 0 || cache_cap == 0 || n_head == 0 ||
        kv_raw_dim == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || value_dim == 0 ||
        kv_lora_dim + qk_rope > kv_raw_dim ||
        qk_dim < qk_nope || (qk_rope & 1u) != 0 ||
        n_tokens > cache_cap ||
        (qk_rope != 0 && (!isfinite(freq_base) || freq_base <= 0.0f)) ||
        (qk_rope != 0 && (!isfinite(freq_scale) || freq_scale <= 0.0f)) ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
        !isfinite(beta_fast) || !isfinite(beta_slow)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        id<MTLBuffer> rawbuf = ds4_gpu_tensor_buffer(kv_raw);
        id<MTLBuffer> knbuf = ds4_gpu_tensor_buffer(k_nope);
        id<MTLBuffer> vbuf = ds4_gpu_tensor_buffer(value);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t cache_value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        const uint64_t raw_bytes = (uint64_t)n_tokens * kv_raw_dim * sizeof(float);
        const uint64_t kn_bytes = (uint64_t)n_tokens * n_head * qk_nope * sizeof(float);
        const uint64_t value_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        if (!keybuf || !valbuf || !rawbuf || !knbuf || !vbuf ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < cache_value_bytes ||
            ds4_gpu_tensor_bytes(kv_raw) < raw_bytes ||
            ds4_gpu_tensor_bytes(k_nope) < kn_bytes ||
            ds4_gpu_tensor_bytes(value) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM staged KV cache builder received undersized buffers\n");
            return 0;
        }

        const NSUInteger q_row_bytes_f16 = (NSUInteger)qk_dim * sizeof(uint16_t);
        const NSUInteger v_row_bytes_f16 = (NSUInteger)value_dim * sizeof(uint16_t);
        const NSUInteger key_f16_offset = 0;
        const NSUInteger key_f16_bytes =
            (NSUInteger)n_tokens * (NSUInteger)n_head * q_row_bytes_f16;
        const NSUInteger value_f16_offset = key_f16_bytes;
        const NSUInteger value_f16_bytes =
            (NSUInteger)n_tokens * (NSUInteger)n_head * v_row_bytes_f16;
        const NSUInteger kv_f16_bytes = key_f16_bytes + value_f16_bytes;
        if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_kv_buffer,
                                           &g_flash_attn_kv_bytes,
                                           kv_f16_bytes,
                                           "ds4_glm_flash_attn_kv_f16")) {
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_build_kv_cache_flash_pipeline,
                                 "kernel_glm_build_kv_cache_flash");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_build_kv_cache_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_cap = cache_cap,
            .n_head = n_head,
            .kv_raw_dim = kv_raw_dim,
            .kv_lora_dim = kv_lora_dim,
            .qk_nope = qk_nope,
            .qk_rope = qk_rope,
            .value_dim = value_dim,
            .n_ctx_orig = n_ctx_orig,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad0 = 0u,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:rawbuf offset:ds4_gpu_tensor_offset(kv_raw) atIndex:1];
        [enc setBuffer:knbuf offset:ds4_gpu_tensor_offset(k_nope) atIndex:2];
        [enc setBuffer:vbuf offset:ds4_gpu_tensor_offset(value) atIndex:3];
        [enc setBuffer:keybuf offset:ds4_gpu_tensor_offset(key_cache) atIndex:4];
        [enc setBuffer:valbuf offset:ds4_gpu_tensor_offset(value_cache) atIndex:5];
        [enc setBuffer:g_flash_attn_kv_buffer offset:key_f16_offset atIndex:6];
        [enc setBuffer:g_flash_attn_kv_buffer offset:value_f16_offset atIndex:7];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, (NSUInteger)n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM staged KV cache build")) return 0;
    }

    return 1;
}

static int ds4_gpu_glm_attention_flash_tensor_impl(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16,
        int                   kv_pre_staged) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !key_cache || !value_cache ||
        n_tokens == 0 || cache_len == 0 || cache_cap == 0 ||
        n_head == 0 || qk_dim != 256u || value_dim != 256u ||
        cache_len > cache_cap ||
        pos0 > cache_len || n_tokens > cache_len - pos0 ||
        cache_len > ds4_gpu_glm_flash_attention_max_cache_len()) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        const uint64_t heads_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * qk_dim * sizeof(float);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        if (!headsbuf || !qbuf || !keybuf || !valbuf ||
            ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM FlashAttention received undersized buffers\n");
            return 0;
        }
        const uint64_t key_elems = (uint64_t)cache_len * n_head * qk_dim;
        const uint64_t value_elems = (uint64_t)cache_len * n_head * value_dim;
        if (key_elems > UINT32_MAX || value_elems > UINT32_MAX) {
            return 0;
        }

        const uint32_t nqptg = 8;
        const uint32_t ncpsg = 64;
        const uint32_t nsg = 4;
        const bool has_kvpad = (cache_len % ncpsg) != 0;
        const bool bc_mask = (n_tokens % nqptg) != 0;
        const NSUInteger q_row_bytes = (NSUInteger)qk_dim * sizeof(float);
        const NSUInteger q_row_bytes_f16 = (NSUInteger)qk_dim * sizeof(uint16_t);
        const NSUInteger v_row_bytes = (NSUInteger)value_dim * sizeof(float);
        const NSUInteger v_row_bytes_f16 = (NSUInteger)value_dim * sizeof(uint16_t);
        const NSUInteger mask_bytes = (NSUInteger)n_tokens * (NSUInteger)cache_len * sizeof(uint16_t);
        const NSUInteger key_f16_offset = 0;
        const NSUInteger key_f16_bytes =
            (NSUInteger)cache_len * (NSUInteger)n_head * q_row_bytes_f16;
        const NSUInteger value_f16_offset = key_f16_bytes;
        const NSUInteger value_f16_bytes =
            (NSUInteger)cache_len * (NSUInteger)n_head * v_row_bytes_f16;
        const NSUInteger kv_f16_bytes = key_f16_bytes + value_f16_bytes;
        const NSUInteger pad_bytes = has_kvpad
            ? (NSUInteger)ncpsg * ((NSUInteger)n_head * (q_row_bytes_f16 + v_row_bytes_f16) +
                                   (NSUInteger)n_tokens * sizeof(uint16_t))
            : 1u;
        const NSUInteger nblk0 = ((NSUInteger)cache_len + ncpsg - 1u) / ncpsg;
        const NSUInteger nblk1 = ((NSUInteger)n_tokens + nqptg - 1u) / nqptg;
        const NSUInteger blk_bytes = ds4_gpu_align_up_ns(nblk0 * nblk1, 32u);

        id<MTLBuffer> mask_buffer =
            ds4_gpu_glm_prefill_mask_buffer(pos0, n_tokens, cache_len, mask_bytes);
        if (!mask_buffer) return 0;
        if (kv_pre_staged) {
            if (!g_flash_attn_kv_buffer || g_flash_attn_kv_bytes < kv_f16_bytes) {
                fprintf(stderr, "ds4: GLM staged FlashAttention KV scratch is missing\n");
                return 0;
            }
        } else if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_kv_buffer,
                                                  &g_flash_attn_kv_bytes,
                                                  kv_f16_bytes,
                                                  "ds4_glm_flash_attn_kv_f16")) {
            return 0;
        }
        if (!ds4_gpu_ensure_scratch_buffer(&g_flash_attn_pad_buffer,
                                             &g_flash_attn_pad_bytes,
                                             pad_bytes,
                                             "ds4_glm_flash_attn_pad") ||
            !ds4_gpu_ensure_scratch_buffer(&g_flash_attn_blk_buffer,
                                             &g_flash_attn_blk_bytes,
                                             blk_bytes,
                                             "ds4_glm_flash_attn_blk")) {
            return 0;
        }

        id<MTLComputePipelineState> pad_pipeline = nil;
        if (has_kvpad) {
            pad_pipeline = ds4_gpu_get_flash_attn_pad_pipeline(true, (int32_t)ncpsg);
            if (!pad_pipeline) return 0;
        }
        id<MTLComputePipelineState> blk_pipeline =
            ds4_gpu_get_flash_attn_blk_pipeline((int32_t)nqptg, (int32_t)ncpsg);
        id<MTLComputePipelineState> attn_pipeline =
            ds4_gpu_get_flash_attn_pipeline("kernel_flash_attn_ext_f16_dk256_dv256",
                                              true, false, false, false, has_kvpad, bc_mask,
                                              (int32_t)qk_dim,
                                              (int32_t)value_dim,
                                              (int32_t)nsg);
        if (!blk_pipeline || !attn_pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        if (!kv_pre_staged) {
            const bool copied = cache_f16 ?
                (ds4_gpu_encode_cpy_f16_f16_3d(cb,
                                               keybuf,
                                               ds4_gpu_tensor_offset(key_cache),
                                               g_flash_attn_kv_buffer,
                                               key_f16_offset,
                                               qk_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * q_row_bytes_f16,
                                               q_row_bytes_f16,
                                               q_row_bytes_f16,
                                               (uint64_t)cache_len * q_row_bytes_f16) &&
                 ds4_gpu_encode_cpy_f16_f16_3d(cb,
                                               valbuf,
                                               ds4_gpu_tensor_offset(value_cache),
                                               g_flash_attn_kv_buffer,
                                               value_f16_offset,
                                               value_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * v_row_bytes_f16,
                                               v_row_bytes_f16,
                                               v_row_bytes_f16,
                                               (uint64_t)cache_len * v_row_bytes_f16)) :
                (ds4_gpu_encode_cpy_f32_f16_3d(cb,
                                               keybuf,
                                               ds4_gpu_tensor_offset(key_cache),
                                               g_flash_attn_kv_buffer,
                                               key_f16_offset,
                                               qk_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * q_row_bytes,
                                               q_row_bytes,
                                               q_row_bytes_f16,
                                               (uint64_t)cache_len * q_row_bytes_f16) &&
                 ds4_gpu_encode_cpy_f32_f16_3d(cb,
                                               valbuf,
                                               ds4_gpu_tensor_offset(value_cache),
                                               g_flash_attn_kv_buffer,
                                               value_f16_offset,
                                               value_dim,
                                               cache_len,
                                               n_head,
                                               (uint64_t)n_head * v_row_bytes,
                                               v_row_bytes,
                                               v_row_bytes_f16,
                                               (uint64_t)cache_len * v_row_bytes_f16));
            if (!copied) {
                return 0;
            }
        }

        if (has_kvpad) {
            ds4_gpu_flash_attn_pad_args pad_args = {
                .ne11 = (int32_t)cache_len,
                .ne_12_2 = (int32_t)n_head,
                .ne_12_3 = 1,
                .nb11 = q_row_bytes_f16,
                .nb12 = (uint64_t)cache_len * q_row_bytes_f16,
                .nb13 = (uint64_t)cache_len * (uint64_t)n_head * q_row_bytes_f16,
                .nb21 = v_row_bytes_f16,
                .nb22 = (uint64_t)cache_len * v_row_bytes_f16,
                .nb23 = (uint64_t)cache_len * (uint64_t)n_head * v_row_bytes_f16,
                .ne31 = (int32_t)n_tokens,
                .ne32 = 1,
                .ne33 = 1,
                .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
                .nb32 = mask_bytes,
                .nb33 = mask_bytes,
            };

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:pad_pipeline];
            [enc setBytes:&pad_args length:sizeof(pad_args) atIndex:0];
            [enc setBuffer:g_flash_attn_kv_buffer offset:key_f16_offset atIndex:1];
            [enc setBuffer:g_flash_attn_kv_buffer offset:value_f16_offset atIndex:2];
            [enc setBuffer:mask_buffer offset:0 atIndex:3];
            [enc setBuffer:g_flash_attn_pad_buffer offset:0 atIndex:4];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(ncpsg, n_head, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
        }

        ds4_gpu_flash_attn_blk_args blk_args = {
            .ne01 = (int32_t)n_tokens,
            .ne30 = (int32_t)cache_len,
            .ne31 = (int32_t)n_tokens,
            .ne32 = 1,
            .ne33 = 1,
            .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
            .nb32 = mask_bytes,
            .nb33 = mask_bytes,
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:blk_pipeline];
        [enc setBytes:&blk_args length:sizeof(blk_args) atIndex:0];
        [enc setBuffer:mask_buffer offset:0 atIndex:1];
        [enc setBuffer:g_flash_attn_blk_buffer offset:0 atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(nblk0, nblk1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        ds4_gpu_flash_attn_vec_args args = {
            .ne01 = (int32_t)n_tokens,
            .ne02 = (int32_t)n_head,
            .ne03 = 1,
            .nb01 = (uint64_t)n_head * q_row_bytes,
            .nb02 = q_row_bytes,
            .nb03 = (uint64_t)n_tokens * n_head * q_row_bytes,
            .ne11 = (int32_t)cache_len,
            .ne_12_2 = (int32_t)n_head,
            .ne_12_3 = 1,
            .ns10 = (int32_t)qk_dim,
            .nb11 = q_row_bytes_f16,
            .nb12 = (uint64_t)cache_len * q_row_bytes_f16,
            .nb13 = (uint64_t)cache_len * (uint64_t)n_head * q_row_bytes_f16,
            .ns20 = (int32_t)value_dim,
            .nb21 = v_row_bytes_f16,
            .nb22 = (uint64_t)cache_len * v_row_bytes_f16,
            .nb23 = (uint64_t)cache_len * (uint64_t)n_head * v_row_bytes_f16,
            .ne31 = (int32_t)n_tokens,
            .ne32 = 1,
            .ne33 = 1,
            .nb31 = (uint64_t)cache_len * sizeof(uint16_t),
            .nb32 = mask_bytes,
            .nb33 = mask_bytes,
            .ne1 = (int32_t)n_head,
            .ne2 = (int32_t)n_tokens,
            .ne3 = 1,
            .scale = 1.0f / sqrtf((float)qk_dim),
            .max_bias = 0.0f,
            .m0 = 0.0f,
            .m1 = 0.0f,
            .n_head_log2 = 0,
            .logit_softcap = 0.0f,
        };

        const NSUInteger padded_v = ds4_gpu_align_up_ns(value_dim, 64u);
        const NSUInteger shared_elems = (NSUInteger)nqptg *
            ((NSUInteger)qk_dim + 2u * padded_v + 2u * (2u * (NSUInteger)ncpsg));
        const NSUInteger shared_bytes = ds4_gpu_align_up_ns(shared_elems * (sizeof(float) / 2u), 16u);

        enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:attn_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:g_flash_attn_kv_buffer offset:key_f16_offset atIndex:2];
        [enc setBuffer:g_flash_attn_kv_buffer offset:value_f16_offset atIndex:3];
        [enc setBuffer:mask_buffer offset:0 atIndex:4];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:5];
        [enc setBuffer:g_flash_attn_pad_buffer offset:0 atIndex:6];
        [enc setBuffer:g_flash_attn_blk_buffer offset:0 atIndex:7];
        [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:8];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(nblk1, n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(32, nsg, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM FlashAttention")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_attention_flash_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    return ds4_gpu_glm_attention_flash_tensor_impl(heads,
                                                   q,
                                                   key_cache,
                                                   value_cache,
                                                   pos0,
                                                   n_tokens,
                                                   cache_len,
                                                   cache_cap,
                                                   n_head,
                                                   qk_dim,
                                                   value_dim,
                                                   cache_f16,
                                                   0);
}

int ds4_gpu_glm_attention_flash_staged_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    if (pos0 != 0 || n_tokens != cache_len) return 0;
    return ds4_gpu_glm_attention_flash_tensor_impl(heads,
                                                   q,
                                                   key_cache,
                                                   value_cache,
                                                   pos0,
                                                   n_tokens,
                                                   cache_len,
                                                   cache_cap,
                                                   n_head,
                                                   qk_dim,
                                                   value_dim,
                                                   cache_f16,
                                                   1);
}

int ds4_gpu_glm_attention_full_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *key_cache,
        const ds4_gpu_tensor *value_cache,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_len,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              qk_dim,
        uint32_t              value_dim,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!heads || !q || !key_cache || !value_cache ||
        n_tokens == 0 || cache_len == 0 || cache_cap == 0 ||
        n_head == 0 || qk_dim == 0 || value_dim == 0 ||
        (qk_dim & 3u) != 0 ||
        cache_len > cache_cap ||
        pos0 > cache_len || n_tokens > cache_len - pos0 ||
        cache_len > ds4_gpu_glm_full_attention_max_cache_len()) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> headsbuf = ds4_gpu_tensor_buffer(heads);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> keybuf = ds4_gpu_tensor_buffer(key_cache);
        id<MTLBuffer> valbuf = ds4_gpu_tensor_buffer(value_cache);
        const uint64_t heads_bytes = (uint64_t)n_tokens * n_head * value_dim * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * qk_dim * sizeof(float);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t key_bytes = (uint64_t)cache_cap * n_head * qk_dim * cache_elem_bytes;
        const uint64_t value_bytes = (uint64_t)cache_cap * n_head * value_dim * cache_elem_bytes;
        if (!headsbuf || !qbuf || !keybuf || !valbuf ||
            ds4_gpu_tensor_bytes(heads) < heads_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(key_cache) < key_bytes ||
            ds4_gpu_tensor_bytes(value_cache) < value_bytes) {
            fprintf(stderr, "ds4: Metal GLM attention received undersized buffers\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_attention_full_pipeline,
                                 "kernel_glm_attention_full");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const uint32_t full_attn_mode = 2u;
        ds4_gpu_glm_attention_full_args args = {
            .pos0 = pos0,
            .n_tokens = n_tokens,
            .cache_len = cache_len,
            .cache_cap = cache_cap,
            .n_head = n_head,
            .qk_dim = qk_dim,
            .value_dim = value_dim,
            .pad0 = full_attn_mode,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .pad1 = 0u,
            .pad2 = 0u,
            .scale = 1.0f / sqrtf((float)qk_dim),
        };

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:keybuf offset:ds4_gpu_tensor_offset(key_cache) atIndex:2];
        [enc setBuffer:valbuf offset:ds4_gpu_tensor_offset(value_cache) atIndex:3];
        [enc setBuffer:headsbuf offset:ds4_gpu_tensor_offset(heads) atIndex:4];
        [enc setThreadgroupMemoryLength:ds4_gpu_align_up_ns(
                (256u + (NSUInteger)cache_len) * sizeof(float), 16u) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_tokens, (NSUInteger)n_head, 1)
             threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM full attention")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_fill_selected_range_tensor(
        ds4_gpu_tensor *selected,
        uint32_t        n_selected) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || n_selected == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        const uint64_t selected_bytes = (uint64_t)n_selected * sizeof(uint32_t);
        if (!selectedbuf || ds4_gpu_tensor_bytes(selected) < selected_bytes) {
            fprintf(stderr, "ds4: Metal GLM selected range received undersized buffer\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_fill_selected_range_pipeline,
                                 "kernel_glm_fill_selected_range");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_fill_selected_range_args args = {
            .n_selected = n_selected,
        };
        const NSUInteger nth = 256u;
        const NSUInteger n_groups = ((NSUInteger)n_selected + nth - 1u) / nth;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:selectedbuf offset:ds4_gpu_tensor_offset(selected) atIndex:1];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM selected range")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_fill_selected_range_batch_tensor(
        ds4_gpu_tensor *selected,
        uint32_t        n_tokens,
        uint32_t        pos0,
        uint32_t        n_selected,
        uint32_t        pad_row) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || n_tokens == 0 || n_selected == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        const uint64_t total = (uint64_t)n_tokens * n_selected;
        if (n_tokens != 0 && total / n_tokens != n_selected) return 0;
        if (total > UINT64_MAX / sizeof(uint32_t)) return 0;
        const uint64_t selected_bytes = total * sizeof(uint32_t);
        if (!selectedbuf || ds4_gpu_tensor_bytes(selected) < selected_bytes) {
            fprintf(stderr, "ds4: Metal GLM selected range batch received undersized buffer\n");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_fill_selected_range_batch_pipeline,
                                 "kernel_glm_fill_selected_range_batch");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_fill_selected_range_batch_args args = {
            .n_tokens = n_tokens,
            .pos0 = pos0,
            .n_selected = n_selected,
            .pad_row = pad_row,
        };
        const NSUInteger nth = 256u;
        const NSUInteger n_groups = ((NSUInteger)total + nth - 1u) / nth;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:selectedbuf offset:ds4_gpu_tensor_offset(selected) atIndex:1];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_groups, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM selected range batch")) return 0;
    }

    return 1;
}

static int ds4_gpu_glm_rope_tail_offset_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        rot_offset,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow,
        const char     *label) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!x || n_tokens == 0 || n_head == 0 || head_dim == 0 ||
        rot_dim == 0 || rot_offset > head_dim || rot_dim > head_dim - rot_offset ||
        (rot_dim & 1u) != 0 ||
        pos0 > UINT32_MAX - n_tokens ||
        !isfinite(freq_base) || freq_base <= 0.0f ||
        !isfinite(freq_scale) || freq_scale <= 0.0f ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
        !isfinite(beta_fast) || !isfinite(beta_slow)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        const uint64_t bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        if (!xbuf || ds4_gpu_tensor_bytes(x) < bytes) {
            fprintf(stderr, "ds4: Metal %s received undersized buffer\n",
                    label ? label : "GLM RoPE");
            return 0;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_indexer_rope_tail_pipeline,
                                 "kernel_glm_indexer_rope_tail_f32");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_rope_tail_args args = {
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .rot_dim = rot_dim,
            .rot_offset = rot_offset,
            .pos0 = pos0,
            .n_ctx_orig = n_ctx_orig,
            .freq_base = freq_base,
            .freq_scale = freq_scale,
            .ext_factor = ext_factor,
            .attn_factor = attn_factor,
            .beta_fast = beta_fast,
            .beta_slow = beta_slow,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(rot_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_head, (NSUInteger)n_tokens, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, label ? label : "GLM RoPE")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow) {
    if (rot_dim > head_dim) return 0;
    return ds4_gpu_glm_rope_tail_offset_tensor(x,
                                               n_tokens,
                                               n_head,
                                               head_dim,
                                               rot_dim,
                                               head_dim - rot_dim,
                                               pos0,
                                               n_ctx_orig,
                                               freq_base,
                                               freq_scale,
                                               ext_factor,
                                               attn_factor,
                                               beta_fast,
                                               beta_slow,
                                               "GLM RoPE");
}

int ds4_gpu_glm_indexer_rope_tail_tensor(
        ds4_gpu_tensor *x,
        uint32_t        n_tokens,
        uint32_t        n_head,
        uint32_t        head_dim,
        uint32_t        rot_dim,
        uint32_t        pos0,
        uint32_t        n_ctx_orig,
        float           freq_base,
        float           freq_scale,
        float           ext_factor,
        float           attn_factor,
        float           beta_fast,
        float           beta_slow) {
    return ds4_gpu_glm_rope_tail_offset_tensor(x,
                                               n_tokens,
                                               n_head,
                                               head_dim,
                                               rot_dim,
                                               0,
                                               pos0,
                                               n_ctx_orig,
                                               freq_base,
                                               freq_scale,
                                               ext_factor,
                                               attn_factor,
                                               beta_fast,
                                               beta_slow,
                                               "GLM indexer RoPE");
}

/* llms LLMS_DS4_IDX_SCORE_SG: indexer score with 4 rows per simdgroup (apply_ds4_idx_score_sg.py); the kernel exists only in the
 * replacement source build_idx/dsv4_misc_sg.metal (DS4_METAL_DSV4_MISC_SOURCE), so the switch is on only when both are set.
 * 1 = on, 2 = canary (grid sized for half the rows). */
static uint64_t g_llms_idx_score_sg_calls, g_llms_idx_score_sg_rows;
static void llms_idx_score_sg_report(void) { fprintf(stderr, "llms idx score sg: %llu dispatches, %llu rows\n",
    (unsigned long long)g_llms_idx_score_sg_calls, (unsigned long long)g_llms_idx_score_sg_rows); }
/* llms IDX_SCORE_SGM (apply_ds4_idx_score_sgm.py): the indexer score on simdgroup-matrix tiles. 2 / 4 / 8 = row tiles per simdgroup; -4 canary */
static uint64_t g_llms_idx_sgm_calls;
static void llms_idx_sgm_report(void) { fprintf(stderr, "llms idx score sgm: %llu dispatches\n", (unsigned long long)g_llms_idx_sgm_calls); }
static int llms_idx_score_sgm(void) {
    static int on = -99;
    if (on == -99) {
        const char *e = getenv("LLMS_DS4_IDX_SCORE_SGM"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
        on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -4 : atoi(e);
        if (on != 0 && on != 2 && on != 4 && on != 8 && on != -4) on = 4;
        if (on && !(src && llms_srckey(src, "llms4") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_IDX_SCORE_SGM ignored: DS4_METAL_DSV4_MISC_SOURCE does not name a *llms4.metal source\n"), LLMS_G_NAME); on = 0; }
        if (on) { fprintf(stderr, on < 0 ? "llms: indexer score on tiles -- CANARY: grid sized for half the rows\n" : "llms: indexer score on tiles (%d row tiles per simdgroup; NOT bit-exact)\n", on); atexit(llms_idx_sgm_report); }
    }
    return on;
}
static int llms_idx_score_sg(void) {
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("LLMS_DS4_IDX_SCORE_SG"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE");
        const int want = e && *e && *e != '0';
        on = want && src && llms_srckey(src, "dsv4_misc_sg") != NULL ? (!strcmp(e, "canary") ? 2 : 1) : 0;
        if (want) fprintf(stderr, on == 2 ? "llms: indexer score, 4 rows per simdgroup -- CANARY: grid sized for half the rows\n" :
                                  on ? "llms: indexer score with 4 rows per simdgroup\n" :
                                       "llms: LLMS_DS4_IDX_SCORE_SG ignored: DS4_METAL_DSV4_MISC_SOURCE does not name dsv4_misc_sg\n");
        if (want && !on) llms_guard_fail(LLMS_G_NAME);
        if (on) atexit(llms_idx_score_sg_report);
    }
    return on;
}
int ds4_gpu_glm_indexer_score_one_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !indexer_key_cache ||
        n_rows == 0 || n_head == 0 || head_dim == 0 ||
        !isfinite(scale) || scale <= 0.0f) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> scoresbuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> cachebuf = ds4_gpu_tensor_buffer(indexer_key_cache);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_rows * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_head * head_dim * sizeof(float);
        const uint64_t weights_bytes = (uint64_t)n_head * sizeof(float);
        const uint64_t cache_bytes = (uint64_t)n_rows * head_dim * cache_elem_bytes;
        if (!scoresbuf || !qbuf || !weightsbuf || !cachebuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(indexer_key_cache) < cache_bytes) {
            fprintf(stderr, "ds4: Metal GLM indexer score received undersized buffers\n");
            return 0;
        }

        ds4_gpu_glm_indexer_score_one_args args = {
            .n_rows = n_rows,
            .n_head = n_head,
            .head_dim = head_dim,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .scale = scale,
        };

        {   /* llms IDX_HALF: the SGM kernel on a half key cache (llms13 misc source) */
            static int ih = -2;
            if (ih < -1) { const char *e = getenv("LLMS_DS4_IDX_HALF"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); ih = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                           if (ih && !(src && llms_srckey(src, "llms13") != NULL)) ih = 0; }
            if (n_head == 32u && head_dim == 128u && cache_f16 && ih && llms_idx_score_sgm() > 0 && !llms_alt_off("idxsgm")) {
                const int nrt = llms_idx_score_sgm(); const NSUInteger nr = (NSUInteger)nrt * 8u;
                static char nmh[48]; snprintf(nmh, sizeof nmh, "kernel_llms_indexer_score_sgm_h_t%d", nrt);
                id<MTLComputePipelineState> tp = n_rows >= nr ? ds4_gpu_get_pipeline(nmh) : nil;
                if (tp) {
                    int owned = 0;
                    id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                    if (!cb) return 0;
                    ds4_gpu_glm_indexer_score_one_args hargs = args;   /* persistent kernel (07:2x): the grid is capped; the canary scores half the rows */
                    if (ih < 0) hargs.n_rows = (n_rows + 1u) / 2u;
                    const NSUInteger nblk = ((NSUInteger)hargs.n_rows + nr - 1u) / nr;
                    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                    [enc setComputePipelineState:tp];
                    [enc setBytes:&hargs length:sizeof(hargs) atIndex:0];
                    [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
                    [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
                    [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
                    [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
                    [enc setThreadgroupMemoryLength:nr * 32u * sizeof(float) + 32u * 128u * sizeof(uint16_t) atIndex:0];
                    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(MIN(nblk, (NSUInteger)256u), 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
                    ds4_gpu_end_compute_encoder(cb, enc);
                    g_llms_idx_sgm_calls++;
                    if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sgm half")) return 0;
                    return 1;
                }
            }
        }
        if (n_head == 32u && head_dim == 128u && !cache_f16 && llms_idx_score_sgm() && !llms_alt_off("idxsgm")) {   /* llms IDX_SCORE_SGM; ALT */
            const int nrt = llms_idx_score_sgm() < 0 ? 4 : llms_idx_score_sgm(); const NSUInteger nr = (NSUInteger)nrt * 8u;
            static char nm[48]; snprintf(nm, sizeof nm, "kernel_llms_indexer_score_sgm_t%d", nrt);
            id<MTLComputePipelineState> tp = n_rows >= nr ? ds4_gpu_get_pipeline(nm) : nil;
            if (tp) {
                int owned = 0;
                id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
                if (!cb) return 0;
                const NSUInteger grid_rows = llms_idx_score_sgm() < 0 ? ((NSUInteger)n_rows + 1u) / 2u : (NSUInteger)n_rows;   /* canary */
                id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
                [enc setComputePipelineState:tp];
                [enc setBytes:&args length:sizeof(args) atIndex:0];
                [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
                [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
                [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
                [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
                [enc setThreadgroupMemoryLength:nr * 32u * sizeof(float) atIndex:0];
                [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((grid_rows + nr - 1u) / nr, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
                ds4_gpu_end_compute_encoder(cb, enc);
                g_llms_idx_sgm_calls++;
                if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sgm")) return 0;
                return 1;
            }
        }
        if (n_head == 32u && head_dim == 128u && !cache_f16 && llms_idx_score_sg()) {   /* llms IDX_SCORE_SG */
            id<MTLComputePipelineState> sg_pipeline = ds4_gpu_get_pipeline("kernel_glm_indexer_score_one_sg");
            if (!sg_pipeline) return 0;
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;
            const NSUInteger sg_rows = llms_idx_score_sg() == 2 ? ((NSUInteger)n_rows + 1u) / 2u : (NSUInteger)n_rows;
            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:sg_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
            [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((sg_rows + 15u) / 16u, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);
            g_llms_idx_score_sg_calls++; g_llms_idx_score_sg_rows += n_rows;
            if (!ds4_gpu_finish_command_buffer(cb, owned, "llms indexer score sg")) return 0;
            return 1;
        }
        if (n_head == 32u && head_dim == 128u) {
            id<MTLComputePipelineState> direct_pipeline =
                ds4_gpu_hot_pipeline(g_glm_indexer_score_one_direct_pipeline,
                                     "kernel_glm_indexer_score_one_direct");
            if (!direct_pipeline) return 0;

            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:direct_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
            [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
            [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
            [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
            [enc setThreadgroupMemoryLength:(128u + 4u) * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer direct score")) return 0;
            return 1;
        }

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_glm_indexer_score_one_pipeline,
                                 "kernel_glm_indexer_score_one");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        const NSUInteger nth = ds4_gpu_rms_norm_threads(head_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
        [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer score")) return 0;
    }

    return 1;
}

static int ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              row_group_size,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16,
        bool                  tiled_f32) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!scores || !q || !weights || !indexer_key_cache ||
        n_rows == 0 || n_tokens == 0 || row_group_size == 0 ||
        n_head == 0 || head_dim != 128 ||
        pos0 > UINT32_MAX - n_tokens ||
        (uint64_t)(pos0 + n_tokens) / row_group_size > n_rows ||
        !isfinite(scale) || scale <= 0.0f) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> scoresbuf = ds4_gpu_tensor_buffer(scores);
        id<MTLBuffer> qbuf = ds4_gpu_tensor_buffer(q);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> cachebuf = ds4_gpu_tensor_buffer(indexer_key_cache);
        const uint64_t cache_elem_bytes = cache_f16 ? sizeof(uint16_t) : sizeof(float);
        const uint64_t score_bytes = (uint64_t)n_rows * n_tokens * sizeof(float);
        const uint64_t q_bytes = (uint64_t)n_tokens * n_head * head_dim * sizeof(float);
        const uint64_t weights_bytes = (uint64_t)n_tokens * n_head * sizeof(float);
        const uint64_t cache_bytes = (uint64_t)n_rows * head_dim * cache_elem_bytes;
        if (!scoresbuf || !qbuf || !weightsbuf || !cachebuf ||
            ds4_gpu_tensor_bytes(scores) < score_bytes ||
            ds4_gpu_tensor_bytes(q) < q_bytes ||
            ds4_gpu_tensor_bytes(weights) < weights_bytes ||
            ds4_gpu_tensor_bytes(indexer_key_cache) < cache_bytes) {
            fprintf(stderr, "ds4: Metal GLM indexer batch scores received undersized buffers\n");
            return 0;
        }

        const bool force_scalar = g_quality_mode;
        const bool use_tiled_f32 = tiled_f32;
        const bool use_tiled = !force_scalar && n_tokens >= 8u &&
                               n_head == 32u && head_dim == 128u;
        id<MTLComputePipelineState> pipeline =
            use_tiled
                ? ds4_gpu_hot_pipeline(use_tiled_f32 ? g_glm_indexer_scores_tiled_f32_pipeline
                                                     : g_glm_indexer_scores_tiled_pipeline,
                                       use_tiled_f32 ? "kernel_glm_indexer_scores_tiled_f32"
                                                     : "kernel_glm_indexer_scores_tiled")
                : ds4_gpu_hot_pipeline(g_glm_indexer_scores_batch_pipeline,
                                       "kernel_glm_indexer_scores_batch");
        if (!pipeline) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        ds4_gpu_glm_indexer_scores_batch_args args = {
            .n_rows = n_rows,
            .n_tokens = n_tokens,
            .n_head = n_head,
            .head_dim = head_dim,
            .pos0 = pos0,
            .cache_f16 = cache_f16 ? 1u : 0u,
            .row_group_size = row_group_size,
            .pad0 = 0,
            .q_token_stride = (uint64_t)n_head * head_dim * sizeof(float),
            .q_head_stride = (uint64_t)head_dim * sizeof(float),
            .weights_token_stride = (uint64_t)n_head * sizeof(float),
            .score_token_stride = (uint64_t)n_rows * sizeof(float),
            .scale = scale,
        };
        const NSUInteger nth = ds4_gpu_rms_norm_threads(head_dim);

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:qbuf offset:ds4_gpu_tensor_offset(q) atIndex:1];
        [enc setBuffer:weightsbuf offset:ds4_gpu_tensor_offset(weights) atIndex:2];
        [enc setBuffer:cachebuf offset:ds4_gpu_tensor_offset(indexer_key_cache) atIndex:3];
        [enc setBuffer:scoresbuf offset:ds4_gpu_tensor_offset(scores) atIndex:4];
        if (use_tiled) {
            const NSUInteger q_shared = 8u * 128u;
            const NSUInteger k_shared = 32u * 128u;
            const NSUInteger dot_shared = 8u * 32u;
            if (use_tiled_f32) {
                [enc setThreadgroupMemoryLength:(q_shared + k_shared + dot_shared) *
                                                sizeof(float) atIndex:0];
            } else {
                [enc setThreadgroupMemoryLength:(q_shared + k_shared) * sizeof(uint16_t) +
                                                dot_shared * sizeof(float) atIndex:0];
            }
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(((NSUInteger)n_rows + 31u) / 32u,
                                                  ((NSUInteger)n_tokens + 7u) / 8u,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(32, 4, 1)];
        } else {
            [enc setThreadgroupMemoryLength:nth * sizeof(float) atIndex:0];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows,
                                                  (NSUInteger)n_tokens,
                                                  1)
                 threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        }
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "GLM indexer batch scores")) return 0;
    }

    return 1;
}

int ds4_gpu_glm_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
        const ds4_gpu_tensor *indexer_key_cache,
        uint32_t              n_rows,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              n_head,
        uint32_t              head_dim,
        float                 scale,
        bool                  cache_f16) {
    return ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
            scores, q, weights, indexer_key_cache, n_rows, n_tokens, pos0, 1u,
            n_head, head_dim, scale, cache_f16, false);
}

int ds4_gpu_glm53_indexer_scores_batch_tensor(
        ds4_gpu_tensor       *scores,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *weights,
