    if (pool_size != 4u) return 0;
    return ds4_gpu_glm_indexer_scores_batch_grouped_tensor(
            scores, q, weights, indexer_key_cache, n_rows, n_tokens, pos0,
            pool_size, n_head, head_dim, scale, cache_f16, false);
