        n_head == 0 || kv_lora_dim == 0 ||
        qk_nope == 0 || (qk_rope & 1u) != 0 ||
        value_dim == 0 || qk_dim < qk_nope ||
        (qk_rope != 0 && (!isfinite(freq_base) || freq_base <= 0.0f)) ||
        (qk_rope != 0 && (!isfinite(freq_scale) || freq_scale <= 0.0f)) ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
