static int g_llms_route_layer = -1;
static uint64_t g_llms_cr_calls, g_llms_cr_boosted;
void ds4_gpu_llms_set_route_layer(int il) { g_llms_route_layer = il; }
/* llms ROWS_WIN (apply_ds4_rows_win.py): n row copies of the same size in one dispatch on the open batch encoder */
int ds4_gpu_llms_rows_copy(ds4_gpu_tensor *const *dst, const uint64_t *dst_off, ds4_gpu_tensor *const *src, const uint64_t *src_off,
                           uint32_t n, uint64_t bytes, int canary) {
    if (!n || n > llms_rows_max() || (bytes % 16u) != 0 || !g_batch_cb) return 0;   /* llms ROWS128 */
    static id<MTLComputePipelineState> pl; static int tried;
    if (!tried) { tried = 1; pl = ds4_gpu_get_pipeline("kernel_llms_rows_copy"); if (!pl) fprintf(stderr, "llms rows win: kernel_llms_rows_copy missing (an *llms11* misc source is needed)\n"); }
    if (!pl) return 0;
    struct { uint64_t s, d; } rec[128];
    NSMutableArray<id<MTLBuffer>> *reads = [NSMutableArray array], *writes = [NSMutableArray array];
    if (@available(macOS 13.0, *)) {
        for (uint32_t i = 0; i < n; i++) {
            id<MTLBuffer> bs = ds4_gpu_tensor_buffer(src[i]), bd = ds4_gpu_tensor_buffer(dst[i]);
            if (!bs || !bd || src_off[i] + bytes > ds4_gpu_tensor_bytes(src[i]) || dst_off[i] + bytes > ds4_gpu_tensor_bytes(dst[i])) return 0;
            rec[i].s = (uint64_t)[bs gpuAddress] + ds4_gpu_tensor_offset(src[i]) + src_off[i];
            rec[i].d = (uint64_t)[bd gpuAddress] + ds4_gpu_tensor_offset(dst[i]) + dst_off[i];
            [reads addObject:bs]; [writes addObject:bd];
        }
    } else return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    if (!enc) return 0;
    g_batch_has_work = YES;
    const uint32_t nf4 = (uint32_t)(bytes / 16u) - (canary ? 1u : 0u);
    [enc setComputePipelineState:pl];
    [enc setBytes:&nf4 length:sizeof(nf4) atIndex:0];
    [enc setBytes:rec length:sizeof(rec[0]) * n atIndex:1];
    for (id<MTLBuffer> b in reads) [enc useResource:b usage:MTLResourceUsageRead];
    for (id<MTLBuffer> b in writes) [enc useResource:b usage:MTLResourceUsageWrite];
    [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
    ds4_gpu_end_compute_encoder(g_batch_cb, enc);
    return 1;
}

static dispatch_queue_t g_llms_bpf_q; static uint64_t g_llms_bpf_calls, g_llms_bpf_advised;
static void llms_bpf_report(void) { fprintf(stderr, "llms bpf: %llu layer calls, %llu experts advised (side-file gate + up, GGUF down)\n",
                                            (unsigned long long)g_llms_bpf_calls, (unsigned long long)g_llms_bpf_advised); }
void ds4_gpu_llms_bpf_prefetch(uint32_t layer, const uint8_t *want, uint64_t down_offset, uint64_t down_expert_bytes) {
    if (!g_ssd_streaming_mode || layer >= 40u || !llms_gubs() || g_llms_gubs_fd < 0 || g_model_fd_nocache < 0 || !g_llms_gubs_matb) return;
    if (!g_llms_bpf_q) { g_llms_bpf_q = dispatch_queue_create("llms.bpf", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_SERIAL, QOS_CLASS_UTILITY, 0));
                         atexit(llms_bpf_report); fprintf(stderr, "llms: bpf (batched page-cache prefetch of the previous step's selections at IOPOL_UTILITY)\n"); }
    uint16_t *list = (uint16_t *)malloc(384 * sizeof(uint16_t)); uint32_t n = 0;
    if (!list) return;
    for (uint32_t e = 0; e < 384u; e++) if (want[e] && !g_stream_expert_cache[layer][e].valid) list[n++] = (uint16_t)e;
    g_llms_bpf_calls++;
    if (!n) { free(list); return; }
    g_llms_bpf_advised += n;
    const int sfd = g_llms_gubs_fd, mfd = g_model_fd_nocache; const uint64_t hdr = g_llms_gubs_hdr, matb = g_llms_gubs_matb, layb = g_llms_gubs_layb;
    dispatch_async(g_llms_bpf_q, ^{
        (void)setiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD, IOPOL_UTILITY);
        for (uint32_t i = 0; i < n; i++) {
            const uint64_t e = list[i], g0 = hdr + (uint64_t)layer * layb + e * matb, u0 = hdr + (uint64_t)layer * layb + 384u * matb + e * matb;
            struct radvisory ra;
            ra.ra_offset = (off_t)g0; ra.ra_count = (int)matb; (void)fcntl(sfd, F_RDADVISE, &ra);
            ra.ra_offset = (off_t)u0; ra.ra_count = (int)matb; (void)fcntl(sfd, F_RDADVISE, &ra);
            ra.ra_offset = (off_t)(down_offset + e * down_expert_bytes); ra.ra_count = (int)down_expert_bytes; (void)fcntl(mfd, F_RDADVISE, &ra);
        }
        free(list);
    });
}
int ds4_gpu_llms_resident_mask(uint32_t layer, uint8_t *mask, uint32_t n) {   /* llms ROUTE_TRACE: the layer's valid cache entries now */
    if (!g_ssd_streaming_mode || layer >= (uint32_t)DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || n > (uint32_t)DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) return 0;
    for (uint32_t e = 0; e < n; e++) mask[e] = g_stream_expert_cache[layer][e].valid != 0;
    return 1;
}
static void llms_cr_report(void) { fprintf(stderr, "llms cache route: %llu router calls with a bonus buffer, %llu resident experts boosted in total\n",
    (unsigned long long)g_llms_cr_calls, (unsigned long long)g_llms_cr_boosted); }
static id<MTLBuffer> llms_cache_route_bias(const void *model_map, uint64_t model_size, uint64_t bias_offset, uint32_t n_expert) {
    static float beta = -1.0f;
    if (beta < 0.0f) { const char *e = getenv("LLMS_DS4_CACHE_ROUTE"); beta = (e && *e) ? strtof(e, NULL) : 0.0f; if (beta < 0.0f) beta = 0.0f; if (beta > 0.0f) atexit(llms_cr_report); }
    const int layer = g_llms_route_layer; g_llms_route_layer = -1;   /* one-shot */
    if (beta <= 0.0f || !g_ssd_streaming_mode || layer < 0 || layer >= (int)DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER ||
        n_expert == 0 || n_expert > DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || !model_map ||
        bias_offset > model_size || (uint64_t)n_expert * sizeof(float) > model_size - bias_offset) return nil;
    id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)n_expert * sizeof(float) options:MTLResourceStorageModeShared];
    if (!b) return nil;
    float *d = (float *)[b contents];
    const float *src = (const float *)((const uint8_t *)model_map + bias_offset);
    uint32_t nb = 0;
    for (uint32_t e = 0; e < n_expert; e++) {
        const int res = g_stream_expert_cache[layer][e].valid != 0;
        d[e] = src[e] + (res ? beta : 0.0f); nb += (uint32_t)res;
    }
    g_llms_cr_calls++; g_llms_cr_boosted += nb;
    return b;
}

int ds4_gpu_router_select_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
        ds4_gpu_tensor       *probs,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                bias_offset,
        uint64_t                hash_offset,
        uint32_t                hash_rows,
        uint32_t                token,
        uint32_t                n_expert,
        uint32_t                n_expert_used,
        float                   expert_weight_scale,
        uint32_t                n_expert_groups,
        uint32_t                n_group_used,
        bool                    has_bias,
        bool                    hash_mode,
        const ds4_gpu_tensor *logits) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !weights || !probs || !logits || !model_map ||
        n_expert == 0 || n_expert_used == 0) return 0;
    if (hash_mode && token >= hash_rows) return 0;
    if (n_expert_groups > 1u || n_group_used > 0u) {
        fprintf(stderr, "ds4: Metal router group gating is not part of this DeepSeek V4 path\n");
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> logitsbuf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
        if (!logitsbuf || !selectedbuf || !weightsbuf || !probsbuf ||
            ds4_gpu_tensor_bytes(logits) < (uint64_t)n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_expert_used * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_expert_used * sizeof(float) ||
            ds4_gpu_tensor_bytes(probs) < (uint64_t)n_expert * sizeof(float)) {
            fprintf(stderr, "ds4: Metal router select received undersized buffers\n");
            return 0;
        }

        uint64_t bias_inner = 0;
        uint64_t hash_inner = 0;
        id<MTLBuffer> biasbuf = nil;
        id<MTLBuffer> hashbuf = nil;
        NSUInteger bias_set_offset = 0;
        NSUInteger hash_set_offset = 0;
        if (has_bias && !hash_mode) {
            const uint64_t bias_bytes = (uint64_t)n_expert * sizeof(float);
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size, bias_offset, bias_bytes, &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
            { id<MTLBuffer> llms_cb = llms_cache_route_bias(model_map, model_size, bias_offset, n_expert);   /* llms CACHE_ROUTE */
              if (llms_cb) { biasbuf = llms_cb; bias_set_offset = 0; } }
            if (g_llms_bias_ovr) { biasbuf = ds4_gpu_tensor_buffer(g_llms_bias_ovr); bias_set_offset = ds4_gpu_tensor_offset(g_llms_bias_ovr); }   /* llms DSP41_BANK */
        }
        if (hash_mode) {
            const uint64_t hash_bytes = (uint64_t)hash_rows * n_expert_used * sizeof(int32_t);
            hashbuf = ds4_gpu_wrap_model_range(model_map, model_size, hash_offset, hash_bytes, &hash_inner);
            if (!hashbuf) return 0;
            hash_set_offset = (NSUInteger)hash_inner;
        }

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        const int32_t token_i32 = (int32_t)token;
        int ok = cb &&
                 ds4_gpu_encode_router_select(cb,
                                                      selected,
                                                      weights,
                                                      probs,
                                                      logitsbuf,
                                                      ds4_gpu_tensor_offset(logits),
                                                      biasbuf,
                                                      bias_set_offset,
                                                      hashbuf,
                                                      hash_set_offset,
                                                      nil,
                                                      0,
                                                      nil,
                                                      0,
                                                      &token_i32,
                                                      hash_rows,
                                                      0,
                                                      1,
                                                      n_expert,
                                                      n_expert_used,
                                                      expert_weight_scale,
                                                      has_bias && !hash_mode,
                                                      hash_mode,
                                                      false);
        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        if (!ok) return 0;
    }

    return 1;
}

int ds4_gpu_router_select_batch_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
        ds4_gpu_tensor       *probs,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                bias_offset,
        uint64_t                hash_offset,
        uint32_t                hash_rows,
        uint32_t                n_expert_groups,
        uint32_t                n_group_used,
        bool                    has_bias,
        bool                    hash_mode,
        const ds4_gpu_tensor *logits,
        const ds4_gpu_tensor *tokens,
        uint32_t                n_expert,
        uint32_t                n_expert_used,
        float                   expert_weight_scale,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !weights || !probs || !logits || !tokens || !model_map ||
        n_expert == 0 || n_expert_used == 0 || n_tokens == 0) return 0;
    if (n_expert_groups > 1u || n_group_used > 0u) {
        fprintf(stderr, "ds4: Metal router group gating is not part of this DeepSeek V4 path\n");
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> logitsbuf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
        id<MTLBuffer> tokensbuf = ds4_gpu_tensor_buffer(tokens);
        if (!logitsbuf || !selectedbuf || !weightsbuf || !probsbuf || !tokensbuf ||
            ds4_gpu_tensor_bytes(logits) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_tokens * n_expert_used * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_tokens * n_expert_used * sizeof(float) ||
            ds4_gpu_tensor_bytes(probs) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(tokens) < (uint64_t)n_tokens * sizeof(int32_t)) {
            fprintf(stderr, "ds4: Metal router batch select received undersized buffers\n");
            return 0;
        }

        uint64_t bias_inner = 0;
        uint64_t hash_inner = 0;
        id<MTLBuffer> biasbuf = nil;
        id<MTLBuffer> hashbuf = nil;
        NSUInteger bias_set_offset = 0;
        NSUInteger hash_set_offset = 0;
        if (has_bias && !hash_mode) {
            const uint64_t bias_bytes = (uint64_t)n_expert * sizeof(float);
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size, bias_offset, bias_bytes, &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
            { id<MTLBuffer> llms_cb = llms_cache_route_bias(model_map, model_size, bias_offset, n_expert);   /* llms CACHE_ROUTE */
              if (llms_cb) { biasbuf = llms_cb; bias_set_offset = 0; } }
            if (g_llms_bias_ovr) { biasbuf = ds4_gpu_tensor_buffer(g_llms_bias_ovr); bias_set_offset = ds4_gpu_tensor_offset(g_llms_bias_ovr); }   /* llms DSP41_BANK */
        }
        if (hash_mode) {
            const uint64_t hash_bytes = (uint64_t)hash_rows * n_expert_used * sizeof(int32_t);
            hashbuf = ds4_gpu_wrap_model_range(model_map, model_size, hash_offset, hash_bytes, &hash_inner);
            if (!hashbuf) return 0;
            hash_set_offset = (NSUInteger)hash_inner;
        }

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        int ok = cb &&
                 ds4_gpu_encode_router_select(cb,
                                                      selected,
                                                      weights,
                                                      probs,
                                                      logitsbuf,
                                                      ds4_gpu_tensor_offset(logits),
                                                      biasbuf,
                                                      bias_set_offset,
                                                      hashbuf,
                                                      hash_set_offset,
                                                      tokensbuf,
                                                      ds4_gpu_tensor_offset(tokens),
                                                      nil,
                                                      0,
                                                      NULL,
                                                      hash_rows,
                                                      0,
                                                      n_tokens,
                                                      n_expert,
                                                      n_expert_used,
                                                      expert_weight_scale,
                                                      has_bias && !hash_mode,
                                                      hash_mode,
                                                      false);
        if (!had_batch) {
            ok = ds4_gpu_end_commands() != 0 && ok;
        }
        if (!ok) return 0;
    }

    return 1;
}

int ds4_gpu_router_select_batch_visual_tensor(
        ds4_gpu_tensor       *selected,
        ds4_gpu_tensor       *weights,
        ds4_gpu_tensor       *probs,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                bias_offset,
        uint64_t                hash_offset,
        uint32_t                hash_rows,
        bool                    has_bias,
        bool                    hash_mode,
        const void             *vision_map,
        uint64_t                vision_size,
        uint64_t                visual_bias_offset,
        const ds4_gpu_tensor *logits,
        const ds4_gpu_tensor *tokens,
        uint32_t                vocab_size,
        uint32_t                n_expert,
        uint32_t                n_expert_used,
        float                   expert_weight_scale,
        uint32_t                n_tokens) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!selected || !weights || !probs || !logits || !tokens ||
        !model_map || !vision_map || vocab_size == 0 || n_tokens == 0 ||
        n_expert != 256u || n_expert_used != 6u ||
        fabsf(expert_weight_scale - 1.5f) > 1.0e-6f) return 0;

    @autoreleasepool {
        id<MTLBuffer> logitsbuf = ds4_gpu_tensor_buffer(logits);
        id<MTLBuffer> selectedbuf = ds4_gpu_tensor_buffer(selected);
        id<MTLBuffer> weightsbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> probsbuf = ds4_gpu_tensor_buffer(probs);
        id<MTLBuffer> tokensbuf = ds4_gpu_tensor_buffer(tokens);
        if (!logitsbuf || !selectedbuf || !weightsbuf || !probsbuf || !tokensbuf ||
            ds4_gpu_tensor_bytes(logits) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(selected) < (uint64_t)n_tokens * n_expert_used * sizeof(int) ||
            ds4_gpu_tensor_bytes(weights) < (uint64_t)n_tokens * n_expert_used * sizeof(float) ||
            ds4_gpu_tensor_bytes(probs) < (uint64_t)n_tokens * n_expert * sizeof(float) ||
            ds4_gpu_tensor_bytes(tokens) < (uint64_t)n_tokens * sizeof(int32_t)) {
            fprintf(stderr, "ds4: Metal visual router received undersized buffers\n");
            return 0;
        }

        uint64_t bias_inner = 0, hash_inner = 0, visual_inner = 0;
        id<MTLBuffer> biasbuf = nil, hashbuf = nil;
        NSUInteger bias_set_offset = 0, hash_set_offset = 0;
        if (has_bias && !hash_mode) {
            biasbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                               bias_offset,
                                               (uint64_t)n_expert * sizeof(float),
                                               &bias_inner);
            if (!biasbuf) return 0;
            bias_set_offset = (NSUInteger)bias_inner;
        }
        if (hash_mode) {
            hashbuf = ds4_gpu_wrap_model_range(
                    model_map, model_size, hash_offset,
                    (uint64_t)hash_rows * n_expert_used * sizeof(int32_t),
                    &hash_inner);
            if (!hashbuf) return 0;
            hash_set_offset = (NSUInteger)hash_inner;
        }
        id<MTLBuffer> visual_biasbuf = ds4_gpu_wrap_model_range(
                vision_map, vision_size, visual_bias_offset,
                (uint64_t)n_expert * sizeof(float), &visual_inner);
        if (!visual_biasbuf) return 0;

        const bool had_batch = g_batch_cb != nil;
        if (!had_batch && ds4_gpu_begin_commands() == 0) return 0;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        int ok = cb && ds4_gpu_encode_router_select(
                cb, selected, weights, probs,
                logitsbuf, ds4_gpu_tensor_offset(logits),
                biasbuf, bias_set_offset,
                hashbuf, hash_set_offset,
                tokensbuf, ds4_gpu_tensor_offset(tokens),
                visual_biasbuf, (NSUInteger)visual_inner,
                NULL, hash_rows, vocab_size, n_tokens,
                n_expert, n_expert_used, expert_weight_scale,
                has_bias && !hash_mode, hash_mode, true);
        if (!had_batch) ok = ds4_gpu_end_commands() != 0 && ok;
        if (!ok) return 0;
    }
    return 1;
}

int ds4_gpu_routed_moe_set_selected_override(const int32_t *selected, uint32_t n_selected) {
    if (n_selected > DS4_METAL_MAX_ROUTED_EXPERT_USED ||
        (!selected && n_selected != 0)) return 0;
    for (uint32_t i = 0; i < n_selected; i++) {
        g_routed_moe_selected_override[i] = selected[i];
    }
    g_routed_moe_selected_override_n = n_selected;
    return 1;
}


/* Single-simdgroup MXFP4 decode MoE policy: the nsg=1 pair_swiglu/sum6
 * variants are the pre-M5 Apple-Silicon default for single-token decode
 * (bit-exact; only the row-to-simdgroup mapping changes).  Read on the
 * dispatch path so A/B harnesses can toggle it after engine creation. */
static bool ds4_gpu_mxfp4_moe_decode_nsg1_enabled(uint32_t n_tokens) {
    if (n_tokens != 1) return false;
    return ds4_gpu_device_is_pre_m5_apple_silicon() &&
           getenv("DS4_METAL_DISABLE_PRE_M5_MXFP4_MOE_DECODE_NSG1") == NULL;
}


/* llms MISS_SKIP_SUB helper: best-probability resident, unselected expert into slot i (returns 1 if substituted) */
static ds4_gpu_stream_expert_cache_entry *ds4_gpu_stream_expert_cache_peek(const void *, uint64_t, uint32_t, uint32_t, uint32_t,
        uint32_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);
static int llms_ms_sub_impl(uint32_t i, int have_probs, const float *probs, uint32_t *sub_mask, int32_t *sel, uint32_t n_expert,
        uint32_t n_total, const void *map, uint64_t size, uint32_t layer, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_bytes, uint64_t down_bytes, uint64_t *g_abs, uint64_t *u_abs, uint64_t *d_abs,
        ds4_gpu_stream_expert_cache_entry **entries, __unsafe_unretained id<MTLBuffer> *gb, NSUInteger *go, __unsafe_unretained id<MTLBuffer> *ub, NSUInteger *uo,
        __unsafe_unretained id<MTLBuffer> *db, NSUInteger *dofs) {
    if (!have_probs) return 0;
    int used[512] = {0};
    for (uint32_t j = 0; j < n_expert; j++) if (sel[j] >= 0 && sel[j] < 512) used[sel[j]] = 1;
    for (int tries = 0; tries < 24; tries++) {
        int best = -1;
        for (uint32_t e = 0; e < n_total; e++) if (!used[e] && (best < 0 || probs[e] > probs[best])) best = (int)e;
        if (best < 0) return 0;
        used[best] = 1;
        const uint64_t gr = (uint64_t)best * gate_bytes, dr = (uint64_t)best * down_bytes;
        ds4_gpu_stream_expert_cache_entry *en = ds4_gpu_stream_expert_cache_peek(map, size, layer, (uint32_t)best, n_total, n_expert,
            gate_offset + gr, up_offset + gr, down_offset + dr, gate_bytes, down_bytes);
        if (!en) continue;
        sel[i] = best; g_abs[i] = gate_offset + gr; u_abs[i] = up_offset + gr; d_abs[i] = down_offset + dr;
        entries[i] = en; gb[i] = en->gate_buffer; go[i] = en->gate_inner; ub[i] = en->up_buffer; uo[i] = en->up_inner;
        db[i] = en->down_buffer; dofs[i] = en->down_inner;
        *sub_mask |= 1u << i; g_llms_ms_sub++;
        return 1;
    }
    return 0;
}
/* llms LLMS_DS4_Q4_OVERLAY (apply_ds4_q4_overlay.py): measurement-only CPU computation of the routed MoE for chosen layers */
/* 1: computed on the CPU, out written; 0: not an overlay layer (the GPU computes); -1: error */

static int llms_routed_moe_one_tensor_impl(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *add_in,
        uint32_t                layer_index,
        bool                    force_resident);
static int llms_routed_moe_batch_tensor_impl(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        uint32_t                n_tokens,
        bool                   *mid_is_f16,
        bool                    force_resident);
static int g_llms_q4ov_depth;   /* the batch entry calls the one-token entry: only the outer call is hooked */
static int llms_ela_inflight(uint32_t L, int32_t e);   /* llms MISS_SPLIT: defined with the look-ahead below */
static int llms_decode_route_apply_row(uint32_t layer, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert,
                         uint32_t n_expert, const ds4_gpu_tensor *probs, const float *bias, uint32_t row) {   /* llms ONE_RPOL: the re-pick of one row (llms SP_ED: row r) */
    float pr[512], sc[512], w[8]; int32_t sel[8], ns[8];
    if (!ds4_gpu_tensor_read(probs, (uint64_t)row * n_total_expert * sizeof(float), pr, (uint64_t)n_total_expert * sizeof(float)) ||
        !ds4_gpu_tensor_read(selected, (uint64_t)row * n_expert * sizeof(int32_t), sel, (uint64_t)n_expert * sizeof(int32_t)) ||
        !ds4_gpu_tensor_read(weights, (uint64_t)row * n_expert * sizeof(float), w, (uint64_t)n_expert * sizeof(float))) return 0;
    const float llms_dcm = llms_dec_cold_mult();   /* llms DEC_COLD */
    for (uint32_t e = 0; e < n_total_expert; e++) {
        const int res = (int)((g_llms_vbits[layer][e >> 6] >> (e & 63u)) & 1ull);
        sc[e] = pr[e] + bias[e] + (res ? llms_dcm * ((g_llms_decode_route_band_hi && layer >= g_llms_decode_route_band_lo && layer <= g_llms_decode_route_band_hi && !llms_alt_off("band")) ? g_llms_decode_route_band_beta :   /* llms ONE_RPOL_BAND */
                                           ((g_llms_decode_route_late_l && layer >= g_llms_decode_route_late_l) ? g_llms_decode_route_late_beta : g_llms_decode_route_beta)) : 0.0f);   /* llms ONE_RPOL_LATE */
    }
    llms_decode_route_topk(sc, n_total_expert, n_expert, ns);
    {
        static int otk = -1; static uint64_t otk_drops;
        if (otk < 0) { const char *e = getenv("LLMS_DS4_DECODE_ROUTE_TOPK"); otk = e && *e ? atoi(e) : 0; if (otk < 1 || otk > 5) otk = 0;
                       if (otk || getenv("LLMS_DS4_DECODE_ROUTE_TOPK_LATE")) { if (otk) { g_llms_route_skip = 1; fprintf(stderr, "llms: one-token top-%d (the re-pick keeps its best %d of 6) -- FIDELITY DIAL\n", otk, otk); }
                                  atexit_b(^{ fprintf(stderr, "llms decode route topk: %llu slots dropped\n", (unsigned long long)otk_drops); }); } }
        static int otl_l = -1, otl_k = 0;   /* llms ONE_TOPK_LATE (apply_one_topk_late.py): L:k */
        if (otl_l < 0) { otl_l = 0; const char *e = getenv("LLMS_DS4_DECODE_ROUTE_TOPK_LATE");
                         if (e && *e && strchr(e, ':')) { otl_l = atoi(e); otl_k = atoi(strchr(e, ':') + 1); if (otl_k < 1 || otl_k > 5 || otl_l < 1) { otl_l = 0; otl_k = 0; } }
                         if (otl_k) { g_llms_route_skip = 1; fprintf(stderr, "llms: one-token top-%d in layers >= %d -- FIDELITY DIAL\n", otl_k, otl_l); } }
        int kk = otk; if (otl_k && (int)layer >= otl_l && (!kk || otl_k < kk)) kk = otl_k;
        if (kk && n_expert <= 8u && !llms_alt_off("otk")) for (uint32_t i = (uint32_t)kk; i < n_expert; i++) if (ns[i] >= 0) { ns[i] = -1; otk_drops++; }   /* ALT otk */
        {
            static float cum = -1.0f; static uint64_t cum_drops;
            if (cum < 0.0f) { const char *e = getenv("LLMS_DS4_DECODE_ROUTE_CUM"); cum = e && *e ? (float)atof(e) : 0.0f; if (!(cum > 0.0f && cum < 1.0f)) cum = 0.0f;
                              if (cum > 0.0f) { g_llms_route_skip = 1; fprintf(stderr, "llms: one-token cumulative-mass keep %.2f -- FIDELITY DIAL\n", (double)cum);
                                                atexit_b(^{ fprintf(stderr, "llms decode route cum: %llu slots dropped\n", (unsigned long long)cum_drops); }); } }
            if (cum > 0.0f && n_expert <= 8u) {
                float tot = 0.0f; for (uint32_t i = 0; i < n_expert; i++) if (ns[i] >= 0) tot += pr[ns[i]];
                float run = 0.0f; uint32_t kept = 0;
                for (uint32_t i = 0; i < n_expert; i++) {
                    if (ns[i] < 0) continue;
                    if (kept >= 2u && run >= cum * tot) { ns[i] = -1; cum_drops++; continue; }
                    run += pr[ns[i]]; kept++;
                }
            }
        }
    }


    {
        static int msp = -1, msp_count = 0; static uint64_t msp_rows, msp_heavy, msp_light;
        if (msp < 0) { const char *e = getenv("LLMS_DS4_DECODE_ROUTE_MISS_SPLIT"); msp = 0;
                       if (e && *e) { if (!strcmp(e, "count")) { msp = 2; msp_count = 1; } else { msp = atoi(e); if (msp < 1 || msp > 5) msp = 0; } }
                       if (msp) { if (!msp_count) g_llms_route_skip = 1;
                                  fprintf(stderr, "llms: decode route miss split %d%s (a non-resident pick outside the row's %d heaviest is %s; FIDELITY DIAL)\n", msp, msp_count ? " COUNT ONLY" : "", msp, msp_count ? "counted, not dropped" : "dropped");
                                  atexit_b(^{ fprintf(stderr, "llms decode route miss split: %llu rows with a miss, %llu heavy misses kept, %llu light misses %s\n", (unsigned long long)msp_rows,
                                                      (unsigned long long)msp_heavy, (unsigned long long)msp_light, msp_count ? "counted" : "dropped"); }); } }
        static int msl_l = -1, msl_k = 0; static uint64_t msl_kept, msl_drop;
        if (msl_l < 0) { msl_l = 0; const char *e = getenv("LLMS_DS4_DECODE_ROUTE_MISS_SPLIT_LATE");
                         if (e && *e && strchr(e, ':')) { msl_l = atoi(e); msl_k = atoi(strchr(e, ':') + 1); if (msl_l < 1 || msl_l > 42 || msl_k < 0 || msl_k > 5) { msl_l = 0; msl_k = 0; } }
                         if (msl_l) { g_llms_route_skip = 1; fprintf(stderr, "llms: decode route miss split LATE: layers >= %d keep a non-resident pick only among the row's %d heaviest -- FIDELITY DIAL\n", msl_l, msl_k);
                                      atexit_b(^{ fprintf(stderr, "llms decode route miss split late: %llu late misses kept, %llu dropped\n", (unsigned long long)msl_kept, (unsigned long long)msl_drop); }); } }
        const int msl_on = msl_l && (int)layer >= msl_l && !llms_alt_off("msl");
        if ((msp || msl_on) && n_expert <= 8u && !llms_alt_off("msplit")) {
            int kk = msl_on ? msl_k : msp;
            if (msl_on && kk < 1) {   /* 10:4x: never leave a row without a routed expert -- with no resident pick, the heaviest miss stays (the first
                                         verify after a br:1 prefill met cold decoder experts, dropped every pick of a row, and the step failed) */
                int res_any = 0;
                for (uint32_t j = 0; j < n_expert; j++) if (ns[j] >= 0 && ((((g_llms_vbits[layer][ns[j] >> 6] >> (ns[j] & 63u)) & 1ull)) || llms_ela_inflight(layer, ns[j]))) { res_any = 1; break; }
                if (!res_any) kk = 1;
            }
            int any = 0;
            for (uint32_t i = 0; i < n_expert; i++) {
                if (ns[i] < 0) continue;
                if (((g_llms_vbits[layer][ns[i] >> 6] >> (ns[i] & 63u)) & 1ull) || llms_ela_inflight(layer, ns[i])) continue;
                any = 1;
                uint32_t rank = 0;
                for (uint32_t j = 0; j < n_expert; j++) if (j != i && ns[j] >= 0 && (pr[ns[j]] > pr[ns[i]] || (pr[ns[j]] == pr[ns[i]] && j < i))) rank++;
                if (rank < (uint32_t)kk) { msp_heavy++; if (msl_on) msl_kept++; continue; }
                msp_light++; if (msl_on) msl_drop++;
                if (!msp_count || msl_on) ns[i] = -1;
            }
            msp_rows += (uint64_t)any;
        }
    }
    uint32_t same = 0;
    for (uint32_t i = 0; i < n_expert; i++) for (uint32_t j = 0; j < n_expert; j++) if (ns[i] == sel[j]) { same++; break; }
    if (g_llms_decode_route_check) { if (same != n_expert) g_llms_decode_route_checkbad++; return 1; }
    if (same == n_expert) return 1;
    float ws = 0.0f, ps = 0.0f;
    for (uint32_t i = 0; i < n_expert; i++) { ws += w[i]; ps += ns[i] >= 0 ? pr[ns[i]] : 0.0f; }
    for (uint32_t i = 0; i < n_expert; i++) w[i] = (ps > 0.0f && ns[i] >= 0) ? pr[ns[i]] / ps * ws : 0.0f;
    if (!ds4_gpu_tensor_write((ds4_gpu_tensor *)weights, (uint64_t)row * n_expert * sizeof(float), w, (uint64_t)n_expert * sizeof(float)) ||
        !ds4_gpu_tensor_write((ds4_gpu_tensor *)selected, (uint64_t)row * n_expert * sizeof(int32_t), ns, (uint64_t)n_expert * sizeof(int32_t))) return 0;
    g_llms_decode_route_changed++; g_llms_decode_route_swapped += n_expert - same;
    return 1;
}
static int g_llms_sped_canary;   /* llms SP_ED canary: rows after the first skip the re-pick */
static int llms_decode_route_apply(uint32_t layer, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert,
                         uint32_t n_expert, const ds4_gpu_tensor *probs, const float *bias, uint32_t n_tokens) {   /* llms SP_ED: every row of the request */
    for (uint32_t r = 0; r < (n_tokens ? n_tokens : 1u); r++) {
        if (r > 0 && g_llms_sped_canary) continue;
        if (!llms_decode_route_apply_row(layer, selected, weights, n_total_expert, n_expert, probs, bias, r)) return 0;
    }
    return 1;
}

static uint64_t g_llms_sped_calls;
int ds4_gpu_llms_ed_rows_begin(const ds4_gpu_tensor *probs, const ds4_gpu_tensor *weights, uint32_t layer_index, int canary) {
    if (!(llms_decode_experts_bs64() && llms_gubs() && llms_ed() && layer_index < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER)) return 0;
    if (!g_llms_ed_pre && g_stream_expert_cache_slab_slot_bytes != 0) { g_llms_ed_pre = 1; llms_ed_prealloc(); }
    const uint32_t budget = ds4_gpu_stream_expert_cache_configured_budget();
    if (!(budget != 0 && g_stream_expert_cache_slab_total_slots >= budget && g_stream_expert_cache_slab_count != 0)) {
        static int tr = -1; static uint64_t trn; if (tr < 0) { const char *e = getenv("LLMS_DS4_ED_TRACE"); tr = e && *e && *e != '0'; }
        if (tr && trn++ < 8) fprintf(stderr, "llms ed trace: unarmed at layer %u: pre %d slot_bytes %llu slab_count %u total_slots %u budget %u requested %u mlock_cap %u\n", layer_index, g_llms_ed_pre, (unsigned long long)g_stream_expert_cache_slab_slot_bytes, g_stream_expert_cache_slab_count, g_stream_expert_cache_slab_total_slots, budget, ds4_gpu_stream_expert_cache_requested_budget(), g_stream_expert_cache_mlock_budget_cap);
        return 0; }
    if (!g_llms_sped_calls++) atexit_b(^{ fprintf(stderr, "llms sp ed: %llu k-row routed calls served by the ED listener\n", (unsigned long long)g_llms_sped_calls); });
    g_llms_sped_canary = canary;
    g_llms_ed_call = 1; g_llms_ed_probs = probs; g_llms_ed_bias = g_llms_route_bias_host; g_llms_ed_weights = weights;
    return 1;
}
int ds4_gpu_llms_ed_rows_end(uint32_t layer_index, int ok) {   /* the one-token wrapper's commit cadence */
    if (!g_llms_ed_call) return ok;
    g_llms_ed_call = 0; ++g_llms_ed_k;
    const uint32_t ek = g_llms_ed_every;
    if (ok && (g_llms_ed_k % ek) == 0 && ds4_gpu_flush_commands() == 0) ok = 0;
    if (g_llms_ed_err) ok = 0;
    (void)layer_index;
    return ok;
}
int ds4_gpu_routed_moe_one_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *add_in,
        uint32_t                layer_index,
        bool                    force_resident) {
    if (!g_llms_q4ov_depth && llms_decode_experts_bs64() && llms_gubs() && gate_expert_bytes == LLMS_BS6C_IQ2_GATE && layer_index < 40u) {   /* llms ONE_BS6C */
        if (llms_ed() && !g_llms_ed_pre && g_stream_expert_cache_slab_slot_bytes != 0) { g_llms_ed_pre = 1; llms_ed_prealloc(); }   /* llms ED v4 */
        const uint32_t llms_ed_budget = ds4_gpu_stream_expert_cache_configured_budget();   /* llms ED v3: event-driven only once every slab exists */
        const int llms_ed_now = llms_ed() && layer_index < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER && llms_ed_budget != 0 &&
                                g_stream_expert_cache_slab_total_slots >= llms_ed_budget && g_stream_expert_cache_slab_count != 0;
        if (llms_or() && !llms_ed_now) {   /* llms ONE_RPOL (encode time; under ED the listener applies it) */
            g_llms_decode_route_calls++;
            if (!g_llms_route_probs || !g_llms_route_bias_host || n_total_expert > 512u || n_expert > 8u || layer_index >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER) g_llms_decode_route_noinput++;
            else {
                const int llms_decode_route_ended = g_batch_cb != nil;   /* llms ONE_RPOL v2 */
                if (llms_decode_route_ended && ds4_gpu_end_commands() == 0) return 0;
                if (!llms_decode_route_apply(layer_index, selected, weights, n_total_expert, n_expert, g_llms_route_probs, g_llms_route_bias_host, 1u)) return 0;
                if (llms_decode_route_ended && ds4_gpu_begin_commands() == 0) return 0;   /* llms ONE_RPOL v2: reopen the batch the routed path expects */
            }
        }
        if (!llms_ed_now && llms_decode_aging_clock()) llms_decode_aging_clock_tick(layer_index);   /* llms ONE_CLOCK: no listener, no race */
        bool llms_mf = false;
        if (llms_ed_now) {   /* llms ED */
            g_llms_ed_call = 1; g_llms_ed_probs = g_llms_route_probs; g_llms_ed_bias = g_llms_route_bias_host; g_llms_ed_weights = weights;
        }
        g_llms_gubs_refused = 0;   /* llms BS6C_FALLBACK */
        int llms_r1 = ds4_gpu_routed_moe_batch_tensor(out, gate, up, mid, experts, model_map, model_size, gate_offset, up_offset, down_offset,
                                                      gate_type, down_type, gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes,
                                                      expert_in_dim, expert_mid_dim, out_dim, selected, weights, n_total_expert, n_expert, clamp, x,
                                                      layer_index, 1u, &llms_mf, force_resident);
        if (!llms_r1 && g_llms_gubs_refused) {   /* llms BS6C_FALLBACK: the original IQ2 one-token path below */
            g_llms_gubs_refused = 0; g_llms_ed_call = 0; g_llms_gubs_fallbacks++;
            static int warned; if (!warned) { warned = 1; fprintf(stderr, "llms bs6c fallback: a resident-branch call with side-file offsets (layer %u) took the IQ2 one-token path\n", layer_index); }
            goto llms_gubs_fallthrough;
        }
        if (g_llms_ed_call) {   /* llms ED: commit (every k-th, v5), no wait; llms BOUNDARY: LLMS_DS4_ED_PHASE commits after layers with layer % k == 0 */
            static int edp = -1; if (edp < 0) { edp = getenv("LLMS_DS4_ED_PHASE") != NULL; if (edp) fprintf(stderr, "llms: ed phase (commit after layers 0, k, 2k, ...)\n"); }
            g_llms_ed_call = 0; ++g_llms_ed_k;
            const uint32_t ek = g_llms_ed_every;
            int due = (edp && !llms_alt_off("edp")) ? ((uint32_t)layer_index % ek) == 0u : (g_llms_ed_k % ek) == 0;
            if (llms_r1 && due && ds4_gpu_flush_commands() == 0) llms_r1 = 0; if (g_llms_ed_err) llms_r1 = 0; }
        if (llms_r1 && add_in) { llms_r1 = ds4_gpu_add_tensor(out, out, add_in, out_dim); g_llms_decode_experts_bs64_adds++; }
        g_llms_decode_experts_bs64_calls++;
        return llms_r1;
    }
llms_gubs_fallthrough:;   /* llms BS6C_FALLBACK */
    g_llms_q4ov_depth++;
    const int r = llms_routed_moe_one_tensor_impl(out, gate, up, mid, experts, model_map, model_size, gate_offset, up_offset, down_offset, gate_type, down_type, gate_expert_bytes, gate_row_bytes, down_expert_bytes, down_row_bytes, expert_in_dim, expert_mid_dim, out_dim, selected, weights, n_total_expert, n_expert, clamp, x, add_in, layer_index, force_resident);
    g_llms_q4ov_depth--;
    return r;
}
int ds4_gpu_routed_moe_batch_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        uint32_t                layer_index,
        uint32_t                n_tokens,
        bool                   *mid_is_f16,
        bool                    force_resident) {
    g_llms_q4ov_depth++;
    uint64_t llms_go = gate_offset, llms_uo = up_offset, llms_gb = gate_expert_bytes, llms_grb = gate_row_bytes;   /* llms BS6C: decode-sized calls read the side file */
    uint64_t llms_do = down_offset, llms_db = down_expert_bytes;   /* llms G32D: the down from its side file in the same calls */
    {
        static int cc = -1; static uint64_t ccn[2][2], ccr[2][2];
        if (cc < 0) { const char *ge = getenv("LLMS_DS4_GUARDS"); cc = ge && *ge && *ge != '0';
            if (cc) atexit_b(^{ fprintf(stderr, "llms codec census: prefill side %llu calls (%llu rows) / gguf %llu (%llu rows); decode side %llu (%llu rows) / gguf %llu (%llu rows)\n",
                (unsigned long long)ccn[1][0], (unsigned long long)ccr[1][0], (unsigned long long)ccn[1][1], (unsigned long long)ccr[1][1],
                (unsigned long long)ccn[0][0], (unsigned long long)ccr[0][0], (unsigned long long)ccn[0][1], (unsigned long long)ccr[0][1]); }); }
        if (cc && layer_index < 40u) {
            const uint32_t ph = __atomic_load_n(&g_llms_tl_phase, __ATOMIC_RELAXED); const int pf = ph == 2u || ph == 3u;
            const int side = llms_gubs() && gate_expert_bytes == LLMS_BS6C_IQ2_GATE && n_tokens <= llms_rows_max() && !force_resident;
            ccn[pf][!side]++; ccr[pf][!side] += n_tokens;
            static int warned = 0;
            if (!side && llms_gubs() && gate_expert_bytes == LLMS_BS6C_IQ2_GATE && !warned) { warned = 1;
                fprintf(stderr, "llms CODEC CENSUS: a routed call took the GGUF codec while the side file is on -- n_tokens %u (rows_max %u), force_resident %d, layer %u, %s "
                        "(Astra 10-21 item 1: a phase comparison here changes weights too)\n", (unsigned)n_tokens, (unsigned)llms_rows_max(), (int)force_resident, (unsigned)layer_index, pf ? "prefill" : "decode"); }
        }
    }
    if (llms_gubs() && gate_expert_bytes == LLMS_BS6C_IQ2_GATE && n_tokens <= llms_rows_max() && layer_index < 40u && !force_resident) {   /* llms ROWS128; llms BS6C_RESIDENT */
        llms_go = LLMS_BS6C_BASE + g_llms_gubs_hdr + (uint64_t)layer_index * g_llms_gubs_layb; llms_uo = llms_go + 384ull * g_llms_gubs_matb;
        llms_gb = g_llms_gubs_matb; llms_grb = 1520u; g_llms_gubs_active = 1; g_llms_gubs_xlates++;
        if (llms_g32d() && down_expert_bytes == LLMS_BS6C_DOWN) { llms_do = LLMS_G32D_BASE + g_llms_g32d_hdr + (uint64_t)layer_index * g_llms_g32d_layb; llms_db = g_llms_g32d_matb; }   /* llms G32D */
        g_llms_g32d_layer = layer_index;   /* llms G32D probe */
    }
    const int r = llms_routed_moe_batch_tensor_impl(out, gate, up, mid, experts, model_map, model_size, llms_go, llms_uo, llms_do, gate_type, down_type, llms_gb, llms_grb, llms_db, down_row_bytes, expert_in_dim, expert_mid_dim, out_dim, selected, weights, n_total_expert, n_expert, clamp, x, layer_index, n_tokens, mid_is_f16, force_resident);
    g_llms_q4ov_depth--;
    g_llms_gubs_active = 0;   /* llms BS6C */
    return r;
}

static int llms_routed_moe_one_tensor_impl(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *gate,
        ds4_gpu_tensor       *up,
        ds4_gpu_tensor       *mid,
        ds4_gpu_tensor       *experts,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                gate_offset,
        uint64_t                up_offset,
        uint64_t                down_offset,
        uint32_t                gate_type,
        uint32_t                down_type,
        uint64_t                gate_expert_bytes,
        uint64_t                gate_row_bytes,
        uint64_t                down_expert_bytes,
        uint64_t                down_row_bytes,
        uint32_t                expert_in_dim,
        uint32_t                expert_mid_dim,
        uint32_t                out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t                n_total_expert,
        uint32_t                n_expert,
        float                   clamp,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *add_in,
        uint32_t                layer_index,
        bool                    force_resident) {
    BOOL parallel_ffn_scope
        __attribute__((cleanup(ds4_gpu_parallel_ffn_scope_cleanup))) =
            g_parallel_q8_pending;
    if (!g_initialized && !ds4_gpu_init()) return 0;
    /* TP sharding: only the owned contiguous expert range is mapped,
