                                            ds4_gpu_tensor_offset(up),
                                            selectedbuf,
                                            ds4_gpu_tensor_offset(selected),
                                            gate_smem,
                                            gate_nsg,
                                            gate_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("gate_up");
        if (ok && (!fuse_pair_swiglu || use_q4_group24_experts)) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    false);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("activation_weight");
        if (ok && g_parallel_q8_pending) {
            ok = ds4_gpu_parallel_q8_matvec_encode_pending(cb, midbuf) != 0;
        }

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok && stream_expert_split_completed) {
            /* The split path already wrote the resident partial output and
             * accumulated the missing experts into out. */
        } else if (ok && use_q4_grouped_experts) {
            bool first_group = true;
            for (uint32_t expert_base = 0; ok && expert_base < n_total_expert; expert_base += q4_expert_group_size) {
                const uint32_t expert_count =
                    q4_expert_group_size < n_total_expert - expert_base ?
                    q4_expert_group_size : n_total_expert - expert_base;
                if ((uint64_t)expert_base > UINT64_MAX / down_expert_bytes ||
                    (uint64_t)expert_count > UINT64_MAX / down_expert_bytes) {
                    ok = 0;
                    break;
                }
                const uint64_t group_rel = (uint64_t)expert_base * down_expert_bytes;
                const uint64_t group_bytes = (uint64_t)expert_count * down_expert_bytes;
                if (group_rel > UINT64_MAX - down_offset) {
                    ok = 0;
                    break;
                }
                uint64_t down_group_inner = 0;
                id<MTLBuffer> down_group_buf =
                    q4_grouped_cache_views ?
                    ds4_gpu_wrap_model_exact_range(model_map,
                                                   model_size,
                                                   down_offset + group_rel,
                                                   group_bytes,
                                                   &down_group_inner) :
                    ds4_gpu_wrap_model_exact_range_transient(model_map,
                                                             model_size,
                                                             down_offset + group_rel,
                                                             group_bytes,
                                                             &down_group_inner);
                if (!down_group_buf) {
                    ok = 0;
                    break;
                }
                ds4_gpu_moe_expert_group_args group_args = {
                    .expert_base = expert_base,
                    .expert_count = expert_count,
                    .accumulate = first_group ? 0u : 1u,
                    .pad0 = 0,
                };
                ok = ds4_gpu_encode_mul_mv_group_q4_sum6(cb,
                                                          g_moe_mul_mv_group_q4_k_sum6_pipeline,
                                                          &down_args,
                                                          &group_args,
                                                          down_group_buf,
                                                          (NSUInteger)down_group_inner,
                                                          midbuf,
                                                          ds4_gpu_tensor_offset(mid),
                                                          outbuf,
                                                          ds4_gpu_tensor_offset(out),
                                                          selectedbuf,
                                                          ds4_gpu_tensor_offset(selected),
                                                          down_smem,
                                                          2);
                first_group = false;
            }
        } else if (ok && use_q4_expert_address_table) {
            ok = ds4_gpu_encode_mul_mv_addr_q4_sum6(cb,
                                                    g_moe_mul_mv_addr_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_expert_table) {
            ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                    g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_table,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2,
                                                    q4_table_queue_residency);
        } else if (ok && use_q4_group6_experts) {
            ok = ds4_gpu_encode_mul_mv_group6_sum6(cb,
                                                    g_moe_mul_mv_group6_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group6_bufs,
                                                    down_group6_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group8_experts) {
            ok = ds4_gpu_encode_mul_mv_group8_sum6(cb,
                                                    g_moe_mul_mv_group8_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group8_bufs,
                                                    down_group8_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && use_q4_group24_experts) {
            ok = ds4_gpu_encode_mul_mv_group24_sum6(cb,
                                                    g_moe_mul_mv_group24_q4_k_sum6_pipeline,
                                                    &down_args,
                                                    down_group24_bufs,
                                                    down_group24_offsets,
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    outbuf,
                                                    ds4_gpu_tensor_offset(out),
                                                    selectedbuf,
                                                    ds4_gpu_tensor_offset(selected),
                                                    down_smem,
                                                    2);
        } else if (ok && (use_q4_gather_slots || use_selected_slots)) {
            if (use_stream_expert_addr_table) {
                if (down_type == DS4_METAL_TENSOR_IQ2_XXS) {
                    ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                                                        g_moe_mul_mv_addr_iq2_xxs_pipeline,
                                                        &down_args,
                                                        stream_slot_entries,
                                                        n_expert,
                                                        stream_down_addr_buf,
                                                        midbuf,
                                                        ds4_gpu_tensor_offset(mid),
                                                        down_dst,
                                                        down_dst_off,
                                                        selected_exec_buf,
                                                        selected_exec_off,
                                                        down_smem,
                                                        2,
                                                        false, 2, nil);
                } else if (use_stream_expert_masked_addr_table) {
                    ds4_gpu_stream_expert_split_args split_args = {
                        .active_mask = 0x3fu,
                        .accumulate = 0u,
                    };
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6_masked(cb,
                                                                   g_moe_mul_mv_addr_q2_k_sum6_masked_pipeline,
                                                                   &down_args,
                                                                   &split_args,
                                                                   stream_slot_entries,
                                                                   stream_down_addr_buf,
                                                                   midbuf,
                                                                   ds4_gpu_tensor_offset(mid),
                                                                   outbuf,
                                                                   ds4_gpu_tensor_offset(out),
                                                                   selected_exec_buf,
                                                                   selected_exec_off,
                                                                   down_smem,
                                                                   2);
                } else {
                    ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(cb,
                                                             g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                                                             &down_args,
                                                             stream_slot_entries,
                                                             n_expert,
                                                             stream_down_addr_buf,
                                                             midbuf,
                                                             ds4_gpu_tensor_offset(mid),
                                                             outbuf,
                                                             ds4_gpu_tensor_offset(out),
                                                             selected_exec_buf,
                                                             selected_exec_off,
                                                             down_smem,
                                                             2,
                                                             nil);
                }
            } else {
                ok = (!use_stream_expert_cache ||
                      ds4_gpu_stream_expert_cache_mark_entries_inflight(
                              stream_slot_entries,
                              n_expert,
                              0)) &&
                     ds4_gpu_encode_mul_mv_slots6_sum6(cb,
                                                       slots_sum6_pipeline,
                                                       &down_args,
                                                       down_slot_bufs,
                                                       down_slot_offsets,
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       down_smem,
                                                       2);
            }
        } else if (ok && direct_down_sum) {
            ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                 down_sum6_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 outbuf,
                                                 ds4_gpu_tensor_offset(out),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 add_in ? ds4_gpu_tensor_buffer(add_in) : nil,
                                                 add_in ? ds4_gpu_tensor_offset(add_in) : 0,
                                                 down_smem,
                                                 down_sum6_nsg);
        } else if (ok) {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                 down_mv_pipeline,
                                                 &down_args,
                                                 down_buf,
                                                 (NSUInteger)down_inner,
                                                 midbuf,
                                                 ds4_gpu_tensor_offset(mid),
                                                 down_dst,
                                                 down_dst_off,
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 down_smem,
                                                 down_nsg,
                                                 down_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("down");
        if (ok && n_expert > 1 && !direct_down_sum && !stream_expert_split_completed) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_ONE_STAGE("sum");
        if (ok && g_parallel_ffn_mode == 2 && g_parallel_ffn_stage == 1) {
            ok = ds4_gpu_parallel_ffn_encode_second_stage(cb) != 0;
        }
        if (!ok) { if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34395); return 0; }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed tensor MoE")) { if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34397); return 0; }
        if (q4_grouped_boundary || q4_exact_boundary || q4_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                if (getenv("DS4_GLM_TP_DEBUG")) fprintf(stderr, "ds4: routed_moe_one silent return at line %d\n", 34372);
                return 0;
            }
        }
#undef DS4_METAL_PROFILE_MOE_ONE_STAGE
    }

    parallel_ffn_scope = NO;
    return 1;
}


#include <pthread.h>
#include <pthread/qos.h>
enum { LLMS_EDF_RING = 256 };
typedef struct {
    const void *model_map; uint64_t model_size; uint32_t layer; const ds4_gpu_tensor *selected; uint32_t n_tokens, n_total_expert, n_selected;
    uint64_t gate_offset, up_offset, down_offset, gate_expert_bytes, down_expert_bytes;
    __unsafe_unretained id<MTLBuffer> ga, ua, da;
    const ds4_gpu_tensor *probs, *wts; const float *bias; uint64_t v1, v2;
    int ela;   /* llms ED_LA5: this step computes the look-ahead and prefetches on it */
    int wfe;   /* llms EDF_WFE_ALT: this request's wait sleeps in WFE (decided at encode: LLMS_DS4_EDF_WFE and not ALT-off 'wfe') */
    int altoff;   /* llms EDF_TIME_C: the ALT name in LLMS_DS4_EDF_TIME_ALT was off when this request was encoded */
    int msk;   /* llms ED_SKIP: this request may drop small cold picks (decided at encode: LLMS_DS4_ED_SKIP and not ALT-off 'msk') */
    double astra_enqueue; uint32_t astra_step; /* diagnostic request identity */
    const ds4_gpu_tensor *elc_norm; uint32_t elc_rows;   /* llms KROW_LA: the request's own FFN input rows */
    int lag_on, lag_src; uint64_t lag_step;   /* llms LAG: decide this layer's lags; prepare the lag call of layer lag_src (-1: none); the step */
} llms_edf_req;
static float llms_msk_theta(void);   /* llms ED_SKIP */
static llms_edf_req g_llms_edf_ring[LLMS_EDF_RING]; static uint64_t g_llms_edf_head, g_llms_edf_tail;
static int g_llms_astra_mark; static id<MTLComputePipelineState> g_llms_astra_mark_ps;
static int g_llms_edf = -1; static id<MTLComputePipelineState> g_llms_edf_ps; static id<MTLBuffer> g_llms_edf_box; static dispatch_semaphore_t g_llms_edf_sem;
static uint64_t g_llms_edf_posts, g_llms_edf_served, g_llms_edf_fallback, g_llms_edf_retry_notices, g_llms_edf_rereads, g_llms_edf_badsum, g_llms_edf_spins;
static uint64_t g_llms_edf_aborted;   /* llms EDF_ABORT */
static void llms_edf_atexit_abort(void) { g_llms_edf_abort = 1; }
static void llms_edf_report(void) {
    fprintf(stderr, "llms ed flag: %llu posts, %llu served, %llu calls on the listener path, %llu notices needed re-reads (%llu re-reads), %llu checksum failures (retired), %llu retired without a post, %.0f spins per notice\n",
            (unsigned long long)g_llms_edf_posts, (unsigned long long)g_llms_edf_served, (unsigned long long)g_llms_edf_fallback, (unsigned long long)g_llms_edf_retry_notices,
            (unsigned long long)g_llms_edf_rereads, (unsigned long long)g_llms_edf_badsum, (unsigned long long)g_llms_edf_aborted, g_llms_edf_served ? (double)g_llms_edf_spins / (double)g_llms_edf_served : 0.0);
}
static inline uint32_t llms_edf_mix(uint32_t w, uint32_t i) { uint32_t x = w ^ (i * 0x9E3779B9u); x *= 0x85EBCA6Bu; x ^= x >> 13; x *= 0xC2B2AE35u; x ^= x >> 16; return x; }
static const volatile uint32_t *llms_edf_words(const ds4_gpu_tensor *t) { return (const volatile uint32_t *)((const uint8_t *)[ds4_gpu_tensor_buffer(t) contents] + ds4_gpu_tensor_offset(t)); }
static uint32_t llms_edf_csum(const llms_edf_req *q) {   /* the post kernel's function: sum of mixed words + the sequence number */
    uint32_t c = 0; const uint32_t ns = q->n_selected * q->n_tokens;
    const volatile uint32_t *p = llms_edf_words(q->probs), *se = llms_edf_words(q->selected), *w = llms_edf_words(q->wts);
    for (uint32_t i = 0; i < q->n_total_expert; i++) c += llms_edf_mix(p[i], i);
    for (uint32_t i = 0; i < ns; i++) { c += llms_edf_mix(se[i], 1024u + i); c += llms_edf_mix(w[i], 2048u + i); }
    return c + llms_edf_mix((uint32_t)q->v1, 4096u);
}

static int g_llms_edr = -1; static FILE *g_llms_edr_log, *g_llms_edr_rep; static uint64_t g_llms_edr_logged, g_llms_edr_replayed, g_llms_edr_mismatch, g_llms_edr_short;
static void llms_edr_report(void) {
    fprintf(stderr, "llms ed route: %llu calls logged, %llu replayed, %llu layer mismatches, %llu replay records missing\n", (unsigned long long)g_llms_edr_logged,
            (unsigned long long)g_llms_edr_replayed, (unsigned long long)g_llms_edr_mismatch, (unsigned long long)g_llms_edr_short);
    if (g_llms_edr_log) fflush(g_llms_edr_log);
}
static int llms_edr(void) {
    if (g_llms_edr < 0) {
        g_llms_edr = 0; const char *l = getenv("LLMS_DS4_ED_ROUTE_LOG"), *r = getenv("LLMS_DS4_ED_ROUTE_REPLAY");
        if (l && *l) g_llms_edr_log = fopen(l, "wb");
        if (r && *r) g_llms_edr_rep = fopen(r, "rb");
        if (g_llms_edr_log || g_llms_edr_rep) { g_llms_edr = 1; atexit(llms_edr_report);
            fprintf(stderr, "llms: ed route%s%s\n", g_llms_edr_log ? " log" : "", g_llms_edr_rep ? " replay (every routing decision pinned to the record)" : ""); }
    }
    return g_llms_edr;
}
static int llms_edr_replay(const llms_edf_req *q) {   /* 1 = the recorded selection was written into the tensors */
    int32_t hdr[2]; static float pr[1024];
    if (fread(hdr, sizeof hdr, 1, g_llms_edr_rep) != 1 || hdr[1] < 0 || hdr[1] > 64) { g_llms_edr_short++; return 0; }
    int32_t ids[64]; float wt[64];
    if (fread(pr, sizeof(float), q->n_total_expert, g_llms_edr_rep) != q->n_total_expert || fread(ids, sizeof(int32_t), (size_t)hdr[1], g_llms_edr_rep) != (size_t)hdr[1] ||
        fread(wt, sizeof(float), (size_t)hdr[1], g_llms_edr_rep) != (size_t)hdr[1]) { g_llms_edr_short++; return 0; }
    if ((uint32_t)hdr[0] != q->layer || (uint32_t)hdr[1] != q->n_selected * q->n_tokens) { g_llms_edr_mismatch++; return 0; }
    memcpy((uint8_t *)[ds4_gpu_tensor_buffer(q->selected) contents] + ds4_gpu_tensor_offset(q->selected), ids, (size_t)hdr[1] * sizeof(int32_t));
    memcpy((uint8_t *)[ds4_gpu_tensor_buffer(q->wts) contents] + ds4_gpu_tensor_offset(q->wts), wt, (size_t)hdr[1] * sizeof(float));
    g_llms_edr_replayed++; return 1;
}
static void llms_edr_write(const llms_edf_req *q) {
    const int32_t n = (int32_t)(q->n_selected * q->n_tokens), hdr[2] = {(int32_t)q->layer, n};
    fwrite(hdr, sizeof hdr, 1, g_llms_edr_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->probs) contents] + ds4_gpu_tensor_offset(q->probs), sizeof(float), q->n_total_expert, g_llms_edr_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->selected) contents] + ds4_gpu_tensor_offset(q->selected), sizeof(int32_t), (size_t)n, g_llms_edr_log);
    fwrite((const uint8_t *)[ds4_gpu_tensor_buffer(q->wts) contents] + ds4_gpu_tensor_offset(q->wts), sizeof(float), (size_t)n, g_llms_edr_log);
    g_llms_edr_logged++;
}

static ds4_gpu_stream_expert_table g_llms_ela_t[64]; static int g_llms_ela_ok[64]; static const float *g_llms_ela_bias[64];
static const ds4_gpu_tensor *g_llms_ela_sel, *g_llms_ela_probs;   /* g_llms_ela_m: see llms ED_LA2 above */
static uint64_t g_llms_ela_reads, g_llms_ela_req, g_llms_ela_fin, g_llms_ela_used, g_llms_ela_unused, g_llms_ela_bad, g_llms_ela_err, g_llms_ela_none;
static void llms_ela_report(void) {
    fprintf(stderr, "llms ed la: %llu predictions read (%llu malformed), %llu with nothing to fetch, %llu skipped (previous prefetch in flight); "
            "%llu experts prefetched (%llu begin errors, %llu aio refusals, %llu read failures); %llu installs before the peek (%llu waited on the read), "
            "%llu prefetched experts selected, %llu installed unasked, %llu in flight and unused at their layer\n",
            (unsigned long long)g_llms_ela_reads, (unsigned long long)g_llms_ela_bad, (unsigned long long)g_llms_ela_none, (unsigned long long)g_llms_ela_busy,
            (unsigned long long)g_llms_ela_req, (unsigned long long)g_llms_ela_err, (unsigned long long)g_llms_ela_aio_refused, (unsigned long long)g_llms_ela_aio_fail,
            (unsigned long long)g_llms_ela_fin, (unsigned long long)g_llms_ela_waited, (unsigned long long)g_llms_ela_used, (unsigned long long)g_llms_ela_late,
            (unsigned long long)g_llms_ela_unused);     fprintf(stderr, "llms ed la slots: %llu predictions dropped with every slot reading, %llu experts already in flight\n", (unsigned long long)g_llms_ela_full, (unsigned long long)g_llms_ela_dup);   /* llms ED_LA9 */
    fprintf(stderr, "llms ed la timing: used installs: mean lead %.3f ms (n %llu), mean read %.3f ms (n %llu); %llu waits, mean wait %.3f ms, total %.1f ms\n",
            g_llms_ela_nlead ? g_llms_ela_lead_ms / g_llms_ela_nlead : 0.0, (unsigned long long)g_llms_ela_nlead, g_llms_ela_nread ? g_llms_ela_read_ms / g_llms_ela_nread : 0.0,
            (unsigned long long)g_llms_ela_nread, (unsigned long long)g_llms_ela_waited, g_llms_ela_waited ? g_llms_ela_wait_ms / g_llms_ela_waited : 0.0, g_llms_ela_wait_ms);   /* llms ED_LA4 */
}
void ds4_gpu_llms_ela_note(uint32_t layer, const void *map, uint64_t size, uint32_t n_total, uint64_t gate_off, uint64_t up_off, uint64_t down_off,
                           uint64_t gate_bytes, uint64_t down_bytes, const ds4_gpu_tensor *sel, const ds4_gpu_tensor *probs, const float *bias, int m) {
    if (layer >= 64u || m <= 0) return;
    if (!g_llms_ela_m) { g_llms_ela_sel = sel; g_llms_ela_probs = probs; atexit(llms_ela_report);
                         fprintf(stderr, "llms: ed la (layer l+1's router on layer l's FFN input; its top %d non-resident experts prefetched by the ED server)\n", m);
                         __atomic_store_n(&g_llms_ela_m, m, __ATOMIC_RELEASE); }
    if (!__atomic_load_n(&g_llms_ela_ok[layer], __ATOMIC_ACQUIRE)) {
        g_llms_ela_t[layer] = (ds4_gpu_stream_expert_table){ .model_map = map, .model_size = size, .layer = layer, .n_total_expert = n_total,
            .gate_offset = gate_off, .up_offset = up_off, .down_offset = down_off, .gate_expert_bytes = gate_bytes, .down_expert_bytes = down_bytes };
        g_llms_ela_bias[layer] = bias;
        __atomic_store_n(&g_llms_ela_ok[layer], 1, __ATOMIC_RELEASE);
    }
}
