    static float s[512];
    for (uint32_t r = 0; r < nt; r++) s[r] = pr[r] + (g_llms_ela_bias[L1] ? g_llms_ela_bias[L1][r] : 0.0f);
    int32_t top[8]; const uint32_t nn = llms_ela_policy_top(s, L1, nt, ns, top);
    g_llms_ela_reads++;
    uint32_t w = 0;
    w = llms_ela_take(s, L1, nt, top, nn, (uint32_t)g_llms_ela_m, out);   /* llms ELA_TAKE */
    if (!w) g_llms_ela_none++;
    return w;
}
enum { LLMS_ELA_SLOTS = 4 };   /* llms ED_LA9: prefetches in flight at once */
typedef struct { ds4_gpu_stream_expert_pending_load p; dispatch_group_t grp; uint32_t left; int busy; double t_issue, t_done; int lag; } llms_ela_slot;   /* lag: llms LAG v2 */
static int g_llms_ela_lagbg;   /* llms LAG v2: llms_ela_begin is reading for LAG (a deferred demand read, not a prefetch) */
static dispatch_queue_t g_llms_lag_q;   /* llms LAG v2: its reads' queue (USER_INITIATED) */
static llms_ela_slot g_llms_ela_s[LLMS_ELA_SLOTS];   /* g_llms_ela_full / _dup: declared with the ED_LA2 globals */
static int llms_ela_inflight(uint32_t L, int32_t e) {
    for (int k = 0; k < LLMS_ELA_SLOTS; k++) { const llms_ela_slot *s = &g_llms_ela_s[k]; if (!s->busy || s->p.layer != L) continue;
        for (uint32_t i = 0; i < s->p.n_selected && i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++) if (s->p.selected_ids[i] == e) return 1; }
    return 0;
}
static void llms_ela_install(llms_ela_slot *s) {   /* reads landed (or awaited): install, free the slot */
    int ok = 1; for (uint32_t i = 0; i < s->p.n_tasks; i++) if (!s->p.tasks[i].ok) ok = 0;
    {
        static int ck = -1; static uint64_t ck_tasks, ck_zero;
        if (ck < 0) { const char *e = getenv("LLMS_DS4_ELA_CHECK"); ck = e && *e && *e != '0';
                      if (ck) atexit_b(^{ fprintf(stderr, "llms ela check: %llu tasks checked at install, %llu with an all-zero destination sample\n", (unsigned long long)ck_tasks, (unsigned long long)ck_zero); }); }
        for (uint32_t i = 0; ck && i < s->p.n_tasks; i++) {
            const ds4_gpu_stream_expert_read_task *t = &s->p.tasks[i]; ck_tasks++;
            if (!t->dst || t->len < 192u) continue;
            const uint8_t *pp[3] = { t->dst, t->dst + t->len / 2u, t->dst + t->len - 64u }; int nz = 0;
            for (int q = 0; q < 3; q++) for (int j = 0; j < 64; j++) nz |= pp[q][j];
            if (!nz) { ck_zero++;
                if (ck_zero <= 40) fprintf(stderr, "llms ela check: ZERO layer %u task %u of %u (load %u) offset %s%llu len %llu dst %p read %llu ok %d ms %.3f issue->now %.3f ms left %u\n",
                    s->p.layer, i, s->p.n_tasks, i / 3u, t->offset >= (1ull << 60) ? "bs6c+" : "", (unsigned long long)(t->offset >= (1ull << 60) ? t->offset - (1ull << 60) : t->offset),
                    (unsigned long long)t->len, (const void *)t->dst, (unsigned long long)t->read_bytes, t->ok, t->ms, ds4_gpu_now_ms() - s->t_issue,
                    __atomic_load_n(&s->left, __ATOMIC_ACQUIRE)); }
        }
    }
    if (ok) { if (!ds4_gpu_stream_expert_pending_load_install(&s->p, NULL, (s->t_done > 0.0 ? s->t_done : ds4_gpu_now_ms()) - s->t_issue)) g_llms_ela_aio_fail++; }
    else g_llms_ela_aio_fail++;
    ds4_gpu_stream_expert_pending_load_release_buffers(&s->p); s->p.active = 0; s->p.n_tasks = 0; s->p.n_loads = 0; s->busy = 0;
}
static void llms_ela_begin(uint32_t L1, const int32_t *ids0, uint32_t n0) {   /* llms ED_LA9: never waits */
    int32_t ids[8]; uint32_t n = 0;
    for (uint32_t i = 0; i < n0 && n < 8u; i++) { if (llms_ela_inflight(L1, ids0[i])) { g_llms_ela_dup++; continue; } ids[n++] = ids0[i]; }
    if (!n) return;
    int k = -1;
    for (int j = 0; j < LLMS_ELA_SLOTS && k < 0; j++) if (!g_llms_ela_s[j].busy) k = j;
    if (k < 0) for (int j = 0; j < LLMS_ELA_SLOTS && k < 0; j++) if (__atomic_load_n(&g_llms_ela_s[j].left, __ATOMIC_ACQUIRE) == 0u) { llms_ela_install(&g_llms_ela_s[j]); g_llms_ela_late++; k = j; }
    if (k < 0) { g_llms_ela_full++; return; }
    if (g_stream_expert_pending_load.active) { g_llms_ela_busy++; return; }   /* the engine's own slot is in use: no prefetch now */
    g_llms_ela_req += n;
    g_llms_ela_inbegin = 2;
    const int bok = ds4_gpu_stream_expert_cache_begin_selected_load(&g_llms_ela_t[L1], ids, n);
    g_llms_ela_inbegin = 0;
    ds4_gpu_stream_expert_pending_load *gp = &g_stream_expert_pending_load;
    if (!bok) { g_llms_ela_err++; if (gp->active) { ds4_gpu_stream_expert_pending_load_release_buffers(gp); gp->active = 0; gp->n_tasks = 0; gp->n_loads = 0; } return; }
    if (!gp->active || gp->n_tasks == 0) return;   /* nothing was missing */
    llms_ela_slot *s = &g_llms_ela_s[k];
    s->p = *gp;   /* ARC copy: the slot now holds the victim buffers */
    ds4_gpu_stream_expert_pending_load_release_buffers(gp); gp->active = 0; gp->n_tasks = 0; gp->n_loads = 0;
    if (!s->grp) s->grp = dispatch_group_create();
    if (g_llms_ela_tier < 0) {
        g_llms_ela_tier = IOPOL_UTILITY;
        g_llms_ela_q = dispatch_queue_create("llms.ela", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_CONCURRENT, QOS_CLASS_UTILITY, 0));
        fprintf(stderr, "llms: ed la slots %d, reads as libdispatch blocks at I/O tier %d\n", (int)LLMS_ELA_SLOTS, g_llms_ela_tier);
    }
    s->busy = 1; s->t_issue = ds4_gpu_now_ms(); s->t_done = 0.0; __atomic_store_n(&s->left, s->p.n_tasks + 1u, __ATOMIC_RELEASE);
    s->lag = g_llms_ela_lagbg;   /* llms LAG v2 */
    if (s->lag && !g_llms_lag_q) g_llms_lag_q = dispatch_queue_create("llms.lag", dispatch_queue_attr_make_with_qos_class(DISPATCH_QUEUE_CONCURRENT, QOS_CLASS_USER_INITIATED, 0));
    const int tier = s->lag ? IOPOL_IMPORTANT : g_llms_ela_tier;
    dispatch_queue_t llms_rq = s->lag ? g_llms_lag_q : g_llms_ela_q;   /* llms LAG v2: demand priority for LAG's reads */
    for (uint32_t i = 0; i < s->p.n_tasks; i++) {
        ds4_gpu_stream_expert_read_task *t = &s->p.tasks[i]; t->ok = 0; t->read_bytes = 0;
        dispatch_group_async(s->grp, llms_rq, ^{
            const int old = getiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD);
            (void)setiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD, tier);
            t->ok = llms_expert_read_pread(t->offset, t->len, t->dst, &t->read_bytes, &t->ms);
            (void)setiopolicy_np(IOPOL_TYPE_DISK, IOPOL_SCOPE_THREAD, old >= 0 ? old : IOPOL_DEFAULT);
            llms_ela_complete(&s->left, &s->t_done);
        });
    }
}
static void llms_ela_settle(uint32_t layer, const ds4_gpu_tensor *selected, uint32_t n_selected) {   /* llms ED_LA9: before the peek; llms SP_ED: n_selected = picks x rows */
    int32_t ids[32]; int have = -1; const uint32_t ns = n_selected <= 32u ? n_selected : 32u;
    for (int k = 0; k < LLMS_ELA_SLOTS; k++) {
        llms_ela_slot *s = &g_llms_ela_s[k]; if (!s->busy) continue;
        const int done = __atomic_load_n(&s->left, __ATOMIC_ACQUIRE) == 0u;
        uint32_t hit = 0;
        if (s->p.layer == layer) {
            if (have < 0) have = ds4_gpu_tensor_read(selected, 0, ids, (uint64_t)ns * sizeof(int32_t)) ? 1 : 0;
            if (have) for (uint32_t i = 0; i < s->p.n_selected && i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++)
                if (s->p.missing_mask & (1u << i)) for (uint32_t j = 0; j < ns; j++) if (ids[j] == s->p.selected_ids[i]) hit++;
        }
        if (g_llms_elcal > 0 && have > 0 && s->p.layer == layer && layer < 64u && !s->lag) {   /* llms ELA_CALIB; LAG v2: a lag read is no prediction */
            for (uint32_t i = 0; i < s->p.n_selected && i < DS4_METAL_STREAM_EXPERT_CACHE_MAX_SELECTED; i++) {
                if (!(s->p.missing_mask & (1u << i))) continue; const int32_t e = s->p.selected_ids[i]; if (e < 0 || e >= 512) continue;
                int used = 0; for (uint32_t j = 0; j < ns; j++) if (ids[j] == e) used = 1;
                const int b = llms_elcal_bin(g_llms_elm[layer][e]); if (used) g_llms_elc_used[b]++; else g_llms_elc_unused[b]++;
            }
        }
        if (hit) {
            g_llms_ela_lead_ms += ds4_gpu_now_ms() - s->t_issue; g_llms_ela_nlead++;
            if (!done) { g_llms_ela_waited++; const double w0 = ds4_gpu_now_ms(); dispatch_group_wait(s->grp, DISPATCH_TIME_FOREVER); g_llms_ela_wait_ms += ds4_gpu_now_ms() - w0; }
            if (s->t_done > 0.0) { g_llms_ela_read_ms += s->t_done - s->t_issue; g_llms_ela_nread++; }
            llms_ela_install(s); g_llms_ela_fin++; g_llms_ela_used += hit;
        } else if (done) { llms_ela_install(s); g_llms_ela_late++; }
        else if (s->p.layer == layer && !s->lag) g_llms_ela_unused++;   /* llms LAG v2 */
    }
}

static float g_llms_msk_th = -2.0f; static uint64_t g_llms_msk_calls, g_llms_msk_cold, g_llms_msk_drop, g_llms_msk_bg; static double g_llms_msk_share;
static void llms_msk_report(void) {
    fprintf(stderr, "llms ed skip (theta %g): %llu layer calls, %llu cold picks, %llu dropped (mean share %.4f), %llu background reads begun\n",
            (double)g_llms_msk_th, (unsigned long long)g_llms_msk_calls, (unsigned long long)g_llms_msk_cold, (unsigned long long)g_llms_msk_drop,
            g_llms_msk_drop ? g_llms_msk_share / (double)g_llms_msk_drop : 0.0, (unsigned long long)g_llms_msk_bg);
}
static float llms_msk_theta(void) {
    if (g_llms_msk_th < -1.5f) {
        const char *e = getenv("LLMS_DS4_ED_SKIP"); g_llms_msk_th = e && *e ? (float)atof(e) : -1.0f;
        if (g_llms_msk_th > 0.0f) { fprintf(stderr, "llms: ed skip (cold picks under %g of the routing weight are dropped and read in the background)\n", (double)g_llms_msk_th);
                                    atexit(llms_msk_report); }
    }
    return g_llms_msk_th;
}
static void llms_msk_apply(const llms_edf_req *q) {
    const uint32_t layer = q->layer, ns = q->n_selected;
    if (ns < 2u || ns > 8u || layer >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER || !q->wts) return;
    int32_t ids[8]; float w[8];
    if (!ds4_gpu_tensor_read(q->selected, 0, ids, (uint64_t)ns * sizeof(int32_t)) || !ds4_gpu_tensor_read(q->wts, 0, w, (uint64_t)ns * sizeof(float))) return;
    g_llms_msk_calls++;
    float sum = 0.0f; int r = -1; uint32_t cold = 0;
    for (uint32_t i = 0; i < ns; i++) {
        sum += w[i];
        if (ids[i] < 0 || (uint32_t)ids[i] >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) return;
        if (g_stream_expert_cache[layer][ids[i]].valid) { if (r < 0 || w[i] > w[r]) r = (int)i; } else cold |= 1u << i;
    }
    if (!cold || r < 0 || !(sum > 0.0f)) return;
    g_llms_msk_cold += (uint64_t)__builtin_popcount(cold);
    uint32_t drop = 0; float dropped = 0.0f;
    for (uint32_t i = 0; i < ns; i++) if ((cold & (1u << i)) && w[i] < g_llms_msk_th * sum) { drop |= 1u << i; dropped += w[i]; }
    if (!drop || !(sum - dropped > 0.0f)) return;
    int32_t bg[8]; uint32_t nbg = 0; const float k = sum / (sum - dropped);
    for (uint32_t i = 0; i < ns; i++) {
        if (drop & (1u << i)) { bg[nbg++] = ids[i]; ids[i] = ids[r]; w[i] = 0.0f; } else w[i] *= k;
    }
    if (!ds4_gpu_tensor_write((ds4_gpu_tensor *)q->wts, 0, w, (uint64_t)ns * sizeof(float)) ||
        !ds4_gpu_tensor_write((ds4_gpu_tensor *)q->selected, 0, ids, (uint64_t)ns * sizeof(int32_t))) { g_llms_ed_err = 1; return; }
    g_llms_msk_drop += nbg; g_llms_msk_share += (double)(dropped / sum);
    if (g_llms_ela_m > 0) { const uint64_t r0 = g_llms_ela_req; @autoreleasepool { llms_ela_begin(layer, bg, nbg); } g_llms_msk_bg += g_llms_ela_req - r0; }
}
/* llms EDF_PHASE (apply_edf_phase.py): per-phase time of the server's request (an instrument) */
static int g_llms_efp = -1; static double g_llms_efp_t[2][5]; static uint64_t g_llms_efp_n[2];   /* [0] no load, [1] loaded */
static void llms_efp_report(void) { for (int k = 0; k < 2; k++) if (g_llms_efp_n[k]) fprintf(stderr, "llms edf phase (%s): %llu requests; mean us: clock tick %.2f, re-pick %.2f, la settle %.2f, prepare %.2f, rest %.2f\n",
    k ? "loaded" : "no load", (unsigned long long)g_llms_efp_n[k], g_llms_efp_t[k][0] / g_llms_efp_n[k], g_llms_efp_t[k][1] / g_llms_efp_n[k], g_llms_efp_t[k][2] / g_llms_efp_n[k], g_llms_efp_t[k][3] / g_llms_efp_n[k], g_llms_efp_t[k][4] / g_llms_efp_n[k]); }
static inline double llms_efp_us(void) { return (double)clock_gettime_nsec_np(CLOCK_UPTIME_RAW) * 1e-3; }
static int g_llms_pcr = -1; static uint64_t g_llms_pcr_rows;
static int llms_pcr_on(void) {
    if (g_llms_pcr < 0) { const char *e = getenv("LLMS_DS4_PRICE_COROUTE"); g_llms_pcr = e && *e && *e != '0';
                          if (g_llms_pcr) { fprintf(stderr, "llms: PRICE_COROUTE -- PRICING (numerics wrong): verify rows take row 0's experts\n");
                                            atexit_b(^{ fprintf(stderr, "llms price coroute: %llu rows overwritten\n", (unsigned long long)g_llms_pcr_rows); }); } }
    return g_llms_pcr;
}

#define LLMS_LAG_R 4u
typedef struct { uint64_t step; uint32_t nt, ns, nte, tot; uint32_t cnt[LLMS_LAG_R]; const void *map; uint64_t size, go, uo, dof, gb, db; } llms_lag_host_t;
static int g_llms_lag = -1, g_llms_lag_lo, g_llms_lag_hi, g_llms_lag_dd, g_llms_lag_mode;
static llms_lag_host_t g_llms_lag_h[64]; static int g_llms_lag_prepped[64];
static ds4_gpu_tensor *g_llms_lag_t_sel[64], *g_llms_lag_t_w[64], *g_llms_lag_t_cnt[64], *g_llms_lag_t_x[64], *g_llms_lag_t_late, *g_llms_lag_t_scr[4];
static uint64_t g_llms_lag_stepid, g_llms_lag_arm_step; static int g_llms_lag_arm_layer = -1, g_llms_lag_nw;
static int g_llms_lag_arm_src = -1;   /* v3: the source layer this request prepares (-1: none) */
static volatile uint64_t g_llms_lag_decided[64], g_llms_lag_armed[64];   /* v3: per layer, the step whose serve decided / whose request was lag-armed */
static uint64_t g_llms_lag_postc[64];   /* v3: the commit count when layer L's post was encoded (its batch is open while they are equal) */
static uint64_t g_llms_lag_nwait, g_llms_lag_ntimeout, g_llms_lag_nflush, g_llms_lag_nunarmed; static double g_llms_lag_wait_ms;
static uint64_t g_llms_lag_nsteps, g_llms_lag_npairs, g_llms_lag_nrows, g_llms_lag_nprep, g_llms_lag_nfail, g_llms_lag_nbg, g_llms_lag_ninfl, g_llms_lag_nkeep,
                g_llms_lag_nnw, g_llms_lag_nadd, g_llms_lag_nlost, g_llms_lag_byl[64];
static double g_llms_lag_prep_ms;
static id<MTLComputePipelineState> g_llms_lag_add_ps;
static void llms_lag_report(void) {
    fprintf(stderr, "llms lag (layers %d..%d, d %d, mode %d): %llu steps, %llu pairs lagged in %llu rows (%llu rows kept whole: no resident pick); %llu lag prepares "
            "(%.1f ms serving them, %llu failed); %llu adds encoded, %llu no-wait encodes; %llu reads begun in the background, %llu in flight at the decision; %llu pairs lost\n",
            g_llms_lag_lo, g_llms_lag_hi, g_llms_lag_dd, g_llms_lag_mode, (unsigned long long)g_llms_lag_nsteps, (unsigned long long)g_llms_lag_npairs, (unsigned long long)g_llms_lag_nrows,
            (unsigned long long)g_llms_lag_nkeep, (unsigned long long)g_llms_lag_nprep, g_llms_lag_prep_ms, (unsigned long long)g_llms_lag_nfail, (unsigned long long)g_llms_lag_nadd,
            (unsigned long long)g_llms_lag_nnw, (unsigned long long)g_llms_lag_nbg, (unsigned long long)g_llms_lag_ninfl, (unsigned long long)g_llms_lag_nlost);
    fprintf(stderr, "llms lag v3 waits: %llu waited (%.1f ms total, %llu flushes), %llu timeouts, %llu sources never armed\n", (unsigned long long)g_llms_lag_nwait, g_llms_lag_wait_ms,
            (unsigned long long)g_llms_lag_nflush, (unsigned long long)g_llms_lag_ntimeout, (unsigned long long)g_llms_lag_nunarmed);
    fprintf(stderr, "llms lag pairs by layer:"); for (int L = g_llms_lag_lo; L <= g_llms_lag_hi; L++) fprintf(stderr, " %d:%llu", L, (unsigned long long)g_llms_lag_byl[L]); fprintf(stderr, "\n");
}
int ds4_gpu_llms_lag_cfg(uint32_t n_embd, uint32_t n_ff, uint32_t n_used, int *lo, int *hi, int *d) {
    if (g_llms_lag < 0) {
        g_llms_lag = 0; const char *e = getenv("LLMS_DS4_LAG");
        if (e && *e && strcmp(e, "0") != 0) {
            int a = -1, b = -1, cc = -1, md = 0;
            if (g_device && sscanf(e, "%d:%d:%d:%d", &a, &b, &cc, &md) >= 3 && a >= 0 && b >= a && b < 64 && cc >= 0 && cc <= 8 && b + cc < 64 && n_used <= 8u && n_embd && n_ff) {
                int ok = 1; static const uint32_t z[LLMS_LAG_R] = {0};
                for (int L = a; L <= b && ok; L++) {
                    g_llms_lag_t_sel[L] = ds4_gpu_tensor_alloc(LLMS_LAG_R * 8u * sizeof(int32_t)); g_llms_lag_t_w[L] = ds4_gpu_tensor_alloc(LLMS_LAG_R * 8u * sizeof(float));
                    g_llms_lag_t_cnt[L] = ds4_gpu_tensor_alloc(LLMS_LAG_R * sizeof(uint32_t)); g_llms_lag_t_x[L] = ds4_gpu_tensor_alloc((uint64_t)LLMS_LAG_R * n_embd * sizeof(float));
                    ok = g_llms_lag_t_sel[L] && g_llms_lag_t_w[L] && g_llms_lag_t_cnt[L] && g_llms_lag_t_x[L] && ds4_gpu_tensor_write(g_llms_lag_t_cnt[L], 0, z, sizeof z);
                }
                g_llms_lag_t_late = ok ? ds4_gpu_tensor_alloc((uint64_t)LLMS_LAG_R * n_embd * sizeof(float)) : NULL;
                for (int k = 0; k < 3 && ok; k++) ok = (g_llms_lag_t_scr[k] = ds4_gpu_tensor_alloc((uint64_t)LLMS_LAG_R * n_used * n_ff * sizeof(float))) != NULL;
                if (ok) ok = (g_llms_lag_t_scr[3] = ds4_gpu_tensor_alloc((uint64_t)LLMS_LAG_R * n_used * n_embd * sizeof(float))) != NULL && g_llms_lag_t_late != NULL;
                if (ok) {
                    NSError *err = nil;
                    id<MTLLibrary> lib = [g_device newLibraryWithSource:@"#include <metal_stdlib>\nusing namespace metal;\n"
                        "kernel void llms_lag_add(device float *blk [[buffer(0)]], device const float *late [[buffer(1)]], device const uint *cnt [[buffer(2)]],\n"
                        "    constant uint2 &a [[buffer(3)]], uint i [[thread_position_in_grid]]) { const uint r = i / a.x; if (r >= a.y || cnt[r] == 0u) return; blk[i] += late[i]; }\n"
                        options:nil error:&err];
                    id<MTLFunction> fn = lib ? [lib newFunctionWithName:@"llms_lag_add"] : nil;
                    g_llms_lag_add_ps = fn ? [g_device newComputePipelineStateWithFunction:fn error:&err] : nil;
                    ok = g_llms_lag_add_ps != nil;
                    if (!ok) fprintf(stderr, "llms lag: the add kernel failed: %s\n", err ? err.localizedDescription.UTF8String : "?");
                }
                if (ok) { g_llms_lag_lo = a; g_llms_lag_hi = b; g_llms_lag_dd = cc; g_llms_lag_mode = md; g_llms_lag = 1; g_llms_route_skip = 1;
                          fprintf(stderr, "llms: LAG layers %d..%d, d %d, mode %d (a non-resident decode pick leaves its call and is added %d layers later%s%s) -- FIDELITY DIAL\n",
                                  a, b, cc, md, cc, (md & 1) ? "; in-flight reads stay synchronous" : "", (md & 2) ? "; DROP CANARY: never added" : "");
                          atexit(llms_lag_report); }
                else fprintf(stderr, "llms lag: allocation failed; off\n");
            } else fprintf(stderr, "llms lag: LLMS_DS4_LAG=%s not understood (lo:hi:d[:mode], hi + d < 64) or no device; off\n", e);
        }
    }
    if (lo) *lo = g_llms_lag_lo; if (hi) *hi = g_llms_lag_hi; if (d) *d = g_llms_lag_dd;
    return g_llms_lag == 1;
}
uint64_t ds4_gpu_llms_lag_step_begin(void) {   /* main thread, between steps (the previous step's GPU work and serves are done) */
    if (g_llms_lag != 1) return 0;
