    g_llms_lag_nsteps++; return ++g_llms_lag_stepid;
}
void ds4_gpu_llms_lag_step_end(void) {   /* lags decided this step that no request prepared: their outputs were never added */
    if (g_llms_lag != 1) return;
    for (int L = g_llms_lag_lo; L <= g_llms_lag_hi; L++) if (g_llms_lag_h[L].step == g_llms_lag_stepid && g_llms_lag_h[L].tot && !g_llms_lag_prepped[L]) g_llms_lag_nlost += g_llms_lag_h[L].tot;
}
void ds4_gpu_llms_lag_arm(uint32_t layer, uint64_t step) { g_llms_lag_arm_layer = step ? (int)layer : -1; g_llms_lag_arm_step = step; g_llms_lag_arm_src = -1; }
void ds4_gpu_llms_lag_arm_src(int src) { g_llms_lag_arm_src = src; }   /* v3: after ds4_gpu_llms_lag_arm, the source whose lag call this request prepares */
int ds4_gpu_llms_lag_wait(uint32_t L, uint64_t step) {   /* v3, main thread: layer L's decision this step -> pairs lagged (0 none), -1 never armed or timed out */
    if (g_llms_lag != 1 || L >= 64u || !step) return -1;
    if (__atomic_load_n(&g_llms_lag_armed[L], __ATOMIC_ACQUIRE) != step) { g_llms_lag_nunarmed++; return -1; }
    if (__atomic_load_n(&g_llms_lag_decided[L], __ATOMIC_ACQUIRE) != step) {
        const double t0 = ds4_gpu_now_ms(); g_llms_lag_nwait++;
        if (g_batch_cb && g_llms_all_commits == g_llms_lag_postc[L] && ds4_gpu_flush_commands() != 0) g_llms_lag_nflush++;   /* only when layer L's post sits in the open batch */
        for (;;) {   /* v3b: sleep in WFE, armed on the stamp's line by ldaxr (the ED server's pattern): a polling P-core takes the GPU's power */
            uint64_t v; __asm__ volatile("ldaxr %0, [%1]" : "=r"(v) : "r"(&g_llms_lag_decided[L]) : "memory");
            if (v == step) break;
