void ds4_gpu_llms_lag_nowait(int on) { g_llms_lag_nw = on; g_llms_ed_call = on ? 1 : 0; }
ds4_gpu_tensor *ds4_gpu_llms_lag_tensor(int which, uint32_t L) {
    if (g_llms_lag != 1) return NULL;
    switch (which) { case 0: return L < 64u ? g_llms_lag_t_sel[L] : NULL; case 1: return L < 64u ? g_llms_lag_t_w[L] : NULL; case 2: return L < 64u ? g_llms_lag_t_x[L] : NULL;
                     case 3: return g_llms_lag_t_late; case 4: case 5: case 6: case 7: return g_llms_lag_t_scr[which - 4]; }
    return NULL;
}
int ds4_gpu_llms_lag_add(ds4_gpu_tensor *block, uint32_t src, uint32_t rows, uint32_t n_embd) {   /* block += late on the rows whose count is > 0 */
    if (g_llms_lag != 1 || src >= 64u || !g_llms_lag_t_cnt[src] || !g_llms_lag_add_ps || !g_batch_cb || !block || rows > LLMS_LAG_R) return 0;
    id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(g_batch_cb);
    [enc setComputePipelineState:g_llms_lag_add_ps];
    [enc setBuffer:ds4_gpu_tensor_buffer(block) offset:ds4_gpu_tensor_offset(block) atIndex:0];
    [enc setBuffer:ds4_gpu_tensor_buffer(g_llms_lag_t_late) offset:ds4_gpu_tensor_offset(g_llms_lag_t_late) atIndex:1];
    [enc setBuffer:ds4_gpu_tensor_buffer(g_llms_lag_t_cnt[src]) offset:ds4_gpu_tensor_offset(g_llms_lag_t_cnt[src]) atIndex:2];
    const uint32_t a[2] = { n_embd, rows }; [enc setBytes:a length:sizeof a atIndex:3];
    [llms_bar(enc) dispatchThreads:MTLSizeMake((NSUInteger)rows * n_embd, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    g_llms_lag_nadd++;
    return 1;
}
static void llms_lag_decide_body(const llms_edf_req *q);
static void llms_lag_decide(const llms_edf_req *q) {   /* v3: the body, then the stamp the main thread waits on (lag or not) */
    llms_lag_decide_body(q);
    if (q->layer < 64u) __atomic_store_n(&g_llms_lag_decided[q->layer], q->lag_step, __ATOMIC_RELEASE);
}
static void llms_lag_decide_body(const llms_edf_req *q) {   /* serve thread, before the settle: this layer's non-resident picks leave the call */
    const uint32_t L = q->layer, ns = q->n_selected, nt = q->n_tokens ? q->n_tokens : 1u;
    if (g_llms_lag != 1 || nt > LLMS_LAG_R || ns > 8u || ns == 0 || L >= 64u || !q->wts || !g_llms_lag_t_sel[L]) return;
    if (g_llms_lag_mode & 4) return;   /* LAG v2 mode 4: the instrument -- every lag call encoded, nothing lagged */
    int32_t ids[LLMS_LAG_R * 8]; float w[LLMS_LAG_R * 8];
    if (!ds4_gpu_tensor_read(q->selected, 0, ids, (uint64_t)nt * ns * sizeof(int32_t)) || !ds4_gpu_tensor_read(q->wts, 0, w, (uint64_t)nt * ns * sizeof(float))) return;
    int32_t ls[LLMS_LAG_R * 8]; float lw[LLMS_LAG_R * 8]; uint32_t cnt[LLMS_LAG_R] = {0}, tot = 0; int32_t bg[8]; uint32_t nbg = 0;
    for (uint32_t i = 0; i < nt * ns; i++) { ls[i] = -1; lw[i] = 0.0f; }
    for (uint32_t r = 0; r < nt; r++) {
        int res = 0;
        for (uint32_t i = 0; i < ns; i++) { const int32_t e = ids[r * ns + i]; if (e >= 0 && (uint32_t)e < DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT && g_stream_expert_cache[L][e].valid) res++; }
        if (!res) { g_llms_lag_nkeep++; continue; }   /* never an all-dropped row: a row with no resident pick keeps its misses */
        for (uint32_t i = 0; i < ns; i++) {
            const int32_t e = ids[r * ns + i];
            if (e < 0 || (uint32_t)e >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT || g_stream_expert_cache[L][e].valid) continue;
            const int infl = llms_ela_inflight(L, e);
            if (infl && (g_llms_lag_mode & 1)) continue;
