        !ds4_gpu_tensor_write(g_llms_lag_t_sel[L], 0, ls, nb * sizeof(int32_t)) || !ds4_gpu_tensor_write(g_llms_lag_t_w[L], 0, lw, nb * sizeof(float))) { g_llms_ed_err = 1; return; }
    llms_lag_host_t *h = &g_llms_lag_h[L];
