    h->map = q->model_map; h->size = q->model_size; h->go = q->gate_offset; h->uo = q->up_offset; h->dof = q->down_offset; h->gb = q->gate_expert_bytes; h->db = q->down_expert_bytes;
    __atomic_store_n(&h->step, q->lag_step, __ATOMIC_RELEASE);
    g_llms_lag_npairs += tot; g_llms_lag_byl[L] += tot; for (uint32_t r = 0; r < nt; r++) if (cnt[r]) g_llms_lag_nrows++;
    if (nbg && g_llms_ela_m > 0) { const uint64_t r0 = g_llms_ela_req; g_llms_ela_lagbg = 1; @autoreleasepool { llms_ela_begin(L, bg, nbg); } g_llms_ela_lagbg = 0; g_llms_lag_nbg += g_llms_ela_req - r0; }   /* LAG v2: tagged */
}
static void llms_lag_prepare(const llms_edf_req *q) {   /* serve thread: the lag call of layer q->lag_src, encoded after this request's routed kernels */
    const int L = q->lag_src;
    if (g_llms_lag != 1 || L < 0 || L >= 64) return;
