}
static void llms_edf_serve(const llms_edf_req *q) {   /* the listener block's body, unchanged, over the request's fields */
    astra_edt_phase(0);
    const uint32_t layer = q->layer, n_total_expert = q->n_total_expert, n_selected = q->n_selected; const ds4_gpu_tensor *selected = q->selected, *probs = q->probs, *wts = q->wts;
    const float *bias = q->bias;
    if (g_llms_efp < 0) { const char *e = getenv("LLMS_DS4_EDF_PHASE"); g_llms_efp = e && *e && *e != '0'; if (g_llms_efp) { fprintf(stderr, "llms: edf phase timing\n"); atexit(llms_efp_report); } }
    double llms_p0 = g_llms_efp ? llms_efp_us() : 0.0, llms_p1, llms_pt[5] = {0};   /* llms EDF_PHASE */ const uint64_t llms_pm0 = g_llms_efp ? ds4_gpu_llms_stream_misses() : 0;
    if (llms_decode_aging_clock()) llms_decode_aging_clock_tick(layer);
    if (g_llms_efp) { llms_p1 = llms_efp_us(); llms_pt[0] = llms_p1 - llms_p0; llms_p0 = llms_p1; }
    astra_edt_phase(1);
    int ok = 1;
    if (g_llms_ep_on < 0) { const char *ev = getenv("LLMS_DS4_ELA_PROTECT"); g_llms_ep_on = ev && *ev && *ev != '0';
                            if (g_llms_ep_on) { fprintf(stderr, "llms: ela protect (the look-ahead prefetch may not evict the last served request's experts)\n");
                                                atexit_b(^{ fprintf(stderr, "llms ela protect: %llu requests recorded, %llu victim candidates protected\n", (unsigned long long)g_llms_ep_sets, (unsigned long long)g_llms_ep_hits); }); } }
    g_llms_ep_layer = UINT32_MAX; g_llms_ep_n = 0;   /* llms ELA_PROTECT: this request's picks replace the last one's (recorded after the policy, below) */
    const int llms_rep = llms_edr() && g_llms_edr_rep && llms_edr_replay(q);   /* llms ED_ROUTE: the recorded selection instead of the policy */
    if (!llms_rep && llms_or() && probs && wts && bias && n_total_expert <= 512u && n_selected <= 8u) { g_llms_decode_route_calls++; ok = llms_decode_route_apply(layer, selected, wts, n_total_expert, n_selected, probs, bias, q->n_tokens); }
    if (g_llms_efp) { llms_p1 = llms_efp_us(); llms_pt[1] = llms_p1 - llms_p0; llms_p0 = llms_p1; }
    astra_edt_phase(2);
    if (ok && q->n_tokens > 1u && n_selected <= 8u && llms_pcr_on()) {   /* llms PRICE_COROUTE: rows 1.. take row 0's ids and weights */
        int32_t s0[8]; float w0[8];
        if (!ds4_gpu_tensor_read(selected, 0, s0, (uint64_t)n_selected * sizeof(int32_t)) || !wts || !ds4_gpu_tensor_read(wts, 0, w0, (uint64_t)n_selected * sizeof(float))) ok = 0;
        for (uint32_t r = 1; ok && r < q->n_tokens; r++) {
            ok = ds4_gpu_tensor_write((ds4_gpu_tensor *)selected, (uint64_t)r * n_selected * sizeof(int32_t), s0, (uint64_t)n_selected * sizeof(int32_t)) &&
                 ds4_gpu_tensor_write((ds4_gpu_tensor *)wts, (uint64_t)r * n_selected * sizeof(float), w0, (uint64_t)n_selected * sizeof(float));
            g_llms_pcr_rows++;
        }
    }
    if (llms_edr() && g_llms_edr_log) llms_edr_write(q);   /* llms ED_ROUTE: the router probs and the final selection */
    if (ok && g_llms_ep_on > 0 && !llms_alt_off("elap")) {   /* llms ELA_PROTECT: the final picks of every row */
        const uint32_t nt = (q->n_tokens ? q->n_tokens : 1u) * n_selected;
        if (nt <= 64u && ds4_gpu_tensor_read(selected, 0, g_llms_ep_ids, (uint64_t)nt * sizeof(int32_t))) { g_llms_ep_layer = layer; g_llms_ep_n = nt; g_llms_ep_sets++; }
    }
    id<MTLBuffer> g2 = nil, u2 = nil, d2 = nil, o1 = nil, o2 = nil, o3 = nil;
    ds4_gpu_stream_expert_cache_entry *r2[DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT]; uint32_t nr2 = 0, un2 = 0;
    if (ok && q->lag_on) llms_lag_decide(q);   /* llms LAG: before the settle, so a hit on an in-flight read is lagged, not waited for */
    if (ok && q->lag_src >= 0) llms_lag_prepare(q);   /* llms LAG: the lag call of layer q->lag_src rides this request */
    if (ok && g_llms_ela_m) llms_ela_settle(layer, selected, n_selected * (q->n_tokens ? q->n_tokens : 1u));   /* llms ED_LA (ED_LA9: the slots); llms SP_ED: every row */
    if (g_llms_efp) { llms_p1 = llms_efp_us(); llms_pt[2] = llms_p1 - llms_p0; llms_p0 = llms_p1; }
    astra_edt_phase(3);
