                     q->gate_offset, q->up_offset, q->down_offset, q->gate_expert_bytes, q->down_expert_bytes, &g2, &u2, &d2, r2, &nr2, &un2, &o1, &o2, &o3);
    if (g_llms_efp) { llms_p1 = llms_efp_us(); llms_pt[3] = llms_p1 - llms_p0; llms_p0 = llms_p1; }
    astra_edt_phase(4);
