        static int sc = -1; static uint64_t sc_n, sc_bad;
        if (sc < 0) { const char *ev = getenv("LLMS_DS4_SERVE_CHECK"); sc = ev && *ev && *ev != '0';
                      if (sc) atexit_b(^{ fprintf(stderr, "llms serve check: %llu selected experts checked at release, %llu failures\n", (unsigned long long)sc_n, (unsigned long long)sc_bad); }); }
        const uint32_t nt = (q->n_tokens ? q->n_tokens : 1u) * n_selected; int32_t sid[64];
        if (sc && ok && nt <= 64u && layer < DS4_METAL_STREAM_EXPERT_CACHE_MAX_LAYER && ds4_gpu_tensor_read(selected, 0, sid, (uint64_t)nt * sizeof(int32_t))) {
            for (uint32_t i = 0; i < nt; i++) {
                if (sid[i] < 0 || (uint32_t)sid[i] >= DS4_METAL_STREAM_EXPERT_CACHE_MAX_EXPERT) continue;
                const ds4_gpu_stream_expert_cache_entry *e = &g_stream_expert_cache[layer][sid[i]]; sc_n++;
                id<MTLBuffer> ab[3] = { g_stream_expert_cache_gate_addr_buffers[layer], g_stream_expert_cache_up_addr_buffers[layer], g_stream_expert_cache_down_addr_buffers[layer] };
                uint64_t av[3] = {0, 0, 0}; for (int k = 0; k < 3; k++) if (ab[k]) av[k] = ((const uint64_t *)[ab[k] contents])[sid[i]];
                const uint64_t ev3[3] = { e->valid ? ds4_gpu_buffer_address(e->gate_buffer, e->gate_inner) : 0, e->valid ? ds4_gpu_buffer_address(e->up_buffer, e->up_inner) : 0,
                                          e->valid ? ds4_gpu_buffer_address(e->down_buffer, e->down_inner) : 0 };
                int dz = 0;
                if (e->valid && e->gate_buffer && e->up_buffer) {
                    const uint64_t gb = e->gate_expert_bytes ? e->gate_expert_bytes : 0;
                    const uint8_t *gp = (const uint8_t *)[e->gate_buffer contents] + e->gate_inner, *up = (const uint8_t *)[e->up_buffer contents] + e->up_inner;
                    if (gb >= 192u) { int zg = 0, zu = 0;   /* 22:1x: every 64 KiB of gate and up, 64 bytes each; any all-zero sample flags */
                        for (uint64_t o = 0; o + 64u <= gb; o += 65536u) { int a1 = 0, a2 = 0; for (int j = 0; j < 64; j++) { a1 |= gp[o + j]; a2 |= up[o + j]; } if (!a1) zg = 1; if (!a2) zu = 1; }
                        dz = zg | (zu << 1); }
                }
                const int bad = !e->valid || !av[0] || !av[1] || !av[2] || av[0] != ev3[0] || av[1] != ev3[1] || av[2] != ev3[2] || dz;
                if (bad) { sc_bad++;
                    if (sc_bad <= 40) fprintf(stderr, "llms serve check: BAD layer %u expert %d (row %u): valid %d addr g %llx u %llx d %llx | entry g %llx u %llx d %llx | data zero mask %d gbytes %llu\n",
                        layer, sid[i], i / n_selected, (int)e->valid, (unsigned long long)av[0], (unsigned long long)av[1], (unsigned long long)av[2],
                        (unsigned long long)ev3[0], (unsigned long long)ev3[1], (unsigned long long)ev3[2], dz, (unsigned long long)e->gate_expert_bytes); }
            }
        }
    }
    if (ok && g_llms_ed_canary && n_selected >= 2) {   /* llms ED canary: the first pick reads the second pick's slot */
        int32_t cs[8];
        if (n_selected <= 8 && ds4_gpu_tensor_read(selected, 0, cs, (uint64_t)n_selected * sizeof(int32_t)) && cs[0] >= 0 && cs[1] >= 0 && cs[0] != cs[1]) {
            ds4_gpu_stream_expert_cache_entry *e1 = &g_stream_expert_cache[layer][cs[1]];
            if (e1->valid) (void)ds4_gpu_stream_expert_cache_set_addr_slot(layer, (uint32_t)cs[0], e1->gate_buffer, e1->gate_inner, e1->up_buffer, e1->up_inner, e1->down_buffer, e1->down_inner);
