    if (g_llms_efp) { llms_p1 = llms_efp_us(); llms_pt[4] = llms_p1 - llms_p0; const int ld = ds4_gpu_llms_stream_misses() != llms_pm0; for (int k = 0; k < 5; k++) g_llms_efp_t[ld][k] += llms_pt[k]; g_llms_efp_n[ld]++; }
}

static int g_llms_eft = -1; static uint64_t g_llms_eft_h[8][12], g_llms_eft_n[8]; static double g_llms_eft_s[8], g_llms_eft_rel;   /* llms EDF_TIME_D: [6] / [7] serve no load / loaded with the ALT OFF */   /* llms EDF_TIME_B / _C: [3] boundary, [4] boundary on steps where the ALT name in LLMS_DS4_EDF_TIME_ALT is OFF, [5] within-token on those steps */
static void llms_eft_add(int k, double us) { int b = 0; double v = 8.0; while (b < 11 && us >= v) { v *= 2.0; b++; } g_llms_eft_h[k][b]++; g_llms_eft_n[k]++; g_llms_eft_s[k] += us; }
static void llms_eft_report(void) {
    static const char *nm[8] = { "serve, no load (ALT on or none)", "serve, loaded (ALT on or none)", "release -> next post seen (within a token; ALT on or none)", "token boundary (ALT on or none)", "token boundary (ALT off)", "within a token (ALT off)", "serve, no load (ALT off)", "serve, loaded (ALT off)" };
    for (int k = 0; k < 8; k++) { fprintf(stderr, "llms edf time %s: n %llu, mean %.1f us; bins (<8, <16, ... us):", nm[k], (unsigned long long)g_llms_eft_n[k],
                                          g_llms_eft_n[k] ? g_llms_eft_s[k] / g_llms_eft_n[k] : 0.0);
        for (int b = 0; b < 12; b++) fprintf(stderr, " %llu", (unsigned long long)g_llms_eft_h[k][b]); fprintf(stderr, "\n"); }
}

static int g_astra_efo;
static double g_astra_efo_after;
static struct { uint64_t n, ready; double arm, poll, after; } g_astra_efo_s[2];
static void astra_efo_report(void) {
    for (int i = 0; i < 2; i++) fprintf(stderr,
        "astra ed observer %s: n %llu ready_at_arm %llu arm_gap_ms_sum %.6f poll_gap_ms_sum %.6f previous_after_release_ms_sum %.6f\n",
        i ? "boundary" : "within", (unsigned long long)g_astra_efo_s[i].n,
