                "static inline uint mx(uint w, uint i) { uint x = w ^ (i * 0x9E3779B9u); x *= 0x85EBCA6Bu; x ^= x >> 13; x *= 0xC2B2AE35u; x ^= x >> 16; return x; }\n"
                "kernel void llms_edf_post(device const uint *pr [[buffer(0)]], device const uint *se [[buffer(1)]], device const uint *wt [[buffer(2)]], device atomic_uint *box [[buffer(3)]],\n"
                "    constant uint4 &a [[buffer(4)]], uint t [[thread_index_in_threadgroup]], uint lane [[thread_index_in_simdgroup]], uint sg [[simdgroup_index_in_threadgroup]]) {\n"
                "  uint c = 0; for (uint i = t; i < a.y; i += 128u) c += mx(pr[i], i);\n"
                "  for (uint i = t; i < a.z; i += 128u) { c += mx(se[i], 1024u + i); c += mx(wt[i], 2048u + i); }\n"
                "  c = simd_sum(c); threadgroup uint part[4]; if (lane == 0) part[sg] = c; threadgroup_barrier(mem_flags::mem_threadgroup);\n"
                "  if (t == 0) { atomic_store_explicit(&box[1], part[0] + part[1] + part[2] + part[3] + mx(a.x, 4096u), memory_order_relaxed); atomic_store_explicit(&box[0], a.x, memory_order_relaxed); } }\n"
                options:nil error:&err];
