                                                           gate_mm_pipeline,
                                                           &gate_mm_args,
                                                           use_iq2_cached_batch ? stream_gate_addr_buf : gate_buf,
                                                           (NSUInteger)gate_inner,
                                                           use_packed_mpp ? g_moe_packed_rhs_buffer : xbuf,
                                                           use_packed_mpp ? 0 : ds4_gpu_tensor_offset(x),
                                                           gatebuf,
                                                           ds4_gpu_tensor_offset(gate),
                                                           packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                           use_iq2_cached_batch ? stream_resources : NULL,
                                                           stream_resource_count, 0, stream_overflow_gate,
                                                           packed_m32n128 ? 32u : 64u);
                DS4_METAL_PROFILE_MOE_STAGE("gate");
            }
            if (ok && !use_mm_id_pair_swiglu) {
                ok = ds4_gpu_encode_mul_mm_id_mapped_tile_resources(cb,
                                                   up_mm_pipeline,
                                                   &gate_mm_args,
                                                   use_iq2_cached_batch ? stream_up_addr_buf : up_buf,
                                                   (NSUInteger)up_inner,
                                                   use_packed_mpp ? g_moe_packed_rhs_buffer : xbuf,
                                                   use_packed_mpp ? 0 : ds4_gpu_tensor_offset(x),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                   use_iq2_cached_batch ? stream_resources : NULL,
                                                   stream_resource_count, 1, stream_overflow_up,
                                                   packed_m32n128 ? 32u : 64u);
                DS4_METAL_PROFILE_MOE_STAGE("up");
            }
        } else if (use_iq2_cached_batch && use_tiny_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim, .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float), .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_routed_gateup_swiglu(cb,
                g_moe_mul_mv_addr_iq2_xxs_pair_swiglu_pipeline, &gate_args, &act_args,
                stream_resources, stream_resource_count, stream_gate_addr_buf, stream_up_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), gatebuf, ds4_gpu_tensor_offset(gate),
                upbuf, ds4_gpu_tensor_offset(up), midbuf, ds4_gpu_tensor_offset(mid),
                selectedbuf, ds4_gpu_tensor_offset(selected), weightsbuf, ds4_gpu_tensor_offset(weights),
                gate_smem, 2, false, stream_overflow_gate, stream_overflow_up);
        } else if (use_iq2_cached_batch) {
            ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                g_moe_mul_mv_addr_iq2_xxs_pipeline, &gate_args,
                stream_resources, stream_resource_count, stream_gate_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), gatebuf, ds4_gpu_tensor_offset(gate),
                selectedbuf, ds4_gpu_tensor_offset(selected), gate_smem, gate_nsg,
                gate_rows_per_group_is_nr0, 0, stream_overflow_gate) &&
                 ds4_gpu_encode_mul_mv_addr_iq2(cb,
                g_moe_mul_mv_addr_iq2_xxs_pipeline, &gate_args,
                stream_resources, stream_resource_count, stream_up_addr_buf,
                xbuf, ds4_gpu_tensor_offset(x), upbuf, ds4_gpu_tensor_offset(up),
                selectedbuf, ds4_gpu_tensor_offset(selected), gate_smem, gate_nsg,
                gate_rows_per_group_is_nr0, 1, stream_overflow_up);
        } else if (use_tiny_pair_swiglu) {
            ds4_gpu_dsv4_moe_swiglu_weight_args act_args = {
                .width = expert_mid_dim,
                .rows = pair_rows,
                .gate_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .up_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .mid_row_stride = (uint64_t)expert_mid_dim * sizeof(float),
                .weight_stride = sizeof(float),
                .write_clamped = 0,
                .clamp_value = clamp,
            };
            ok = ds4_gpu_encode_mul_mv_id_pair_swiglu(cb,
                                                       tiny_pair_swiglu_pipeline,
                                                       &gate_args,
                                                       &act_args,
                                                       gate_buf,
                                                       (NSUInteger)gate_inner,
                                                       up_buf,
                                                       (NSUInteger)up_inner,
                                                       xbuf,
                                                       ds4_gpu_tensor_offset(x),
                                                       gatebuf,
                                                       ds4_gpu_tensor_offset(gate),
                                                       upbuf,
                                                       ds4_gpu_tensor_offset(up),
                                                       midbuf,
                                                       ds4_gpu_tensor_offset(mid),
                                                       selectedbuf,
                                                       ds4_gpu_tensor_offset(selected),
                                                       weightsbuf,
                                                       ds4_gpu_tensor_offset(weights),
                                                       gate_smem,
                                                       use_tp_mxfp4_static_batch ? 1 : 2,
                                                       false);
        } else if (use_tiny_pair_mv) {
            id<MTLComputePipelineState> pair_pipeline =
                gate_type == DS4_METAL_TENSOR_IQ2_XXS ?
                    g_moe_mul_mv_id_iq2_xxs_pair_pipeline :
                    g_moe_mul_mv_id_q4_k_pair_pipeline;
            ok = ds4_gpu_encode_mul_mv_id_pair(cb,
                                                 pair_pipeline,
                                                 &gate_args,
                                                 gate_buf,
                                                 (NSUInteger)gate_inner,
                                                 up_buf,
                                                 (NSUInteger)up_inner,
                                                 xbuf,
                                                 ds4_gpu_tensor_offset(x),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 selectedbuf,
                                                 ds4_gpu_tensor_offset(selected),
                                                 gate_smem,
                                                 2,
                                                 false);
        } else {
            ok = ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  gate_buf,
                                                  (NSUInteger)gate_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  gatebuf,
                                                  ds4_gpu_tensor_offset(gate),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  gate_nsg,
                                                  gate_rows_per_group_is_nr0) &&
                 ds4_gpu_encode_mul_mv_id(cb,
                                                  gate_mv_pipeline,
                                                  &gate_args,
                                                  up_buf,
                                                  (NSUInteger)up_inner,
                                                  xbuf,
                                                  ds4_gpu_tensor_offset(x),
                                                  upbuf,
                                                  ds4_gpu_tensor_offset(up),
                                                  selectedbuf,
                                                  ds4_gpu_tensor_offset(selected),
                                                  gate_smem,
                                                  gate_nsg,
                                                  gate_rows_per_group_is_nr0);
        }
        DS4_METAL_PROFILE_MOE_STAGE("gate_up");
        const bool use_fused_activation = !g_quality_mode && !use_q4_batch_expert_table;
        const bool use_mid_f16 =
            use_mm_id &&
            use_fused_activation &&
            request_mid_f16;
        if (mid_is_f16) *mid_is_f16 = use_mid_f16;
        if (ok && use_iq2_batch_selected_addr) {
            /* The address-table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_q4_batch_expert_table) {
            /* The table pair kernel already wrote weighted SwiGLU rows into mid. */
        } else if (ok && use_mm_id_pair_swiglu) {
            /* The fused batch mm_id pair kernel already wrote weighted f16 SwiGLU rows into mid. */
        } else if (ok && use_tiny_pair_swiglu) {
            /* The fused tiny pair kernel already wrote weighted F32 SwiGLU rows into mid. */
        } else if (ok && use_fused_activation) {
            ok = ds4_gpu_encode_moe_swiglu_weight(cb,
                                                    gatebuf,
                                                    ds4_gpu_tensor_offset(gate),
                                                    upbuf,
                                                    ds4_gpu_tensor_offset(up),
                                                    midbuf,
                                                    ds4_gpu_tensor_offset(mid),
                                                    weightsbuf,
                                                    ds4_gpu_tensor_offset(weights),
                                                    expert_mid_dim,
                                                    pair_rows,
                                                    clamp,
                                                    use_mid_f16);
        } else if (ok && clamp > 1.0e-6f) {
            ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 gatebuf,
                                                 ds4_gpu_tensor_offset(gate),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -FLT_MAX,
                                                 clamp);
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                     g_unary_silu_pipeline,
                                                     gatebuf,
                                                     ds4_gpu_tensor_offset(gate),
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     expert_mid_dim,
                                                     pair_rows,
                                                     1,
                                                     0.0f,
                                                     0.0f);
            }
            if (ok) {
                ok = ds4_gpu_encode_unary_f32_rows(cb,
                                                 g_unary_clamp_pipeline,
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 upbuf,
                                                 ds4_gpu_tensor_offset(up),
                                                 expert_mid_dim,
                                                 pair_rows,
                                                 0,
                                                 -clamp,
                                                 clamp);
            }
            if (ok) {
                ds4_gpu_bin_args mul_args =
                    ds4_gpu_make_bin_same_rows_args(expert_mid_dim, pair_rows);
                ok = ds4_gpu_encode_bin_f32_rows(cb,
                                                   g_mul_pipeline,
                                                   &mul_args,
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid),
                                                   upbuf,
                                                   ds4_gpu_tensor_offset(up),
                                                   midbuf,
                                                   ds4_gpu_tensor_offset(mid));
            }
        } else if (ok) {
            ok = ds4_gpu_encode_swiglu_flat(cb,
                                              gatebuf,
                                              ds4_gpu_tensor_offset(gate),
                                              upbuf,
                                              ds4_gpu_tensor_offset(up),
                                              midbuf,
                                              ds4_gpu_tensor_offset(mid),
                                              (uint32_t)((uint64_t)pair_rows * expert_mid_dim));
        }
        if (ok && !use_fused_activation && !use_q4_batch_expert_table) {
            ds4_gpu_bin_args weight_args =
                ds4_gpu_make_bin_rowwise_scalar_args(expert_mid_dim, pair_rows);
            ok = ds4_gpu_encode_bin_f32_rows(cb,
                                               g_bin_mul_scalar_pipeline,
                                               &weight_args,
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid),
                                               weightsbuf,
                                               ds4_gpu_tensor_offset(weights),
                                               midbuf,
                                               ds4_gpu_tensor_offset(mid));
        }
        DS4_METAL_PROFILE_MOE_STAGE("activation_weight");

        id<MTLBuffer> down_dst = n_expert == 1 ? outbuf : (expertsbuf ? expertsbuf : g_moe_down_scratch_buffer);
        NSUInteger down_dst_off = n_expert == 1 ? ds4_gpu_tensor_offset(out) :
            (expertsbuf ? ds4_gpu_tensor_offset(experts) : 0);
        if (ok) {
            if (use_iq2_batch_selected_addr) {
                g_llms_dd_site = 1;   /* llms DOWN_DD: the peeked ids are this group-layer's */
                if (g_llms_cd_layer && g_llms_dt8_layer && g_llms_cd_dirty_n > 0) {   /* llms DOWN_T8: pass 1's tiles (if not yet run) and pass 2's, before the dirty tokens' down */
                    if (!g_llms_dt8_p1_done && g_llms_dt8_n1) { ok = llms_dt8_encode(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            selectedbuf, ds4_gpu_tensor_offset(selected), g_llms_dt8_eoff1, g_llms_dt8_n1, 0, stream_overflow_down); g_llms_dt8_p1_done = 1; }
                    if (ok && g_llms_dt8_n2 && llms_down_t8() > 0) ok = llms_dt8_encode(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            selectedbuf, ds4_gpu_tensor_offset(selected), g_llms_dt8_eoff2, g_llms_dt8_n2, g_llms_dt8_n1, stream_overflow_down);
                    if (!ok) { fprintf(stderr, "llms down t8: pass-2 tiles failed layer %u\n", layer_index); return 0; }
                }
                {
                    static FILE *pl = (FILE *)1; static uint64_t pn;
                    if (pl == (FILE *)1) { const char *e = getenv("LLMS_DS4_PATH_LOG"); pl = e && *e ? fopen(e, "w") : NULL; }
                    if (pl) { fprintf(pl, "%llu %u %u splits %llu tok %d t8 %d k1 %u k2 %u dirty %u\n", (unsigned long long)pn++, layer_index, n_tokens, (unsigned long long)g_llms_split_pass1, g_llms_cd_layer,   /* splits: the running count of split layer-calls (the local flag is out of scope here) */
                                      g_llms_dt8_layer, g_llms_dt8_n1, g_llms_dt8_n2, g_llms_cd_layer ? g_llms_cd_dirty_n : 0u); fflush(pl); }
                }
                if (g_llms_cd_layer) {   /* llms CLEAN_DOWN: the clean tokens' projection ran in the pass-1 buffer */
                    g_llms_cd_layer = 0;
                    ok = g_llms_cd_dirty_n == 0 ? 1 : llms_encode_down_tok(cb, &down_args, stream_resources, stream_resource_count, stream_down_addr_buf, midbuf, ds4_gpu_tensor_offset(mid),
                            outbuf, ds4_gpu_tensor_offset(out), selectedbuf, ds4_gpu_tensor_offset(selected), down_smem, 2, stream_overflow_down, g_llms_cd_dirty_off, g_llms_cd_dirty_n);
                } else
                ok = ds4_gpu_encode_mul_mv_addr_q2_sum6(
                        cb,
                        g_moe_mul_mv_addr_q2_k_sum6_pipeline,
                        &down_args,
                        stream_resources,
                        stream_resource_count,
                        stream_down_addr_buf,
                        midbuf,
                        ds4_gpu_tensor_offset(mid),
                        outbuf,
                        ds4_gpu_tensor_offset(out),
                        selectedbuf,
                        ds4_gpu_tensor_offset(selected),
                        down_smem,
                        2,
                        stream_overflow_down);
                g_llms_dd_site = 0; g_llms_peek_call = 0;
                g_llms_dt8_layer = 0; g_llms_dt8_p1_done = 0;   /* llms DOWN_T8 (apply_down_t8_fix.py): cleared after the layer's down, not before */
                if (!ok) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to encode down path tokens=%u unique=%u\n",
                            layer_index,
                            n_tokens,
                            stream_unique);
                }
            } else if (use_q4_batch_expert_table) {
                ok = ds4_gpu_encode_mul_mv_table_q4_sum6(cb,
                                                         g_moe_mul_mv_table_q4_k_sum6_pipeline,
                                                         &down_args,
                                                         down_table,
                                                         midbuf,
                                                         ds4_gpu_tensor_offset(mid),
                                                         outbuf,
                                                         ds4_gpu_tensor_offset(out),
                                                         selectedbuf,
                                                         ds4_gpu_tensor_offset(selected),
                                                         down_smem,
                                                         2,
                                                         q4_batch_table_queue_residency);
            } else if (direct_down_sum) {
                ok = ds4_gpu_encode_mul_mv_id_sum6(cb,
                                                     down_sum6_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     outbuf,
                                                     ds4_gpu_tensor_offset(out),
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     nil,
                                                     0,
                                                     down_smem,
                                                     use_tp_mxfp4_static_batch ? 1 : 2);
            } else if (use_mm_id) {
                if (use_packed_mpp)
                    ok = ds4_gpu_encode_moe_packed_rhs(cb, &down_mm_args,
                                                      midbuf, ds4_gpu_tensor_offset(mid), true, packed_limit);
                if (ok) ok = ds4_gpu_encode_mul_mm_id_mapped_tile_resources(cb,
                                                       down_mm_pipeline,
                                                       &down_mm_args,
                                                       use_iq2_cached_batch ? stream_down_addr_buf : down_buf,
                                                       (NSUInteger)down_inner,
                                                       use_packed_mpp ? g_moe_packed_rhs_buffer : midbuf,
                                                       use_packed_mpp ? 0 : ds4_gpu_tensor_offset(mid),
                                                       down_dst,
                                                       down_dst_off,
                                                       packed_m32n128 ? 16384u : mm_id_mpp_active ? 12288u : 8192u,
                                                       use_iq2_cached_batch ? stream_resources : NULL,
                                                       stream_resource_count, 2, stream_overflow_down,
                                                       packed_m32n128 ? 32u : 64u);
            } else if (use_iq2_cached_batch) {
                ok = ds4_gpu_encode_mul_mv_addr_iq2(cb,
                    g_moe_mul_mv_addr_iq2_xxs_pipeline, &down_args,
                    stream_resources, stream_resource_count, stream_down_addr_buf,
                    midbuf, ds4_gpu_tensor_offset(mid), down_dst, down_dst_off,
                    selectedbuf, ds4_gpu_tensor_offset(selected), down_smem, down_nsg,
                    down_rows_per_group_is_nr0, 2, stream_overflow_down);
            } else {
                ok = ds4_gpu_encode_mul_mv_id(cb,
                                                     down_mv_pipeline,
                                                     &down_args,
                                                     down_buf,
                                                     (NSUInteger)down_inner,
                                                     midbuf,
                                                     ds4_gpu_tensor_offset(mid),
                                                     down_dst,
                                                     down_dst_off,
                                                     selectedbuf,
                                                     ds4_gpu_tensor_offset(selected),
                                                     down_smem,
                                                     down_nsg,
                                                     down_rows_per_group_is_nr0);
            }
        }
        DS4_METAL_PROFILE_MOE_STAGE("down");
        if (ok &&
            n_expert > 1 &&
            !direct_down_sum &&
            !use_q4_batch_expert_table &&
            !use_iq2_batch_selected_addr) {
            ok = ds4_gpu_encode_moe_sum_experts(cb,
                                                       down_dst,
                                                       down_dst_off,
                                                       outbuf,
                                                       ds4_gpu_tensor_offset(out),
                                                       out_dim,
                                                       n_expert,
                                                       n_tokens);
        }
        DS4_METAL_PROFILE_MOE_STAGE("sum");
        if (!ok) {
            fprintf(stderr,
                    "ds4: Metal routed batch MoE failed before submit layer=%u tokens=%u "
                    "gate=%s down=%s path=%s\n",
                    layer_index,
                    n_tokens,
                    ds4_gpu_metal_tensor_type_name(gate_type),
                    ds4_gpu_metal_tensor_type_name(down_type),
                    moe_path);
            { fprintf(stderr, "llms rmb ret 44706\n"); return 0; }
        }

        if (!ds4_gpu_finish_command_buffer(cb, owned, "routed batch MoE")) {
            if (use_cached_batch) {
                ds4_gpu_stream_expert_cache_clear_layer(layer_index);
            }
            { fprintf(stderr, "llms rmb ret 44713\n"); return 0; }
        }
        static int llms_npw = -1;

        if (llms_npw < 0) { const char *e = getenv("LLMS_DS4_NOPOSTWAIT"); llms_npw = e && *e && *e != '0'; if (llms_npw) fprintf(stderr, "llms: nopostwait (one-token routed calls keep the batch open after the MoE)\n"); }
        if (use_cached_batch && (g_llms_pipe || g_llms_ed_call || g_llms_sp_npw || (llms_npw && n_tokens == 1)) && !owned) {   /* llms SP_NPW */   /* llms BATCH_PIPE: keep the batch open; guard the union slots instead; llms ED v6 / NOPOSTWAIT: the same for one-token calls */
            if (stream_resource_count &&
                !ds4_gpu_stream_expert_cache_mark_entries_inflight(stream_resources, stream_resource_count, 0)) {
                fprintf(stderr, "llms rmb pipe mark-inflight failed layer=%u\n", layer_index); return 0;
            }
        } else if (use_cached_batch) {
            if (!owned) {
                if (ds4_gpu_end_commands() == 0) {
                    ds4_gpu_stream_expert_cache_clear_layer(layer_index);
                    { fprintf(stderr, "llms rmb ret 44719\n"); return 0; }
                }
                if (ds4_gpu_begin_commands() == 0) {
                    fprintf(stderr,
                            "ds4: Metal streaming prefill batch selected addr layer=%u "
                            "failed to reopen command batch after execution\n",
                            layer_index);
                    { fprintf(stderr, "llms rmb ret 44726\n"); return 0; }
                }
            }
        }
        if (q4_batch_table_boundary) {
            if (ds4_gpu_end_commands() == 0 || ds4_gpu_begin_commands() == 0) {
                { fprintf(stderr, "llms rmb ret 44732\n"); return 0; }
            }
        }
#undef DS4_METAL_PROFILE_MOE_STAGE
    }

    return 1;
}

int ds4_gpu_hc_split_sinkhorn_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *mix,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc == 0 || n_hc > 16) return 0;
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t mix_tensor_bytes = ds4_gpu_tensor_bytes(mix);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (!mixbuf || !outbuf ||
            mix_tensor_bytes < mix_bytes ||
            out_tensor_bytes < mix_bytes) {
            fprintf(stderr, "ds4: Metal HC split received undersized activation buffers\n");
            return 0;
        }
        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal HC split parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        uint64_t n_rows64 = mix_tensor_bytes / mix_bytes;
        const uint64_t out_rows64 = out_tensor_bytes / mix_bytes;
        if (out_rows64 < n_rows64) n_rows64 = out_rows64;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC split row count is outside supported range\n");
            return 0;
        }

        ds4_gpu_hc_split_args args = {
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb01 = mix_bytes,
            .nb1 = mix_bytes,
            .eps = eps,
        };
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_rows64));
        const NSUInteger n_tg = ((NSUInteger)n_rows64 + nth - 1u) / nth;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_sinkhorn_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sinkhorn")) return 0;
    }

    return 1;
}

/* llms HC_VEC (apply_ds4_hc_vec.py): float4 HC weighted sum / expand; 1 on, -1 canary */
static uint64_t g_llms_hcv_calls[2];
static void llms_hcv_report(void) { fprintf(stderr, "llms hc vec: %llu weighted sums, %llu expands\n", (unsigned long long)g_llms_hcv_calls[0], (unsigned long long)g_llms_hcv_calls[1]); }
static int llms_hc_vec(void) {
    static int on = -2;
    if (on < -1) { const char *e = getenv("LLMS_DS4_HC_VEC"), *src = getenv("DS4_METAL_DSV4_HC_SOURCE"); on = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                   if (on && !(src && llms_srckey(src, "llms12") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_HC_VEC ignored: DS4_METAL_DSV4_HC_SOURCE does not name an *llms12* source\n"), LLMS_G_NAME); on = 0; }
                   if (on) { fprintf(stderr, on < 0 ? "llms: hc vec -- CANARY: the weighted sum leaves the fourth stream out\n" : "llms: hc vec (float4 HC weighted sum and expand)\n"); atexit(llms_hcv_report); } }
    return on;
}
/* llms HC_BF16 (apply_ds4_hc_bf16.py): HC_VEC outputs rounded to BF16 in the store; the BF16 pass on exactly that range, with no
 * compute encoder requested in between, is skipped. 1 on, -1 canary (plain kernels marked: the rounding is lost) */
static int g_llms_hcb = -2; static uint64_t g_llms_hcb_ops = UINT64_MAX, g_llms_hcb_marks, g_llms_hcb_skips;
static id<MTLBuffer> g_llms_hcb_buf; static NSUInteger g_llms_hcb_off, g_llms_hcb_bytes;
static void llms_hcb_report(void) { fprintf(stderr, "llms hc bf16: %llu outputs rounded in the store, %llu BF16 passes skipped\n", (unsigned long long)g_llms_hcb_marks, (unsigned long long)g_llms_hcb_skips); }
static int llms_hc_bf16(void) {
    if (g_llms_hcb == -2) { const char *e = getenv("LLMS_DS4_HC_BF16"), *src = getenv("DS4_METAL_DSV4_HC_SOURCE"); g_llms_hcb = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                            if (g_llms_hcb && !(src && llms_srckey(src, "llms20") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_HC_BF16 ignored: DS4_METAL_DSV4_HC_SOURCE does not name an *llms20* source\n"), LLMS_G_NAME); g_llms_hcb = 0; }
                            if (g_llms_hcb) { fprintf(stderr, g_llms_hcb < 0 ? "llms: hc bf16 -- CANARY: the BF16 pass after HC outputs skipped without rounding\n" : "llms: hc bf16 (HC outputs rounded to BF16 in the store; the following BF16 pass skipped)\n"); atexit(llms_hcb_report); } }
    return g_llms_hcb;
}
static void llms_hcb_mark(id<MTLBuffer> b, NSUInteger off, NSUInteger bytes) { g_llms_hcb_buf = b; g_llms_hcb_off = off; g_llms_hcb_bytes = bytes; g_llms_hcb_ops = g_llms_ops; g_llms_hcb_marks++; }
static int ds4_gpu_hc_weighted_sum_strided(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint64_t                weight_offset,
        uint64_t                weight_row_stride,
        uint32_t                n_embd,
        uint32_t                n_hc,
        const char             *label) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0 ||
        weight_row_stride < (uint64_t)n_hc * sizeof(float)) {
        return 0;
    }

    @autoreleasepool {
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> wbuf = ds4_gpu_tensor_buffer(weights);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes || out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal HC weighted sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / out_row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC weighted sum token count is outside supported range\n");
            return 0;
        }

        const uint64_t x_row_values = (uint64_t)n_hc * n_embd;
        if (x_row_values == 0 ||
            x_row_values > UINT64_MAX / sizeof(float) ||
            n_tokens64 > UINT64_MAX / (x_row_values * sizeof(float)) ||
            n_tokens64 > UINT64_MAX / ((uint64_t)n_hc * sizeof(float))) {
            fprintf(stderr, "ds4: Metal HC weighted sum activation size overflow\n");
            return 0;
        }

        const uint64_t x_bytes = n_tokens64 * x_row_values * sizeof(float);
        const uint64_t w_last = weight_offset +
                                (n_tokens64 - 1u) * weight_row_stride +
                                (uint64_t)n_hc * sizeof(float);
        if (!xbuf || !wbuf || !outbuf ||
            ds4_gpu_tensor_bytes(residual_hc) < x_bytes ||
            ds4_gpu_tensor_bytes(weights) < w_last) {
            fprintf(stderr, "ds4: Metal HC weighted sum received undersized activation buffers\n");
            return 0;
        }

        ds4_gpu_hc_weighted_sum_args args = {
            .n_embd = n_embd,
            .n_hc = n_hc,
            .n_tokens = (int64_t)n_tokens64,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .nb_w0 = sizeof(float),
            .nb_w1 = weight_row_stride,
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_embd * sizeof(float),
        };
        const uint64_t n_elem = (uint64_t)n_embd * n_tokens64;
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
        const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        id<MTLComputePipelineState> llms_wpl = g_hc_weighted_sum_pipeline;   /* llms HC_VEC */
        NSUInteger llms_tg = n_tg, llms_th = nth;
        if (llms_hc_vec() && !llms_alt_off("hcv") && (n_embd % 4u) == 0) {
            static id<MTLComputePipelineState> llms_wv; if (!llms_wv) llms_wv = ds4_gpu_get_pipeline("kernel_llms_hc_weighted_sum_v4");
            if (llms_wv) { const uint64_t n4 = n_elem / 4u; llms_wpl = llms_wv; llms_th = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n4));
                           llms_tg = ((NSUInteger)n4 + llms_th - 1u) / llms_th; if (llms_hc_vec() < 0) args.n_hc = -(int64_t)n_hc; g_llms_hcv_calls[0]++; }
        }
        bool llms_hcb_w = false;   /* llms HC_BF16 */
        if (llms_wpl != g_hc_weighted_sum_pipeline && llms_hc_bf16() && !llms_alt_off("hcb")) {
            static id<MTLComputePipelineState> llms_wb; if (!llms_wb && llms_hc_bf16() > 0) llms_wb = ds4_gpu_get_pipeline("kernel_llms_hc_weighted_sum_v4b");
            if (llms_hc_bf16() < 0 || llms_wb) { if (llms_hc_bf16() > 0) llms_wpl = llms_wb; llms_hcb_w = true; }
        }
        [enc setComputePipelineState:llms_wpl];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:1];
        [enc setBuffer:wbuf offset:ds4_gpu_tensor_offset(weights) + (NSUInteger)weight_offset atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(llms_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(llms_th, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (llms_hcb_w) llms_hcb_mark(outbuf, (NSUInteger)ds4_gpu_tensor_offset(out), (NSUInteger)n_elem * sizeof(float));   /* llms HC_BF16 */

        if (!ds4_gpu_finish_command_buffer(cb, owned, label)) return 0;
    }

    return 1;
}

int ds4_gpu_hc_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *weights,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             weights,
                                             0,
                                             (uint64_t)n_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum");
}


static uint64_t g_llms_hcf1_calls;
int ds4_gpu_llms_hc_pre_fused(ds4_gpu_tensor *split, ds4_gpu_tensor *xo, ds4_gpu_tensor *no, const ds4_gpu_tensor *residual,
                              const ds4_gpu_tensor *pre, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t fn_off, uint64_t scale_off,
                              uint64_t base_off, uint64_t nw_off, uint32_t n_embd, uint32_t n_hc, uint32_t iters, float rms_eps, float hc_eps, int canary) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc != 4u || (n_embd % 4u) != 0) return 0;
    @autoreleasepool {
        static id<MTLComputePipelineState> p; static id<MTLBuffer> scr;
        if (!p) { p = ds4_gpu_get_pipeline("kernel_llms_hc_pre_fused");
                  if (!p) { fprintf(stderr, "llms: kernel_llms_hc_pre_fused missing (DS4_METAL_DSV4_HC_SOURCE must name the *_hcf source)\n"); return 0; }
                  if (p.maxTotalThreadsPerThreadgroup < 1024) { fprintf(stderr, "llms: hc fuse needs 1024 threads per threadgroup, the pipeline allows %lu\n", (unsigned long)p.maxTotalThreadsPerThreadgroup); return 0; }
                  atexit_b(^{ fprintf(stderr, "llms hc fuse1: %llu fused HC pre-sublayers\n", (unsigned long long)g_llms_hcf1_calls); }); }
        if (!scr) { scr = [g_device newBufferWithLength:32u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; if (!scr) return 0; memset([scr contents], 0, 32u * sizeof(uint32_t)); }
        const uint64_t n = (uint64_t)n_hc * n_embd;
        uint64_t fi = 0, si = 0, bi = 0, wi = 0;
        id<MTLBuffer> fb = ds4_gpu_wrap_model_range(model_map, model_size, fn_off, 24u * n * 2u, &fi);
        id<MTLBuffer> sb = ds4_gpu_wrap_model_range(model_map, model_size, scale_off, 3u * sizeof(float), &si);
        id<MTLBuffer> bb = ds4_gpu_wrap_model_range(model_map, model_size, base_off, 24u * sizeof(float), &bi);
        id<MTLBuffer> wb = ds4_gpu_wrap_model_range(model_map, model_size, nw_off, (uint64_t)n_embd * sizeof(float), &wi);
        if (!fb || !sb || !bb || !wb) return 0;
        struct { int32_t n_embd, n_hc, iters; float rms_eps, hc_eps; int32_t canary; } a = { (int32_t)n_embd, (int32_t)n_hc, (int32_t)iters, rms_eps, hc_eps, canary };
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:p];
        [enc setBytes:&a length:sizeof(a) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:1];
        [enc setBuffer:fb offset:(NSUInteger)fi atIndex:2];
        [enc setBuffer:sb offset:(NSUInteger)si atIndex:3];
        [enc setBuffer:bb offset:(NSUInteger)bi atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:5];
        [enc setBuffer:wb offset:(NSUInteger)wi atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:9];
        [enc setBuffer:scr offset:0 atIndex:10];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:11];
        [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 96u) * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(25, 1, 1) threadsPerThreadgroup:MTLSizeMake((canary & 4) ? 256 : 1024, 1, 1)];   /* bit 2: 256 threads (HC_FUSE1=3) */
        ds4_gpu_end_compute_encoder(cb, enc);
        g_llms_hcf1_calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms HC fused pre") ? 1 : 0;
    }
}


static uint64_t g_llms_hcfr_calls;


int ds4_gpu_llms_hcq(ds4_gpu_tensor *hout, const ds4_gpu_tensor *block, const ds4_gpu_tensor *residual, const ds4_gpu_tensor *cur, const ds4_gpu_tensor *pre,
                     ds4_gpu_tensor *xo, ds4_gpu_tensor *no, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t nw_off,
                     uint32_t n_embd, float rms_eps, int canary, uint32_t rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (rows != 2u || n_embd != 5120u) return 0;
    @autoreleasepool {
        static id<MTLComputePipelineState> pq, pa; static id<MTLBuffer> scr, scx; static int tried; static uint64_t calls;
        if (!tried) { tried = 1; pq = ds4_gpu_get_pipeline("kernel_llms_hcq_fused2"); pa = ds4_gpu_get_pipeline("kernel_llms_hcq_apply");
                      scr = [g_device newBufferWithLength:2u * 128u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; if (scr) memset(scr.contents, 0, 2u * 128u * sizeof(uint32_t));
                      scx = [g_device newBufferWithLength:2u * sizeof(float) options:MTLResourceStorageModePrivate];
                      if (!pq || !pa) fprintf(stderr, "llms hc fuseq: kernels missing (DS4_METAL_DSV4_HC_SOURCE) -- off\n");
                      else atexit_b(^{ fprintf(stderr, "llms hc fuseq: %llu fused two-row HC transitions\n", (unsigned long long)calls); }); }
        if (!pq || !pa || !scr || !scx) return 0;
        uint64_t wi = 0; id<MTLBuffer> wb = ds4_gpu_wrap_model_range(model_map, model_size, nw_off, (uint64_t)n_embd * sizeof(float), &wi);
        if (!wb) return 0;
        struct { int32_t n_embd, n_hc, iters; float rms_eps, hc_eps; int32_t canary; } a = { (int32_t)n_embd, 4, 0, rms_eps, 0.0f, canary ? 99 : 2 };
        const uint32_t ps = 24u;
        int owned = 0; id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned); if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pq]; [enc setBytes:&a length:sizeof a atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(block) offset:ds4_gpu_tensor_offset(block) atIndex:1];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:2];
        [enc setBuffer:ds4_gpu_tensor_buffer(cur) offset:ds4_gpu_tensor_offset(cur) atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:4];
        [enc setBuffer:scr offset:0 atIndex:5];
        [enc setBuffer:ds4_gpu_tensor_buffer(hout) offset:ds4_gpu_tensor_offset(hout) atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:7];
        [enc setBuffer:scx offset:0 atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:9];
        [enc setBytes:&ps length:sizeof ps atIndex:10];
        [enc setThreadgroupMemoryLength:16 atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(8u * rows, 1, 1) threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
        if (enc.dispatchType == MTLDispatchTypeConcurrent) [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
        [enc setComputePipelineState:pa]; [enc setBytes:&a length:sizeof a atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:1];
        [enc setBuffer:scx offset:0 atIndex:2]; [enc setBuffer:wb offset:(NSUInteger)wi atIndex:3];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:4];
        [llms_bar(enc) dispatchThreads:MTLSizeMake((NSUInteger)rows * n_embd / 4u, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms hc fuseq") ? 1 : 0;
    }
}
int ds4_gpu_llms_hc_pre_fused_rows(ds4_gpu_tensor *split, ds4_gpu_tensor *xo, ds4_gpu_tensor *no, const ds4_gpu_tensor *residual, const ds4_gpu_tensor *pre,
    uint32_t pre_stride, ds4_gpu_tensor *mixo, const void *model_map, uint64_t model_size, uint64_t fn_off, uint64_t scale_off, uint64_t base_off, uint64_t nw_off,
    uint32_t n_embd, uint32_t n_hc, uint32_t iters, float rms_eps, float hc_eps, int flags, uint32_t rows) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_hc != 4u || (n_embd % 4u) != 0 || rows == 0 || rows > 16u || (flags & 7) < 2) return 0;
