                      else atexit_b(^{ fprintf(stderr, "llms hcf rows: %llu fused k-row HC pre-sublayers\n", (unsigned long long)g_llms_hcfr_calls); });
                      scr = [g_device newBufferWithLength:32u * sizeof(uint32_t) options:MTLResourceStorageModeShared]; }
        if (!p || !scr) return 0;
