        [enc setComputePipelineState:p];
        [enc setBytes:&a length:sizeof(a) atIndex:0];
        [enc setBuffer:ds4_gpu_tensor_buffer(residual) offset:ds4_gpu_tensor_offset(residual) atIndex:1];
        [enc setBuffer:fb offset:(NSUInteger)fi atIndex:2];
        [enc setBuffer:sb offset:(NSUInteger)si atIndex:3];
        [enc setBuffer:bb offset:(NSUInteger)bi atIndex:4];
        [enc setBuffer:ds4_gpu_tensor_buffer(pre) offset:ds4_gpu_tensor_offset(pre) atIndex:5];
        [enc setBuffer:wb offset:(NSUInteger)wi atIndex:6];
        [enc setBuffer:ds4_gpu_tensor_buffer(split) offset:ds4_gpu_tensor_offset(split) atIndex:7];
        [enc setBuffer:ds4_gpu_tensor_buffer(xo) offset:ds4_gpu_tensor_offset(xo) atIndex:8];
        [enc setBuffer:ds4_gpu_tensor_buffer(no) offset:ds4_gpu_tensor_offset(no) atIndex:9];
        [enc setBuffer:scr offset:0 atIndex:10];
        [enc setBuffer:ds4_gpu_tensor_buffer(mixo) offset:ds4_gpu_tensor_offset(mixo) atIndex:11];
        [enc setBytes:&pre_stride length:sizeof(pre_stride) atIndex:12];
        [enc setThreadgroupMemoryLength:((NSUInteger)n_embd + 96u) * sizeof(float) atIndex:0];
        {   static id<MTLComputePipelineState> px, pmx; const int md = (flags & DS4_GPU_LLMS_HCFR_XS) ? 1 : (flags & DS4_GPU_LLMS_HCFR_MIX) ? 2 : 0;   /* llms HC_MIXDUAL; HC_OWED: the mode in flags */
            if (md == 1 && !px) px = ds4_gpu_get_pipeline("kernel_llms_hc_pre_fused_rows_xs");
            if (md == 2 && !pmx) pmx = ds4_gpu_get_pipeline("kernel_llms_hc_pre_fused_rows_mix");
            if ((md == 1 && !px) || (md == 2 && !pmx)) { fprintf(stderr, "llms hc mixdual: the _xs / _mix kernels are missing (DS4_METAL_DSV4_HC_SOURCE)\n"); ds4_gpu_end_compute_encoder(cb, enc); return 0; }
            if (md == 1) [enc setComputePipelineState:px]; else if (md == 2) [enc setComputePipelineState:pmx];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((md == 1 ? 1u : md == 2 ? 24u : 25u) * rows, 1, 1) threadsPerThreadgroup:MTLSizeMake((flags & 4) ? 256 : 1024, 1, 1)]; }
        ds4_gpu_end_compute_encoder(cb, enc);
        g_llms_hcfr_calls++;
        return ds4_gpu_finish_command_buffer(cb, owned, "llms HC fused pre rows") ? 1 : 0;
    }
}

int ds4_gpu_hc_weighted_sum_split_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    return ds4_gpu_hc_weighted_sum_strided(out,
                                             residual_hc,
                                             split,
                                             0,
                                             mix_hc * sizeof(float),
                                             n_embd,
                                             n_hc,
                                             "HC weighted sum split");
}

/* Release decode fused HC pre-sublayer operation.  The graph driver owns the
 * optional reference fallback so this function stays a direct fused dispatch. */
int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc == 0) {
        return 0;
    }
    if (n_hc != 4) {
        fprintf(stderr, "ds4: Metal fused HC split/sum is specialized for HC=4\n");
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        if (!scalebuf || !basebuf) return 0;

        ds4_gpu_hc_split_weighted_sum_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .eps = eps,
        };

        NSUInteger nth = g_hc_split_weighted_sum_pipeline.maxTotalThreadsPerThreadgroup;
        if (nth > 256u) nth = 256u;
        if (nth > (NSUInteger)n_embd) nth = (NSUInteger)n_embd;
        if (nth == 0) nth = 1u;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:g_hc_split_weighted_sum_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setThreadgroupMemoryLength:(NSUInteger)n_hc * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum fused")) return 0;
    }

    return 1;
}

/* HC-pre plus the immediately following weighted RMSNorm, specialized for
 * DS4's HC=4 shape. Both decode and batched prefill use this implementation;
 * the kernel preserves their established single-row and batched scale formulas. */
int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
    float                   norm_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
        n_hc != 4 || (n_embd & 3u) != 0) {
        return 0;
    }

    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t scale_bytes = 3ull * sizeof(float);

    @autoreleasepool {
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (out_row_bytes == 0 || out_tensor_bytes < out_row_bytes ||
            out_tensor_bytes % out_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm output size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_rows64 = out_tensor_bytes / out_row_bytes;
        if (n_rows64 == 0 || n_rows64 > UINT32_MAX ||
            n_rows64 > UINT64_MAX / mix_bytes ||
            n_rows64 > UINT64_MAX / residual_row_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm row count is outside supported range\n");
            return 0;
        }

        const uint64_t mix_total_bytes = n_rows64 * mix_bytes;
        const uint64_t residual_total_bytes = n_rows64 * residual_row_bytes;
        const uint64_t out_total_bytes = n_rows64 * out_row_bytes;
        if (!mixbuf || !splitbuf || !xbuf || !outbuf || !normbuf ||
            ds4_gpu_tensor_bytes(mix) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_total_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_total_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < out_total_bytes) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm received undersized activation buffers\n");
            return 0;
        }

        if (scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size || out_row_bytes > model_size - norm_weight_offset) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm parameter range is outside the mapped model\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        uint64_t norm_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size, base_offset, mix_bytes, &base_inner);
        id<MTLBuffer> normwbuf = ds4_gpu_wrap_model_range(model_map, model_size, norm_weight_offset, out_row_bytes, &norm_inner);
        if (!scalebuf || !basebuf || !normwbuf) return 0;

        id<MTLComputePipelineState> pipeline =
            ds4_gpu_hot_pipeline(g_hc_split_weighted_sum_norm_pipeline,
                                   "kernel_dsv4_hc_split_weighted_sum_norm4");
        if (!pipeline) return 0;

        ds4_gpu_hc_split_weighted_sum_norm_args args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = (int64_t)n_rows64,
            .mix_hc = (int64_t)mix_hc,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_row_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_row_bytes,
            .nb_norm1 = out_row_bytes,
            .eps = eps,
            .norm_eps = norm_eps,
        };

        NSUInteger nth = ds4_gpu_rms_norm_threads(n_embd);
        if (nth > pipeline.maxTotalThreadsPerThreadgroup) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu threads but pipeline supports %lu\n",
                    (unsigned long)nth,
                    (unsigned long)pipeline.maxTotalThreadsPerThreadgroup);
            return 0;
        }

        const NSUInteger shared_bytes = ((NSUInteger)n_embd + 4u + 32u) * sizeof(float);
        const NSUInteger max_shared = [g_device maxThreadgroupMemoryLength];
        if (max_shared != 0 && shared_bytes > max_shared) {
            fprintf(stderr, "ds4: Metal fused HC split/sum/norm requires %lu bytes of threadgroup memory but device supports %lu\n",
                    (unsigned long)shared_bytes,
                    (unsigned long)max_shared);
            return 0;
        }

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:6];
        [enc setBuffer:normwbuf offset:(NSUInteger)norm_inner atIndex:7];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:8];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n_rows64, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC split/sum/norm fused")) return 0;
    }

    return 1;
}

typedef struct {
    int32_t n;
    int32_t out_dim;
    float   eps;
} ds4_gpu_hc_norm_mix_args;

int ds4_gpu_hc_rms_norm_mix_f16_available(void) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    static int cached = -1;
    if (cached < 0) {
        cached = ds4_gpu_get_pipeline("kernel_dsv4_hc_rms_norm_mix_f16") != nil;
    }
    return cached;
}

/* Fused decode HC-pre: unweighted RMSNorm over the flattened HC row plus the
 * F16 HC-mix matvec in one dispatch.  The kernel reproduces the standalone
 * kernels' reduction trees bit-exactly (see metal/dsv4_hc.metal), so this is
 * purely a dispatch-count optimization. */
int ds4_gpu_hc_rms_norm_mix_f16_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *x,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              weight_offset,
        uint32_t              n,
        uint32_t              out_dim,
        float                 eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !x || !model_map || n != 16384u || out_dim != 24u) return 0;

    @autoreleasepool {
        const uint64_t row_bytes = (uint64_t)n * sizeof(uint16_t);
        const uint64_t weight_bytes = row_bytes * out_dim;
        if (weight_offset > model_size || weight_bytes > model_size - weight_offset) {
            fprintf(stderr, "ds4: Metal fused HC norm/mix weight range is outside the mapped model\n");
            return 0;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(x);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        if (!xbuf || !outbuf ||
            ds4_gpu_tensor_bytes(x) < (uint64_t)n * sizeof(float) ||
            ds4_gpu_tensor_bytes(out) < (uint64_t)out_dim * sizeof(float)) {
            fprintf(stderr, "ds4: Metal fused HC norm/mix received undersized activation buffers\n");
            return 0;
        }

        uint64_t weight_inner = 0;
        id<MTLBuffer> wbuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                      weight_offset, weight_bytes,
                                                      &weight_inner);
        if (!wbuf) return 0;

        const bool use_cluster2 =
            ds4_gpu_device_is_m5_apple_silicon() &&
            getenv("DS4_METAL_DISABLE_M5_HC_NORM_MIX_CLUSTER2") == NULL;
        id<MTLComputePipelineState> pipeline = ds4_gpu_get_pipeline(
            use_cluster2 ? "kernel_dsv4_hc_rms_norm_mix_f16_cluster2" :
                           "kernel_dsv4_hc_rms_norm_mix_f16");
        if (!pipeline ||
            (use_cluster2 && pipeline.maxTotalThreadsPerThreadgroup < 512u)) {
            return 0;
        }
        const NSUInteger shared_floats =
            use_cluster2 ? 32u + 32u * 2u * 2u : 32u + 32u * 2u;

        ds4_gpu_hc_norm_mix_args args = {
            .n = (int32_t)n,
            .out_dim = (int32_t)out_dim,
            .eps = eps,
        };

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(x) atIndex:1];
        [enc setBuffer:wbuf offset:(NSUInteger)weight_inner atIndex:2];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:3];
        [enc setThreadgroupMemoryLength:shared_floats * sizeof(float) atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:
             MTLSizeMake(use_cluster2 ? (out_dim + 3u) / 4u :
                                        (out_dim + 1u) / 2u,
                         1, 1)
             threadsPerThreadgroup:
             MTLSizeMake(32, use_cluster2 ? 16 : 8, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "fused HC norm/mix")) return 0;
    }

    return 1;
}


int ds4_gpu_hc_rms_norm_mix_split_norm_f16_tensor(
        ds4_gpu_tensor       *mix,
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *residual_hc,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              mix_weight_offset,
        uint64_t              scale_offset,
        uint64_t              base_offset,
        uint64_t              norm_weight_offset,
        uint32_t              n,
        uint32_t              mix_dim,
        uint32_t              n_embd,
        uint32_t              n_hc,
        uint32_t              sinkhorn_iters,
        float                 eps,
        float                 hc_eps,
        float                 norm_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!mix || !out || !norm_out || !split || !residual_hc || !model_map ||
        n != 16384u || mix_dim != 24u || n_embd != 4096u || n_hc != 4u) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t mix_weight_bytes =
            (uint64_t)n * (uint64_t)mix_dim * sizeof(uint16_t);
        const uint64_t mix_bytes = (uint64_t)mix_dim * sizeof(float);
        const uint64_t residual_bytes = (uint64_t)n * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t scale_bytes = 3u * sizeof(float);
        if (mix_weight_offset > model_size ||
            mix_weight_bytes > model_size - mix_weight_offset ||
            scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            out_bytes > model_size - norm_weight_offset) {
            fprintf(stderr,
                    "ds4: Metal compound HC producer parameter range is outside the mapped model\n");
            return 0;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        if (!xbuf || !mixbuf || !splitbuf || !outbuf || !normbuf ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_bytes ||
            ds4_gpu_tensor_bytes(mix) < mix_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < out_bytes) {
            fprintf(stderr,
                    "ds4: Metal compound HC producer received undersized activation buffers\n");
            return 0;
        }

        uint64_t mix_weight_inner = 0;
        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        uint64_t norm_inner = 0;
        id<MTLBuffer> mix_weight = ds4_gpu_wrap_model_range(
            model_map, model_size, mix_weight_offset, mix_weight_bytes,
            &mix_weight_inner);
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, base_offset, mix_bytes, &base_inner);
        id<MTLBuffer> norm_weight = ds4_gpu_wrap_model_range(
            model_map, model_size, norm_weight_offset, out_bytes, &norm_inner);
        if (!mix_weight || !scalebuf || !basebuf || !norm_weight) return 0;

        if (!g_dsv4_hc_producer_pre_norm_pipeline) {
            g_dsv4_hc_producer_pre_norm_pipeline = ds4_gpu_get_pipeline(
                "kernel_dsv4_hc_rms_norm_mix_f16_cluster2_pre_norm");
        }
        id<MTLComputePipelineState> producer =
            g_dsv4_hc_producer_pre_norm_pipeline;
        if (!producer || producer.maxTotalThreadsPerThreadgroup < 512u) {
            return 0;
        }
        if (!g_dsv4_completion_cache) return 0;
        const NSUInteger mix_offset = ds4_gpu_tensor_offset(mix);
        id<MTLBuffer> completion = nil;
        if (g_dsv4_hc_producer_last_mix_buffer == mixbuf &&
            g_dsv4_hc_producer_last_mix_offset == mix_offset) {
            completion = g_dsv4_hc_producer_last_completion;
        } else {
            NSString *completion_key = [NSString stringWithFormat:@"%p:%llu",
                (void *)mixbuf, (unsigned long long)mix_offset];
            completion = [g_dsv4_completion_cache
                objectForKey:completion_key];
            if (!completion) {
                completion = [g_device newBufferWithLength:sizeof(uint32_t)
                    options:MTLResourceStorageModeShared];
                if (!completion) return 0;
                *((uint32_t *)[completion contents]) = 0u;
                [g_dsv4_completion_cache
                    setObject:completion forKey:completion_key];
            }
            g_dsv4_hc_producer_last_mix_buffer = mixbuf;
            g_dsv4_hc_producer_last_mix_offset = mix_offset;
            g_dsv4_hc_producer_last_completion = completion;
        }
        [g_transient_buffers addObject:completion];

        ds4_gpu_hc_norm_mix_args mix_args = {
            .n = (int32_t)n,
            .out_dim = (int32_t)mix_dim,
            .eps = eps,
        };
        ds4_gpu_hc_split_weighted_sum_norm_args split_args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = 1,
            .mix_hc = (int64_t)mix_dim,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_bytes,
            .nb_norm1 = out_bytes,
            .eps = hc_eps,
            .norm_eps = norm_eps,
        };

        const NSUInteger shared_floats = 32u + 4u * 32u + 4u + 32u;
        const NSUInteger shared_bytes = shared_floats * sizeof(float);
        const NSUInteger max_shared = [g_device maxThreadgroupMemoryLength];
        if (max_shared != 0 && shared_bytes > max_shared) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);

        [enc setComputePipelineState:producer];
        [enc setBytes:&mix_args length:sizeof(mix_args) atIndex:0];
        [enc setBytes:&split_args length:sizeof(split_args) atIndex:1];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:2];
        [enc setBuffer:mix_weight offset:(NSUInteger)mix_weight_inner atIndex:3];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:4];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:5];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:6];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:7];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:8];
        [enc setBuffer:norm_weight offset:(NSUInteger)norm_inner atIndex:9];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:10];
        [enc setBuffer:completion offset:0 atIndex:11];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(6, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 16, 1)];

        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "compound HC producer/pre-norm")) {
            return -1;
        }
    }
    return 1;
}

int ds4_gpu_hc_expand_add_rms_norm_mix_split_norm_f16_tensor(
        ds4_gpu_tensor       *mix,
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *block_out,
        const ds4_gpu_tensor *block_add,
        const ds4_gpu_tensor *residual_prev,
        const ds4_gpu_tensor *post,
        const ds4_gpu_tensor *comb,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              mix_weight_offset,
        uint64_t              scale_offset,
        uint64_t              base_offset,
        uint64_t              norm_weight_offset,
        uint32_t              n,
        uint32_t              mix_dim,
        uint32_t              n_embd,
        uint32_t              n_hc,
        uint32_t              sinkhorn_iters,
        float                 eps,
        float                 hc_eps,
        float                 norm_eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!mix || !out || !norm_out || !split || !residual_hc || !model_map ||
        !block_out || !block_add || !residual_prev || !post || !comb ||
        n != 16384u || mix_dim != 24u || n_embd != 4096u || n_hc != 4u) {
        return 0;
    }

    @autoreleasepool {
        const uint64_t mix_weight_bytes =
            (uint64_t)n * (uint64_t)mix_dim * sizeof(uint16_t);
        const uint64_t mix_bytes = (uint64_t)mix_dim * sizeof(float);
        const uint64_t residual_bytes = (uint64_t)n * sizeof(float);
        const uint64_t out_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t scale_bytes = 3u * sizeof(float);
        if (mix_weight_offset > model_size ||
            mix_weight_bytes > model_size - mix_weight_offset ||
            scale_offset > model_size || scale_bytes > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            out_bytes > model_size - norm_weight_offset) {
            fprintf(stderr,
                    "ds4: Metal compound HC producer parameter range is outside the mapped model\n");
            return 0;
        }

        id<MTLBuffer> xbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> mixbuf = ds4_gpu_tensor_buffer(mix);
        id<MTLBuffer> splitbuf = ds4_gpu_tensor_buffer(split);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        id<MTLBuffer> normbuf = ds4_gpu_tensor_buffer(norm_out);
        if (!xbuf || !mixbuf || !splitbuf || !outbuf || !normbuf ||
            ds4_gpu_tensor_bytes(residual_hc) < residual_bytes ||
            ds4_gpu_tensor_bytes(mix) < mix_bytes ||
            ds4_gpu_tensor_bytes(split) < mix_bytes ||
            ds4_gpu_tensor_bytes(out) < out_bytes ||
            ds4_gpu_tensor_bytes(norm_out) < out_bytes) {
            fprintf(stderr,
                    "ds4: Metal compound HC producer received undersized activation buffers\n");
            return 0;
        }

        uint64_t mix_weight_inner = 0;
        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        uint64_t norm_inner = 0;
        id<MTLBuffer> mix_weight = ds4_gpu_wrap_model_range(
            model_map, model_size, mix_weight_offset, mix_weight_bytes,
            &mix_weight_inner);
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, scale_offset, scale_bytes, &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(
            model_map, model_size, base_offset, mix_bytes, &base_inner);
        id<MTLBuffer> norm_weight = ds4_gpu_wrap_model_range(
            model_map, model_size, norm_weight_offset, out_bytes, &norm_inner);
        if (!mix_weight || !scalebuf || !basebuf || !norm_weight) return 0;

        if (!g_dsv4_hc_expand_producer_pre_norm_pipeline) {
            g_dsv4_hc_expand_producer_pre_norm_pipeline = ds4_gpu_get_pipeline(
                "kernel_dsv4_hc_expand4_rms_norm_mix_f16_cluster2_pre_norm");
        }
        id<MTLComputePipelineState> producer =
            g_dsv4_hc_expand_producer_pre_norm_pipeline;
        id<MTLBuffer> blockbuf = ds4_gpu_tensor_buffer(block_out);
        id<MTLBuffer> addbuf = ds4_gpu_tensor_buffer(block_add);
        id<MTLBuffer> prevbuf = ds4_gpu_tensor_buffer(residual_prev);
        id<MTLBuffer> postbuf = ds4_gpu_tensor_buffer(post);
        id<MTLBuffer> combbuf = ds4_gpu_tensor_buffer(comb);
        if (!blockbuf || !addbuf || !prevbuf || !postbuf || !combbuf ||
            ds4_gpu_tensor_bytes(block_out) < out_bytes ||
            ds4_gpu_tensor_bytes(block_add) < out_bytes ||
            ds4_gpu_tensor_bytes(residual_prev) < residual_bytes ||
            ds4_gpu_tensor_bytes(post) < (uint64_t)n_hc * sizeof(float) ||
            ds4_gpu_tensor_bytes(comb) < (uint64_t)n_hc * n_hc * sizeof(float)) {
            fprintf(stderr,
                    "ds4: Metal fused HC expand/producer received undersized expand buffers\n");
            return 0;
        }
        if (!producer || producer.maxTotalThreadsPerThreadgroup < 512u) {
            return 0;
        }
        if (!g_dsv4_completion_cache) return 0;
        const NSUInteger mix_offset = ds4_gpu_tensor_offset(mix);
        id<MTLBuffer> completion = nil;
        if (g_dsv4_hc_producer_last_mix_buffer == mixbuf &&
            g_dsv4_hc_producer_last_mix_offset == mix_offset) {
            completion = g_dsv4_hc_producer_last_completion;
        } else {
            NSString *completion_key = [NSString stringWithFormat:@"%p:%llu",
                (void *)mixbuf, (unsigned long long)mix_offset];
            completion = [g_dsv4_completion_cache
                objectForKey:completion_key];
            if (!completion) {
                completion = [g_device newBufferWithLength:sizeof(uint32_t)
                    options:MTLResourceStorageModeShared];
                if (!completion) return 0;
                *((uint32_t *)[completion contents]) = 0u;
                [g_dsv4_completion_cache
                    setObject:completion forKey:completion_key];
            }
            g_dsv4_hc_producer_last_mix_buffer = mixbuf;
            g_dsv4_hc_producer_last_mix_offset = mix_offset;
            g_dsv4_hc_producer_last_completion = completion;
        }
        [g_transient_buffers addObject:completion];
        /* Monotonic cross-threadgroup barrier counter for this mix tensor,
         * plus the host-side dispatch count that sets the target. */
        NSString *barrier_key = [NSString stringWithFormat:@"%p:%llu",
            (void *)mixbuf, (unsigned long long)mix_offset];
        if (!g_dsv4_hc_barrier_cache) {
            g_dsv4_hc_barrier_cache = [NSMutableDictionary dictionary];
            g_dsv4_hc_barrier_gen = [NSMutableDictionary dictionary];
        }
        id<MTLBuffer> barrier = [g_dsv4_hc_barrier_cache objectForKey:barrier_key];
        if (!barrier) {
            barrier = [g_device newBufferWithLength:sizeof(uint32_t)
                                            options:MTLResourceStorageModeShared];
            if (!barrier) return 0;
            *((uint32_t *)[barrier contents]) = 0u;
            [g_dsv4_hc_barrier_cache setObject:barrier forKey:barrier_key];
        }
        const uint32_t gen =
            (uint32_t)[[g_dsv4_hc_barrier_gen objectForKey:barrier_key] unsignedIntValue] + 1u;
        [g_dsv4_hc_barrier_gen setObject:@(gen) forKey:barrier_key];
        const uint32_t barrier_target = 6u * gen;
        [g_transient_buffers addObject:barrier];
        ds4_gpu_hc_expand_args ex = {
            .n_embd = n_embd,
            .n_hc = n_hc,
            .n_tokens = 1,
            .nb_block0 = sizeof(float),
            .nb_block1 = (uint64_t)n_embd * sizeof(float),
            .nb_add0 = sizeof(float),
            .nb_add1 = (uint64_t)n_embd * sizeof(float),
            .nb_res0 = sizeof(float),
            .nb_res1 = (uint64_t)n_embd * sizeof(float),
            .nb_res2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .nb_post0 = sizeof(float),
            .nb_post1 = (uint64_t)n_hc * sizeof(float),
            .nb_comb0 = sizeof(float),
            .nb_comb1 = (uint64_t)n_hc * sizeof(float),
            .nb_comb2 = (uint64_t)n_hc * n_hc * sizeof(float),
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_embd * sizeof(float),
            .nb2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .has_add = 1,
        };
        ds4_gpu_hc_norm_mix_args mix_args = {
            .n = (int32_t)n,
            .out_dim = (int32_t)mix_dim,
            .eps = eps,
        };
        ds4_gpu_hc_split_weighted_sum_norm_args split_args = {
            .n_embd = (int64_t)n_embd,
            .n_hc = (int32_t)n_hc,
            .sinkhorn_iters = (int32_t)sinkhorn_iters,
            .n_rows = 1,
            .mix_hc = (int64_t)mix_dim,
            .nb_mix1 = mix_bytes,
            .nb_split1 = mix_bytes,
            .nb_x0 = sizeof(float),
            .nb_x1 = (uint64_t)n_embd * sizeof(float),
            .nb_x2 = residual_bytes,
            .nb0 = sizeof(float),
            .nb1 = out_bytes,
            .nb_norm1 = out_bytes,
            .eps = hc_eps,
            .norm_eps = norm_eps,
        };

        const NSUInteger shared_floats = 32u + 4u * 32u + 4u + 32u;
        const NSUInteger shared_bytes = shared_floats * sizeof(float);
        const NSUInteger max_shared = [g_device maxThreadgroupMemoryLength];
        if (max_shared != 0 && shared_bytes > max_shared) return 0;

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);

        [enc setComputePipelineState:producer];
        [enc setBytes:&mix_args length:sizeof(mix_args) atIndex:0];
        [enc setBytes:&split_args length:sizeof(split_args) atIndex:1];
        [enc setBytes:&ex length:sizeof(ex) atIndex:2];
        [enc setBytes:&barrier_target length:sizeof(barrier_target) atIndex:3];
        [enc setBuffer:xbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:4];
        [enc setBuffer:mix_weight offset:(NSUInteger)mix_weight_inner atIndex:5];
        [enc setBuffer:mixbuf offset:ds4_gpu_tensor_offset(mix) atIndex:6];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:7];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:8];
        [enc setBuffer:splitbuf offset:ds4_gpu_tensor_offset(split) atIndex:9];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:10];
        [enc setBuffer:norm_weight offset:(NSUInteger)norm_inner atIndex:11];
        [enc setBuffer:normbuf offset:ds4_gpu_tensor_offset(norm_out) atIndex:12];
        [enc setBuffer:completion offset:0 atIndex:13];
        [enc setBuffer:barrier offset:0 atIndex:14];
        [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:15];
        [enc setBuffer:addbuf offset:ds4_gpu_tensor_offset(block_add) atIndex:16];
        [enc setBuffer:prevbuf offset:ds4_gpu_tensor_offset(residual_prev) atIndex:17];
        [enc setBuffer:postbuf offset:ds4_gpu_tensor_offset(post) atIndex:18];
        [enc setBuffer:combbuf offset:ds4_gpu_tensor_offset(comb) atIndex:19];
        [enc setThreadgroupMemoryLength:shared_bytes atIndex:0];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(6, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(32, 16, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(
                cb, owned, "fused HC expand/producer/pre-norm")) {
            return -1;
        }
    }
    return 1;
}

int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !pre || !model_map || n_hc == 0) return 0;

    @autoreleasepool {
        if ((n_hc % 4u) != 0) {
            fprintf(stderr, "ds4: Metal output HC weights requires a multiple-of-4 HC width\n");
            return 0;
        }

        id<MTLBuffer> prebuf = ds4_gpu_tensor_buffer(pre);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out);
        const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out);
        if (row_bytes == 0 || out_tensor_bytes < row_bytes || out_tensor_bytes % row_bytes != 0) {
            fprintf(stderr, "ds4: Metal output HC weights size is not a whole token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX ||
            n_tokens64 > UINT64_MAX / row_bytes) {
            fprintf(stderr, "ds4: Metal output HC weights token count is outside supported range\n");
            return 0;
        }

        const uint64_t bytes = n_tokens64 * row_bytes;
        if (!prebuf || !outbuf ||
            ds4_gpu_tensor_bytes(pre) < bytes ||
            ds4_gpu_tensor_bytes(out) < bytes) {
            fprintf(stderr, "ds4: Metal output HC weights received undersized buffers\n");
            return 0;
        }

        uint64_t scale_inner = 0;
        uint64_t base_inner = 0;
        id<MTLBuffer> scalebuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                            scale_offset, sizeof(float),
                                                            &scale_inner);
        id<MTLBuffer> basebuf = ds4_gpu_wrap_model_range(model_map, model_size,
                                                           base_offset, row_bytes,
                                                           &base_inner);
        if (!scalebuf || !basebuf) return 0;

        const bool require_weights4 =
            getenv("DS4_METAL_REQUIRE_OUTPUT_HC_WEIGHTS4") != NULL;
        const bool weights4_shape = n_hc == 4u && n_tokens64 == 1u;
        const bool use_weights4 =
            weights4_shape && !g_quality_mode &&
            g_output_hc_weights4_pipeline != nil &&
            (ds4_gpu_device_name_contains("M3") ||
             (g_test_flags & DS4_GPU_TEST_OUTPUT_HC_WEIGHTS4) != 0u) &&
            g_output_hc_weights4_pipeline.maxTotalThreadsPerThreadgroup >= 2u;
        if (require_weights4 && weights4_shape && !use_weights4) {
            fprintf(stderr,
                    "ds4: required Metal output HC weights4 kernel was not selected\n");
            return 0;
        }

        if (use_weights4) {
            ds4_gpu_output_hc_weights4_args args = {
                .post_scale = 1.0f,
                .eps = eps,
            };
            int owned = 0;
            id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
            if (!cb) return 0;

            id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
            [enc setComputePipelineState:g_output_hc_weights4_pipeline];
            [enc setBytes:&args length:sizeof(args) atIndex:0];
            [enc setBuffer:prebuf offset:ds4_gpu_tensor_offset(pre) atIndex:1];
            [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
            [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:3];
            [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out) atIndex:4];
            [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(1, 1, 1)
                 threadsPerThreadgroup:MTLSizeMake(2, 1, 1)];
            ds4_gpu_end_compute_encoder(cb, enc);

            if (!ds4_gpu_finish_command_buffer(
                    cb, owned, "output HC weights4")) {
                return 0;
            }
            return 1;
        }

        const uint32_t n_tokens = (uint32_t)n_tokens64;
        ds4_gpu_bin_args mul_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, 1);
        ds4_gpu_bin_args add_args = ds4_gpu_make_bin_rows_args(n_hc, n_tokens, n_hc);
        ds4_gpu_unary_args sigmoid_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 0.0f, 0.0f);
        ds4_gpu_unary_args scale_args = ds4_gpu_make_unary_rows_args(n_hc, n_tokens, 1, 1.0f, eps);

        NSUInteger mul_nth_max = g_bin_mul_scalar_pipeline.maxTotalThreadsPerThreadgroup;
        if (mul_nth_max > 256u) mul_nth_max = 256u;
        NSUInteger mul_nth = 1u;
        while (2u * mul_nth < (NSUInteger)mul_args.ne0 && mul_nth < mul_nth_max) {
            mul_nth *= 2u;
        }

        NSUInteger add_nth_max = g_add_pipeline.maxTotalThreadsPerThreadgroup;
        if (add_nth_max > 256u) add_nth_max = 256u;
        NSUInteger add_nth = 1u;
        while (2u * add_nth < (NSUInteger)add_args.ne0 && add_nth < add_nth_max) {
            add_nth *= 2u;
        }

        NSUInteger unary_nth_max = g_unary_sigmoid_pipeline.maxTotalThreadsPerThreadgroup;
        if (unary_nth_max > 256u) unary_nth_max = 256u;
        NSUInteger unary_nth = (NSUInteger)sigmoid_args.ne00;
        if (unary_nth > unary_nth_max) unary_nth = unary_nth_max;
        if (unary_nth == 0) unary_nth = 1u;
        const NSUInteger unary_nk0 = ((NSUInteger)sigmoid_args.ne00 + unary_nth - 1u) / unary_nth;
        const NSUInteger out_offset = ds4_gpu_tensor_offset(out);

        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);

        [enc setComputePipelineState:g_bin_mul_scalar_pipeline];
        [enc setBytes:&mul_args length:sizeof(mul_args) atIndex:0];
        [enc setBuffer:prebuf offset:ds4_gpu_tensor_offset(pre) atIndex:1];
        [enc setBuffer:scalebuf offset:(NSUInteger)scale_inner atIndex:2];
        [enc setBuffer:outbuf offset:out_offset atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)mul_args.ne01,
                                              (NSUInteger)mul_args.ne02,
                                              (NSUInteger)mul_args.ne03)
             threadsPerThreadgroup:MTLSizeMake(mul_nth, 1, 1)];

        [enc setComputePipelineState:g_add_pipeline];
        [enc setBytes:&add_args length:sizeof(add_args) atIndex:0];
        [enc setBuffer:outbuf offset:out_offset atIndex:1];
        [enc setBuffer:basebuf offset:(NSUInteger)base_inner atIndex:2];
        [enc setBuffer:outbuf offset:out_offset atIndex:3];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)add_args.ne01,
                                              (NSUInteger)add_args.ne02,
                                              (NSUInteger)add_args.ne03)
             threadsPerThreadgroup:MTLSizeMake(add_nth, 1, 1)];

        [enc setComputePipelineState:g_unary_sigmoid_pipeline];
        [enc setBytes:&sigmoid_args length:sizeof(sigmoid_args) atIndex:0];
        [enc setBuffer:outbuf offset:out_offset atIndex:1];
        [enc setBuffer:outbuf offset:out_offset atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(unary_nk0 * (NSUInteger)sigmoid_args.ne01,
                                              (NSUInteger)sigmoid_args.ne02,
                                              (NSUInteger)sigmoid_args.ne03)
             threadsPerThreadgroup:MTLSizeMake(unary_nth, 1, 1)];

        [enc setComputePipelineState:g_unary_scale_pipeline];
        [enc setBytes:&scale_args length:sizeof(scale_args) atIndex:0];
        [enc setBuffer:outbuf offset:out_offset atIndex:1];
        [enc setBuffer:outbuf offset:out_offset atIndex:2];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(unary_nk0 * (NSUInteger)scale_args.ne01,
                                              (NSUInteger)scale_args.ne02,
                                              (NSUInteger)scale_args.ne03)
             threadsPerThreadgroup:MTLSizeMake(unary_nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);

        if (!ds4_gpu_finish_command_buffer(cb, owned, "output HC weights")) return 0;
    }

    return 1;
}

int ds4_gpu_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        const ds4_gpu_tensor *block_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *post,
        const ds4_gpu_tensor *comb,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (n_embd == 0 || n_hc == 0) return 0;

    @autoreleasepool {
        id<MTLBuffer> blockbuf = ds4_gpu_tensor_buffer(block_out);
        id<MTLBuffer> resbuf = ds4_gpu_tensor_buffer(residual_hc);
        id<MTLBuffer> postbuf = ds4_gpu_tensor_buffer(post);
        id<MTLBuffer> combbuf = ds4_gpu_tensor_buffer(comb);
        id<MTLBuffer> outbuf = ds4_gpu_tensor_buffer(out_hc);
        const uint64_t hc_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        const uint64_t out_tensor_bytes = ds4_gpu_tensor_bytes(out_hc);
        if (hc_row_bytes == 0 || out_tensor_bytes < hc_row_bytes || out_tensor_bytes % hc_row_bytes != 0) {
            fprintf(stderr, "ds4: Metal HC expand output size is not a whole HC token row\n");
            return 0;
        }

        const uint64_t n_tokens64 = out_tensor_bytes / hc_row_bytes;
        if (n_tokens64 == 0 || n_tokens64 > UINT32_MAX) {
            fprintf(stderr, "ds4: Metal HC expand token count is outside supported range\n");
            return 0;
        }

        const uint64_t block_values = (uint64_t)n_embd;
        const uint64_t hc_values = (uint64_t)n_hc * n_embd;
        const uint64_t comb_values = (uint64_t)n_hc * n_hc;
        if (hc_values == 0 ||
            hc_values > UINT64_MAX / sizeof(float) ||
            comb_values > UINT64_MAX / sizeof(float) ||
            n_tokens64 > UINT64_MAX / (block_values * sizeof(float)) ||
            n_tokens64 > UINT64_MAX / (hc_values * sizeof(float)) ||
            n_tokens64 > UINT64_MAX / (comb_values * sizeof(float))) {
            fprintf(stderr, "ds4: Metal HC expand activation size overflow\n");
            return 0;
        }

        const uint64_t block_bytes = n_tokens64 * block_values * sizeof(float);
        const uint64_t hc_bytes = n_tokens64 * hc_values * sizeof(float);
        const uint64_t post_bytes = n_tokens64 * (uint64_t)n_hc * sizeof(float);
        const uint64_t comb_bytes = n_tokens64 * comb_values * sizeof(float);
        if (!blockbuf || !resbuf || !postbuf || !combbuf || !outbuf ||
            ds4_gpu_tensor_bytes(block_out) < block_bytes ||
            ds4_gpu_tensor_bytes(residual_hc) < hc_bytes ||
            ds4_gpu_tensor_bytes(post) < post_bytes ||
            ds4_gpu_tensor_bytes(comb) < comb_bytes) {
            fprintf(stderr, "ds4: Metal HC expand received undersized activation buffers\n");
            return 0;
        }

        ds4_gpu_hc_expand_args args = {
            .n_embd = n_embd,
            .n_hc = n_hc,
            .n_tokens = (int64_t)n_tokens64,
            .nb_block0 = sizeof(float),
            .nb_block1 = (uint64_t)n_embd * sizeof(float),
            .nb_add0 = sizeof(float),
            .nb_add1 = (uint64_t)n_embd * sizeof(float),
            .nb_res0 = sizeof(float),
            .nb_res1 = (uint64_t)n_embd * sizeof(float),
            .nb_res2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .nb_post0 = sizeof(float),
            .nb_post1 = (uint64_t)n_hc * sizeof(float),
            .nb_comb0 = sizeof(float),
            .nb_comb1 = (uint64_t)n_hc * sizeof(float),
            .nb_comb2 = (uint64_t)n_hc * n_hc * sizeof(float),
            .nb0 = sizeof(float),
            .nb1 = (uint64_t)n_embd * sizeof(float),
            .nb2 = (uint64_t)n_hc * n_embd * sizeof(float),
            .has_add = 0,
        };
        id<MTLComputePipelineState> expand_pipeline = g_hc_expand_pipeline;
        uint64_t n_elem = (uint64_t)n_embd * n_hc * n_tokens64;
        if (n_hc == 4) {
            expand_pipeline = ds4_gpu_hot_pipeline(g_dsv4_hc_expand4_pipeline,
                                                      "kernel_dsv4_hc_expand4");
            n_elem = (uint64_t)n_embd * n_tokens64;
        }
        bool llms_hcb_e = false;   /* llms HC_BF16 */
        if (n_hc == 4 && llms_hc_vec() && !llms_alt_off("hcv") && (n_embd % 4u) == 0 && args.nb_block0 == sizeof(float) &&
            args.nb_res0 == sizeof(float) && args.nb0 == sizeof(float) && (!args.has_add || args.nb_add0 == sizeof(float))) {   /* llms HC_VEC */
            static id<MTLComputePipelineState> llms_ev; if (!llms_ev) llms_ev = ds4_gpu_get_pipeline("kernel_llms_hc_expand4_v4");
            if (llms_ev) { expand_pipeline = llms_ev; n_elem /= 4u; g_llms_hcv_calls[1]++; }
            if (llms_ev && llms_hc_bf16() && !llms_alt_off("hcb") && args.nb1 == (uint64_t)n_embd * sizeof(float) && args.nb2 == 4u * args.nb1) {   /* llms HC_BF16: contiguous output only */
                static id<MTLComputePipelineState> llms_eb; if (!llms_eb && llms_hc_bf16() > 0) llms_eb = ds4_gpu_get_pipeline("kernel_llms_hc_expand4_v4b");
                if (llms_hc_bf16() < 0 || llms_eb) { if (llms_hc_bf16() > 0) expand_pipeline = llms_eb; llms_hcb_e = true; }
            }
        }
        if (!expand_pipeline) return 0;
        const NSUInteger nth = MIN((NSUInteger)256, MAX((NSUInteger)1, (NSUInteger)n_elem));
        const NSUInteger n_tg = ((NSUInteger)n_elem + nth - 1u) / nth;
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;

        id<MTLComputeCommandEncoder> enc = ds4_gpu_compute_encoder(cb);
        [enc setComputePipelineState:expand_pipeline];
        [enc setBytes:&args length:sizeof(args) atIndex:0];
        [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:1];
        [enc setBuffer:resbuf offset:ds4_gpu_tensor_offset(residual_hc) atIndex:2];
        [enc setBuffer:postbuf offset:ds4_gpu_tensor_offset(post) atIndex:3];
        [enc setBuffer:combbuf offset:ds4_gpu_tensor_offset(comb) atIndex:4];
        [enc setBuffer:blockbuf offset:ds4_gpu_tensor_offset(block_out) atIndex:5];
        [enc setBuffer:outbuf offset:ds4_gpu_tensor_offset(out_hc) atIndex:6];
        [llms_bar(enc) dispatchThreadgroups:MTLSizeMake(n_tg, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(nth, 1, 1)];
        ds4_gpu_end_compute_encoder(cb, enc);
        if (llms_hcb_e) llms_hcb_mark(outbuf, (NSUInteger)ds4_gpu_tensor_offset(out_hc), (NSUInteger)args.nb2 * (NSUInteger)args.n_tokens);   /* llms HC_BF16 */

        if (!ds4_gpu_finish_command_buffer(cb, owned, "HC expand")) return 0;
    }

    return 1;
}

