    [enc setBuffer:ds4_gpu_tensor_buffer(out)
            offset:ds4_gpu_tensor_offset(out) atIndex:2];
    [llms_bar(enc) dispatchThreads:MTLSizeMake(9216u, output_rows, 1)
         threadsPerThreadgroup:MTLSizeMake(256u, 1, 1)];
