static id<MTLBuffer> g_llms_v41_rows_ring; static unsigned g_llms_v41_rows_ri;   /* llms ROWS128: 56-byte row records past setBytes' 4 KB (> 73 rows) */
static void llms_v41_rows_bind(id<MTLComputeCommandEncoder> enc, const llms_v41_row *rows, uint32_t n, NSUInteger index) {
    const NSUInteger bytes = (NSUInteger)sizeof(llms_v41_row) * n;
    if (bytes <= 4096u) { [enc setBytes:rows length:bytes atIndex:index]; return; }
    enum { LLMS_V41R_SLOT = 8192u, LLMS_V41R_NSLOT = 1024u };
    if (!g_llms_v41_rows_ring) g_llms_v41_rows_ring = [g_device newBufferWithLength:(NSUInteger)LLMS_V41R_SLOT * LLMS_V41R_NSLOT options:MTLResourceStorageModeShared];
    const NSUInteger off = (NSUInteger)(g_llms_v41_rows_ri++ % LLMS_V41R_NSLOT) * LLMS_V41R_SLOT;
    memcpy((uint8_t *)[g_llms_v41_rows_ring contents] + off, rows, bytes);
    [enc setBuffer:g_llms_v41_rows_ring offset:off atIndex:index];
}
