    if (!ds4_gpu_ensure_scratch_buffer(&part, &pcap, (NSUInteger)S * 32u * (NSUInteger)N * sizeof(float), "llms_hcfuse_part") ||
        !ds4_gpu_ensure_scratch_buffer(&sq, &scap, (NSUInteger)S * 32u * sizeof(float), "llms_hcfuse_sq")) return 0;
