                ag_v = e && (!strcmp(e, "2") || !strcmp(e, "canary2")) ? 2 : 1;   /* llms ATTN_GEMM v2 */
                if (ag && !(src && llms_srckey(src, ag_v == 2 ? "llms18" : "llms17") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_ATTN_GEMM ignored: DS4_METAL_DSV4_MISC_SOURCE does not name an *%s* source\n", ag_v == 2 ? "llms18" : "llms17"), LLMS_G_NAME); ag = 0; }
                if (ag) { ag_g = ds4_gpu_get_pipeline(ag_v == 2 ? "kernel_llms_agemm2_gather" : "kernel_llms_agemm_gather"); ag_q = ds4_gpu_get_pipeline("kernel_llms_agemm_qk");
                          ag_s = ds4_gpu_get_pipeline(ag_v == 2 ? "kernel_llms_agemm2_softmax" : "kernel_llms_agemm_softmax"); ag_p = ds4_gpu_get_pipeline(ag_v == 2 ? "kernel_llms_agemm2_pv" : "kernel_llms_agemm_pv");
                          if (!ag_g || !ag_q || !ag_s || !ag_p) { fprintf(stderr, "llms attn gemm: kernels missing\n"); ag = 0; }
                          else if (ag_v == 2) fprintf(stderr, ag < 0 ? "llms: attn gemm v2 -- CANARY: every row's newest raw key masked\n" : "llms: attn gemm v2 (float P; P(float) . V(half) on simdgroup matrices)\n");
                          else fprintf(stderr, ag < 0 ? "llms: attn gemm -- CANARY: the last 8 top-k slots of every row masked\n" : "llms: attn gemm (gather + Q.K^T + softmax + P.V on simdgroup matrices)\n"); }
