                [llms_bar(enc) dispatchThreadgroups:MTLSizeMake((NSUInteger)n * n_head, 1, 1) threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
                [enc memoryBarrierWithScope:MTLBarrierScopeBuffers];
