            if (at == -2) { const char *e = getenv("LLMS_DS4_ATTN_T"), *src = getenv("DS4_METAL_DSV4_MISC_SOURCE"); at = !e || !*e || *e == '0' ? 0 : !strcmp(e, "canary") ? -1 : 1;
                            if (at && !(src && llms_srckey(src, "llms14") != NULL)) { llms_strict_after(fprintf(stderr, "llms: LLMS_DS4_ATTN_T ignored: DS4_METAL_DSV4_MISC_SOURCE does not name an *llms14* source\n"), LLMS_G_NAME); at = 0; }
                            if (at) { at_pl = ds4_gpu_get_pipeline("kernel_llms_v41_rows_attn_split_t"); if (!at_pl) { fprintf(stderr, "llms: attn t pipeline missing\n"); at = 0; }
                                      else fprintf(stderr, at < 0 ? "llms: attn t -- CANARY: 8 fewer top-k rows attended\n" : "llms: attn t (one key row per 4-lane group, softmax per stage of 8 rows)\n"); } }
