        ds4_gpu_end_compute_encoder(cb, enc);
        if (!ds4_gpu_finish_command_buffer(cb, owned, "llms v41 rows attention")) return 0;
    }
    return 1;
}


#import <IOSurface/IOSurface.h>
#import <objc/runtime.h>
#import <objc/message.h>
#include <dlfcn.h>

void ds4_gpu_llms_cache_counts(uint64_t *hits, uint64_t *misses) { if (hits) *hits = g_stream_expert_cache_hits; if (misses) *misses = g_stream_expert_cache_misses; }


int ds4_gpu_llms_step_cov(double *v, int n) {
    static uint64_t prev[32]; uint64_t cur[32]; int k = 0;
    cur[k++] = g_stream_expert_cache_misses; cur[k++] = g_stream_expert_cache_hits; cur[k++] = g_stream_expert_cache_read_bytes;
    for (int r = 1; r < 18; r++) cur[k++] = g_llms_run_hist[r];
    cur[k++] = g_llms_dd2_singles; cur[k++] = g_llms_dd2_doubles; cur[k++] = g_llms_dd4_quads;
    for (int i = 0; i < k && i < n; i++) { v[i] = (double)(cur[i] - prev[i]); prev[i] = cur[i]; }
    return k;
}

void ds4_gpu_llms_conc_skip(int on) { g_llms_conc_skip = on ? 1 : 0; }   /* llms CONC: drop the barrier before the next op's first dispatch */
uint64_t ds4_gpu_llms_conc_count(void) { return g_llms_conc_bars + g_llms_conc_skips; }   /* llms CONC_SKIP */




int ds4_gpu_llms_add_model_views(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    for (uint32_t i = 0; i < g_model_view_count; i++) if (g_model_views[i].model_map == model_map) return 1;
    uint64_t mapped = 0;
    @autoreleasepool {
        const int ok = ds4_gpu_add_model_view_range(model_map, model_size, map_offset, map_size, max_tensor_bytes, false, &mapped);
        if (ok) fprintf(stderr, "llms dsp41: %.2f GiB of the support model wrapped as Metal views (%u views in all)\n", (double)mapped / 1073741824.0, g_model_view_count);
        return ok;
    }
}
/* llms DSP41_COPY (apply_dsp41_copy.py): the range [map_offset, map_offset + map_size) of a mapping copied into one Metal-allocated buffer,
   registered as that mapping's model view (ds4_gpu_wrap_model_range then resolves the map's offsets into it) */
int ds4_gpu_llms_add_model_copy(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, const void **host_out) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    for (uint32_t i = 0; i < g_model_view_count; i++) if (g_model_views[i].model_map == model_map) { if (host_out) *host_out = [g_model_views[i].buffer contents]; return 1; }
    if (g_model_view_count == DS4_METAL_MAX_MODEL_VIEWS || map_offset > model_size || map_size > model_size - map_offset) return 0;
    @autoreleasepool {
        const double t0 = ds4_gpu_now_ms();
        id<MTLBuffer> b = [g_device newBufferWithLength:(NSUInteger)map_size options:MTLResourceStorageModeShared];
        if (!b) { fprintf(stderr, "llms dsp41: a %.2f GiB Metal buffer for the support model failed\n", (double)map_size / 1073741824.0); return 0; }
        b.label = @"llms_dsp41_support";
        memcpy([b contents], (const uint8_t *)model_map + map_offset, (size_t)map_size);
        if (host_out) *host_out = [b contents];
        g_model_views[g_model_view_count].buffer = b;
        g_model_views[g_model_view_count].model_map = model_map;
        g_model_views[g_model_view_count].model_size = model_size;
        g_model_views[g_model_view_count].model_offset = map_offset;
        g_model_views[g_model_view_count].bytes = map_size;
        g_model_view_count++;
        fprintf(stderr, "llms dsp41: %.2f GiB of the support model copied into a Metal buffer in %.0f ms\n", (double)map_size / 1073741824.0, ds4_gpu_now_ms() - t0);
        return 1;
    }
}

void ds4_gpu_llms_router_bias_override(const ds4_gpu_tensor *bias) { g_llms_bias_ovr = bias; }
int ds4_gpu_llms_add_model_view_span(const void *model_map, uint64_t model_size, uint64_t off, uint64_t len, uint64_t max_tensor_bytes) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    uint64_t mapped = 0;
    @autoreleasepool { return ds4_gpu_add_model_view_range(model_map, model_size, off, len, max_tensor_bytes, false, &mapped); }
}
int ds4_gpu_llms_dsp_moe_bank(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *experts,
    const ds4_gpu_tensor *gbank, const ds4_gpu_tensor *ubank, const ds4_gpu_tensor *dbank, const ds4_gpu_tensor *map, ds4_gpu_tensor *selb,
    uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes,
    uint32_t in_dim, uint32_t mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_orig, uint32_t n_bank,
    uint32_t n_used, float clamp, const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !experts || !x || !selected || !weights || !gbank || !ubank || !dbank || !map || !selb ||
        n_bank == 0 || n_used < 2 || n_used > DS4_METAL_MAX_ROUTED_EXPERT_USED) return 0;
    @autoreleasepool {
        id<MTLComputePipelineState> gp = ds4_gpu_routed_mv_pipeline(gate_type), dp = ds4_gpu_routed_mv_pipeline(down_type);
        const uint32_t gnr = ds4_gpu_routed_mv_nr0(gate_type), dnr = ds4_gpu_routed_mv_nr0(down_type);
        if (!gp || !dp || !gnr || !dnr) { fprintf(stderr, "llms dsp41 bank: moe setup failed (types %u / %u)\n", gate_type, down_type); return 0; }
        const ds4_gpu_mul_mv_id_args ga = ds4_gpu_make_mul_mv_id_args(in_dim, mid_dim, n_bank, gate_row_bytes, gate_expert_bytes, 1, n_used, 1, gnr);
        const ds4_gpu_mul_mv_id_args da = ds4_gpu_make_mul_mv_id_args(mid_dim, out_dim, n_bank, down_row_bytes, down_expert_bytes, n_used, n_used, 1, dnr);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLBuffer> xb = ds4_gpu_tensor_buffer(x), gtb = ds4_gpu_tensor_buffer(gate), utb = ds4_gpu_tensor_buffer(up), mb = ds4_gpu_tensor_buffer(mid),
                      eb = ds4_gpu_tensor_buffer(experts), ob = ds4_gpu_tensor_buffer(out), sb = ds4_gpu_tensor_buffer(selected), wb = ds4_gpu_tensor_buffer(weights),
                      gbb = ds4_gpu_tensor_buffer(gbank), ubb = ds4_gpu_tensor_buffer(ubank), dbb = ds4_gpu_tensor_buffer(dbank),
                      mpb = ds4_gpu_tensor_buffer(map), sbb = ds4_gpu_tensor_buffer(selb);
        const NSUInteger xo = ds4_gpu_tensor_offset(x), go = ds4_gpu_tensor_offset(gate), uo = ds4_gpu_tensor_offset(up), mo = ds4_gpu_tensor_offset(mid),
                         eo = ds4_gpu_tensor_offset(experts), oo = ds4_gpu_tensor_offset(out), so = ds4_gpu_tensor_offset(selected), wo = ds4_gpu_tensor_offset(weights),
                         gbo = ds4_gpu_tensor_offset(gbank), ubo = ds4_gpu_tensor_offset(ubank), dbo = ds4_gpu_tensor_offset(dbank),
                         mpo = ds4_gpu_tensor_offset(map), sbo = ds4_gpu_tensor_offset(selb);
        const int ok =
            ds4_gpu_encode_get_rows_i32_token_rows(cb, mpb, mpo, sb, so, NULL, sbb, sbo, n_orig, 1, n_used) &&   /* bank slot = map[original id] */
            ds4_gpu_encode_mul_mv_id(cb, gp, &ga, gbb, gbo, xb, xo, gtb, go, sbb, sbo, ds4_gpu_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_mul_mv_id(cb, gp, &ga, ubb, ubo, xb, xo, utb, uo, sbb, sbo, ds4_gpu_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_moe_swiglu_weight(cb, gtb, go, utb, uo, mb, mo, wb, wo, mid_dim, n_used, clamp, false) &&
            ds4_gpu_encode_mul_mv_id(cb, dp, &da, dbb, dbo, mb, mo, eb, eo, sbb, sbo, ds4_gpu_routed_mv_smem(down_type),
                                     ds4_gpu_routed_mv_nsg(down_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(down_type)) &&
            ds4_gpu_encode_moe_sum_experts(cb, eb, eo, ob, oo, out_dim, n_used, 1);
        if (!ok) { fprintf(stderr, "llms dsp41 bank: moe encode failed\n"); return 0; }
        return ds4_gpu_finish_command_buffer(cb, owned, "llms dsp41 bank moe");
    }
}
int ds4_gpu_llms_dsp_moe(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *experts,
                         const void *model_map, uint64_t model_size, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
                         uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes,
                         uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t in_dim, uint32_t mid_dim, uint32_t out_dim,
                         const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total, uint32_t n_used, float clamp,
                         const ds4_gpu_tensor *x) {
    if (!g_initialized && !ds4_gpu_init()) return 0;
    if (!out || !gate || !up || !mid || !experts || !x || !selected || !weights || n_used < 2 || n_used > DS4_METAL_MAX_ROUTED_EXPERT_USED) return 0;
    @autoreleasepool {
        uint64_t gi = 0, ui = 0, di = 0;
        id<MTLBuffer> gb = ds4_gpu_wrap_model_range(model_map, model_size, gate_offset, (uint64_t)n_total * gate_expert_bytes, &gi);
        id<MTLBuffer> ub = ds4_gpu_wrap_model_range(model_map, model_size, up_offset, (uint64_t)n_total * gate_expert_bytes, &ui);
        id<MTLBuffer> db = ds4_gpu_wrap_model_range(model_map, model_size, down_offset, (uint64_t)n_total * down_expert_bytes, &di);
        id<MTLComputePipelineState> gp = ds4_gpu_routed_mv_pipeline(gate_type), dp = ds4_gpu_routed_mv_pipeline(down_type);
        const uint32_t gnr = ds4_gpu_routed_mv_nr0(gate_type), dnr = ds4_gpu_routed_mv_nr0(down_type);
        if (!gb || !ub || !db || !gp || !dp || !gnr || !dnr) { fprintf(stderr, "llms dsp41: moe setup failed (types %u / %u)\n", gate_type, down_type); return 0; }
        const ds4_gpu_mul_mv_id_args ga = ds4_gpu_make_mul_mv_id_args(in_dim, mid_dim, n_total, gate_row_bytes, gate_expert_bytes, 1, n_used, 1, gnr);
        const ds4_gpu_mul_mv_id_args da = ds4_gpu_make_mul_mv_id_args(mid_dim, out_dim, n_total, down_row_bytes, down_expert_bytes, n_used, n_used, 1, dnr);
        int owned = 0;
        id<MTLCommandBuffer> cb = ds4_gpu_command_buffer(&owned);
        if (!cb) return 0;
        id<MTLBuffer> xb = ds4_gpu_tensor_buffer(x), gtb = ds4_gpu_tensor_buffer(gate), utb = ds4_gpu_tensor_buffer(up), mb = ds4_gpu_tensor_buffer(mid),
                      eb = ds4_gpu_tensor_buffer(experts), ob = ds4_gpu_tensor_buffer(out), sb = ds4_gpu_tensor_buffer(selected), wb = ds4_gpu_tensor_buffer(weights);
        const NSUInteger xo = ds4_gpu_tensor_offset(x), go = ds4_gpu_tensor_offset(gate), uo = ds4_gpu_tensor_offset(up), mo = ds4_gpu_tensor_offset(mid),
                         eo = ds4_gpu_tensor_offset(experts), oo = ds4_gpu_tensor_offset(out), so = ds4_gpu_tensor_offset(selected), wo = ds4_gpu_tensor_offset(weights);
        const int ok =
            ds4_gpu_encode_mul_mv_id(cb, gp, &ga, gb, (NSUInteger)gi, xb, xo, gtb, go, sb, so, ds4_gpu_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_mul_mv_id(cb, gp, &ga, ub, (NSUInteger)ui, xb, xo, utb, uo, sb, so, ds4_gpu_routed_mv_smem(gate_type),
                                     ds4_gpu_routed_mv_nsg(gate_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(gate_type)) &&
            ds4_gpu_encode_moe_swiglu_weight(cb, gtb, go, utb, uo, mb, mo, wb, wo, mid_dim, n_used, clamp, false) &&
            ds4_gpu_encode_mul_mv_id(cb, dp, &da, db, (NSUInteger)di, mb, mo, eb, eo, sb, so, ds4_gpu_routed_mv_smem(down_type),
                                     ds4_gpu_routed_mv_nsg(down_type), ds4_gpu_routed_mv_rows_per_group_is_nr0(down_type)) &&
            ds4_gpu_encode_moe_sum_experts(cb, eb, eo, ob, oo, out_dim, n_used, 1);
        if (!ok) { fprintf(stderr, "llms dsp41: moe encode failed\n"); return 0; }
        return ds4_gpu_finish_command_buffer(cb, owned, "llms dsp41 moe");
    }
}
static uint32_t llms_pc_phase(void) { return __atomic_load_n(&g_llms_tl_phase, __ATOMIC_RELAXED); }   /* llms PIPE_CENSUS */
